  animation: stat-card-enter var(--motion-slow) var(--ease-enter) both;
}
.stat-card-enter:nth-child(1) {
  animation-delay: 0ms;
}
.stat-card-enter:nth-child(2) {
  animation-delay: 60ms;
}
.stat-card-enter:nth-child(3) {
  animation-delay: 120ms;
}
.stat-card-enter:nth-child(4) {
  animation-delay: 180ms;
}

/* Glass card entrance — staggered fade-up for list grids. */
@keyframes glass-card-enter {
  from {
    opacity: 0;
    transform: translateY(0.5rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
