import { getErrorMessage } from "~/utils/errors";

type AIChatTranslate = (key: string, params?: Record<string, unknown>) => string;

export const createAIChatPageActions = (input: {
  readonly input: Ref<string>;
  readonly loading: Readonly<Ref<boolean>>;
  readonly isVoiceListening: Readonly<Ref<boolean>>;
  readonly stopListening: () => void;
  readonly sendMessage: ReturnType<typeof useAI>["sendMessage"];
  readonly scrollToBottom: (force?: boolean) => void;
  readonly focusComposer: () => void;
  readonly shouldStickToBottom: Ref<boolean>;
  readonly saveSpeechConfig: ReturnType<typeof useSpeechModelProfiles>["saveSpeechConfig"];
  readonly toast: ReturnType<typeof useNuxtApp>["$toast"];
  readonly t: AIChatTranslate;
}) => {
  const handlePromptSelection = (prompt: string): void => {
    input.input.value = prompt;
    input.focusComposer();
  };

  const handleSendMessage = async (): Promise<void> => {
    if (!input.input.value.trim() || input.loading.value) return;

    if (input.isVoiceListening.value) {
      input.stopListening();
    }

    input.shouldStickToBottom.value = true;
    const content = input.input.value.trim();
    input.input.value = "";
    await input.sendMessage(content, { source: "chat-page" });
    input.scrollToBottom(true);
  };

  const handleComposerKeydown = async (event: KeyboardEvent): Promise<void> => {
    if (event.key !== "Enter" || event.shiftKey || event.isComposing) {
      return;
    }

    event.preventDefault();
    await handleSendMessage();
  };

  const handleSaveSpeechConfig = async (): Promise<void> => {
    const saveSpeechResult = await input.saveSpeechConfig(
      input.t("aiChatPage.voiceSettings.saveErrorFallback"),
    );
    if (!saveSpeechResult.ok) {
      input.toast.error(
        getErrorMessage(
          saveSpeechResult.error,
          input.t("aiChatPage.voiceSettings.saveErrorFallback"),
        ),
      );
      return;
    }

    if (!saveSpeechResult.saved) {
      return;
    }

    input.toast.success(input.t("aiChatPage.voiceSettings.saveSuccess"));
  };

  return {
    handlePromptSelection,
    handleSendMessage,
    handleComposerKeydown,
    handleSaveSpeechConfig,
  };
};

import type { ChatMessage } from "@bao/shared/types/ai";
import { computed } from "vue";
import {
  buildChatMessageRenderRows,
  createStreamingAssistantMessage,
  resolveLatestAssistantMessageIndex,
} from "~/utils/chat";

type AIChatTranslate = (key: string, params?: Record<string, unknown>) => string;

export const createAIChatPageDerivedState = (input: {
  readonly t: AIChatTranslate;
  readonly messages: Readonly<Ref<readonly ChatMessage[]>>;
  readonly loading: Readonly<Ref<boolean>>;
  readonly streaming: Readonly<Ref<boolean>>;
  readonly streamingContent: Readonly<Ref<string>>;
  readonly voiceErrorMessageKey: Readonly<Ref<string>>;
  readonly buildCurrentContext: ReturnType<typeof useAI>["buildCurrentContext"];
}) => {
  const voiceErrorLabel = computed(() => {
    if (input.voiceErrorMessageKey.value.length === 0) {
      return "";
    }

    return input.t("aiChatCommon.voice.errorLabel", {
      error: input.t(input.voiceErrorMessageKey.value),
    });
  });
  const renderedMessages = computed(() => buildChatMessageRenderRows([...input.messages.value]));
  const renderedMessageSignature = computed(() =>
    renderedMessages.value
      .map(({ message }) =>
        [message.id, message.role, message.timestamp, message.content].join(":"),
      )
      .join("\n"),
  );
  const latestAssistantMessageIndex = computed(() =>
    resolveLatestAssistantMessageIndex([...input.messages.value]),
  );
  const streamingBubble = computed(() =>
    createStreamingAssistantMessage("chatPage", input.streamingContent.value),
  );
  const chatContext = computed(() => input.buildCurrentContext("chat-page"));
  const hasConversation = computed(
    () => renderedMessages.value.length > 0 || input.streaming.value,
  );
  const composerStatusLabel = computed(() =>
    input.loading.value || input.streaming.value
      ? input.t("aiChatPage.composerBusyStatus")
      : input.t("aiChatPage.composerIdleStatus"),
  );
  const contextSummary = useAIChatContextSummary(chatContext, input.t);

  return {
    voiceErrorLabel,
    renderedMessages,
    renderedMessageSignature,
    latestAssistantMessageIndex,
    streamingBubble,
    hasConversation,
    composerStatusLabel,
    contextChips: contextSummary.contextChips,
    contextualPrompts: contextSummary.contextualPrompts,
    currentContextLabel: contextSummary.currentContextLabel,
    focusedEntityLabel: contextSummary.focusedEntityLabel,
  };
};

const CHAT_SCROLL_STICKY_THRESHOLD_PX = 96;

export const useAIChatPageScroll = (input: {
  readonly chatContainer: ReturnType<typeof useTemplateRef<HTMLElement>>;
  readonly composerRef: ReturnType<typeof useTemplateRef<HTMLTextAreaElement>>;
  readonly renderedMessageSignature: Readonly<Ref<string>>;
  readonly loading: Readonly<Ref<boolean>>;
  readonly streaming: Readonly<Ref<boolean>>;
}) => {
  const shouldStickToBottom = ref(true);

  const updateScrollStickiness = (): void => {
    const container = input.chatContainer.value;
    if (!container) {
      return;
    }

    const remainingScrollDistance =
      container.scrollHeight - container.scrollTop - container.clientHeight;
    shouldStickToBottom.value = remainingScrollDistance <= CHAT_SCROLL_STICKY_THRESHOLD_PX;
  };

  const scrollToBottom = (force = false): void => {
    requestAnimationFrame(() => {
      const container = input.chatContainer.value;
      if (!(container && (force || shouldStickToBottom.value))) {
        return;
      }

      container.scrollTop = container.scrollHeight;
      updateScrollStickiness();
    });
  };

  watch(input.renderedMessageSignature, () => {
    if (shouldStickToBottom.value || input.loading.value || input.streaming.value) {
      scrollToBottom(true);
    }
  });

  watch(input.streaming, (isStreaming) => {
    if (!isStreaming) {
      return;
    }

    shouldStickToBottom.value = true;
    scrollToBottom(true);
  });

  return {
    handleChatScroll: updateScrollStickiness,
    focusComposer: () => requestAnimationFrame(() => input.composerRef.value?.focus()),
    scrollToBottom,
    shouldStickToBottom,
  };
};

import {
  AI_CHAT_ENTITY_ROUTE_PATHS,
  AI_CHAT_PAGE_PATH,
  AI_CHAT_ROUTE_QUERY_KEYS,
  inferAIChatDomainFromRoutePath,
} from "@bao/shared/constants/ai-chat";
import type {
  AIChatContext,
  AIChatContextEntity,
  AIChatContextEntityType,
  AIChatContextSource,
} from "@bao/shared/types/ai";
import type { GameStudio, InterviewSession } from "@bao/shared/types/interview";
import type { Job } from "@bao/shared/types/jobs";
import type { PortfolioData } from "@bao/shared/types/portfolio";
import type { ResumeData } from "@bao/shared/types/resume";
import type { LocationQueryValue } from "vue-router";

interface EntityContextInput {
  path: string;
  routeParams: Record<string, string>;
  routeQuery: Record<string, string>;
  jobs: readonly Job[];
  resumes: readonly ResumeData[];
  studio: GameStudio | null;
  interviewSessions: readonly InterviewSession[];
}

interface ContextBuilderInput {
  route: ReturnType<typeof useRoute>;
  jobs: ReturnType<typeof useState<Job[]>>;
  resumes: ReturnType<typeof useState<ResumeData[]>>;
  currentStudio: ReturnType<typeof useState<GameStudio | null>>;
  interviewSessions: ReturnType<typeof useState<InterviewSession[]>>;
  portfolioData: ReturnType<typeof useState<PortfolioData | null>>;
}

function resolveAIChatSource(path: string, source?: AIChatContextSource): AIChatContextSource {
  if (source) {
    return source;
  }
  return path.startsWith(AI_CHAT_PAGE_PATH) ? "chat-page" : "floating-widget";
}

function normalizeRouteParams(
  params: Record<string, string | string[] | null | undefined>,
): Record<string, string> {
  const normalized: Record<string, string> = {};
  for (const [key, value] of Object.entries(params)) {
    if (Array.isArray(value)) {
      const [firstValue] = value;
      if (typeof firstValue === "string" && firstValue.length > 0) {
        normalized[key] = firstValue;
      }
      continue;
    }
    if (typeof value === "string" && value.length > 0) {
      normalized[key] = value;
    }
  }
  return normalized;
}

function normalizeRouteQuery(
  query: Record<string, LocationQueryValue | LocationQueryValue[]>,
): Record<string, string> {
  const normalized: Record<string, string> = {};
  for (const [key, value] of Object.entries(query)) {
    if (Array.isArray(value)) {
      const firstStringValue = value.find(
        (entry): entry is string => typeof entry === "string" && entry.length > 0,
      );
      if (firstStringValue) {
        normalized[key] = firstStringValue;
      }
      continue;
    }
    if (typeof value === "string" && value.length > 0) {
      normalized[key] = value;
    }
  }
  return normalized;
}

function toEntity(type: AIChatContextEntityType, id: string, label?: string): AIChatContextEntity {
  if (!label) {
    return { type, id };
  }
  return { type, id, label };
}

function buildInterviewSessionLabel(session: InterviewSession): string {
  const role =
    session.role?.trim() ||
    session.config.targetJob?.title?.trim() ||
    session.config.roleType.trim() ||
    "";
  const studio =
    session.studioName?.trim() ||
    session.config.targetJob?.company?.trim() ||
    session.studioId.trim() ||
    "";

  if (role.length > 0 && studio.length > 0) {
    return `${role} at ${studio}`;
  }

  return role || studio;
}

function resolveJobContextEntity(input: EntityContextInput): AIChatContextEntity | undefined {
  const routeId = input.routeParams[AI_CHAT_ROUTE_QUERY_KEYS.id];
  if (!(input.path.startsWith(`${AI_CHAT_ENTITY_ROUTE_PATHS.jobs}/`) && routeId)) {
    return;
  }
  const selectedJob = input.jobs.find((job) => job.id === routeId);
  const selectedJobLabel = selectedJob ? `${selectedJob.title} at ${selectedJob.company}` : "";
  return toEntity("job", routeId, selectedJobLabel);
}

function resolveInterviewContextEntity(input: EntityContextInput): AIChatContextEntity | undefined {
  const queryJobId = input.routeQuery[AI_CHAT_ROUTE_QUERY_KEYS.jobId];
  if (!(input.path.startsWith(AI_CHAT_ENTITY_ROUTE_PATHS.interview) && queryJobId)) {
    return;
  }
  const selectedJob = input.jobs.find((job) => job.id === queryJobId);
  const selectedJobLabel = selectedJob ? `${selectedJob.title} at ${selectedJob.company}` : "";
  return toEntity("job", queryJobId, selectedJobLabel);
}

function resolveResumeContextEntity(input: EntityContextInput): AIChatContextEntity | undefined {
  if (!input.path.startsWith(AI_CHAT_ENTITY_ROUTE_PATHS.resume)) {
    return;
  }
  const routeId = input.routeParams[AI_CHAT_ROUTE_QUERY_KEYS.id];
  const queryResumeId = input.routeQuery[AI_CHAT_ROUTE_QUERY_KEYS.resumeId];
  const resolvedResumeId = routeId || queryResumeId;
  if (!resolvedResumeId) {
    return;
  }
  const selectedResume = input.resumes.find((resume) => resume.id === resolvedResumeId);
  return toEntity("resume", resolvedResumeId, selectedResume?.name ?? "");
}

function resolveStudioPathContextEntity(
  input: EntityContextInput,
): AIChatContextEntity | undefined {
  const routeId = input.routeParams[AI_CHAT_ROUTE_QUERY_KEYS.id];
  if (!(input.path.startsWith(`${AI_CHAT_ENTITY_ROUTE_PATHS.studios}/`) && routeId)) {
    return;
  }
  return toEntity("studio", routeId, input.studio?.name ?? "");
}

function resolveStudioQueryContextEntity(
  input: EntityContextInput,
): AIChatContextEntity | undefined {
  const queryStudioId = input.routeQuery[AI_CHAT_ROUTE_QUERY_KEYS.studioId];
  if (!queryStudioId) {
    return;
  }
  return toEntity("studio", queryStudioId, input.studio?.name ?? "");
}

function resolveSessionContextEntity(input: EntityContextInput): AIChatContextEntity | undefined {
  const interviewSessionId = input.routeQuery[AI_CHAT_ROUTE_QUERY_KEYS.id];
  if (input.path.startsWith(AI_CHAT_ENTITY_ROUTE_PATHS.interviewSession) && interviewSessionId) {
    const interviewSession = input.interviewSessions.find(
      (session) => session.id === interviewSessionId,
    );
    return toEntity(
      "interview_session",
      interviewSessionId,
      interviewSession ? buildInterviewSessionLabel(interviewSession) : undefined,
    );
  }

  const routeId = input.routeParams[AI_CHAT_ROUTE_QUERY_KEYS.id];
  if (input.path.startsWith(`${AI_CHAT_ENTITY_ROUTE_PATHS.automationRuns}/`) && routeId) {
    return toEntity("automation_run", routeId);
  }
}

function resolveEntityContext(input: EntityContextInput): AIChatContextEntity | undefined {
  const resolvers = [
    resolveJobContextEntity,
    resolveInterviewContextEntity,
    resolveResumeContextEntity,
    resolveStudioPathContextEntity,
    resolveStudioQueryContextEntity,
    resolveSessionContextEntity,
  ] as const;

  for (const resolver of resolvers) {
    const entity = resolver(input);
    if (entity) {
      return entity;
    }
  }
}

export function createContextBuilder(input: ContextBuilderInput) {
  return (source?: AIChatContextSource): AIChatContext => {
    const routeParams = normalizeRouteParams(input.route.params);
    const routeQuery = normalizeRouteQuery(input.route.query);
    const routeName = typeof input.route.name === "string" ? input.route.name : "";
    const resolvedSource = resolveAIChatSource(input.route.path, source);
    const entityContext = resolveEntityContext({
      path: input.route.path,
      routeParams,
      routeQuery,
      jobs: input.jobs.value,
      resumes: input.resumes.value,
      studio: input.currentStudio.value,
      interviewSessions: input.interviewSessions.value,
    });

    const context: AIChatContext = {
      source: resolvedSource,
      domain: inferAIChatDomainFromRoutePath(input.route.path),
      route: {
        path: input.route.path,
        params: routeParams,
        query: routeQuery,
        ...(routeName ? { name: routeName } : {}),
      },
      state: {
        hasResumes: input.resumes.value.length > 0,
        resumeCount: input.resumes.value.length,
        hasJobs: input.jobs.value.length > 0,
        jobCount: input.jobs.value.length,
        hasStudios: input.currentStudio.value !== null,
        studioCount: input.currentStudio.value ? 1 : 0,
        hasInterviewSessions: input.interviewSessions.value.length > 0,
        interviewSessionCount: input.interviewSessions.value.length,
        hasPortfolioProjects: (input.portfolioData.value?.projects.length ?? 0) > 0,
        portfolioProjectCount: input.portfolioData.value?.projects.length ?? 0,
      },
    };

    return entityContext ? { ...context, entity: entityContext } : context;
  };
}

import { AI_ROUTING_PURPOSE_IDS, type AIProviderType, type AIRouting } from "@bao/shared/types/ai";
import type { Ref } from "vue";
import { settlePromise } from "~/composables/async-flow";
import type { ProviderConnectivityResult } from "~/types/ai-dashboard";
import { getErrorMessage } from "~/utils/errors";

type ApiClient = ReturnType<typeof useApi>;
type TestApiKeyInput = NonNullable<Parameters<ApiClient["settings"]["test-api-key"]["post"]>[0]>;
type Translate = (key: string, params?: Record<string, unknown>) => string;
type ProviderTestMessageContext = {
  providerId: AIProviderType;
  valid: boolean;
  t: Translate;
};

const PROVIDER_TEST_MESSAGES = {
  local: {
    false: "aiDashboard.tests.localFailure",
    true: "aiDashboard.tests.localSuccess",
  },
  remote: {
    false: "aiDashboard.tests.connectionFailure",
    true: "aiDashboard.tests.connectionSuccess",
  },
} as const;

export function createDefaultRouting(provider: AIProviderType) {
  const [
    chat,
    interviewQuestions,
    interviewFeedback,
    resume,
    coverLetter,
    emailResponse,
    jobMatch,
    scrapeEnrichment,
    automationFieldMapping,
  ] = AI_ROUTING_PURPOSE_IDS;

  return {
    [chat]: { provider },
    [interviewQuestions]: { provider },
    [interviewFeedback]: { provider },
    [resume]: { provider },
    [coverLetter]: { provider },
    [emailResponse]: { provider },
    [jobMatch]: { provider },
    [scrapeEnrichment]: { provider },
    [automationFieldMapping]: { provider },
  } satisfies AIRouting;
}

function resolveProviderCredential(
  settings: ReturnType<typeof useSettings>["settings"],
  providerId: TestApiKeyInput["provider"],
): string {
  const currentSettings = settings.value;
  if (!currentSettings) return "";
  const credentialByProvider = {
    claude: currentSettings.claudeApiKey ?? "",
    gemini: currentSettings.geminiApiKey ?? "",
    huggingface: currentSettings.huggingfaceToken ?? "",
    openai: currentSettings.openaiApiKey ?? "",
  } as const;
  return credentialByProvider[providerId as keyof typeof credentialByProvider] ?? "";
}

function resolveTestMessage({ providerId, valid, t }: ProviderTestMessageContext): string {
  const messageGroup =
    providerId === "local" ? PROVIDER_TEST_MESSAGES.local : PROVIDER_TEST_MESSAGES.remote;
  return t(messageGroup[valid ? "true" : "false"]);
}

async function testProviderConnectivity(input: {
  providerId: AIProviderType;
  settings: ReturnType<typeof useSettings>["settings"];
  localProviderState: ReturnType<typeof useSettings>["localProviderState"];
  testApiKey: ReturnType<typeof useSettings>["testApiKey"];
  t: Translate;
}): Promise<ProviderConnectivityResult> {
  if (input.providerId === "local") {
    const result = await input.testApiKey(
      "local",
      input.localProviderState.value.endpoint,
      input.localProviderState.value.configuredModel || undefined,
    );
    return {
      valid: result.valid,
      message:
        result.message ||
        resolveTestMessage({ providerId: "local", valid: result.valid, t: input.t }),
    };
  }

  const providerCredential = resolveProviderCredential(input.settings, input.providerId);
  if (!providerCredential.trim()) {
    return {
      valid: false,
      message: input.t("aiDashboard.tests.missingCredential"),
    };
  }

  const result = await input.testApiKey(input.providerId, providerCredential);
  return {
    valid: result.valid,
    message:
      result.message ||
      resolveTestMessage({ providerId: input.providerId, valid: result.valid, t: input.t }),
  };
}

function createDashboardRefreshAction(input: {
  refreshDashboardBootstrap: () => Promise<unknown>;
  t: Translate;
  toast: ReturnType<typeof useNuxtApp>["$toast"];
}) {
  return async function fetchProviderStats() {
    const refreshResult = await settlePromise(
      input.refreshDashboardBootstrap(),
      input.t("aiDashboard.toasts.loadFailed"),
    );
    if (!refreshResult.ok) {
      input.toast.error(
        getErrorMessage(refreshResult.error, input.t("aiDashboard.toasts.loadFailed")),
      );
    }
  };
}

function createProviderTestAction(input: {
  localProviderState: ReturnType<typeof useSettings>["localProviderState"];
  settings: ReturnType<typeof useSettings>["settings"];
  t: Translate;
  testApiKey: ReturnType<typeof useSettings>["testApiKey"];
  testResults: Record<AIProviderType, ProviderConnectivityResult | null>;
  testingProvider: Ref<AIProviderType | null>;
}) {
  return async function handleTestProvider(providerId: AIProviderType) {
    input.testingProvider.value = providerId;
    input.testResults[providerId] = null;

    const providerTestResult = await settlePromise(
      testProviderConnectivity({
        providerId,
        settings: input.settings,
        localProviderState: input.localProviderState,
        testApiKey: input.testApiKey,
        t: input.t,
      }),
      input.t("aiDashboard.tests.connectionFailure"),
    );
    input.testingProvider.value = null;

    if (!providerTestResult.ok) {
      input.testResults[providerId] = {
        valid: false,
        message: getErrorMessage(
          providerTestResult.error,
          input.t("aiDashboard.tests.connectionFailure"),
        ),
      };
      return;
    }

    input.testResults[providerId] = providerTestResult.value;
  };
}

function createDashboardPreferenceAction(
  input: {
    api: ReturnType<typeof useApi>;
    selectedModel: Ref<string>;
    selectedProvider: Ref<AIProviderType>;
    settings: ReturnType<typeof useSettings>["settings"];
    t: Translate;
    toast: ReturnType<typeof useNuxtApp>["$toast"];
  },
  fetchProviderStats: () => Promise<void>,
) {
  return async function handleSetPreference() {
    if (!(input.selectedProvider.value && input.selectedModel.value)) {
      return;
    }

    const preferenceResult = await settlePromise(
      (async () => {
        const { error } = await input.api.settings.put({
          aiRouting: {
            ...(input.settings.value?.aiRouting ??
              createDefaultRouting(input.selectedProvider.value)),
            chat: {
              provider: input.selectedProvider.value,
              ...(input.selectedModel.value ? { model: input.selectedModel.value } : {}),
            },
          },
          preferredProvider: input.selectedProvider.value,
          preferredModel: input.selectedModel.value || undefined,
        });
        if (error) {
          throw new Error(input.t("aiDashboard.errors.preferenceSaveFailed"));
        }
      })(),
      input.t("aiDashboard.toasts.preferenceSaveFailed"),
    );
    if (!preferenceResult.ok) {
      input.toast.error(
        getErrorMessage(preferenceResult.error, input.t("aiDashboard.toasts.preferenceSaveFailed")),
      );
      return;
    }

    input.toast.success(input.t("aiDashboard.toasts.preferenceSaved"));
    await fetchProviderStats();
  };
}

export function createAIDashboardActions(input: {
  api: ReturnType<typeof useApi>;
  localProviderState: ReturnType<typeof useSettings>["localProviderState"];
  refreshDashboardBootstrap: () => Promise<unknown>;
  selectedModel: Ref<string>;
  selectedProvider: Ref<AIProviderType>;
  settings: ReturnType<typeof useSettings>["settings"];
  t: Translate;
  testApiKey: ReturnType<typeof useSettings>["testApiKey"];
  testResults: Record<AIProviderType, ProviderConnectivityResult | null>;
  testingProvider: Ref<AIProviderType | null>;
  toast: ReturnType<typeof useNuxtApp>["$toast"];
}) {
  const fetchProviderStats = createDashboardRefreshAction(input);
  const handleTestProvider = createProviderTestAction(input);
  const handleSetPreference = createDashboardPreferenceAction(input, fetchProviderStats);

  return {
    fetchProviderStats,
    handleSetPreference,
    handleTestProvider,
  };
}

import { AI_PROVIDER_DEFAULT } from "@bao/shared/constants/ai-provider";
import type { AIProviderType } from "@bao/shared/types/ai";
import { useI18n } from "vue-i18n";
import { PERCENT_MAX } from "~/constants/numeric-ui";
import type {
  AiDashboardStats,
  ProviderConfig,
  ProviderConnectivityResult,
} from "~/types/ai-dashboard";
import {
  buildFallbackProviderRows,
  normalizeProviderRows,
  resolveProviderModelSelection,
} from "~/utils/ai-control-plane";

export type DashboardBootstrap = {
  activeModel: string;
  activeProvider: AIProviderType;
  normalizedStats: AiDashboardStats;
  resolvedProviders: ProviderConfig[];
};

const asNumber = (value: unknown): number | undefined =>
  typeof value === "number" && Number.isFinite(value) ? value : undefined;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function readNumberField(payload: Record<string, unknown>, key: string): number | undefined {
  return asNumber(payload[key]);
}

function normalizeDashboardStats(
  usagePayload: unknown,
  activeProvider: AIProviderType,
): AiDashboardStats {
  if (!isRecord(usagePayload)) {
    return {
      totalRequests: 0,
      successRate: 0,
      averageResponseTimeSeconds: 0,
      activeProvider,
      sessions: 0,
    };
  }

  const totalMessages = readNumberField(usagePayload, "totalMessages") ?? 0;
  const userMessages = readNumberField(usagePayload, "userMessages") ?? 0;
  const assistantMessages = readNumberField(usagePayload, "assistantMessages") ?? 0;
  const sessions = readNumberField(usagePayload, "sessions") ?? 0;
  let successRate = 0;
  if (userMessages > 0) {
    successRate = Math.round((assistantMessages / userMessages) * PERCENT_MAX);
  } else if (totalMessages > 0) {
    successRate = PERCENT_MAX;
  }

  return {
    totalRequests: totalMessages,
    successRate,
    averageResponseTimeSeconds: 0,
    activeProvider,
    sessions,
  };
}

function useAIDashboardDependencies() {
  const { t } = useI18n();
  const { settings, fetchSettings, testApiKey, chatRoutingPreference, localProviderState } =
    useSettings();
  const { $toast } = useNuxtApp();
  const api = useApi();

  return {
    api,
    chatRoutingPreference,
    fetchSettings,
    localProviderState,
    settings,
    t,
    testApiKey,
    toast: $toast,
  };
}

function useDashboardBootstrap(input: {
  api: ReturnType<typeof useApi>;
  fetchSettings: ReturnType<typeof useSettings>["fetchSettings"];
  settings: ReturnType<typeof useSettings>["settings"];
  chatRoutingPreference: ReturnType<typeof useSettings>["chatRoutingPreference"];
  t: ReturnType<typeof useI18n>["t"];
  resolveDefaultModel: (providerId: AIProviderType) => string;
}) {
  async function loadDashboardState(): Promise<DashboardBootstrap> {
    if (!input.settings.value) {
      await input.fetchSettings();
    }
    const [usageResult, modelsResult] = await Promise.all([
      input.api.ai.usage.get(),
      input.api.ai.models.get(),
    ]);

    if (usageResult.error) {
      throw new Error(input.t("aiDashboard.errors.usageLoadFailed"));
    }
    if (modelsResult.error) {
      throw new Error(input.t("aiDashboard.errors.modelsLoadFailed"));
    }

    const normalizedProviders = normalizeProviderRows(modelsResult.data, input.settings.value);
    const resolvedProviders =
      normalizedProviders.length > 0
        ? normalizedProviders
        : buildFallbackProviderRows(input.settings.value);
    const activeProvider = resolvedProviders.some(
      (provider) => provider.id === input.chatRoutingPreference.value.provider,
    )
      ? input.chatRoutingPreference.value.provider
      : (resolvedProviders[0]?.id ?? AI_PROVIDER_DEFAULT);
    const activeProviderModels =
      resolvedProviders.find((provider) => provider.id === activeProvider)?.models ?? [];

    return {
      resolvedProviders,
      activeProvider,
      activeModel:
        resolveProviderModelSelection(activeProvider, input.settings.value, activeProviderModels) ||
        input.resolveDefaultModel(activeProvider),
      normalizedStats: normalizeDashboardStats(usageResult.data, activeProvider),
    };
  }

  return useAsyncData("ai-dashboard-bootstrap", loadDashboardState, {
    server: true,
    lazy: false,
  });
}

export function createAIDashboardRuntime() {
  return {
    dependencies: useAIDashboardDependencies(),
    testingProvider: ref<AIProviderType | null>(null),
    testResults: reactive<Record<AIProviderType, ProviderConnectivityResult | null>>({
      local: null,
      gemini: null,
      openai: null,
      claude: null,
      huggingface: null,
    }),
  };
}

export function createAIDashboardBootstrapState(
  runtime: ReturnType<typeof createAIDashboardRuntime>,
  resolveDefaultModel: (providerId: AIProviderType) => string,
) {
  const {
    data: dashboardBootstrap,
    error: dashboardBootstrapError,
    refresh: refreshDashboardBootstrap,
    status: dashboardBootstrapStatus,
  } = useDashboardBootstrap({
    api: runtime.dependencies.api,
    fetchSettings: runtime.dependencies.fetchSettings,
    settings: runtime.dependencies.settings,
    chatRoutingPreference: runtime.dependencies.chatRoutingPreference,
    t: runtime.dependencies.t,
    resolveDefaultModel,
  });

  return {
    dashboardBootstrap,
    dashboardBootstrapError,
    dashboardBootstrapStatus,
    refreshDashboardBootstrap,
  };
}

import type { AIProviderType } from "@bao/shared/types/ai";
import type { ComputedRef, Ref } from "vue";
import type {
  AiDashboardStats,
  ProviderConfig,
  ProviderConnectivityResult,
  ProviderHealth,
} from "~/types/ai-dashboard";
import {
  isProviderConfigured as isConfiguredProviderFromSettings,
  resolveProviderMetadata,
} from "~/utils/ai-control-plane";

type Translate = (key: string, params?: Record<string, unknown>) => string;

const HEALTH_LABEL_KEY_BY_VALUE: Record<ProviderHealth, string> = {
  healthy: "aiDashboard.health.healthy",
  degraded: "aiDashboard.health.degraded",
  down: "aiDashboard.health.down",
  unconfigured: "aiDashboard.health.unconfigured",
};

const HEALTH_BADGE_CLASS_BY_VALUE: Record<ProviderHealth, string> = {
  healthy: "badge-success",
  degraded: "badge-warning",
  down: "badge-error",
  unconfigured: "badge-ghost",
};

export function createDashboardProviderPresentation(
  t: Translate,
  settings: ReturnType<typeof useSettings>["settings"],
) {
  function isProviderConfigured(providerId: AIProviderType): boolean {
    return isConfiguredProviderFromSettings(settings.value, providerId);
  }

  function providerAvailabilityLabel(available: boolean): string {
    return available
      ? t("aiDashboard.availability.available")
      : t("aiDashboard.availability.unavailable");
  }

  function providerHealthLabel(health: ProviderHealth): string {
    return t(HEALTH_LABEL_KEY_BY_VALUE[health]);
  }

  function providerHealthBadgeClass(health: ProviderHealth): string {
    return HEALTH_BADGE_CLASS_BY_VALUE[health];
  }

  function providerLabel(providerId: AIProviderType): string {
    const catalogEntry = resolveProviderMetadata(providerId);
    if (!catalogEntry) {
      return providerId;
    }
    return t(catalogEntry.nameKey);
  }

  function providerDescription(providerId: AIProviderType): string {
    const catalogEntry = resolveProviderMetadata(providerId);
    if (!catalogEntry) {
      return "";
    }
    return t(catalogEntry.descriptionKey);
  }

  function providerSelectOptionLabel(provider: ProviderConfig): string {
    const providerName = providerLabel(provider.id);
    if (isProviderConfigured(provider.id)) {
      return providerName;
    }
    return t("aiDashboard.preference.providerNotConfiguredOption", { provider: providerName });
  }

  return {
    isProviderConfigured,
    providerAvailabilityLabel,
    providerDescription,
    providerHealthBadgeClass,
    providerHealthLabel,
    providerLabel,
    providerSelectOptionLabel,
  };
}

export function createDashboardStatsPresentation(
  providerStats: ComputedRef<AiDashboardStats | null>,
  t: Translate,
  providerLabel: (providerId: AIProviderType) => string,
) {
  const activeProviderLabel = computed(() =>
    providerStats.value ? providerLabel(providerStats.value.activeProvider) : "",
  );

  const statsItems = computed(() =>
    providerStats.value
      ? [
          {
            titleKey: "aiDashboard.stats.totalRequestsTitle",
            value: providerStats.value.totalRequests,
            valueClass: "text-primary",
            descKey: "aiDashboard.stats.totalRequestsDesc",
          },
          {
            titleKey: "aiDashboard.stats.successRateTitle",
            value: `${providerStats.value.successRate}%`,
            valueClass: "text-success",
            descKey: "aiDashboard.stats.successRateDesc",
          },
          {
            titleKey: "aiDashboard.stats.averageResponseTitle",
            value: t("aiDashboard.stats.averageResponseValue", {
              seconds: providerStats.value.averageResponseTimeSeconds,
            }),
            valueClass: "text-secondary",
            descKey: "aiDashboard.stats.averageResponseDesc",
          },
          {
            titleKey: "aiDashboard.stats.sessionsTitle",
            value: providerStats.value.sessions,
            valueClass: "text-accent",
            descKey: "aiDashboard.stats.sessionsDesc",
            descInterpolation: { provider: activeProviderLabel.value },
          },
        ]
      : [],
  );

  return {
    statsItems,
  };
}

export function buildAIDashboardViewModel(input: {
  dashboardBootstrapError: Ref<unknown>;
  loading: ComputedRef<boolean>;
  providerPresentation: ReturnType<typeof createDashboardProviderPresentation>;
  providerStats: ComputedRef<AiDashboardStats | null>;
  providers: ComputedRef<ProviderConfig[]>;
  selection: {
    selectedModel: Ref<string>;
    selectedProvider: Ref<AIProviderType>;
    selectedProviderModels: ComputedRef<string[]>;
  };
