export const API_DOCS_ASYNC_DATA_KEY = "api-docs-json";
export const UNKNOWN_TAG_LABEL_KEY = "apiDocs.groups.untagged";
export const API_TESTER_DIALOG_TITLE_ID = "api-endpoint-tester-title";
export const API_TESTER_DIALOG_DESCRIPTION_ID = "api-endpoint-tester-description";

export const HTTP_METHOD_CLASSES: Readonly<Record<ApiHttpMethod, string>> = {
  get: "badge-success",
  post: "badge-info",
  put: "badge-warning",
  patch: "badge-accent",
  delete: "badge-error",
  head: "badge-neutral",
  options: "badge-neutral",
  trace: "badge-neutral",
};

export type ApiDocsTranslate = (key: string) => string;

export interface ApiDocsToast {
  readonly error: (message: string) => void;
  readonly info: (message: string) => void;
  readonly success: (message: string) => void;
}

import { computed } from "vue";
import {
  API_DOCS_ASYNC_DATA_KEY,
  type ApiDocsTranslate,
  UNKNOWN_TAG_LABEL_KEY,
} from "~/composables/api-docs-page-contracts";
import { useApi } from "~/composables/useApi";
import type { ApiDocsUiState, ApiEndpointGroup, OpenApiSpec } from "~/types/api-docs";
import { buildApiEndpointGroups } from "~/utils/api-docs-endpoints";
import { readOpenApiSpec } from "~/utils/api-docs-openapi";
import { toApiDocsUiStateFromStatusCode, toErrorStatusCode } from "~/utils/api-docs-status";
import { requireApiResponsePayload } from "~/utils/api-response";

interface ApiDocsPageDataOptions {
  readonly t: ApiDocsTranslate;
}

export const useApiDocsPageData = ({ t }: ApiDocsPageDataOptions) => {
  const api = useApi();

  const fetchOpenApiSpec = async (): Promise<OpenApiSpec | null> => {
    const raw = requireApiResponsePayload(
      await api.docs.api.json.get(),
      t("apiDocs.state.errorNonRetryable"),
    );
    return readOpenApiSpec(raw);
  };

  const {
    data: parsedSpec,
    status: rawSpecStatus,
    error: rawSpecError,
    refresh: refreshSpec,
  } = useAsyncData<OpenApiSpec | null>(API_DOCS_ASYNC_DATA_KEY, fetchOpenApiSpec, {
    server: true,
    default: () => null,
  });

  const endpointGroups = computed<readonly ApiEndpointGroup[]>(() =>
    buildApiEndpointGroups(parsedSpec.value, t(UNKNOWN_TAG_LABEL_KEY)),
  );
  const endpointCount = computed(() => {
    let total = 0;
    for (const endpointGroup of endpointGroups.value) {
      total += endpointGroup.endpoints.length;
    }
    return total;
  });
  const docsUiState = computed<ApiDocsUiState>(() => {
    if (rawSpecStatus.value === "pending") {
      return "loading";
    }
    if (rawSpecError.value) {
      return toApiDocsUiStateFromStatusCode(toErrorStatusCode(rawSpecError.value));
    }
    if (endpointCount.value === 0) {
      return "empty";
    }
    return "success";
  });

  return {
    docsUiState,
    endpointGroups,
    rawSpecError,
    refreshSpec,
  };
};

import type { ComponentPublicInstance, Ref } from "vue";
import { computed, nextTick, onBeforeUnmount, watch } from "vue";
import { useScrollSpy } from "~/composables/useScrollSpy";
import type { ApiDocsUiState, ApiEndpointGroup } from "~/types/api-docs";

interface ApiDocsPageNavigationOptions {
  readonly route: { readonly hash: string };
  readonly docsUiState: Readonly<Ref<ApiDocsUiState>>;
  readonly endpointGroups: Readonly<Ref<readonly ApiEndpointGroup[]>>;
}

const createActiveEndpointId = (
  activeSectionId: Readonly<Ref<string | undefined>>,
  endpointGroups: Readonly<Ref<readonly ApiEndpointGroup[]>>,
) =>
  computed(() => {
    if (activeSectionId.value && activeSectionId.value.length > 0) {
      return activeSectionId.value;
    }
    const firstGroup = endpointGroups.value[0];
    return firstGroup?.endpoints[0]?.id ?? "";
  });

const syncScrollSpyFromHash = (
  routeHash: string,
  endpointGroups: Readonly<Ref<readonly ApiEndpointGroup[]>>,
  syncFromHash: (hash: string) => boolean,
  scrollToSection: ReturnType<typeof useScrollSpy>["scrollToSection"],
): void => {
  if (!syncFromHash(routeHash)) {
    const firstEndpointId = endpointGroups.value[0]?.endpoints[0]?.id;
    if (firstEndpointId) {
      scrollToSection(firstEndpointId, {
        smooth: false,
        focus: false,
        updateHash: false,
      });
    }
  }
};

const createScrollToEndpoint =
  (scrollToSection: ReturnType<typeof useScrollSpy>["scrollToSection"]) =>
  (sectionId: string): void => {
    scrollToSection(sectionId, {
      smooth: true,
      focus: true,
      updateHash: true,
    });
  };

const createEndpointSectionRegistrar =
  (setSectionRef: ReturnType<typeof useScrollSpy>["setSectionRef"]) =>
  (endpointId: string) =>
  (element: Element | ComponentPublicInstance | null) => {
    setSectionRef(endpointId, element instanceof Element ? element : null);
  };

const registerApiDocsNavigationEffects = (input: {
  readonly docsUiState: Readonly<Ref<ApiDocsUiState>>;
  readonly endpointGroups: Readonly<Ref<readonly ApiEndpointGroup[]>>;
  readonly route: { readonly hash: string };
  readonly syncFromHash: ReturnType<typeof useScrollSpy>["syncFromHash"];
  readonly startObserver: ReturnType<typeof useScrollSpy>["startObserver"];
  readonly refreshObserver: ReturnType<typeof useScrollSpy>["refreshObserver"];
  readonly stopObserver: ReturnType<typeof useScrollSpy>["stopObserver"];
  readonly scrollToSection: ReturnType<typeof useScrollSpy>["scrollToSection"];
}) => {
  watch(
    [input.docsUiState, input.endpointGroups],
    async ([stateValue]) => {
      if (stateValue !== "success") {
        input.stopObserver();
        return;
      }

      await nextTick();
      input.startObserver();
      input.refreshObserver();
      syncScrollSpyFromHash(
        input.route.hash,
        input.endpointGroups,
        input.syncFromHash,
        input.scrollToSection,
      );
    },
    { immediate: true },
  );

  watch(
    () => input.route.hash,
    (nextHash) => {
      if (input.docsUiState.value !== "success") {
        return;
      }
      input.syncFromHash(nextHash);
    },
  );

  onBeforeUnmount(() => {
    input.stopObserver();
  });
};

export const useApiDocsPageNavigation = ({
  route,
  docsUiState,
  endpointGroups,
}: ApiDocsPageNavigationOptions) => {
  const scrollSpy = useScrollSpy();
  registerApiDocsNavigationEffects({
    docsUiState,
    endpointGroups,
    route,
    syncFromHash: scrollSpy.syncFromHash,
    startObserver: scrollSpy.startObserver,
    refreshObserver: scrollSpy.refreshObserver,
    stopObserver: scrollSpy.stopObserver,
    scrollToSection: scrollSpy.scrollToSection,
  });

  return {
    activeEndpointId: createActiveEndpointId(scrollSpy.activeSectionId, endpointGroups),
    scrollToEndpoint: createScrollToEndpoint(scrollSpy.scrollToSection),
    registerEndpointSectionRef: createEndpointSectionRegistrar(scrollSpy.setSectionRef),
  };
};

import { HTTP_METHOD_CLASSES } from "~/composables/api-docs-page-contracts";
