import {
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_MULTIPLE_CHOICES,
  HTTP_STATUS_OK,
  HTTP_STATUS_TOO_MANY_REQUESTS,
} from "@bao/shared/constants/http";
import { nextTick } from "vue";
import type { ApiDocsToast, ApiDocsTranslate } from "~/composables/api-docs-page-contracts";
import {
  createApiDocsEndpointRequest,
  createInitialTesterValues,
  fetchApiDocsEndpointResponse,
} from "~/composables/api-docs-page-tester-request";
import type { ApiEndpoint, ApiTesterState, FetchEndpointResultOk } from "~/types/api-docs";
import { toApiDocsUiStateFromStatusCode } from "~/utils/api-docs-status";

type MutableRef<T> = {
  value: T;
};

export interface ApiDocsEndpointTesterActionOptions {
  readonly t: ApiDocsTranslate;
  readonly apiBase: string;
  readonly requestUrl: URL;
  readonly toast: ApiDocsToast;
  readonly testerInvoker: MutableRef<{ focus?: () => void } | null>;
  readonly testerDialogOpen: MutableRef<boolean>;
  readonly selectedEndpoint: MutableRef<ApiEndpoint | null>;
  readonly testerState: MutableRef<ApiTesterState>;
  readonly testerErrorMessage: MutableRef<string>;
  readonly testerResponse: MutableRef<FetchEndpointResultOk | null>;
  readonly pathParameterValues: MutableRef<Record<string, string>>;
  readonly queryParameterValues: MutableRef<Record<string, string>>;
  readonly requestBodyValue: MutableRef<string>;
}

const applyApiDocsTesterFailure = (input: {
  testerState: MutableRef<ApiTesterState>;
  testerErrorMessage: MutableRef<string>;
  toast: ApiDocsToast;
  t: ApiDocsTranslate;
  message: string;
  state?: ApiTesterState;
}) => {
  input.testerState.value = input.state ?? "errorRetryable";
  input.testerErrorMessage.value = input.message;
  input.toast.error(input.t("apiDocs.tester.requestErrorToast"));
};

const applyApiDocsTesterSuccess = (input: {
  testerState: MutableRef<ApiTesterState>;
  testerErrorMessage: MutableRef<string>;
  testerResponse: MutableRef<FetchEndpointResultOk | null>;
  toast: ApiDocsToast;
  t: ApiDocsTranslate;
  responseResult: FetchEndpointResultOk;
}) => {
  input.testerResponse.value = input.responseResult;
  const isSuccessStatusCode =
    input.responseResult.statusCode >= HTTP_STATUS_OK &&
    input.responseResult.statusCode < HTTP_STATUS_MULTIPLE_CHOICES;

  if (!isSuccessStatusCode) {
    input.testerState.value = toApiDocsUiStateFromStatusCode(input.responseResult.statusCode);
    if (input.testerState.value === "loading" || input.testerState.value === "success") {
      input.testerState.value =
        input.responseResult.statusCode === HTTP_STATUS_TOO_MANY_REQUESTS ||
        input.responseResult.statusCode >= HTTP_STATUS_INTERNAL_SERVER_ERROR
          ? "errorRetryable"
          : "errorNonRetryable";
    }
    input.testerErrorMessage.value = input.t("apiDocs.tester.errorFallback");
    input.toast.error(input.t("apiDocs.tester.requestErrorToast"));
    return;
  }

  if (input.responseResult.body.trim().length === 0) {
    input.testerState.value = "empty";
    input.toast.info(input.t("apiDocs.tester.emptyResponseToast"));
    return;
  }

  input.testerState.value = "success";
  input.toast.success(input.t("apiDocs.tester.requestSuccessToast"));
};

const openApiEndpointTester =
  (input: ApiDocsEndpointTesterActionOptions) =>
  (endpoint: ApiEndpoint, invoker: EventTarget | null): void => {
    const initialValues = createInitialTesterValues(endpoint);
    input.selectedEndpoint.value = endpoint;
    input.testerState.value = "idle";
    input.testerErrorMessage.value = "";
    input.testerResponse.value = null;
    input.testerInvoker.value = invoker instanceof HTMLElement ? invoker : null;
    input.pathParameterValues.value = initialValues.initialPathValues;
    input.queryParameterValues.value = initialValues.initialQueryValues;
    input.requestBodyValue.value = initialValues.requestBodyValue;
    input.testerDialogOpen.value = true;
  };

const closeApiEndpointTester = async (input: ApiDocsEndpointTesterActionOptions): Promise<void> => {
  input.testerDialogOpen.value = false;
  const invoker = input.testerInvoker.value;
  input.testerInvoker.value = null;
  if (!invoker) {
    return;
  }
  await nextTick();
  invoker.focus?.();
};

const executeApiEndpointTesterRequest = async (
  input: ApiDocsEndpointTesterActionOptions,
): Promise<void> => {
  const endpoint = input.selectedEndpoint.value;
  if (!endpoint) {
    return;
  }

  const request = createApiDocsEndpointRequest({
    endpoint,
    pathParameterValues: input.pathParameterValues.value,
    queryParameterValues: input.queryParameterValues.value,
    requestBodyValue: input.requestBodyValue.value,
    apiBase: input.apiBase,
    requestUrl: input.requestUrl,
    t: input.t,
  });

  if (!request.ok) {
    applyApiDocsTesterFailure({
      testerState: input.testerState,
      testerErrorMessage: input.testerErrorMessage,
      toast: input.toast,
      t: input.t,
      message: request.message,
      state: request.state,
    });
    return;
  }

  input.testerState.value = "loading";
  input.testerErrorMessage.value = "";
  input.testerResponse.value = null;

  const responseResult = await fetchApiDocsEndpointResponse({
    endpointUrl: request.endpointUrl,
    requestMethod: request.requestMethod,
    requestBody: request.requestBody,
    t: input.t,
  });

  if (!responseResult.ok) {
    applyApiDocsTesterFailure({
      testerState: input.testerState,
      testerErrorMessage: input.testerErrorMessage,
      toast: input.toast,
      t: input.t,
      message: responseResult.errorMessage,
    });
    return;
  }

  applyApiDocsTesterSuccess({
    testerState: input.testerState,
    testerErrorMessage: input.testerErrorMessage,
    testerResponse: input.testerResponse,
    toast: input.toast,
    t: input.t,
    responseResult: responseResult.payload,
  });
};

export const createEndpointTesterActions = (input: ApiDocsEndpointTesterActionOptions) => ({
  openEndpointTester: openApiEndpointTester(input),
  handleEndpointTesterClosed: () => closeApiEndpointTester(input),
  executeEndpointRequest: () => executeApiEndpointTesterRequest(input),
});

import { safeParseJson } from "@bao/shared/utils/json";
import type { ApiDocsTranslate } from "~/composables/api-docs-page-contracts";
import { requestResolvedApiRaw, toClientApiHttpMethod } from "~/composables/api-request";
import type { ApiEndpoint, FetchEndpointResult, FetchEndpointResultOk } from "~/types/api-docs";
import {
  buildApiDocsQueryString,
  resolveApiDocsPathWithParameters,
} from "~/utils/api-docs-endpoints";
import { getApiDocsParameterValueDefault } from "~/utils/api-docs-status";
import { resolveApiEndpoint } from "~/utils/endpoints";

export type ApiDocsTesterInitialValues = {
  readonly initialPathValues: Record<string, string>;
  readonly initialQueryValues: Record<string, string>;
  readonly requestBodyValue: string;
};

export function createInitialTesterValues(endpoint: ApiEndpoint): ApiDocsTesterInitialValues {
  const initialPathValues: Record<string, string> = {};
  for (const name of endpoint.pathParameters) {
    initialPathValues[name] = "";
  }

  const initialQueryValues: Record<string, string> = {};
  for (const parameter of endpoint.queryParameters) {
    initialQueryValues[parameter.name] = getApiDocsParameterValueDefault(parameter.example);
  }

  return {
    initialPathValues,
    initialQueryValues,
    requestBodyValue: endpoint.requestBodyTemplate,
  };
}

type ApiDocsEndpointRequestError = {
  readonly ok: false;
  readonly state: "errorNonRetryable";
  readonly message: string;
};

type ApiDocsEndpointRequestOk = {
  readonly ok: true;
  readonly endpointUrl: string;
  readonly requestMethod: string;
  readonly requestBody: string | null;
};

export type ApiDocsEndpointRequest = ApiDocsEndpointRequestOk | ApiDocsEndpointRequestError;

export function createApiDocsEndpointRequest(input: {
  readonly endpoint: ApiEndpoint;
  readonly pathParameterValues: Record<string, string>;
  readonly queryParameterValues: Record<string, string>;
  readonly requestBodyValue: string;
  readonly apiBase: string;
  readonly requestUrl: URL;
  readonly t: ApiDocsTranslate;
}): ApiDocsEndpointRequest {
  const resolvedPath = resolveApiDocsPathWithParameters(input.endpoint, input.pathParameterValues);
  if (!resolvedPath) {
    return {
      ok: false,
      state: "errorNonRetryable",
      message: input.t("apiDocs.tester.invalidPath"),
    };
  }

  const queryString = buildApiDocsQueryString(
    input.endpoint.queryParameters,
    input.queryParameterValues,
  );
  const payloadText = input.requestBodyValue.trim();
  const shouldSendBody = input.endpoint.requestBodyRequired || payloadText.length > 0;
  const parsedBody = shouldSendBody
    ? safeParseJson(payloadText.length > 0 ? payloadText : "{}")
    : null;

  if (shouldSendBody && parsedBody === null) {
    return {
      ok: false,
      state: "errorNonRetryable",
      message: input.t("apiDocs.tester.requestFailure"),
    };
  }

  return {
    ok: true,
    endpointUrl: resolveApiEndpoint(
      input.apiBase,
      input.requestUrl,
      `${resolvedPath}${queryString}`,
    ),
    requestMethod: input.endpoint.method.toUpperCase(),
    requestBody: shouldSendBody ? JSON.stringify(parsedBody) : null,
  };
}

export async function fetchApiDocsEndpointResponse(input: {
  readonly endpointUrl: string;
  readonly requestMethod: string;
  readonly requestBody: string | null;
  readonly t: ApiDocsTranslate;
}): Promise<FetchEndpointResult> {
  const method = toClientApiHttpMethod(input.requestMethod);
  if (!method) {
    return {
      ok: false,
      errorMessage: input.t("apiDocs.tester.requestFailure"),
    };
  }

  const startedAt = Date.now();
  return requestResolvedApiRaw(input.endpointUrl, {
    method,
    headers: {
      Accept: "application/json",
      ...(input.requestBody ? { "Content-Type": "application/json" } : {}),
    },
    ...(input.requestBody ? { body: input.requestBody } : {}),
    responseType: "text",
  }).then(
    (response) => {
      const headers: Record<string, string> = {};
      response.headers.forEach((value, key) => {
        headers[key] = value;
      });
      const body =
        typeof response._data === "string" ? response._data : JSON.stringify(response._data ?? "");
      return {
        ok: true,
        payload: {
          statusCode: response.status,
          statusText: response.statusText,
          headers,
          body,
          durationMs: Date.now() - startedAt,
          url: input.endpointUrl,
          method: input.requestMethod,
        } satisfies FetchEndpointResultOk,
      };
    },
    () => ({
      ok: false,
      errorMessage: input.t("apiDocs.tester.requestFailure"),
    }),
  );
}

import { safeParseJson } from "@bao/shared/utils/json";
import type { Ref } from "vue";
import { computed, ref } from "vue";
import type { ApiDocsToast, ApiDocsTranslate } from "~/composables/api-docs-page-contracts";
import { createEndpointTesterActions } from "~/composables/api-docs-page-tester-actions";
import type { ApiEndpoint, ApiTesterState, FetchEndpointResultOk } from "~/types/api-docs";

interface ApiDocsPageTesterOptions {
  readonly t: ApiDocsTranslate;
  readonly apiBase: string;
  readonly requestUrl: URL;
  readonly toast: ApiDocsToast;
}

const createTesterStateLabel = (testerState: Readonly<Ref<ApiTesterState>>, t: ApiDocsTranslate) =>
  computed(() => {
    if (testerState.value === "idle") {
      return t("apiDocs.tester.steps.configure");
    }
    if (testerState.value === "success") {
      return t("apiDocs.tester.requestSuccessToast");
    }
    if (testerState.value === "loading") {
      return t("apiDocs.state.loading");
    }
    if (testerState.value === "empty") {
      return t("apiDocs.state.empty");
    }
    return t(`apiDocs.state.${testerState.value}`);
  });

const createFormattedResponseBody = (testerResponse: Readonly<Ref<FetchEndpointResultOk | null>>) =>
  computed(() => {
    const body = testerResponse.value?.body ?? "";
    if (!body.trim()) {
      return "";
    }
    const parsedBody = safeParseJson(body);
    if (parsedBody === null) {
      return body;
    }
    return JSON.stringify(parsedBody, null, 2);
  });

export const useApiDocsPageTester = ({
  t,
  apiBase,
  requestUrl,
  toast,
}: ApiDocsPageTesterOptions) => {
  const testerInvoker = ref<{ focus?: () => void } | null>(null);
  const testerDialogOpen = ref(false);
  const selectedEndpoint = ref<ApiEndpoint | null>(null);
  const testerState = ref<ApiTesterState>("idle");
  const testerErrorMessage = ref("");
  const testerResponse = ref<FetchEndpointResultOk | null>(null);
  const pathParameterValues = ref<Record<string, string>>({});
  const queryParameterValues = ref<Record<string, string>>({});
  const requestBodyValue = ref("");
  const actions = createEndpointTesterActions({
    t,
    apiBase,
    requestUrl,
    toast,
    testerInvoker,
    testerDialogOpen,
    selectedEndpoint,
    testerState,
    testerErrorMessage,
    testerResponse,
    pathParameterValues,
    queryParameterValues,
    requestBodyValue,
  });

  return {
    testerDialogOpen,
    selectedEndpoint,
    testerState,
    testerStateLabel: createTesterStateLabel(testerState, t),
    pathParameterValues,
    queryParameterValues,
    requestBodyValue,
    testerErrorMessage,
    testerResponse,
    formattedResponseBody: createFormattedResponseBody(testerResponse),
    openEndpointTester: (endpoint: ApiEndpoint, invoker: EventTarget | null) =>
      actions.openEndpointTester(endpoint, invoker),
    handleEndpointTesterClosed: () => actions.handleEndpointTesterClosed(),
    executeEndpointRequest: () => actions.executeEndpointRequest(),
  };
};

