import { normalizeJobProviderSettings as normalizeSharedJobProviderSettings } from "@bao/shared/types/settings-normalization";
import {
  asBoolean,
  asJsonArray,
  asNumber,
  asString,
  isRecord,
} from "@bao/shared/utils/type-guards";
