  COMPANY_BOARD_ATS_TYPES,
  COMPANY_BOARD_TEMPLATE_KEYS,
  GAMING_PORTAL_IDS,
  SPEECH_AUDIO_FORMATS,
} from "~/composables/api-normalizer-settings-constants";
