import { $fetch } from "ofetch";
import { useRequestURL, useRuntimeConfig } from "#imports";
import { getStoredApiKey } from "~/plugins/eden";
import { resolveApiEndpoint, resolveBrowserApiFetchUrl } from "~/utils/endpoints";

const CONTENT_DISPOSITION_ENCODED_FILENAME_PATTERN = /filename\*=UTF-8''([^;]+)/i;
const CONTENT_DISPOSITION_QUOTED_FILENAME_PATTERN = /filename="([^"]+)"/i;
const CONTENT_DISPOSITION_PLAIN_FILENAME_PATTERN = /filename=([^;]+)/i;

export interface ClientApiRequestRuntime {
  apiBase: string;
  requestUrl: URL;
}

export type ClientApiHttpMethod = "GET" | "POST" | "PUT" | "DELETE" | "PATCH" | "HEAD";

interface ClientApiRequestOptions {
  method?: ClientApiHttpMethod;
  body?: BodyInit | object | null;
  query?: Record<string, string | number | boolean | undefined>;
  headers?: Record<string, string>;
}

export const toClientApiHttpMethod = (method: string): ClientApiHttpMethod | null => {
  switch (method.trim().toUpperCase()) {
    case "GET":
      return "GET";
    case "POST":
      return "POST";
    case "PUT":
      return "PUT";
    case "DELETE":
      return "DELETE";
    case "PATCH":
      return "PATCH";
    case "HEAD":
      return "HEAD";
    default:
      return null;
  }
};

/**
 * Resolves the canonical client request runtime for direct API endpoint calls.
 */
export function useClientApiRequestRuntime(): ClientApiRequestRuntime {
  return {
    apiBase: String(useRuntimeConfig().public.apiBase || "/"),
    requestUrl: useRequestURL(),
  };
}

const buildAuthorizationHeaders = (): Record<string, string> => {
  const key = getStoredApiKey();
  return key ? { Authorization: `Bearer ${key}` } : {};
};

export const buildClientApiHeaders = (
  headers: Record<string, string> = {},
): Record<string, string> => ({
  ...buildAuthorizationHeaders(),
  ...headers,
});

function isBodyInitValue(value: BodyInit | object | null | undefined): value is BodyInit {
  return (
    typeof value === "string" ||
    value instanceof Blob ||
    value instanceof FormData ||
    value instanceof URLSearchParams ||
    value instanceof ArrayBuffer ||
    ArrayBuffer.isView(value) ||
    value instanceof ReadableStream
  );
}

function createRequestBody(body: BodyInit | object | null | undefined): BodyInit | undefined {
  if (body == null) {
    return;
  }

  if (isBodyInitValue(body)) {
    return body;
  }

  return JSON.stringify(body);
}

function resolveDownloadFilename(
  contentDisposition: string | null,
  fallbackFilename: string,
): string {
  if (!contentDisposition) {
    return fallbackFilename;
  }

  const encodedMatch = CONTENT_DISPOSITION_ENCODED_FILENAME_PATTERN.exec(contentDisposition);
  if (encodedMatch?.[1]) {
    return encodedMatch[1];
  }

  const quotedMatch = CONTENT_DISPOSITION_QUOTED_FILENAME_PATTERN.exec(contentDisposition);
  if (quotedMatch?.[1]) {
    return quotedMatch[1];
  }

  const plainMatch = CONTENT_DISPOSITION_PLAIN_FILENAME_PATTERN.exec(contentDisposition);
  return plainMatch?.[1]?.trim() || fallbackFilename;
}

function triggerFileDownload(blob: Blob, filename: string): void {
  if (!import.meta.client) {
    return;
  }
  const objectUrl = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = objectUrl;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(objectUrl);
}

export async function downloadApiFile(
  runtime: ClientApiRequestRuntime,
  endpoint: string,
  options: ClientApiRequestOptions,
  fallbackFilename: string,
): Promise<void> {
  const body = createRequestBody(options.body);
  const headers = buildClientApiHeaders(options.headers);
  const shouldSetJsonContentType =
    body !== undefined && !isBodyInitValue(options.body) && !("Content-Type" in headers);

  const absoluteEndpoint = resolveApiEndpoint(runtime.apiBase, runtime.requestUrl, endpoint);
  const fetchUrl = import.meta.client
    ? resolveBrowserApiFetchUrl(absoluteEndpoint, runtime.requestUrl)
    : absoluteEndpoint;
  const response = await fetch(fetchUrl, {
    method: options.method ?? "GET",
    body,
    headers: shouldSetJsonContentType
      ? {
          ...headers,
          "Content-Type": "application/json",
        }
      : headers,
  });

  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }

  const blob = await response.blob();
  triggerFileDownload(
    blob,
    resolveDownloadFilename(response.headers.get("content-disposition"), fallbackFilename),
  );
}

/**
 * Executes a typed client API request against a canonical shared endpoint.
 */
export function requestApi<TResponse>(
  runtime: ClientApiRequestRuntime,
  endpoint: string,
  options: ClientApiRequestOptions = {},
): Promise<TResponse> {
  return $fetch<TResponse>(resolveApiEndpoint(runtime.apiBase, runtime.requestUrl, endpoint), {
    ...options,
    headers: buildClientApiHeaders(options.headers),
  });
}

/**
 * Executes a raw request against an already-resolved absolute API URL with canonical auth.
 */
export function requestResolvedApiRaw(
  absoluteUrl: string,
  options: ClientApiRequestOptions & { responseType?: "text" } = {},
) {
  return $fetch.raw(absoluteUrl, {
    ...options,
    headers: buildClientApiHeaders(options.headers),
    credentials: "include",
    responseType: options.responseType ?? "text",
  });
}

import type { Ref } from "vue";

type SettledPromise<T> = { ok: true; value: T } | { ok: false; error: Error };

const loadingCounters = new WeakMap<Ref<boolean>, number>();

const toError = (value: unknown, fallbackMessage: string): Error => {
  if (value instanceof Error) {
    return value;
  }
  if (typeof value === "string" && value.trim().length > 0) {
    return new Error(value);
  }
  return new Error(fallbackMessage);
};

/**
 * Executes an async task while maintaining a reference-counted loading state.
 *
 * Nested calls that share the same `loading` ref remain loading until the outermost task finishes.
 */
export function withLoadingState<T>(loading: Ref<boolean>, task: () => Promise<T>): Promise<T> {
  const activeCount = (loadingCounters.get(loading) ?? 0) + 1;
  loadingCounters.set(loading, activeCount);
  loading.value = true;

  return task().finally(() => {
    const pendingCount = (loadingCounters.get(loading) ?? 1) - 1;
    if (pendingCount <= 0) {
      loadingCounters.delete(loading);
      loading.value = false;
      return;
    }
    loadingCounters.set(loading, pendingCount);
    loading.value = true;
  });
}

/**
 * Throws a deterministic error when an Eden response contains an error payload.
 */
export function assertApiResponse<TError>(error: TError | null | undefined, message: string): void {
  if (!error) {
    return;
  }
  throw new Error(message);
}

/**
 * Requires a nullable value to be present and returns it as non-nullable.
 */
export function requireValue<T>(value: T | null | undefined, message: string): T {
  if (value === null || value === undefined) {
    throw new Error(message);
  }
  return value;
}

/**
 * Resolves a promise into a typed success/error union without `try/catch`.
 */
export function settlePromise<T>(
  promise: Promise<T>,
  fallbackMessage: string,
): Promise<SettledPromise<T>> {
  return promise.then(
    (value) => ({ ok: true, value }),
    (reason: unknown) => ({ ok: false, error: toError(reason, fallbackMessage) }),
  );
}

import type {
  AutomationRunStatus,
  AutomationRunType,
  AutomationScrapeTarget,
  RpaCapabilityAuditReport,
} from "@bao/shared/constants/automation";
import type {
  EmailResponseRequest,
  EmailResponseResult,
} from "@bao/shared/schemas/automation-email.schema";
import type { RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import { settle } from "@bao/shared/utils/promise";
import type { AsyncData } from "nuxt/app";
import type { FetchError } from "ofetch";
import { type MaybeRef, toValue } from "vue";
import { useAsyncData } from "#imports";
import { assertApiResponse } from "~/composables/async-flow";
import type { ClientApi } from "~/types/client-api";

export interface JobApplyBody {
  jobUrl: string;
  resumeId: string;
  coverLetterId?: string;
  jobId?: string;
  customAnswers?: Record<string, string>;
}

export interface ScheduleJobApplyBody extends JobApplyBody {
  runAt: string;
}

export interface ScheduleEmailResponseBody extends EmailResponseRequest {
  runAt: string;
}

export interface ScheduleScrapeBody {
  target: AutomationScrapeTarget;
  runAt: string;
}

export interface RunScrapeBody {
  target: AutomationScrapeTarget;
}

export interface FetchRunsParams {
  type?: AutomationRunType;
  status?: AutomationRunStatus;
}

type RunListAsyncData = AsyncData<RpaRunExecutionEnvelope[] | undefined, FetchError | undefined>;
type RunAsyncData = AsyncData<RpaRunExecutionEnvelope | undefined, FetchError | undefined>;
type CapabilityAuditAsyncData = AsyncData<
  RpaCapabilityAuditReport | undefined,
  FetchError | undefined
>;

function asRunEnvelope(data: unknown): RpaRunExecutionEnvelope {
  return data as RpaRunExecutionEnvelope;
}

function asRunEnvelopeList(data: unknown): RpaRunExecutionEnvelope[] {
  return Array.isArray(data) ? (data as RpaRunExecutionEnvelope[]) : [];
}

function asCapabilityReport(data: unknown): RpaCapabilityAuditReport {
  return data as RpaCapabilityAuditReport;
}

export function createAutomationEdenMutations(api: ClientApi) {
  const triggerJobApply = async (body: JobApplyBody): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation["job-apply"].post(body);
    assertApiResponse(error, "automation.jobApply.triggerFailed");
    return asRunEnvelope(data);
  };

  const scheduleJobApply = async (body: ScheduleJobApplyBody): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation["job-apply"].schedule.post(body);
    assertApiResponse(error, "automation.jobApply.scheduleFailed");
    return asRunEnvelope(data);
  };

  const triggerEmailResponse = async (body: EmailResponseRequest): Promise<EmailResponseResult> => {
    const { data, error } = await api.automation["email-response"].post(body);
    assertApiResponse(error, "automation.emailResponse.triggerFailed");
    return data as EmailResponseResult;
  };

  const scheduleEmailResponse = async (
    body: ScheduleEmailResponseBody,
  ): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation["email-response"].schedule.post(body);
    assertApiResponse(error, "automation.emailResponse.scheduleFailed");
    return asRunEnvelope(data);
  };

  const triggerScrape = async (body: RunScrapeBody): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation.scrape.post(body);
    assertApiResponse(error, "automation.scrape.triggerFailed");
    return asRunEnvelope(data);
  };

  const scheduleScrape = async (body: ScheduleScrapeBody): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation.scrape.schedule.post(body);
    assertApiResponse(error, "automation.scrape.scheduleFailed");
    return asRunEnvelope(data);
  };

  return {
    triggerJobApply,
    scheduleJobApply,
    triggerEmailResponse,
    scheduleEmailResponse,
    triggerScrape,
    scheduleScrape,
  };
}

export function createAutomationEdenQueries(api: ClientApi) {
  const getVerifyContext = async (): Promise<{ resumeId: string } | null> => {
    const result = await settle(api.automation.verify.context.get());
    if (result.status !== "fulfilled") {
      return null;
    }
    const { data, error } = result.value;
    if (error || !data || typeof data.resumeId !== "string" || data.resumeId.length === 0) {
      return null;
    }
    return { resumeId: data.resumeId };
  };

  const getRun = async (id: string): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation.runs({ id }).get();
    assertApiResponse(error, "automation.runs.fetchOneFailed");
    return asRunEnvelope(data);
  };

  const getRuns = async (params: FetchRunsParams = {}): Promise<RpaRunExecutionEnvelope[]> => {
    const { data, error } = await api.automation.runs.get({
      query: {
        type: params.type,
        status: params.status,
      },
    });
    assertApiResponse(error, "automation.runs.fetchListFailed");
    return asRunEnvelopeList(data);
  };

  const getRpaCapabilities = async (): Promise<RpaCapabilityAuditReport> => {
    const { data, error } = await api.automation.capabilities.get();
    assertApiResponse(error, "automation.capabilities.fetchFailed");
    return asCapabilityReport(data);
  };

  const fetchRuns = (params: MaybeRef<FetchRunsParams> = {}): RunListAsyncData =>
    useAsyncData("automation-runs-list", async () => getRuns(toValue(params)), {
      watch: [() => toValue(params)],
    }) as RunListAsyncData;

  const fetchRun = (id: string): RunAsyncData =>
    useAsyncData(`automation-run-${id}`, async () => getRun(id)) as RunAsyncData;

  const fetchRpaCapabilities = (): CapabilityAuditAsyncData =>
    useAsyncData("automation-rpa-capabilities", async () =>
      getRpaCapabilities(),
    ) as CapabilityAuditAsyncData;

  return {
    getVerifyContext,
    getRun,
    getRuns,
    getRpaCapabilities,
    fetchRuns,
    fetchRun,
    fetchRpaCapabilities,
  };
}

import type { RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import { isValidEmail } from "@bao/shared/utils/validation";
import type { Ref } from "vue";
import type { useI18n } from "vue-i18n";
import { settlePromise } from "~/composables/async-flow";
import { DATE_FORMAT_OPTIONS, toIsoTimestamp } from "~/composables/schedule-timestamp";
import { getErrorMessage } from "~/utils/errors";
import { formatDateWithLocale } from "~/utils/locale-format";

export type EmailResponseTone = "professional" | "friendly" | "concise";

export interface EmailFormState {
  subject: string;
  message: string;
  sender: string;
  tone: EmailResponseTone;
  recipientEmail: string;
  deliverAfterGeneration: boolean;
  runAt: string;
}

export interface EmailActionResult {
  runId: string;
  reply: string;
  provider: string;
  model: string;
  delivered: boolean;
  recipientEmail?: string;
  deliveredAt?: string;
  messageId?: string;
}
export const EMAIL_TONE_OPTIONS: readonly EmailResponseTone[] = [
  "professional",
  "friendly",
  "concise",
] as const;

export const createEmailAutomationForm = () =>
  reactive<EmailFormState>({
    subject: "",
    message: "",
    sender: "",
    tone: "professional",
    recipientEmail: "",
    deliverAfterGeneration: false,
    runAt: "",
  });

export const createEmailAutomationResultState = () => ({
  pendingAction: ref<"generate" | "schedule" | null>(null),
  submitError: ref(""),
  lastResult: ref<EmailActionResult | null>(null),
  scheduledRun: ref<RpaRunExecutionEnvelope | null>(null),
});

export type EmailAutomationResultState = ReturnType<typeof createEmailAutomationResultState>;

export const createResolvedRecipientEmailComputed = (form: EmailFormState) =>
  computed(() => {
    const explicitRecipient = form.recipientEmail.trim();
    if (explicitRecipient.length > 0) {
      return explicitRecipient;
    }

    const sender = form.sender.trim();
    return isValidEmail(sender) ? sender : "";
  });
export const createToLocalizedDateTime =
  (localeValue: () => unknown, fallbackLocaleValue: () => unknown) =>
  (value: string): string =>
    formatDateWithLocale(value, localeValue(), fallbackLocaleValue(), DATE_FORMAT_OPTIONS) ?? value;

export const resetEmailAutomationResults = (
  submitError: Ref<string>,
  lastResult: Ref<EmailActionResult | null>,
  scheduledRun: Ref<RpaRunExecutionEnvelope | null>,
): void => {
  submitError.value = "";
  lastResult.value = null;
  scheduledRun.value = null;
};

export const createBaseEmailPayload = (
  form: EmailFormState,
  resolvedRecipientEmail: Readonly<Ref<string>>,
) => ({
  subject: form.subject.trim(),
  message: form.message.trim(),
  tone: form.tone,
  ...(form.sender.trim() ? { sender: form.sender.trim() } : {}),
  ...(resolvedRecipientEmail.value ? { recipientEmail: resolvedRecipientEmail.value } : {}),
  deliverAfterGeneration: form.deliverAfterGeneration,
});

export const createValidateDeliverySettings = (options: {
  t: ReturnType<typeof useI18n>["t"];
  form: EmailFormState;
  submitError: Ref<string>;
  emailDeliveryConfigured: Readonly<Ref<boolean>>;
  resolvedRecipientEmail: Readonly<Ref<string>>;
}) => {
  return (): boolean => {
    if (!options.form.deliverAfterGeneration) return true;
    if (!options.emailDeliveryConfigured.value) {
      options.submitError.value = options.t("automation.email.deliveryUnavailableDescription");
      return false;
    }
    if (!isValidEmail(options.resolvedRecipientEmail.value)) {
      options.submitError.value = options.t("automation.email.invalidRecipient");
      return false;
    }
    return true;
  };
};

export const createSubmitEmailResponse = (options: {
  t: ReturnType<typeof useI18n>["t"];
  form: EmailFormState;
  resultState: EmailAutomationResultState;
  resolvedRecipientEmail: Readonly<Ref<string>>;
  validateDeliverySettings: () => boolean;
  triggerEmailResponse: ReturnType<typeof useAutomation>["triggerEmailResponse"];
}) => {
  return async (): Promise<void> => {
    resetEmailAutomationResults(
      options.resultState.submitError,
      options.resultState.lastResult,
      options.resultState.scheduledRun,
    );

    if (!options.validateDeliverySettings()) {
      return;
    }

    options.resultState.pendingAction.value = "generate";
    const responseResult = await settlePromise(
      options.triggerEmailResponse(
        createBaseEmailPayload(options.form, options.resolvedRecipientEmail),
      ),
      options.t("automation.email.submitErrorFallback"),
    );
    options.resultState.pendingAction.value = null;

    if (!responseResult.ok) {
      options.resultState.submitError.value = getErrorMessage(
        responseResult.error,
        options.t("automation.email.submitErrorFallback"),
      );
      return;
    }

    const response = responseResult.value;
    options.resultState.lastResult.value = {
      runId: response.runId,
      reply: response.reply,
      provider: response.provider,
      model: response.model,
      delivered: response.delivered,
      recipientEmail: response.recipientEmail,
      deliveredAt: response.deliveredAt,
      messageId: response.messageId,
    };
  };
};

export const createSubmitScheduledEmailResponse = (options: {
  t: ReturnType<typeof useI18n>["t"];
  form: EmailFormState;
  resultState: EmailAutomationResultState;
  resolvedRecipientEmail: Readonly<Ref<string>>;
  validateDeliverySettings: () => boolean;
  scheduleEmailResponse: ReturnType<typeof useAutomation>["scheduleEmailResponse"];
}) => {
  return async (): Promise<void> => {
    resetEmailAutomationResults(
      options.resultState.submitError,
      options.resultState.lastResult,
      options.resultState.scheduledRun,
    );

    if (!options.validateDeliverySettings()) {
      return;
    }

    const runAt = toIsoTimestamp(options.form.runAt);
    if (!runAt) {
      options.resultState.submitError.value = options.t("automation.email.schedule.invalidRunAt");
      return;
    }

    options.resultState.pendingAction.value = "schedule";
    const scheduleResult = await settlePromise(
      options.scheduleEmailResponse({
        ...createBaseEmailPayload(options.form, options.resolvedRecipientEmail),
        runAt,
      }),
      options.t("automation.email.submitErrorFallback"),
    );
    options.resultState.pendingAction.value = null;

    if (!scheduleResult.ok) {
      options.resultState.submitError.value = getErrorMessage(
        scheduleResult.error,
        options.t("automation.email.submitErrorFallback"),
      );
      return;
    }

    options.resultState.scheduledRun.value = scheduleResult.value;
  };
};

