import { asJsonArray, isRecord } from "@bao/shared/utils/type-guards";
import type { CoverLetterSelectOption, ResumeSelectOption } from "~/types/automation-job-apply";

export interface JobApplyFormBody {
  jobUrl: string;
  resumeId: string;
  coverLetterId?: string;
  jobId?: string;
}

export const toResumeSelectOptions = <T>(value: T): ResumeSelectOption[] => {
  const entries = asJsonArray(value);
  if (!entries) {
    return [];
  }
  const options: ResumeSelectOption[] = [];
  for (const entry of entries) {
    if (!isRecord(entry) || typeof entry.id !== "string") {
      continue;
    }
    options.push({
      id: entry.id,
      ...(typeof entry.name === "string" ? { name: entry.name } : {}),
    });
  }
  return options;
};

export const toCoverLetterSelectOptions = <T>(value: T): CoverLetterSelectOption[] => {
  const entries = asJsonArray(value);
  if (!entries) {
    return [];
  }
  const options: CoverLetterSelectOption[] = [];
  for (const entry of entries) {
    if (!isRecord(entry) || typeof entry.id !== "string") {
      continue;
    }
    options.push({
      id: entry.id,
      ...(typeof entry.company === "string" ? { company: entry.company } : {}),
      ...(typeof entry.position === "string" ? { position: entry.position } : {}),
    });
  }
  return options;
};

export function buildJobApplyBody(input: {
  jobUrl: { value: string };
  resumeId: { value: string };
  coverLetterId: { value: string };
  jobId: { value: string };
}): JobApplyFormBody {
  const coverLetterId = input.coverLetterId.value.trim();
  const jobId = input.jobId.value.trim();

  return {
    jobUrl: input.jobUrl.value.trim(),
    resumeId: input.resumeId.value,
    ...(coverLetterId ? { coverLetterId } : {}),
    ...(jobId ? { jobId } : {}),
  };
}

export type TimelineStatus = "pending" | "running" | "success" | "error" | "skipped";

export interface TimelineEntry {
  readonly id: string;
  readonly timestamp: string;
  readonly stage: string;
  readonly status: TimelineStatus;
  readonly message: string;
}

import type { JsonObject, JsonValue } from "@bao/shared/utils/json";
import { safeParseJson } from "@bao/shared/utils/json";
import { asJsonArray, asNumber, asString, isRecord } from "@bao/shared/utils/type-guards";
import type { TimelineStatus } from "~/composables/automation-run-detail-page-contracts";

export type RunDetailFields = {
  id: string;
  status: TimelineStatus;
  updatedAt: string;
  progress: number | null;
  screenshots: readonly string[];
  input: JsonObject | null;
  output: JsonValue | null;
};

export type OutputStep = {
  action: string;
  status: "ok" | "error" | "skipped";
  message?: string;
};

export type StreamEventFields = {
  eventType: string;
  runId: string;
  sequence: number;
  timestamp: string;
  status?: TimelineStatus;
  message?: string;
  action?: string;
  resultSuccess?: boolean;
  resultError?: string;
  errorMessage?: string;
};

export const toTimelineStatus = (value: string | undefined): TimelineStatus => {
  if (
    value === "pending" ||
    value === "running" ||
    value === "success" ||
    value === "error" ||
    value === "skipped"
  ) {
    return value;
  }
  return "pending";
};

const projectJson = <T>(value: T): JsonValue | null => safeParseJson(JSON.stringify(value));

export const projectRunDetail = <T>(value: T): RunDetailFields | null => {
  const parsed = projectJson(value);
  if (!isRecord(parsed)) {
    return null;
  }
  const id = asString(parsed.id);
  const status = asString(parsed.status);
  const updatedAt = asString(parsed.updatedAt);
  if (!(id && status && updatedAt)) {
    return null;
  }
  const screenshots = asJsonArray(parsed.screenshots) ?? [];
  return {
    id,
    status: toTimelineStatus(status),
    updatedAt,
    progress: asNumber(parsed.progress) ?? null,
    screenshots: screenshots.filter((entry): entry is string => typeof entry === "string"),
    input: isRecord(parsed.input) ? parsed.input : null,
    output: parsed.output ?? null,
  };
};

const projectStreamEvent = (value: JsonValue): StreamEventFields | null => {
  if (!isRecord(value)) {
    return null;
  }
  const eventType = asString(value.eventType);
  const runId = asString(value.runId);
  const sequence = asNumber(value.sequence);
  const timestamp = asString(value.timestamp);
  if (!(eventType && runId && sequence !== undefined && timestamp)) {
    return null;
  }
  const fields: StreamEventFields = {
    eventType,
    runId,
    sequence,
    timestamp,
  };
  const status = asString(value.status);
  if (status) {
    fields.status = toTimelineStatus(status);
  }
  const message = asString(value.message);
  if (message) {
    fields.message = message;
  }
  const action = asString(value.action);
  if (action) {
    fields.action = action;
  }
  if (isRecord(value.result)) {
    fields.resultSuccess = value.result.success === true;
    const resultError = asString(value.result.error);
    if (resultError) {
      fields.resultError = resultError;
    }
  }
  if (isRecord(value.error)) {
    const errorMessage = asString(value.error.message);
    if (errorMessage) {
      fields.errorMessage = errorMessage;
    }
  }
  return fields;
};

export const projectStreamEvents = <T>(value: T): readonly StreamEventFields[] => {
  const parsed = projectJson(value);
  const entries = asJsonArray(parsed) ?? [];
  const events: StreamEventFields[] = [];
  for (const entry of entries) {
    const event = projectStreamEvent(entry);
    if (event) {
      events.push(event);
    }
  }
  return events;
};

export const projectOutputSteps = (output: JsonValue | null): OutputStep[] => {
  if (!isRecord(output)) {
    return [];
  }
  const steps = asJsonArray(output.steps) ?? [];
  const projected: OutputStep[] = [];
  for (const step of steps) {
    if (!isRecord(step)) {
      continue;
    }
    const action = asString(step.action);
    const status = asString(step.status);
    if (!(action && (status === "ok" || status === "error" || status === "skipped"))) {
      continue;
    }
    const message = asString(step.message);
    projected.push(message ? { action, status, message } : { action, status });
  }
  return projected;
};

export const toLocaleCode = <T>(value: T): string => {
  if (typeof value === "string" && value.length > 0) {
    return value;
  }
  if (Array.isArray(value) && typeof value[0] === "string" && value[0].length > 0) {
    return value[0];
  }
  return "en-US";
};

import { WS_ENDPOINTS } from "@bao/shared/constants/endpoints";
import { type RpaRunEvent, rpaRunEventSchema } from "@bao/shared/schemas/rpa-events.schema";
import { safeParseJson } from "@bao/shared/utils/json";
import type { ClientApiRequestRuntime } from "~/composables/api-request";
import { resolveWebSocketEndpoint } from "~/utils/endpoints";

/**
 * Subscribes to automation run events over WS_ENDPOINTS.automation.
 */
export function createAutomationRunSubscription(runtime: ClientApiRequestRuntime, wsBase: string) {
  return (runId: string, onEvent: (event: RpaRunEvent) => void): (() => void) => {
    const wsUrl = resolveWebSocketEndpoint(wsBase, runtime.requestUrl, WS_ENDPOINTS.automation);
    const ws = new WebSocket(wsUrl);

    ws.onopen = () => {
      ws.send(
        JSON.stringify({
          type: "subscribe",
          runId,
        }),
      );
    };

    ws.onmessage = (event) => {
      if (typeof event.data !== "string") {
        return;
      }
      const parsedPayload = safeParseJson(event.data);
      const parsedEvent = rpaRunEventSchema.safeParse(parsedPayload);
      if (parsedEvent.success) {
        onEvent(parsedEvent.data);
      }
    };

    return () => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(
          JSON.stringify({
            type: "unsubscribe",
            runId,
          }),
        );
      }
      ws.close();
    };
  };
}

import { AUTOMATION_RUN_STATUSES } from "@bao/shared/constants/automation";
import type { RpaRunEvent, RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import { PERCENT_MAX } from "~/constants/numeric-ui";

const [RUN_STATUS_PENDING, RUN_STATUS_RUNNING, RUN_STATUS_SUCCESS, RUN_STATUS_ERROR] =
  AUTOMATION_RUN_STATUSES;

export const isLiveAutomationRun = (run: RpaRunExecutionEnvelope): boolean =>
  run.status === RUN_STATUS_PENDING || run.status === RUN_STATUS_RUNNING;

export const computeAutomationRunProgressFromSteps = (
  currentStep: number | null,
  totalSteps: number | null,
): number => {
  if (
    typeof currentStep !== "number" ||
    typeof totalSteps !== "number" ||
    totalSteps <= 0 ||
    !Number.isFinite(currentStep) ||
    !Number.isFinite(totalSteps)
  ) {
    return 0;
  }
  return Math.max(0, Math.min(PERCENT_MAX, Math.round((currentStep / totalSteps) * PERCENT_MAX)));
};

const mergeProgressEvent = (
  run: RpaRunExecutionEnvelope,
  event: Extract<RpaRunEvent, { eventType: "progress" }>,
): RpaRunExecutionEnvelope => {
  const currentStep = typeof event.step === "number" ? event.step : run.currentStep;
  const totalSteps = typeof event.totalSteps === "number" ? event.totalSteps : run.totalSteps;
  const progress =
    typeof run.progress === "number" && Number.isFinite(run.progress)
      ? run.progress
      : computeAutomationRunProgressFromSteps(currentStep ?? null, totalSteps ?? null);
  return {
    ...run,
    status: event.status,
    currentStep: currentStep ?? null,
    totalSteps: totalSteps ?? null,
    progress,
    updatedAt: event.timestamp,
  };
};

const mergeResultEvent = (
  run: RpaRunExecutionEnvelope,
  event: Extract<RpaRunEvent, { eventType: "result" }>,
): RpaRunExecutionEnvelope => {
  const outputSteps = event.result.steps.length;
  return {
    ...run,
    status: event.result.success ? RUN_STATUS_SUCCESS : RUN_STATUS_ERROR,
    output: event.result,
    error: event.result.success ? null : event.result.error,
    progress: PERCENT_MAX,
    currentStep: outputSteps,
    totalSteps: outputSteps,
    completedAt: event.timestamp,
    updatedAt: event.timestamp,
  };
};

export const mergeAutomationRunWithEvent = (
  run: RpaRunExecutionEnvelope,
  event: RpaRunEvent,
): RpaRunExecutionEnvelope => {
  if (event.eventType === "progress") {
    return mergeProgressEvent(run, event);
  }
  if (event.eventType === "result") {
    return mergeResultEvent(run, event);
  }
  return {
    ...run,
    status: RUN_STATUS_ERROR,
    error: event.error,
    completedAt: event.timestamp,
    updatedAt: event.timestamp,
  };
};

import {
  AUTOMATION_RUN_STATUSES,
  type AutomationRunStatus,
  type AutomationRunType,
} from "@bao/shared/constants/automation";
import type { RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import { isRecord } from "@bao/shared/utils/type-guards";
import { computed, type Ref } from "vue";
import type { useI18n } from "vue-i18n";
import { isLiveAutomationRun } from "~/composables/automation-runs-page-merge";
import { PERCENT_MAX } from "~/constants/numeric-ui";
import { formatDateWithLocale } from "~/utils/locale-format";

type Translate = ReturnType<typeof useI18n>["t"];

const [
  RUN_STATUS_PENDING,
  RUN_STATUS_RUNNING,
  RUN_STATUS_SUCCESS,
  RUN_STATUS_ERROR,
  RUN_STATUS_CANCELLED,
] = AUTOMATION_RUN_STATUSES;

const RUN_STATUS_ORDER: Record<AutomationRunStatus, number> = {
  [RUN_STATUS_RUNNING]: 0,
  [RUN_STATUS_PENDING]: 1,
  [RUN_STATUS_ERROR]: 2,
  [RUN_STATUS_CANCELLED]: 3,
  [RUN_STATUS_SUCCESS]: 4,
};

const DATE_FORMAT_OPTIONS = {
  dateStyle: "medium",
  timeStyle: "short",
} as const satisfies Intl.DateTimeFormatOptions;

function compareRunsForSort(left: RpaRunExecutionEnvelope, right: RpaRunExecutionEnvelope): number {
  const statusDiff = RUN_STATUS_ORDER[left.status] - RUN_STATUS_ORDER[right.status];
  if (statusDiff !== 0) {
    return statusDiff;
  }
  const createdDiff = Date.parse(right.createdAt) - Date.parse(left.createdAt);
  if (Number.isFinite(createdDiff) && createdDiff !== 0) {
    return createdDiff;
  }
  return left.id.localeCompare(right.id);
}

export function createAutomationRunsPagePresentation(
  mergedRuns: Ref<RpaRunExecutionEnvelope[]>,
  t: Translate,
  locale: Readonly<{ value: unknown }>,
  fallbackLocale: Readonly<{ value: unknown }>,
) {
  const notAvailableValue = computed(() => t("automation.runs.list.notAvailable"));

  const sortedRuns = computed<RpaRunExecutionEnvelope[]>(() =>
    [...mergedRuns.value].sort(compareRunsForSort),
  );

  const formatDate = (value: string): string => {
    const formattedDate = formatDateWithLocale(
      value,
      locale.value,
      fallbackLocale.value,
      DATE_FORMAT_OPTIONS,
    );
    return formattedDate ?? value;
  };

  const formatRunType = (runType: AutomationRunType): string =>
    t(`automation.runs.typeOptions.${runType}`);
  const formatRunStatus = (runStatus: AutomationRunStatus): string =>
    t(`automation.runs.statusOptions.${runStatus}`);

  const resolveJobIdLabel = (run: RpaRunExecutionEnvelope): string | undefined =>
    typeof run.jobId === "string" && run.jobId.trim().length > 0 ? run.jobId : undefined;

  const resolveInputLabel = (input: unknown): string | undefined => {
    if (!isRecord(input)) {
      return undefined;
    }
    if (typeof input.jobUrl === "string" && input.jobUrl.trim().length > 0) {
      return URL.canParse(input.jobUrl) ? new URL(input.jobUrl).hostname : input.jobUrl;
    }
    if (typeof input.target === "string" && input.target.trim().length > 0) {
      return input.target;
    }
    return undefined;
  };

  const resolveOutputLabel = (output: unknown): string | undefined => {
    if (!isRecord(output) || typeof output.scraped !== "number") {
      return undefined;
    }
    return String(output.scraped);
  };

  const formatRunJobLabel = (run: RpaRunExecutionEnvelope): string =>
    resolveJobIdLabel(run) ??
    resolveInputLabel(run.input) ??
    resolveOutputLabel(run.output) ??
    t("automation.runs.emptyJobId");

  const formatRunProgress = (run: RpaRunExecutionEnvelope): string => {
    if (typeof run.progress === "number" && Number.isFinite(run.progress)) {
      return `${Math.max(0, Math.min(PERCENT_MAX, Math.round(run.progress)))}%`;
    }
    return notAvailableValue.value;
  };

  const resolveRowClass = (run: RpaRunExecutionEnvelope): Record<string, boolean> => ({
    "bg-base-200": isLiveAutomationRun(run),
  });

  return {
    sortedRuns,
    formatDate,
    formatRunType,
    formatRunStatus,
    formatRunJobLabel,
    formatRunProgress,
    resolveRowClass,
  };
}

import {
  AUTOMATION_RUN_STATUSES,
  AUTOMATION_RUN_TYPES,
  type AutomationRunStatus,
  type AutomationRunType,
} from "@bao/shared/constants/automation";
import { computed, ref, watch } from "vue";
import type { useI18n } from "vue-i18n";
import { useAutomation } from "~/composables/useAutomation";
import { getErrorMessage } from "~/utils/errors";

type RunFilterType = "" | AutomationRunType;
type RunFilterStatus = "" | AutomationRunStatus;
type Translate = ReturnType<typeof useI18n>["t"];

export function createAutomationRunsPageQuery(t: Translate) {
  const statusFilter = ref<RunFilterStatus>("");
  const typeFilter = ref<RunFilterType>("");
  const { fetchRuns, subscribeToRun } = useAutomation();

  const typeOptions = computed(() => {
    const options: Array<{ value: AutomationRunType; label: string }> = [];
    for (const runType of AUTOMATION_RUN_TYPES) {
      options.push({
        value: runType,
        label: t(`automation.runs.typeOptions.${runType as string}`),
      });
    }
    return options;
  });
  const statusOptions = computed(() => {
    const options: Array<{ value: AutomationRunStatus; label: string }> = [];
    for (const runStatus of AUTOMATION_RUN_STATUSES) {
      options.push({
        value: runStatus,
        label: t(`automation.runs.statusOptions.${runStatus as string}`),
      });
    }
    return options;
  });

  const query = computed(() => {
    const params: { type?: AutomationRunType; status?: AutomationRunStatus } = {};
    if (statusFilter.value) {
      params.status = statusFilter.value;
    }
    if (typeFilter.value) {
      params.type = typeFilter.value;
    }
    return params;
  });

  const { data: runs, status: runFetchStatus, error, refresh } = fetchRuns(query);
  watch(query, () => {
    refresh().then(
      () => undefined,
      () => undefined,
    );
  });

  const isLoading = computed(() => runFetchStatus.value === "pending");
  const errorMessage = computed(() =>
    error.value ? getErrorMessage(error.value, t("automation.runs.loadErrorFallback")) : "",
  );

  return {
    statusFilter,
    typeFilter,
    typeOptions,
    statusOptions,
    runs,
    subscribeToRun,
    isLoading,
    error,
    errorMessage,
    refresh,
  };
}

import type { RpaRunEvent, RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import { computed, type Ref, ref, watch } from "vue";
import {
  isLiveAutomationRun,
  mergeAutomationRunWithEvent,
} from "~/composables/automation-runs-page-merge";

type SubscribeToRun = (runId: string, onEvent: (event: RpaRunEvent) => void) => () => void;

export function createAutomationRunsLiveState(
  runs: Ref<RpaRunExecutionEnvelope[] | null | undefined>,
  subscribeToRun: SubscribeToRun,
) {
  const activeSubscriptions = new Map<string, () => void>();
  const liveRunById = ref<Record<string, RpaRunExecutionEnvelope>>({});

  const unsubscribeRun = (runId: string): void => {
    const unsubscribe = activeSubscriptions.get(runId);
    if (!unsubscribe) {
      return;
    }
    unsubscribe();
    activeSubscriptions.delete(runId);
  };

  const clearSubscriptions = (): void => {
    for (const [runId, unsubscribe] of activeSubscriptions.entries()) {
      unsubscribe();
      activeSubscriptions.delete(runId);
    }
  };

  const subscribeRun = (run: RpaRunExecutionEnvelope): void => {
    if (!isLiveAutomationRun(run) || activeSubscriptions.has(run.id)) {
      return;
    }
    const unsubscribe = subscribeToRun(run.id, (event) => {
      const currentRun =
        liveRunById.value[event.runId] ||
        runs.value?.find((candidate) => candidate.id === event.runId);
      if (!currentRun) {
        return;
      }
      const mergedRun = mergeAutomationRunWithEvent(currentRun, event);
      liveRunById.value = {
        ...liveRunById.value,
        [event.runId]: mergedRun,
      };
      if (!isLiveAutomationRun(mergedRun)) {
        unsubscribeRun(event.runId);
      }
    });
    activeSubscriptions.set(run.id, unsubscribe);
  };

  const mergedRuns = computed<RpaRunExecutionEnvelope[]>(() => {
    const rows: RpaRunExecutionEnvelope[] = [];
    for (const run of runs.value || []) {
      rows.push(liveRunById.value[run.id] || run);
    }
    return rows;
  });

  watch(
    mergedRuns,
    (nextRuns) => {
      const liveRunIds = new Set<string>();
      for (const nextRun of nextRuns) {
        if (isLiveAutomationRun(nextRun)) {
          liveRunIds.add(nextRun.id);
        }
      }
      for (const runId of activeSubscriptions.keys()) {
        if (!liveRunIds.has(runId)) {
          unsubscribeRun(runId);
        }
      }
      for (const nextRun of nextRuns) {
        subscribeRun(nextRun);
      }
    },
    { immediate: true },
  );

  return {
    mergedRuns,
    clearSubscriptions,
  };
}

import {
  type AutomationScrapeTarget,
  automationScrapeTargetToPortalId,
  isAutomationJobScrapeTarget,
} from "@bao/shared/constants/automation";
import type { Ref } from "vue";
import type { ComposerTranslation } from "vue-i18n";
import type { Router } from "vue-router";
import type { NuxtApp } from "#app";
import { settlePromise } from "~/composables/async-flow";
import { toIsoTimestamp } from "~/composables/schedule-timestamp";
import { useApi } from "~/composables/useApi";
import type { AutomationRunEnvelope, ScrapePendingAction } from "~/types/automation-scraper";
import { getErrorMessage } from "~/utils/errors";
import { buildInterviewJobNavigation } from "~/utils/interview-navigation";
import { isFailedScrapeRun, readScrapeOutputErrors } from "~/utils/scrape-run-output";

async function syncDirectScraperCatalog(target: AutomationScrapeTarget): Promise<void> {
  const api = useApi();
  if (target === "studios") {
    await api.scraper.studios.post();
    return;
  }
  if (!isAutomationJobScrapeTarget(target)) {
    return;
  }
  const portalId = automationScrapeTargetToPortalId(target);
  const portalRoute = api.scraper.jobs[portalId];
  if (portalRoute && typeof portalRoute.post === "function") {
    await portalRoute.post();
  }
}

type AutomationScraperActionsInput = {
  awardForAction: (action: "scraperStudios" | "scraperJobs") => Promise<{
    awarded: boolean;
    amount: number;
  }>;
  lastRunAt: Record<AutomationScrapeTarget, string | null>;
  latestRuns: Record<AutomationScrapeTarget, AutomationRunEnvelope | null>;
  pendingAction: Ref<ScrapePendingAction | null>;
  refreshCapabilityAudit: () => Promise<unknown>;
  refreshScraperJobs: () => Promise<unknown>;
  runMessages: Record<AutomationScrapeTarget, string>;
  runStates: Record<AutomationScrapeTarget, "idle" | "running" | "success" | "error">;
  scheduleScrape: (input: {
    target: AutomationScrapeTarget;
    runAt: string;
  }) => Promise<AutomationRunEnvelope>;
  scheduledRunAt: Record<AutomationScrapeTarget, string>;
  triggerScrape: (input: { target: AutomationScrapeTarget }) => Promise<AutomationRunEnvelope>;
};

type AutomationScraperRunStateStore = Pick<
  AutomationScraperActionsInput,
  "latestRuns" | "pendingAction" | "runMessages" | "runStates"
>;

type AutomationScraperSuccessStore = Pick<
  AutomationScraperActionsInput,
  "lastRunAt" | "latestRuns" | "runMessages" | "runStates"
>;

type AutomationScraperRefreshInput = Pick<
  AutomationScraperActionsInput,
  "refreshCapabilityAudit" | "refreshScraperJobs"
> & {
  target: AutomationScrapeTarget;
};

function createScheduleScrapeRun(input: AutomationScraperActionsInput, t: ComposerTranslation) {
  return async (target: AutomationScrapeTarget): Promise<void> => {
    const runAt = toIsoTimestamp(input.scheduledRunAt[target]);
    if (!runAt) {
      input.runStates[target] = "error";
      input.runMessages[target] = t("automation.scraper.schedule.invalidRunAt");
      return;
    }

    input.pendingAction.value = `${target}-schedule`;
    input.latestRuns[target] = null;
    const scheduleResult = await settlePromise(
      input.scheduleScrape({ target, runAt }),
      t("automation.scraper.errors.scheduleFailed"),
    );
    input.pendingAction.value = null;

    if (!scheduleResult.ok) {
      input.runStates[target] = "error";
      input.runMessages[target] = getErrorMessage(
        scheduleResult.error,
        t("automation.scraper.errors.scheduleFailed"),
      );
      return;
    }

    input.runStates[target] = "success";
    input.runMessages[target] = t("automation.scraper.schedule.createdMessage");
    input.latestRuns[target] = scheduleResult.value;
  };
}

function createRunScrapeTarget(
  input: AutomationScraperActionsInput,
  rewardResolver: ReturnType<typeof createPipelineRewardResolver>,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;
  const runStateStore = {
    lastRunAt: input.lastRunAt,
    latestRuns: input.latestRuns,
    pendingAction: input.pendingAction,
    runMessages: input.runMessages,
    runStates: input.runStates,
  };

  return async (target: AutomationScrapeTarget): Promise<void> => {
    const failureKey = resolveRunFailureKey(target);
    prepareManualRun(target, runStateStore);
    const runResult = await settlePromise(input.triggerScrape({ target }), t(failureKey));
    input.pendingAction.value = null;

    if (!runResult.ok) {
      applyRunFailure({ error: runResult.error, failureKey, target }, runStateStore, t);
      return;
    }

    const completedRun = runResult.value;
    // Dual fabric: RPA run + Eden scraper portal sync for catalog freshness.
    await settlePromise(syncDirectScraperCatalog(target), t(failureKey));
    await refreshManualRunArtifacts({
      refreshCapabilityAudit: input.refreshCapabilityAudit,
      refreshScraperJobs: input.refreshScraperJobs,
      target,
    });
    const scrapeFailed = isFailedScrapeRun({
      aborted: completedRun.aborted,
      exitCode: completedRun.exitCode,
      output: completedRun.output,
      timedOut: completedRun.timedOut,
    });
    const reward = scrapeFailed ? null : await rewardResolver(resolveRewardAction(target));
    applyRunSuccess({ completedRun, reward, target }, runStateStore, t);
    if (reward) {
      $toast.success(t(resolveRewardToastKey(target), { xp: reward }));
    }
  };
}

export function useAutomationScraperActions(
  input: AutomationScraperActionsInput,
  router: Router,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const rewardResolver = createPipelineRewardResolver(input.awardForAction, t);
  const scheduleScrapeRun = createScheduleScrapeRun(input, t);
  const runScrapeTarget = createRunScrapeTarget(input, rewardResolver, nuxtApp, t);

  function isPendingAction(target: AutomationScrapeTarget, action: "run" | "schedule"): boolean {
    return input.pendingAction.value === `${target}-${action}`;
  }

  async function startJobInterview(jobId: string): Promise<void> {
    await router.push(buildInterviewJobNavigation(jobId, "scraper"));
  }

  return {
    isPendingAction,
    runScrapeTarget,
    scheduleScrapeRun,
    startJobInterview,
  };
}

function resolveRunFailureKey(target: AutomationScrapeTarget): string {
  return target === "studios"
    ? "automation.scraper.errors.studioFailed"
    : "automation.scraper.errors.jobFailed";
}

function resolveRewardAction(target: AutomationScrapeTarget): "scraperStudios" | "scraperJobs" {
  return target === "studios" ? "scraperStudios" : "scraperJobs";
}

function resolveRewardToastKey(target: AutomationScrapeTarget): string {
  return target === "studios"
    ? "automation.scraper.toasts.studioReward"
    : "automation.scraper.toasts.jobReward";
}

function resolveCompletionMessageKey(target: AutomationScrapeTarget, hasReward: boolean): string {
  if (target === "studios") {
    return hasReward
      ? "automation.scraper.messages.studioCompletedWithXp"
      : "automation.scraper.messages.studioCompleted";
  }
  return hasReward
    ? "automation.scraper.messages.jobCompletedWithXp"
    : "automation.scraper.messages.jobCompleted";
}

function prepareManualRun(
  target: AutomationScrapeTarget,
  { latestRuns, pendingAction, runMessages, runStates }: AutomationScraperRunStateStore,
): void {
  runStates[target] = "running";
  runMessages[target] = "";
  latestRuns[target] = null;
  pendingAction.value = `${target}-run`;
}

function applyRunFailure(
  {
    error,
    failureKey,
    target,
  }: { error: unknown; failureKey: string; target: AutomationScrapeTarget },
  { runMessages, runStates }: Pick<AutomationScraperActionsInput, "runMessages" | "runStates">,
  t: ComposerTranslation,
): void {
  runStates[target] = "error";
  runMessages[target] = getErrorMessage(error, t(failureKey));
}

async function refreshManualRunArtifacts({
  refreshCapabilityAudit,
  refreshScraperJobs,
  target,
}: AutomationScraperRefreshInput): Promise<void> {
  if (target !== "studios") {
    await refreshScraperJobs();
  }
  await refreshCapabilityAudit();
}

function applyRunSuccess(
  {
    completedRun,
    reward,
    target,
  }: { completedRun: AutomationRunEnvelope; reward: number | null; target: AutomationScrapeTarget },
  { lastRunAt, latestRuns, runMessages, runStates }: AutomationScraperSuccessStore,
  t: ComposerTranslation,
): void {
  lastRunAt[target] = completedRun.completedAt ?? completedRun.updatedAt;
  latestRuns[target] = completedRun;

  const failed = isFailedScrapeRun({
    aborted: completedRun.aborted,
    exitCode: completedRun.exitCode,
    output: completedRun.output,
    timedOut: completedRun.timedOut,
  });
  if (failed) {
    runStates[target] = "error";
    const outputErrors = readScrapeOutputErrors(completedRun.output);
    const envelopeError = typeof completedRun.error === "string" ? completedRun.error : null;
    runMessages[target] = outputErrors[0] ?? envelopeError ?? t(resolveRunFailureKey(target));
    return;
  }

  runStates[target] = "success";
  const messageKey = resolveCompletionMessageKey(target, reward !== null);
  runMessages[target] = reward === null ? t(messageKey) : t(messageKey, { xp: reward });
}

function createPipelineRewardResolver(
  awardForAction: (action: "scraperStudios" | "scraperJobs") => Promise<{
    awarded: boolean;
    amount: number;
  }>,
  t: ComposerTranslation,
) {
  return async (action: "scraperStudios" | "scraperJobs"): Promise<number | null> => {
    const rewardResult = await settlePromise(
      awardForAction(action),
      t("automation.scraper.errors.rewardFailed"),
    );
    if (!rewardResult.ok) {
      return null;
    }
    return rewardResult.value.awarded ? rewardResult.value.amount : null;
  };
}

import {
  AUTOMATION_SCRAPE_TARGETS,
  type RpaCapabilityAuditEntry,
  type RpaCapabilityAuditReport,
} from "@bao/shared/constants/automation";
import { SCRAPER_JOB_QUERY_LIMIT } from "@bao/shared/constants/interview";
import type {
  AutomationRunEnvelope,
  AutomationScraperRunState,
  ScrapeCapabilityCard,
  ScrapePendingAction,
  TargetRecord,
} from "~/types/automation-scraper";

export const RUN_STATE_BADGE_CLASS: Record<AutomationScraperRunState, string> = {
  idle: "badge-ghost",
  running: "badge-info",
  success: "badge-success",
  error: "badge-error",
};

const createTargetRecord = <TValue>(factory: () => TValue): TargetRecord<TValue> => {
  const entries = AUTOMATION_SCRAPE_TARGETS.map((target) => [target, factory()] as const);
  return Object.fromEntries(entries) as TargetRecord<TValue>;
};

export const isScrapeCapabilityCard = (
  capability: RpaCapabilityAuditEntry,
): capability is ScrapeCapabilityCard =>
  capability.category === "scrape" && capability.target !== null;

type AutomationScraperBootstrapInput = {
  getRpaCapabilities: () => Promise<RpaCapabilityAuditReport>;
  searchJobs: (input: { limit: string }) => Promise<void>;
};

export function useAutomationScraperBootstrap({
  getRpaCapabilities,
  searchJobs,
}: AutomationScraperBootstrapInput) {
  const runStates = reactive(createTargetRecord<AutomationScraperRunState>(() => "idle"));
  const runMessages = reactive(createTargetRecord<string>(() => ""));
  const lastRunAt = reactive(createTargetRecord<string | null>(() => null));
  const scheduledRunAt = reactive(createTargetRecord<string>(() => ""));
  const latestRuns = reactive(createTargetRecord<AutomationRunEnvelope | null>(() => null));
  const pendingAction = ref<ScrapePendingAction | null>(null);

  const {
    data: capabilityAuditData,
    status: capabilityAuditStatus,
    error: capabilityAuditError,
    refresh: refreshCapabilityAudit,
  } = useAsyncData<RpaCapabilityAuditReport>(
    "automation-scraper-capabilities",
    () => getRpaCapabilities(),
    {
      lazy: false,
      server: true,
    },
  );

  const {
    status: scraperJobsStatus,
    error: scraperJobsError,
    refresh: refreshScraperJobs,
  } = useAsyncData("automation-scraper-jobs", async () => {
    await searchJobs({ limit: String(SCRAPER_JOB_QUERY_LIMIT) });
    return true;
  });

  const scraperJobsPending = computed(
    () => scraperJobsStatus.value === "pending" || scraperJobsStatus.value === "idle",
  );

  return {
    capabilityAuditData,
    capabilityAuditError,
    capabilityAuditStatus,
    lastRunAt,
    latestRuns,
    pendingAction,
    refreshCapabilityAudit,
    refreshScraperJobs,
    runMessages,
    runStates,
    scheduledRunAt,
    scraperJobsError,
    scraperJobsPending,
    scraperJobsStatus,
  };
}

import type {
  AutomationScrapeTarget,
  RpaCapabilityAuditReport,
} from "@bao/shared/constants/automation";
import { JOB_PREVIEW_LIMIT } from "@bao/shared/constants/interview";
import type { Ref } from "vue";
import type { ComposerTranslation } from "vue-i18n";
import { isScrapeCapabilityCard } from "~/composables/automation-scraper-bootstrap";
import {
  createAutomationPresentation,
  createAutomationSummaryStats,
} from "~/composables/automation-scraper-presentation";
import type {
  AutomationRunEnvelope,
  AutomationScraperRunState,
  ScrapeCapabilityCard,
} from "~/types/automation-scraper";

type AutomationScraperJobView = {
  readonly id: string;
  readonly title: string;
  readonly company: string;
  readonly location: string;
  readonly postedDate: string;
  readonly enrichment?: {
    readonly summary?: string;
    readonly interviewFocusAreas: readonly string[];
  };
};

type AutomationScraperDerivedInput = {
  capabilityAuditData: Ref<RpaCapabilityAuditReport | null | undefined>;
  fallbackLocale: Ref<unknown>;
  jobs: Ref<readonly AutomationScraperJobView[]>;
  lastRunAt: Record<AutomationScrapeTarget, string | null>;
  latestRuns: Record<AutomationScrapeTarget, AutomationRunEnvelope | null>;
  locale: Ref<string>;
  runStates: Record<AutomationScrapeTarget, AutomationScraperRunState>;
};

function useAutomationJobFeedDerived(jobs: Ref<readonly AutomationScraperJobView[]>) {
  const sortedJobs = computed(() => {
    const rows = [...jobs.value];
    rows.sort((left, right) => {
      const leftTime = new Date(left.postedDate).getTime();
      const rightTime = new Date(right.postedDate).getTime();
      return rightTime - leftTime;
    });
    return rows;
  });

  return {
    enrichedJobCount: computed(
      () => sortedJobs.value.filter((job) => typeof job.enrichment?.summary === "string").length,
    ),
    jobCount: computed(() => sortedJobs.value.length),
    topJobs: computed(() => sortedJobs.value.slice(0, JOB_PREVIEW_LIMIT)),
  };
}

function useAutomationCapabilityDerived(
  capabilityAuditData: Ref<RpaCapabilityAuditReport | null | undefined>,
  runStates: Record<AutomationScrapeTarget, AutomationScraperRunState>,
) {
  const capabilityAudit = computed(() => capabilityAuditData.value ?? null);
  const scrapeCapabilities = computed<readonly ScrapeCapabilityCard[]>(() =>
    (capabilityAudit.value?.capabilities ?? []).filter(isScrapeCapabilityCard),
  );

  return {
    availableManualRunCount: computed(
      () => scrapeCapabilities.value.filter((capability) => capability.manualRunAvailable).length,
    ),
    configuredCapabilityCount: computed(
      () => scrapeCapabilities.value.filter((capability) => capability.configured).length,
    ),
    overallJobState: computed<AutomationScraperRunState>(() => {
      const jobTargets = scrapeCapabilities.value.filter(
        (capability) => capability.target !== "studios",
      );
      if (jobTargets.some((capability) => runStates[capability.target] === "running")) {
        return "running";
      }
      if (jobTargets.some((capability) => runStates[capability.target] === "error")) {
        return "error";
      }
      if (jobTargets.some((capability) => runStates[capability.target] === "success")) {
        return "success";
      }
      return "idle";
    }),
    scrapeCapabilities,
  };
}

export function useAutomationScraperDerived(
  {
    capabilityAuditData,
    fallbackLocale,
    jobs,
    lastRunAt,
    latestRuns,
    locale,
    runStates,
  }: AutomationScraperDerivedInput,
  t: ComposerTranslation,
) {
  const jobFeed = useAutomationJobFeedDerived(jobs);
  const capabilityState = useAutomationCapabilityDerived(capabilityAuditData, runStates);
  const presentation = createAutomationPresentation(
    { fallbackLocale, lastRunAt, latestRuns, locale },
    t,
  );
  const summaryStats = createAutomationSummaryStats(capabilityState, jobFeed, presentation);

  return {
    availableManualRunCount: capabilityState.availableManualRunCount,
    capabilityAvailabilityBadgeClass: (capability: ScrapeCapabilityCard) =>
      presentation.capabilityAvailabilityBadgeClass(capability),
    capabilityAvailabilityLabel: (capability: ScrapeCapabilityCard) =>
      presentation.capabilityAvailabilityLabel(capability),
    cardDescription: (target: AutomationScrapeTarget) => presentation.cardDescription(target),
    cardRunAria: (target: AutomationScrapeTarget) => presentation.cardRunAria(target),
    cardRunButtonLabel: (target: AutomationScrapeTarget) => presentation.cardRunButtonLabel(target),
    configuredCapabilityCount: capabilityState.configuredCapabilityCount,
    hasJobEnrichment: (job: AutomationScraperJobView) => presentation.hasJobEnrichment(job),
    jobCount: jobFeed.jobCount,
    jobInterviewFocusAreas: (job: AutomationScraperJobView) =>
      presentation.jobInterviewFocusAreas(job),
    latestRunNoticeText: (target: AutomationScrapeTarget) =>
      presentation.latestRunNoticeText(target),
    latestRunStatusText: (target: AutomationScrapeTarget) =>
      presentation.latestRunStatusText(target),
    relativePostedDate: (date: string) => presentation.relativePostedDate(date),
    runStateBadgeClass: (state: AutomationScraperRunState) =>
      presentation.runStateBadgeClass(state),
    runStateLabel: (state: AutomationScraperRunState) => presentation.runStateLabel(state),
    scrapeCapabilities: capabilityState.scrapeCapabilities,
    summaryStats,
    topJobs: jobFeed.topJobs,
  };
}

import type { AutomationScrapeTarget } from "@bao/shared/constants/automation";
import { formatRelativeTimeForDate } from "@bao/shared/utils/date-helpers";
import type { ComputedRef, Ref } from "vue";
import type { ComposerTranslation } from "vue-i18n";
import { RUN_STATE_BADGE_CLASS } from "~/composables/automation-scraper-bootstrap";
import { DATE_FORMAT_OPTIONS, resolveScheduledRunAt } from "~/composables/schedule-timestamp";
import type {
  AutomationRunEnvelope,
  AutomationScraperRunState,
  AutomationScraperSummaryStat,
  ScrapeCapabilityCard,
} from "~/types/automation-scraper";
import { formatDateWithLocale } from "~/utils/locale-format";

function createAutomationDateFormatting(
  input: {
    fallbackLocale: Ref<unknown>;
    locale: Ref<string>;
  },
  t: ComposerTranslation,
) {
  const formatRunTime = (value: string | null): string => {
    if (!value) {
      return t("automation.scraper.notRunYet");
    }

    const formattedDate = formatDateWithLocale(
      value,
      input.locale.value,
      input.fallbackLocale.value,
      DATE_FORMAT_OPTIONS,
    );
    return formattedDate ?? t("automation.scraper.notRunYet");
  };

  const toLocalizedDateTime = (value: string): string => {
    const formattedDate = formatDateWithLocale(
      value,
      input.locale.value,
      input.fallbackLocale.value,
      DATE_FORMAT_OPTIONS,
    );
    return formattedDate ?? value;
  };

  return {
    formatRunTime,
    toLocalizedDateTime,
  };
}

function createCapabilityPresentation(t: ComposerTranslation) {
  return {
    capabilityAvailabilityBadgeClass(capability: ScrapeCapabilityCard): string {
      if (capability.configured) {
        return "badge-success";
      }
      if (capability.enabled) {
        return "badge-warning";
      }
      return "badge-error";
    },
    capabilityAvailabilityLabel(capability: ScrapeCapabilityCard): string {
      if (capability.configured) {
        return t("automation.hub.audit.available");
      }
      if (capability.enabled) {
        return t("automation.hub.audit.needsConfig");
      }
      return t("automation.hub.audit.unavailable");
    },
  };
}

function createScraperCardPresentation(t: ComposerTranslation) {
  return {
    cardDescription(target: AutomationScrapeTarget): string {
      return target === "studios"
        ? t("automation.scraper.studioCard.description")
        : t("automation.scraper.jobCard.description");
    },
    cardRunAria(target: AutomationScrapeTarget): string {
      return target === "studios"
        ? t("automation.scraper.studioCard.runAria")
        : t("automation.scraper.jobCard.runAria");
    },
    cardRunButtonLabel(target: AutomationScrapeTarget): string {
      return target === "studios"
        ? t("automation.scraper.studioCard.runButton")
        : t("automation.scraper.jobCard.runButton");
    },
  };
}

function createJobPresentation() {
  return {
    hasJobEnrichment(job: {
      readonly enrichment?: {
        readonly summary?: string;
        readonly interviewFocusAreas: readonly string[];
      };
    }): boolean {
      return typeof job.enrichment?.summary === "string" && job.enrichment.summary.length > 0;
    },
    jobInterviewFocusAreas(job: {
      readonly enrichment?: {
        readonly summary?: string;
        readonly interviewFocusAreas: readonly string[];
      };
    }): string[] {
      return [...(job.enrichment?.interviewFocusAreas.slice(0, 2) ?? [])];
    },
  };
}

function createAutomationRunPresentation(
  input: {
    lastRunAt: Record<AutomationScrapeTarget, string | null>;
    latestRuns: Record<AutomationScrapeTarget, AutomationRunEnvelope | null>;
  },
  formatting: ReturnType<typeof createAutomationDateFormatting>,
  t: ComposerTranslation,
) {
  return {
    latestRunNoticeText(target: AutomationScrapeTarget): string {
      const run = input.latestRuns[target];
      if (!run) {
        return "";
      }
      if (run.status === "pending") {
        return t("automation.scraper.schedule.scheduledForLabel", {
          date: formatting.toLocalizedDateTime(resolveScheduledRunAt(run)),
        });
      }
      return t("automation.scraper.lastRunLabel", {
        value: formatting.formatRunTime(input.lastRunAt[target]),
      });
    },
    latestRunStatusText(target: AutomationScrapeTarget): string {
      const run = input.latestRuns[target];
      if (!run) {
        return "";
      }
      return t("automation.scraper.schedule.statusLabel", {
        status: run.status,
      });
    },
    relativePostedDate(date: string): string {
      return formatRelativeTimeForDate(date, t);
    },
    runStateBadgeClass(state: AutomationScraperRunState): string {
      return RUN_STATE_BADGE_CLASS[state];
    },
    runStateLabel(state: AutomationScraperRunState): string {
      if (state === "running") return t("automation.scraper.state.running");
      if (state === "success") return t("automation.scraper.state.success");
      if (state === "error") return t("automation.scraper.state.error");
      return t("automation.scraper.state.idle");
    },
  };
}

export function createAutomationPresentation(
  input: {
    fallbackLocale: Ref<unknown>;
    lastRunAt: Record<AutomationScrapeTarget, string | null>;
    latestRuns: Record<AutomationScrapeTarget, AutomationRunEnvelope | null>;
    locale: Ref<string>;
  },
  t: ComposerTranslation,
) {
  const formatting = createAutomationDateFormatting(input, t);

  return {
    ...createCapabilityPresentation(t),
    ...createScraperCardPresentation(t),
    ...createJobPresentation(),
    ...createAutomationRunPresentation(input, formatting, t),
  };
}

export function createAutomationSummaryStats(
  capabilityState: {
    scrapeCapabilities: ComputedRef<readonly ScrapeCapabilityCard[]>;
    configuredCapabilityCount: ComputedRef<number>;
    overallJobState: ComputedRef<AutomationScraperRunState>;
  },
  jobFeed: {
    jobCount: ComputedRef<number>;
    enrichedJobCount: ComputedRef<number>;
  },
  presentation: Pick<ReturnType<typeof createAutomationPresentation>, "runStateLabel">,
) {
  return computed<readonly AutomationScraperSummaryStat[]>(() => [
    {
      titleKey: "automation.hub.audit.summary.total",
      value: capabilityState.scrapeCapabilities.value.length,
      valueClass: "text-primary",
      descKey: "automation.hub.audit.summary.totalDesc",
    },
    {
      titleKey: "automation.hub.audit.summary.configured",
      value: capabilityState.configuredCapabilityCount.value,
      valueClass: "text-secondary",
      descKey: "automation.hub.audit.summary.configuredDesc",
    },
    {
      titleKey: "automation.scraper.stats.availableJobsTitle",
      value: jobFeed.jobCount.value,
      valueClass: "text-primary",
      descKey: "automation.scraper.stats.availableJobsDescription",
    },
    {
      titleKey: "automation.scraper.stats.enrichedJobsTitle",
      value: jobFeed.enrichedJobCount.value,
      valueClass: "text-secondary",
      descKey: "automation.scraper.stats.enrichedJobsDescription",
    },
    {
      titleKey: "automation.scraper.stats.jobStatusTitle",
      value: presentation.runStateLabel(capabilityState.overallJobState.value),
      valueClass: "text-base-content",
      descKey: "automation.scraper.stats.jobStatusDescription",
    },
  ]);
}

import { API_ERROR_AI_STREAMING_FAILED } from "@bao/shared/constants/api-errors";
import { WS_ENDPOINTS } from "@bao/shared/constants/endpoints";
import { safeParseJson } from "@bao/shared/utils/json";
import { resolveWebSocketEndpoint } from "~/utils/endpoints";

const CHAT_WS_CONNECTION_FAILED = "chat_ws_connection_failed";
const CHAT_WS_CLOSED_EARLY = "chat_ws_closed_early";

type ChatSocketPayload = {
  type?: string;
  chunk?: string;
  sessionId?: string;
  message?: string;
};

export type ChatRealtimeStreamResult = {
  fullText: string;
  sessionId: string;
};

export type ChatRealtimeStreamInput = {
  content: string;
  sessionId: string;
  onChunk: (chunk: string) => void;
  onSessionId: (sessionId: string) => void;
};

type StreamSession = {
  fullText: string;
  activeSessionId: string;
  settled: boolean;
  finish: (result: ChatRealtimeStreamResult) => void;
  fail: (reason: string) => void;
};

function createStreamSession(
  initialSessionId: string,
  socket: WebSocket,
  resolve: (result: ChatRealtimeStreamResult) => void,
  reject: (reason: Error) => void,
): StreamSession {
  const session: StreamSession = {
    fullText: "",
    activeSessionId: initialSessionId,
    settled: false,
    finish: (result) => {
      if (session.settled) {
        return;
      }
      session.settled = true;
      socket.close();
      resolve(result);
    },
    fail: (reason) => {
      if (session.settled) {
        return;
      }
      session.settled = true;
      socket.close();
      reject(new Error(reason));
    },
  };
  return session;
}

function handleChatSocketMessage(
  event: MessageEvent,
  input: ChatRealtimeStreamInput,
  session: StreamSession,
): void {
  if (typeof event.data !== "string") {
    return;
  }
  const payload = safeParseJson(event.data) as ChatSocketPayload | null;
  if (!payload || typeof payload !== "object") {
    return;
  }
  if (typeof payload.sessionId === "string" && payload.sessionId.length > 0) {
    session.activeSessionId = payload.sessionId;
    input.onSessionId(payload.sessionId);
  }
  switch (payload.type) {
    case "stream_chunk": {
      if (typeof payload.chunk === "string" && payload.chunk.length > 0) {
        session.fullText += payload.chunk;
        input.onChunk(payload.chunk);
      }
      break;
    }
    case "stream_end": {
      session.finish({ fullText: session.fullText, sessionId: session.activeSessionId });
      break;
    }
    case "error": {
      const remoteMessage =
        typeof payload.message === "string" && payload.message.trim().length > 0
          ? payload.message
          : API_ERROR_AI_STREAMING_FAILED;
      session.fail(remoteMessage);
      break;
    }
    default:
      break;
  }
}

/**
 * Opens chat WS and resolves when stream_end arrives (or rejects on error/close).
 */
export function openChatRealtimeStream(
  wsBase: string,
  requestUrl: URL,
  input: ChatRealtimeStreamInput,
): Promise<ChatRealtimeStreamResult> {
  return new Promise((resolve, reject) => {
    const url = resolveWebSocketEndpoint(wsBase, requestUrl, WS_ENDPOINTS.chat);
    const socket = new WebSocket(url);
    const session = createStreamSession(input.sessionId, socket, resolve, reject);

    socket.onopen = () => {
      socket.send(
        JSON.stringify({
          content: input.content,
          sessionId: input.sessionId,
        }),
      );
    };
    socket.onmessage = (event) => {
      handleChatSocketMessage(event, input, session);
    };
    socket.onerror = () => {
      session.fail(CHAT_WS_CONNECTION_FAILED);
    };
    socket.onclose = () => {
      if (!session.settled) {
        session.fail(CHAT_WS_CLOSED_EARLY);
      }
    };
  });
}

import {
  COVER_LETTER_COMPANY_MIN_LENGTH,
  COVER_LETTER_POSITION_MIN_LENGTH,
} from "@bao/shared/constants/cover-letter";
import type { CoverLetterData } from "@bao/shared/types/cover-letter";
import type { useI18n } from "vue-i18n";
import { runExportWithToast } from "~/composables/export-with-toast";
import type { CoverLetterDetailFormState } from "~/composables/cover-letter-detail-page-state";
import {
  coverLetterContentToPlainText,
  plainTextToCoverLetterContent,
} from "~/utils/cover-letter-content";

type CoverLetterApi = ReturnType<typeof useCoverLetter>;
type GenerateCoverLetterResult = Awaited<ReturnType<CoverLetterApi["generateCoverLetter"]>>;
type Toast = ReturnType<typeof useNuxtApp>["$toast"];
type Translate = ReturnType<typeof useI18n>["t"];

export type CoverLetterDetailActionDeps = {
  readonly state: CoverLetterDetailFormState;
  readonly api: CoverLetterApi;
  readonly toast: Toast;
  readonly t: Translate;
};

const resolveGeneratedContent = (
  value: Exclude<GenerateCoverLetterResult, null>,
): CoverLetterData["content"] =>
  "content" in value ? value.content : value.coverLetter.content;

const validateRequiredFields = (deps: CoverLetterDetailActionDeps): boolean => {
  const { state, toast, t } = deps;
  if (state.formData.company.trim().length < COVER_LETTER_COMPANY_MIN_LENGTH) {
    toast.error(
      t("coverLetterDetailPage.toasts.companyMinLength", {
        count: COVER_LETTER_COMPANY_MIN_LENGTH,
      }),
    );
    return false;
  }
  if (state.formData.position.trim().length < COVER_LETTER_POSITION_MIN_LENGTH) {
    toast.error(
      t("coverLetterDetailPage.toasts.positionMinLength", {
        count: COVER_LETTER_POSITION_MIN_LENGTH,
      }),
    );
    return false;
  }
  return true;
};

/** Loads the persisted letter into the form model (id from the route). */
export const loadCoverLetter = async (deps: CoverLetterDetailActionDeps): Promise<void> => {
  const { state, api } = deps;
  if (!state.letterId.value) return;

  const loaded = await api.getCoverLetter(state.letterId.value);
  if (loaded) {
    state.applyCoverLetterToForm(loaded);
  }
};

/** Validates, persists, and re-normalizes the letter; toasts the outcome. */
export const saveCoverLetter = async (deps: CoverLetterDetailActionDeps): Promise<void> => {
  const { state, api, toast, t } = deps;
  if (!state.letterId.value) return;
  if (!validateRequiredFields(deps)) return;

  const updated = await api.updateCoverLetter(state.letterId.value, {
    company: state.formData.company.trim(),
    position: state.formData.position.trim(),
    template: state.formData.template,
    content: plainTextToCoverLetterContent(state.formData.contentText),
  });

  if (updated === null) return;

  const normalized = await api.getCoverLetter(state.letterId.value);
  if (normalized) {
    state.applyCoverLetterToForm(normalized);
  }

  state.lastSavedFingerprint.value = state.buildFormFingerprint();
  toast.success(t("coverLetterDetailPage.toasts.saved"));
};

/** Runs AI regeneration and applies the result to the editor buffer. */
export const regenerateCoverLetter = async (
  deps: CoverLetterDetailActionDeps,
): Promise<void> => {
  const { state, api, toast, t } = deps;
  state.regenerating.value = true;
  const regenerated = await api.generateCoverLetter({
    company: state.formData.company.trim(),
    position: state.formData.position.trim(),
    template: state.formData.template,
    save: false,
  });
  state.regenerating.value = false;

  if (regenerated === null) {
    state.showRegenerateDialog.value = false;
    return;
  }

  const regeneratedContent = resolveGeneratedContent(regenerated);
  if (!regeneratedContent) {
    toast.error(t("coverLetterDetailPage.toasts.regenerateMissingContent"));
    state.showRegenerateDialog.value = false;
    return;
  }

  state.formData.contentText = coverLetterContentToPlainText(regeneratedContent);
  toast.success(t("coverLetterDetailPage.toasts.regenerated"));
  state.showRegenerateDialog.value = false;
};

/** Exports the persisted letter, saving dirty edits first so the file matches. */
export const exportCoverLetter = async (
  deps: CoverLetterDetailActionDeps,
  format: "pdf" | "docx",
): Promise<void> => {
  const { state, api, toast, t } = deps;
  const id = state.letterId.value;
  if (!id) {
    return;
  }
  // Export reads DB row — persist dirty template/content first or PDF/DOCX lies.
  if (state.buildFormFingerprint() !== state.lastSavedFingerprint.value) {
    await saveCoverLetter(deps);
    if (state.buildFormFingerprint() !== state.lastSavedFingerprint.value) {
      return;
    }
  }
  await runExportWithToast({
    exportFn: () => api.exportDocument(id, format, state.formData.template),
    failMessage: t("coverLetterDetailPage.toasts.exportFailed"),
    successMessage: t("coverLetterDetailPage.toasts.exported"),
    toast,
    t,
  });
};

import {
  COVER_LETTER_DEFAULT_TEMPLATE,
  type CoverLetterTemplate,
  isCoverLetterTemplate,
} from "@bao/shared/constants/cover-letter";
import { APP_ROUTES } from "@bao/shared/constants/routes";
import type { CoverLetterData } from "@bao/shared/types/cover-letter";
import { useI18n } from "vue-i18n";
import { coverLetterContentToPlainText } from "~/utils/cover-letter-content";

const CONTENT_SECTION_SPLIT = /\n{2,}/u;

export type CoverLetterDetailFormData = {
  company: string;
  position: string;
  template: CoverLetterTemplate;
  contentText: string;
};

/**
 * Core form model for the cover-letter detail page: refs, the persistence
 * fingerprint contract, and mutation helpers.
 */
export const useCoverLetterDetailFormState = () => {
  const route = useRoute();

  const letter = ref<CoverLetterData | null>(null);
  const letterId = computed(() =>
    typeof route.params.id === "string" ? route.params.id : "",
  );
  const regenerating = ref(false);
  const showRegenerateDialog = ref(false);

  const formData = reactive<CoverLetterDetailFormData>({
    company: "",
    position: "",
    template: COVER_LETTER_DEFAULT_TEMPLATE,
    contentText: "",
  });

  const lastSavedFingerprint = ref("");

  function buildFormFingerprint(): string {
    return JSON.stringify({
      company: formData.company.trim(),
      position: formData.position.trim(),
      template: formData.template,
      contentText: formData.contentText.trim(),
    });
  }

  const hasUnsavedChanges = computed(
    () => buildFormFingerprint() !== lastSavedFingerprint.value,
  );

  function applyCoverLetterToForm(value: CoverLetterData): void {
    letter.value = value;
    formData.company = value.company;
    formData.position = value.position;
    formData.template = isCoverLetterTemplate(value.template)
      ? value.template
      : COVER_LETTER_DEFAULT_TEMPLATE;
    formData.contentText = coverLetterContentToPlainText(value.content);
    lastSavedFingerprint.value = buildFormFingerprint();
  }

  return {
    letter,
    letterId,
    regenerating,
    showRegenerateDialog,
    formData,
    lastSavedFingerprint,
    buildFormFingerprint,
    hasUnsavedChanges,
    applyCoverLetterToForm,
  };
};

export type CoverLetterDetailFormState = ReturnType<typeof useCoverLetterDetailFormState>;

/**
 * Derived presentation values for the cover-letter detail page header and stats.
 */
export const useCoverLetterDetailDerived = (formState: CoverLetterDetailFormState) => {
  const { t } = useI18n();
  const { letter, formData } = formState;

  const breadcrumbs = computed(() => [
    { label: t("nav.dashboard"), to: APP_ROUTES.dashboard },
    { label: t("nav.coverLetter"), to: APP_ROUTES.coverLetter },
    { label: letter.value?.position || t("coverLetterDetailPage.breadcrumbFallback") },
  ]);
  const heroTitle = computed(() =>
    t("coverLetterDetailPage.hero.title", {
      position: formData.position.trim() || t("coverLetterDetailPage.breadcrumbFallback"),
      company: formData.company.trim() || t("coverLetterDetailPage.details.companyPlaceholder"),
    }),
  );
  const heroDescription = computed(() => t("coverLetterDetailPage.hero.description"));

  const contentCharacterCount = computed(() => formData.contentText.trim().length);
  const contentSectionCount = computed(() => {
    if (!formData.contentText.trim()) return 0;
    return formData.contentText
      .trim()
      .split(CONTENT_SECTION_SPLIT)
      .map((section) => section.trim())
      .filter((section) => section.length > 0).length;
  });

  function templateLabel(template: CoverLetterTemplate): string {
    return t(`coverLetterDetailPage.templates.${template}`);
  }

  return {
    t,
    breadcrumbs,
    heroTitle,
    heroDescription,
    contentCharacterCount,
    contentSectionCount,
    templateLabel,
  };
};

import {
  COVER_LETTER_COMPANY_MIN_LENGTH,
  COVER_LETTER_DEFAULT_TEMPLATE,
  COVER_LETTER_JOB_DESCRIPTION_MIN_LENGTH,
  COVER_LETTER_POSITION_MIN_LENGTH,
  type CoverLetterTemplate,
} from "@bao/shared/constants/cover-letter";
import { APP_ROUTE_BUILDERS, APP_ROUTE_QUERY_KEYS } from "@bao/shared/constants/routes";
import type { Ref } from "vue";
import { settlePromise } from "~/composables/async-flow";
import { getErrorMessage } from "~/utils/errors";
import { queryValueToString, type RouteQueryValue } from "~/utils/route-query";
import type { GenerateCoverLetterInput, GenerateCoverLetterResult } from "./useCoverLetter";

export type CoverLetterGenerateForm = {
  company: string;
  position: string;
  jobDescription: string;
  resumeId: string;
  template: CoverLetterTemplate;
};

type TranslateFn = (key: string, values?: Record<string, unknown>) => string;
type ToastApi = {
  error(message: string): void;
  success(message: string): void;
};

type CoverLetterPageActionServices = {
  deleteCoverLetter(id: string): Promise<void>;
  generateCoverLetter(payload: GenerateCoverLetterInput): Promise<GenerateCoverLetterResult | null>;
  fetchCoverLetters(): Promise<void>;
  fetchResumes(): Promise<void>;
  router: { push(path: string): Promise<unknown> };
  route: { query: Readonly<Record<string, RouteQueryValue>> };
  $toast: ToastApi;
  t: TranslateFn;
};

type CoverLetterPageActionState = {
  showGenerateModal: Ref<boolean>;
  generating: Ref<boolean>;
  initialResumeId: Ref<string>;
  generateForm: CoverLetterGenerateForm;
  pendingDeleteId: Ref<string | null>;
  closeDeleteDialog(): void;
  searchQuery: Ref<string>;
  templateFilter: Ref<CoverLetterTemplate | "all">;
  sortOrder: Ref<"newest" | "oldest">;
};

function resetGenerateForm(state: CoverLetterPageActionState) {
  state.generateForm.company = "";
  state.generateForm.position = "";
  state.generateForm.jobDescription = "";
  state.generateForm.resumeId = state.initialResumeId.value;
  state.generateForm.template = COVER_LETTER_DEFAULT_TEMPLATE;
}

function initializeResumeSelection(
  state: Pick<CoverLetterPageActionState, "generateForm" | "initialResumeId">,
  route: CoverLetterPageActionServices["route"],
) {
  const routeResumeId = route.query[APP_ROUTE_QUERY_KEYS.resumeId];
  if (typeof routeResumeId === "string" && routeResumeId.trim().length > 0) {
    state.initialResumeId.value = routeResumeId.trim();
    state.generateForm.resumeId = state.initialResumeId.value;
  }
}

function validateGenerateForm(state: CoverLetterPageActionState, toast: ToastApi, t: TranslateFn) {
  if (state.generateForm.company.trim().length < COVER_LETTER_COMPANY_MIN_LENGTH) {
    toast.error(
      t("coverLetterPage.toasts.companyMinLength", {
        count: COVER_LETTER_COMPANY_MIN_LENGTH,
      }),
    );
    return false;
  }

  if (state.generateForm.position.trim().length < COVER_LETTER_POSITION_MIN_LENGTH) {
    toast.error(
      t("coverLetterPage.toasts.positionMinLength", {
        count: COVER_LETTER_POSITION_MIN_LENGTH,
      }),
    );
    return false;
  }

  const description = state.generateForm.jobDescription.trim();
  if (description.length > 0 && description.length < COVER_LETTER_JOB_DESCRIPTION_MIN_LENGTH) {
    toast.error(
      t("coverLetterPage.toasts.jobDescriptionMinLength", {
        count: COVER_LETTER_JOB_DESCRIPTION_MIN_LENGTH,
      }),
    );
    return false;
  }

  return true;
}

/**
 * Forwards the posting and studio the user arrived from (`?job=` / `?studio=`) so the
 * server can load those records and tailor the letter against the scraped data,
 * rather than only the description pasted into the form.
 */
function buildGeneratePayload(
  state: CoverLetterPageActionState,
  query: Readonly<Record<string, RouteQueryValue>>,
): GenerateCoverLetterInput {
  const description = state.generateForm.jobDescription.trim();
  const jobId = queryValueToString(query[APP_ROUTE_QUERY_KEYS.jobId]).trim();
  const studioId = queryValueToString(query[APP_ROUTE_QUERY_KEYS.studioId]).trim();
  return {
    company: state.generateForm.company.trim(),
    position: state.generateForm.position.trim(),
    resumeId:
      state.generateForm.resumeId.trim().length > 0
        ? state.generateForm.resumeId.trim()
        : undefined,
    template: state.generateForm.template,
    save: true,
    ...(description.length > 0 ? { jobInfo: { description } } : {}),
    ...(jobId.length > 0 ? { jobId } : {}),
    ...(studioId.length > 0 ? { studioId } : {}),
  };
}

function createEditLetterAction(services: Pick<CoverLetterPageActionServices, "router">) {
  return async (id: string) => {
    await services.router.push(APP_ROUTE_BUILDERS.coverLetterDetail(id));
  };
}

function createDeleteCoverLetterHandler(
  services: CoverLetterPageActionServices,
  state: CoverLetterPageActionState,
) {
  return async () => {
    const id = state.pendingDeleteId.value;
    if (!id) {
      return;
    }

    const deleteResult = await settlePromise(
      services.deleteCoverLetter(id),
      services.t("coverLetterPage.toasts.deleteFailed"),
    );
    state.closeDeleteDialog();

    if (!deleteResult.ok) {
      services.$toast.error(
        getErrorMessage(deleteResult.error, services.t("coverLetterPage.toasts.deleteFailed")),
      );
      return;
    }

    services.$toast.success(services.t("coverLetterPage.toasts.deleted"));
  };
}

function resolveGeneratedCoverLetterId(result: GenerateCoverLetterResult | null): string | null {
  if (!(result && "coverLetter" in result)) {
    return null;
  }

  return result.coverLetter.id ?? null;
}

function createGenerateCoverLetterHandler(
  services: CoverLetterPageActionServices,
  state: CoverLetterPageActionState,
) {
  return async () => {
    if (!validateGenerateForm(state, services.$toast, services.t)) {
      return;
    }

    state.generating.value = true;
    const generateResult = await settlePromise(
      services.generateCoverLetter(buildGeneratePayload(state, services.route.query)),
      services.t("coverLetterPage.toasts.generateFailed"),
    );
    state.generating.value = false;

    if (!generateResult.ok) {
      services.$toast.error(
        getErrorMessage(generateResult.error, services.t("coverLetterPage.toasts.generateFailed")),
      );
      return;
    }

    state.showGenerateModal.value = false;
    resetGenerateForm(state);
    const generatedId = resolveGeneratedCoverLetterId(generateResult.value);
    if (!generatedId) {
      services.$toast.success(services.t("coverLetterPage.toasts.generatedWithoutRedirect"));
      return;
    }

    services.$toast.success(services.t("coverLetterPage.toasts.generated"));
    await services.router.push(APP_ROUTE_BUILDERS.coverLetterDetail(generatedId));
  };
}

export function createCoverLetterActions(
  services: CoverLetterPageActionServices,
  state: CoverLetterPageActionState,
) {
  const clearFilters = () => {
    state.searchQuery.value = "";
    state.templateFilter.value = "all";
    state.sortOrder.value = "newest";
  };

  const coverLetterPageAria = (page: number) =>
    services.t("coverLetterPage.pagination.pageAria", { page });

  return {
    clearFilters,
    coverLetterPageAria,
    editLetter: createEditLetterAction(services),
    handleDeleteCoverLetter: createDeleteCoverLetterHandler(services, state),
    handleGenerate: createGenerateCoverLetterHandler(services, state),
  };
}

export function useCoverLetterPageBootstrap(
  services: Pick<
    CoverLetterPageActionServices,
    "fetchCoverLetters" | "fetchResumes" | "route" | "$toast" | "t"
  >,
  state: Pick<CoverLetterPageActionState, "generateForm" | "initialResumeId">,
) {
  return useAsyncData("cover-letter-page-bootstrap", async () => {
    initializeResumeSelection(state, services.route);
    const [coverLettersResult, resumesResult] = await Promise.all([
      settlePromise(services.fetchCoverLetters(), services.t("coverLetterPage.toasts.fetchFailed")),
      settlePromise(services.fetchResumes(), services.t("apiErrors.resumes.fetchListFailed")),
    ]);

    if (!coverLettersResult.ok) {
      const failure = getErrorMessage(
        coverLettersResult.error,
        services.t("coverLetterPage.toasts.fetchFailed"),
      );
      services.$toast.error(failure);
      throw coverLettersResult.error;
    }

    if (!resumesResult.ok) {
      const failure = getErrorMessage(
        resumesResult.error,
        services.t("apiErrors.resumes.fetchListFailed"),
      );
      services.$toast.error(failure);
      throw resumesResult.error;
    }

    return true;
  });
}

