  const routeStudioId = computed(() =>
    queryValueToString(route.query[APP_ROUTE_QUERY_KEYS.studioId]),
  );
  const requestedMode = computed<InterviewMode>(() =>
    route.query[APP_ROUTE_QUERY_KEYS.mode] === "job" || routeJobId.value ? "job" : "studio",
  );

  return {
    requestedMode,
    routeJobId,
    routeStudioId,
  };
}

async function loadInterviewHubBootstrapData(
  {
    input,
    requestedMode,
    routeStudioId,
    sessionConfig,
    state,
  }: {
    input: InterviewHubBootstrapInput;
    requestedMode: ComputedRef<InterviewMode>;
    routeStudioId: ComputedRef<string>;
    sessionConfig: InterviewHubSessionConfig;
    state: ReturnType<typeof createInterviewHubBootstrapState>;
  },
  t: ComposerTranslation,
) {
  state.pathwaysRecommendationError.value = null;

  const bootstrapResult = await settlePromise(
    Promise.all([
      input.fetchSessions(),
      input.fetchStats(),
      input.fetchProfile(),
      input.searchStudios(),
      input.searchJobs({ limit: String(INTERVIEW_HUB_JOB_QUERY_LIMIT) }),
      input.fetchResumes(),
      input.fetchCoverLetters(),
      input.fetchPortfolio(),
    ]),
    t("interviewHub.errors.bootstrapLoadFailed"),
  );

  if (!bootstrapResult.ok) {
    throw new Error(
      getErrorMessage(bootstrapResult.error, t("interviewHub.errors.bootstrapLoadFailed")),
    );
  }

  const pathwaysResult = await settlePromise(
    Promise.all([input.fetchPathways(), input.fetchReadiness()]),
    t("interviewHub.errors.roleRecommendationsFailed"),
  );
  state.pathwaysRecommendationError.value = pathwaysResult.ok
    ? null
    : getErrorMessage(pathwaysResult.error, t("interviewHub.errors.roleRecommendationsFailed"));

  state.selectedMode.value = requestedMode.value;
  if (routeStudioId.value) {
    sessionConfig.studioId = routeStudioId.value;
  }

  return true;
}

export function useInterviewHubBootstrap(
  input: InterviewHubBootstrapInput,
  t: ComposerTranslation,
) {
  const state = createInterviewHubBootstrapState();
  const { interviewExperienceOptions, interviewQuestionCountOptions, sessionConfig } =
    createInterviewHubSessionConfig();
  const { requestedMode, routeJobId, routeStudioId } = createInterviewHubRouteState(input.route);

  const {
    status: interviewHubStatus,
    error: interviewHubError,
    refresh: refreshInterviewHub,
  } = useAsyncData("interview-hub-bootstrap", async () =>
    loadInterviewHubBootstrapData({ input, requestedMode, routeStudioId, sessionConfig, state }, t),
  );

  const interviewHubPending = computed(
    () => interviewHubStatus.value === "pending" || interviewHubStatus.value === "idle",
  );

  return {
    interviewExperienceOptions,
    interviewHubError,
    interviewHubPending,
    interviewHubStatus,
    interviewQuestionCountOptions,
    jobSearchTerm: state.jobSearchTerm,
    pathwaysRecommendationError: state.pathwaysRecommendationError,
    refreshInterviewHub,
    requestedMode,
    routeJobId,
    routeStudioId,
    selectedJobFallback: state.selectedJobFallback,
    selectedJobId: state.selectedJobId,
    selectedMode: state.selectedMode,
    sessionConfig,
    showConfigModal: state.showConfigModal,
    starting: state.starting,
  };
}

import {
  INTERVIEW_HUB_RECENT_SESSION_LIMIT,
  JOB_PREVIEW_LIMIT,
} from "@bao/shared/constants/interview";
import { APP_ROUTES } from "@bao/shared/constants/routes";
import type { InterviewMode } from "@bao/shared/types/interview";
import type { Job } from "@bao/shared/types/jobs";
import type { ComputedRef, Ref } from "vue";
import type { ComposerTranslation } from "vue-i18n";
import { cloneJob, type InterviewJobView } from "~/composables/interview-hub-bootstrap";
import { useInterviewRoleOptions } from "~/composables/interview-hub-role-options";
import { PERCENT_MAX } from "~/constants/numeric-ui";

type InterviewHubDerivedInput = {
  coverLetters: Ref<readonly { readonly id?: string }[]>;
  jobSearchTerm: Ref<string>;
  jobs: Ref<readonly InterviewJobView[]>;
  pathways: Ref<readonly { readonly title: string; readonly matchScore: number }[]>;
  portfolio: Ref<{ readonly id?: string; readonly projects: readonly unknown[] } | null>;
  profile: Ref<{ readonly currentRole?: string | null } | null>;
  readiness: Ref<{
    readonly targetRoleReadiness?: readonly {
      readonly roleTitle: string;
      readonly readinessScore: number;
    }[];
  } | null>;
  selectedJobFallback: Ref<Job | null>;
  selectedJobId: Ref<string>;
  selectedMode: Ref<InterviewMode>;
  sessionConfig: { studioId: string; role: string };
  sessions: Ref<readonly unknown[]>;
  stats: Ref<{
    readonly totalSessions?: number;
    readonly averageScore?: number;
    readonly improvementTrend?: number;
  } | null>;
  studios: Ref<
    readonly {
      readonly id: string;
      readonly name: string;
      readonly type?: string;
      readonly location?: string;
    }[]
  >;
  resumes: Ref<readonly { readonly id?: string; readonly isDefault?: boolean }[]>;
};

function useInterviewHubSessionStats(
  sessions: InterviewHubDerivedInput["sessions"],
  stats: InterviewHubDerivedInput["stats"],
  t: ComposerTranslation,
) {
  const recentSessionPagination = usePagination(
    computed(() => sessions.value),
    INTERVIEW_HUB_RECENT_SESSION_LIMIT,
  );

  return {
    averageScore: computed(() => Math.round(stats.value?.averageScore ?? 0)),
    improvementTrend: computed(() => Math.round(stats.value?.improvementTrend ?? 0)),
    recentSessionPagination,
    recentSessions: computed(() => recentSessionPagination.items.value),
    recentSessionsPaginationSummary: computed(() =>
      t("interviewHub.recent.pagination.summary", {
        start: recentSessionPagination.rangeStart.value,
        end: recentSessionPagination.rangeEnd.value,
        total: recentSessionPagination.totalItems.value,
      }),
    ),
    totalSessions: computed(() => stats.value?.totalSessions ?? 0),
  };
}

function useInterviewHubPrepState(
  {
    coverLetters,
    portfolio,
    resumes,
  }: Pick<InterviewHubDerivedInput, "coverLetters" | "portfolio" | "resumes">,
  t: ComposerTranslation,
) {
  const prepChecklist = computed(() => [
    {
      id: "resume",
      ready: resumes.value.length > 0,
      title: t("interviewHub.prep.items.resume.title"),
      description: t("interviewHub.prep.items.resume.description"),
      ctaLabel: t("interviewHub.prep.items.resume.cta"),
      route: APP_ROUTES.resume,
    },
    {
      id: "coverLetter",
      ready: coverLetters.value.length > 0,
      title: t("interviewHub.prep.items.coverLetter.title"),
      description: t("interviewHub.prep.items.coverLetter.description"),
      ctaLabel: t("interviewHub.prep.items.coverLetter.cta"),
      route: APP_ROUTES.coverLetter,
    },
    {
      id: "portfolio",
      ready: (portfolio.value?.projects?.length ?? 0) > 0,
      title: t("interviewHub.prep.items.portfolio.title"),
      description: t("interviewHub.prep.items.portfolio.description"),
      ctaLabel: t("interviewHub.prep.items.portfolio.cta"),
      route: APP_ROUTES.portfolio,
    },
  ]);
  const prepReadyCount = computed(() => prepChecklist.value.filter((item) => item.ready).length);

  return {
    prepChecklist,
    prepCompletionPercent: computed(() => {
      const total = prepChecklist.value.length;
      if (total === 0) {
        return 0;
      }
      return Math.round((prepReadyCount.value / total) * PERCENT_MAX);
    }),
    prepReadyCount,
  };
}

function useInterviewJobSelection(
  {
    jobSearchTerm,
    jobs,
    selectedJobFallback,
    selectedJobId,
  }: Pick<
    InterviewHubDerivedInput,
    "jobSearchTerm" | "jobs" | "selectedJobFallback" | "selectedJobId"
  >,
  t: ComposerTranslation,
) {
  const availableJobs = computed(() => {
    const unique = new Map<string, Job>();
    for (const job of jobs.value) {
      unique.set(job.id, cloneJob(job));
    }
    return [...unique.values()];
  });
  const searchedJobs = computed(() => {
    const query = jobSearchTerm.value.trim().toLowerCase();
    if (!query) {
      return availableJobs.value;
    }
    return availableJobs.value.filter((job) => {
      const title = job.title.toLowerCase();
      const company = job.company.toLowerCase();
      const description = (job.description || "").toLowerCase();
      return title.includes(query) || company.includes(query) || description.includes(query);
    });
  });
  const jobSelectionPagination = usePagination(searchedJobs, JOB_PREVIEW_LIMIT, [jobSearchTerm]);

  return {
    availableJobs,
    jobSelectionPagination,
    jobSelectionPaginationSummary: computed(() =>
      t("interviewHub.config.pagination.summary", {
        start: jobSelectionPagination.rangeStart.value,
        end: jobSelectionPagination.rangeEnd.value,
        total: jobSelectionPagination.totalItems.value,
      }),
    ),
    searchedJobs,
    selectedJob: computed(() => {
      const fromList = availableJobs.value.find((job) => job.id === selectedJobId.value);
      if (fromList) {
        return fromList;
      }
      if (selectedJobFallback.value?.id === selectedJobId.value) {
        return selectedJobFallback.value;
      }
      return null;
    }),
  };
}

function useInterviewResourceSelections(
  {
    coverLetters,
    portfolio,
    resumes,
    sessionConfig,
    selectedMode,
    studios,
  }: Pick<
    InterviewHubDerivedInput,
    "coverLetters" | "portfolio" | "resumes" | "sessionConfig" | "selectedMode" | "studios"
  >,
  selectedJob: ComputedRef<Job | null>,
) {
  return {
    isStartDisabled: computed(() => {
      if (selectedMode.value === "job") {
        return !selectedJob.value;
      }
      return !sessionConfig.studioId;
    }),
    selectedCoverLetterId: computed(() => coverLetters.value[0]?.id),
    selectedPortfolioId: computed(() => portfolio.value?.id),
    selectedResumeId: computed(() => {
      const defaultResume = resumes.value.find((resume) => resume.isDefault && resume.id);
      if (defaultResume?.id) {
        return defaultResume.id;
      }
      return resumes.value[0]?.id;
    }),
    selectedStudioName: computed(() => {
      if (!sessionConfig.studioId) {
        return "";
      }
      const selectedStudio = studios.value.find((studio) => studio.id === sessionConfig.studioId);
      return selectedStudio?.name || "";
    }),
    studiosForSelector: computed(() =>
      studios.value.map((studio) => ({
        id: studio.id,
        name: studio.name,
        type: studio.type,
        location: studio.location,
      })),
    ),
  };
}

export function useInterviewHubDerived(
  {
    coverLetters,
    jobSearchTerm,
    jobs,
    pathways,
    portfolio,
    profile,
    readiness,
    selectedJobFallback,
    selectedJobId,
    selectedMode,
    sessionConfig,
    sessions,
    stats,
    studios,
    resumes,
  }: InterviewHubDerivedInput,
  t: ComposerTranslation,
) {
  const sessionStats = useInterviewHubSessionStats(sessions, stats, t);
  const prepState = useInterviewHubPrepState({ coverLetters, portfolio, resumes }, t);
  const interviewRoleOptions = useInterviewRoleOptions({ jobs, pathways, profile, readiness });
  const jobSelection = useInterviewJobSelection(
    { jobSearchTerm, jobs, selectedJobFallback, selectedJobId },
    t,
  );
  const resourceSelections = useInterviewResourceSelections(
    { coverLetters, portfolio, resumes, sessionConfig, selectedMode, studios },
    jobSelection.selectedJob,
  );

  return {
    averageScore: sessionStats.averageScore,
    availableJobs: jobSelection.availableJobs,
    improvementTrend: sessionStats.improvementTrend,
    interviewRoleOptions,
    isStartDisabled: resourceSelections.isStartDisabled,
    jobSelectionPagination: jobSelection.jobSelectionPagination,
    jobSelectionPaginationSummary: jobSelection.jobSelectionPaginationSummary,
    prepChecklist: prepState.prepChecklist,
    prepCompletionPercent: prepState.prepCompletionPercent,
    prepReadyCount: prepState.prepReadyCount,
    recentSessionPagination: sessionStats.recentSessionPagination,
    recentSessions: sessionStats.recentSessions,
    recentSessionsPaginationSummary: sessionStats.recentSessionsPaginationSummary,
    searchedJobs: jobSelection.searchedJobs,
    selectedCoverLetterId: resourceSelections.selectedCoverLetterId,
    selectedJob: jobSelection.selectedJob,
    selectedPortfolioId: resourceSelections.selectedPortfolioId,
    selectedResumeId: resourceSelections.selectedResumeId,
    selectedStudioName: resourceSelections.selectedStudioName,
    studiosForSelector: resourceSelections.studiosForSelector,
    totalSessions: sessionStats.totalSessions,
  };
}

import type { InterviewMode } from "@bao/shared/types/interview";
import type { Ref } from "vue";
import type { ComposerTranslation } from "vue-i18n";
import { formatDateWithLocale } from "~/utils/locale-format";

type InterviewHubPresentationInput = {
  fallbackLocale: Ref<unknown>;
  locale: Ref<string>;
};

const EXPERIENCE_LABEL_KEYS = {
  entry: "interviewHub.experience.entry",
  lead: "interviewHub.experience.lead",
  mid: "interviewHub.experience.mid",
  senior: "interviewHub.experience.senior",
} as const;

const QUESTION_COUNT_LABEL_KEYS = {
  3: "interviewHub.questionCount.quick",
  5: "interviewHub.questionCount.standard",
  8: "interviewHub.questionCount.deep",
} as const;

export function createInterviewHubPresentation(
  input: InterviewHubPresentationInput,
  t: ComposerTranslation,
) {
  return {
    experienceLabel(level: string): string {
      const key = EXPERIENCE_LABEL_KEYS[level as keyof typeof EXPERIENCE_LABEL_KEYS];
      return key ? t(key) : level;
    },
    formatSessionDate(value: string | undefined): string {
      if (!(typeof value === "string" && value.length > 0)) {
        return t("interviewHub.recent.notAvailable");
      }
      const formattedDate = formatDateWithLocale(
        value,
        input.locale.value,
        input.fallbackLocale.value,
        { dateStyle: "medium" },
      );
      return formattedDate ?? t("interviewHub.recent.notAvailable");
    },
    interviewConfigPageAria(page: number): string {
      return t("interviewHub.config.pagination.pageAria", { page });
    },
    modeLabel(mode: InterviewMode | undefined): string {
      return mode === "job" ? t("interviewHub.mode.job") : t("interviewHub.mode.studio");
    },
    prepStatusBadgeClass(ready: boolean): string {
      return ready ? "badge-success" : "badge-ghost";
    },
    questionCountLabel(count: number): string {
      const key = QUESTION_COUNT_LABEL_KEYS[count as keyof typeof QUESTION_COUNT_LABEL_KEYS];
      return key ? t(key) : String(count);
    },
    recentSessionPageAria(page: number): string {
      return t("interviewHub.recent.pagination.pageAria", { page });
    },
  };
}

import { INTERVIEW_DEFAULT_ROLE_TYPE } from "@bao/shared/constants/interview";
import type { Ref } from "vue";
import {
  type InterviewJobView,
  normalizeRoleCandidate,
} from "~/composables/interview-hub-bootstrap";

type InterviewHubRoleOptionsInput = {
  jobs: Ref<readonly InterviewJobView[]>;
  pathways: Ref<readonly { readonly title: string; readonly matchScore: number }[]>;
  profile: Ref<{ readonly currentRole?: string | null } | null>;
  readiness: Ref<{
    readonly targetRoleReadiness?: readonly {
      readonly roleTitle: string;
      readonly readinessScore: number;
    }[];
  } | null>;
};

export function useInterviewRoleOptions({
  jobs,
  pathways,
  profile,
  readiness,
}: InterviewHubRoleOptionsInput) {
  const pathwayRoleTitles = computed<readonly string[]>(() =>
    [...pathways.value]
      .sort((left, right) => right.matchScore - left.matchScore)
      .map((pathway) => pathway.title),
  );
  const readinessRoleTitles = computed<readonly string[]>(() =>
    [...(readiness.value?.targetRoleReadiness ?? [])]
      .sort((left, right) => right.readinessScore - left.readinessScore)
      .map((entry) => entry.roleTitle),
  );

  return computed<readonly string[]>(() => {
    const ordered: string[] = [];
    const seen = new Set<string>();

    const addRole = (value: string | null | undefined): void => {
      if (!value) {
        return;
      }
      const normalized = normalizeRoleCandidate(value);
      if (normalized.length === 0) {
        return;
      }
      const dedupeKey = normalized.toLowerCase();
      if (seen.has(dedupeKey)) {
        return;
      }
      seen.add(dedupeKey);
      ordered.push(normalized);
    };

    addRole(profile.value?.currentRole ?? null);
    for (const roleTitle of readinessRoleTitles.value) addRole(roleTitle);
    for (const roleTitle of pathwayRoleTitles.value) addRole(roleTitle);
    for (const job of jobs.value) addRole(job.title);
    addRole(INTERVIEW_DEFAULT_ROLE_TYPE);

    return ordered;
  });
}

import { INTERVIEW_DEFAULT_DURATION_MINUTES } from "@bao/shared/constants/interview";
import type {
  InterviewAnalysisAggregateSource,
  InterviewAnalysisProvenanceCounts,
  InterviewCandidateContext,
  InterviewConfig,
  InterviewConversationStyle,
  InterviewMode,
  InterviewSession,
  InterviewTargetJob,
} from "@bao/shared/types/interview";
import { resolveInterviewAnalysisSource } from "@bao/shared/utils/interview-analysis-provenance";
import type { JsonValue } from "@bao/shared/utils/json";
import { normalizeScrapePersonaEnrichment } from "@bao/shared/utils/scrape-enrichment";
import {
  asBoolean,
  asNumber,
  asString,
  asStringArray,
  isRecord,
} from "@bao/shared/utils/type-guards";

const INTERVIEW_STATUS_VALUES = [
  "preparing",
  "active",
  "paused",
  "completed",
  "cancelled",
] as const;

const INTERVIEW_QUESTION_TYPES = [
  "behavioral",
  "technical",
  "studio-specific",
  "intro",
  "closing",
] as const;

const INTERVIEW_QUESTION_DIFFICULTIES = ["easy", "medium", "hard"] as const;

type InterviewStatus = InterviewSession["status"];
type InterviewQuestionType = InterviewSession["questions"][number]["type"];
type InterviewQuestionDifficulty = InterviewSession["questions"][number]["difficulty"];

const isOneOf = <T extends string>(values: readonly T[], value: unknown): value is T =>
  typeof value === "string" && values.some((entry) => entry === value);

const asInterviewStatus = (value: unknown): InterviewStatus =>
  isOneOf(INTERVIEW_STATUS_VALUES, value) ? value : "active";

const asQuestionType = (value: unknown): InterviewQuestionType =>
  isOneOf(INTERVIEW_QUESTION_TYPES, value) ? value : "behavioral";

const asQuestionDifficulty = (value: unknown): InterviewQuestionDifficulty =>
  isOneOf(INTERVIEW_QUESTION_DIFFICULTIES, value) ? value : "medium";

const asInterviewMode = (value: unknown): InterviewMode => (value === "job" ? "job" : "studio");
const asInterviewConversationStyle = (value: unknown): InterviewConversationStyle =>
  value === "structured" ? "structured" : "natural";

const asInterviewTargetJob = (value: unknown): InterviewTargetJob | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const id = asString(value.id);
  const title = asString(value.title);
  const company = asString(value.company);
  const location = asString(value.location);
  if (!(id && title && company && location)) {
    return;
  }

  return {
    id,
    title,
    company,
    location,
    description: asString(value.description),
    requirements: asStringArray(value.requirements),
    technologies: asStringArray(value.technologies),
    source: asString(value.source),
    postedDate: asString(value.postedDate),
    url: asString(value.url),
    enrichment: normalizeScrapePersonaEnrichment(value.enrichment),
  };
};

const asInterviewCandidateContext = (value: unknown): InterviewCandidateContext | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const resumeId = asString(value.resumeId);
  const coverLetterId = asString(value.coverLetterId);
  const portfolioId = asString(value.portfolioId);
  if (!(resumeId || coverLetterId || portfolioId)) {
    return;
  }

  return {
    ...(resumeId ? { resumeId } : {}),
    ...(coverLetterId ? { coverLetterId } : {}),
    ...(portfolioId ? { portfolioId } : {}),
  };
};

const toInterviewQuestion = (value: unknown): InterviewSession["questions"][number] | null => {
  if (!isRecord(value)) {
    return null;
  }

  const id = asString(value.id);
  const question = asString(value.question);
  if (!(id && question)) {
    return null;
  }

  const nextQuestion: InterviewSession["questions"][number] = {
    id,
    type: asQuestionType(value.type),
    question,
    followUps: asStringArray(value.followUps),
    expectedDuration: asNumber(value.expectedDuration) ?? 60,
    difficulty: asQuestionDifficulty(value.difficulty),
    tags: asStringArray(value.tags),
  };
  const score = asNumber(value.score);
  const feedback = asString(value.feedback);
  const response = asString(value.response);
  if (score !== undefined) {
    nextQuestion.score = score;
  }
  if (feedback !== undefined) {
    nextQuestion.feedback = feedback;
  }
  if (response !== undefined) {
    nextQuestion.response = response;
  }
  return nextQuestion;
};

const toInterviewQuestions = (value: unknown): InterviewSession["questions"] =>
  Array.isArray(value)
    ? value
        .map((entry) => toInterviewQuestion(entry))
        .filter((entry): entry is InterviewSession["questions"][number] => entry !== null)
    : [];

const toResponseAnalysis = (
  value: unknown,
): InterviewSession["responses"][number]["aiAnalysis"] | undefined => {
  if (!isRecord(value)) {
    return;
  }
  return {
    score: asNumber(value.score) ?? 0,
    feedback: asString(value.feedback) ?? "",
    strengths: asStringArray(value.strengths),
    improvements: asStringArray(value.improvements),
    // Sessions stored before provenance tracking carry no marker, so the
    // analysis is reported as "unknown" rather than claimed as AI-generated.
    source: resolveInterviewAnalysisSource(value.source),
    ...(asString(value.provider) === undefined ? {} : { provider: asString(value.provider) }),
    ...(asString(value.model) === undefined ? {} : { model: asString(value.model) }),
  };
};

const toInterviewResponse = (value: unknown): InterviewSession["responses"][number] | null => {
  if (!isRecord(value)) {
    return null;
  }

  const questionId = asString(value.questionId);
  const transcript = asString(value.transcript);
  if (!(questionId && transcript)) {
    return null;
  }

  const response: InterviewSession["responses"][number] = {
    questionId,
    transcript,
    duration: asNumber(value.duration) ?? 0,
    timestamp: asNumber(value.timestamp) ?? Date.now(),
    confidence: asNumber(value.confidence) ?? 0,
  };
  const analysis = toResponseAnalysis(value.aiAnalysis);
  if (analysis) {
    response.aiAnalysis = analysis;
  }
  return response;
};

const toInterviewResponses = (value: unknown): InterviewSession["responses"] =>
  Array.isArray(value)
    ? value
        .map((entry) => toInterviewResponse(entry))
        .filter((entry): entry is InterviewSession["responses"][number] => entry !== null)
    : [];

const toVoiceSettings = (value: unknown): InterviewConfig["voiceSettings"] | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const rate = asNumber(value.rate);
  const pitch = asNumber(value.pitch);
  const volume = asNumber(value.volume);
  const language = asString(value.language);
  if (rate === undefined || pitch === undefined || volume === undefined || !language) {
    return;
  }

  return {
    microphoneId: asString(value.microphoneId),
    speakerId: asString(value.speakerId),
    voiceId: asString(value.voiceId),
    rate,
    pitch,
    volume,
    language,
  };
};

const toInterviewConfig = (value: unknown, questionCount: number): InterviewSession["config"] => {
  const configRecord = isRecord(value) ? value : {};
  const config: InterviewSession["config"] = {
    roleType: asString(configRecord.roleType) ?? "Generalist",
    roleCategory: asString(configRecord.roleCategory),
    experienceLevel: asString(configRecord.experienceLevel) ?? "mid",
    focusAreas: asStringArray(configRecord.focusAreas),
    duration: asNumber(configRecord.duration) ?? INTERVIEW_DEFAULT_DURATION_MINUTES,
    questionCount: asNumber(configRecord.questionCount) ?? questionCount,
    includeTechnical: asBoolean(configRecord.includeTechnical) ?? true,
    includeBehavioral: asBoolean(configRecord.includeBehavioral) ?? true,
    includeStudioSpecific: asBoolean(configRecord.includeStudioSpecific) ?? true,
    enableVoiceMode: asBoolean(configRecord.enableVoiceMode),
    technologies: asStringArray(configRecord.technologies),
    interviewMode: asInterviewMode(configRecord.interviewMode),
    conversationStyle: asInterviewConversationStyle(configRecord.conversationStyle),
  };

  const voiceSettings = toVoiceSettings(configRecord.voiceSettings);
  if (voiceSettings) {
    config.voiceSettings = voiceSettings;
  }

  const targetJob = asInterviewTargetJob(configRecord.targetJob);
  if (targetJob) {
    config.targetJob = targetJob;
  }
  const candidateContext = asInterviewCandidateContext(configRecord.candidateContext);
  if (candidateContext) {
    config.candidateContext = candidateContext;
  }

  return config;
};

const toFinalAnalysis = (value: unknown): InterviewSession["finalAnalysis"] | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const feedback = asString(value.feedback);
  const analysis: NonNullable<InterviewSession["finalAnalysis"]> = {
    overallScore: asNumber(value.overallScore) ?? 0,
    strengths: asStringArray(value.strengths),
    improvements: asStringArray(value.improvements),
    recommendations: asStringArray(value.recommendations),
    // Provenance drives the "assessed by" attribution the score card renders;
    // dropping it here would leave the UI unable to distinguish AI from heuristic.
    analysisSource: toAnalysisAggregateSource(value.analysisSource),
  };
  if (feedback !== undefined) {
    analysis.feedback = feedback;
  }
  const aiAverageScore = asNumber(value.aiAverageScore);
  analysis.aiAverageScore = aiAverageScore === undefined ? null : aiAverageScore;
  const counts = toProvenanceCounts(value.provenanceCounts);
  if (counts) {
    analysis.provenanceCounts = counts;
  }
  return analysis;
};

const toAnalysisAggregateSource = (value: JsonValue | undefined): InterviewAnalysisAggregateSource =>
  value === "ai" || value === "heuristic" || value === "mixed" ? value : "unknown";

const toProvenanceCounts = (value: JsonValue | undefined): InterviewAnalysisProvenanceCounts | undefined => {
  if (!isRecord(value)) {
    return;
  }
  const aiCount = asNumber(value.ai);
  const heuristicCount = asNumber(value.heuristic);
  const unknownCount = asNumber(value.unknown);
  if (aiCount === undefined || heuristicCount === undefined || unknownCount === undefined) {
    return;
  }
  return { ai: aiCount, heuristic: heuristicCount, unknown: unknownCount };
};

const toInterviewerPersona = (
  value: unknown,
): InterviewSession["interviewerPersona"] | undefined => {
  if (!isRecord(value)) {
    return;
  }

  return {
    name: asString(value.name) ?? "",
    role: asString(value.role) ?? "",
    studioName: asString(value.studioName) ?? "",
    background: asString(value.background) ?? "",
    style: asString(value.style) ?? "",
    experience: asString(value.experience) ?? "",
  };
};

export const toInterviewSession = (value: unknown): InterviewSession | null => {
  if (!isRecord(value)) {
    return null;
  }

  const id = asString(value.id);
  const studioId = asString(value.studioId);
  if (!(id && studioId)) {
    return null;
  }

  const questions = toInterviewQuestions(value.questions);
  const session: InterviewSession = {
    id,
    studioId,
    config: toInterviewConfig(value.config, questions.length),
    questions,
    currentQuestionIndex: asNumber(value.currentQuestionIndex) ?? 0,
    totalQuestions: asNumber(value.totalQuestions) ?? questions.length,
    startTime: asNumber(value.startTime) ?? Date.now(),
    endTime: asNumber(value.endTime),
    status: asInterviewStatus(value.status),
    responses: toInterviewResponses(value.responses),
    role: asString(value.role),
    studioName: asString(value.studioName),
    score: asNumber(value.score),
    duration: asString(value.duration),
    overallFeedback: asString(value.overallFeedback),
    totalResponses: asNumber(value.totalResponses),
    createdAt: asString(value.createdAt),
    updatedAt: asString(value.updatedAt),
  };

  const finalAnalysis = toFinalAnalysis(value.finalAnalysis);
  if (finalAnalysis) {
    session.finalAnalysis = finalAnalysis;
  }

  const interviewerPersona = toInterviewerPersona(value.interviewerPersona);
  if (interviewerPersona) {
    session.interviewerPersona = interviewerPersona;
  }
  return session;
};

export const toInterviewSessions = (value: unknown): InterviewSession[] =>
  Array.isArray(value)
    ? value
        .map((entry) => toInterviewSession(entry))
        .filter((entry): entry is InterviewSession => entry !== null)
    : [];

export const toNumericRecord = (value: unknown): Record<string, number> | null => {
  if (!isRecord(value)) {
    return null;
  }
  const normalized: Record<string, number> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === "number" && Number.isFinite(entry)) {
      normalized[key] = entry;
    }
  }
  return normalized;
};

import { WS_ENDPOINTS } from "@bao/shared/constants/endpoints";
import { safeParseJson } from "@bao/shared/utils/json";
import {
  INTERVIEW_SOCKET_ACK_DEADLINE_MS,
  INTERVIEW_SOCKET_ACK_POLL_MS,
  INTERVIEW_SOCKET_OPEN_WAIT_MS,
} from "~/constants/numeric-ui";
import { resolveWebSocketEndpoint } from "~/utils/endpoints";

export type InterviewResponseFeedbackPayload = {
  type: "response_feedback";
  sessionId: string;
  feedback: {
    score: number;
    strengths: string[];
    improvements: string[];
    summary: string;
  } | null;
  error: string | null;
  questionIndex: number;
  isComplete: boolean;
  responseIndex: number;
};

type InterviewRealtimeMessage = {
  type: string;
  sessionId?: string;
  content?: string;
};

type InterviewSocketPayload = {
  type?: string;
  sessionId?: string;
  feedback?: InterviewResponseFeedbackPayload["feedback"];
  error?: string | null;
  questionIndex?: number;
  isComplete?: boolean;
  responseIndex?: number;
};

export type InterviewRealtimeSocket = {
  connect: () => void;
  disconnect: () => void;
  send: (payload: InterviewRealtimeMessage) => boolean;
  waitForOpen: () => Promise<boolean>;
  getSocket: () => WebSocket | null;
};

function parseResponseFeedback(raw: string): InterviewResponseFeedbackPayload | null {
  const payload = safeParseJson(raw) as InterviewSocketPayload | null;
  if (!payload || typeof payload !== "object" || payload.type !== "response_feedback") {
    return null;
  }
  if (typeof payload.sessionId !== "string") {
    return null;
  }
  return {
    type: "response_feedback",
    sessionId: payload.sessionId,
    feedback: payload.feedback ?? null,
    error: typeof payload.error === "string" ? payload.error : null,
    questionIndex: typeof payload.questionIndex === "number" ? payload.questionIndex : 0,
    isComplete: Boolean(payload.isComplete),
    responseIndex: typeof payload.responseIndex === "number" ? payload.responseIndex : 0,
  };
}

function bindSocketHandlers(
  socket: WebSocket,
  connected: Ref<boolean>,
  lastFeedback: Ref<InterviewResponseFeedbackPayload | null>,
): void {
  socket.onopen = () => {
    connected.value = true;
  };
  socket.onmessage = (event) => {
    if (typeof event.data !== "string") {
      return;
    }
    const feedback = parseResponseFeedback(event.data);
    if (feedback) {
      lastFeedback.value = feedback;
    }
  };
  socket.onclose = () => {
    connected.value = false;
  };
  socket.onerror = () => {
    connected.value = false;
  };
}

/**
 * Low-level interview WS socket with response_feedback capture.
 */
export function createInterviewRealtimeSocket(input: {
  wsBase: string;
  requestUrl: URL;
  connected: Ref<boolean>;
  lastFeedback: Ref<InterviewResponseFeedbackPayload | null>;
}): InterviewRealtimeSocket {
  let socket: WebSocket | null = null;

  const connect = (): void => {
    if (
      socket &&
      (socket.readyState === WebSocket.OPEN || socket.readyState === WebSocket.CONNECTING)
    ) {
      return;
    }
    const url = resolveWebSocketEndpoint(input.wsBase, input.requestUrl, WS_ENDPOINTS.interview);
    socket = new WebSocket(url);
    bindSocketHandlers(socket, input.connected, input.lastFeedback);
  };

  const send = (payload: InterviewRealtimeMessage): boolean => {
    if (!socket || socket.readyState !== WebSocket.OPEN) {
      return false;
    }
    socket.send(JSON.stringify(payload));
    return true;
  };

  const waitForOpen = (): Promise<boolean> =>
    new Promise((resolve) => {
      connect();
      if (socket?.readyState === WebSocket.OPEN) {
        resolve(true);
        return;
      }
      const pending = socket;
      if (!pending) {
        resolve(false);
        return;
      }
      const previousOnOpen = pending.onopen;
      pending.onopen = (event) => {
        if (typeof previousOnOpen === "function") {
          previousOnOpen.call(pending, event);
        }
        input.connected.value = true;
        resolve(true);
      };
      window.setTimeout(
        () => resolve(socket?.readyState === WebSocket.OPEN),
        INTERVIEW_SOCKET_OPEN_WAIT_MS,
      );
    });

  const disconnect = (): void => {
    if (socket && socket.readyState === WebSocket.OPEN) {
      socket.close();
    }
    socket = null;
    input.connected.value = false;
  };

  return {
    connect,
    disconnect,
    send,
    waitForOpen,
    getSocket: () => socket,
  };
}

function waitForSessionFeedback(
  lastFeedback: Ref<InterviewResponseFeedbackPayload | null>,
  sessionId: string,
): Promise<InterviewResponseFeedbackPayload | null> {
  return new Promise<InterviewResponseFeedbackPayload | null>((resolve) => {
    const deadline = Date.now() + INTERVIEW_SOCKET_ACK_DEADLINE_MS;
    const poll = (): void => {
      const feedback = lastFeedback.value;
      if (feedback && feedback.sessionId === sessionId) {
        resolve(feedback);
        return;
      }
      if (Date.now() >= deadline) {
        resolve(null);
        return;
      }
      window.setTimeout(poll, INTERVIEW_SOCKET_ACK_POLL_MS);
    };
    poll();
  });
}

export async function submitInterviewResponseViaWs(
  socketApi: InterviewRealtimeSocket,
  lastFeedback: Ref<InterviewResponseFeedbackPayload | null>,
  sessionId: string,
  content: string,
): Promise<InterviewResponseFeedbackPayload | null> {
  const opened = await socketApi.waitForOpen();
  if (!opened) {
    return null;
  }
  lastFeedback.value = null;
  if (!socketApi.send({ type: "submit_response", sessionId, content })) {
    return null;
  }
  return await waitForSessionFeedback(lastFeedback, sessionId);
}

import { INTERVIEW_MIN_RESPONSE_LENGTH } from "@bao/shared/constants/interview";
import { APP_ROUTE_QUERY_KEYS, APP_ROUTES } from "@bao/shared/constants/routes";
import { settlePromise } from "~/composables/async-flow";
import { getErrorMessage } from "~/utils/errors";

export type InterviewSessionFlowState =
  | "idle"
  | "loading"
  | "ready"
  | "submitting"
  | "completing"
  | "completed"
  | "error";

interface TimedInterviewSession {
  endTime?: number | null;
  id: string;
  startTime: number;
  status: string;
}

type Translate = (key: string, params?: Record<string, unknown>) => string;

type InterviewSessionActionsInput = {
  canComplete: ComputedRef<boolean>;
  canSubmit: ComputedRef<boolean>;
  completeSession: ReturnType<typeof useInterview>["completeSession"];
  completing: Ref<boolean>;
  currentQuestionIndex: ComputedRef<number>;
  currentSessionLoadId: Ref<number>;
  getSession: ReturnType<typeof useInterview>["getSession"];
  isLastQuestion: ComputedRef<boolean>;
  response: Ref<string>;
  router: ReturnType<typeof useRouter>;
  sessionId: ComputedRef<string>;
  sessionLoadError: Ref<string>;
  stt: ReturnType<typeof useSTT>;
  stopTimer: () => void;
  /** WS-first submit; returns true when WS path handled the write. */
  submitViaWs?: (sessionId: string, content: string) => Promise<boolean>;
  submitResponse: ReturnType<typeof useInterview>["submitResponse"];
  submitting: Ref<boolean>;
  syncCompletedSessionTime: (session: TimedInterviewSession) => void;
  startTimer: () => void;
  t: Translate;
  toast: ReturnType<typeof useNuxtApp>["$toast"];
};

export function normalizeSessionIdFromQuery(
  value: string | null | Array<string | null> | undefined,
): string {
  if (typeof value === "string") {
    return value.trim();
  }
  if (Array.isArray(value)) {
    const [firstValue] = value;
    return typeof firstValue === "string" ? firstValue.trim() : "";
  }
  return "";
}

function createInterviewHistoryAction(input: InterviewSessionActionsInput) {
  return async function goToHistory() {
    if (!input.sessionId.value) {
      return;
    }
    await input.router.push({
      path: APP_ROUTES.interviewHistory,
      query: {
        [APP_ROUTE_QUERY_KEYS.sessionId]: input.sessionId.value,
      },
    });
  };
}

function createInterviewLoadActions(input: InterviewSessionActionsInput) {
  async function loadSession(nextSessionId: string) {
    if (!nextSessionId) {
      input.stopTimer();
      input.sessionLoadError.value = input.t("interviewSession.notFound");
      return;
    }

    const requestId = ++input.currentSessionLoadId.value;
    input.sessionLoadError.value = "";
    input.response.value = "";

    const sessionResult = await settlePromise(
      input.getSession(nextSessionId),
      input.t("interviewSession.notFound"),
    );
    if (requestId !== input.currentSessionLoadId.value) {
      return;
    }

    if (!sessionResult.ok) {
      input.sessionLoadError.value = getErrorMessage(
        sessionResult.error,
        input.t("interviewSession.notFound"),
      );
      input.stopTimer();
      return;
    }

    const loadedSession = sessionResult.value;
    if (!loadedSession || loadedSession.id !== nextSessionId) {
      input.sessionLoadError.value = input.t("interviewSession.notFound");
      input.stopTimer();
      return;
    }

    if (loadedSession.status === "completed" || loadedSession.status === "cancelled") {
      input.stopTimer();
      input.syncCompletedSessionTime(loadedSession);
      return;
    }

    input.startTimer();
  }

  async function retryLoadSession() {
    await loadSession(input.sessionId.value);
  }

  return {
    loadSession,
    retryLoadSession,
  };
}

function createInterviewCompletionAction(
  input: InterviewSessionActionsInput,
  goToHistory: () => Promise<void>,
) {
  return async function handleCompleteInterview() {
    if (!(input.canComplete.value && input.sessionId.value)) {
      return;
    }

    input.stopTimer();
    input.completing.value = true;
    const completionResult = await settlePromise(
      input.completeSession(input.sessionId.value),
      input.t("interviewSession.errors.completeFailed"),
    );
    input.completing.value = false;

    if (!completionResult.ok) {
      input.toast.error(
        getErrorMessage(completionResult.error, input.t("interviewSession.errors.completeFailed")),
      );
      input.startTimer();
      return;
    }

    // HTTP complete is sole path — never also WS end_session (double-complete ban).
    input.toast.success(input.t("interviewSession.toasts.completed"));
    await goToHistory();
  };
}

function resolveInterviewResponseText(
  actions: InterviewSessionActionsInput,
  submittedResponse?: string,
): string {
  if (typeof submittedResponse === "string") {
    return submittedResponse.trim();
  }
  return actions.response.value.trim();
}

async function submitInterviewResponseHttp(
  actions: InterviewSessionActionsInput,
  responseText: string,
): Promise<"failed" | "completed" | "continued"> {
  const submitResult = await settlePromise(
    actions.submitResponse(actions.sessionId.value, {
      questionIndex: actions.currentQuestionIndex.value,
      response: responseText,
    }),
    actions.t("interviewSession.errors.submitFailed"),
  );
  if (!submitResult.ok) {
    actions.toast.error(
      getErrorMessage(submitResult.error, actions.t("interviewSession.errors.submitFailed")),
    );
    return "failed";
  }
  return submitResult.value?.status === "completed" ? "completed" : "continued";
}

async function finalizeInterviewSubmission(input: {
  actions: InterviewSessionActionsInput;
  goToHistory: () => Promise<void>;
  handleCompleteInterview: () => Promise<void>;
  completedViaHttp: boolean;
}): Promise<void> {
  input.actions.stt.stopListening();
  input.actions.response.value = "";
  input.actions.toast.success(input.actions.t("interviewSession.toasts.responseRecorded"));
  if (input.completedViaHttp) {
    input.actions.toast.success(input.actions.t("interviewSession.toasts.completed"));
    await input.goToHistory();
    return;
  }
  if (input.actions.isLastQuestion.value) {
    await input.handleCompleteInterview();
  }
}

function createInterviewSubmissionAction(input: {
  actions: InterviewSessionActionsInput;
  goToHistory: () => Promise<void>;
  handleCompleteInterview: () => Promise<void>;
}) {
  return async function handleSubmitResponse(submittedResponse?: string) {
    if (!(input.actions.canSubmit.value && input.actions.sessionId.value)) {
      return;
    }

    const responseText = resolveInterviewResponseText(input.actions, submittedResponse);
    if (responseText.length < INTERVIEW_MIN_RESPONSE_LENGTH) {
      input.actions.toast.error(
        input.actions.t("interviewSession.errors.minResponseLength", {
          count: INTERVIEW_MIN_RESPONSE_LENGTH,
        }),
      );
      return;
    }

    input.actions.submitting.value = true;
    // WS-or-HTTP single path — never both (mirroring after HTTP double-wrote answers).
    const wsHandled = input.actions.submitViaWs
      ? await input.actions.submitViaWs(input.actions.sessionId.value, responseText)
      : false;

    let completedViaHttp = false;
    if (!wsHandled) {
      const outcome = await submitInterviewResponseHttp(input.actions, responseText);
      if (outcome === "failed") {
        input.actions.submitting.value = false;
        return;
      }
      completedViaHttp = outcome === "completed";
    } else {
      // Refresh HTTP session so UI picks up AI analysis written by WS path.
      await settlePromise(
        input.actions.getSession(input.actions.sessionId.value),
        input.actions.t("interviewSession.errors.submitFailed"),
      );
    }
    input.actions.submitting.value = false;
    await finalizeInterviewSubmission({ ...input, completedViaHttp });
  };
}

export function createInterviewSessionActions(input: InterviewSessionActionsInput) {
  const goToHistory = createInterviewHistoryAction(input);
  const loadActions = createInterviewLoadActions(input);
  const handleCompleteInterview = createInterviewCompletionAction(input, goToHistory);
  const handleSubmitResponse = createInterviewSubmissionAction({
    actions: input,
    goToHistory,
    handleCompleteInterview,
  });

  return {
    goToHistory,
    handleCompleteInterview,
    handleSubmitResponse,
    loadSession: loadActions.loadSession,
    retryLoadSession: loadActions.retryLoadSession,
  };
}

import { INTERVIEW_MIN_RESPONSE_LENGTH } from "@bao/shared/constants/interview";
import { APP_ROUTE_QUERY_KEYS } from "@bao/shared/constants/routes";
import { useI18n } from "vue-i18n";
import {
  type createInterviewSessionActions,
  normalizeSessionIdFromQuery,
  type InterviewSessionFlowState as SessionFlowState,
} from "~/composables/interview-session-actions";
import type { createInterviewSessionTimer } from "~/composables/interview-session-timer";
import { PERCENT_MAX } from "~/constants/numeric-ui";

export function createInterviewSessionState() {
  const route = useRoute();
  const router = useRouter();
  const { currentSession, loading, getSession, submitResponse, completeSession } = useInterview();
  const { $toast } = useNuxtApp();
  const { t } = useI18n();
  const { getAlertClass } = useScoreColor();

  const voiceSettings = computed(() => currentSession.value?.config?.voiceSettings);
  const tts = useTTS(voiceSettings);
  const stt = useSTT(voiceSettings);
  const currentSessionLoadId = ref(0);
  const sessionLoadError = ref("");
  const response = ref("");
  const submitting = ref(false);
  const completing = ref(false);
  return {
    completeSession,
    completing,
    currentSession,
    currentSessionLoadId,
    getAlertClass,
    getSession,
    loading,
    response,
    route,
    router,
    sessionLoadError,
    stt,
    submitResponse,
    submitting,
    t,
    targetJob: computed(() => currentSession.value?.config?.targetJob),
    toast: $toast,
    tts,
  };
}

function createInterviewSessionQuestions(
  activeSession: ComputedRef<ReturnType<typeof useInterview>["currentSession"]["value"] | null>,
  currentQuestionIndex: ComputedRef<number>,
) {
  const currentQuestion = computed(
    () => activeSession.value?.questions?.[Math.max(0, currentQuestionIndex.value)],
  );
  const hasCurrentQuestion = computed(() => Boolean(currentQuestion.value));
  const chatQuestions = computed<{ id: string; text: string }[]>(() => {
    const session = activeSession.value;
    return session
      ? session.questions.map((question) => ({ id: question.id, text: question.question }))
      : [];
  });
  const chatResponses = computed(() => {
    const session = activeSession.value;
    if (!session) {
      return [] as { questionId: string; text: string }[];
    }

    const responseByQuestion = new Map<string, string>();
    for (const sessionResponse of session.responses) {
      responseByQuestion.set(sessionResponse.questionId, sessionResponse.transcript);
    }

    return session.questions.flatMap((question) => {
      const responseText = responseByQuestion.get(question.id);
      return responseText ? [{ questionId: question.id, text: responseText }] : [];
    });
  });

  return {
    chatQuestions,
    chatResponses,
    currentQuestion,
    hasCurrentQuestion,
  };
}

function createInterviewSessionStatus(input: {
  activeSession: ComputedRef<ReturnType<typeof useInterview>["currentSession"]["value"] | null>;
  currentQuestionIndex: ComputedRef<number>;
  loading: Ref<boolean>;
  response: Ref<string>;
  sessionId: ComputedRef<string>;
  sessionLoadError: Ref<string>;
  stt: ReturnType<typeof useSTT>;
  submitting: Ref<boolean>;
  completing: Ref<boolean>;
  t: ReturnType<typeof useI18n>["t"];
  totalQuestions: ComputedRef<number>;
  hasCurrentQuestion: ComputedRef<boolean>;
}) {
  const activeSessionComplete = computed(() => input.activeSession.value?.status === "completed");
  const activeSessionReady = computed(
    () =>
      input.activeSession.value !== null &&
      input.activeSession.value.status !== "cancelled" &&
      input.activeSession.value.status !== "completed",
  );
  const isBusy = computed(
    () =>
      input.loading.value ||
      input.submitting.value ||
      input.completing.value ||
      input.stt.isListening.value,
  );
  const isLastQuestion = computed(
    () =>
      input.hasCurrentQuestion.value &&
      input.currentQuestionIndex.value >= input.totalQuestions.value - 1,
  );
  const completionState = computed<SessionFlowState>(() => {
    if (!input.sessionId.value) return "idle";
    if (input.sessionLoadError.value.length > 0) return "error";
    if (!input.activeSession.value) return input.loading.value ? "loading" : "error";
    if (activeSessionComplete.value) return "completed";
    if (input.completing.value) return "completing";
    if (input.submitting.value) return "submitting";
    return "ready";
  });
  const canSubmit = computed(
    () =>
      input.hasCurrentQuestion.value &&
      input.response.value.trim().length >= INTERVIEW_MIN_RESPONSE_LENGTH &&
      !isBusy.value &&
      activeSessionReady.value,
  );
  const canComplete = computed(
    () => input.activeSession.value !== null && !activeSessionComplete.value && !isBusy.value,
  );

  return {
    canComplete,
    canSubmit,
    completionState,
    isLastQuestion,
  };
}

export function createInterviewSessionDerivedState(
  input: ReturnType<typeof createInterviewSessionState>,
) {
  const sessionState = createInterviewSessionIdentity(input);
  const questionState = createInterviewSessionQuestions(
    sessionState.activeSession,
    sessionState.currentQuestionIndex,
  );
  const statusState = createInterviewSessionStatus({
    activeSession: sessionState.activeSession,
    completing: input.completing,
    currentQuestionIndex: sessionState.currentQuestionIndex,
    hasCurrentQuestion: questionState.hasCurrentQuestion,
    loading: input.loading,
    response: input.response,
    sessionId: sessionState.sessionId,
    sessionLoadError: input.sessionLoadError,
    stt: input.stt,
    submitting: input.submitting,
    t: input.t,
    totalQuestions: sessionState.totalQuestions,
  });
  const progressState = createInterviewSessionProgressState({
    activeSession: sessionState.activeSession,
    currentQuestionIndex: sessionState.currentQuestionIndex,
    isLastQuestion: statusState.isLastQuestion,
    t: input.t,
    totalQuestions: sessionState.totalQuestions,
  });

  return {
    ...questionState,
    ...progressState,
    activeSession: sessionState.activeSession,
    canComplete: statusState.canComplete,
    canSubmit: statusState.canSubmit,
    canUseVoice: sessionState.canUseVoice,
    completionState: statusState.completionState,
    currentQuestionIndex: sessionState.currentQuestionIndex,
    enableVoiceMode: sessionState.enableVoiceMode,
    isLastQuestion: statusState.isLastQuestion,
    sessionId: sessionState.sessionId,
    totalQuestions: sessionState.totalQuestions,
  };
}

function createInterviewSessionIdentity(input: ReturnType<typeof createInterviewSessionState>) {
  const sessionId = computed(() =>
    normalizeSessionIdFromQuery(
      input.route.query[APP_ROUTE_QUERY_KEYS.sessionId] ??
        input.route.query[APP_ROUTE_QUERY_KEYS.id],
    ),
  );
  const activeSession = computed(() => {
    const id = sessionId.value;
    if (!id) {
      return null;
    }
    const session = input.currentSession.value;
    if (!session || session.id !== id) {
      return null;
    }
    return session;
  });
  const enableVoiceMode = computed(() => activeSession.value?.config?.enableVoiceMode ?? false);
  const totalQuestions = computed(() => activeSession.value?.questions.length ?? 0);
  const currentQuestionIndex = computed(() => activeSession.value?.currentQuestionIndex ?? 0);
  const canUseVoice = computed(() => enableVoiceMode.value && input.stt.isSupported.value);
  return {
    activeSession,
    canUseVoice,
    currentQuestionIndex,
    enableVoiceMode,
    sessionId,
    totalQuestions,
  };
}

function createInterviewSessionProgressState(input: {
  activeSession: ComputedRef<ReturnType<typeof useInterview>["currentSession"]["value"] | null>;
  currentQuestionIndex: ComputedRef<number>;
  isLastQuestion: ComputedRef<boolean>;
  t: ReturnType<typeof useI18n>["t"];
  totalQuestions: ComputedRef<number>;
}) {
  const progress = computed(() => {
    if (!(input.totalQuestions.value && input.activeSession.value)) {
      return 0;
    }
    const current = Math.min(input.currentQuestionIndex.value, input.totalQuestions.value - 1);
    return ((current + 1) / input.totalQuestions.value) * PERCENT_MAX;
  });
  const displayQuestionIndex = computed(() =>
    input.totalQuestions.value === 0
      ? 0
      : Math.min(input.currentQuestionIndex.value + 1, input.totalQuestions.value),
  );
  const submitButtonLabelKey = computed(() =>
    input.isLastQuestion.value
      ? "interviewSession.submitFinishButton"
      : "interviewSession.submitNextButton",
  );
  const chatSubmitHint = computed(() =>
    input.t("interviewSession.minResponseHint", { count: INTERVIEW_MIN_RESPONSE_LENGTH }),
  );
  const sessionProgressLabel = computed(() =>
    input.t("interviewSession.progressLabel", {
      current: displayQuestionIndex.value,
      total: input.totalQuestions.value,
    }),
  );

  return {
    chatSubmitHint,
    displayQuestionIndex,
    progress,
    sessionProgressLabel,
    submitButtonLabelKey,
  };
}

export function registerInterviewSessionWatchers(input: {
  actions: ReturnType<typeof createInterviewSessionActions>;
  derived: ReturnType<typeof createInterviewSessionDerivedState>;
  response: Ref<string>;
  stt: ReturnType<typeof useSTT>;
  timer: ReturnType<typeof createInterviewSessionTimer>;
  tts: ReturnType<typeof useTTS>;
}) {
  watch(
    () => input.derived.sessionId.value,
    async (nextSessionId) => {
      await input.actions.loadSession(nextSessionId);
    },
    { immediate: true },
  );
  watch(
    () => input.derived.activeSession.value?.status,
    (status) => {
      if (!status || status === "completed" || status === "cancelled") {
        input.timer.stopTimer();
        return;
      }
      if (status === "active" || status === "preparing" || status === "paused") {
        input.timer.startTimer();
      }
    },
  );
  watch(
    () => input.derived.currentQuestion.value?.question,
    (question) => {
      if (input.derived.enableVoiceMode.value && question && input.tts.isSupported.value) {
        input.tts.speak(question);
      }
    },
    { immediate: true },
  );
  watch(
    () => input.stt.fullTranscript.value,
    (transcript) => {
      if (input.derived.canUseVoice.value && transcript) {
        input.response.value = transcript;
      }
    },
  );
}

export function buildInterviewSessionViewModel(input: {
  actions: ReturnType<typeof createInterviewSessionActions>;
  derived: ReturnType<typeof createInterviewSessionDerivedState>;
  state: ReturnType<typeof createInterviewSessionState>;
  timer: ReturnType<typeof createInterviewSessionTimer>;
}) {
  return {
