import type { ResumeTabId } from "~/components/resume/resume-page-contracts";

export const RESUME_CREATE_DIALOG_TITLE_ID = "resume-page-create-dialog-title";
export const RESUME_EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type DeepReadonly<T> = T extends (...args: never[]) => unknown
  ? T
  : T extends readonly (infer U)[]
    ? readonly DeepReadonly<U>[]
    : T extends object
      ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
      : T;

export type DashboardStatsView = DeepReadonly<DashboardStats>;

export const createResumeFormData = (): ResumeFormData => ({
  name: "",
  email: "",
  phone: "",
  location: "",
  summary: "",
  linkedIn: "",
  portfolio: "",
  template: "modern",
  experience: [],
  education: [],
  skills: [],
  projects: [],
  gaming: {
    roles: [],
    genres: [],
    achievements: [],
  },
});

export function hasNonEmptyGamingValue(value: string | string[]): boolean {
  if (Array.isArray(value)) {
    return value.some((entry) => typeof entry === "string" && entry.trim().length > 0);
  }
  return value.trim().length > 0;
}

export function cloneDashboardStats(
  stats: DashboardStats | DashboardStatsView | null,
): DashboardStats | null {
  if (!stats) {
    return null;
  }

  return {
    profile: { ...stats.profile },
    jobs: { ...stats.jobs },
    resumes: { ...stats.resumes },
    coverLetters: { ...stats.coverLetters },
    portfolio: { ...stats.portfolio },
    interviews: { ...stats.interviews },
    skills: { ...stats.skills },
    ai: { ...stats.ai },
    gamification: { ...stats.gamification },
    automation: {
      ...stats.automation,
      recentRuns: stats.automation.recentRuns.map((run) => ({ ...run })),
    },
  };
}

type ResumePageBootstrapInput = {
  fetchDashboard: () => Promise<void>;
  fetchResumes: () => Promise<void>;
  getResume: (id: string) => Promise<unknown>;
  route: RouteLocationNormalizedLoaded;
};

function createResumePageBootstrapState() {
  const {
    showDeleteDialog: showDeleteResumeDialog,
    pendingDeleteId: pendingDeleteResumeId,
    requestDelete: requestDeleteResume,
    clearDeleteState: clearDeleteResumeState,
    closeDeleteDialog: closeDeleteResumeDialog,
  } = useDeleteConfirmation();

  return {
    activeTab: ref<ResumeTabId>("personal"),
    clearDeleteResumeState,
    closeDeleteResumeDialog,
    creating: ref(false),
    enhancing: ref(false),
    formData: reactive<ResumeFormData>(createResumeFormData()),
    newResumeName: ref(""),
    newResumeTemplate: ref<ResumeTemplate>(RESUME_TEMPLATE_DEFAULT),
    pendingDeleteResumeId,
    requestDeleteResume,
    resumeSearchQuery: ref(""),
    scoring: ref(false),
    selectedResumeId: ref<string | null>(null),
    showCreateModal: ref(false),
    showDeleteResumeDialog,
  };
}

function syncSelectedResumeIdFromRoute(
  route: RouteLocationNormalizedLoaded,
  selectedResumeId: Ref<string | null>,
) {
  const id = route.query[APP_ROUTE_QUERY_KEYS.id];
  if (typeof id === "string" && id.trim()) {
    selectedResumeId.value = id.trim();
  }
}

export function useResumePageBootstrap({
  fetchDashboard,
  fetchResumes,
  getResume,
  route,
}: ResumePageBootstrapInput) {
  const state = createResumePageBootstrapState();

  const {
    error: resumeBootstrapError,
    status: resumeBootstrapStatus,
    refresh: refreshResumeBootstrap,
  } = useAsyncData("resume-page-bootstrap", async () => {
    await fetchResumes();
    await fetchDashboard();
    syncSelectedResumeIdFromRoute(route, state.selectedResumeId);

    return true;
  });

  watch(state.selectedResumeId, async (id) => {
    if (!id) {
      return;
    }

    const resume = await getResume(id);
    if (resume) {
      Object.assign(state.formData, resumeDataToFormData(resume));
    }
  });

  return {
    activeTab: state.activeTab,
    clearDeleteResumeState: state.clearDeleteResumeState,
    closeDeleteResumeDialog: state.closeDeleteResumeDialog,
    creating: state.creating,
    enhancing: state.enhancing,
    formData: state.formData,
    newResumeName: state.newResumeName,
    newResumeTemplate: state.newResumeTemplate,
    pendingDeleteResumeId: state.pendingDeleteResumeId,
    refreshResumeBootstrap,
    requestDeleteResume: state.requestDeleteResume,
    resumeBootstrapError,
    resumeBootstrapStatus,
    resumeSearchQuery: state.resumeSearchQuery,
    scoring: state.scoring,
    selectedResumeId: state.selectedResumeId,
    showCreateModal: state.showCreateModal,
    showDeleteResumeDialog: state.showDeleteResumeDialog,
  };
}

import {
  RESUME_LIST_PAGE_SIZE,
  RESUME_TEMPLATE_DEFAULT,
  RESUME_TEMPLATE_OPTIONS,
} from "@bao/shared/constants/resume";
import { APP_ROUTE_QUERY_KEYS, APP_ROUTES } from "@bao/shared/constants/routes";
import type { ResumeFormData } from "@bao/shared/utils/resume-transform";
import type { Ref } from "vue";
import type { Composer, ComposerTranslation } from "vue-i18n";
import {
  RESUME_TABS,
  type ResumeCompletionQuickAction,
  type ResumeTabId,
} from "~/components/resume/resume-page-contracts";
import {
  cloneDashboardStats,
  type DashboardStatsView,
  hasNonEmptyGamingValue,
} from "~/composables/resume-page-bootstrap";
import { createFlowEngineInput } from "~/constants/flow-engine";
import { PERCENT_MAX, UI_CHIP_OVERFLOW_THRESHOLD } from "~/constants/numeric-ui";

type ResumePageDerivedInput = {
  dashboardStats: Ref<DashboardStatsView | null>;
  formData: ResumeFormData;
  resumeSearchQuery: Ref<string>;
  resumes: Ref<
    readonly {
      readonly id?: string;
      readonly name?: string;
      readonly template?: string;
      readonly isDefault?: boolean;
    }[]
  >;
  selectedResumeId: Ref<string | null>;
};

function useResumeTemplateOptions(i18n: Composer) {
  const templateLabelMap = computed<Record<string, string>>(() =>
    RESUME_TEMPLATE_OPTIONS.reduce<Record<string, string>>((labels, template) => {
      labels[template] = i18n.t(`resumePage.createModal.templates.${template}`);
      return labels;
    }, {}),
  );

  return {
    createResumeTemplateOptions: computed(() =>
      RESUME_TEMPLATE_OPTIONS.map((template) => ({
        value: template,
        label: templateLabelMap.value[template] ?? template,
      })),
    ),
    templateLabelMap,
  };
}

function useResumeCompletionState(formData: ResumeFormData) {
  const resumeSectionCompletion = computed(() => {
    const personalComplete =
      formData.name.trim().length > 0 &&
      formData.email.trim().length > 0 &&
      formData.summary.trim().length > 0;
    const experienceComplete =
      formData.experience.length > 0 &&
      formData.experience.every(
        (item) =>
          item.title.trim().length > 0 &&
          item.company.trim().length > 0 &&
          item.description.trim().length > 0,
      );
    const educationComplete =
      formData.education.length > 0 &&
      formData.education.every(
        (item) => item.degree.trim().length > 0 && item.school.trim().length > 0,
      );
    const skillsComplete = formData.skills.length > 0;
    const projectsComplete =
      formData.projects.length > 0 &&
      formData.projects.every(
        (item) => item.name.trim().length > 0 && item.description.trim().length > 0,
      );
    const gamingComplete =
      hasNonEmptyGamingValue(formData.gaming.roles) ||
      hasNonEmptyGamingValue(formData.gaming.genres) ||
      hasNonEmptyGamingValue(formData.gaming.achievements);

    return [
      { id: RESUME_TABS[0], completed: personalComplete },
      { id: RESUME_TABS[1], completed: experienceComplete },
      { id: RESUME_TABS[2], completed: educationComplete },
      { id: RESUME_TABS[3], completed: skillsComplete },
      { id: RESUME_TABS[4], completed: projectsComplete },
      { id: RESUME_TABS[5], completed: gamingComplete },
    ];
  });
  const completedSectionCount = computed(
    () => resumeSectionCompletion.value.filter((section) => section.completed).length,
  );

  return {
    completedSectionCount,
    completionPercent: computed(() => {
      const total = resumeSectionCompletion.value.length;
      if (total === 0) {
        return 0;
      }
      return Math.round((completedSectionCount.value / total) * PERCENT_MAX);
    }),
    nextRecommendedTab: computed<ResumeTabId | null>(() => {
      const incomplete = resumeSectionCompletion.value.find((section) => !section.completed);
      return incomplete ? incomplete.id : null;
    }),
    resumeSectionCompletion,
  };
}

function useResumeSearch(
  resumes: ResumePageDerivedInput["resumes"],
  resumeSearchQuery: ResumePageDerivedInput["resumeSearchQuery"],
  t: ComposerTranslation,
) {
  const filteredResumes = computed(() => {
    const query = resumeSearchQuery.value.trim().toLowerCase();
    if (!query) {
      return resumes.value;
    }

    return resumes.value.filter((resume) => {
      const name = (resume.name || "").toLowerCase();
      const template = (resume.template || "").toLowerCase();
      return name.includes(query) || template.includes(query);
    });
  });
  const resumePagination = usePagination(filteredResumes, RESUME_LIST_PAGE_SIZE, [
    resumeSearchQuery,
  ]);

  return {
    filteredResumes,
    hasResumeFiltersApplied: computed(() => resumeSearchQuery.value.trim().length > 0),
    resumePageAria(page: number): string {
      return t("resumePage.pagination.pageAria", { page });
    },
    resumePagination,
    resumePaginationSummary: computed(() =>
      t("resumePage.pagination.summary", {
        start: resumePagination.rangeStart.value,
        end: resumePagination.rangeEnd.value,
        total: resumePagination.totalItems.value,
      }),
    ),
  };
}

function useResumeCompletionQuickActions(
  dashboardStats: ResumePageDerivedInput["dashboardStats"],
  resumes: ResumePageDerivedInput["resumes"],
  selectedResumeId: ResumePageDerivedInput["selectedResumeId"],
) {
  const coverLetterQuickActionRoute = computed(() => ({
    path: APP_ROUTES.coverLetter,
    ...(selectedResumeId.value
      ? {
          query: {
            [APP_ROUTE_QUERY_KEYS.resumeId]: selectedResumeId.value,
          },
        }
      : {}),
  }));
  const flowInput = computed(() =>
    createFlowEngineInput(cloneDashboardStats(dashboardStats.value), {
      hasResume: resumes.value.length > 0,
    }),
  );
  const { primaryAction: flowPrimaryAction, recommendedActions: flowRecommendedActions } =
    useFlowEngine(flowInput);

  return computed<readonly ResumeCompletionQuickAction[]>(() => {
    const actionCandidates = [flowPrimaryAction.value, ...flowRecommendedActions.value]
      .filter((action) => action.id !== "resume")
      .slice(0, UI_CHIP_OVERFLOW_THRESHOLD);

    return actionCandidates.map((action) => ({
      id: action.id,
      to: action.id === "coverLetter" ? coverLetterQuickActionRoute.value : action.to,
      labelKey: action.labelKey,
    }));
  });
}

function createResumeTabLabels(t: ComposerTranslation) {
  function tabLabel(tab: ResumeTabId): string {
    if (tab === "personal") return t("resumePage.tabs.personal");
    if (tab === "experience") return t("resumePage.tabs.experience");
    if (tab === "education") return t("resumePage.tabs.education");
    if (tab === "skills") return t("resumePage.tabs.skills");
    if (tab === "projects") return t("resumePage.tabs.projects");
    return t("resumePage.tabs.gaming");
  }

  return {
    resumeTabAriaLabel(tab: ResumeTabId): string {
      return t("resumePage.tabs.selectAria", { tab: tabLabel(tab) });
    },
    resumeTabLabel(tab: ResumeTabId): string {
      return tabLabel(tab);
    },
  };
}

export function useResumePageDerived(
  input: ResumePageDerivedInput,
  i18n: Composer,
  t: ComposerTranslation,
) {
  const templates = useResumeTemplateOptions(i18n);
  const labels = createResumeTabLabels(t);

  const aiEnhancementStepLabels = computed(
    () =>
      [
        t("resumePage.aiSteps.analyzing"),
        t("resumePage.aiSteps.enhancing"),
        t("resumePage.aiSteps.finalizing"),
      ] as const,
  );

  const completion = useResumeCompletionState(input.formData);
  const search = useResumeSearch(input.resumes, input.resumeSearchQuery, t);
  const completionQuickActions = useResumeCompletionQuickActions(
    input.dashboardStats,
    input.resumes,
    input.selectedResumeId,
  );

  function resumeTemplateLabel(template?: string): string {
    if (!template) {
      return templates.templateLabelMap.value[RESUME_TEMPLATE_DEFAULT] ?? RESUME_TEMPLATE_DEFAULT;
    }
    return RESUME_TEMPLATE_OPTIONS.some((option) => option === template)
      ? (templates.templateLabelMap.value[template] ?? template)
      : template;
  }

  return {
    aiEnhancementStepLabels,
    completedSectionCount: completion.completedSectionCount,
    completionPercent: completion.completionPercent,
    completionQuickActions,
    createResumeTemplateOptions: templates.createResumeTemplateOptions,
    filteredResumes: search.filteredResumes,
    hasResumeFiltersApplied: search.hasResumeFiltersApplied,
    nextRecommendedTab: completion.nextRecommendedTab,
    resumePageAria: (page: number) => search.resumePageAria(page),
    resumePagination: search.resumePagination,
    resumePaginationSummary: search.resumePaginationSummary,
    resumeSectionCompletion: completion.resumeSectionCompletion,
    resumeTabAriaLabel: (tab: ResumeTabId) => labels.resumeTabAriaLabel(tab),
    resumeTabLabel: (tab: ResumeTabId) => labels.resumeTabLabel(tab),
    resumeTemplateLabel,
  };
}

import { formDataToResumeData, resumeDataToFormData } from "@bao/shared/utils/resume-transform";
import type { Ref } from "vue";
import type { ComposerTranslation } from "vue-i18n";
import type { NuxtApp } from "#app";
import { settlePromise } from "~/composables/async-flow";
import type { ResumePageActionsInput } from "~/composables/resume-page-actions-contracts";
import { RESUME_EMAIL_PATTERN } from "~/composables/resume-page-bootstrap";
import {
  RESUME_AUTOSAVE_DEBOUNCE_MS,
  RESUME_DESCRIPTION_MIN_CHARS,
  RESUME_SUMMARY_MIN_CHARS,
} from "~/constants/numeric-ui";
import { getErrorMessage } from "~/utils/errors";

type ResumeEditorSupport = {
  progress: ReturnType<typeof useAiEnhancementProgress>;
  resolveReward: ReturnType<typeof useResumeRewardResolver>;
  validate: ReturnType<typeof useResumeFormValidation>;
};

type ResumeActionFeedback = {
  $toast: Pick<NuxtApp["$toast"], "error" | "success">;
  t: ComposerTranslation;
};

type ResumeEnhanceActionInput = Pick<
  ResumePageActionsInput,
  "aiEnhance" | "enhancing" | "formData" | "selectedResumeId"
>;

type ResumeScoreActionInput = Pick<
  ResumePageActionsInput,
  "aiScore" | "analyzeResume" | "scoring" | "selectedResumeId"
>;

type ResumeSaveActionInput = Pick<
  ResumePageActionsInput,
  "formData" | "selectedResumeId" | "updateResume"
>;

export function useAiEnhancementProgress(aiEnhancementStepLabels: Ref<readonly string[]>) {
  const aiEnhancementStepIndex = ref(0);
  let aiEnhancementTimer: number | null = null;

  onUnmounted(() => {
    if (!aiEnhancementTimer) {
      return;
    }
    window.clearInterval(aiEnhancementTimer);
    aiEnhancementTimer = null;
  });

  function startAiEnhancementProgress(): void {
    aiEnhancementStepIndex.value = 0;
    if (aiEnhancementTimer) {
      window.clearInterval(aiEnhancementTimer);
    }
    aiEnhancementTimer = window.setInterval(() => {
      if (aiEnhancementStepIndex.value < aiEnhancementStepLabels.value.length - 1) {
        aiEnhancementStepIndex.value += 1;
      }
    }, RESUME_AUTOSAVE_DEBOUNCE_MS);
  }

  function stopAiEnhancementProgress(): void {
    if (aiEnhancementTimer) {
      window.clearInterval(aiEnhancementTimer);
      aiEnhancementTimer = null;
    }
    aiEnhancementStepIndex.value = 0;
  }

  return {
    aiEnhancementStepIndex,
    startAiEnhancementProgress,
    stopAiEnhancementProgress,
  };
}

export function useResumeRewardResolver(
  awardForAction: ResumePageActionsInput["awardForAction"],
  t: ComposerTranslation,
) {
  return async (action: "resumeSave" | "resumeEnhance"): Promise<number | null> => {
    const rewardResult = await settlePromise(
      awardForAction(action),
      t("apiErrors.gamification.awardXPFailed"),
    );
    if (!rewardResult.ok) {
      return null;
    }
    return rewardResult.value.awarded ? rewardResult.value.amount : null;
  };
}

export function useResumeFormValidation(
  formData: ResumePageActionsInput["formData"],
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;

  function validateResumeForm(): boolean {
    if (formData.name.trim().length < 2) {
      $toast.error(t("resumePage.toasts.nameMinLength"));
      return false;
    }
    if (!RESUME_EMAIL_PATTERN.test(formData.email.trim())) {
      $toast.error(t("resumePage.toasts.invalidEmail"));
      return false;
    }
    if (formData.summary.trim().length < RESUME_SUMMARY_MIN_CHARS) {
      $toast.error(t("resumePage.toasts.summaryMinLength"));
      return false;
    }

    const hasInvalidExperience = formData.experience.some(
      (item) =>
        item.title.trim().length < 2 ||
        item.company.trim().length < 2 ||
        item.description.trim().length < RESUME_DESCRIPTION_MIN_CHARS,
    );
    if (hasInvalidExperience) {
      $toast.error(t("resumePage.toasts.invalidExperience"));
      return false;
    }

    const hasInvalidEducation = formData.education.some(
      (item) => item.degree.trim().length < 2 || item.school.trim().length < 2,
    );
    if (hasInvalidEducation) {
      $toast.error(t("resumePage.toasts.invalidEducation"));
      return false;
    }

    const hasInvalidProjects = formData.projects.some(
      (item) =>
        item.name.trim().length < 2 ||
        item.description.trim().length < RESUME_DESCRIPTION_MIN_CHARS,
    );
    if (hasInvalidProjects) {
      $toast.error(t("resumePage.toasts.invalidProjects"));
      return false;
    }

    return true;
  }

  return { validateResumeForm };
}

export function useResumeEditorActions(
  input: Pick<
    ResumePageActionsInput,
    | "aiEnhance"
    | "aiScore"
    | "analyzeResume"
    | "enhancing"
    | "formData"
    | "scoring"
    | "selectedResumeId"
    | "updateResume"
  >,
  support: ResumeEditorSupport,
  feedback: { nuxtApp: Pick<NuxtApp, "$toast">; t: ComposerTranslation },
) {
  const { $toast } = feedback.nuxtApp;
  const { t } = feedback;

  const handleAIEnhance = createResumeEnhanceAction(input, support, { $toast, t });
  const handleAIScore = createResumeScoreAction(input, { $toast, t });
  const handleSave = createResumeSaveAction(input, support, { $toast, t });

  return {
    handleAIEnhance,
    handleAIScore,
    handleSave,
  };
}

function createResumeEnhanceAction(
  input: ResumeEnhanceActionInput,
  support: ResumeEditorSupport,
  feedback: ResumeActionFeedback,
) {
  return async function handleAIEnhance(): Promise<void> {
    if (!input.selectedResumeId.value) {
      return;
    }

    input.enhancing.value = true;
    support.progress.startAiEnhancementProgress();
    const enhanceResult = await settlePromise(
      input.aiEnhance(input.selectedResumeId.value),
      feedback.t("resumePage.toasts.resumeEnhanceFailed"),
    );
    support.progress.stopAiEnhancementProgress();
    input.enhancing.value = false;

    if (!enhanceResult.ok) {
      feedback.$toast.error(
        getErrorMessage(enhanceResult.error, feedback.t("resumePage.toasts.resumeEnhanceFailed")),
      );
      return;
    }

    Object.assign(input.formData, resumeDataToFormData(enhanceResult.value));
    const reward = await support.resolveReward("resumeEnhance");
    feedback.$toast.success(
      reward
        ? feedback.t("resumePage.toasts.resumeEnhancedWithXp", { xp: reward })
        : feedback.t("resumePage.toasts.resumeEnhanced"),
    );
  };
}

function createResumeScoreAction(input: ResumeScoreActionInput, feedback: ResumeActionFeedback) {
  return async function handleAIScore(): Promise<void> {
    if (!input.selectedResumeId.value) {
      return;
    }

    input.scoring.value = true;
    const scoreSubmission = await settlePromise(
      input.aiScore(input.selectedResumeId.value, ""),
      feedback.t("resumePage.toasts.resumeScoreFailed"),
    );
    input.scoring.value = false;

    if (!scoreSubmission.ok) {
      feedback.$toast.error(
        getErrorMessage(scoreSubmission.error, feedback.t("resumePage.toasts.resumeScoreFailed")),
      );
      return;
    }

    await settlePromise(
      input.analyzeResume(input.selectedResumeId.value),
      feedback.t("apiErrors.ai.analyzeResumeFailed"),
    );
    feedback.$toast.success(feedback.t("resumePage.toasts.resumeScored"));
  };
}

function createResumeSaveAction(
  input: ResumeSaveActionInput,
  support: Pick<ResumeEditorSupport, "resolveReward" | "validate">,
  feedback: ResumeActionFeedback,
) {
  return async function handleSave(): Promise<void> {
    const resumeId = input.selectedResumeId.value;
    if (!(resumeId && support.validate.validateResumeForm())) {
      return;
    }

    const saveResult = await settlePromise(
      (async () => {
        await input.updateResume(resumeId, formDataToResumeData(input.formData));
        return support.resolveReward("resumeSave");
      })(),
      feedback.t("resumePage.toasts.resumeSaveFailed"),
    );
    if (!saveResult.ok) {
      feedback.$toast.error(
        getErrorMessage(saveResult.error, feedback.t("resumePage.toasts.resumeSaveFailed")),
      );
      return;
    }

    const reward = saveResult.value;
    feedback.$toast.success(
      reward
        ? feedback.t("resumePage.toasts.resumeSavedWithXp", { xp: reward })
        : feedback.t("resumePage.toasts.resumeSaved"),
    );
  };
}

import type { ComposerTranslation } from "vue-i18n";
import type { NuxtApp } from "#app";
import { settlePromise } from "~/composables/async-flow";
import type { ResumePageActionsInput } from "~/composables/resume-page-actions-contracts";
import { getErrorMessage } from "~/utils/errors";

function createResumeCreationPayload(
  name: string,
  template: ResumePageActionsInput["newResumeTemplate"]["value"],
): Parameters<ResumePageActionsInput["createResume"]>[0] {
  return {
    name,
    template,
    personalInfo: {},
    experience: [],
    education: [],
    skills: {},
    projects: [],
    gamingExperience: {},
  };
}

function resolveCreatedResumeId(
  result: Awaited<ReturnType<ResumePageActionsInput["createResume"]>>,
): string | null {
  if (
    typeof result === "object" &&
    result !== null &&
    "id" in result &&
    typeof result.id === "string"
  ) {
    return result.id;
  }
  return null;
}

function createResumeCreateAction(
  input: Pick<
    ResumePageActionsInput,
    | "createResume"
    | "creating"
    | "newResumeName"
    | "newResumeTemplate"
    | "selectedResumeId"
    | "showCreateModal"
  >,
  feedback: {
    $toast: Pick<NuxtApp["$toast"], "error" | "success">;
    t: ComposerTranslation;
  },
) {
  return async function handleCreate(): Promise<void> {
    if (!input.newResumeName.value.trim()) {
      return;
    }
    if (input.newResumeName.value.trim().length < 2) {
      feedback.$toast.error(feedback.t("resumePage.toasts.resumeNameMinLength"));
      return;
    }

    input.creating.value = true;
    const createResult = await settlePromise(
      input.createResume(
        createResumeCreationPayload(input.newResumeName.value, input.newResumeTemplate.value),
      ),
      feedback.t("resumePage.toasts.resumeCreateFailed"),
    );
    input.creating.value = false;

    if (!createResult.ok) {
      feedback.$toast.error(
        getErrorMessage(createResult.error, feedback.t("resumePage.toasts.resumeCreateFailed")),
      );
      return;
    }

    input.showCreateModal.value = false;
    input.newResumeName.value = "";
    input.selectedResumeId.value = resolveCreatedResumeId(createResult.value);
    feedback.$toast.success(feedback.t("resumePage.toasts.resumeCreated"));
  };
}

function createResumeDeleteAction(
  input: Pick<
    ResumePageActionsInput,
    "closeDeleteResumeDialog" | "deleteResume" | "pendingDeleteResumeId" | "selectedResumeId"
  >,
  feedback: {
    $toast: Pick<NuxtApp["$toast"], "error" | "success">;
    t: ComposerTranslation;
  },
) {
  return async function handleDeleteResume(): Promise<void> {
    const id = input.pendingDeleteResumeId.value;
    if (!id) {
      return;
    }

    const deleteResult = await settlePromise(
      input.deleteResume(id),
      feedback.t("resumePage.toasts.resumeDeleteFailed"),
    );
    input.closeDeleteResumeDialog();

    if (!deleteResult.ok) {
      feedback.$toast.error(
        getErrorMessage(deleteResult.error, feedback.t("resumePage.toasts.resumeDeleteFailed")),
      );
      return;
    }

    if (input.selectedResumeId.value === id) {
      input.selectedResumeId.value = null;
    }
    feedback.$toast.success(feedback.t("resumePage.toasts.resumeDeleted"));
  };
}

export function useResumeMutationActions(
  {
    closeDeleteResumeDialog,
    createResume,
    creating,
    deleteResume,
    newResumeName,
    newResumeTemplate,
    pendingDeleteResumeId,
    selectedResumeId,
    showCreateModal,
  }: Pick<
    ResumePageActionsInput,
    | "closeDeleteResumeDialog"
    | "createResume"
    | "creating"
    | "deleteResume"
    | "newResumeName"
    | "newResumeTemplate"
    | "pendingDeleteResumeId"
    | "selectedResumeId"
    | "showCreateModal"
  >,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;
  const feedback = { $toast, t };
  const handleCreate = createResumeCreateAction(
    {
      createResume,
      creating,
      newResumeName,
      newResumeTemplate,
      selectedResumeId,
      showCreateModal,
    },
    feedback,
  );
  const handleDeleteResume = createResumeDeleteAction(
    {
      closeDeleteResumeDialog,
      deleteResume,
      pendingDeleteResumeId,
      selectedResumeId,
    },
    feedback,
  );

  return {
    handleCreate,
    handleDeleteResume,
  };
}

