import { AI_CHAT_ROUTE_QUERY_KEYS } from "@bao/shared/constants/ai-chat";
import { useI18n } from "vue-i18n";
import { settlePromise } from "~/composables/async-flow";
import { queryValueToString } from "~/utils/route-query";

/**
 * Resolves the studio referenced by `?studio=<id>` into the shared current-studio
 * state.
 *
 * Only the studio detail page used to populate that state, so any other surface
 * reached with a studio in the route (AI chat, resume, cover letter, interview)
 * had an id but no studio record. The AI context then fell back to rendering the
 * raw slug — "riot-games" instead of "Riot Games" — in user-facing copy, and any
 * tailoring that needs studio attributes (culture, tech stack, interview process)
 * had nothing to read.
 */
export const useRouteStudioContext = (): void => {
  const route = useRoute();
  const { t } = useI18n();
  const { currentStudio, getStudio } = useStudio();

  const routeStudioId = computed(() =>
    queryValueToString(route.query[AI_CHAT_ROUTE_QUERY_KEYS.studioId]).trim(),
  );

  const hydrateRouteStudio = (studioId: string): void => {
    if (studioId.length === 0 || currentStudio.value?.id === studioId) {
      return;
    }
    // Fire-and-settle: a missing or deleted studio leaves the context on the id,
    // which the surfaces already render, so it must not break the page.
    settlePromise(getStudio(studioId), t("apiErrors.studios.fetchFailed")).then(
      () => undefined,
      () => undefined,
    );
  };

  watch(routeStudioId, hydrateRouteStudio, { immediate: true });
};

import type { RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import { describe, expect, it } from "vitest";
import { DATE_FORMAT_OPTIONS, resolveScheduledRunAt, toIsoTimestamp } from "./schedule-timestamp";

const createEnvelope = (
  overrides: Pick<RpaRunExecutionEnvelope, "createdAt" | "input">,
): RpaRunExecutionEnvelope => ({
  id: "019f7bcf-0000-7000-8000-000000000001",
  type: "job_apply",
  status: "pending",
  jobId: null,
  userId: null,
  input: overrides.input,
  output: null,
  screenshots: null,
  error: null,
  progress: null,
  currentStep: null,
  totalSteps: null,
  startedAt: null,
  completedAt: null,
  createdAt: overrides.createdAt,
  updatedAt: overrides.createdAt,
  exitCode: null,
  timedOut: false,
  aborted: false,
  executionMs: null,
});

describe("schedule-timestamp SSOT", () => {
  it("exposes canonical medium date+time options", () => {
    expect(DATE_FORMAT_OPTIONS).toEqual({ dateStyle: "medium", timeStyle: "short" });
  });

  it("resolves schedule.runAt when present", () => {
    const runAt = "2026-07-20T12:00:00.000Z";
    expect(
      resolveScheduledRunAt(
        createEnvelope({
          createdAt: "2026-07-19T12:00:00.000Z",
          input: { schedule: { runAt } },
        }),
      ),
    ).toBe(runAt);
  });

  it("falls back to createdAt without schedule input", () => {
    expect(
      resolveScheduledRunAt(
        createEnvelope({
          createdAt: "2026-07-19T12:00:00.000Z",
          input: null,
        }),
      ),
    ).toBe("2026-07-19T12:00:00.000Z");
  });

  it("rejects past or invalid datetime-local values", () => {
    expect(toIsoTimestamp("not-a-date")).toBeNull();
    expect(toIsoTimestamp("2000-01-01T00:00")).toBeNull();
  });
});

import type { RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import { isRecord } from "@bao/shared/utils/type-guards";

/** Canonical medium date+time formatting for automation schedule surfaces. */
export const DATE_FORMAT_OPTIONS = {
  dateStyle: "medium",
  timeStyle: "short",
} as const satisfies Intl.DateTimeFormatOptions;

/**
 * Resolves the scheduled run-at timestamp from an RPA envelope, falling back to createdAt.
 */
export const resolveScheduledRunAt = (run: RpaRunExecutionEnvelope): string => {
  const runInput = run.input;
  if (!(runInput && isRecord(runInput))) {
    return run.createdAt;
  }
  const scheduleValue = runInput.schedule;
  if (!isRecord(scheduleValue)) {
    return run.createdAt;
  }
  return typeof scheduleValue.runAt === "string" && scheduleValue.runAt.length > 0
    ? scheduleValue.runAt
    : run.createdAt;
};

/**
 * Parses a datetime-local value into a future ISO timestamp, or null when invalid/past.
 */
export const toIsoTimestamp = (dateTimeLocal: string): string | null => {
  const parsed = new Date(dateTimeLocal);
  if (Number.isNaN(parsed.getTime()) || parsed.getTime() <= Date.now()) {
    return null;
  }
  return parsed.toISOString();
};

