import { toSkillMapping } from "~/composables/api-normalizer-skills";
import { settlePromise } from "~/composables/async-flow";
import {
  SKILLS_DEFAULT_CATEGORY,
  SKILLS_DEFAULT_CONFIDENCE,
  SKILLS_DEFAULT_DEMAND_LEVEL,
  SKILLS_GAMIFICATION_REASONS,
  SKILLS_GAMIFICATION_XP,
  SKILLS_MIN_GAME_EXPRESSION_LENGTH,
  SKILLS_MIN_TRANSFERABLE_SKILL_LENGTH,
  type SkillsGamificationReason,
} from "~/constants/skills";
import { getErrorMessage } from "~/utils/errors";

export interface NewSkillMappingFormState {
  gameExpression: string;
  transferableSkill: string;
  industryApplications: string[];
  confidence: number;
  category: SkillCategory;
}

type SkillsPageActionsInput = {
  api: ReturnType<typeof useApi>;
  toast: {
    error: (message: string) => void;
    success: (message: string) => void;
  };
  t: (key: string, params?: Record<string, string | number>) => string;
  awardXP: (amount: number, reason: string) => Promise<unknown>;
  fetchProgress: () => Promise<unknown>;
  mappings: Ref<SkillMapping[]>;
  loading: Ref<boolean>;
  analyzing: Ref<boolean>;
  pageError: Ref<string | null>;
  showAddModal: Ref<boolean>;
  pendingDeleteMappingId: Ref<string | null>;
  closeDeleteMappingDialog: () => void;
  newApplication: Ref<string>;
  newMapping: NewSkillMappingFormState;
};

const DEFAULT_SKILL_FORM_STATE = {
  gameExpression: "",
  transferableSkill: "",
  industryApplications: [],
  confidence: SKILLS_DEFAULT_CONFIDENCE,
  category: SKILLS_DEFAULT_CATEGORY,
} satisfies NewSkillMappingFormState;

function createSkillFormActions(
  newApplication: SkillsPageActionsInput["newApplication"],
  newMapping: SkillsPageActionsInput["newMapping"],
) {
  function resetForm(): void {
    newMapping.gameExpression = DEFAULT_SKILL_FORM_STATE.gameExpression;
    newMapping.transferableSkill = DEFAULT_SKILL_FORM_STATE.transferableSkill;
    newMapping.industryApplications = [...DEFAULT_SKILL_FORM_STATE.industryApplications];
    newMapping.confidence = DEFAULT_SKILL_FORM_STATE.confidence;
    newMapping.category = DEFAULT_SKILL_FORM_STATE.category;
    newApplication.value = "";
  }

  function addApplication(): void {
    const normalizedApplication = newApplication.value.trim();
    if (normalizedApplication.length === 0) {
      return;
    }

    newMapping.industryApplications.push(normalizedApplication);
    newApplication.value = "";
  }

  function removeApplication(index: number): void {
    newMapping.industryApplications.splice(index, 1);
  }

  return {
    addApplication,
    removeApplication,
    resetForm,
  };
}

function createFetchMappingsAction({
  api,
  toast,
  t,
  mappings,
  loading,
  pageError,
}: Pick<SkillsPageActionsInput, "api" | "toast" | "t" | "mappings" | "loading" | "pageError">) {
  async function fetchMappings(): Promise<void> {
    pageError.value = null;
    loading.value = true;
    const mappingsResult = await settlePromise(
      api.skills.mappings.get(),
      t("skillsPage.errors.fetchFailed"),
    );
    loading.value = false;

    if (!mappingsResult.ok) {
      pageError.value = getErrorMessage(mappingsResult.error, t("skillsPage.errors.fetchFailed"));
      toast.error(pageError.value);
      return;
    }

    const { data } = mappingsResult.value;
    mappings.value = Array.isArray(data)
      ? data
          .map((entry) => toSkillMapping(entry))
          .filter((entry): entry is SkillMapping => entry !== null)
      : [];
  }

  return { fetchMappings };
}

function createSkillsGamificationActions(
  input: Pick<SkillsPageActionsInput, "awardXP" | "fetchProgress" | "t">,
) {
  async function syncGamificationProgress(): Promise<void> {
    await settlePromise(input.fetchProgress(), input.t("skillsPage.errors.gamificationLoadFailed"));
  }

  async function tryAwardSkillXp(
    amount: number,
    reason: SkillsGamificationReason,
  ): Promise<boolean> {
    const awardResult = await settlePromise(
      input.awardXP(amount, reason),
      input.t("apiErrors.gamification.awardXPFailed"),
    );
    return awardResult.ok;
  }

  return {
    syncGamificationProgress,
    tryAwardSkillXp,
  };
}

function createSkillsMutationActions(
  input: Pick<
    SkillsPageActionsInput,
    | "api"
    | "toast"
    | "t"
    | "loading"
    | "analyzing"
    | "showAddModal"
    | "pendingDeleteMappingId"
    | "closeDeleteMappingDialog"
    | "newMapping"
  >,
  support: {
    fetchMappings: () => Promise<void>;
    resetForm: () => void;
    tryAwardSkillXp: (amount: number, reason: SkillsGamificationReason) => Promise<boolean>;
  },
) {
  const handleAddMapping = createAddMappingAction(input, support);
  const handleDeleteMapping = createDeleteMappingAction(input, support);
  const handleAIAnalyze = createAnalyzeSkillsAction(input, support);

  return {
    handleAddMapping,
    handleAIAnalyze,
    handleDeleteMapping,
  };
}

function createAddMappingAction(
  input: Pick<
    SkillsPageActionsInput,
    "api" | "toast" | "t" | "loading" | "showAddModal" | "newMapping"
  >,
  support: Pick<Parameters<typeof createSkillsMutationActions>[1], "fetchMappings" | "resetForm">,
) {
  return async function handleAddMapping(): Promise<void> {
    const normalizedGameExpression = input.newMapping.gameExpression.trim();
    if (normalizedGameExpression.length < SKILLS_MIN_GAME_EXPRESSION_LENGTH) {
      input.toast.error(input.t("skillsPage.errors.gameExpressionMinLength"));
      return;
    }

    const normalizedTransferableSkill = input.newMapping.transferableSkill.trim();
    if (normalizedTransferableSkill.length < SKILLS_MIN_TRANSFERABLE_SKILL_LENGTH) {
      input.toast.error(input.t("skillsPage.errors.transferableSkillMinLength"));
      return;
    }

    input.loading.value = true;
    const addMappingResult = await settlePromise(
      (async () => {
        await input.api.skills.mappings.post({
          gameExpression: normalizedGameExpression,
          transferableSkill: normalizedTransferableSkill,
          industryApplications: input.newMapping.industryApplications,
          confidence: input.newMapping.confidence,
          category: input.newMapping.category,
          demandLevel: SKILLS_DEFAULT_DEMAND_LEVEL,
        });
        await support.fetchMappings();
        input.showAddModal.value = false;
        support.resetForm();
      })(),
      input.t("skillsPage.errors.addFailed"),
    );
    input.loading.value = false;

    if (!addMappingResult.ok) {
      input.toast.error(
        getErrorMessage(addMappingResult.error, input.t("skillsPage.errors.addFailed")),
      );
      return;
    }

    input.toast.success(
      input.t("skillsPage.toasts.mappingAddedWithXp", {
        xp: ROUTE_GAMIFICATION_XP.skillsMapped,
      }),
    );
  };
}

function createDeleteMappingAction(
  input: Pick<
    SkillsPageActionsInput,
    "api" | "toast" | "t" | "loading" | "pendingDeleteMappingId" | "closeDeleteMappingDialog"
  >,
  support: Pick<Parameters<typeof createSkillsMutationActions>[1], "fetchMappings">,
) {
  return async function handleDeleteMapping(): Promise<void> {
    const id = input.pendingDeleteMappingId.value;
    if (!id) {
      return;
    }

    input.loading.value = true;
    const deleteResult = await settlePromise(
      (async () => {
        await input.api.skills.mappings({ id }).delete();
        await support.fetchMappings();
      })(),
      input.t("skillsPage.errors.deleteFailed"),
    );
    input.loading.value = false;
    input.closeDeleteMappingDialog();

    if (!deleteResult.ok) {
      input.toast.error(
        getErrorMessage(deleteResult.error, input.t("skillsPage.errors.deleteFailed")),
      );
      return;
    }

    input.toast.success(input.t("skillsPage.toasts.mappingDeleted"));
  };
}

function createAnalyzeSkillsAction(
  input: Pick<SkillsPageActionsInput, "api" | "toast" | "t" | "analyzing">,
  support: Pick<
    Parameters<typeof createSkillsMutationActions>[1],
    "fetchMappings" | "tryAwardSkillXp"
  >,
) {
  return async function handleAIAnalyze(): Promise<void> {
    input.analyzing.value = true;
    const analysisResult = await settlePromise(
      input.api.skills["ai-analyze"].post({}),
      input.t("skillsPage.errors.analysisFailed"),
    );
    input.analyzing.value = false;

    if (!analysisResult.ok) {
      input.toast.error(
        getErrorMessage(analysisResult.error, input.t("skillsPage.errors.analysisFailed")),
      );
      return;
    }

    if (!analysisResult.value.data) {
      return;
    }

    await support.fetchMappings();
    const awardedXp = await support.tryAwardSkillXp(
      SKILLS_GAMIFICATION_XP.aiAnalysisCompleted,
      SKILLS_GAMIFICATION_REASONS.aiAnalysisCompleted,
    );
    input.toast.success(
      awardedXp
        ? input.t("skillsPage.toasts.analysisCompletedWithXp", {
            xp: SKILLS_GAMIFICATION_XP.aiAnalysisCompleted,
          })
        : input.t("skillsPage.toasts.analysisCompleted"),
    );
  };
}

export function createSkillsPageActions(input: SkillsPageActionsInput) {
  const form = createSkillFormActions(input.newApplication, input.newMapping);
  const fetchActions = createFetchMappingsAction(input);
  const gamification = createSkillsGamificationActions(input);
  const mutations = createSkillsMutationActions(input, {
    fetchMappings: fetchActions.fetchMappings,
    resetForm: form.resetForm,
    tryAwardSkillXp: gamification.tryAwardSkillXp,
  });

  async function initializeSkillsPage(): Promise<void> {
    await Promise.all([fetchActions.fetchMappings(), gamification.syncGamificationProgress()]);
  }

  return {
    ...fetchActions,
    ...form,
    ...mutations,
    initializeSkillsPage,
  };
}

import {
  SKILL_CATEGORY_IDS,
  type SkillCategory,
  type SkillMapping,
} from "@bao/shared/types/skill-mapping";
import type { ComputedRef, Ref } from "vue";
import {
  SKILLS_CATEGORY_LABEL_KEYS,
  SKILLS_FILTER_ALL_VALUE,
  SKILLS_TOP_MAPPINGS_PREVIEW_LIMIT,
} from "~/constants/skills";

type SkillsFilterValue = typeof SKILLS_FILTER_ALL_VALUE | SkillCategory;

type SkillsPageDerivedInput = {
  mappings: Ref<SkillMapping[]>;
  categoryFilter: Ref<SkillsFilterValue>;
  searchFilter: Ref<string>;
  level: Ref<number>;
  xp: Ref<number>;
  t: (key: string) => string;
};

function createSkillCategoryOptions(t: SkillsPageDerivedInput["t"]) {
  return computed(() =>
    SKILL_CATEGORY_IDS.map((value) => ({
      value,
      label: t(SKILLS_CATEGORY_LABEL_KEYS[value]),
    })),
  );
}

function createFilteredMappings({
  mappings,
  categoryFilter,
  searchFilter,
}: Pick<SkillsPageDerivedInput, "mappings" | "categoryFilter" | "searchFilter">) {
  return computed(() => {
    const normalizedSearch = searchFilter.value.trim().toLowerCase();
    return mappings.value.filter((mapping) => {
      const categoryMatches =
        categoryFilter.value === SKILLS_FILTER_ALL_VALUE ||
        mapping.category === categoryFilter.value;
      if (!categoryMatches) {
        return false;
      }

      if (normalizedSearch.length === 0) {
        return true;
      }

      const searchableContent = [
        mapping.gameExpression,
        mapping.transferableSkill,
        ...mapping.industryApplications,
      ]
        .join(" ")
        .toLowerCase();

      return searchableContent.includes(normalizedSearch);
    });
  });
}

function createMappingMetrics(mappings: SkillsPageDerivedInput["mappings"]) {
  return computed(() => {
    const total = mappings.value.length;
    const confidenceTotal = mappings.value.reduce((accumulator, mapping) => {
      const confidenceValue = Number.isFinite(mapping.confidence) ? mapping.confidence : 0;
      return accumulator + confidenceValue;
    }, 0);

    return {
      total,
      averageConfidence: total > 0 ? Math.round(confidenceTotal / total) : 0,
      aiGeneratedCount: mappings.value.filter((mapping) => mapping.aiGenerated).length,
      categoriesUsed: new Set(mappings.value.map((mapping) => mapping.category)).size,
    };
  });
}

function createTopMappings(filteredMappings: ComputedRef<SkillMapping[]>) {
  return computed(() =>
    [...filteredMappings.value]
      .sort((left, right) => right.confidence - left.confidence)
      .slice(0, SKILLS_TOP_MAPPINGS_PREVIEW_LIMIT),
  );
}

function createGamificationSummary({
  mappings,
  categoryFilter,
  searchFilter,
  level,
  xp,
}: SkillsPageDerivedInput) {
  return {
    gamificationLevel: computed(() => level.value),
    gamificationXP: computed(() => xp.value),
    hasMappings: computed(() => mappings.value.length > 0),
    hasActiveFilters: computed(
      () =>
        categoryFilter.value !== SKILLS_FILTER_ALL_VALUE || searchFilter.value.trim().length > 0,
    ),
  };
}

export function createSkillsPageDerived(input: SkillsPageDerivedInput) {
  const categoryOptions = createSkillCategoryOptions(input.t);
  const filteredMappings = createFilteredMappings(input);
  const mappingMetrics = createMappingMetrics(input.mappings);
  const topMappings = createTopMappings(filteredMappings);
  const summary = createGamificationSummary(input);

  function clearFilters(): void {
    input.categoryFilter.value = SKILLS_FILTER_ALL_VALUE;
    input.searchFilter.value = "";
  }

  return {
    categoryOptions,
    clearFilters,
    filteredMappings,
    mappingMetrics,
    topMappings,
    ...summary,
  };
}

import type {
  ReadinessAssessment,
  SkillReadinessFeedbackId,
} from "@bao/shared/types/skill-mapping";

export type ReadinessCategoryKey = "technical" | "softSkills" | "industryKnowledge" | "portfolio";

export interface ReadinessCategoryStat {
  readonly key: ReadinessCategoryKey;
  readonly score: number;
  readonly feedbackId: SkillReadinessFeedbackId;
}

export const READINESS_CATEGORY_LABEL_KEYS: Record<ReadinessCategoryKey, string> = {
  technical: "skillsPathwaysPage.categories.technical",
  softSkills: "skillsPathwaysPage.categories.softSkills",
  industryKnowledge: "skillsPathwaysPage.categories.industryKnowledge",
  portfolio: "skillsPathwaysPage.categories.portfolio",
};

export const READINESS_CATEGORY_KEYS = [
  "technical",
  "softSkills",
  "industryKnowledge",
  "portfolio",
] as const satisfies readonly ReadinessCategoryKey[];

export type ReadinessImprovementItem = ReadinessAssessment["improvementSuggestions"][number];
export type ReadinessNextStepItem = ReadinessAssessment["nextSteps"][number];

import {
  type CareerPathway,
  type ReadinessAssessment,
  SKILL_READINESS_FEEDBACK_IDS,
  SKILL_READINESS_IMPROVEMENT_IDS,
  SKILL_READINESS_NEXT_STEP_IDS,
  type SkillReadinessFeedbackId,
  type SkillReadinessImprovementId,
  type SkillReadinessNextStepId,
} from "@bao/shared/types/skill-mapping";
import { isRecord } from "@bao/shared/utils/type-guards";

export interface SkillsPathwaysBootstrapData {
  readonly pathways: readonly CareerPathway[];
  readonly readiness: ReadinessAssessment;
}

export interface SkillsPathwaysGamificationProgress {
  readonly level?: number;
  readonly xp?: number;
}

const toSkillReadinessFeedbackId = (value: unknown): SkillReadinessFeedbackId | null => {
  if (typeof value !== "string") {
    return null;
  }
  return isSkillReadinessFeedbackId(value) ? value : null;
};

const isSkillReadinessFeedbackId = (value: string): value is SkillReadinessFeedbackId =>
  SKILL_READINESS_FEEDBACK_IDS.some((entry) => entry === value);

const isSkillReadinessImprovementId = (value: string): value is SkillReadinessImprovementId =>
  SKILL_READINESS_IMPROVEMENT_IDS.some((entry) => entry === value);

const isSkillReadinessNextStepId = (value: string): value is SkillReadinessNextStepId =>
  SKILL_READINESS_NEXT_STEP_IDS.some((entry) => entry === value);

const toCareerSalary = (value: unknown): CareerPathway["averageSalary"] => {
  if (!(isRecord(value) && typeof value.min === "number" && typeof value.max === "number")) {
    return;
  }

  return {
    min: value.min,
    max: value.max,
    currency: typeof value.currency === "string" ? value.currency : undefined,
  };
};

const toCareerStage = (value: unknown): CareerPathway["stages"][number] | null => {
  if (!isRecord(value)) {
    return null;
  }

  const title = typeof value.title === "string" ? value.title : undefined;
  const duration = typeof value.duration === "string" ? value.duration : undefined;
  const description = typeof value.description === "string" ? value.description : undefined;
  if (!(title && duration && description)) {
    return null;
  }

  const stage: CareerPathway["stages"][number] = { title, duration, description };
  if (typeof value.completed === "boolean") {
    stage.completed = value.completed;
  }
  if (typeof value.current === "boolean") {
    stage.current = value.current;
  }
  if (Array.isArray(value.requirements)) {
    stage.requirements = value.requirements.filter(
      (entry): entry is string => typeof entry === "string",
    );
  }
  if (Array.isArray(value.outcomes)) {
    stage.outcomes = value.outcomes.filter((entry): entry is string => typeof entry === "string");
  }

  return stage;
};

const toCareerPathway = (value: unknown): CareerPathway | null => {
  if (!isRecord(value)) {
    return null;
  }

  const id = typeof value.id === "string" ? value.id : undefined;
  const title = typeof value.title === "string" ? value.title : undefined;
  const description = typeof value.description === "string" ? value.description : undefined;
  const estimatedTimeToEntry =
    typeof value.estimatedTimeToEntry === "string" ? value.estimatedTimeToEntry : undefined;
  if (!(id && title && description && estimatedTimeToEntry)) {
    return null;
  }

  const stages = Array.isArray(value.stages)
    ? value.stages
        .map((entry) => toCareerStage(entry))
        .filter((entry): entry is CareerPathway["stages"][number] => entry !== null)
    : [];
  const trend = typeof value.jobMarketTrend === "string" ? value.jobMarketTrend : undefined;

  return {
    id,
    title,
    description,
    detailedDescription:
      typeof value.detailedDescription === "string" ? value.detailedDescription : undefined,
    matchScore: typeof value.matchScore === "number" ? value.matchScore : 0,
    stages,
    requiredSkills: Array.isArray(value.requiredSkills)
      ? value.requiredSkills.filter((entry): entry is string => typeof entry === "string")
      : [],
    estimatedTimeToEntry,
    icon: typeof value.icon === "string" ? value.icon : undefined,
    averageSalary: toCareerSalary(value.averageSalary),
    jobMarketTrend:
      trend === "growing" || trend === "stable" || trend === "declining" ? trend : "stable",
  };
};

const toReadinessCategory = (
  value: unknown,
): ReadinessAssessment["categories"]["technical"] | null => {
  if (!(isRecord(value) && typeof value.score === "number")) {
    return null;
  }
  const feedbackId = toSkillReadinessFeedbackId(value.feedbackId);
  if (!feedbackId) {
    return null;
  }

  return {
    score: value.score,
    feedbackId,
    strengths: Array.isArray(value.strengths)
      ? value.strengths.filter((entry): entry is string => typeof entry === "string")
      : [],
    improvements: Array.isArray(value.improvements)
      ? value.improvements.filter(
          (entry): entry is SkillReadinessImprovementId =>
            typeof entry === "string" && isSkillReadinessImprovementId(entry),
        )
      : [],
  };
};

const toTargetRoleReadiness = (
  value: unknown,
): NonNullable<ReadinessAssessment["targetRoleReadiness"]> =>
  Array.isArray(value)
    ? value
        .map((entry) => toRoleReadiness(entry))
        .filter(
          (entry): entry is NonNullable<ReadinessAssessment["targetRoleReadiness"]>[number] =>
            entry !== null,
        )
    : [];

const toRoleReadiness = (
  entry: unknown,
): NonNullable<ReadinessAssessment["targetRoleReadiness"]>[number] | null => {
  if (!isRecord(entry)) {
    return null;
  }
  const roleId = typeof entry.roleId === "string" ? entry.roleId : undefined;
  const roleTitle = typeof entry.roleTitle === "string" ? entry.roleTitle : undefined;
  if (!(roleId && roleTitle)) {
    return null;
  }

  const readiness: NonNullable<ReadinessAssessment["targetRoleReadiness"]>[number] = {
    roleId,
    roleTitle,
    readinessScore: typeof entry.readinessScore === "number" ? entry.readinessScore : 0,
    missingSkills: Array.isArray(entry.missingSkills)
      ? entry.missingSkills.filter((skill): skill is string => typeof skill === "string")
      : [],
    matchingSkills: Array.isArray(entry.matchingSkills)
      ? entry.matchingSkills.filter((skill): skill is string => typeof skill === "string")
      : [],
    recommendedActions: Array.isArray(entry.recommendedActions)
      ? entry.recommendedActions.filter((action): action is string => typeof action === "string")
      : [],
  };
  if (typeof entry.timeToReady === "string") {
    readiness.timeToReady = entry.timeToReady;
  }
  return readiness;
};

const toReadinessAssessment = (value: unknown): ReadinessAssessment | null => {
  if (!(isRecord(value) && isRecord(value.categories))) {
    return null;
  }

  const categories = value.categories;
  const technical = toReadinessCategory(categories.technical);
  const softSkills = toReadinessCategory(categories.softSkills);
  const industryKnowledge = toReadinessCategory(categories.industryKnowledge);
  const portfolio = toReadinessCategory(categories.portfolio);
  if (!(technical && softSkills && industryKnowledge && portfolio)) {
    return null;
  }

  return {
    overallScore: typeof value.overallScore === "number" ? value.overallScore : 0,
    categories: {
      technical,
      softSkills,
      industryKnowledge,
      portfolio,
    },
    improvementSuggestions: Array.isArray(value.improvementSuggestions)
      ? value.improvementSuggestions.filter(
          (entry): entry is SkillReadinessImprovementId =>
            typeof entry === "string" && isSkillReadinessImprovementId(entry),
        )
      : [],
    nextSteps: Array.isArray(value.nextSteps)
      ? value.nextSteps.filter(
          (entry): entry is SkillReadinessNextStepId =>
            typeof entry === "string" && isSkillReadinessNextStepId(entry),
        )
      : [],
    targetRoleReadiness: toTargetRoleReadiness(value.targetRoleReadiness),
  };
};

export const toSkillsPathwaysBootstrapData = (
  value: unknown,
): SkillsPathwaysBootstrapData | null => {
  if (!(isRecord(value) && Array.isArray(value.pathways) && isRecord(value.readiness))) {
    return null;
  }

  const pathways = value.pathways
    .map((entry) => toCareerPathway(entry))
    .filter((entry): entry is CareerPathway => entry !== null);
  const readiness = toReadinessAssessment(value.readiness);
  if (!readiness) {
    return null;
  }

  return {
    pathways,
    readiness,
  };
};

export const toGamificationProgress = (
  value: unknown,
): SkillsPathwaysGamificationProgress | null => {
  if (!isRecord(value)) {
    return null;
  }
  const level = typeof value.level === "number" ? value.level : undefined;
  const xp = typeof value.xp === "number" ? value.xp : undefined;
  return level === undefined && xp === undefined ? null : { level, xp };
};

import { getGamificationPathwayIcon } from "@bao/shared/constants/gamification-icons";
import type {
  CareerPathway,
  ReadinessAssessment,
  SkillReadinessFeedbackId,
} from "@bao/shared/types/skill-mapping";
import {
  READINESS_CATEGORY_KEYS,
  READINESS_CATEGORY_LABEL_KEYS,
  type ReadinessCategoryKey,
  type ReadinessCategoryStat,
  type ReadinessImprovementItem,
  type ReadinessNextStepItem,
} from "~/composables/skills-pathways-page-contracts";
import {
  SKILLS_READINESS_THRESHOLD_HIGH,
  SKILLS_READINESS_THRESHOLD_MEDIUM,
} from "~/constants/skills";

interface SkillsPathwaysPresentationOptions {
  readonly t: (key: string, params?: Record<string, unknown>) => string;
}

const getReadinessColor = (percentage: number): string => {
  if (percentage >= SKILLS_READINESS_THRESHOLD_HIGH) return "progress-success";
  if (percentage >= SKILLS_READINESS_THRESHOLD_MEDIUM) return "progress-warning";
  return "progress-error";
};

const getReadinessBadgeColor = (percentage: number): string => {
  if (percentage >= SKILLS_READINESS_THRESHOLD_HIGH) return "badge-success";
  if (percentage >= SKILLS_READINESS_THRESHOLD_MEDIUM) return "badge-warning";
  return "badge-error";
};

const sortPathways = (pathways: readonly CareerPathway[]): readonly CareerPathway[] =>
  [...pathways].sort((left, right) => right.matchScore - left.matchScore);

const createReadinessCategories = (
  readinessAssessment: ReadinessAssessment | null,
): readonly ReadinessCategoryStat[] => {
  if (!readinessAssessment) {
    return [];
  }

  return READINESS_CATEGORY_KEYS.map((key) => ({
    key,
    score: readinessAssessment.categories[key].score,
    feedbackId: readinessAssessment.categories[key].feedbackId,
  }));
};

const createSkillsPathwaysCopy = (t: SkillsPathwaysPresentationOptions["t"]) => {
  const getCategoryLabel = (key: ReadinessCategoryKey): string =>
    t(READINESS_CATEGORY_LABEL_KEYS[key]);
  const getCategoryFeedbackLabel = (
    categoryKey: ReadinessCategoryKey,
    feedbackId: SkillReadinessFeedbackId,
  ): string =>
    t(`skillsPathwaysPage.readiness.feedback.${feedbackId}`, {
      category: getCategoryLabel(categoryKey),
    });

  const getReadinessImprovementLabel = (item: ReadinessImprovementItem): string =>
    t(`skillsPathwaysPage.readiness.improvements.${item}`);

  const getReadinessNextStepLabel = (item: ReadinessNextStepItem): string =>
    t(`skillsPathwaysPage.readiness.nextStepItems.${item}`);

  const getPathwayIcon = (pathwayId: string): string => getGamificationPathwayIcon(pathwayId);
  return {
    getCategoryFeedbackLabel,
    getCategoryLabel,
    getPathwayIcon,
    getReadinessImprovementLabel,
    getReadinessNextStepLabel,
  };
};

export const createSkillsPathwaysPresentation = ({ t }: SkillsPathwaysPresentationOptions) => {
  const copy = createSkillsPathwaysCopy(t);

  return {
    createReadinessCategories,
    getCategoryFeedbackLabel: copy.getCategoryFeedbackLabel,
    getCategoryLabel: copy.getCategoryLabel,
    getPathwayIcon: copy.getPathwayIcon,
    getReadinessBadgeColor,
    getReadinessColor,
    getReadinessImprovementLabel: copy.getReadinessImprovementLabel,
    getReadinessNextStepLabel: copy.getReadinessNextStepLabel,
    sortPathways,
  };
};

import { DEFAULT_SPEECH_SETTINGS } from "@bao/shared/constants/settings";
import { DEFAULT_AUTOMATION_SETTINGS } from "@bao/shared/types/settings-defaults";
import { describe, expect, it } from "vitest";
import {
  buildNextSpeechConfigFromProfile,
  createDefaultSpeechModelProfileState,
  isSpeechModelProfileDirty,
  mapPersistedSpeechToProfileState,
  type SpeechModelProfileState,
} from "./speech-model-profile-state";

const baseProfile = (): SpeechModelProfileState => createDefaultSpeechModelProfileState();

describe("speech-model-profile-state", () => {
  it("defaults endpoints from DEFAULT_SPEECH_SETTINGS", () => {
    const profile = createDefaultSpeechModelProfileState();
    expect(profile.sttEndpoint).toBe(DEFAULT_SPEECH_SETTINGS.stt.endpoint);
    expect(profile.ttsEndpoint).toBe(DEFAULT_SPEECH_SETTINGS.tts.endpoint);
  });

  it("maps persisted speech including endpoints", () => {
    const persisted = {
      ...DEFAULT_AUTOMATION_SETTINGS.speech,
      stt: {
        ...DEFAULT_AUTOMATION_SETTINGS.speech.stt,
        endpoint: "http://127.0.0.1:9090/v1",
      },
      tts: {
        ...DEFAULT_AUTOMATION_SETTINGS.speech.tts,
        endpoint: "http://127.0.0.1:9091/v1",
      },
    };
    expect(mapPersistedSpeechToProfileState(persisted)).toMatchObject({
      sttEndpoint: "http://127.0.0.1:9090/v1",
      ttsEndpoint: "http://127.0.0.1:9091/v1",
    });
  });

  it("detects dirty endpoint edits after trim", () => {
    const persisted = baseProfile();
    const dirtyStt = { ...persisted, sttEndpoint: " http://127.0.0.1:9001/v1 " };
    expect(isSpeechModelProfileDirty(dirtyStt, persisted)).toBe(true);

    const whitespaceOnly = { ...persisted, sttEndpoint: `  ${persisted.sttEndpoint}  ` };
    expect(isSpeechModelProfileDirty(whitespaceOnly, persisted)).toBe(false);
  });

  it("buildNextSpeechConfigFromProfile persists endpoints and preserves voice/format", () => {
    const existing = DEFAULT_AUTOMATION_SETTINGS.speech;
    const profile: SpeechModelProfileState = {
      ...baseProfile(),
      sttEndpoint: "http://127.0.0.1:8099/v1",
      ttsEndpoint: "http://127.0.0.1:8889/v1",
    };
    const next = buildNextSpeechConfigFromProfile(existing, profile, "en-US");
    expect(next.stt.endpoint).toBe("http://127.0.0.1:8099/v1");
    expect(next.tts.endpoint).toBe("http://127.0.0.1:8889/v1");
    expect(next.tts.voice).toBe(existing.tts.voice);
    expect(next.tts.format).toBe(existing.tts.format);
    expect(next.locale).toBe(existing.locale);
  });

  it("buildNextSpeechConfigFromProfile fills blank endpoints from defaults", () => {
    const existing = DEFAULT_AUTOMATION_SETTINGS.speech;
    const profile: SpeechModelProfileState = {
      ...baseProfile(),
      sttEndpoint: "  ",
      ttsEndpoint: "",
    };
    const next = buildNextSpeechConfigFromProfile(existing, profile, "en-US");
    expect(next.stt.endpoint).toBe(DEFAULT_SPEECH_SETTINGS.stt.endpoint);
    expect(next.tts.endpoint).toBe(DEFAULT_SPEECH_SETTINGS.tts.endpoint);
  });
});

import {
  DEFAULT_SPEECH_SETTINGS,
  SPEECH_MODEL_OPTIONS,
  type SpeechProviderOption,
} from "@bao/shared/constants/settings";
import type { DEFAULT_AUTOMATION_SETTINGS } from "@bao/shared/types/settings-defaults";

type SpeechModelProfileKind = "stt" | "tts";

/**
 * Reactive editable speech profile model used by chat surfaces.
 */
export interface SpeechModelProfileState {
  sttProvider: SpeechProviderOption;
  sttModel: string;
  sttEndpoint: string;
  ttsProvider: SpeechProviderOption;
  ttsModel: string;
  ttsEndpoint: string;
}

type PersistedSpeechSettings = typeof DEFAULT_AUTOMATION_SETTINGS.speech;

const resolveProviderModels = (
  kind: SpeechModelProfileKind,
  provider: SpeechProviderOption,
): readonly string[] => SPEECH_MODEL_OPTIONS[kind][provider];

/** First configured model for a provider, else global STT/TTS default. */
export const resolveDefaultSpeechModel = (
  kind: SpeechModelProfileKind,
  provider: SpeechProviderOption,
): string => {
  const configuredModels = resolveProviderModels(kind, provider);
  if (configuredModels.length === 0) {
    return kind === "stt" ? DEFAULT_SPEECH_SETTINGS.stt.model : DEFAULT_SPEECH_SETTINGS.tts.model;
  }
  return configuredModels[0] ?? "";
};

/** Default editable speech profile from DEFAULT_SPEECH_SETTINGS. */
export const createDefaultSpeechModelProfileState = (): SpeechModelProfileState => {
  const sttProvider = DEFAULT_SPEECH_SETTINGS.stt.provider;
  const ttsProvider = DEFAULT_SPEECH_SETTINGS.tts.provider;
  return {
    sttProvider,
    sttModel: resolveDefaultSpeechModel("stt", sttProvider),
    sttEndpoint: DEFAULT_SPEECH_SETTINGS.stt.endpoint,
    ttsProvider,
    ttsModel: resolveDefaultSpeechModel("tts", ttsProvider),
    ttsEndpoint: DEFAULT_SPEECH_SETTINGS.tts.endpoint,
  };
};

/** Map persisted automation speech settings into editable profile state. */
export const mapPersistedSpeechToProfileState = (
  persistedSpeech: PersistedSpeechSettings,
): SpeechModelProfileState => ({
  sttProvider: persistedSpeech.stt.provider,
  sttModel: persistedSpeech.stt.model,
  sttEndpoint: persistedSpeech.stt.endpoint,
  ttsProvider: persistedSpeech.tts.provider,
  ttsModel: persistedSpeech.tts.model,
  ttsEndpoint: persistedSpeech.tts.endpoint,
});

/** True when editable profile differs from persisted (trimmed model/endpoint). */
export const isSpeechModelProfileDirty = (
  speechConfig: SpeechModelProfileState,
  persisted: SpeechModelProfileState,
): boolean =>
  speechConfig.sttProvider !== persisted.sttProvider ||
  speechConfig.sttModel.trim() !== persisted.sttModel ||
  speechConfig.sttEndpoint.trim() !== persisted.sttEndpoint ||
  speechConfig.ttsProvider !== persisted.ttsProvider ||
  speechConfig.ttsModel.trim() !== persisted.ttsModel ||
  speechConfig.ttsEndpoint.trim() !== persisted.ttsEndpoint;

const resolvePersistedModelOrDefault = (
  kind: SpeechModelProfileKind,
  provider: SpeechProviderOption,
  model: string,
): string => {
  const trimmed = model.trim();
  return trimmed.length > 0 ? trimmed : resolveDefaultSpeechModel(kind, provider);
};

const resolvePersistedEndpointOrDefault = (
  kind: SpeechModelProfileKind,
  endpoint: string,
): string => {
  const trimmed = endpoint.trim();
  if (trimmed.length > 0) {
    return trimmed;
  }
  return kind === "stt"
    ? DEFAULT_SPEECH_SETTINGS.stt.endpoint
    : DEFAULT_SPEECH_SETTINGS.tts.endpoint;
};

/**
 * Build next automation speech config from profile edits, preserving locale/voice/format.
 */
export const buildNextSpeechConfigFromProfile = (
  existingSpeech: PersistedSpeechSettings,
  speechConfig: SpeechModelProfileState,
  localeFallback: string,
): PersistedSpeechSettings => {
  const sttModel = resolvePersistedModelOrDefault(
    "stt",
    speechConfig.sttProvider,
    speechConfig.sttModel,
  );
  const ttsModel = resolvePersistedModelOrDefault(
    "tts",
    speechConfig.ttsProvider,
    speechConfig.ttsModel,
  );
  const sttEndpoint = resolvePersistedEndpointOrDefault("stt", speechConfig.sttEndpoint);
  const ttsEndpoint = resolvePersistedEndpointOrDefault("tts", speechConfig.ttsEndpoint);
  return {
    ...existingSpeech,
    locale: existingSpeech.locale || localeFallback,
    stt: {
      ...existingSpeech.stt,
      provider: speechConfig.sttProvider,
      model: sttModel,
      endpoint: sttEndpoint,
    },
    tts: {
      ...existingSpeech.tts,
      provider: speechConfig.ttsProvider,
      model: ttsModel,
      endpoint: ttsEndpoint,
    },
  };
};

