import { API_ENDPOINTS } from "@bao/shared/constants/endpoints";
import type { SpeechProviderOption } from "@bao/shared/constants/settings";
import { settle } from "@bao/shared/utils/promise";
import { requestApi, useClientApiRequestRuntime } from "./api-request";

export type ServerSttResult =
  | { readonly ok: true; readonly text: string }
  | { readonly ok: false; readonly error: string };

export type ServerSttRequestOptions = {
  readonly provider: SpeechProviderOption;
  readonly model: string;
  readonly endpoint: string;
};

const blobToBase64 = async (blob: Blob): Promise<string> => {
  const buffer = await blob.arrayBuffer();
  const bytes = new Uint8Array(buffer);
  let binary = "";
  const chunkSize = 0x8000;
  for (let index = 0; index < bytes.length; index += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(index, index + chunkSize));
  }
  return btoa(binary);
};

/**
 * Records microphone audio until stop() is called, then returns the Blob.
 */
export const createMicrophoneRecorder = async (): Promise<{
  readonly start: () => void;
  readonly stop: () => Promise<Blob>;
}> => {
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  const mimeType = MediaRecorder.isTypeSupported("audio/webm;codecs=opus")
    ? "audio/webm;codecs=opus"
    : "audio/webm";
  const recorder = new MediaRecorder(stream, { mimeType });
  const chunks: BlobPart[] = [];
  recorder.ondataavailable = (event) => {
    if (event.data.size > 0) {
      chunks.push(event.data);
    }
  };

  return {
    start: () => {
      chunks.length = 0;
      recorder.start();
    },
    stop: () =>
      new Promise<Blob>((resolve, reject) => {
        recorder.onstop = () => {
          for (const track of stream.getTracks()) {
            track.stop();
          }
          resolve(new Blob(chunks, { type: mimeType }));
        };
        recorder.onerror = () => {
          for (const track of stream.getTracks()) {
            track.stop();
          }
          reject(new Error("MediaRecorder failed"));
        };
        if (recorder.state !== "inactive") {
          recorder.stop();
        } else {
          for (const track of stream.getTracks()) {
            track.stop();
          }
          resolve(new Blob(chunks, { type: mimeType }));
        }
      }),
  };
};

/**
 * Uploads recorded audio to the server Whisper/STT proxy with explicit provider routing.
 */
export const transcribeAudioViaServer = async (
  blob: Blob,
  options: ServerSttRequestOptions,
): Promise<ServerSttResult> => {
  if (blob.size === 0) {
    return { ok: false, error: "empty audio recording" };
  }
  const audioBase64 = await blobToBase64(blob);
  const runtime = useClientApiRequestRuntime();
  const result = await settle(
    requestApi<{ text: string }>(runtime, API_ENDPOINTS.speechTranscribe, {
      method: "POST",
      body: {
        audioBase64,
        mimeType: blob.type || "audio/webm",
        filename: blob.type.includes("wav") ? "recording.wav" : "recording.webm",
        provider: options.provider,
        model: options.model,
        endpoint: options.endpoint,
      },
    }),
  );
  if (result.status === "rejected") {
    return { ok: false, error: result.reason.message };
  }
  const text = result.value.text?.trim() ?? "";
  if (text.length === 0) {
    return { ok: false, error: "empty transcription" };
  }
  return { ok: true, text };
};

import { API_ENDPOINTS } from "@bao/shared/constants/endpoints";
import { settle } from "@bao/shared/utils/promise";
import { WAV_HEADER_MIN_BYTES } from "~/constants/numeric-ui";
import { requestApi, useClientApiRequestRuntime } from "./api-request";

export type ServerTtsResult =
  | {
      readonly ok: true;
      readonly audioBase64: string;
      readonly mimeType: string;
      readonly bytes: number;
      readonly provider: string;
      readonly model: string;
      readonly voice: string;
    }
  | { readonly ok: false; readonly error: string };

type SynthesizeResponse = {
  audioBase64: string;
  mimeType: string;
  bytes: number;
  provider: string;
  model: string;
  voice: string;
};

/**
 * Local Kokoro TTS via Bao server proxy (on-device neural, not browser speechSynthesis).
 */
export const synthesizeSpeechViaServer = async (input: {
  readonly text: string;
  readonly voice?: string;
}): Promise<ServerTtsResult> => {
  const text = input.text.trim();
  if (text.length === 0) {
    return { ok: false, error: "empty text" };
  }
  const runtime = useClientApiRequestRuntime();
  const result = await settle(
    requestApi<SynthesizeResponse>(runtime, API_ENDPOINTS.speechSynthesize, {
      method: "POST",
      body: {
        text,
        ...(input.voice ? { voice: input.voice } : {}),
      },
    }),
  );
  if (result.status === "rejected") {
    return { ok: false, error: result.reason.message };
  }
  const payload = result.value;
  if (!payload.audioBase64 || payload.bytes < WAV_HEADER_MIN_BYTES) {
    return { ok: false, error: "empty audio" };
  }
  return {
    ok: true,
    audioBase64: payload.audioBase64,
    mimeType: payload.mimeType,
    bytes: payload.bytes,
    provider: payload.provider,
    model: payload.model,
    voice: payload.voice,
  };
};

/** Play base64 WAV through HTMLAudioElement (local Kokoro output). */
export const playBase64Audio = async (audioBase64: string, mimeType: string): Promise<void> => {
  const binary = atob(audioBase64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  const blob = new Blob([bytes], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const audio = new Audio(url);
  const playResult = await settle(audio.play());
  if (playResult.status === "rejected") {
    URL.revokeObjectURL(url);
    throw playResult.reason;
  }
  await new Promise<void>((resolve) => {
    audio.onended = () => {
      URL.revokeObjectURL(url);
      resolve();
    };
    audio.onerror = () => {
      URL.revokeObjectURL(url);
      resolve();
    };
  });
};

import {
  AI_CHAT_VOICE_ERROR_CODES,
  type AIChatVoiceErrorCode,
} from "@bao/shared/constants/ai-voice";
import type { SpeechProviderOption } from "@bao/shared/constants/settings";
import { settle } from "@bao/shared/utils/promise";
import type { Ref } from "vue";
import { resolveSpeechLocale } from "../utils/speech";
import {
  createMicrophoneRecorder,
  type ServerSttRequestOptions,
  transcribeAudioViaServer,
} from "./speech-server-stt";
import { shouldUseServerStt } from "./speech-stt-provider";

type MicrophoneRecorder = Awaited<ReturnType<typeof createMicrophoneRecorder>>;

export interface SpeechListeningState {
  isListening: Ref<boolean>;
  transcript: Ref<string>;
  interimTranscript: Ref<string>;
  error: Ref<AIChatVoiceErrorCode | null>;
  recognition: Ref<SpeechRecognition | null>;
}

function resetListeningTranscript(state: SpeechListeningState): void {
  state.error.value = null;
  state.transcript.value = "";
  state.interimTranscript.value = "";
}

function startServerListening(
  state: SpeechListeningState,
  setRecorder: (recorder: MicrophoneRecorder | null) => void,
): boolean {
  if (state.isListening.value) {
    return true;
  }
  settle(createMicrophoneRecorder()).then(
    (settled) => {
      if (settled.status === "rejected") {
        state.error.value = AI_CHAT_VOICE_ERROR_CODES.audioCapture;
        state.isListening.value = false;
        return;
      }
      setRecorder(settled.value);
      settled.value.start();
      state.isListening.value = true;
    },
    () => {
      state.error.value = AI_CHAT_VOICE_ERROR_CODES.audioCapture;
      state.isListening.value = false;
    },
  );
  return true;
}

function startBrowserListening(state: SpeechListeningState, locale?: string): boolean {
  if (!state.recognition.value) {
    state.error.value = AI_CHAT_VOICE_ERROR_CODES.unsupportedRecognition;
    return false;
  }
  if (state.isListening.value) {
    return true;
  }
  state.recognition.value.lang = resolveSpeechLocale(locale);
  state.recognition.value.start();
  state.isListening.value = true;
  return true;
}

async function transcribeStoppedRecording(
  state: SpeechListeningState,
  blob: Blob,
  getServerSttOptions: () => ServerSttRequestOptions,
): Promise<void> {
  const transcriptSettled = await settle(transcribeAudioViaServer(blob, getServerSttOptions()));
  if (transcriptSettled.status === "rejected") {
    state.error.value = AI_CHAT_VOICE_ERROR_CODES.network;
    return;
  }
  const result = transcriptSettled.value;
  if (result.ok) {
    state.transcript.value = result.text;
    state.interimTranscript.value = "";
    return;
  }
  state.error.value = AI_CHAT_VOICE_ERROR_CODES.network;
}

function stopServerListening(
  state: SpeechListeningState,
  recorder: MicrophoneRecorder | null,
  clearRecorder: () => void,
  getServerSttOptions: () => ServerSttRequestOptions,
): void {
  clearRecorder();
  if (!recorder) {
    state.isListening.value = false;
    return;
  }
  settle(recorder.stop())
    .then(
      async (stopSettled) => {
        if (stopSettled.status === "rejected") {
          state.error.value = AI_CHAT_VOICE_ERROR_CODES.network;
          return;
        }
        await transcribeStoppedRecording(state, stopSettled.value, getServerSttOptions);
      },
      () => {
        state.error.value = AI_CHAT_VOICE_ERROR_CODES.network;
      },
    )
    .then(
      () => {
        state.isListening.value = false;
      },
      () => {
        state.isListening.value = false;
      },
    );
}

function stopBrowserListening(state: SpeechListeningState): void {
  if (state.recognition.value) {
    state.recognition.value.stop();
  }
  state.isListening.value = false;
}

export const createStartListeningAction = (
  state: SpeechListeningState,
  getProvider: () => SpeechProviderOption,
  getServerSttOptions: () => ServerSttRequestOptions,
) => {
  let recorder: MicrophoneRecorder | null = null;

  const startListening = (locale?: string): boolean => {
    resetListeningTranscript(state);
    if (shouldUseServerStt(getProvider())) {
      return startServerListening(state, (next) => {
        recorder = next;
      });
    }
    return startBrowserListening(state, locale);
  };

  const stopListening = (): void => {
    if (shouldUseServerStt(getProvider())) {
      const active = recorder;
      stopServerListening(
        state,
        active,
        () => {
          recorder = null;
        },
        getServerSttOptions,
      );
      return;
    }
    stopBrowserListening(state);
  };

  return { startListening, stopListening };
};

