import { DEFAULT_SPEECH_SETTINGS } from "@bao/shared/constants/settings";
import type { ServerSttRequestOptions } from "./speech-server-stt";
import { resolveSpeechSttProvider } from "./speech-stt-provider";

type SpeechSettingsReader = {
  value?: {
    automationSettings?: {
      speech?: {
        stt?: {
          provider?: string;
          model?: string;
          endpoint?: string;
        };
      };
    };
  } | null;
};

/** Build server STT routing options from persisted speech settings (defaults filled). */
export const createServerSttRequestOptions = (
  appSettings: SpeechSettingsReader,
): ServerSttRequestOptions => {
  const stt = appSettings.value?.automationSettings?.speech?.stt;
  const provider = resolveSpeechSttProvider(stt?.provider);
  const model = stt?.model?.trim() || DEFAULT_SPEECH_SETTINGS.stt.model;
  const endpoint = stt?.endpoint?.trim() || DEFAULT_SPEECH_SETTINGS.stt.endpoint;
  return { provider, model, endpoint };
};

import type { SpeechProviderOption } from "@bao/shared/constants/settings";

/**
 * Resolves TTS provider. Product path is local Kokoro; browser Web Speech is fallback.
 * Cloud OpenAI/HF TTS is ignored (normalized to local).
 */
export const resolveSpeechTtsProvider = (
  value: string | null | undefined,
): SpeechProviderOption => {
  if (value === "browser") {
    return "browser";
  }
  if (value === "local" || value === "custom") {
    return "local";
  }
  // Ignore cloud TTS selections — force local Kokoro.
  if (value === "openai" || value === "huggingface") {
    return "local";
  }
  return "local";
};

/** Local Kokoro neural path (server → OpenAI-compatible Kokoro). */
export const shouldUseLocalKokoroTts = (provider: SpeechProviderOption): boolean =>
  resolveSpeechTtsProvider(provider) === "local";

import { useI18n } from "vue-i18n";
import { createChatActions } from "~/composables/ai-chat-actions";
import { createContextBuilder } from "~/composables/ai-context";
import { createDataActions } from "~/composables/ai-data-actions";
import { initializeAIState } from "~/composables/ai-state";

/**
 * AI interaction composable for chat, analysis, and generation.
 */
export function useAI() {
  const api = useApi();
  const route = useRoute();
  const { $toast } = useNuxtApp();
  const { t } = useI18n();
  const { resolvedBrand } = useBrand();
  const state = initializeAIState(t, resolvedBrand.value.name, resolvedBrand.value.assistantName);

  const buildCurrentContext = createContextBuilder({
    route,
    jobs: state.jobs,
    resumes: state.resumes,
    currentStudio: state.currentStudio,
    interviewSessions: state.interviewSessions,
    portfolioData: state.portfolioData,
  });

  const chatActions = createChatActions({
    api,
    t,
    toast: $toast,
    loading: state.loading,
    streaming: state.streaming,
    streamingContent: state.streamingContent,
    messages: state.messages,
    sessionId: state.sessionId,
    buildAssistantGreetingMessage: state.buildAssistantGreetingMessage,
    buildCurrentContext,
    unableToProcessFallback: () => t("aiChatCommon.unableToProcessFallback"),
    requestErrorFallback: () => t("aiChatCommon.requestErrorFallback"),
  });

  const dataActions = createDataActions({ api, t, loading: state.loading });

  return {
    messages: readonly(state.messages),
    sessionId: readonly(state.sessionId),
    streaming: readonly(state.streaming),
    streamingContent: readonly(state.streamingContent),
    loading: readonly(state.loading),
    buildCurrentContext,
    ...chatActions,
    ...dataActions,
  };
}

