    init: { post: vi.fn() },
  },
};

function getNuxtState<T>(key: string, initializer?: () => T): Ref<T> {
  const existing = nuxtStateStore.get(key);
  if (existing) {
    return existing as Ref<T>;
  }
  const created: Ref<unknown> = ref(initializer ? initializer() : undefined);
  nuxtStateStore.set(key, created);
  return created as Ref<T>;
}

function resetNuxtState() {
  nuxtStateStore.clear();
  storedApiKey = null;
}

vi.mock("./nuxtRuntime", () => ({
  useNuxtRuntimeApp: () => ({
    $getStoredApiKey: () => storedApiKey,
    $setStoredApiKey: (apiKey: string | null) => {
      storedApiKey = apiKey;
    },
  }),
  useNuxtState: getNuxtState,
}));

vi.mock("./useApi", () => ({
  useApi: () => mockApi,
}));

const { useAuth } = await import("./useAuth");

beforeEach(() => {
  vi.clearAllMocks();
  resetNuxtState();
});

describe("useAuth", () => {
  it("checkAuthStatus fails closed when api status is unavailable", async () => {
    mockApi.auth.status.get.mockResolvedValueOnce({
      data: null,
      error: { value: "err" },
    });

    const { checkAuthStatus } = useAuth();
    const result = await checkAuthStatus();
    expect(result.authRequired).toBe(true);
    expect(result.configured).toBe(false);
    expect(result.bootstrapRequired).toBe(true);
    expect(result.setupTokenConfigured).toBe(false);
  });

  it("checkAuthStatus returns data when api succeeds", async () => {
    mockApi.auth.status.get.mockResolvedValueOnce({
      data: {
        authRequired: true,
        configured: true,
        bootstrapRequired: false,
        setupTokenConfigured: true,
      },
      error: null,
    });

    const { checkAuthStatus } = useAuth();
    const result = await checkAuthStatus();
    expect(result.authRequired).toBe(true);
    expect(result.configured).toBe(true);
    expect(result.bootstrapRequired).toBe(false);
    expect(result.setupTokenConfigured).toBe(true);
  });

  it("passes setupToken to auth init requests", async () => {
    mockApi.auth.init.post.mockResolvedValueOnce({
      data: { configured: true, apiKey: "SK_test_placeholder", message: "ok" },
      error: null,
    });

    const { initAuth } = useAuth();
    const result = await initAuth("setup-token");

    expect(mockApi.auth.init.post).toHaveBeenCalledWith({ setupToken: "setup-token" });
    expect(result.apiKey).toBe("SK_test_placeholder");
  });

  it("stores and retrieves the API key through Nuxt app injection", () => {
    const { getStoredApiKey: readApiKey, setStoredApiKey: persistApiKey } = useAuth();

    expect(readApiKey()).toBeNull();
    persistApiKey("abc");
    expect(readApiKey()).toBe("abc");
  });
});

import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { useNuxtRuntimeApp } from "./nuxtRuntime";
import { useApi } from "./useApi";

interface AuthStatus {
  authRequired: boolean;
  configured: boolean;
  bootstrapRequired: boolean;
  setupTokenConfigured: boolean;
}

interface AuthInitResult {
  configured: boolean;
  apiKey?: string;
  message?: string;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

interface UseAuthState {
  checkAuthStatus: () => Promise<AuthStatus>;
  initAuth: (setupToken?: string) => Promise<AuthInitResult>;
  getStoredApiKey: () => string | null;
  setStoredApiKey: (key: string | null) => void;
}

const AUTH_INIT_FAILED_ERROR_KEY = "apiErrors.auth.initFailed";

/**
 * Authentication composable.
 *
 * @returns Auth helpers used by navigation guards and setup flows.
 */
export function useAuth(): UseAuthState {
  const api = useApi();
  const nuxtApp = useNuxtRuntimeApp();
  const authStatusErrorFallback: AuthStatus = {
    authRequired: true,
    configured: false,
    bootstrapRequired: true,
    setupTokenConfigured: false,
  };

  async function checkAuthStatus(): Promise<AuthStatus> {
    const { data, error } = await api.auth.status.get();
    if (error) return authStatusErrorFallback;
    return {
      authRequired: data?.authRequired ?? true,
      configured: data?.configured ?? false,
      bootstrapRequired: data?.bootstrapRequired ?? false,
      setupTokenConfigured: data?.setupTokenConfigured ?? false,
    };
  }

  async function initAuth(setupToken?: string) {
    const requestBody =
      typeof setupToken === "string" && setupToken.trim().length > 0
        ? { setupToken: setupToken.trim() }
        : undefined;
    const { data, error } = await api.auth.init.post(requestBody);
    if (error) {
      throw new Error(toErrorMessage(error, AUTH_INIT_FAILED_ERROR_KEY));
    }
    const payload: unknown = data ?? {};
    if (!isRecord(payload)) {
      return { configured: false };
    }

    const configured = payload.configured === true;
    const apiKey = typeof payload.apiKey === "string" ? payload.apiKey : undefined;
    const message = typeof payload.message === "string" ? payload.message : undefined;

    return { configured, apiKey, message };
  }

  return {
    checkAuthStatus,
    initAuth,
    getStoredApiKey: () => nuxtApp.$getStoredApiKey?.() ?? null,
    setStoredApiKey: (key: string | null) => nuxtApp.$setStoredApiKey?.(key),
  };
}

