  key: typeof STATE_KEYS.AI_CHAT_VOICE_ID,
  _initializer?: () => string,
): Ref<string>;
function useNuxtStateMock(
  key: string,
  initializer?: () => boolean | string,
): Ref<boolean | string> {
  if (typeof initializer === "function") {
    // Keep signature parity with Nuxt's state factory callback.
