import {
  AI_CHAT_VOICE_AUTO_SPEAK_DEFAULT,
  AI_CHAT_VOICE_DEFAULT_ID,
  AI_CHAT_VOICE_ERROR_MESSAGE_KEYS,
  type AIChatVoiceErrorCode,
} from "@bao/shared/constants/ai-voice";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { ChatMessage } from "@bao/shared/types/ai";
import type { Ref } from "vue";
import { computed, getCurrentScope, onScopeDispose, watch } from "vue";
import { type ComposerTranslation, useI18n } from "vue-i18n";
import { resolveSpeechLocale } from "../utils/speech";
import { useNuxtState } from "./nuxtRuntime";
import { useSpeech } from "./useSpeech";

/**
 * Input and message refs needed to bind voice controls to a chat surface.
 */
export interface UseChatVoiceOptions {
  draft: Ref<string>;
  locale: Ref<string>;
  messages: Readonly<Ref<readonly ChatMessage[]>>;
}

interface VoiceWatchInput {
  speech: ReturnType<typeof useSpeech>;
  locale: Ref<string>;
  messages: Readonly<Ref<readonly ChatMessage[]>>;
  draft: Ref<string>;
  autoSpeakReplies: Ref<boolean>;
  selectedVoiceId: Ref<string>;
  voices: Readonly<Ref<readonly SpeechSynthesisVoice[]>>;
}

interface VoiceActionInput {
  speech: ReturnType<typeof useSpeech>;
  locale: Ref<string>;
  selectedVoiceId: Ref<string>;
  voices: Readonly<Ref<readonly SpeechSynthesisVoice[]>>;
  latestAssistantMessage: Readonly<Ref<string>>;
  canReplayAssistant: Readonly<Ref<boolean>>;
}

interface VoiceComputedState {
  autoSpeakReplies: Ref<boolean>;
  selectedVoiceId: Ref<string>;
  voices: Readonly<Ref<readonly SpeechSynthesisVoice[]>>;
  latestAssistantMessage: Readonly<Ref<string>>;
  canReplayAssistant: Readonly<Ref<boolean>>;
  errorMessageKey: Readonly<Ref<string>>;
  supportHintKey: Readonly<Ref<string>>;
}

interface SpeakVoiceInput {
  speech: ReturnType<typeof useSpeech>;
  text: string;
  locale: string;
  selectedVoiceId: string;
  voices: readonly SpeechSynthesisVoice[];
}

/**
 * Resolves the most recent assistant message with non-empty content.
 *
 * @param messages Chat message history.
 * @returns Latest assistant message content or empty string.
 */
function resolveLatestAssistantMessage(messages: readonly ChatMessage[]): string {
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (message?.role !== "assistant") {
      continue;
    }

    const trimmedContent = message.content.trim();
    if (trimmedContent.length > 0) {
      return trimmedContent;
    }
  }

  return "";
}

/**
 * Resolves the i18n key for a canonical speech error code.
 *
 * @param value Canonical voice error code.
 * @returns Translation key path or empty string.
 */
function resolveSpeechErrorMessageKey(value: AIChatVoiceErrorCode | null | undefined): string {
  if (value === null || value === undefined) {
    return "";
  }

  return AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[value];
}

/**
 * Resolves the i18n key for voice feature support hints.
 *
 * @param supportsRecognition Whether browser speech recognition is available.
 * @param supportsSynthesis Whether browser speech synthesis is available.
 * @returns Translation key path or empty string when all voice features are available.
 */
function resolveVoiceSupportHintKey(
  supportsRecognition: boolean,
  supportsSynthesis: boolean,
): string {
  if (supportsRecognition && supportsSynthesis) {
    return "";
  }

  if (!(supportsRecognition || supportsSynthesis)) {
    return "aiChatCommon.voice.unsupportedHint";
  }

  if (!supportsRecognition) {
    return "aiChatCommon.voice.recognitionUnsupportedHint";
  }

  return "aiChatCommon.voice.synthesisUnsupportedHint";
}

/**
 * Resolves a speech synthesis voice by ID.
 *
 * @param voiceId Persisted voice identifier.
 * @param voices Available browser voices.
 * @returns Matching browser voice when available.
 */
function resolveVoiceById(
  voiceId: string,
  voices: readonly SpeechSynthesisVoice[],
): SpeechSynthesisVoice | undefined {
  const trimmedVoiceId = voiceId.trim();
  if (trimmedVoiceId.length === 0) {
    return;
  }

  return voices.find((voice) => voice.voiceURI === trimmedVoiceId);
}

/**
 * Resolves a locale-matching fallback voice for synthesis.
 *
 * @param locale Current UI locale.
 * @param voices Available browser voices.
 * @returns Locale-aligned fallback voice.
 */
function resolveLocaleVoice(
  locale: string,
  voices: readonly SpeechSynthesisVoice[],
): SpeechSynthesisVoice | undefined {
  const normalizedLocale = resolveSpeechLocale(locale).toLowerCase();
  const [languagePrefix = ""] = normalizedLocale.split("-");
  const localePrefix = `${languagePrefix}-`;

  return (
    voices.find((voice) => voice.lang.toLowerCase() === normalizedLocale) ??
    voices.find((voice) => voice.lang.toLowerCase().startsWith(localePrefix)) ??
    voices.find((voice) => voice.default) ??
    voices.at(0)
  );
}

function resolveSelectedVoice(
  selectedVoiceId: string,
  locale: string,
  voices: readonly SpeechSynthesisVoice[],
): string {
  if (voices.length === 0) {
    return AI_CHAT_VOICE_DEFAULT_ID;
  }

  const selectedVoice = resolveVoiceById(selectedVoiceId, voices);
  if (selectedVoice) {
    return selectedVoiceId;
  }

  return resolveLocaleVoice(locale, voices)?.voiceURI ?? AI_CHAT_VOICE_DEFAULT_ID;
}

function speakWithSelectedVoice(input: SpeakVoiceInput): void {
  const selectedVoice = resolveVoiceById(input.selectedVoiceId, input.voices);
  input.speech.speak(input.text, {
    lang: resolveSpeechLocale(input.locale),
    ...(selectedVoice ? { voice: selectedVoice } : {}),
  });
}

function registerVoiceWatchers(input: VoiceWatchInput): void {
  watch(
    [input.voices, () => input.locale.value],
    ([availableVoices, localeValue]) => {
      input.selectedVoiceId.value = resolveSelectedVoice(
        input.selectedVoiceId.value,
        localeValue,
        availableVoices,
      );
    },
    { immediate: true },
  );

  watch(
    () => input.speech.fullTranscript.value,
    (transcriptValue) => {
      if (transcriptValue.length > 0) {
        input.draft.value = transcriptValue;
      }
    },
  );

  watch(
    () => input.messages.value.length,
    (nextLength, previousLength) => {
      if (!(input.speech.supportsSynthesis.value && input.autoSpeakReplies.value)) {
        return;
      }
      if (nextLength <= previousLength) {
        return;
      }
      const newestMessage = input.messages.value.at(-1);
      if (newestMessage?.role !== "assistant") {
        return;
      }
      const trimmedContent = newestMessage.content.trim();
      if (trimmedContent.length > 0) {
        speakWithSelectedVoice({
          speech: input.speech,
          text: trimmedContent,
          locale: input.locale.value,
          selectedVoiceId: input.selectedVoiceId.value,
          voices: input.voices.value,
        });
      }
    },
  );
}

function createVoiceActions(input: VoiceActionInput, t: ComposerTranslation) {
  const startListening = (): boolean => {
    if (!input.speech.supportsRecognition.value) {
      return false;
    }
    return input.speech.startListening(resolveSpeechLocale(input.locale.value));
  };

  const stopListening = (): void => {
    input.speech.stopListening();
  };

  const toggleListening = (): boolean => {
    if (input.speech.isListening.value) {
      stopListening();
      return true;
    }
    return startListening();
  };

  const speakLatestAssistantMessage = (): boolean => {
    if (!input.canReplayAssistant.value) {
      return false;
    }
    speakWithSelectedVoice({
      speech: input.speech,
      text: input.latestAssistantMessage.value,
      locale: input.locale.value,
      selectedVoiceId: input.selectedVoiceId.value,
      voices: input.voices.value,
    });
    return true;
  };

  /** On-device TTS sample — does not require an assistant message (Web Speech API). */
  const testOnDeviceTts = (): boolean => {
    if (!input.speech.supportsSynthesis.value) {
      return false;
    }
    speakWithSelectedVoice({
      speech: input.speech,
      text: t("aiChatCommon.voice.testOnDeviceSample"),
      locale: input.locale.value,
      selectedVoiceId: input.selectedVoiceId.value,
      voices: input.voices.value,
    });
    return true;
  };

  return {
    startListening,
    stopListening,
    toggleListening,
    speakLatestAssistantMessage,
    testOnDeviceTts,
  };
}

function createVoiceComputedState(
  options: UseChatVoiceOptions,
  speech: ReturnType<typeof useSpeech>,
): VoiceComputedState {
  const autoSpeakReplies = useNuxtState<boolean>(
    STATE_KEYS.AI_CHAT_AUTO_SPEAK,
    () => AI_CHAT_VOICE_AUTO_SPEAK_DEFAULT,
  );
  const selectedVoiceId = useNuxtState<string>(
    STATE_KEYS.AI_CHAT_VOICE_ID,
    () => AI_CHAT_VOICE_DEFAULT_ID,
  );
  const voices = computed(() => speech.voices.value);
  const latestAssistantMessage = computed(() =>
    resolveLatestAssistantMessage(options.messages.value),
  );
  const canReplayAssistant = computed(
    () => speech.supportsSynthesis.value && latestAssistantMessage.value.length > 0,
  );

  return {
    autoSpeakReplies,
    selectedVoiceId,
    voices,
    latestAssistantMessage,
    canReplayAssistant,
    errorMessageKey: computed(() => resolveSpeechErrorMessageKey(speech.error.value)),
    supportHintKey: computed(() =>
      resolveVoiceSupportHintKey(speech.supportsRecognition.value, speech.supportsSynthesis.value),
    ),
  };
}

/**
 * Voice controls shared by floating chat and full chat page.
 *
 * @param options Chat input and message refs.
 * @returns Reactive voice controls and status values.
 */
export function useChatVoice(options: UseChatVoiceOptions) {
  const { t } = useI18n();
  const speech = useSpeech();
  const state = createVoiceComputedState(options, speech);

  registerVoiceWatchers({
    speech,
    locale: options.locale,
    messages: options.messages,
    draft: options.draft,
    autoSpeakReplies: state.autoSpeakReplies,
    selectedVoiceId: state.selectedVoiceId,
    voices: state.voices,
  });
  const actions = createVoiceActions(
    {
      speech,
      locale: options.locale,
      selectedVoiceId: state.selectedVoiceId,
      voices: state.voices,
      latestAssistantMessage: state.latestAssistantMessage,
      canReplayAssistant: state.canReplayAssistant,
    },
    t,
  );

  const cleanup = () => {
    speech.stopListening();
    speech.stopSpeaking();
  };
  if (getCurrentScope()) {
    onScopeDispose(cleanup);
  }

  return {
    autoSpeakReplies: state.autoSpeakReplies,
    selectedVoiceId: state.selectedVoiceId,
    voices: state.voices,
    canReplayAssistant: state.canReplayAssistant,
    errorMessageKey: state.errorMessageKey,
    supportHintKey: state.supportHintKey,
    isListening: speech.isListening,
    isSpeaking: speech.isSpeaking,
    supportsRecognition: speech.supportsRecognition,
    supportsSynthesis: speech.supportsSynthesis,
    isSupported: speech.isSupported,
    ...actions,
  };
}

import { buildCoverLetterExportEndpoint } from "@bao/shared/constants/endpoints";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { CoverLetterData } from "@bao/shared/types/cover-letter";
import type { JsonObject } from "@bao/shared/utils/json";
import { isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import type { ClientApi } from "~/types/client-api";
import { toCoverLetterData } from "./api-normalizer-cover-letter";
import {
  type ClientApiRequestRuntime,
  downloadApiFile,
  useClientApiRequestRuntime,
} from "./api-request";
import { useApi } from "./useApi";

interface CreateCoverLetterInput {
  company: string;
  position: string;
  jobInfo?: Record<string, unknown>;
  content?: CoverLetterData["content"];
  template?: CoverLetterData["template"];
}

type UpdateCoverLetterInput = Partial<CreateCoverLetterInput>;

export interface GenerateCoverLetterInput {
  company: string;
  position: string;
  resumeId?: string;
  template?: CoverLetterData["template"];
  save?: boolean;
  jobInfo?: JsonObject;
  /**
   * Ids let the server load the scraped posting and the studio record itself, so the
   * prompt carries their real attributes instead of only the free-text description
   * the user happened to paste into `jobInfo`.
   */
  jobId?: string;
  studioId?: string;
}

export type GenerateCoverLetterResult =
  | {
      message: string;
      content: CoverLetterData["content"];
    }
  | {
      message: string;
      coverLetter: CoverLetterData;
    };

interface CoverLetterContext {
  api: ClientApi;
  runtime: ClientApiRequestRuntime;
  toast: ReturnType<typeof useNuxtApp>["$toast"];
  t: ReturnType<typeof useI18n>["t"];
  loading: ReturnType<typeof useState<boolean>>;
  coverLetters: ReturnType<typeof useState<CoverLetterData[]>>;
  currentLetter: ReturnType<typeof useState<CoverLetterData | null>>;
}

const readApiData = async (
  request: Promise<unknown>,
  fallbackMessage: string,
): Promise<unknown> => {
  const response = await request;
  if (!(isRecord(response) || Array.isArray(response))) {
    throw new Error(fallbackMessage);
  }
  if (isRecord(response) && "error" in response && response.error) {
    throw new Error(fallbackMessage);
  }
  if (isRecord(response) && "data" in response) {
    return response.data;
  }
  return response;
};

const toCoverLetterContent = (value: unknown): CoverLetterData["content"] | null => {
  if (!isRecord(value)) {
    return null;
  }

  const content: CoverLetterData["content"] = {};
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === "string") {
      content[key] = entry;
    }
  }

  return Object.keys(content).length > 0 ? content : null;
};

const toGenerateCoverLetterResult = (value: unknown): GenerateCoverLetterResult | null => {
  if (!isRecord(value)) {
    return null;
  }

  const message = typeof value.message === "string" ? value.message : "";
  const content = toCoverLetterContent(value.content);
  if (content) {
    return { message, content };
  }

  const coverLetter = toCoverLetterData(value.coverLetter);
  if (!coverLetter) {
    return null;
  }

  return {
    message,
    coverLetter,
  };
};

async function fetchCoverLetters(context: CoverLetterContext): Promise<void> {
  context.loading.value = true;
  const data = await readApiData(
    context.api["cover-letters"].get(),
    context.t("coverLetterPage.toasts.fetchFailed"),
  );
  context.loading.value = false;

  const rows = Array.isArray(data) ? data : [];
  context.coverLetters.value = rows
    .map((row) => toCoverLetterData(row))
    .filter((row): row is CoverLetterData => row !== null);
}

async function getCoverLetter(
  context: CoverLetterContext,
  id: string,
): Promise<CoverLetterData | null> {
  context.loading.value = true;
  const data = await readApiData(
    context.api["cover-letters"]({ id }).get(),
    context.t("coverLetterDetailPage.toasts.loadFailed"),
  );
  context.loading.value = false;

  const normalized = toCoverLetterData(data);
  if (!normalized) {
    context.toast.error(context.t("coverLetterDetailPage.toasts.loadFailed"));
    return null;
  }

  context.currentLetter.value = normalized;
  return normalized;
}

async function createCoverLetter(
  context: CoverLetterContext,
  letterData: CreateCoverLetterInput,
): Promise<CoverLetterData | null> {
  context.loading.value = true;
  const data = await readApiData(
    context.api["cover-letters"].post(letterData),
    context.t("coverLetterPage.toasts.generateFailed"),
  );
  context.loading.value = false;

  const normalized = toCoverLetterData(data);
  if (!normalized) {
    context.toast.error(context.t("coverLetterPage.toasts.generateFailed"));
    return null;
  }

  await fetchCoverLetters(context);
  return normalized;
}

async function updateCoverLetter(
  context: CoverLetterContext,
  id: string,
  updates: UpdateCoverLetterInput,
): Promise<CoverLetterData | null> {
  context.loading.value = true;
  const data = await readApiData(
    context.api["cover-letters"]({ id }).put(updates),
    context.t("coverLetterDetailPage.toasts.saveFailed"),
  );
  context.loading.value = false;

  const normalized = toCoverLetterData(data);
  if (normalized) {
    context.currentLetter.value = normalized;
  }
  await fetchCoverLetters(context);
  return normalized;
}

async function deleteCoverLetter(context: CoverLetterContext, id: string): Promise<void> {
  context.loading.value = true;
  const { error } = await context.api["cover-letters"]({ id }).delete();
  if (error) {
    context.loading.value = false;
    throw new Error(context.t("coverLetterDetailPage.toasts.saveFailed"));
  }
  context.loading.value = false;

  if (context.currentLetter.value?.id === id) {
    context.currentLetter.value = null;
  }
  await fetchCoverLetters(context);
}

async function generateCoverLetter(
  context: CoverLetterContext,
  generationData: GenerateCoverLetterInput,
): Promise<GenerateCoverLetterResult | null> {
  context.loading.value = true;
  const data = await readApiData(
    context.api["cover-letters"].generate.post(generationData),
    context.t("coverLetterPage.toasts.generateFailed"),
  );
  context.loading.value = false;

  if (generationData.save) {
    await fetchCoverLetters(context);
  }
  return toGenerateCoverLetterResult(data);
}

async function exportDocument(
  context: CoverLetterContext,
  id: string,
  format?: string,
  template?: string,
): Promise<void> {
  context.loading.value = true;
  // Binary download stays on downloadApiFile (Eden Treaty JSON envelope unsuitable for blobs).
  const body: { format?: string; template?: string } = {};
  if (format) {
    body.format = format;
  }
  if (template) {
    body.template = template;
  }
  await downloadApiFile(
    context.runtime,
    buildCoverLetterExportEndpoint(id),
    {
      method: "POST",
      body,
    },
    `cover-letter-${id}.${format === "docx" ? "docx" : "pdf"}`,
  );
  context.loading.value = false;
}

/**
 * Cover letter management composable — Eden Treaty for JSON CRUD/generate.
 */
export function useCoverLetter() {
  const context: CoverLetterContext = {
    api: useApi(),
    runtime: useClientApiRequestRuntime(),
    toast: useNuxtApp().$toast,
    t: useI18n().t,
    coverLetters: useState<CoverLetterData[]>(STATE_KEYS.COVERLETTERS_LIST, () => []),
    currentLetter: useState<CoverLetterData | null>(STATE_KEYS.COVERLETTER_CURRENT, () => null),
    loading: useState(STATE_KEYS.COVERLETTER_LOADING, () => false),
  };

  return {
    coverLetters: readonly(context.coverLetters),
    currentLetter: readonly(context.currentLetter),
    loading: readonly(context.loading),
    fetchCoverLetters: () => fetchCoverLetters(context),
    getCoverLetter: (id: string) => getCoverLetter(context, id),
    createCoverLetter: (letterData: CreateCoverLetterInput) =>
      createCoverLetter(context, letterData),
    updateCoverLetter: (id: string, updates: UpdateCoverLetterInput) =>
      updateCoverLetter(context, id, updates),
    deleteCoverLetter: (id: string) => deleteCoverLetter(context, id),
    generateCoverLetter: (generationData: GenerateCoverLetterInput) =>
      generateCoverLetter(context, generationData),
    exportDocument: (id: string, format?: string, template?: string) =>
      exportDocument(context, id, format, template),
  };
}

