import type { Ref } from "vue";
import { onScopeDispose, ref, watch } from "vue";

/**
 * Returns a debounced mirror of a source ref value.
 *
 * @param source Source reactive value to debounce.
 * @param delayMs Debounce duration in milliseconds.
 * @returns Debounced ref that updates after the provided delay.
 */
export function useDebouncedValue<T>(source: Readonly<Ref<T>>, delayMs: number): Ref<T> {
  const debouncedValue = ref(source.value) as Ref<T>;
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  watch(
    source,
    (nextValue) => {
      if (timeoutId !== null) {
        clearTimeout(timeoutId);
      }

      timeoutId = setTimeout(() => {
        debouncedValue.value = nextValue;
        timeoutId = null;
      }, delayMs);
    },
    { deep: true },
  );

  onScopeDispose(() => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }
  });

  return debouncedValue;
}

import { ref } from "vue";

export function useDeleteConfirmation() {
  const showDeleteDialog = ref(false);
  const pendingDeleteId = ref<string | null>(null);

  function requestDelete(id: string): void {
    pendingDeleteId.value = id;
    showDeleteDialog.value = true;
  }

  function clearDeleteState(): void {
    pendingDeleteId.value = null;
  }

  function closeDeleteDialog(): void {
    clearDeleteState();
    showDeleteDialog.value = false;
  }

  return {
    showDeleteDialog,
    pendingDeleteId,
    requestDelete,
    clearDeleteState,
    closeDeleteDialog,
  };
}

import { settle } from "@bao/shared/utils/promise";
import { EDITOR_AUTOSAVE_DEBOUNCE_MS } from "~/constants/editor";

/**
 * Dirty tracking + debounced autosave for writing/JSON editors.
 */
export function useEditorChrome(options: {
  readonly getFingerprint: () => string;
  readonly onAutosave: () => void | Promise<void>;
  readonly debounceMs?: number;
}) {
  const savedFingerprint = ref(options.getFingerprint());
  const isDirty = computed(() => options.getFingerprint() !== savedFingerprint.value);
  let timer: ReturnType<typeof setTimeout> | null = null;

  const markSaved = (): void => {
    savedFingerprint.value = options.getFingerprint();
  };

  const scheduleAutosave = (): void => {
    if (timer) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      timer = null;
      if (!isDirty.value) {
        return;
      }
      settle(Promise.resolve(options.onAutosave())).then(
        (result) => {
          if (result.status === "fulfilled") {
            markSaved();
          }
        },
        () => undefined,
      );
    }, options.debounceMs ?? EDITOR_AUTOSAVE_DEBOUNCE_MS);
  };

  const notifyEdited = (): void => {
    scheduleAutosave();
  };

  onBeforeUnmount(() => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
  });

  return {
    isDirty,
    markSaved,
    notifyEdited,
    scheduleAutosave,
  };
}

import { computed, type MaybeRefOrGetter, toValue } from "vue";
import { resolveFlowRecommendations } from "~/constants/flow-engine";
import type {
  FlowEngineInput,
  FlowRecommendation,
  FlowResolution,
  FlowStage,
} from "~/constants/flow-engine-types";

/**
 * Reactive interface around the global flow recommendation engine.
 *
 * @param input Reactive or static flow-engine input.
 * @returns Computed primary action, recommendations, stage, and next-step label.
 */
export function useFlowEngine(input: MaybeRefOrGetter<FlowEngineInput>) {
  const resolution = computed<FlowResolution>(() => resolveFlowRecommendations(toValue(input)));

  const primaryAction = computed<FlowRecommendation>(() => resolution.value.primaryAction);
  const recommendedActions = computed<readonly FlowRecommendation[]>(
    () => resolution.value.recommendedActions,
  );
  const nextStepLabel = computed<string>(() => resolution.value.nextStepLabel);
  const flowStage = computed<FlowStage>(() => resolution.value.flowStage);

  return {
    primaryAction,
    recommendedActions,
    nextStepLabel,
    flowStage,
  };
}

import type { MaybeRefOrGetter, ShallowRef } from "vue";
import { getCurrentScope, onScopeDispose, toValue, watch } from "vue";

const FOCUSABLE_SELECTORS = [
  "a[href]",
  "area[href]",
  "button:not([disabled])",
  "input:not([disabled]):not([type='hidden'])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  "iframe",
  "object",
  "embed",
  "[contenteditable='true']",
  "[tabindex]:not([tabindex='-1'])",
].join(",");

type FocusBoundary = {
  first: HTMLElement;
  last: HTMLElement;
};

function isVisibleElement(element: HTMLElement): boolean {
  return element.getClientRects().length > 0;
}

function getFocusableElements(container: HTMLElement): HTMLElement[] {
  return Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTORS)).filter(
    (element) =>
      !element.hasAttribute("disabled") &&
      element.getAttribute("aria-hidden") !== "true" &&
      isVisibleElement(element),
  );
}

function resolveFocusBoundary(dialog: HTMLDialogElement): FocusBoundary | null {
  const focusableElements = getFocusableElements(dialog);
  const firstElement = focusableElements[0];
  const lastElement = focusableElements.at(-1);
  if (!(firstElement && lastElement)) {
    return null;
  }

  return {
    first: firstElement,
    last: lastElement,
  };
}

function focusDialogEntry(dialog: HTMLDialogElement): void {
  const boundary = resolveFocusBoundary(dialog);
  if (!boundary) {
    dialog.focus();
    return;
  }

  boundary.first.focus();
}

function resolveActiveElement(dialog: HTMLDialogElement): HTMLElement | null {
  const activeElement = document.activeElement;
  return activeElement instanceof HTMLElement && dialog.contains(activeElement)
    ? activeElement
    : null;
}

function cycleFocus(event: KeyboardEvent, dialog: HTMLDialogElement): void {
  const boundary = resolveFocusBoundary(dialog);
  if (!boundary) {
    event.preventDefault();
    dialog.focus();
    return;
  }

  const activeElement = resolveActiveElement(dialog);
  if (!activeElement) {
    event.preventDefault();
    boundary.first.focus();
    return;
  }

  if (event.shiftKey && activeElement === boundary.first) {
    event.preventDefault();
    boundary.last.focus();
    return;
  }

  if (!event.shiftKey && activeElement === boundary.last) {
    event.preventDefault();
    boundary.first.focus();
  }
}

/**
 * Traps keyboard focus inside an open dialog to keep modal interactions WCAG-compliant.
 */
export function useFocusTrap(
  dialogRef: Readonly<ShallowRef<HTMLDialogElement | null>>,
  enabled: MaybeRefOrGetter<boolean> = true,
): void {
  const onKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== "Tab") {
      return;
    }

    const dialog = dialogRef.value;
    if (!dialog?.open) {
      return;
    }

    cycleFocus(event, dialog);
  };

  let releaseTrap: (() => void) | null = null;

  const detachTrap = (): void => {
    releaseTrap?.();
    releaseTrap = null;
  };

  watch(
    () => {
      const dialog = dialogRef.value;
      return Boolean(dialog?.open && toValue(enabled));
    },
    (active) => {
      detachTrap();

      const dialog = dialogRef.value;
      if (!(active && dialog)) {
        return;
      }

      focusDialogEntry(dialog);
      dialog.addEventListener("keydown", onKeyDown);
      releaseTrap = () => {
        dialog.removeEventListener("keydown", onKeyDown);
      };
    },
    { immediate: true, flush: "post" },
  );

  if (getCurrentScope()) {
    onScopeDispose(detachTrap);
  }
}

import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type {
  Achievement,
  DailyChallenge,
  UserGamificationData,
} from "@bao/shared/types/gamification";
import type { JsonObject, JsonValue } from "@bao/shared/utils/json";
import { asJsonArray, isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import {
  GAMIFICATION_STREAK_DAYS,
  GAMIFICATION_STREAK_MULTIPLIER,
  GAMIFICATION_XP_LEVEL_DIVISOR,
} from "~/constants/numeric-ui";
import { withLoadingState } from "./async-flow";
import { parseAchievementList, parseDailyChallengeList } from "./gamification-entity-normalizers";

interface GamificationState {
  progress: ReturnType<typeof useState<UserGamificationData | null>>;
  achievements: ReturnType<typeof useState<Achievement[]>>;
  challenges: ReturnType<typeof useState<DailyChallenge[]>>;
  weeklyProgress: ReturnType<typeof useState<JsonObject | null>>;
  monthlyStats: ReturnType<typeof useState<JsonObject | null>>;
  loading: ReturnType<typeof useState<boolean>>;
}

interface GamificationContext extends GamificationState {
  api: ReturnType<typeof useApi>;
  t: ReturnType<typeof useI18n>["t"];
}

type GamificationStatKey = Exclude<keyof UserGamificationData["stats"], "actionHistory">;

const GAMIFICATION_STAT_KEYS: readonly GamificationStatKey[] = [
  "profileComplete",
  "skillsMapped",
  "portfolioItems",
  "jobApplications",
  "chatSessions",
  "resumesGenerated",
  "coverLettersGenerated",
  "savedJobs",
  "jobsSaved",
  "interviewScore",
  "dataExported",
  "earlyLogin",
  "totalTimeSpent",
  "featuresUsed",
  "dailyStreak",
  "weeklyProgress",
  "interviewsCompleted",
  "studiosExplored",
];

const readApiData = async <T>(request: Promise<T>, fallbackMessage: string): Promise<JsonValue> => {
  const response = await request;
  if (!isRecord(response) || !("data" in response)) {
    throw new Error(fallbackMessage);
  }
  if ("error" in response && response.error) {
    throw new Error(fallbackMessage);
  }
  return response.data ?? null;
};

const toNumberWithDefault = <T>(value: T, fallback: number): number =>
  typeof value === "number" ? value : fallback;

const toOptionalNumber = <T>(value: T): number | undefined =>
  typeof value === "number" ? value : undefined;

const toOptionalString = <T>(value: T): string | undefined =>
  typeof value === "string" ? value : undefined;

const toStringArray = <T>(value: T): string[] => {
  const entries = asJsonArray(value);
  if (!entries) {
    return [];
  }
  return entries.filter((entry): entry is string => typeof entry === "string");
};

const normalizeStats = <T>(value: T): UserGamificationData["stats"] => {
  const stats: UserGamificationData["stats"] = {};
  if (!isRecord(value)) {
    return stats;
  }

  for (const key of GAMIFICATION_STAT_KEYS) {
    const statValue = value[key];
    if (typeof statValue === "number") {
      stats[key] = statValue;
    }
  }
  return stats;
};

const normalizeDailyChallenges = <T>(value: T): Record<string, string[]> => {
  if (!isRecord(value)) {
    return {};
  }

  const dailyChallenges: Record<string, string[]> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (Array.isArray(entry)) {
      dailyChallenges[key] = toStringArray(entry);
    }
  }
  return dailyChallenges;
};

const normalizeProgress = <T>(value: T): UserGamificationData | null => {
  if (!isRecord(value)) {
    return null;
  }

  return {
    xp: toNumberWithDefault(value.xp, 0),
    level: toNumberWithDefault(value.level, 1),
    achievements: toStringArray(value.achievements),
    dailyChallenges: normalizeDailyChallenges(value.dailyChallenges),
    longestStreak: toNumberWithDefault(value.longestStreak, 0),
    currentStreak: toNumberWithDefault(value.currentStreak, 0),
    lastActiveDate: toOptionalString(value.lastActiveDate),
    stats: normalizeStats(value.stats),
    xpForNextLevel: toOptionalNumber(value.xpForNextLevel),
    streak: toOptionalNumber(value.streak),
  };
};

const createGamificationState = (): GamificationState => ({
  progress: useState<UserGamificationData | null>(STATE_KEYS.GAMIFICATION_PROGRESS, () => null),
  achievements: useState<Achievement[]>(STATE_KEYS.GAMIFICATION_ACHIEVEMENTS, () => []),
  challenges: useState<DailyChallenge[]>(STATE_KEYS.GAMIFICATION_CHALLENGES, () => []),
  weeklyProgress: useState<JsonObject | null>(STATE_KEYS.GAMIFICATION_WEEKLY, () => null),
  monthlyStats: useState<JsonObject | null>(STATE_KEYS.GAMIFICATION_MONTHLY, () => null),
  loading: useState(STATE_KEYS.GAMIFICATION_LOADING, () => false),
});

const createFetchProgressAction = (context: GamificationContext) => async () =>
  withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.gamification.progress.get(),
      context.t("apiErrors.gamification.fetchProgressFailed"),
    );
    const normalized = normalizeProgress(data);
    if (normalized) {
      context.progress.value = normalized;
    }
  });

const createAwardXpAction =
  (context: GamificationContext, fetchProgress: () => Promise<void>) =>
  async (amount: number, reason: string) =>
    withLoadingState(context.loading, async () => {
      await readApiData(
        context.api.gamification["award-xp"].post({ amount, reason }),
        context.t("apiErrors.gamification.awardXPFailed"),
      );
      await fetchProgress();
    });

const createFetchAchievementsAction = (context: GamificationContext) => async () =>
  withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.gamification.achievements.get(),
      context.t("apiErrors.gamification.fetchAchievementsFailed"),
    );
    context.achievements.value = parseAchievementList(data);
  });

const createFetchChallengesAction = (context: GamificationContext) => async () =>
  withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.gamification.challenges.get(),
      context.t("apiErrors.gamification.fetchChallengesFailed"),
    );
    if (!isRecord(data)) {
      context.challenges.value = [];
      return;
    }
    context.challenges.value = parseDailyChallengeList(data.challenges);
  });

const createCompleteChallengeAction =
  (
    context: GamificationContext,
    fetchChallenges: () => Promise<void>,
    fetchProgress: () => Promise<void>,
  ) =>
  async (id: string) =>
    withLoadingState(context.loading, async () => {
      await readApiData(
        context.api.gamification.challenges({ id }).complete.post(),
        context.t("apiErrors.gamification.completeChallengeFailed"),
      );
      await fetchChallenges();
      await fetchProgress();
    });

const createFetchWeeklyProgressAction = (context: GamificationContext) => async () =>
  withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.gamification.weekly.get(),
      context.t("apiErrors.gamification.fetchWeeklyFailed"),
    );
    context.weeklyProgress.value = isRecord(data) ? data : null;
  });

const createFetchMonthlyStatsAction = (context: GamificationContext) => async () =>
  withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.gamification.monthly.get(),
      context.t("apiErrors.gamification.fetchMonthlyFailed"),
    );
    context.monthlyStats.value = isRecord(data) ? data : null;
  });

const createGamificationComputedState = (state: GamificationState) => {
  const level = computed(() => {
    const xp = state.progress.value?.xp || 0;
    return Math.floor(Math.sqrt(xp / GAMIFICATION_XP_LEVEL_DIVISOR)) + 1;
  });

  const xpToNextLevel = computed(() => {
    const nextLevelXp = level.value ** 2 * GAMIFICATION_XP_LEVEL_DIVISOR;
    const currentXp = state.progress.value?.xp || 0;
    return nextLevelXp - currentXp;
  });

  const currentStreak = computed(
    () => state.progress.value?.currentStreak || state.progress.value?.streak || 0,
  );

  const streakMultiplier = computed(() => {
    const streak = currentStreak.value;
    if (streak >= GAMIFICATION_STREAK_DAYS.long) return GAMIFICATION_STREAK_MULTIPLIER.long;
    if (streak >= GAMIFICATION_STREAK_DAYS.medium) return GAMIFICATION_STREAK_MULTIPLIER.medium;
    if (streak >= GAMIFICATION_STREAK_DAYS.short) return GAMIFICATION_STREAK_MULTIPLIER.short;
    if (streak >= GAMIFICATION_STREAK_DAYS.start) return GAMIFICATION_STREAK_MULTIPLIER.start;
    return GAMIFICATION_STREAK_MULTIPLIER.none;
  });

  const actionHistory = computed<JsonValue[]>(() => {
    const weeklyValue = state.weeklyProgress.value;
    if (!(isRecord(weeklyValue) && Array.isArray(weeklyValue.actionHistory))) {
      return [];
    }
    return asJsonArray(weeklyValue.actionHistory) ?? [];
  });

  return {
    level,
    xpToNextLevel,
    currentStreak,
    streakMultiplier,
    actionHistory,
  };
};

/**
 * Gamification system composable for XP, achievements, and challenges.
 */
export function useGamification() {
  const state = createGamificationState();
  const context: GamificationContext = {
    ...state,
    api: useApi(),
    t: useI18n().t,
  };

  const fetchProgress = createFetchProgressAction(context);
  const fetchChallenges = createFetchChallengesAction(context);
  const actions = {
    fetchProgress,
    awardXP: createAwardXpAction(context, fetchProgress),
    fetchAchievements: createFetchAchievementsAction(context),
    fetchChallenges,
    completeChallenge: createCompleteChallengeAction(context, fetchChallenges, fetchProgress),
    fetchWeeklyProgress: createFetchWeeklyProgressAction(context),
    fetchMonthlyStats: createFetchMonthlyStatsAction(context),
  };
  const computedState = createGamificationComputedState(state);

  return {
    progress: readonly(state.progress),
    achievements: readonly(state.achievements),
    challenges: readonly(state.challenges),
    weeklyProgress: readonly(state.weeklyProgress),
    monthlyStats: readonly(state.monthlyStats),
    loading: readonly(state.loading),
    ...computedState,
    ...actions,
  };
}

import { INTERVIEW_FALLBACK_STUDIO_ID } from "@bao/shared/constants/interview";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { InterviewConfig, InterviewSession } from "@bao/shared/types/interview";
import { useI18n } from "vue-i18n";
import { assertApiResponse, requireValue, withLoadingState } from "./async-flow";
import { toInterviewSession, toInterviewSessions, toNumericRecord } from "./interview-normalizers";

interface SubmitResponseInput {
  questionId?: string;
  questionIndex?: number;
  response: string;
}

interface InterviewState {
  sessions: ReturnType<typeof useState<InterviewSession[]>>;
  currentSession: ReturnType<typeof useState<InterviewSession | null>>;
  stats: ReturnType<typeof useState<Record<string, number> | null>>;
  loading: ReturnType<typeof useState<boolean>>;
}

interface InterviewContext extends InterviewState {
  api: ReturnType<typeof useApi>;
  t: ReturnType<typeof useI18n>["t"];
}
const requireSession = (value: unknown, invalidMessage: string): InterviewSession =>
  requireValue(toInterviewSession(value), invalidMessage);

const createInterviewState = (): InterviewState => ({
  sessions: useState<InterviewSession[]>(STATE_KEYS.INTERVIEW_SESSIONS, () => []),
  currentSession: useState<InterviewSession | null>(
    STATE_KEYS.INTERVIEW_CURRENT_SESSION,
    () => null,
  ),
  stats: useState<Record<string, number> | null>(STATE_KEYS.INTERVIEW_STATS, () => null),
  loading: useState(STATE_KEYS.INTERVIEW_LOADING, () => false),
});

const createFetchSessionsAction = (context: InterviewContext) => async () =>
  withLoadingState(context.loading, async () => {
    const { data, error } = await context.api.interview.sessions.get();
    assertApiResponse(error, context.t("apiErrors.interview.fetchSessionsFailed"));
    context.sessions.value = toInterviewSessions(data);
  });

const createFetchStatsAction = (context: InterviewContext) => async () =>
  withLoadingState(context.loading, async () => {
    const { data, error } = await context.api.interview.stats.get();
    assertApiResponse(error, context.t("apiErrors.interview.fetchStatsFailed"));
    context.stats.value = toNumericRecord(data);
  });

const createStartSessionAction =
  (context: InterviewContext, fetchSessions: () => Promise<void>) =>
  async (studioId?: string, config?: Partial<InterviewConfig>) =>
    withLoadingState(context.loading, async () => {
      const trimmedStudioId = studioId?.trim() ?? "";
      const resolvedStudioId =
        trimmedStudioId.length > 0 ? trimmedStudioId : INTERVIEW_FALLBACK_STUDIO_ID;
      const { data, error } = await context.api.interview.sessions.post({
        studioId: resolvedStudioId,
        config,
      });
      assertApiResponse(error, context.t("apiErrors.interview.startFailed"));
      const normalized = requireSession(data, context.t("apiErrors.interview.invalidPayload"));
      context.currentSession.value = normalized;
      await fetchSessions();
      return normalized;
    });

const createGetSessionAction = (context: InterviewContext) => async (id: string) =>
  withLoadingState(context.loading, async () => {
    const { data, error } = await context.api.interview.sessions({ id }).get();
    assertApiResponse(error, context.t("apiErrors.interview.fetchSessionFailed"));
    const normalized = requireSession(data, context.t("apiErrors.interview.invalidPayload"));
    context.currentSession.value = normalized;
    return normalized;
  });

const createSubmitResponseAction =
  (context: InterviewContext) => async (sessionId: string, response: SubmitResponseInput) =>
    withLoadingState(context.loading, async () => {
      const { data, error } = await context.api.interview
        .sessions({ id: sessionId })
        .response.post(response);
      assertApiResponse(error, context.t("apiErrors.interview.submitResponseFailed"));
      const normalized = requireSession(data, context.t("apiErrors.interview.invalidPayload"));
      context.currentSession.value = normalized;
      return normalized;
    });

const createCompleteSessionAction =
  (
    context: InterviewContext,
    fetchSessions: () => Promise<void>,
    fetchStats: () => Promise<void>,
  ) =>
  async (id: string) =>
    withLoadingState(context.loading, async () => {
      const { data, error } = await context.api.interview.sessions({ id }).complete.post();
      assertApiResponse(error, context.t("apiErrors.interview.completeFailed"));
      const normalized = requireSession(data, context.t("apiErrors.interview.invalidPayload"));
      context.currentSession.value = normalized;
      await fetchSessions();
      await fetchStats();
      return normalized;
    });

/**
 * Interview practice session management composable.
 */
export function useInterview() {
  const state = createInterviewState();
  const context: InterviewContext = {
    ...state,
    api: useApi(),
    t: useI18n().t,
  };

  const fetchSessions = createFetchSessionsAction(context);
  const fetchStats = createFetchStatsAction(context);
  const actions = {
    startSession: createStartSessionAction(context, fetchSessions),
    fetchSessions,
    getSession: createGetSessionAction(context),
    submitResponse: createSubmitResponseAction(context),
    completeSession: createCompleteSessionAction(context, fetchSessions, fetchStats),
    fetchStats,
  };

  return {
    sessions: readonly(state.sessions),
    currentSession: readonly(state.currentSession),
    stats: readonly(state.stats),
    loading: readonly(state.loading),
    ...actions,
  };
}

