import { useI18n } from "vue-i18n";
import { normalizeRoutePath, resolveLongestMatchingSidebarNavItem } from "~/constants/navigation";

/**
 * Section label for the app navbar — current peer section only.
 * Nested page hierarchies use page-level `AppBreadcrumbs` (no fake Dashboard parent).
 */
export function useNavbarBreadcrumbs() {
  const route = useRoute();
  const { t } = useI18n();

  const navbarBreadcrumbs = computed(() => {
    const normalized = normalizeRoutePath(route.path);
    if (normalized === "/") {
      return [{ label: t("nav.dashboard") }] as const;
    }

    const section = resolveLongestMatchingSidebarNavItem(route.path);
    if (!section) {
      return [{ label: t("nav.breadcrumbUnknown") }] as const;
    }

    return [{ label: t(section.labelKey) }] as const;
  });

  return { navbarBreadcrumbs };
}

import type { ComputedRef, Ref, WatchSource } from "vue";
import { computed, ref, watch } from "vue";

const FIRST_PAGE = 1;
const MIN_PAGE_SIZE = 1;

function clampToRange(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

interface PaginationComputeds<T> {
  totalItems: ComputedRef<number>;
  totalPages: ComputedRef<number>;
  pageNumbers: ComputedRef<readonly number[]>;
  itemsForCurrentPage: ComputedRef<readonly T[]>;
  rangeStart: ComputedRef<number>;
  rangeEnd: ComputedRef<number>;
  hasMultiplePages: ComputedRef<boolean>;
}

function createPaginationComputeds<T>(
  items: ComputedRef<readonly T[]>,
  currentPage: Ref<number>,
  normalizedPageSize: number,
): PaginationComputeds<T> {
  const totalItems = computed(() => items.value.length);
  const totalPages = computed(() =>
    totalItems.value === 0 ? FIRST_PAGE : Math.ceil(totalItems.value / normalizedPageSize),
  );
  const pageNumbers = computed(() => {
    const pages: number[] = [];
    for (let page = FIRST_PAGE; page <= totalPages.value; page += 1) {
      pages.push(page);
    }
    return pages;
  });
  const itemsForCurrentPage = computed(() => {
    const startIndex = (currentPage.value - FIRST_PAGE) * normalizedPageSize;
    return items.value.slice(startIndex, startIndex + normalizedPageSize);
  });
  const rangeStart = computed(() =>
    totalItems.value === 0 ? 0 : (currentPage.value - FIRST_PAGE) * normalizedPageSize + FIRST_PAGE,
  );
  const rangeEnd = computed(() =>
    totalItems.value === 0
      ? 0
      : Math.min(totalItems.value, rangeStart.value + normalizedPageSize - FIRST_PAGE),
  );

  return {
    totalItems,
    totalPages,
    pageNumbers,
    itemsForCurrentPage,
    rangeStart,
    rangeEnd,
    hasMultiplePages: computed(() => totalPages.value > FIRST_PAGE),
  };
}

function registerPaginationWatchers(
  currentPage: Ref<number>,
  totalPages: ComputedRef<number>,
  resetSources: readonly WatchSource[],
): void {
  watch(totalPages, (nextTotalPages) => {
    if (currentPage.value > nextTotalPages) {
      currentPage.value = nextTotalPages;
    }
  });

  if (resetSources.length > 0) {
    watch([...resetSources], () => {
      currentPage.value = FIRST_PAGE;
    });
  }
}

/**
 * Reactive pagination state derived from a computed item collection.
 */
export interface PaginationState<T> {
  currentPage: Ref<number>;
  totalPages: ComputedRef<number>;
  pageNumbers: ComputedRef<readonly number[]>;
  totalItems: ComputedRef<number>;
  rangeStart: ComputedRef<number>;
  rangeEnd: ComputedRef<number>;
  hasMultiplePages: ComputedRef<boolean>;
  items: ComputedRef<readonly T[]>;
  goToPage: (page: number) => void;
  goToPreviousPage: () => void;
  goToNextPage: () => void;
}

/**
 * Build deterministic pagination state for a computed list.
 *
 * @param items Reactive list source.
 * @param pageSize Number of items per page.
 * @param resetSources Reactive sources that reset to page 1 when changed.
 * @returns Reactive pagination values and navigation helpers.
 */
export function usePagination<T>(
  items: ComputedRef<readonly T[]>,
  pageSize: number,
  resetSources: readonly WatchSource[] = [],
): PaginationState<T> {
  const normalizedPageSize = Math.max(MIN_PAGE_SIZE, Math.trunc(pageSize));
  const currentPage = ref(FIRST_PAGE);
  const computedState = createPaginationComputeds(items, currentPage, normalizedPageSize);

  const goToPage = (page: number): void => {
    currentPage.value = clampToRange(page, FIRST_PAGE, computedState.totalPages.value);
  };
  const goToPreviousPage = (): void => {
    goToPage(currentPage.value - FIRST_PAGE);
  };
  const goToNextPage = (): void => {
    goToPage(currentPage.value + FIRST_PAGE);
  };

  registerPaginationWatchers(currentPage, computedState.totalPages, resetSources);

  return {
    currentPage,
    totalPages: computedState.totalPages,
    pageNumbers: computedState.pageNumbers,
    totalItems: computedState.totalItems,
    rangeStart: computedState.rangeStart,
    rangeEnd: computedState.rangeEnd,
    hasMultiplePages: computedState.hasMultiplePages,
    items: computedState.itemsForCurrentPage,
    goToPage,
    goToPreviousPage,
    goToNextPage,
  };
}

import {
  PIPELINE_GAMIFICATION_REASONS,
  PIPELINE_GAMIFICATION_XP,
  type PipelineGamificationAction,
  type PipelineGamificationReason,
} from "@bao/shared/constants/gamification";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";

type AwardedReasonState = Partial<Record<PipelineGamificationReason, true>>;

/**
 * Result returned when awarding XP for a pipeline action.
 */
export interface PipelineGamificationAwardResult {
  /** Canonical reason passed to the gamification API. */
  readonly reason: PipelineGamificationReason;
  /** XP amount associated with the action. */
  readonly amount: number;
  /** True only when XP was awarded in this call. */
  readonly awarded: boolean;
}

/**
 * Centralized XP award flow for end-to-end pipeline actions.
 * Awards each action once per client session to prevent duplicate farming.
 */
export function usePipelineGamification() {
  const { awardXP } = useGamification();
  const awardedReasons = useState<AwardedReasonState>(
    STATE_KEYS.PIPELINE_GAMIFICATION_AWARDED,
    () => ({}),
  );

  /**
   * Attempts to award XP for a pipeline action.
   *
   * @param action Canonical pipeline action.
   * @returns Award result with amount and reason metadata.
   */
  async function awardForAction(
    action: PipelineGamificationAction,
  ): Promise<PipelineGamificationAwardResult> {
    const reason = PIPELINE_GAMIFICATION_REASONS[action];
    const amount = PIPELINE_GAMIFICATION_XP[action];

    if (awardedReasons.value[reason]) {
      return {
        reason,
        amount,
        awarded: false,
      };
    }

    await awardXP(amount, reason);
    awardedReasons.value = {
      ...awardedReasons.value,
      [reason]: true,
    };

    return {
      reason,
      amount,
      awarded: true,
    };
  }

  return {
    awardForAction,
  };
}

import { API_ENDPOINTS } from "@bao/shared/constants/endpoints";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type {
  PortfolioData,
  PortfolioMetadata,
  PortfolioProject,
} from "@bao/shared/types/portfolio";
import { isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import { toPortfolioData } from "./api-normalizer-portfolio";
import {
  type ClientApiRequestRuntime,
  downloadApiFile,
  useClientApiRequestRuntime,
} from "./api-request";
import { assertApiResponse, withLoadingState } from "./async-flow";

type ApiClient = ReturnType<typeof useApi>;
type UpdatePortfolioPayload = NonNullable<Parameters<ApiClient["portfolio"]["put"]>[0]>;
type CreateProjectPayload = NonNullable<Parameters<ApiClient["portfolio"]["projects"]["post"]>[0]>;
type ProjectRoute = ReturnType<ApiClient["portfolio"]["projects"]>;
type UpdateProjectPayload = NonNullable<Parameters<ProjectRoute["put"]>[0]>;

interface PortfolioContext {
  api: ApiClient;
  t: ReturnType<typeof useI18n>["t"];
  loading: ReturnType<typeof useState<boolean>>;
  portfolio: ReturnType<typeof useState<PortfolioData | null>>;
  projects: ReturnType<typeof useState<PortfolioProject[]>>;
  runtime: ClientApiRequestRuntime;
}

const readApiData = async (
  request: Promise<unknown>,
  fallbackMessage: string,
): Promise<unknown> => {
  const response = await request;
  if (!(isRecord(response) && "data" in response)) {
    throw new Error(fallbackMessage);
  }
  if ("error" in response && response.error) {
    throw new Error(fallbackMessage);
  }
  return response.data;
};

function hydratePortfolio(context: PortfolioContext, next: PortfolioData | null): void {
  context.portfolio.value = next;
  context.projects.value = next && Array.isArray(next.projects) ? next.projects : [];
}

async function fetchPortfolio(context: PortfolioContext): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.portfolio.get(),
      context.t("apiErrors.portfolio.fetchFailed"),
    );
    hydratePortfolio(context, toPortfolioData(data));
  });
}

async function updatePortfolio(
  context: PortfolioContext,
  updates: Partial<PortfolioMetadata>,
): Promise<PortfolioData | null> {
  return withLoadingState(context.loading, async () => {
    const payload: UpdatePortfolioPayload = { metadata: updates };
    const data = await readApiData(
      context.api.portfolio.put(payload),
      context.t("apiErrors.portfolio.updateFailed"),
    );
    const normalized = toPortfolioData(data);
    hydratePortfolio(context, normalized);
    return normalized;
  });
}

async function addProject(
  context: PortfolioContext,
  projectData: CreateProjectPayload,
): Promise<void> {
  return withLoadingState(context.loading, async () => {
    await readApiData(
      context.api.portfolio.projects.post(projectData),
      context.t("apiErrors.portfolio.addProjectFailed"),
    );
    await fetchPortfolio(context);
  });
}

async function updateProject(
  context: PortfolioContext,
  id: string,
  updates: UpdateProjectPayload,
): Promise<void> {
  return withLoadingState(context.loading, async () => {
    await readApiData(
      context.api.portfolio.projects({ id }).put(updates),
      context.t("apiErrors.portfolio.updateProjectFailed"),
    );
    await fetchPortfolio(context);
  });
}

async function deleteProject(context: PortfolioContext, id: string): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const { error } = await context.api.portfolio.projects({ id }).delete();
    assertApiResponse(error, context.t("apiErrors.portfolio.deleteProjectFailed"));
    await fetchPortfolio(context);
  });
}

async function reorderProjects(context: PortfolioContext, orderedIds: string[]): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.portfolio.projects.reorder.post({ orderedIds }),
      context.t("apiErrors.portfolio.reorderFailed"),
    );
    const normalized = toPortfolioData(data);
    hydratePortfolio(context, normalized);
  });
}

async function exportPortfolio(
  context: PortfolioContext,
  format?: string,
  template?: string,
): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const body: { format?: string; template?: string } = {};
    if (format) {
      body.format = format;
    }
    if (template) {
      body.template = template;
    }
    await downloadApiFile(
      context.runtime,
      `${API_ENDPOINTS.portfolio}/export`,
      {
        method: "POST",
        body,
      },
      `portfolio.${format === "docx" ? "docx" : "pdf"}`,
    );
  });
}

/**
 * Portfolio management composable.
 */
export function usePortfolio() {
  const context: PortfolioContext = {
    api: useApi(),
    t: useI18n().t,
    portfolio: useState<PortfolioData | null>(STATE_KEYS.PORTFOLIO_DATA, () => null),
    projects: useState<PortfolioProject[]>(STATE_KEYS.PORTFOLIO_PROJECTS, () => []),
    loading: useState(STATE_KEYS.PORTFOLIO_LOADING, () => false),
    runtime: useClientApiRequestRuntime(),
  };

  return {
    portfolio: readonly(context.portfolio),
    projects: readonly(context.projects),
    loading: readonly(context.loading),
    fetchPortfolio: () => fetchPortfolio(context),
    updatePortfolio: (updates: Partial<PortfolioMetadata>) => updatePortfolio(context, updates),
    addProject: (projectData: CreateProjectPayload) => addProject(context, projectData),
    updateProject: (id: string, updates: UpdateProjectPayload) =>
      updateProject(context, id, updates),
    deleteProject: (id: string) => deleteProject(context, id),
    reorderProjects: (orderedIds: string[]) => reorderProjects(context, orderedIds),
    exportPortfolio: (format?: string, template?: string) =>
      exportPortfolio(context, format, template),
  };
}

import {
  PORTFOLIO_PROJECT_DESCRIPTION_MIN_LENGTH,
  PORTFOLIO_PROJECT_TITLE_MIN_LENGTH,
} from "@bao/shared/constants/portfolio";
import { APP_ROUTE_QUERY_KEYS } from "@bao/shared/constants/routes";
import { useI18n } from "vue-i18n";
import { usePortfolioPageActions } from "~/composables/portfolio-page-actions";
import { usePortfolioPageDerived } from "~/composables/portfolio-page-derived";
import {
  PORTFOLIO_PROJECT_DIALOG_TITLE_ID,
  normalizePortfolioProject,
  usePortfolioPageState,
} from "~/composables/portfolio-page-state";

function usePortfolioPageDependencies() {
  return {
    i18n: useI18n(),
    nuxtApp: useNuxtApp(),
    portfolioApi: usePortfolio(),
    route: useRoute(),
  };
}

export function usePortfolioPage() {
  const { i18n, nuxtApp, portfolioApi, route } = usePortfolioPageDependencies();
  const state = usePortfolioPageState();
  const derived = usePortfolioPageDerived(
    {
      portfolioForm: state.portfolioForm,
      projects: portfolioApi.projects,
      searchQuery: state.searchQuery,
    },
    i18n.t,
  );

  async function loadPortfolio(): Promise<void> {
    await portfolioApi.fetchPortfolio();
    state.syncPortfolioMetadata(portfolioApi.portfolio.value?.metadata);
    const projectId = route.query[APP_ROUTE_QUERY_KEYS.id];
    if (typeof projectId === "string" && projectId.length > 0) {
      const match = portfolioApi.projects.value.find((project) => project.id === projectId);
      if (match) {
        state.openEditModal(normalizePortfolioProject(match));
      }
    }
  }

  const actions = usePortfolioPageActions(
    {
      addProject: portfolioApi.addProject,
      deleteProject: portfolioApi.deleteProject,
      deleteProjectState: {
        pendingDeleteProjectId: state.pendingDeleteProjectId,
        closeDeleteProjectDialog: state.closeDeleteProjectDialog,
        requestDeleteProjectConfirmation: state.requestDeleteProjectConfirmation,
      },
      displayProjects: derived.displayProjects,
      editingProject: state.editingProject,
      exportPortfolio: portfolioApi.exportPortfolio,
      exportTemplate: state.exportTemplate,
      newTech: state.newTech,
      portfolioForm: state.portfolioForm,
      projectForm: state.projectForm,
      projects: portfolioApi.projects,
      reorderProjects: portfolioApi.reorderProjects,
      reorderingProjectId: state.reorderingProjectId,
      updatePortfolio: portfolioApi.updatePortfolio,
      updateProject: portfolioApi.updateProject,
    },
    { $toast: nuxtApp.$toast },
    i18n.t,
  );

  return {
    PORTFOLIO_PROJECT_DESCRIPTION_MIN_LENGTH,
    PORTFOLIO_PROJECT_DIALOG_TITLE_ID,
    PORTFOLIO_PROJECT_TITLE_MIN_LENGTH,
    loadPortfolio,
    ...state,
    ...derived,
    ...actions,
    clearDeleteProjectState: state.clearDeleteProjectState,
    handleSaveProject: async () => {
      const saveSucceeded = await actions.handleSaveProject(state.clearProjectForm);
      if (saveSucceeded) {
        state.showAddModal.value = false;
      }
    },
    loading: portfolioApi.loading,
    portfolio: portfolioApi.portfolio,
    projects: portfolioApi.projects,
  };
}

import { buildResumeExportEndpoint } from "@bao/shared/constants/endpoints";
import type { ResumeTemplate } from "@bao/shared/constants/resume";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { ResumeData } from "@bao/shared/types/resume";
import { isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import type { ClientApi } from "~/types/client-api";
import { requireApiResponsePayload } from "~/utils/api-response";
import { toResumeData } from "./api-normalizer-resume";
import {
  type ClientApiRequestRuntime,
  downloadApiFile,
  useClientApiRequestRuntime,
} from "./api-request";
import { requireValue, withLoadingState } from "./async-flow";
import { useApi } from "./useApi";

type CreateResumeInput = Record<string, unknown>;
type UpdateResumeInput = Record<string, unknown>;
type ExportResumeInput = Record<string, unknown>;
type ScoreResumeInput = {
  jobId: string;
};
type ScoreResumeError = {
  details?: string;
  error: string;
};
type ScoreResumeSuccess = {
  [key: string]: unknown;
  details?: unknown;
  error?: undefined;
  score?: unknown;
};

type ResumeSynthesisSuccess = Partial<ResumeData> & {
  id: string;
  name?: string;
  personalInfo?: ResumeData["personalInfo"];
};

type ResumeSynthesisError = {
  error?: string;
  details?: string;
};

interface ResumeContext {
  api: ClientApi;
  t: ReturnType<typeof useI18n>["t"];
  loading: ReturnType<typeof useState<boolean>>;
  resumes: ReturnType<typeof useState<ResumeData[]>>;
  currentResume: ReturnType<typeof useState<ResumeData | null>>;
  runtime: ClientApiRequestRuntime;
}

interface ResumeExportRequest {
  id: string;
  template?: ResumeTemplate;
  format?: string;
}

const readApiData = async (
  request: Promise<unknown>,
  fallbackMessage: string,
): Promise<unknown> => {
  const response = await request;
  return requireApiResponsePayload(response, fallbackMessage);
};

const isResumeSynthesisError = (value: unknown): value is ResumeSynthesisError =>
  isRecord(value) && typeof value.error === "string";

const isResumeSynthesisSuccess = (value: unknown): value is ResumeSynthesisSuccess =>
  isRecord(value) && "id" in value && typeof value.id === "string";

const isResumeScoreError = (value: unknown): value is ScoreResumeError =>
  isRecord(value) && typeof value.error === "string";

const isResumeScoreSuccess = (value: unknown): value is ScoreResumeSuccess =>
  isRecord(value) && !("error" in value);

function toResumeList(value: unknown): ResumeData[] {
  return Array.isArray(value)
    ? value
        .map((entry) => toResumeData(entry))
        .filter((entry): entry is ResumeData => entry !== null)
    : [];
}

function toExportPayload(template?: ResumeTemplate, format?: string): ExportResumeInput {
  const payload: ExportResumeInput = {};
  if (template) {
    payload.template = template;
  }
  if (format) {
    payload.format = format;
  }
  return payload;
}

async function fetchResumes(context: ResumeContext): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.resumes.get(),
      context.t("apiErrors.resumes.fetchListFailed"),
    );
    context.resumes.value = toResumeList(data);
  });
}

async function getResume(context: ResumeContext, id: string): Promise<ResumeData> {
  return withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.resumes({ id }).get(),
      context.t("apiErrors.resumes.fetchFailed"),
    );
    const normalized = requireValue(
      toResumeData(data),
      context.t("apiErrors.resumes.invalidPayload"),
    );
    context.currentResume.value = normalized;
    return normalized;
  });
}

async function createResume(
  context: ResumeContext,
  resumeData: CreateResumeInput,
): Promise<ResumeData> {
  return withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.resumes.post(resumeData),
      context.t("apiErrors.resumes.createFailed"),
    );
    const normalized = requireValue(
      toResumeData(data),
      context.t("apiErrors.resumes.invalidPayload"),
    );
    await fetchResumes(context);
    return normalized;
  });
}

async function updateResume(
  context: ResumeContext,
  id: string,
  updates: UpdateResumeInput,
): Promise<ResumeData> {
  return withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.resumes({ id }).put(updates),
      context.t("apiErrors.resumes.updateFailed"),
    );
    const normalized = requireValue(
      toResumeData(data),
      context.t("apiErrors.resumes.invalidPayload"),
    );
    context.currentResume.value = normalized;
    await fetchResumes(context);
    return normalized;
  });
}

async function deleteResume(context: ResumeContext, id: string): Promise<void> {
  return withLoadingState(context.loading, async () => {
    await readApiData(
      context.api.resumes({ id }).delete(),
      context.t("apiErrors.resumes.deleteFailed"),
    );
    if (context.currentResume.value?.id === id) {
      context.currentResume.value = null;
    }
    await fetchResumes(context);
  });
}

async function performExportResume(
  context: ResumeContext,
  request: ResumeExportRequest,
): Promise<void> {
  return withLoadingState(context.loading, async () => {
    await downloadApiFile(
      context.runtime,
      buildResumeExportEndpoint(request.id),
      {
        method: "POST",
        body: toExportPayload(request.template, request.format),
      },
      `resume-${request.id}.${request.format === "docx" ? "docx" : "pdf"}`,
    );
  });
}

async function exportResume(
  context: ResumeContext,
  id: string,
  template?: ResumeTemplate,
  format?: string,
): Promise<unknown> {
  return performExportResume(context, {
    id,
    template,
    format,
  });
}

async function exportResumeOnePage(
  context: ResumeContext,
  id: string,
  template?: ResumeTemplate,
  format?: string,
): Promise<unknown> {
  return performExportResume(context, {
    id,
    template,
    format,
  });
}

async function aiEnhance(context: ResumeContext, id: string): Promise<ResumeData> {
  return withLoadingState(context.loading, async () => {
    const data = await readApiData(
      context.api.resumes({ id })["ai-enhance"].post({}),
      context.t("apiErrors.resumes.enhanceFailed"),
    );
    const normalized = requireValue(
      toResumeData(data),
      context.t("apiErrors.resumes.invalidPayload"),
    );
    context.currentResume.value = normalized;
    await fetchResumes(context);
    return normalized;
  });
}

async function aiScore(
  context: ResumeContext,
  id: string,
  jobId: string,
): Promise<ScoreResumeSuccess> {
  return withLoadingState(context.loading, async () => {
    const payload: ScoreResumeInput = { jobId };
    const data = await readApiData(
      context.api.resumes({ id })["ai-score"].post(payload),
      context.t("apiErrors.resumes.scoreFailed"),
    );
    if (isResumeScoreError(data)) {
      throw new Error(
        String(data.details ?? data.error ?? context.t("apiErrors.resumes.scoreFailed")),
      );
    }
    if (!isResumeScoreSuccess(data)) {
      throw new Error(context.t("apiErrors.resumes.scoreFailed"));
    }
    return data;
  });
}

async function generateCvQuestions(
  context: ResumeContext,
  config: {
    targetRole: string;
    studioName?: string;
    experienceLevel?: string;
  },
): Promise<Array<{ id: string; question: string; category: string }>> {
  const data = await readApiData(
    context.api.resumes["from-questions"].generate.post(config),
    context.t("apiErrors.resumes.fetchFailed"),
  );
  if (!isRecord(data) || !Array.isArray(data.questions)) {
    return [];
  }
  return data.questions.filter(
    (entry): entry is { id: string; question: string; category: string } =>
      isRecord(entry) &&
      typeof entry.id === "string" &&
      typeof entry.question === "string" &&
      typeof entry.category === "string",
  );
}

async function synthesizeCvResume(
  context: ResumeContext,
  questionsAndAnswers: Array<{ id: string; question: string; answer: string; category: string }>,
): Promise<ResumeSynthesisSuccess> {
  const response = await readApiData(
    context.api.resumes["from-questions"].synthesize.post({ questionsAndAnswers }),
    context.t("apiErrors.resumes.createFailed"),
  );

  if (isResumeSynthesisError(response) && response.error) {
    throw new Error(String(response.details ?? response.error ?? "Unknown error"));
  }
  if (!isResumeSynthesisSuccess(response)) {
    throw new Error("Resume synthesis payload is missing an id");
  }

  return response;
}

/**
 * Resume management composable — Eden JSON fabric; binary export stays downloadApiFile.
 */
export function useResume() {
  const context: ResumeContext = {
    api: useApi(),
    t: useI18n().t,
    runtime: useClientApiRequestRuntime(),
    resumes: useState<ResumeData[]>(STATE_KEYS.RESUME_LIST, () => []),
    currentResume: useState<ResumeData | null>(STATE_KEYS.RESUME_CURRENT, () => null),
    loading: useState(STATE_KEYS.RESUME_LOADING, () => false),
  };

  return {
    resumes: readonly(context.resumes),
    currentResume: readonly(context.currentResume),
    loading: readonly(context.loading),
    fetchResumes: () => fetchResumes(context),
    getResume: (id: string) => getResume(context, id),
    createResume: (resumeData: CreateResumeInput) => createResume(context, resumeData),
    updateResume: (id: string, updates: UpdateResumeInput) => updateResume(context, id, updates),
    deleteResume: (id: string) => deleteResume(context, id),
    exportResume: (id: string, template?: ResumeTemplate, format?: string) =>
      exportResume(context, id, template, format),
    exportResumeOnePage: (id: string, template?: ResumeTemplate, format?: string) =>
      exportResumeOnePage(context, id, template, format),
    aiEnhance: (id: string) => aiEnhance(context, id),
    aiScore: (id: string, jobId: string) => aiScore(context, id, jobId),
    generateCvQuestions: (config: {
      targetRole: string;
      studioName?: string;
      experienceLevel?: string;
    }) => generateCvQuestions(context, config),
    synthesizeCvResume: (
      questionsAndAnswers: Array<{
        id: string;
        question: string;
