import {
  AI_CHAT_VOICE_ERROR_CODES,
  AI_CHAT_VOICE_ERROR_MESSAGE_KEYS,
} from "@bao/shared/constants/ai-voice";
import type { VoiceSettings } from "@bao/shared/types/interview";
import type { Ref } from "vue";
import { computed, onMounted, onUnmounted, readonly, ref } from "#imports";
import { resolveSpeechLocale, resolveSpeechRecognitionConstructor } from "~/utils/speech";
import {
  createMicrophoneRecorder,
  type ServerSttRequestOptions,
  transcribeAudioViaServer,
} from "./speech-server-stt";
import { resolveSpeechSttProvider, shouldUseServerStt } from "./speech-stt-provider";
import { createServerSttRequestOptions } from "./speech-stt-request-options";
import { useSettings } from "./useSettings";

interface RecognitionUpdate {
  finalTranscript: string;
  interimTranscript: string;
  confidence: number;
}

type MicrophoneRecorder = Awaited<ReturnType<typeof createMicrophoneRecorder>>;

interface SttMutableState {
  transcript: Ref<string>;
  interimTranscript: Ref<string>;
  isListening: Ref<boolean>;
  confidence: Ref<number>;
  error: Ref<string | null>;
  recognition: SpeechRecognition | null;
  recorder: MicrophoneRecorder | null;
  useServerStt: boolean;
  /** Tracked mic lifecycle promise — observed so the chain is never floating. */
  micPromise: Promise<void> | null;
}

function isSpeechRecognitionEvent(event: Event): event is SpeechRecognitionEvent {
  return "resultIndex" in event && "results" in event;
}

function isSpeechRecognitionErrorEvent(event: Event): event is SpeechRecognitionErrorEvent {
  return "error" in event;
}

function processRecognitionResults(event: SpeechRecognitionEvent): RecognitionUpdate {
  let finalTranscript = "";
  let currentInterimTranscript = "";
  let currentConfidence = 0;

  for (let index = event.resultIndex; index < event.results.length; index += 1) {
    const result = event.results[index];
    const firstAlternative = result?.[0];
    if (!firstAlternative) {
      continue;
    }
    if (result.isFinal) {
      finalTranscript += firstAlternative.transcript;
      currentConfidence = Math.max(currentConfidence, firstAlternative.confidence ?? 0);
      continue;
    }
    currentInterimTranscript += firstAlternative.transcript;
  }

  return {
    finalTranscript,
    interimTranscript: currentInterimTranscript,
    confidence: currentConfidence,
  };
}

function createRecognitionInstance(
  settings?: Ref<VoiceSettings | undefined>,
): SpeechRecognition | null {
  const speechRecognitionCtor = resolveSpeechRecognitionConstructor();
  if (!speechRecognitionCtor) {
    return null;
  }

  const recognition = new speechRecognitionCtor();
  recognition.continuous = true;
  recognition.interimResults = true;
  recognition.lang = resolveSpeechLocale(settings?.value?.language);
  return recognition;
}

function toFullTranscript(transcript: string, interimTranscript: string): string {
  const combined = transcript + (interimTranscript ? ` ${interimTranscript}` : "");
  return combined.trim();
}

function bindBrowserRecognitionHandlers(state: SttMutableState): void {
  const recognition = state.recognition;
  if (!recognition) {
    return;
  }
  recognition.addEventListener("result", (event: Event) => {
    if (!isSpeechRecognitionEvent(event)) {
      return;
    }
    const update = processRecognitionResults(event);
    if (update.finalTranscript.length > 0) {
      state.transcript.value += update.finalTranscript;
    }
    state.interimTranscript.value = update.interimTranscript;
    if (update.confidence > 0) {
      state.confidence.value = update.confidence;
    }
  });
  recognition.addEventListener("error", (event: Event) => {
    if (!isSpeechRecognitionErrorEvent(event)) {
      return;
    }
    state.error.value = `${event.error}: ${event.message ?? ""}`;
  });
  recognition.addEventListener("end", () => {
    state.isListening.value = false;
  });
}

function startServerSttListening(state: SttMutableState): boolean {
  if (state.isListening.value) {
    return true;
  }
  const micPromise = createMicrophoneRecorder()
    .then(
      (created) => {
        state.recorder = created;
        created.start();
        state.isListening.value = true;
      },
      () => {
        state.error.value =
          AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[AI_CHAT_VOICE_ERROR_CODES.audioCapture];
        state.isListening.value = false;
      },
    )
    .then(
      () => undefined,
      (error: Error) => {
        state.error.value =
          error instanceof Error
            ? error.message
            : AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[AI_CHAT_VOICE_ERROR_CODES.startFailed];
      },
    );
  state.micPromise = micPromise;
  return true;
}

function startBrowserSttListening(
  state: SttMutableState,
  locale: string | undefined,
  settings?: Ref<VoiceSettings | undefined>,
): boolean {
  if (!state.recognition) {
    state.error.value =
      AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[AI_CHAT_VOICE_ERROR_CODES.unsupportedRecognition];
    return false;
  }
  if (state.isListening.value) {
    return true;
  }
  state.recognition.lang = resolveSpeechLocale(locale ?? settings?.value?.language);
  state.recognition.start();
  state.isListening.value = true;
  return true;
}

function startSttListening(
  state: SttMutableState,
  locale: string | undefined,
  settings: Ref<VoiceSettings | undefined> | undefined,
  provider: ReturnType<typeof resolveSpeechSttProvider>,
): boolean {
  state.error.value = null;
  state.transcript.value = "";
  state.interimTranscript.value = "";
  state.confidence.value = 0;
  state.useServerStt = shouldUseServerStt(provider);
  if (state.useServerStt) {
    return startServerSttListening(state);
  }
  return startBrowserSttListening(state, locale, settings);
}

function stopServerSttListening(state: SttMutableState, options: ServerSttRequestOptions): void {
  const activeRecorder = state.recorder;
  state.recorder = null;
  if (!activeRecorder) {
    state.isListening.value = false;
    return;
  }
  const micPromise = activeRecorder
    .stop()
    .then((blob) => transcribeAudioViaServer(blob, options))
    .then(
      (result) => {
        if (result.ok) {
          state.transcript.value = result.text;
          state.interimTranscript.value = "";
          state.confidence.value = 1;
        } else {
          state.error.value = result.error;
        }
      },
      () => {
        state.error.value = AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[AI_CHAT_VOICE_ERROR_CODES.network];
      },
    )
    .then(() => {
      state.isListening.value = false;
    })
    .then(
      () => undefined,
      (error: Error) => {
        state.error.value =
          error instanceof Error
            ? error.message
            : AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[AI_CHAT_VOICE_ERROR_CODES.network];
      },
    );
  state.micPromise = micPromise;
}

function stopSttListening(state: SttMutableState, options: ServerSttRequestOptions): void {
  if (state.useServerStt) {
    stopServerSttListening(state, options);
    return;
  }
  state.recognition?.stop();
  state.isListening.value = false;
}

/**
 * Speech-to-text composable.
 * Uses Whisper/server STT when automationSettings.speech.stt.provider is not browser;
 * otherwise falls back to Web Speech API.
 */
export function useSTT(settings?: Ref<VoiceSettings | undefined>) {
  const { settings: appSettings } = useSettings();
  const state: SttMutableState = {
    transcript: ref(""),
    interimTranscript: ref(""),
    isListening: ref(false),
    confidence: ref(0),
    error: ref<string | null>(null),
    recognition: null,
    recorder: null,
    useServerStt: false,
    micPromise: null,
  };

  const sttProvider = computed(() =>
    resolveSpeechSttProvider(appSettings.value?.automationSettings?.speech?.stt?.provider),
  );
  const getServerSttOptions = (): ServerSttRequestOptions =>
    createServerSttRequestOptions(appSettings);

  onMounted(() => {
    state.useServerStt = shouldUseServerStt(sttProvider.value);
    if (state.useServerStt) {
      return;
    }
    state.recognition = createRecognitionInstance(settings);
    bindBrowserRecognitionHandlers(state);
  });

  onUnmounted(() => {
    if (state.recognition) {
      state.recognition.stop();
      state.recognition = null;
    }
    state.recorder = null;
    state.isListening.value = false;
  });

  const fullTranscript = computed(() =>
    toFullTranscript(state.transcript.value, state.interimTranscript.value),
  );
  const isSupported = computed(
    () =>
      shouldUseServerStt(sttProvider.value) ||
      resolveSpeechRecognitionConstructor() !== null ||
      typeof navigator !== "undefined",
  );

  return {
    startListening: (locale?: string) =>
      startSttListening(state, locale, settings, sttProvider.value),
    stopListening: () => stopSttListening(state, getServerSttOptions()),
    transcript: readonly(state.transcript),
    interimTranscript: readonly(state.interimTranscript),
    fullTranscript,
    isListening: readonly(state.isListening),
    confidence: readonly(state.confidence),
    error: readonly(state.error),
    isSupported: readonly(isSupported),
  };
}

import {
  SCORE_PASS_THRESHOLD,
  SCORE_WARNING_THRESHOLD,
} from "@bao/shared/constants/score-thresholds";

export type ScoreLevel = "pass" | "warning" | "developing" | "unknown";

function resolveScoreLevel(score: number | undefined): ScoreLevel {
  if (!Number.isFinite(score ?? Number.NaN)) return "unknown";
  const s = score ?? 0;
  if (s >= SCORE_PASS_THRESHOLD) return "pass";
  if (s >= SCORE_WARNING_THRESHOLD) return "warning";
  return "developing";
}

const LEVEL_TEXT_MAP: Record<ScoreLevel, string> = {
  pass: "text-success",
  warning: "text-warning",
  developing: "text-error",
  unknown: "text-warning",
};

const LEVEL_BADGE_MAP: Record<ScoreLevel, string> = {
  pass: "badge-success",
  warning: "badge-warning",
  developing: "badge-error",
  unknown: "badge-warning",
};

const LEVEL_PROGRESS_MAP: Record<ScoreLevel, string> = {
  pass: "progress-success",
  warning: "progress-warning",
  developing: "progress-error",
  unknown: "progress-warning",
};

const LEVEL_BORDER_MAP: Record<ScoreLevel, string> = {
  pass: "border-success",
  warning: "border-warning",
  developing: "border-error",
  unknown: "border-warning",
};

const LEVEL_BG_MAP: Record<ScoreLevel, string> = {
  pass: "bg-success",
  warning: "bg-warning",
  developing: "bg-error",
  unknown: "bg-warning",
};

const LEVEL_ALERT_MAP: Record<ScoreLevel, string> = {
  pass: "alert-success",
  warning: "alert-warning",
  developing: "alert-error",
  unknown: "alert-warning",
};

export function useScoreColor() {
  function getScoreColorClass(score: number | undefined): string {
    return LEVEL_TEXT_MAP[resolveScoreLevel(score)];
  }

  function getScoreTextClass(score: number | undefined): string {
    return getScoreColorClass(score);
  }

  function getScoreBadgeClass(score: number | undefined): string {
    return LEVEL_BADGE_MAP[resolveScoreLevel(score)];
  }

  function getScoreProgressClass(score: number | undefined): string {
    return LEVEL_PROGRESS_MAP[resolveScoreLevel(score)];
  }

  function getScoreBorderClass(score: number | undefined): string {
    return LEVEL_BORDER_MAP[resolveScoreLevel(score)];
  }

  function getTimelineLineClass(score: number | undefined): string {
    return LEVEL_BG_MAP[resolveScoreLevel(score)];
  }

  function getAlertClass(score: number | undefined): string {
    return LEVEL_ALERT_MAP[resolveScoreLevel(score)];
  }

  return {
    getScoreColorClass,
    getScoreTextClass,
    getScoreBadgeClass,
    getScoreProgressClass,
    getScoreBorderClass,
    getTimelineLineClass,
    getAlertClass,
  };
}

import { beforeEach, describe, expect, it, vi } from "vitest";
import { effectScope } from "vue";
import { SCROLL_SPY_THRESHOLDS } from "~/constants/numeric-ui";
import { useScrollSpy } from "./useScrollSpy";

class MockIntersectionObserver implements IntersectionObserver {
  static latest: MockIntersectionObserver | null = null;

  readonly root: Element | Document | null = null;
  readonly rootMargin: string;
  readonly scrollMargin: string = "0px";
  readonly thresholds: ReadonlyArray<number>;
  readonly takeRecords = vi.fn((): IntersectionObserverEntry[] => []);
  readonly disconnect = vi.fn((): void => undefined);
  readonly observe = vi.fn((target: Element): void => {
    this.targets.add(target);
  });
  readonly unobserve = vi.fn((target: Element): void => {
    this.targets.delete(target);
  });

  private readonly callback: IntersectionObserverCallback;
  private readonly targets = new Set<Element>();

  constructor(callback: IntersectionObserverCallback, options?: IntersectionObserverInit) {
    this.callback = callback;
    this.rootMargin = options?.rootMargin ?? "0px";
    this.thresholds = Array.isArray(options?.threshold)
      ? options.threshold
      : [typeof options?.threshold === "number" ? options.threshold : 0];
    MockIntersectionObserver.latest = this;
  }

  trigger(entries: readonly IntersectionObserverEntry[]): void {
    this.callback.call(undefined, [...entries], this);
  }
}

const createEntry = (target: Element, intersectionRatio: number): IntersectionObserverEntry => ({
  time: Date.now(),
  target,
  rootBounds: null,
  boundingClientRect: target.getBoundingClientRect(),
  intersectionRect: target.getBoundingClientRect(),
  isIntersecting: true,
  intersectionRatio,
});

const hasDomEnvironment = (): boolean =>
  typeof window !== "undefined" && typeof document !== "undefined";

beforeEach(() => {
  MockIntersectionObserver.latest = null;
  vi.restoreAllMocks();
  Object.defineProperty(globalThis, "IntersectionObserver", {
    configurable: true,
    writable: true,
    value: MockIntersectionObserver,
  });
});

function createScopedScrollSpy() {
  const scope = effectScope();
  const scrollSpy = scope.run(() => useScrollSpy());
  if (!scrollSpy) {
    throw new Error("Scroll spy did not initialize");
  }
  return { scope, scrollSpy };
}

function assertSyncsFromHash(): void {
  expect(hasDomEnvironment(), "happy-dom must provide document/window for scroll spy").toBe(true);

  const { scope, scrollSpy } = createScopedScrollSpy();
  const replaceStateSpy = vi.spyOn(window.history, "replaceState");

  const section = document.createElement("section");
  section.id = "overview";
  const scrollIntoViewMock = vi.fn();
  const focusMock = vi.fn();
  section.scrollIntoView = scrollIntoViewMock;
  section.focus = focusMock;

  scrollSpy.setSectionRef("overview", section);
  const restored = scrollSpy.syncFromHash("#overview");

  expect(restored).toBe(true);
  expect(scrollSpy.activeSectionId.value).toBe("overview");
  expect(scrollIntoViewMock).toHaveBeenCalledWith({ behavior: "auto", block: "start" });
  expect(focusMock).not.toHaveBeenCalled();
  expect(replaceStateSpy).not.toHaveBeenCalled();

  scope.stop();
}

function assertUpdatesActiveSectionFromObserver(): void {
  expect(hasDomEnvironment(), "happy-dom must provide document/window for scroll spy").toBe(true);

  const { scope, scrollSpy } = createScopedScrollSpy();
  const replaceStateSpy = vi.spyOn(window.history, "replaceState");

  const sectionOne = document.createElement("section");
  sectionOne.id = "one";
  const sectionTwo = document.createElement("section");
  sectionTwo.id = "two";
  scrollSpy.setSectionRef("one", sectionOne);
  scrollSpy.setSectionRef("two", sectionTwo);

  scrollSpy.startObserver();
  const observer = MockIntersectionObserver.latest;
  if (!observer) {
    throw new Error("Observer was not created");
  }

  observer.trigger([
    createEntry(sectionOne, SCROLL_SPY_THRESHOLDS[1]),
    createEntry(sectionTwo, SCROLL_SPY_THRESHOLDS[3]),
  ]);

  expect(scrollSpy.activeSectionId.value).toBe("two");
  expect(replaceStateSpy).toHaveBeenCalledWith({}, "", "#two");

  scope.stop();
}

function assertDoesNotDuplicateHashUpdates(): void {
  expect(hasDomEnvironment(), "happy-dom must provide document/window for scroll spy").toBe(true);

  const { scope, scrollSpy } = createScopedScrollSpy();
  const replaceStateSpy = vi.spyOn(window.history, "replaceState");

  const section = document.createElement("section");
  section.id = "same";
  section.scrollIntoView = vi.fn();
  section.focus = vi.fn();
  scrollSpy.setSectionRef("same", section);

  scrollSpy.scrollToSection("same", { smooth: false, focus: false, updateHash: true });
  scrollSpy.scrollToSection("same", { smooth: false, focus: false, updateHash: true });

  expect(replaceStateSpy).toHaveBeenCalledTimes(1);

  scope.stop();
}

describe("useScrollSpy", () => {
  it("syncs from hash and scrolls to registered section", assertSyncsFromHash);
  it(
    "updates active section from intersection observer events",
    assertUpdatesActiveSectionFromObserver,
  );
  it(
    "does not duplicate hash updates when the active section is unchanged",
    assertDoesNotDuplicateHashUpdates,
  );
});

import { escapeRegExp } from "@bao/shared/utils/string";
import { getCurrentScope, onScopeDispose, readonly, ref } from "vue";
import { SCROLL_SPY_THRESHOLDS } from "~/constants/numeric-ui";

type ScrollSpyOptions = {
  rootMargin?: string;
  threshold?: number[];
  hashPrefix?: string;
};

const DEFAULT_HASH_PREFIX = "#";
const DEFAULT_ROOT_MARGIN = "-20% 0px -60% 0px";
const DEFAULT_THRESHOLD = [...SCROLL_SPY_THRESHOLDS];
const MANUAL_SCROLL_LOCK_MS = 250;
const normalizeHashValue = (value: string, hashPrefix: string): string =>
  value.replace(new RegExp(`^${escapeRegExp(hashPrefix)}`, "u"), "").trim();

type ObserverHolder = {
  value: IntersectionObserver | null;
};

interface ScrollSpyState {
  activeSectionId: ReturnType<typeof ref<string>>;
  sectionNodes: Map<string, HTMLElement>;
  observer: ObserverHolder;
  hashPrefix: string;
  lastManualScrollAt: number;
}

function createScrollSpyState(options: ScrollSpyOptions): ScrollSpyState {
  return {
    activeSectionId: ref(""),
    sectionNodes: new Map<string, HTMLElement>(),
    observer: { value: null },
    hashPrefix: options.hashPrefix ?? DEFAULT_HASH_PREFIX,
    lastManualScrollAt: 0,
  };
}

function resolveFallbackSectionId(state: ScrollSpyState): string | null {
  const firstSection = state.sectionNodes.values().next().value;
  return firstSection?.id || null;
}

function updateActiveSection(state: ScrollSpyState, sectionId: string, updateHash: boolean): void {
  if (sectionId.length === 0 || state.activeSectionId.value === sectionId) {
    return;
  }

  state.activeSectionId.value = sectionId;
  if (!updateHash || typeof window === "undefined") {
    return;
  }

  const nextHash = `${state.hashPrefix}${sectionId}`;
  if (window.location.hash !== nextHash) {
    window.history.replaceState({}, "", nextHash);
  }
}

function shouldIgnoreObserverTick(state: ScrollSpyState): boolean {
  if (typeof window === "undefined") {
    return false;
  }
  return Date.now() - state.lastManualScrollAt < MANUAL_SCROLL_LOCK_MS;
}

function pickEntryId(
  state: ScrollSpyState,
  entries: readonly IntersectionObserverEntry[],
): string | null {
  const nextEntry = entries
    .filter((entry) => entry.isIntersecting)
    .sort((a, b) => {
      const ratioCompare = b.intersectionRatio - a.intersectionRatio;
      if (ratioCompare !== 0) {
        return ratioCompare;
      }
      return a.boundingClientRect.top - b.boundingClientRect.top;
    })[0];

  return nextEntry?.target.id || resolveFallbackSectionId(state);
}

function createObserverCallback(state: ScrollSpyState): IntersectionObserverCallback {
  return (entries) => {
    if (shouldIgnoreObserverTick(state)) {
      return;
    }

    const nextId = pickEntryId(state, entries);
    if (nextId) {
      updateActiveSection(state, nextId, true);
    }
  };
}

function refreshObserver(state: ScrollSpyState): void {
  const activeObserver = state.observer.value;
  if (!activeObserver) {
    return;
  }

  activeObserver.disconnect();
  for (const section of state.sectionNodes.values()) {
    activeObserver.observe(section);
  }
}

function startObserver(state: ScrollSpyState, options: ScrollSpyOptions): void {
  if (typeof window === "undefined" || typeof IntersectionObserver === "undefined") {
    return;
  }

  if (!state.observer.value) {
    state.observer.value = new IntersectionObserver(createObserverCallback(state), {
      root: null,
      threshold: options.threshold ?? DEFAULT_THRESHOLD,
      rootMargin: options.rootMargin ?? DEFAULT_ROOT_MARGIN,
    });
  }

  refreshObserver(state);
}

function stopObserver(state: ScrollSpyState): void {
  state.observer.value?.disconnect();
  state.observer.value = null;
}

function setSectionRef(state: ScrollSpyState, sectionId: string, element: Element | null): void {
  const previous = state.sectionNodes.get(sectionId);
  if (previous && state.observer.value) {
    state.observer.value.unobserve(previous);
  }

  if (!element) {
    state.sectionNodes.delete(sectionId);
    if (state.activeSectionId.value === sectionId) {
      state.activeSectionId.value = resolveFallbackSectionId(state) ?? "";
    }
    return;
  }

  if (element instanceof HTMLElement) {
    state.sectionNodes.set(sectionId, element);
    state.observer.value?.observe(element);
  }
}

function scrollToSection(
  state: ScrollSpyState,
  sectionId: string,
  optionsValue: {
    smooth?: boolean;
    focus?: boolean;
    updateHash?: boolean;
  } = {},
): void {
  const section = state.sectionNodes.get(sectionId);
  if (!section) {
    return;
  }

  const smooth = optionsValue.smooth ?? true;
  const focus = optionsValue.focus ?? true;
  const updateHash = optionsValue.updateHash ?? true;

  state.lastManualScrollAt = Date.now();
  updateActiveSection(state, sectionId, updateHash);
  section.scrollIntoView({
    behavior: smooth ? "smooth" : "auto",
    block: "start",
  });
  if (focus) {
    section.focus({ preventScroll: true });
  }
}

function syncFromHash(state: ScrollSpyState, hashValue: string): boolean {
  const normalizedHash = normalizeHashValue(hashValue, state.hashPrefix);
  if (!(normalizedHash && state.sectionNodes.has(normalizedHash))) {
    return false;
  }

  scrollToSection(state, normalizedHash, {
    smooth: false,
    focus: false,
    updateHash: false,
  });
  return true;
}

/**
 * Generic section-based scroll spy composable with deterministic active-id updates.
 */
export function useScrollSpy(options: ScrollSpyOptions = {}) {
  const state = createScrollSpyState(options);
  const stop = (): void => stopObserver(state);
  if (getCurrentScope()) {
    onScopeDispose(stop);
  }

  return {
    activeSectionId: readonly(state.activeSectionId),
    setSectionRef: (sectionId: string, element: Element | null) =>
      setSectionRef(state, sectionId, element),
    scrollToSection: (
      sectionId: string,
      optionsValue: {
        smooth?: boolean;
        focus?: boolean;
        updateHash?: boolean;
      } = {},
    ) => scrollToSection(state, sectionId, optionsValue),
    syncFromHash: (hashValue: string) => syncFromHash(state, hashValue),
    startObserver: () => startObserver(state, options),
    refreshObserver: () => refreshObserver(state),
    stopObserver: stop,
  };
}

