import { resolveSpeechSttProvider, shouldUseServerStt } from "./speech-stt-provider";
import { createServerSttRequestOptions } from "./speech-stt-request-options";
import { resolveSpeechTtsProvider, shouldUseLocalKokoroTts } from "./speech-tts-provider";
import { useSettings } from "./useSettings";

type RecognitionErrorName = keyof typeof AI_CHAT_VOICE_RECOGNITION_ERROR_CODE_MAP;
type SynthesisErrorName = keyof typeof AI_CHAT_VOICE_SYNTHESIS_ERROR_CODE_MAP;

interface SpeechState {
  isListening: Ref<boolean>;
  isSpeaking: Ref<boolean>;
  transcript: Ref<string>;
  interimTranscript: Ref<string>;
  error: Ref<AIChatVoiceErrorCode | null>;
  voices: Ref<SpeechSynthesisVoice[]>;
  recognition: Ref<SpeechRecognition | null>;
  synthesis: Ref<SpeechSynthesis | null>;
}

interface SpeakOptions {
  rate?: number;
  pitch?: number;
  volume?: number;
  voice?: SpeechSynthesisVoice;
  lang?: string;
}

/**
 * Checks whether a raw recognition error name is mapped to a canonical code.
 *
 * @param value Raw browser recognition error.
 * @returns True when the error name is known.
 */
function isRecognitionErrorName(value: string): value is RecognitionErrorName {
  return Object.hasOwn(AI_CHAT_VOICE_RECOGNITION_ERROR_CODE_MAP, value);
}

/**
 * Checks whether a raw synthesis error name is mapped to a canonical code.
 *
 * @param value Raw browser synthesis error.
 * @returns True when the error name is known.
 */
function isSynthesisErrorName(value: string): value is SynthesisErrorName {
  return Object.hasOwn(AI_CHAT_VOICE_SYNTHESIS_ERROR_CODE_MAP, value);
}

/**
 * Resolves a browser recognition error into canonical UI-facing code.
 *
 * @param value Raw browser recognition error.
 * @returns Canonical voice error code.
 */
function resolveRecognitionErrorCode(value: string): AIChatVoiceErrorCode {
  if (isRecognitionErrorName(value)) {
    return AI_CHAT_VOICE_RECOGNITION_ERROR_CODE_MAP[value];
  }
  return AI_CHAT_VOICE_ERROR_CODES.unknown;
}

/**
 * Resolves a browser synthesis error into canonical UI-facing code.
 *
 * @param value Raw browser synthesis error.
 * @returns Canonical voice error code.
 */
function resolveSynthesisErrorCode(value: string): AIChatVoiceErrorCode {
  if (isSynthesisErrorName(value)) {
    return AI_CHAT_VOICE_SYNTHESIS_ERROR_CODE_MAP[value];
  }
  return AI_CHAT_VOICE_ERROR_CODES.unknown;
}

const createSpeechState = (): SpeechState => ({
  isListening: ref(false),
  isSpeaking: ref(false),
  transcript: ref(""),
  interimTranscript: ref(""),
  error: ref<AIChatVoiceErrorCode | null>(null),
  voices: ref<SpeechSynthesisVoice[]>([]),
  recognition: ref<SpeechRecognition | null>(null),
  synthesis: ref<SpeechSynthesis | null>(null),
});

const resolveSynthesis = (state: SpeechState): SpeechSynthesis | null => {
  const resolved = state.synthesis.value ?? resolveSpeechSynthesis();
  if (resolved) {
    state.synthesis.value = resolved;
  }
  return resolved;
};

const createLoadVoicesAction = (state: SpeechState) => (): SpeechSynthesisVoice[] => {
  const synthesis = resolveSynthesis(state);
  if (!synthesis) {
    state.voices.value = [];
    return [];
  }

  const availableVoices = synthesis.getVoices();
  state.voices.value = availableVoices;
  return availableVoices;
};

const createRecognitionResultHandler =
  (state: SpeechState) =>
  (event: SpeechRecognitionEvent): void => {
    let finalTranscript = "";
    let currentInterimTranscript = "";
    for (let index = event.resultIndex; index < event.results.length; index += 1) {
      const result = event.results[index];
      const firstAlternative = result?.[0];
      if (!firstAlternative) {
        continue;
      }
      if (result.isFinal) {
        finalTranscript += firstAlternative.transcript;
      } else {
        currentInterimTranscript += firstAlternative.transcript;
      }
    }

    if (finalTranscript.length > 0) {
      state.transcript.value += finalTranscript;
    }
    state.interimTranscript.value = currentInterimTranscript;
  };

const setupSpeechApis = (state: SpeechState, loadVoices: () => SpeechSynthesisVoice[]) => {
  onMounted(() => {
    state.synthesis.value = resolveSpeechSynthesis();
    if (state.synthesis.value) {
      state.synthesis.value.onvoiceschanged = () => {
        loadVoices();
      };
      loadVoices();
    }

    const speechRecognitionCtor = resolveSpeechRecognitionConstructor();
    if (!speechRecognitionCtor) {
      return;
    }

    const recognition = new speechRecognitionCtor();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = resolveSpeechLocale();
    recognition.onresult = createRecognitionResultHandler(state);
    recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
      state.error.value = resolveRecognitionErrorCode(event.error);
    };
    recognition.onend = () => {
      state.isListening.value = false;
    };
    state.recognition.value = recognition;
  });
};

const createSpeakAction =
  (
    state: SpeechState,
    getTtsProvider: () => ReturnType<typeof resolveSpeechTtsProvider>,
    getTtsVoice: () => string,
  ) =>
  (text: string, options?: SpeakOptions): void => {
    const trimmed = text.trim();
    if (trimmed.length === 0) {
      return;
    }

    // Local Kokoro (on-device neural) — fail-closed path, not browser speechSynthesis.
    if (shouldUseLocalKokoroTts(getTtsProvider())) {
      state.isSpeaking.value = true;
      state.error.value = null;
      settle(
        synthesizeSpeechViaServer({
          text: trimmed,
          voice: getTtsVoice() || undefined,
        }).then(async (result) => {
          if (!result.ok) {
            state.error.value = AI_CHAT_VOICE_ERROR_CODES.startFailed;
            state.isSpeaking.value = false;
            return;
          }
          await playBase64Audio(result.audioBase64, result.mimeType);
          state.isSpeaking.value = false;
        }),
      ).then(
        (settled) => {
          if (settled.status === "rejected") {
            state.error.value = AI_CHAT_VOICE_ERROR_CODES.startFailed;
            state.isSpeaking.value = false;
          }
        },
        () => undefined,
      );
      return;
    }

    const synthesis = resolveSynthesis(state);
    if (!synthesis) {
      state.error.value = AI_CHAT_VOICE_ERROR_CODES.unsupportedSynthesis;
      return;
    }

    synthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(trimmed);
    utterance.rate = options?.rate ?? 1;
    utterance.pitch = options?.pitch ?? 1;
    utterance.volume = options?.volume ?? 1;
    utterance.lang = resolveSpeechLocale(options?.lang);
    if (options?.voice) {
      utterance.voice = options.voice;
    }

    utterance.onstart = () => {
      state.isSpeaking.value = true;
      state.error.value = null;
    };
    utterance.onend = () => {
      state.isSpeaking.value = false;
    };
    utterance.onerror = (event: SpeechSynthesisErrorEvent) => {
      state.error.value = resolveSynthesisErrorCode(event.error);
      state.isSpeaking.value = false;
    };
    synthesis.speak(utterance);
  };

const createStopSpeakingAction = (state: SpeechState) => (): void => {
  const synthesis = resolveSynthesis(state);
  if (synthesis) {
    synthesis.cancel();
  }
  state.isSpeaking.value = false;
};

const createSpeechSupportState = (
  state: SpeechState,
  getSttProvider: () => ReturnType<typeof resolveSpeechSttProvider>,
  getTtsProvider: () => ReturnType<typeof resolveSpeechTtsProvider>,
) => {
  const fullTranscript = computed(() => {
    const interim = state.interimTranscript.value;
    const combinedTranscript = state.transcript.value + (interim ? ` ${interim}` : "");
    return combinedTranscript.trim();
  });
  const supportsRecognition = computed(
    () => shouldUseServerStt(getSttProvider()) || resolveSpeechRecognitionConstructor() !== null,
  );
  const supportsSynthesis = computed(
    () =>
      shouldUseLocalKokoroTts(getTtsProvider()) ||
      (state.synthesis.value ?? resolveSpeechSynthesis()) !== null,
  );
  const isSupported = computed(() => supportsRecognition.value || supportsSynthesis.value);
  return {
    fullTranscript,
    supportsRecognition,
    supportsSynthesis,
    isSupported,
  };
};

/**
 * Web Speech API composable for local TTS and STT (no external services).
 * Uses browser-native SpeechSynthesis and SpeechRecognition.
 */
export function useSpeech() {
  const { settings: appSettings } = useSettings();
  const getSttProvider = () =>
    resolveSpeechSttProvider(appSettings.value?.automationSettings?.speech?.stt?.provider);
  const getTtsProvider = () =>
    resolveSpeechTtsProvider(appSettings.value?.automationSettings?.speech?.tts?.provider);
  const getTtsVoice = () =>
    appSettings.value?.automationSettings?.speech?.tts?.voice?.trim() || "af_heart";
  const getServerSttOptions = (): ServerSttRequestOptions =>
    createServerSttRequestOptions(appSettings);
  const state = createSpeechState();
  const loadVoices = createLoadVoicesAction(state);
  setupSpeechApis(state, loadVoices);

  const speechSupport = createSpeechSupportState(state, getSttProvider, getTtsProvider);
  const listeningActions = createStartListeningAction(state, getSttProvider, getServerSttOptions);
  const actions = {
    speak: createSpeakAction(state, getTtsProvider, getTtsVoice),
    stopSpeaking: createStopSpeakingAction(state),
    startListening: listeningActions.startListening,
    stopListening: listeningActions.stopListening,
    loadVoices,
  };

  return {
    isListening: readonly(state.isListening),
    isSpeaking: readonly(state.isSpeaking),
    transcript: readonly(state.transcript),
    interimTranscript: readonly(state.interimTranscript),
    error: readonly(state.error),
    voices: readonly(state.voices),
    ...speechSupport,
    ...actions,
  };
}

import {
  ON_DEVICE_TTS_PROVIDER_OPTIONS,
  SPEECH_PROVIDER_OPTIONS,
} from "@bao/shared/constants/settings";
import { DEFAULT_AUTOMATION_SETTINGS } from "@bao/shared/types/settings-defaults";
import type { ComputedRef, Ref } from "vue";
import { computed, reactive, ref, watch } from "vue";
import { settlePromise } from "./async-flow";
import {
  buildNextSpeechConfigFromProfile,
  createDefaultSpeechModelProfileState,
  isSpeechModelProfileDirty,
  mapPersistedSpeechToProfileState,
  resolveDefaultSpeechModel,
  resolveProviderModels,
  type SpeechModelProfileState,
} from "./speech-model-profile-state";
import { useSettings } from "./useSettings";

/**
 * Result envelope for saving speech model profile preferences.
 */
export type SpeechModelProfileSaveResult =
  | { readonly ok: true; readonly saved: boolean }
  | { readonly ok: false; readonly saved: false; readonly error: Error };

/**
 * Options for speech model profile state management.
 */
export interface UseSpeechModelProfilesOptions {
  readonly locale: Ref<string>;
}

interface SaveSpeechConfigActionOptions {
  settings: ReturnType<typeof useSettings>["settings"];
  updateSettings: ReturnType<typeof useSettings>["updateSettings"];
  isSpeechConfigDirty: ComputedRef<boolean>;
  speechConfigSaving: Ref<boolean>;
  speechConfig: SpeechModelProfileState;
  locale: Ref<string>;
}

const createSpeechConfigState = (): SpeechModelProfileState =>
  reactive<SpeechModelProfileState>(createDefaultSpeechModelProfileState());

const createPersistedSpeechConfig = (
  settings: ReturnType<typeof useSettings>["settings"],
): ComputedRef<SpeechModelProfileState> =>
  computed<SpeechModelProfileState>(() => {
    const persistedSpeech =
      settings.value?.automationSettings?.speech ?? DEFAULT_AUTOMATION_SETTINGS.speech;
    return mapPersistedSpeechToProfileState(persistedSpeech);
  });

const createSpeechConfigDirtyState = (
  speechConfig: SpeechModelProfileState,
  persistedSpeechConfig: ComputedRef<SpeechModelProfileState>,
): ComputedRef<boolean> =>
  computed(() => isSpeechModelProfileDirty(speechConfig, persistedSpeechConfig.value));

const syncSpeechConfigFromSettings = (
  settings: ReturnType<typeof useSettings>["settings"],
  speechConfig: SpeechModelProfileState,
) => {
  watch(
    settings,
    (currentSettings) => {
      const persistedSpeech =
        currentSettings?.automationSettings?.speech ?? DEFAULT_AUTOMATION_SETTINGS.speech;
      const mapped = mapPersistedSpeechToProfileState(persistedSpeech);
      speechConfig.sttProvider = mapped.sttProvider;
      speechConfig.sttModel = mapped.sttModel;
      speechConfig.sttEndpoint = mapped.sttEndpoint;
      speechConfig.ttsProvider = mapped.ttsProvider;
      speechConfig.ttsModel = mapped.ttsModel;
      speechConfig.ttsEndpoint = mapped.ttsEndpoint;
    },
    { immediate: true },
  );
};

const registerSttProviderWatcher = (speechConfig: SpeechModelProfileState) => {
  watch(
    () => speechConfig.sttProvider,
    (provider) => {
      const optionsForProvider = resolveProviderModels("stt", provider);
      if (optionsForProvider.includes(speechConfig.sttModel)) {
        return;
      }
      speechConfig.sttModel = resolveDefaultSpeechModel("stt", provider);
    },
  );
};

const registerTtsProviderWatcher = (speechConfig: SpeechModelProfileState) => {
  watch(
    () => speechConfig.ttsProvider,
    (provider) => {
      const optionsForProvider = resolveProviderModels("tts", provider);
      if (optionsForProvider.includes(speechConfig.ttsModel)) {
        return;
      }
      speechConfig.ttsModel = resolveDefaultSpeechModel("tts", provider);
    },
  );
};

const buildNextSpeechConfig = (
  settings: ReturnType<typeof useSettings>["settings"],
  speechConfig: SpeechModelProfileState,
  locale: string,
) => {
  const existingAutomationSettings =
    settings.value?.automationSettings ?? DEFAULT_AUTOMATION_SETTINGS;
  return buildNextSpeechConfigFromProfile(existingAutomationSettings.speech, speechConfig, locale);
};

const createEnsureSpeechConfigLoadedAction =
  (
    settings: ReturnType<typeof useSettings>["settings"],
    fetchSettings: ReturnType<typeof useSettings>["fetchSettings"],
  ) =>
  async (): Promise<void> => {
    if (settings.value) {
      return;
    }
    await fetchSettings();
  };

const createSaveSpeechConfigAction =
  (options: SaveSpeechConfigActionOptions) =>
  async (fallbackMessage: string): Promise<SpeechModelProfileSaveResult> => {
    if (!options.isSpeechConfigDirty.value || options.speechConfigSaving.value) {
      return { ok: true, saved: false };
    }

    const nextSpeechConfig = buildNextSpeechConfig(
      options.settings,
      options.speechConfig,
      options.locale.value,
    );
    options.speechConfigSaving.value = true;
    const saveSpeechResult = await settlePromise(
      options.updateSettings({
        automationSettings: {
          speech: nextSpeechConfig,
        },
      }),
      fallbackMessage,
    );
    options.speechConfigSaving.value = false;

    if (!saveSpeechResult.ok) {
      return {
        ok: false,
        saved: false,
        error: saveSpeechResult.error,
      };
    }
    return {
      ok: true,
      saved: true,
    };
  };

/**
 * Provides a single source of truth for persisted speech provider/model profile state.
 *
 * @param options Locale ref used as fallback speech locale when persisting settings.
 * @returns Reactive speech config, model options, dirty/saving flags, and save/load actions.
 */
export function useSpeechModelProfiles(options: UseSpeechModelProfilesOptions) {
  const { settings, fetchSettings, updateSettings } = useSettings();
  const speechConfigSaving = ref(false);
  const speechConfig = createSpeechConfigState();
  const sttModelOptions = computed(() => resolveProviderModels("stt", speechConfig.sttProvider));
  const ttsModelOptions = computed(() => resolveProviderModels("tts", speechConfig.ttsProvider));
  const persistedSpeechConfig = createPersistedSpeechConfig(settings);
  const isSpeechConfigDirty = createSpeechConfigDirtyState(speechConfig, persistedSpeechConfig);

  syncSpeechConfigFromSettings(settings, speechConfig);
  registerSttProviderWatcher(speechConfig);
  registerTtsProviderWatcher(speechConfig);

  return {
    speechProviderOptions: SPEECH_PROVIDER_OPTIONS,
    /** Cloud TTS ignored — UI only offers browser + local Kokoro. */
    ttsProviderOptions: ON_DEVICE_TTS_PROVIDER_OPTIONS,
    speechConfig,
    sttModelOptions,
    ttsModelOptions,
    speechConfigSaving,
    isSpeechConfigDirty,
    ensureSpeechConfigLoaded: createEnsureSpeechConfigLoadedAction(settings, fetchSettings),
    saveSpeechConfig: createSaveSpeechConfigAction({
      settings,
      updateSettings,
      isSpeechConfigDirty,
      speechConfigSaving,
      speechConfig,
      locale: options.locale,
    }),
  };
}

import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { CareerProgress, DashboardStats, WeeklyActivity } from "@bao/shared/types/search";
import { asNumber, asString, isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import { withLoadingState } from "./async-flow";

type StatisticsState = {
  readonly dashboard: ReturnType<typeof useState<DashboardStats | null>>;
  readonly weekly: ReturnType<typeof useState<WeeklyActivity | null>>;
  readonly career: ReturnType<typeof useState<CareerProgress | null>>;
  readonly loading: ReturnType<typeof useState<boolean>>;
};

type DashboardSections = {
  readonly profile: Record<string, unknown>;
  readonly jobs: Record<string, unknown>;
  readonly resumes: Record<string, unknown>;
  readonly coverLetters: Record<string, unknown>;
  readonly portfolio: Record<string, unknown>;
  readonly interviews: Record<string, unknown>;
  readonly skills: Record<string, unknown>;
  readonly ai: Record<string, unknown>;
  readonly gamification: Record<string, unknown>;
  readonly automation: Record<string, unknown>;
};

const asRecordOrNull = (value: unknown): Record<string, unknown> | null =>
  isRecord(value) ? value : null;

const resolveDashboardSections = (value: Record<string, unknown>): DashboardSections | null => {
  const profile = asRecordOrNull(value.profile);
  const jobs = asRecordOrNull(value.jobs);
  const resumes = asRecordOrNull(value.resumes);
  const coverLetters = asRecordOrNull(value.coverLetters);
  const portfolio = asRecordOrNull(value.portfolio);
  const interviews = asRecordOrNull(value.interviews);
  const skills = asRecordOrNull(value.skills);
  const ai = asRecordOrNull(value.ai);
  const gamification = asRecordOrNull(value.gamification);
  const automation = asRecordOrNull(value.automation);

  if (
    !(
      profile &&
      jobs &&
      resumes &&
      coverLetters &&
      portfolio &&
      interviews &&
      skills &&
      ai &&
      gamification &&
      automation
    )
  ) {
    return null;
  }

  return {
    profile,
    jobs,
    resumes,
    coverLetters,
    portfolio,
    interviews,
    skills,
    ai,
    gamification,
    automation,
  };
};

const toRecentAutomationRun = (
  value: unknown,
): DashboardStats["automation"]["recentRuns"][number] | null => {
  if (!isRecord(value)) {
    return null;
  }

  const id = asString(value.id);
  const type = asString(value.type);
  const status = asString(value.status);
  const createdAt = asString(value.createdAt);
  if (!(id && type && status && createdAt)) {
    return null;
  }

  return { id, type, status, createdAt };
};

const toRecentAutomationRuns = (value: unknown): DashboardStats["automation"]["recentRuns"] => {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((entry) => toRecentAutomationRun(entry))
    .filter((entry): entry is DashboardStats["automation"]["recentRuns"][number] => entry !== null);
};

const toProfileStats = (value: DashboardSections["profile"]): DashboardStats["profile"] => ({
  completeness: asNumber(value.completeness) ?? 0,
});

const toJobStats = (value: DashboardSections["jobs"]): DashboardStats["jobs"] => ({
  saved: asNumber(value.saved) ?? 0,
  applied: asNumber(value.applied) ?? 0,
  interviewing: asNumber(value.interviewing) ?? 0,
  offered: asNumber(value.offered) ?? 0,
});

const toResumeStats = (value: DashboardSections["resumes"]): DashboardStats["resumes"] => ({
  count: asNumber(value.count) ?? 0,
  lastUpdated: asString(value.lastUpdated) ?? null,
});

const toCoverLetterStats = (
  value: DashboardSections["coverLetters"],
): DashboardStats["coverLetters"] => ({
  count: asNumber(value.count) ?? 0,
});

const toPortfolioStats = (value: DashboardSections["portfolio"]): DashboardStats["portfolio"] => ({
  projectCount: asNumber(value.projectCount) ?? 0,
});

const toInterviewStats = (
  value: DashboardSections["interviews"],
): DashboardStats["interviews"] => ({
  totalSessions: asNumber(value.totalSessions) ?? 0,
  averageScore: asNumber(value.averageScore) ?? null,
});

const toSkillStats = (value: DashboardSections["skills"]): DashboardStats["skills"] => ({
  mappedCount: asNumber(value.mappedCount) ?? 0,
});

const toAiStats = (value: DashboardSections["ai"]): DashboardStats["ai"] => ({
  chatMessages: asNumber(value.chatMessages) ?? 0,
  chatSessions: asNumber(value.chatSessions) ?? 0,
});

const toGamificationStats = (
  value: DashboardSections["gamification"],
): DashboardStats["gamification"] => ({
  level: asNumber(value.level) ?? 1,
  xp: asNumber(value.xp) ?? 0,
  achievements: asNumber(value.achievements) ?? 0,
  streak: asNumber(value.streak) ?? 0,
});

const toAutomationStats = (
  value: DashboardSections["automation"],
): DashboardStats["automation"] => ({
  totalRuns: asNumber(value.totalRuns) ?? 0,
  successfulRuns: asNumber(value.successfulRuns) ?? 0,
  successRate: asNumber(value.successRate) ?? 0,
  todayRuns: asNumber(value.todayRuns) ?? 0,
  recentRuns: toRecentAutomationRuns(value.recentRuns),
});

const toDashboardStats = (value: unknown): DashboardStats | null => {
  if (!isRecord(value)) {
    return null;
  }

  const sections = resolveDashboardSections(value);
  if (!sections) {
    return null;
  }

  return {
    profile: toProfileStats(sections.profile),
    jobs: toJobStats(sections.jobs),
    resumes: toResumeStats(sections.resumes),
    coverLetters: toCoverLetterStats(sections.coverLetters),
    portfolio: toPortfolioStats(sections.portfolio),
    interviews: toInterviewStats(sections.interviews),
    skills: toSkillStats(sections.skills),
    ai: toAiStats(sections.ai),
    gamification: toGamificationStats(sections.gamification),
    automation: toAutomationStats(sections.automation),
  };
};

const toWeeklyActivity = (value: unknown): WeeklyActivity | null => {
  if (!(isRecord(value) && Array.isArray(value.days))) {
    return null;
  }

  return {
    days: value.days
      .map((entry) => {
        if (!isRecord(entry)) {
          return null;
        }
        const date = asString(entry.date);
        if (!date) {
          return null;
        }
        return {
          date,
          actions: asNumber(entry.actions) ?? 0,
          xpEarned: asNumber(entry.xpEarned) ?? 0,
        };
      })
      .filter((entry): entry is WeeklyActivity["days"][number] => entry !== null),
    topCategory: asString(value.topCategory) ?? "unknown",
    totalXP: asNumber(value.totalXP) ?? 0,
  };
};

const toCareerProgress = (value: unknown): CareerProgress | null => {
  if (!isRecord(value)) {
    return null;
  }

  return {
    skillCoverage: asNumber(value.skillCoverage) ?? 0,
    applicationSuccessRate: asNumber(value.applicationSuccessRate) ?? 0,
    interviewTrend: Array.isArray(value.interviewTrend)
      ? value.interviewTrend.filter((entry): entry is number => typeof entry === "number")
      : [],
  };
};

const readApiData = async (
  request: Promise<unknown>,
  fallbackMessage: string,
): Promise<unknown> => {
  const response = await request;
  if (!(isRecord(response) && "data" in response)) {
    throw new Error(fallbackMessage);
  }
  if ("error" in response && response.error) {
    throw new Error(fallbackMessage);
  }
  return response.data;
};

function createStatisticsState(): StatisticsState {
  return {
    dashboard: useState<DashboardStats | null>(STATE_KEYS.STATS_DASHBOARD, () => null),
    weekly: useState<WeeklyActivity | null>(STATE_KEYS.STATS_WEEKLY, () => null),
    career: useState<CareerProgress | null>(STATE_KEYS.STATS_CAREER, () => null),
    loading: useState(STATE_KEYS.STATS_LOADING, () => false),
  };
}

function createStatisticsActions(
  api: ReturnType<typeof useApi>,
  t: ReturnType<typeof useI18n>["t"],
  state: StatisticsState,
) {
  const fetchDashboard = async () =>
    withLoadingState(state.loading, async () => {
      const data = await readApiData(
        api.stats.dashboard.get(),
        t("apiErrors.statistics.fetchDashboardFailed"),
      );
      state.dashboard.value = toDashboardStats(data);
    });

  const fetchWeekly = async () =>
    withLoadingState(state.loading, async () => {
      const data = await readApiData(
        api.stats.weekly.get(),
        t("apiErrors.statistics.fetchWeeklyFailed"),
      );
      state.weekly.value = toWeeklyActivity(data);
    });

  const fetchCareerProgress = async () =>
    withLoadingState(state.loading, async () => {
      const data = await readApiData(
        api.stats.career.get(),
        t("apiErrors.statistics.fetchCareerFailed"),
      );
      state.career.value = toCareerProgress(data);
    });

  const refreshAll = async () => {
    await Promise.all([fetchDashboard(), fetchWeekly(), fetchCareerProgress()]);
  };

  return {
    fetchDashboard,
    fetchWeekly,
    fetchCareerProgress,
    refreshAll,
  };
}

function createStatisticsAccessors(dashboard: StatisticsState["dashboard"]) {
  const profileCompleteness = computed(() => dashboard.value?.profile?.completeness ?? 0);
  const totalJobsSaved = computed(() => dashboard.value?.jobs?.saved ?? 0);
  const totalApplications = computed(() => {
    const jobs = dashboard.value?.jobs;
    if (!jobs) {
      return 0;
    }
    return (jobs.applied ?? 0) + (jobs.interviewing ?? 0) + (jobs.offered ?? 0);
  });
  const currentLevel = computed(() => dashboard.value?.gamification?.level ?? 1);
  const currentXP = computed(() => dashboard.value?.gamification?.xp ?? 0);
  const currentStreak = computed(() => dashboard.value?.gamification?.streak ?? 0);
  const achievementCount = computed(() => dashboard.value?.gamification?.achievements ?? 0);
  const resumeCount = computed(() => dashboard.value?.resumes?.count ?? 0);
  const interviewCount = computed(() => dashboard.value?.interviews?.totalSessions ?? 0);
  const skillsMapped = computed(() => dashboard.value?.skills?.mappedCount ?? 0);

  return {
    profileCompleteness,
    totalJobsSaved,
    totalApplications,
    currentLevel,
    currentXP,
    currentStreak,
    achievementCount,
    resumeCount,
    interviewCount,
    skillsMapped,
  };
}

/**
 * Dashboard statistics composable for aggregate metrics and activity tracking.
 */
export function useStatistics() {
  const api = useApi();
  const { t } = useI18n();
  const state = createStatisticsState();
  const actions = createStatisticsActions(api, t, state);
  const accessors = createStatisticsAccessors(state.dashboard);

  return {
    dashboard: readonly(state.dashboard),
    weekly: readonly(state.weekly),
    career: readonly(state.career),
    loading: readonly(state.loading),
    profileCompleteness: accessors.profileCompleteness,
    totalJobsSaved: accessors.totalJobsSaved,
    totalApplications: accessors.totalApplications,
    currentLevel: accessors.currentLevel,
    currentXP: accessors.currentXP,
    currentStreak: accessors.currentStreak,
    achievementCount: accessors.achievementCount,
    resumeCount: accessors.resumeCount,
    interviewCount: accessors.interviewCount,
    skillsMapped: accessors.skillsMapped,
    fetchDashboard: actions.fetchDashboard,
    fetchWeekly: actions.fetchWeekly,
    fetchCareerProgress: actions.fetchCareerProgress,
    refreshAll: actions.refreshAll,
  };
}

import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { GameStudio } from "@bao/shared/types/interview";
import { useI18n } from "vue-i18n";
import type { ClientApi } from "~/types/client-api";
import { requireApiResponsePayload } from "~/utils/api-response";
import { toGameStudio } from "./api-normalizer-studios";
import { requireValue, withLoadingState } from "./async-flow";
import { useApi } from "./useApi";

interface StudioContext {
  api: ClientApi;
  t: ReturnType<typeof useI18n>["t"];
  loading: ReturnType<typeof useState<boolean>>;
  studios: ReturnType<typeof useState<GameStudio[]>>;
  currentStudio: ReturnType<typeof useState<GameStudio | null>>;
}

type CreateStudioInput = {
  [key: string]: unknown;
};
type UpdateStudioInput = {
  [key: string]: unknown;
};

const toStudioList = (value: unknown): GameStudio[] =>
  Array.isArray(value)
    ? value
        .map((entry) => toGameStudio(entry))
        .filter((entry): entry is GameStudio => entry !== null)
    : [];

const readApiData = async (
  request: Promise<unknown>,
  fallbackMessage: string,
): Promise<unknown> => {
  const response = await request;
  return requireApiResponsePayload(response, fallbackMessage);
};

function createReadStudioActions(context: StudioContext) {
  const searchStudios = async (query?: Record<string, string>) =>
    withLoadingState(context.loading, async () => {
      const data = await readApiData(
        context.api.studios.get({ query: query || {} }),
        context.t("apiErrors.studios.searchFailed"),
      );
      context.studios.value = toStudioList(data);
    });

  const getStudio = async (id: string) =>
    withLoadingState(context.loading, async () => {
      const data = await readApiData(
        context.api.studios({ id }).get(),
        context.t("apiErrors.studios.fetchFailed"),
      );
      const normalized = requireValue(
        toGameStudio(data),
        context.t("apiErrors.studios.invalidPayload"),
      );
      context.currentStudio.value = normalized;
      return normalized;
    });

  return {
    searchStudios,
    getStudio,
  };
}

function createWriteStudioActions(
  context: StudioContext,
  searchStudios: (query?: Record<string, string>) => Promise<void>,
) {
  const createStudio = async (studioData: CreateStudioInput) =>
    withLoadingState(context.loading, async () => {
      const data = await readApiData(
        context.api.studios.post(studioData),
        context.t("apiErrors.studios.createFailed"),
      );
      const normalized = requireValue(
        toGameStudio(data),
        context.t("apiErrors.studios.invalidPayload"),
      );
      await searchStudios();
      return normalized;
    });

  const updateStudio = async (id: string, updates: UpdateStudioInput) =>
    withLoadingState(context.loading, async () => {
      const data = await readApiData(
        context.api.studios({ id }).put(updates),
        context.t("apiErrors.studios.updateFailed"),
      );
      const normalized = requireValue(
        toGameStudio(data),
        context.t("apiErrors.studios.invalidPayload"),
      );
      context.currentStudio.value = normalized;
      await searchStudios();
      return normalized;
    });

  const deleteStudio = async (id: string) =>
    withLoadingState(context.loading, async () => {
      await readApiData(
        context.api.studios({ id }).delete(),
        context.t("apiErrors.studios.deleteFailed"),
      );
      if (context.currentStudio.value?.id === id) {
        context.currentStudio.value = null;
      }
      await searchStudios();
    });

  return {
    createStudio,
    updateStudio,
    deleteStudio,
  };
}

/**
 * Studio discovery composable — Eden fabric. Analytics page owns api.studios.analytics.
 */
export function useStudio() {
  const context: StudioContext = {
    api: useApi(),
    t: useI18n().t,
    studios: useState<GameStudio[]>(STATE_KEYS.STUDIOS_LIST, () => []),
    currentStudio: useState<GameStudio | null>(STATE_KEYS.STUDIO_CURRENT, () => null),
    loading: useState(STATE_KEYS.STUDIO_LOADING, () => false),
  };

  const readActions = createReadStudioActions(context);
  const writeActions = createWriteStudioActions(context, readActions.searchStudios);

  return {
    studios: readonly(context.studios),
    studio: readonly(context.currentStudio),
    currentStudio: readonly(context.currentStudio),
    loading: readonly(context.loading),
    searchStudios: readActions.searchStudios,
    fetchStudios: readActions.searchStudios,
    getStudio: readActions.getStudio,
    fetchStudioById: readActions.getStudio,
    createStudio: writeActions.createStudio,
    updateStudio: writeActions.updateStudio,
    deleteStudio: writeActions.deleteStudio,
  };
}

import { isRecord } from "@bao/shared/utils/type-guards";
import type { ComputedRef, Ref } from "vue";
import { useI18n } from "vue-i18n";
import { settlePromise } from "~/composables/async-flow";
import { PERCENT_MAX } from "~/constants/numeric-ui";
import { getErrorMessage } from "~/utils/errors";

type AnalyticsByBreakdown = Record<string, number>;

type AnalyticsTechnology = {
  name: string;
  count: number;
};

type StudioAnalytics = {
  totalStudios: number;
  byType: AnalyticsByBreakdown;
  bySize: AnalyticsByBreakdown;
  remoteWorkStudios: number;
  topTechnologies: AnalyticsTechnology[];
};

type StudioAnalyticsLoadResult = {
  data: StudioAnalytics | null;
  errorMessage: string | null;
};

type StudioAnalyticsMetrics = {
  bySizeEntries: ComputedRef<[string, number][]>;
  byTypeEntries: ComputedRef<[string, number][]>;
  indieStudiosCount: ComputedRef<number>;
  onSiteOnlyCount: ComputedRef<number>;
  remoteWorkPercentage: ComputedRef<number>;
  remoteWorkStudios: ComputedRef<number>;
  topTechnologies: ComputedRef<AnalyticsTechnology[]>;
  totalStudios: ComputedRef<number>;
};

function toBreakdown(value: unknown): AnalyticsByBreakdown {
  if (!isRecord(value)) {
    return {};
  }

  const breakdown: AnalyticsByBreakdown = {};
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === "number") {
      breakdown[key] = entry;
    }
  }

  return breakdown;
}

function toTechnology(value: unknown): AnalyticsTechnology | null {
  if (!isRecord(value)) {
    return null;
  }

  const name = typeof value.name === "string" ? value.name : "";
  const count = typeof value.count === "number" ? value.count : 0;
  if (!name) {
    return null;
  }

  return { name, count };
}

function mapAnalyticsResponse(data: unknown): StudioAnalytics | null {
  if (!isRecord(data)) {
    return null;
  }

  return {
    totalStudios: typeof data.totalStudios === "number" ? data.totalStudios : 0,
    byType: toBreakdown(data.byType),
    bySize: toBreakdown(data.bySize),
    remoteWorkStudios: typeof data.remoteWorkStudios === "number" ? data.remoteWorkStudios : 0,
    topTechnologies: Array.isArray(data.topTechnologies)
      ? data.topTechnologies
          .map((technology) => toTechnology(technology))
          .filter((technology): technology is AnalyticsTechnology => technology !== null)
      : [],
  };
}

function createStudioAnalyticsMetrics(
  analytics: Ref<StudioAnalytics | null> | ComputedRef<StudioAnalytics | null>,
): StudioAnalyticsMetrics {
  const totalStudios = computed(() => analytics.value?.totalStudios ?? 0);
  const remoteWorkStudios = computed(() => analytics.value?.remoteWorkStudios ?? 0);
  const remoteWorkPercentage = computed(() => {
    if (totalStudios.value === 0) {
      return 0;
    }

    return Math.round((remoteWorkStudios.value / totalStudios.value) * PERCENT_MAX);
  });
  const byTypeEntries = computed(() => Object.entries(analytics.value?.byType ?? {}));
  const bySizeEntries = computed(() => Object.entries(analytics.value?.bySize ?? {}));
  const topTechnologies = computed(() => analytics.value?.topTechnologies ?? []);
  const indieStudiosCount = computed(() => analytics.value?.byType.Indie ?? 0);
  const onSiteOnlyCount = computed(() => Math.max(0, totalStudios.value - remoteWorkStudios.value));

  return {
    bySizeEntries,
    byTypeEntries,
    indieStudiosCount,
    onSiteOnlyCount,
    remoteWorkPercentage,
    remoteWorkStudios,
    topTechnologies,
    totalStudios,
  };
}

function getMaxCount(items: readonly AnalyticsTechnology[]): number {
  return Math.max(1, ...items.map((item) => item.count));
}

async function loadStudioAnalyticsData(
  api: ReturnType<typeof useApi>,
  loadFailedMessage: string,
): Promise<StudioAnalyticsLoadResult> {
  const analyticsResult = await settlePromise(api.studios.analytics.get(), loadFailedMessage);
  if (!analyticsResult.ok) {
    return {
      data: null,
      errorMessage: getErrorMessage(analyticsResult.error, loadFailedMessage),
    };
  }

  const { data, error } = analyticsResult.value;
  if (error) {
    return {
      data: null,
      errorMessage: getErrorMessage(error, loadFailedMessage),
    };
  }

  return {
    data: mapAnalyticsResponse(data),
    errorMessage: null,
  };
}

/**
 * Studio analytics page state. Payload must flow through `useAsyncData` `data`
 * so SSR HTML and client hydration share one owner (no orphan `ref(null)`).
 */
export function useStudioAnalyticsPage() {
  const { $toast } = useNuxtApp();
  const api = useApi();
  const { t } = useI18n();
  const loadFailedMessage = t("studioAnalytics.errors.loadFailed");

  const {
    data: analyticsPayload,
    pending: loading,
    refresh: refreshAnalytics,
    error: asyncError,
  } = useAsyncData(
    "studio-analytics",
    async () => {
      const result = await loadStudioAnalyticsData(api, loadFailedMessage);
      if (result.errorMessage && import.meta.client) {
        $toast.error(result.errorMessage);
      }
      return result;
    },
    { lazy: false, server: true },
  );

  const analytics = computed(() => analyticsPayload.value?.data ?? null);
  const pageError = computed(
    () =>
      analyticsPayload.value?.errorMessage ??
      (asyncError.value ? getErrorMessage(asyncError.value, loadFailedMessage) : null),
  );
  const metrics = createStudioAnalyticsMetrics(analytics);

  return {
    analytics,
    getMaxCount,
    loading,
    pageError,
    refreshAnalytics,
    ...metrics,
  };
}

import { APP_ROUTE_BUILDERS, APP_ROUTE_QUERY_KEYS } from "@bao/shared/constants/routes";
import { useI18n } from "vue-i18n";
import { settlePromise } from "~/composables/async-flow";
import { useDebouncedValue } from "~/composables/useDebouncedValue";
import {
  STUDIO_INDEX_FILTER_DEBOUNCE_MS,
  STUDIO_INDEX_INITIAL_VISIBLE_COUNT,
  STUDIO_INDEX_VISIBLE_INCREMENT,
} from "~/constants/studios";
import { getErrorMessage } from "~/utils/errors";
import { buildInterviewStudioNavigation } from "~/utils/interview-navigation";
import { queryValueToString } from "~/utils/route-query";

function sortUniqueOptions(values: string[]): string[] {
  return [...new Set(values.filter((value) => value.trim().length > 0))].sort((left, right) =>
    left.localeCompare(right),
  );
}

function createStudiosIndexRuntime() {
  const { $toast } = useNuxtApp();
  const route = useRoute();
  const router = useRouter();
  const { t } = useI18n();
  const { studios, loading: studioLoading, fetchStudios } = useStudio();

  const pageError = ref<string | null>(null);
  const searchQuery = ref("");
  const showPreviewModal = ref(false);
  const previewStudioId = ref("");
  const visibleStudioCount = ref(STUDIO_INDEX_INITIAL_VISIBLE_COUNT);
  const filters = reactive({
    remoteWork: false,
    size: "",
    type: "",
  });

  return {
    fetchStudios,
    filters,
    pageError,
    previewStudioId,
    route,
    router,
    searchQuery,
    showPreviewModal,
    studioLoading,
    studios,
    t,
    toast: $toast,
    visibleStudioCount,
  };
}

function createStudiosIndexActions(input: ReturnType<typeof createStudiosIndexRuntime>) {
  const previewActions = createStudiosPreviewActions(input);

  function showErrorToast(message: string) {
    if (import.meta.client) {
      input.toast.error(message);
    }
  }

  async function loadStudios() {
    input.pageError.value = null;
    const studiosResult = await settlePromise(
      input.fetchStudios(),
      input.t("studiosIndex.errors.loadFailed"),
    );
    if (!studiosResult.ok) {
      input.pageError.value = getErrorMessage(
        studiosResult.error,
        input.t("studiosIndex.errors.loadFailed"),
      );
      showErrorToast(input.pageError.value);
    }
  }

  function clearFilters() {
    input.searchQuery.value = "";
    input.filters.type = "";
    input.filters.size = "";
    input.filters.remoteWork = false;
    input.visibleStudioCount.value = STUDIO_INDEX_INITIAL_VISIBLE_COUNT;
  }

  function showMoreStudios(filteredCount: number) {
    input.visibleStudioCount.value = Math.min(
      filteredCount,
      input.visibleStudioCount.value + STUDIO_INDEX_VISIBLE_INCREMENT,
    );
  }

  return {
    clearFilters,
    closeStudioPreview: previewActions.closeStudioPreview,
    loadStudios,
    openStudioPreview: previewActions.openStudioPreview,
    showMoreStudios,
    startInterview: previewActions.startInterview,
    viewStudio: previewActions.viewStudio,
  };
}

function createStudiosPreviewActions(input: ReturnType<typeof createStudiosIndexRuntime>) {
  async function setPreviewRouteStudioId(id: string | null): Promise<void> {
    const nextQuery = { ...input.route.query };
    if (id) {
      nextQuery[APP_ROUTE_QUERY_KEYS.studioId] = id;
    } else {
      delete nextQuery[APP_ROUTE_QUERY_KEYS.studioId];
    }
    await input.router.replace({ query: nextQuery });
  }

  async function openStudioPreview(id: string) {
    input.previewStudioId.value = id;
    input.showPreviewModal.value = true;
    await setPreviewRouteStudioId(id);
  }

  async function closeStudioPreview(routeStudioId: string) {
    input.showPreviewModal.value = false;
    input.previewStudioId.value = "";
    if (routeStudioId) {
      await setPreviewRouteStudioId(null);
    }
  }

  async function viewStudio(id: string, routeStudioId: string) {
    await closeStudioPreview(routeStudioId);
    await input.router.push(APP_ROUTE_BUILDERS.studioDetail(id));
  }

  async function startInterview(studioId: string, routeStudioId: string) {
    await closeStudioPreview(routeStudioId);
    await input.router.push(buildInterviewStudioNavigation(studioId));
  }

  return {
    closeStudioPreview,
    openStudioPreview,
    startInterview,
    viewStudio,
  };
}

function createStudiosIndexDerivedState(input: ReturnType<typeof createStudiosIndexRuntime>) {
  const debouncedSearchQuery = useDebouncedValue(
    input.searchQuery,
    STUDIO_INDEX_FILTER_DEBOUNCE_MS,
  );
  const filterOptions = createStudiosIndexFilterOptions(input.studios);
  const filterResults = createStudiosFilteredResults({
    debouncedSearchQuery,
    filters: input.filters,
    studios: input.studios,
  });
  const loading = computed(() => input.studioLoading.value);
  const totalStudios = computed(() => input.studios.value.length);
  const remoteFriendlyStudios = computed(
    () => input.studios.value.filter((studio) => studio.remoteWork).length,
  );
  const previewStudio = computed(
    () => input.studios.value.find((studio) => studio.id === input.previewStudioId.value) ?? null,
  );
  const routeStudioId = computed(() =>
    queryValueToString(input.route.query[APP_ROUTE_QUERY_KEYS.studioId]),
  );
  const visibleStudios = computed(() =>
    filterResults.filteredStudios.value.slice(0, input.visibleStudioCount.value),
  );
  const hasAdditionalStudios = computed(
    () => visibleStudios.value.length < filterResults.filteredStudios.value.length,
  );

  return {
    debouncedSearchQuery,
    filteredStudios: filterResults.filteredStudios,
    hasAdditionalStudios,
    loading,
    previewStudio,
    remoteFriendlyStudios,
    routeStudioId,
    studioSizeOptions: filterOptions.studioSizeOptions,
    studioTypeOptions: filterOptions.studioTypeOptions,
    totalStudios,
    visibleStudios,
  };
}

function createStudiosIndexFilterOptions(studios: ReturnType<typeof useStudio>["studios"]) {
  const studioTypeOptions = computed(() =>
    sortUniqueOptions(studios.value.map((studio) => studio.type)),
  );
  const studioSizeOptions = computed(() =>
    sortUniqueOptions(studios.value.map((studio) => studio.size)),
  );

  return {
    studioSizeOptions,
    studioTypeOptions,
  };
}

function createStudiosFilteredResults(input: {
  debouncedSearchQuery: Ref<string>;
  filters: {
    remoteWork: boolean;
    size: string;
    type: string;
  };
  studios: ReturnType<typeof useStudio>["studios"];
}) {
  const searchableStudios = computed(() =>
    input.studios.value.map((studio) => ({
      searchableText: `${studio.name} ${studio.description ?? ""} ${studio.location}`.toLowerCase(),
      studio,
    })),
  );
  const filteredStudios = computed(() =>
    filterStudios({
      entries: searchableStudios.value,
      filters: input.filters,
      query: input.debouncedSearchQuery.value,
    }),
  );

  return {
    filteredStudios,
  };
}

function filterStudios(input: {
  entries: Array<{
    searchableText: string;
    studio: ReturnType<typeof useStudio>["studios"]["value"][number];
  }>;
  filters: {
    remoteWork: boolean;
    size: string;
    type: string;
  };
  query: string;
}) {
  let result = input.entries;

  const query = input.query.trim().toLowerCase();
  if (query.length > 0) {
    result = result.filter((entry) => entry.searchableText.includes(query));
  }
  if (input.filters.type.length > 0) {
    result = result.filter((entry) => entry.studio.type === input.filters.type);
  }
  if (input.filters.size.length > 0) {
    result = result.filter((entry) => entry.studio.size === input.filters.size);
  }
  if (input.filters.remoteWork) {
    result = result.filter((entry) => entry.studio.remoteWork);
  }

  return result.map((entry) => entry.studio);
}

function registerStudiosIndexEffects(input: {
  derived: ReturnType<typeof createStudiosIndexDerivedState>;
  runtime: ReturnType<typeof createStudiosIndexRuntime>;
}) {
  watch(
    () => ({
      remoteWork: input.runtime.filters.remoteWork,
      search: input.derived.debouncedSearchQuery.value,
      size: input.runtime.filters.size,
      type: input.runtime.filters.type,
    }),
    () => {
      input.runtime.visibleStudioCount.value = STUDIO_INDEX_INITIAL_VISIBLE_COUNT;
    },
  );

  watch(input.derived.filteredStudios, (nextStudios) => {
    if (nextStudios.length < input.runtime.visibleStudioCount.value) {
      input.runtime.visibleStudioCount.value = nextStudios.length;
    }
  });

  watch(
    input.derived.routeStudioId,
    (studioId) => {
      if (!studioId) {
        input.runtime.showPreviewModal.value = false;
        input.runtime.previewStudioId.value = "";
        return;
      }

      input.runtime.previewStudioId.value = studioId;
      input.runtime.showPreviewModal.value = true;
    },
    { immediate: true },
  );
}

export function useStudiosIndexPage() {
  const runtime = createStudiosIndexRuntime();
  const actions = createStudiosIndexActions(runtime);
  const derived = createStudiosIndexDerivedState(runtime);
  registerStudiosIndexEffects({
    derived,
    runtime,
  });

  return {
    clearFilters: actions.clearFilters,
    closeStudioPreview: () => actions.closeStudioPreview(derived.routeStudioId.value),
    filteredStudios: derived.filteredStudios,
    filters: runtime.filters,
    hasAdditionalStudios: derived.hasAdditionalStudios,
    loadStudios: actions.loadStudios,
    loading: derived.loading,
    openStudioPreview: actions.openStudioPreview,
    pageError: runtime.pageError,
    previewStudio: derived.previewStudio,
    remoteFriendlyStudios: derived.remoteFriendlyStudios,
    searchQuery: runtime.searchQuery,
    showMoreStudios: () => actions.showMoreStudios(derived.filteredStudios.value.length),
    showPreviewModal: runtime.showPreviewModal,
    startInterview: (studioId: string) =>
      actions.startInterview(studioId, derived.routeStudioId.value),
    studioSizeOptions: derived.studioSizeOptions,
    studioTypeOptions: derived.studioTypeOptions,
    totalStudios: derived.totalStudios,
    viewStudio: (id: string) => actions.viewStudio(id, derived.routeStudioId.value),
    visibleStudios: derived.visibleStudios,
  };
}

import type { VoiceSettings } from "@bao/shared/types/interview";
import type { Ref } from "vue";
import { resolveSpeechLocale, resolveSpeechSynthesis } from "~/utils/speech";

interface TTSState {
  isSpeaking: Ref<boolean>;
  isPaused: Ref<boolean>;
  error: Ref<string | null>;
  voices: Ref<SpeechSynthesisVoice[]>;
}

interface TTSContext {
  settings?: Ref<VoiceSettings | undefined>;
  state: TTSState;
  synthesis: SpeechSynthesis | null;
}

function createTTSState(): TTSState {
  return {
    isSpeaking: ref(false),
    isPaused: ref(false),
    error: ref<string | null>(null),
    voices: ref<SpeechSynthesisVoice[]>([]),
  };
}

function resolveContextSynthesis(context: TTSContext): SpeechSynthesis | null {
  const resolved = context.synthesis ?? resolveSpeechSynthesis();
  if (resolved) {
    context.synthesis = resolved;
  }
  return resolved;
}

function loadVoices(context: TTSContext): SpeechSynthesisVoice[] {
  const synthesis = resolveContextSynthesis(context);
  if (!synthesis) {
    context.state.voices.value = [];
    return [];
  }

  const availableVoices = synthesis.getVoices();
  context.state.voices.value = availableVoices;
  return availableVoices;
}

function resolveVoiceById(
  voices: readonly SpeechSynthesisVoice[],
  id: string,
): SpeechSynthesisVoice | undefined {
  const normalizedId = id.toLowerCase();
  return voices.find(
    (voice) =>
      voice.voiceURI === id || voice.name === id || voice.name.toLowerCase().includes(normalizedId),
  );
}

function createUtterance(
  context: TTSContext,
  text: string,
  opts?: Partial<Pick<VoiceSettings, "voiceId" | "rate" | "pitch" | "volume" | "language">>,
): SpeechSynthesisUtterance {
  const persisted: Partial<VoiceSettings> = context.settings?.value ?? {};
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.rate = opts?.rate ?? persisted.rate ?? 1;
  utterance.pitch = opts?.pitch ?? persisted.pitch ?? 1;
  utterance.volume = Math.max(0, Math.min(1, opts?.volume ?? persisted.volume ?? 1));
  utterance.lang = resolveSpeechLocale(opts?.language ?? persisted.language);

  const voiceId = opts?.voiceId ?? persisted.voiceId;
  if (voiceId) {
    const voice = resolveVoiceById(context.state.voices.value, voiceId);
    if (voice) {
      utterance.voice = voice;
    }
  }

  utterance.onstart = () => {
    context.state.isSpeaking.value = true;
    context.state.isPaused.value = false;
    context.state.error.value = null;
  };
  utterance.onend = () => {
    context.state.isSpeaking.value = false;
    context.state.isPaused.value = false;
  };
  utterance.onerror = (event: SpeechSynthesisErrorEvent) => {
    context.state.error.value = event.error;
    context.state.isSpeaking.value = false;
    context.state.isPaused.value = false;
  };

  return utterance;
}

function createTTSActions(context: TTSContext) {
  const speak = (
    text: string,
    opts?: Partial<Pick<VoiceSettings, "voiceId" | "rate" | "pitch" | "volume" | "language">>,
  ): void => {
    const synthesis = resolveContextSynthesis(context);
    if (!synthesis) {
      return;
    }
    synthesis.cancel();
    synthesis.speak(createUtterance(context, text, opts));
  };

  const pause = (): void => {
    if (context.synthesis && context.state.isSpeaking.value) {
      context.synthesis.pause();
      context.state.isPaused.value = true;
    }
  };

  const resume = (): void => {
    if (context.synthesis && context.state.isPaused.value) {
      context.synthesis.resume();
      context.state.isPaused.value = false;
    }
  };

  const cancel = (): void => {
    if (context.synthesis) {
      context.synthesis.cancel();
    }
    context.state.isSpeaking.value = false;
    context.state.isPaused.value = false;
  };

  return {
    speak,
    pause,
    resume,
    cancel,
  };
}

/**
 * Web Speech API Text-to-Speech composable.
 * Supports VoiceSettings: voiceId, rate, pitch, volume, language.
 */
export function useTTS(settings?: Ref<VoiceSettings | undefined>) {
  const context: TTSContext = {
    settings,
    state: createTTSState(),
    synthesis: null,
  };

  onMounted(() => {
    const synthesis = resolveContextSynthesis(context);
    if (!synthesis) {
      return;
    }
    synthesis.onvoiceschanged = () => {
      loadVoices(context);
    };
    loadVoices(context);
  });

  const isSupported = computed(() => resolveContextSynthesis(context) !== null);
  const actions = createTTSActions(context);

  return {
    ...actions,
    isSpeaking: readonly(context.state.isSpeaking),
    isPaused: readonly(context.state.isPaused),
    error: readonly(context.state.error),
    voices: readonly(context.state.voices),
    isSupported: readonly(isSupported),
    loadVoices: () => loadVoices(context),
  };
}

import {
  type AppDataTheme,
  normalizeAppDataTheme,
  THEME_NAMES,
} from "@bao/shared/constants/branding";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import { SECONDS_PER_DAY } from "@bao/shared/constants/time";
import { readonly } from "vue";
import { useCookie, useState } from "#imports";
import { THEME_COOKIE_MAX_AGE_DAYS } from "~/constants/numeric-ui";

/**
 * Theme toggle: daisyUI `corporate` (light) / `business` (dark), driven by `data-theme`.
 * Persists via cookie (SSOT with settings sync).
 */
export function useTheme() {
  const theme = useState<AppDataTheme>(STATE_KEYS.APP_THEME, () => THEME_NAMES.light);
  const themeCookie = useCookie<string | null>(THEME_NAMES.storageKey, {
    default: () => null,
    path: "/",
    sameSite: "lax",
    maxAge: SECONDS_PER_DAY * THEME_COOKIE_MAX_AGE_DAYS,
  });

  function setTheme(newTheme: AppDataTheme, options: { persist?: boolean } = {}) {
    theme.value = newTheme;
    if (import.meta.client) {
      document.documentElement.setAttribute("data-theme", newTheme);
    }
    if (options.persist !== false) {
      themeCookie.value = newTheme;
    }
  }

  function toggleTheme() {
    setTheme(theme.value === THEME_NAMES.light ? THEME_NAMES.dark : THEME_NAMES.light);
  }

  function initTheme(preferredTheme?: AppDataTheme) {
    // Settings are the persisted SSOT; cookie is a hydration cache only.
    if (preferredTheme) {
      setTheme(preferredTheme, { persist: true });
      return;
    }

    const savedRaw = themeCookie.value;
    if (savedRaw) {
      const normalized = normalizeAppDataTheme(savedRaw);
      setTheme(normalized, { persist: normalized !== savedRaw });
      return;
    }

    if (import.meta.client && window.matchMedia("(prefers-color-scheme: dark)").matches) {
      setTheme(THEME_NAMES.dark, { persist: false });
    }
  }

  return {
    theme: readonly(theme),
    setTheme,
    toggleTheme,
    initTheme,
  };
}

import { STATE_KEYS } from "@bao/shared/constants/state-keys";

const DEFAULT_TOAST_DURATION_MS = 5_000;
const ERROR_TOAST_DURATION_MS = 8_000;

const toastTypeTitles = {
  success: "Success",
  error: "Error",
  info: "Info",
  warning: "Warning",
} as const;

let toastSequence = 0;
const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

/**
 * Supported toast semantic types.
 */
export type ToastType = "success" | "error" | "info" | "warning";

/**
 * Reactive toast item rendered by `ToastContainer`.
 */
export type ToastItem = {
  id: string;
  type: ToastType;
  title: string;
  message: string;
  durationMs: number;
};

/**
 * Toast override options for title and visibility duration.
 */
export type ToastOptions = {
  title?: string;
  durationMs?: number;
};

/**
 * Public toast API exposed through `$toast`.
 */
export type ToastApi = {
  success: (message: string, options?: ToastOptions) => string;
  error: (message: string, options?: ToastOptions) => string;
  info: (message: string, options?: ToastOptions) => string;
  warning: (message: string, options?: ToastOptions) => string;
};

function getToastDuration(type: ToastType, durationOverride?: number): number {
  if (
    typeof durationOverride === "number" &&
    Number.isFinite(durationOverride) &&
    durationOverride >= 0
  ) {
    return durationOverride;
  }
  return type === "error" ? ERROR_TOAST_DURATION_MS : DEFAULT_TOAST_DURATION_MS;
}

function createToastId(): string {
  toastSequence += 1;
  return `toast-${toastSequence}`;
}

function clearToastTimeout(toastId: string): void {
  const timeout = toastTimeouts.get(toastId);
  if (!timeout) {
    return;
  }
  clearTimeout(timeout);
  toastTimeouts.delete(toastId);
}

/**
 * Centralized reactive toast store used by the global `$toast` plugin.
 */
export function useToast() {
  const toasts = useState<ToastItem[]>(STATE_KEYS.UI_TOASTS, () => []);

  function removeToast(toastId: string): void {
    clearToastTimeout(toastId);
    toasts.value = toasts.value.filter((toast) => toast.id !== toastId);
  }

  function clearToasts(): void {
    for (const toast of toasts.value) {
      clearToastTimeout(toast.id);
    }
    toasts.value = [];
  }

  function pushToast(message: string, type: ToastType, options: ToastOptions = {}): string {
    const normalizedMessage = message.trim();
    if (!normalizedMessage) {
      return "";
    }

    const toastId = createToastId();
    const durationMs = getToastDuration(type, options.durationMs);

    toasts.value = [
      ...toasts.value,
      {
        id: toastId,
        type,
        title: options.title || toastTypeTitles[type],
        message: normalizedMessage,
        durationMs,
      },
    ];

    if (import.meta.client && durationMs > 0) {
      const timeout = setTimeout(() => {
        removeToast(toastId);
      }, durationMs);
      toastTimeouts.set(toastId, timeout);
    }

    return toastId;
  }

  const toastApi: ToastApi = {
    success: (message, options) => pushToast(message, "success", options),
    error: (message, options) => pushToast(message, "error", options),
    info: (message, options) => pushToast(message, "info", options),
    warning: (message, options) => pushToast(message, "warning", options),
  };

  return {
    toasts: readonly(toasts),
    pushToast,
    removeToast,
    clearToasts,
    ...toastApi,
  };
}

import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { UserProfile } from "@bao/shared/types/user";
import { readonly } from "vue";
import { useI18n } from "vue-i18n";
import { useState } from "#imports";
import { toUserProfile } from "./api-normalizer-user";
import { assertApiResponse, requireValue, withLoadingState } from "./async-flow";
import { useApi } from "./useApi";

type ApiClient = ReturnType<typeof useApi>;
type UpdateUserProfileInput = NonNullable<Parameters<ApiClient["user"]["profile"]["put"]>[0]>;

/**
 * User profile management composable.
 */
export function useUser() {
  const api = useApi();
  const { t } = useI18n();
  const profile = useState<UserProfile | null>(STATE_KEYS.USER_PROFILE, () => null);
  const loading = useState(STATE_KEYS.USER_LOADING, () => false);

  async function fetchProfile() {
    return withLoadingState(loading, async () => {
      const { data, error } = await api.user.profile.get();
      assertApiResponse(error, t("apiErrors.user.fetchProfileFailed"));
      const normalized = requireValue(toUserProfile(data), t("apiErrors.user.invalidPayload"));
      profile.value = normalized;
    });
  }

  async function updateProfile(updates: UpdateUserProfileInput) {
    return withLoadingState(loading, async () => {
      const { data, error } = await api.user.profile.put(updates);
      assertApiResponse(error, t("apiErrors.user.updateProfileFailed"));
      const normalized = requireValue(toUserProfile(data), t("apiErrors.user.invalidPayload"));
      profile.value = normalized;
    });
  }

  return {
    profile: readonly(profile),
    loading: readonly(loading),
    fetchProfile,
    updateProfile,
  };
}

import {
  APP_ROUTE_BUILDERS,
  APP_ROUTE_QUERY_KEYS,
  APP_ROUTES,
} from "@bao/shared/constants/routes";
import { SEARCH_RESULT_TYPES, type SearchResultType } from "@bao/shared/constants/search";
import { settle } from "@bao/shared/utils/promise";
import { isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import { assertApiResponse, withLoadingState } from "~/composables/async-flow";
import { useApi } from "~/composables/useApi";

export type WorkspaceSearchResult = {
  type: SearchResultType;
  id: string;
  title: string;
  subtitle: string;
  snippet: string;
  relevance: number;
};

export type WorkspaceSearchSuggestion = {
  text: string;
  type: string;
};

/** SSOT route map — keys MUST equal SEARCH_RESULT_TYPES (validate:search-type-parity). */
export const SEARCH_TYPE_ROUTE: Record<SearchResultType, (id: string) => string> = {
  jobs: (id) => APP_ROUTE_BUILDERS.jobDetail(id),
  studios: (id) => APP_ROUTE_BUILDERS.studioDetail(id),
  resumes: (id) => APP_ROUTE_BUILDERS.resumeEditor(id),
  skills: () => APP_ROUTES.skills,
  "cover-letters": (id) => APP_ROUTE_BUILDERS.coverLetterDetail(id),
  "portfolio-projects": (id) =>
    `${APP_ROUTES.portfolio}?${APP_ROUTE_QUERY_KEYS.id}=${encodeURIComponent(id)}`,
  "interview-sessions": (id) => APP_ROUTE_BUILDERS.interviewSession(id),
  "automation-runs": (id) => APP_ROUTE_BUILDERS.automationRunDetail(id),
};

const AUTOCOMPLETE_MIN_PREFIX = 2;
const AUTOCOMPLETE_DEBOUNCE_MS = 180;

export const WORKSPACE_OMNI_SEARCH_OPEN_EVENT = "bao:open-omni-search";

export function resolveWorkspaceSearchResultRoute(result: WorkspaceSearchResult): string {
  const builder = SEARCH_TYPE_ROUTE[result.type];
  return builder(result.id);
}

function asString(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function asSearchResultType(value: unknown): SearchResultType | null {
  if (typeof value !== "string") {
    return null;
  }
  return (SEARCH_RESULT_TYPES as readonly string[]).includes(value)
    ? (value as SearchResultType)
    : null;
}

function mapSearchResults(data: unknown): WorkspaceSearchResult[] {
  const resultsValue = isRecord(data) ? data.results : undefined;
  const nextResults: readonly unknown[] = Array.isArray(resultsValue) ? resultsValue : [];
  const mapped: WorkspaceSearchResult[] = [];
  for (const entry of nextResults) {
    if (!isRecord(entry)) {
      continue;
    }
    const type = asSearchResultType(entry.type);
    if (!type) {
      continue;
    }
    mapped.push({
      type,
      id: asString(entry.id),
      title: asString(entry.title),
      subtitle: asString(entry.subtitle),
      snippet: asString(entry.snippet),
      relevance: typeof entry.relevance === "number" ? entry.relevance : 0,
    });
  }
  return mapped;
}

function mapSuggestions(data: unknown): WorkspaceSearchSuggestion[] {
  if (!Array.isArray(data)) {
    return [];
  }
  const entries: readonly unknown[] = data;
  const mapped: WorkspaceSearchSuggestion[] = [];
  for (const entry of entries) {
    if (!isRecord(entry)) {
      continue;
    }
    mapped.push({
      text: asString(entry.text),
      type: asString(entry.type),
    });
  }
  return mapped;
}

function createWorkspaceSearchActions(input: {
  api: ReturnType<typeof useApi>;
  loading: Ref<boolean>;
  query: Ref<string>;
  results: Ref<WorkspaceSearchResult[]>;
  suggesting: Ref<boolean>;
  suggestions: Ref<WorkspaceSearchSuggestion[]>;
  t: ReturnType<typeof useI18n>["t"];
}) {
  let autocompleteTimer: ReturnType<typeof setTimeout> | undefined;

  const search = async (nextQuery = input.query.value): Promise<void> => {
    const trimmed = nextQuery.trim();
    input.query.value = trimmed;
    if (trimmed.length < AUTOCOMPLETE_MIN_PREFIX) {
      input.results.value = [];
      return;
    }
    await withLoadingState(input.loading, async () => {
      const { data, error } = await input.api.search.get({ query: { q: trimmed } });
      assertApiResponse(error, input.t("workspaceSearch.searchFailed"));
      input.results.value = mapSearchResults(data);
    });
  };

  const fetchAutocomplete = async (prefix = input.query.value): Promise<void> => {
    const trimmed = prefix.trim();
    if (trimmed.length < AUTOCOMPLETE_MIN_PREFIX) {
      input.suggestions.value = [];
      return;
    }
    input.suggesting.value = true;
    const settled = await settle(input.api.search.autocomplete.get({ query: { prefix: trimmed } }));
    input.suggesting.value = false;
    if (settled.status !== "fulfilled") {
      return;
    }
    const { data, error } = settled.value;
    assertApiResponse(error, input.t("workspaceSearch.autocompleteFailed"));
    input.suggestions.value = mapSuggestions(data);
  };

  const scheduleAutocomplete = (prefix = input.query.value): void => {
    if (autocompleteTimer) {
      clearTimeout(autocompleteTimer);
    }
    autocompleteTimer = setTimeout(() => {
      settle(fetchAutocomplete(prefix)).then(
        () => undefined,
        () => undefined,
      );
    }, AUTOCOMPLETE_DEBOUNCE_MS);
  };

  const applySuggestion = async (suggestion: WorkspaceSearchSuggestion): Promise<void> => {
    input.query.value = suggestion.text;
    input.suggestions.value = [];
    await search(suggestion.text);
  };

  const clear = (): void => {
    if (autocompleteTimer) {
      clearTimeout(autocompleteTimer);
      autocompleteTimer = undefined;
    }
    input.query.value = "";
    input.results.value = [];
    input.suggestions.value = [];
  };

  return {
    applySuggestion,
    clear,
    scheduleAutocomplete,
    search,
  };
}

export function useWorkspaceSearch() {
  const api = useApi();
  const { t } = useI18n();
  const query = ref("");
  const results = ref<WorkspaceSearchResult[]>([]);
  const suggestions = ref<WorkspaceSearchSuggestion[]>([]);
  const loading = ref(false);
  const suggesting = ref(false);
  const open = ref(false);
  const actions = createWorkspaceSearchActions({
    api,
    loading,
    query,
    results,
    suggesting,
    suggestions,
    t,
  });

  return {
    applySuggestion: actions.applySuggestion,
    clear: actions.clear,
    loading: readonly(loading),
    open,
    query,
    results: readonly(results),
    scheduleAutocomplete: actions.scheduleAutocomplete,
    suggesting: readonly(suggesting),
    suggestions: readonly(suggestions),
    search: actions.search,
  };
}

