import { APP_ROUTES } from "@bao/shared/constants/routes";
import { describe, expect, it } from "vitest";
import {
  DOCK_NAVIGATION_IDS,
  getDockNavigationItems,
  isDockRouteActive,
  NAVIGATION_ITEMS,
  type NavigationItem,
} from "./navigation";

const requireNavItem = (id: string): NavigationItem => {
  const item = NAVIGATION_ITEMS.find((candidate) => candidate.id === id);
  expect(item, `${id} nav item missing from NAVIGATION_ITEMS`).toBeDefined();
  if (!item) {
    throw new Error(`${id} nav item missing from NAVIGATION_ITEMS`);
  }
  return item;
};

describe("dock section wayfinding", () => {
  it("activates ai-chat for AI section prefixes", () => {
    const aiChat = requireNavItem("ai-chat");
    expect(isDockRouteActive(APP_ROUTES.aiChat, aiChat)).toBe(true);
    expect(isDockRouteActive(APP_ROUTES.aiDashboard, aiChat)).toBe(true);
  });

  it("activates Jobs dock for automation Work-section routes (automation not in dock)", () => {
    const jobs = requireNavItem("jobs");
    const automation = requireNavItem("automation");
    expect(automation.includeInDock).toBe(false);
    expect(jobs.includeInDock).toBe(true);
    expect(isDockRouteActive(APP_ROUTES.automation, jobs)).toBe(true);
    expect(isDockRouteActive(APP_ROUTES.automationRuns, jobs)).toBe(true);
    expect(isDockRouteActive(APP_ROUTES.automationJobApply, jobs)).toBe(true);
  });

  it("keeps dock composition as Home/Work/Create/AI/System", () => {
    const ids = getDockNavigationItems().map((item) => item.id);
    expect(ids).toEqual([...DOCK_NAVIGATION_IDS]);
  });
});

import { describe, expect, it } from "vitest";
import {
  DOCK_NAVIGATION_IDS,
  getDockNavigationItems,
  MOBILE_DOCK_MAX_ITEMS,
  NAVIGATION_ITEMS,
} from "./navigation";

describe("mobile dock navigation SSOT", () => {
  it("keeps dock at or under Apple HIG primary-destination cap", () => {
    const dock = getDockNavigationItems();
    expect(dock.length).toBeGreaterThan(0);
    expect(dock.length).toBeLessThanOrEqual(MOBILE_DOCK_MAX_ITEMS);
  });

  it("uses the canonical Home/Work/Create/AI/System dock set", () => {
    expect(getDockNavigationItems().map((item) => item.id)).toEqual([...DOCK_NAVIGATION_IDS]);
  });

  it("never flags more dock candidates than the cap without slice protection", () => {
    const flagged = NAVIGATION_ITEMS.filter((item) => item.includeInDock);
    expect(flagged.length).toBeLessThanOrEqual(MOBILE_DOCK_MAX_ITEMS);
  });

  it("excludes automation and docs from the dock", () => {
    const ids = getDockNavigationItems().map((item) => item.id);
    expect(ids).not.toContain("automation");
    expect(ids).not.toContain("apiDocs");
  });
});

import { describe, expect, it } from "vitest";
import { getSidebarNavigationGroups, NAVIGATION_GROUP_IDS, NAVIGATION_ITEMS } from "./navigation";

describe("sidebar navigation groups SSOT", () => {
  it("assigns every sidebar item a known groupId", () => {
    for (const item of NAVIGATION_ITEMS.filter((entry) => entry.includeInSidebar)) {
      expect(NAVIGATION_GROUP_IDS.includes(item.groupId)).toBe(true);
    }
  });

  it("returns non-empty Work/Create/Intelligence/System groups", () => {
    const groups = getSidebarNavigationGroups();
    expect(groups.map((group) => group.id)).toEqual([...NAVIGATION_GROUP_IDS]);
    for (const group of groups) {
      expect(group.items.length).toBeGreaterThan(0);
    }
  });

  it("places AI chat before AI dashboard in intelligence", () => {
    const intelligence = getSidebarNavigationGroups().find((group) => group.id === "intelligence");
    expect(intelligence?.items.map((item) => item.id)).toEqual(["ai-chat", "ai-dashboard"]);
  });
});

