const providerCatalogById = new Map<AIProviderType, AIProviderMetadata>(
  AI_PROVIDER_CATALOG.map<[AIProviderType, AIProviderMetadata]>((provider) => [
    provider.id,
    provider,
  ]),
);

const isProviderId = (value: string): value is AIProviderType =>
  AI_PROVIDER_CATALOG.some((provider) => provider.id === value);

const resolveNonEmptyString = (value?: string | null): string => value?.trim() ?? "";

const uniqueNonEmptyStrings = (values: Iterable<string | null | undefined>): string[] => {
  const ordered = new Set<string>();
  for (const value of values) {
    const trimmed = resolveNonEmptyString(value);
    if (trimmed.length > 0) {
      ordered.add(trimmed);
    }
  }
  return [...ordered];
};

const resolvePreferredProviderId = (value?: string | null): AIProviderType => {
  const candidate = resolveNonEmptyString(value);
  return candidate && isProviderId(candidate) ? candidate : AI_PROVIDER_DEFAULT;
};

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

const asString = (value: unknown): string | undefined =>
  typeof value === "string" ? value : undefined;

const asBoolean = (value: unknown): boolean | undefined =>
  typeof value === "boolean" ? value : undefined;

const asStringArray = (value: unknown): string[] =>
  Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === "string") : [];

const providerHealthValues = new Set(["healthy", "degraded", "down", "unconfigured"]);

const isProviderHealth = (value: string): value is AIProviderHealth =>
  providerHealthValues.has(value);

const hasExplicitOverride = (value: string | null | undefined): boolean =>
  value !== undefined && value !== null;

const resolveLocalConfiguredModel = (
  settings: AppSettingsSnapshot | null | undefined,
  model?: string | null,
): string =>
  hasExplicitOverride(model)
    ? resolveNonEmptyString(model)
    : resolveNonEmptyString(settings?.localModelName);

const resolveLocalEndpoint = (
  settings: AppSettingsSnapshot | null | undefined,
  endpoint?: string | null,
): string =>
  hasExplicitOverride(endpoint)
    ? resolveNonEmptyString(endpoint) || LOCAL_AI_DEFAULT_ENDPOINT
    : resolveNonEmptyString(settings?.localModelEndpoint) || LOCAL_AI_DEFAULT_ENDPOINT;

const resolveLocalDiagnosticCode = (
  diagnostics: AIProviderDiagnostic | undefined,
  testResult?: ClientProviderTestResult | null,
): AIProviderDiagnostic["code"] | "unconfigured" => {
  if (testResult) {
    return testResult.valid ? "healthy" : (testResult.diagnosticCode ?? "error");
  }
  return diagnostics?.code ?? "unconfigured";
};

const resolveLocalAvailableModels = (
  diagnostics: AIProviderDiagnostic | undefined,
  testResult?: ClientProviderTestResult | null,
): string[] =>
  uniqueNonEmptyStrings([
    testResult?.selectedModel,
    ...(testResult?.availableModels ?? []),
    diagnostics?.selectedModel,
    ...(diagnostics?.availableModels ?? []),
    ...LOCAL_AI_RECOMMENDED_MODELS,
  ]);

const resolveLocalSelectedModel = (
  configuredModel: string,
  availableModels: readonly string[],
  diagnostics: AIProviderDiagnostic | undefined,
  testResult?: ClientProviderTestResult | null,
): string =>
  configuredModel ||
  resolveNonEmptyString(testResult?.selectedModel) ||
  resolveNonEmptyString(diagnostics?.selectedModel) ||
  availableModels[0] ||
  "";

/**
 * Client-facing provider test result fields returned by the settings test endpoint.
 */
export interface ClientProviderTestResult {
  valid: boolean;
  diagnosticCode?: AIProviderDiagnostic["code"];
  message?: string;
  availableModels?: string[];
  selectedModel?: string;
}

/**
 * Normalized provider/model pair resolved from persisted AI routing settings.
 */
export interface AIRoutingPreferenceState {
  provider: AIProviderType;
  model: string;
}

/**
 * Canonical local-provider readiness and model-selection state for client surfaces.
 */
export interface LocalProviderState {
  endpoint: string;
  configuredModel: string;
  selectedModel: string;
  availableModels: string[];
  diagnosticCode: AIProviderDiagnostic["code"] | "unconfigured";
  message?: string;
  isHealthy: boolean;
}

/**
 * Canonical client-side provider health values rendered across AI surfaces.
 */
export type AIProviderHealth = "healthy" | "degraded" | "down" | "unconfigured";

/**
 * Canonical normalized provider row returned to AI dashboard and settings surfaces.
 */
export interface AIProviderRow {
  id: AIProviderType;
  iconId: AIProviderType;
  models: string[];
  available: boolean;
  health: AIProviderHealth;
}

/**
 * Looks up the canonical provider catalog row.
 */
export function resolveProviderMetadata(
  providerId: AIProviderType,
): AIProviderMetadata | undefined {
  return providerCatalogById.get(providerId);
}

/**
 * Returns a stable provider-diagnostics map from persisted settings.
 */
export function resolveProviderDiagnostics(
  settings?: AppSettingsSnapshot | null,
): AIProviderDiagnostics {
  return settings?.providerDiagnostics ?? {};
}

/**
 * Resolves whether the given provider is configured from the canonical settings payload.
 */
export function isProviderConfigured(
  settings: AppSettingsSnapshot | null | undefined,
  providerId: AIProviderType,
): boolean {
  if (!settings) {
    return false;
  }

  if (providerId === "local") {
    return settings.hasLocalKey ?? resolveNonEmptyString(settings.localModelEndpoint).length > 0;
  }
  if (providerId === "gemini") {
    return Boolean(settings.hasGeminiKey);
  }
  if (providerId === "openai") {
    return Boolean(settings.hasOpenaiKey);
  }
  if (providerId === "claude") {
    return Boolean(settings.hasClaudeKey);
  }
  return Boolean(settings.hasHuggingfaceToken);
}

/**
 * Resolves the canonical provider/model selection for one AI routing purpose.
 */
export function resolveAIRoutingPreference(
  settings: AppSettingsSnapshot | null | undefined,
  purpose: AIRoutingPurpose = "chat",
): AIRoutingPreferenceState {
  const preferredProvider = resolvePreferredProviderId(settings?.preferredProvider);
  const routedTarget = settings?.aiRouting?.[purpose];
  const provider = resolvePreferredProviderId(routedTarget?.provider ?? preferredProvider);
  const model =
    resolveNonEmptyString(routedTarget?.model) ||
    (purpose === "chat" ? resolveNonEmptyString(settings?.preferredModel) : "");

  return {
    provider,
    model,
  };
}

/**
 * Builds the ordered model-option list for one provider from diagnostics, routing, and catalog hints.
 */
export function resolveProviderModelOptions(
  providerId: AIProviderType,
  settings: AppSettingsSnapshot | null | undefined,
  extraModels: readonly string[] = [],
): string[] {
  const diagnostics = resolveProviderDiagnostics(settings)[providerId];
  const chatRouting = resolveAIRoutingPreference(settings, "chat");
  const catalogEntry = providerCatalogById.get(providerId);

  return uniqueNonEmptyStrings([
    ...(chatRouting.provider === providerId ? [chatRouting.model] : []),
    ...(settings?.preferredProvider === providerId ? [settings?.preferredModel] : []),
    diagnostics?.selectedModel,
    ...(diagnostics?.availableModels ?? []),
    ...extraModels,
    ...(catalogEntry?.modelHints ?? []),
  ]);
}

/**
 * Resolves the currently selected model for a provider from the canonical routing contract.
 */
export function resolveProviderModelSelection(
  providerId: AIProviderType,
  settings: AppSettingsSnapshot | null | undefined,
  extraModels: readonly string[] = [],
): string {
  const chatRouting = resolveAIRoutingPreference(settings, "chat");
  if (chatRouting.provider === providerId && chatRouting.model.length > 0) {
    return chatRouting.model;
  }

  return resolveProviderModelOptions(providerId, settings, extraModels)[0] ?? "";
}

const normalizeProviderRow = (
  row: unknown,
  settings: AppSettingsSnapshot | null | undefined,
): AIProviderRow | null => {
  if (!isRecord(row)) {
    return null;
  }

  const rawId = asString(row.id);
  if (!(rawId && isProviderId(rawId))) {
    return null;
  }

  const catalogEntry = resolveProviderMetadata(rawId);
  if (!catalogEntry) {
    return null;
  }

  const available = asBoolean(row.available) ?? isProviderConfigured(settings, rawId);
  const rawHealth = asString(row.health);
  let health: AIProviderHealth;
  if (rawHealth && isProviderHealth(rawHealth)) {
    health = rawHealth;
  } else if (available) {
    health = "healthy";
  } else {
    health = "unconfigured";
  }
  const models = asStringArray(row.models);

  return {
    id: rawId,
    iconId: catalogEntry.iconId,
    models: models.length > 0 ? models : [...catalogEntry.modelHints],
    available,
    health,
  };
};

/**
 * Normalizes provider rows from the canonical shared AI models payload shape.
 */
export function normalizeProviderRows(
  value: unknown,
  settings: AppSettingsSnapshot | null | undefined,
): AIProviderRow[] {
  if (!isRecord(value)) {
    return [];
  }

  const rows = Array.isArray(value.providers) ? value.providers : [];
  return rows
    .map((row) => normalizeProviderRow(row, settings))
    .filter((provider): provider is AIProviderRow => provider !== null);
}

/**
 * Builds fallback provider rows when diagnostics are unavailable.
 */
export function buildFallbackProviderRows(
  settings: AppSettingsSnapshot | null | undefined,
): AIProviderRow[] {
  return AI_PROVIDER_DEFAULT_ORDER.map((providerId) => {
    const catalogEntry = resolveProviderMetadata(providerId);

    return {
      id: providerId,
      iconId: catalogEntry?.iconId ?? providerId,
      models: catalogEntry ? [...catalogEntry.modelHints] : [],
      available: isProviderConfigured(settings, providerId),
      health: isProviderConfigured(settings, providerId) ? "degraded" : "unconfigured",
    };
  });
}

/**
 * Resolves the local-provider endpoint, model, and diagnostics into one stable presentation state.
 */
export function resolveLocalProviderState(options: {
  settings?: AppSettingsSnapshot | null;
  endpoint?: string | null;
  model?: string | null;
  diagnostic?: AIProviderDiagnostic | null;
  testResult?: ClientProviderTestResult | null;
}): LocalProviderState {
  const diagnostics =
    options.diagnostic ?? resolveProviderDiagnostics(options.settings).local ?? undefined;
  const configuredModel = resolveLocalConfiguredModel(options.settings, options.model);
  const availableModels = resolveLocalAvailableModels(diagnostics, options.testResult);
  const selectedModel = resolveLocalSelectedModel(
    configuredModel,
    availableModels,
    diagnostics,
    options.testResult,
  );
  const diagnosticCode = resolveLocalDiagnosticCode(diagnostics, options.testResult);

  return {
    endpoint: resolveLocalEndpoint(options.settings, options.endpoint),
    configuredModel,
    selectedModel,
    availableModels,
    diagnosticCode,
    message: options.testResult?.message ?? diagnostics?.message,
    isHealthy: diagnosticCode === "healthy",
  };
}

import type {
  ApiEndpoint,
  ApiEndpointGroup,
  OpenApiOperation,
  OpenApiParameter,
  OpenApiRequestBody,
  OpenApiSpec,
} from "~/types/api-docs";
import {
  getOperationParameters,
  getPathParameters,
  readOpenApiRequestBody,
  readOpenApiResponses,
} from "~/utils/api-docs-openapi";
import {
  API_DOCS_HTTP_METHODS_ORDER,
  isApiHttpMethod,
  normalizeApiDocsPathForId,
} from "~/utils/api-docs-status";

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const dedupeCaseInsensitiveStrings = (values: readonly string[]): string[] => {
  const seen = new Set<string>();
  const output: string[] = [];
  for (const value of values) {
    const normalized = value.trim();
    if (!normalized) {
      continue;
    }

    const key = normalized.toLowerCase();
    if (seen.has(key)) {
      continue;
    }

    seen.add(key);
    output.push(normalized);
  }
  return output;
};

const collectPathParameters = (path: string): string[] => {
  const names: string[] = [];
  const pattern = /\{([^}]+)\}/gu;
  for (const match of path.matchAll(pattern)) {
    const value = match[1];
    if (typeof value === "string" && value.trim().length > 0) {
      names.push(value.trim());
    }
  }
  return names;
};

const collectParameters = (
  parameters: readonly OpenApiParameter[],
  inValue: OpenApiParameter["in"],
): OpenApiParameter[] => {
  const filtered = parameters.filter((parameter) => parameter.in === inValue);
  const unique = new Map<string, OpenApiParameter>();
  for (const parameter of filtered) {
    const key = `${parameter.in}:${parameter.name.toLowerCase()}`;
    if (!unique.has(key)) {
      unique.set(key, parameter);
    }
  }
  return Array.from(unique.values());
};

const getRequestBodyTemplate = (requestBody: OpenApiRequestBody | undefined): string => {
  const content = requestBody?.content;
  if (!content) {
    return "";
  }

  const jsonBody = content["application/json"];
  if (!(jsonBody && typeof jsonBody === "object")) {
    return "";
  }

  const firstExample =
    jsonBody.examples && typeof jsonBody.examples === "object"
      ? Object.values(jsonBody.examples)[0]
      : undefined;
  const candidate = jsonBody.example ?? firstExample?.value;
  return candidate === undefined ? "" : JSON.stringify(candidate, null, 2);
};

const readOpenApiOperation = (
  value: unknown,
  pathParameters: readonly OpenApiParameter[],
): OpenApiOperation | null => {
  if (!isRecord(value)) {
    return null;
  }

  return {
    operationId: typeof value.operationId === "string" ? value.operationId : undefined,
    summary: typeof value.summary === "string" ? value.summary : undefined,
    description: typeof value.description === "string" ? value.description : undefined,
    tags: Array.isArray(value.tags)
      ? value.tags.filter((tag): tag is string => typeof tag === "string")
      : undefined,
    deprecated: typeof value.deprecated === "boolean" ? value.deprecated : undefined,
    parameters: getOperationParameters(value, pathParameters),
    requestBody: readOpenApiRequestBody(value.requestBody),
    responses: readOpenApiResponses(value.responses),
  };
};

const collectEndpointsForPath = (
  path: string,
  pathItem: unknown,
  unknownTagLabel: string,
): ApiEndpoint[] => {
  if (!isRecord(pathItem)) {
    return [];
  }

  const pathParameters = getPathParameters(pathItem);
  const pathParameterNames = dedupeCaseInsensitiveStrings(collectPathParameters(path));
  const endpoints: ApiEndpoint[] = [];

  for (const method of API_DOCS_HTTP_METHODS_ORDER) {
    const operation = readOpenApiOperation(pathItem[method], pathParameters);
    if (!(operation && isApiHttpMethod(method))) {
      continue;
    }

    const endpointTags = dedupeCaseInsensitiveStrings(operation.tags ?? []);
    const groupLabel = endpointTags[0] ?? unknownTagLabel;
    endpoints.push({
      id: `${groupLabel.toLowerCase().replace(/\s+/gu, "-")}-${method}-${normalizeApiDocsPathForId(path)}`,
      path,
      method,
      operation,
      groupLabel,
      pathParameters: pathParameterNames,
      queryParameters: collectParameters(operation.parameters ?? [], "query"),
      requestBodyTemplate: getRequestBodyTemplate(operation.requestBody),
      requestBodyRequired: Boolean(operation.requestBody?.required),
    });
  }

  return endpoints;
};

export const buildApiEndpointGroups = (
  spec: OpenApiSpec | null,
  unknownTagLabel: string,
): ApiEndpointGroup[] => {
  if (!spec?.paths) {
    return [];
  }

  const grouped = new Map<string, ApiEndpoint[]>();
  for (const [path, pathItem] of Object.entries(spec.paths)) {
    for (const endpoint of collectEndpointsForPath(path, pathItem, unknownTagLabel)) {
      const groupEndpoints = grouped.get(endpoint.groupLabel);
      if (groupEndpoints) {
        groupEndpoints.push(endpoint);
        continue;
      }

      grouped.set(endpoint.groupLabel, [endpoint]);
    }
  }

  return Array.from(grouped.entries())
    .sort((left, right) => left[0].localeCompare(right[0]))
    .map(([label, endpoints]) => ({
      id: normalizeApiDocsPathForId(label),
      label,
      endpoints: endpoints.sort((left, right) => {
        const methodOrder =
          API_DOCS_HTTP_METHODS_ORDER.indexOf(left.method) -
          API_DOCS_HTTP_METHODS_ORDER.indexOf(right.method);
        return methodOrder !== 0 ? methodOrder : left.path.localeCompare(right.path);
      }),
    }));
};

export const resolveApiDocsPathWithParameters = (
  endpoint: ApiEndpoint,
  values: Record<string, string>,
): string | null => {
  let outputPath = endpoint.path;
  for (const name of endpoint.pathParameters) {
    const value = values[name]?.trim() ?? "";
    if (value.length === 0) {
      return null;
    }

    outputPath = outputPath.replace(`{${name}}`, encodeURIComponent(value));
  }
  return outputPath;
};

export const buildApiDocsQueryString = (
  queryParameters: readonly OpenApiParameter[],
  values: Record<string, string>,
): string => {
  const urlSearch = new URLSearchParams();
  for (const parameter of queryParameters) {
    const value = values[parameter.name]?.trim();
    if (!value) {
      continue;
    }
    urlSearch.append(parameter.name, value);
  }

  const serialized = urlSearch.toString();
  return serialized.length > 0 ? `?${serialized}` : "";
};

import type {
  OpenApiMediaType,
  OpenApiParameter,
  OpenApiRequestBody,
  OpenApiResponse,
  OpenApiSpec,
} from "~/types/api-docs";

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isOpenApiParameterIn = (value: unknown): value is OpenApiParameter["in"] =>
  value === "path" || value === "query" || value === "header" || value === "cookie";

const toOpenApiMediaExamples = (
  value: unknown,
): Record<string, { value?: unknown }> | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const output: Record<string, { value?: unknown }> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (!isRecord(entry)) {
      continue;
    }

    output[key] = entry.value !== undefined ? { value: entry.value } : {};
  }

  return Object.keys(output).length > 0 ? output : undefined;
};

const toOpenApiMediaType = (value: unknown): OpenApiMediaType | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const mediaType: OpenApiMediaType = {};
  if (value.example !== undefined) {
    mediaType.example = value.example;
  }

  if (isRecord(value.schema)) {
    mediaType.schema = value.schema;
  }

  const examples = toOpenApiMediaExamples(value.examples);
  if (examples) {
    mediaType.examples = examples;
  }

  return Object.keys(mediaType).length > 0 ? mediaType : undefined;
};

const toOpenApiMediaTypeMap = (value: unknown): Record<string, OpenApiMediaType> | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const output: Record<string, OpenApiMediaType> = {};
  for (const [key, entry] of Object.entries(value)) {
    const mediaType = toOpenApiMediaType(entry);
    if (mediaType) {
      output[key] = mediaType;
    }
  }

  return Object.keys(output).length > 0 ? output : undefined;
};

const toOpenApiRequestBody = (value: unknown): OpenApiRequestBody | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const requestBody: OpenApiRequestBody = {
    required: typeof value.required === "boolean" ? value.required : undefined,
  };
  const content = toOpenApiMediaTypeMap(value.content);
  if (content) {
    requestBody.content = content;
  }

  return requestBody.required !== undefined || requestBody.content ? requestBody : undefined;
};

const toOpenApiResponses = (value: unknown): Record<string, OpenApiResponse> | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const output: Record<string, OpenApiResponse> = {};
  for (const [statusCode, entry] of Object.entries(value)) {
    if (!isRecord(entry)) {
      continue;
    }

    const response: OpenApiResponse = {
      description: typeof entry.description === "string" ? entry.description : undefined,
    };
    const content = toOpenApiMediaTypeMap(entry.content);
    if (content) {
      response.content = content;
    }
    output[statusCode] = response;
  }

  return Object.keys(output).length > 0 ? output : undefined;
};

const toOpenApiPathMap = (value: unknown): Record<string, Record<string, unknown>> => {
  if (!isRecord(value)) {
    return {};
  }

  const output: Record<string, Record<string, unknown>> = {};
  for (const [path, entry] of Object.entries(value)) {
    if (isRecord(entry)) {
      output[path] = entry;
    }
  }

  return output;
};

export const readOpenApiSpec = (value: unknown): OpenApiSpec | null => {
  if (!isRecord(value)) {
    return null;
  }

  const infoRaw = isRecord(value.info) ? value.info : undefined;
  return {
    openapi: typeof value.openapi === "string" ? value.openapi : undefined,
    info: {
      title: typeof infoRaw?.title === "string" ? infoRaw.title : undefined,
      description: typeof infoRaw?.description === "string" ? infoRaw.description : undefined,
      version: typeof infoRaw?.version === "string" ? infoRaw.version : undefined,
    },
    paths: toOpenApiPathMap(value.paths),
  };
};

const dedupeParameters = (parameters: readonly OpenApiParameter[]): OpenApiParameter[] => {
  const unique = new Map<string, OpenApiParameter>();
  for (const parameter of parameters) {
    const key = `${parameter.in}:${parameter.name.toLowerCase()}`;
    if (!unique.has(key)) {
      unique.set(key, {
        ...parameter,
        name: parameter.name.trim(),
      });
    }
  }

  return Array.from(unique.values()).filter((parameter) => parameter.name.length > 0);
};

export const getPathParameters = (pathItem: Record<string, unknown>): OpenApiParameter[] => {
  const rawParameters = Array.isArray(pathItem.parameters) ? pathItem.parameters : [];
  const normalized = rawParameters
    .filter((parameter): parameter is OpenApiParameter => {
      if (!isRecord(parameter)) {
        return false;
      }

      if (typeof parameter.name !== "string") {
        return false;
      }

      return isOpenApiParameterIn(parameter.in);
    })
    .map((parameter) => ({
      ...parameter,
      name: parameter.name.trim(),
    }));

  return dedupeParameters(normalized);
};

export const getOperationParameters = (
  value: unknown,
  pathParameters: readonly OpenApiParameter[],
): OpenApiParameter[] => {
  if (!isRecord(value)) {
    return [];
  }

  const parameters = Array.isArray(value.parameters) ? value.parameters : [];
  const operationParameters = parameters.filter((parameter): parameter is OpenApiParameter => {
    if (!isRecord(parameter)) {
      return false;
    }

    if (typeof parameter.name !== "string") {
      return false;
    }

    return isOpenApiParameterIn(parameter.in);
  });

  return dedupeParameters([...pathParameters, ...operationParameters]);
};

export const readOpenApiRequestBody = (value: unknown): OpenApiRequestBody | undefined =>
  toOpenApiRequestBody(value);

export const readOpenApiResponses = (value: unknown): Record<string, OpenApiResponse> | undefined =>
  toOpenApiResponses(value);

import {
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_TOO_MANY_REQUESTS,
  HTTP_STATUS_UNAUTHORIZED,
} from "@bao/shared/constants/http";
import type { ApiDocsUiState, ApiHttpMethod } from "~/types/api-docs";

export const API_DOCS_HTTP_METHODS_ORDER = [
  "get",
  "post",
  "put",
  "patch",
  "delete",
  "head",
  "options",
  "trace",
] as const satisfies readonly ApiHttpMethod[];

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

export const isApiHttpMethod = (value: string): value is ApiHttpMethod =>
  API_DOCS_HTTP_METHODS_ORDER.some((method) => method === value);

export const toErrorStatusCode = (error: unknown): number | null => {
  if (!isRecord(error)) {
    return null;
  }

  const status = error.status;
  if (typeof status === "number") {
    return status;
  }

  const statusCode = error.statusCode;
  return typeof statusCode === "number" ? statusCode : null;
};

export const toApiDocsUiStateFromStatusCode = (statusCode: number | null): ApiDocsUiState => {
  if (statusCode === HTTP_STATUS_UNAUTHORIZED) {
    return "unauthorized";
  }

  if (
    statusCode === null ||
    statusCode >= HTTP_STATUS_INTERNAL_SERVER_ERROR ||
    statusCode === HTTP_STATUS_TOO_MANY_REQUESTS
  ) {
    return "errorRetryable";
  }

  return "errorNonRetryable";
};

export const normalizeApiDocsPathForId = (path: string): string =>
  path
    .toLowerCase()
    .replace(/[^a-z0-9]+/giu, "-")
    .replace(/(^-|-$)/gu, "") || "root";

export const getApiDocsParameterValueDefault = (value: unknown): string => {
  if (typeof value === "string") {
    return value;
  }

  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }

  return "";
};

import { describe, expect, it } from "vitest";
import { buildApiProxyWildcardTarget, normalizeApiProxyTarget } from "./api-proxy-target";

describe("api proxy target normalization", () => {
  it("preserves the api suffix for absolute proxy targets", () => {
    expect(normalizeApiProxyTarget("http://localhost:3002/api")).toBe("http://localhost:3002/api");
    expect(normalizeApiProxyTarget("http://localhost:3002/api/")).toBe("http://localhost:3002/api");
  });

  it("appends the api suffix when the target path does not include it", () => {
    expect(normalizeApiProxyTarget("http://localhost:3002")).toBe("http://localhost:3002/api");
    expect(normalizeApiProxyTarget("http://localhost:3002/")).toBe("http://localhost:3002/api");
    expect(normalizeApiProxyTarget("https://example.test/backend")).toBe(
      "https://example.test/backend/api",
    );
  });
});

describe("api proxy wildcard target", () => {
  it("builds wildcard targets without duplicating the api prefix", () => {
    expect(buildApiProxyWildcardTarget("http://localhost:3002")).toBe(
      "http://localhost:3002/api/**",
    );
    expect(buildApiProxyWildcardTarget("http://localhost:3002/api")).toBe(
      "http://localhost:3002/api/**",
    );
  });
});

import { API_ENDPOINT_PREFIX } from "@bao/shared/constants/endpoints";

const ABSOLUTE_HTTP_URL_PATTERN = /^https?:\/\//iu;
const TRAILING_SLASH_PATTERN = /\/$/u;
const PROXY_WILDCARD_SUFFIX = "/**";

const trimTrailingSlash = (value: string): string => value.replace(TRAILING_SLASH_PATTERN, "");

export function normalizeApiProxyTarget(target: string): string | undefined {
  const trimmedTarget = target.trim();
  if (!(ABSOLUTE_HTTP_URL_PATTERN.test(trimmedTarget) && URL.canParse(trimmedTarget))) {
    return;
  }

  const resolvedTarget = new URL(trimmedTarget);
  const normalizedPath = trimTrailingSlash(resolvedTarget.pathname);
  let pathnameWithApiPrefix: string;
  if (normalizedPath.length === 0 || normalizedPath === "/") {
    pathnameWithApiPrefix = API_ENDPOINT_PREFIX;
  } else if (normalizedPath.endsWith(API_ENDPOINT_PREFIX)) {
    pathnameWithApiPrefix = normalizedPath;
  } else {
    pathnameWithApiPrefix = `${normalizedPath}${API_ENDPOINT_PREFIX}`;
  }

  resolvedTarget.pathname = pathnameWithApiPrefix;
  resolvedTarget.search = "";
  resolvedTarget.hash = "";
  return trimTrailingSlash(resolvedTarget.toString());
}

export function buildApiProxyWildcardTarget(target: string): string | undefined {
  const normalizedTarget = normalizeApiProxyTarget(target);
  return normalizedTarget ? `${normalizedTarget}${PROXY_WILDCARD_SUFFIX}` : undefined;
}

