  if (capability.category === "job_apply") {
    return {
      to: APP_ROUTES.automationJobApply,
      label: t("automation.hub.audit.actions.openJobApply"),
      ariaLabel: t("automation.hub.audit.actions.openJobApplyAria"),
    };
