import type { AvailableLocale } from "~/constants/i18n-catalog";
import { I18N_MESSAGE_CATALOG } from "~/constants/i18n-catalog";

type MessageNode = Record<string, unknown>;

function cloneMessageNode<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

function setByPath(target: MessageNode, path: string, value: string): void {
  const segments = path
    .split(".")
    .map((segment) => segment.trim())
    .filter((segment) => segment.length > 0);

  if (segments.length === 0) {
    return;
  }

  let cursor: MessageNode = target;
  for (const segment of segments.slice(0, -1)) {
    const next = cursor[segment];
    if (typeof next !== "object" || next === null || Array.isArray(next)) {
      cursor[segment] = {};
    }
    cursor = next as Record<string, unknown>;
  }

  const leafKey = segments[segments.length - 1];
  if (leafKey) {
    cursor[leafKey] = value;
  }
}

/**
 * Builds a locale catalog with brand copy overrides applied to dot-delimited message keys.
 *
 * @param locale Active locale key.
 * @param overrides White-label copy overrides keyed by locale-message path.
 * @returns Localized message tree with overrides applied.
 */
export function buildBrandedLocaleMessages(
  locale: AvailableLocale,
  overrides: Record<string, string>,
): MessageNode {
  const baseMessages: MessageNode = cloneMessageNode(I18N_MESSAGE_CATALOG[locale]);
  for (const [messageKey, messageValue] of Object.entries(overrides)) {
    setByPath(baseMessages, messageKey, messageValue);
  }
  return baseMessages;
}

import type { ChatMessage } from "@bao/shared/types/ai";
import { generateId } from "@bao/shared/utils/validation";

/** Render-ready chat row with a stable key and normalized payload. */
export interface ChatMessageRenderRow {
  message: ChatMessage;
  key: string;
}

/** Timestamp format used across chat bubbles. */
const CHAT_MESSAGE_TIME_OPTIONS: Intl.DateTimeFormatOptions = {
  hour: "numeric",
  minute: "2-digit",
};

/** Stable IDs for streaming placeholders across chat surfaces. */
export const AI_CHAT_STREAMING_MESSAGE_IDS = {
  chatPage: "ai-chat-page-streaming",
  floatingWidget: "floating-chat-streaming",
} as const;

type ChatStreamingContext = keyof typeof AI_CHAT_STREAMING_MESSAGE_IDS;

/** Locale fallback when the active locale is unavailable. */
function resolveLocaleFallback(locale?: string): string {
  if (locale && locale.trim().length > 0) {
    return locale;
  }

  return Intl.DateTimeFormat().resolvedOptions().locale || "en-US";
}

/** Resolve a chat message bubble from a raw role and content with a stable ID. */
export function createChatMessage(params: {
  role: ChatMessage["role"];
  content: string;
  timestamp?: string;
  sessionId?: string;
  id?: string;
  provider?: string;
  model?: string;
  confidence?: number;
}): ChatMessage {
  return {
    id: params.id ?? generateId(),
    role: params.role,
    content: params.content,
    timestamp: params.timestamp ?? new Date().toISOString(),
    ...(params.sessionId ? { sessionId: params.sessionId } : {}),
    ...(params.provider ? { provider: params.provider } : {}),
    ...(params.model ? { model: params.model } : {}),
    ...(params.confidence !== undefined ? { confidence: params.confidence } : {}),
  };
}

/** Create a stable streaming placeholder bubble for a given chat context. */
export function createStreamingAssistantMessage(
  context: ChatStreamingContext,
  content = "",
): ChatMessage {
  return createChatMessage({
    role: "assistant",
    id: AI_CHAT_STREAMING_MESSAGE_IDS[context],
    content,
  });
}

/**
 * Build chat rows with stable keys for deterministic rendering and no drift during
 * streaming or rerender cycles.
 */
export function buildChatMessageRenderRows(
  messages: readonly ChatMessage[],
): ChatMessageRenderRow[] {
  return messages.map((message, index) => ({
    message,
    key: message.id ?? `${message.role}-${message.timestamp ?? "no-timestamp"}-${index}`,
  }));
}

/**
 * Resolve the index of the latest assistant message in a message list.
 */
export function resolveLatestAssistantMessageIndex(messages: readonly ChatMessage[]): number {
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    if (messages[index]?.role === "assistant") {
      return index;
    }
  }

  return -1;
}

/**
 * Format a chat timestamp for the active locale and return an empty string for invalid values.
 */
export function formatChatTimestamp(timestamp: string | undefined, locale?: string): string {
  if (!timestamp) {
    return "";
  }

  const parsedDate = new Date(timestamp);
  if (Number.isNaN(parsedDate.getTime())) {
    return "";
  }

  return parsedDate.toLocaleTimeString(resolveLocaleFallback(locale), CHAT_MESSAGE_TIME_OPTIONS);
}

import { ref } from "vue";

type ClientLogLevel = "debug" | "info" | "warn" | "error";

type ClientLogger = {
  debug: (...values: unknown[]) => void;
  info: (...values: unknown[]) => void;
  warn: (...values: unknown[]) => void;
  error: (...values: unknown[]) => void;
};

const debugLogEnabled = ref(true);

/**
 * Create a client-side logger that avoids direct console output.
 */
export function createClientLogger(scope: string): ClientLogger {
  const emit = (level: ClientLogLevel, values: unknown[]) => {
    if (!(import.meta.client && debugLogEnabled.value)) {
      return;
    }

    window.dispatchEvent(
      new CustomEvent("baobuildbuddy:diagnostic", {
        detail: {
          scope,
          level,
          values,
          timestamp: Date.now(),
        },
      }),
    );
  };

  return {
    debug: (...values: unknown[]) => {
      emit("debug", values);
    },
    info: (...values: unknown[]) => {
      emit("info", values);
    },
    warn: (...values: unknown[]) => {
      emit("warn", values);
    },
    error: (...values: unknown[]) => {
      emit("error", values);
    },
  };
}

import type { CoverLetterData } from "@bao/shared/types/cover-letter";

const COVER_LETTER_PRIMARY_SECTION_KEYS = [
  "opening",
  "introduction",
  "body",
  "closing",
  "conclusion",
  "signature",
] as const;
const SECTION_SPLIT_PATTERN = /\n{2,}/u;

/**
 * Converts structured cover-letter content into readable multiline text for previews/editing.
 *
 * @param content Structured cover-letter content map.
 * @returns Concatenated plain-text content with paragraph spacing.
 */
export function coverLetterContentToPlainText(
  content: CoverLetterData["content"] | undefined,
): string {
  if (!content) return "";

  const sectionKeys = new Set<string>();
  const orderedSections: string[] = [];

  for (const key of COVER_LETTER_PRIMARY_SECTION_KEYS) {
    sectionKeys.add(key);
    const value = content[key];
    if (typeof value !== "string") continue;
    const trimmed = value.trim();
    if (trimmed.length > 0) {
      orderedSections.push(trimmed);
    }
  }

  const additionalSections = Object.entries(content).flatMap(([key, value]) => {
    if (sectionKeys.has(key) || typeof value !== "string") {
      return [];
    }

    const trimmedValue = value.trim();
    return trimmedValue.length > 0 ? [trimmedValue] : [];
  });

  if (additionalSections.length > 0) {
    orderedSections.push(...additionalSections);
  }

  return orderedSections.join("\n\n");
}

/**
 * Converts user-edited plain text into canonical structured cover-letter content.
 *
 * @param value Editable plain-text cover-letter input.
 * @returns Structured cover-letter content suitable for API payloads.
 */
export function plainTextToCoverLetterContent(value: string): CoverLetterData["content"] {
  const trimmedValue = value.trim();
  if (trimmedValue.length === 0) return {};

  const sections = trimmedValue
    .split(SECTION_SPLIT_PATTERN)
    .map((section) => section.trim())
    .filter((section) => section.length > 0);

  if (sections.length === 1) {
    return {
      body: sections[0],
    };
  }

  if (sections.length === 2) {
    return {
      introduction: sections[0],
      body: sections[1],
    };
  }

  return {
    introduction: sections[0],
    body: sections.slice(1, -1).join("\n\n"),
    conclusion: sections[sections.length - 1],
  };
}

