      resolveQuickActionTarget(APP_ROUTES.gamification, `${APP_ROUTES.studios}/riot-games`, {}),
    ).toEqual({ path: APP_ROUTES.gamification, query: {} });
  });

  it("emits no query when the source page has no entity", () => {
    expect(resolveQuickActionTarget(APP_ROUTES.aiChat, APP_ROUTES.dashboard, {}).query).toEqual({});
  });
});

import { AI_CHAT_ROUTE_QUERY_KEYS } from "@bao/shared/constants/ai-chat";
import { APP_ROUTES } from "@bao/shared/constants/routes";

/**
 * The floating quick actions used to navigate to fixed paths, which dropped
 * whatever the user was looking at. Opening AI Chat from a studio profile landed
 * on a chat with no studio, and "Customize Resume" from a job posting lost the
 * job — so the AI had no page context to tailor against.
 *
 * These helpers read the entity out of the current route and carry it into the
 * target as route query, using the same query keys the AI chat context builder
 * already reads (`AI_CHAT_ROUTE_QUERY_KEYS`). Pure functions so the mapping is
 * unit-testable without mounting the shell.
 */

export interface QuickActionRouteTarget {
  readonly path: string;
  readonly query: Readonly<Record<string, string>>;
}

/** The entity a page is "about", derived from its route. */
export interface QuickActionSourceEntity {
  readonly studioId: string | null;
  readonly jobId: string | null;
  readonly resumeId: string | null;
}

const trimmedOrNull = (value: string | undefined): string | null => {
  const trimmed = (value ?? "").trim();
  return trimmed.length > 0 ? trimmed : null;
};

/** Matches a studio detail path only — not the studio index or analytics routes. */
const resolveStudioIdFromPath = (path: string): string | null => {
  if (!path.startsWith(`${APP_ROUTES.studios}/`)) {
    return null;
  }
  const segment = path.slice(`${APP_ROUTES.studios}/`.length).split("/")[0];
  const studioId = trimmedOrNull(segment);
  if (studioId === null || `${APP_ROUTES.studios}/${studioId}` === APP_ROUTES.studiosAnalytics) {
    return null;
  }
  return studioId;
};

const resolveJobIdFromPath = (path: string): string | null => {
  if (!path.startsWith(`${APP_ROUTES.jobs}/`)) {
    return null;
  }
  return trimmedOrNull(path.slice(`${APP_ROUTES.jobs}/`.length).split("/")[0]);
};

export const resolveQuickActionSourceEntity = (
  path: string,
  query: Readonly<Record<string, string>>,
): QuickActionSourceEntity => ({
  studioId:
    resolveStudioIdFromPath(path) ?? trimmedOrNull(query[AI_CHAT_ROUTE_QUERY_KEYS.studioId]),
  jobId: resolveJobIdFromPath(path) ?? trimmedOrNull(query[AI_CHAT_ROUTE_QUERY_KEYS.jobId]),
  resumeId: trimmedOrNull(query[AI_CHAT_ROUTE_QUERY_KEYS.resumeId]),
});

/**
 * Which entities each destination can act on.
 *
 * This map lists ONLY destinations that actually read these keys off the route
 * today: the AI chat context builder (`ai-context.ts`), the interview hub
 * bootstrap (`interview-hub-bootstrap.ts`), and the studio index
 * (`useStudiosIndexPage.ts`). Forwarding to a page that ignores the query would
 * produce a URL that advertises context the page silently drops — worse than not
 * forwarding, because it looks wired. Add a destination here only together with
 * the code that consumes it.
 */
const FORWARDED_ENTITY_KEYS_BY_PATH: Readonly<
  Record<string, readonly (keyof QuickActionSourceEntity)[]>
> = {
  [APP_ROUTES.aiChat]: ["studioId", "jobId", "resumeId"],
  [APP_ROUTES.interview]: ["studioId", "jobId"],
  [APP_ROUTES.studios]: ["studioId"],
  // `cover-letter-list-page-actions.ts:buildGeneratePayload` reads both keys and
  // sends them to the generation route, which loads the records for the prompt.
  [APP_ROUTES.coverLetter]: ["studioId", "jobId"],
};

const QUERY_KEY_BY_ENTITY: Readonly<Record<keyof QuickActionSourceEntity, string>> = {
  studioId: AI_CHAT_ROUTE_QUERY_KEYS.studioId,
  jobId: AI_CHAT_ROUTE_QUERY_KEYS.jobId,
  resumeId: AI_CHAT_ROUTE_QUERY_KEYS.resumeId,
};

/**
 * Builds the destination for a quick action, carrying the current page's entity
 * when the destination can use it. Navigating to the page you are already on
 * yields no query so the action stays idempotent.
 */
export const resolveQuickActionTarget = (
  actionPath: string,
  currentPath: string,
  currentQuery: Readonly<Record<string, string>>,
): QuickActionRouteTarget => {
  const forwardedKeys = FORWARDED_ENTITY_KEYS_BY_PATH[actionPath];
  if (!forwardedKeys || actionPath === currentPath) {
    return { path: actionPath, query: {} };
  }

  const entity = resolveQuickActionSourceEntity(currentPath, currentQuery);
  const query: Record<string, string> = {};
  for (const entityKey of forwardedKeys) {
    const entityId = entity[entityKey];
    if (entityId !== null) {
      query[QUERY_KEY_BY_ENTITY[entityKey]] = entityId;
    }
  }
  return { path: actionPath, query };
};

/**
 * Canonical route query decoding — one implementation for string/array query values.
 * All pages/composables that read `route.query[...]` must use these helpers (SSOT).
 */
import type { LocationQueryValue } from "vue-router";

export type RouteQueryValue =
  | LocationQueryValue
  | LocationQueryValue[]
  | readonly LocationQueryValue[]
  | undefined;

/** Decode a single query param to a string (first array element when multi). */
export function queryValueToString(value: RouteQueryValue): string {
  if (Array.isArray(value)) {
    const [firstValue] = value;
    return typeof firstValue === "string" ? firstValue : "";
  }
  return typeof value === "string" ? value : "";
}

/** Decode a single query param to string | null when empty/missing. */
export function queryValueToOptionalString(value: RouteQueryValue): string | null {
  const decoded = queryValueToString(value);
  return decoded.length > 0 ? decoded : null;
}

/**
 * Resolve a section query against an allowlist, falling back to the default.
 * Used by Settings / Automation hub / Scraper section rails.
 */
export function resolveRouteSectionId<T extends string>(
  value: RouteQueryValue,
  isValid: (candidate: string) => candidate is T,
  defaultSection: T,
): T {
  const candidate = queryValueToOptionalString(value);
  if (candidate && isValid(candidate)) {
    return candidate;
  }
  return defaultSection;
}

import { describe, expect, it } from "vitest";
import {
  isFailedScrapeRun,
  readScrapeOutputCounts,
  readScrapeOutputErrors,
} from "./scrape-run-output";

describe("scrape-run-output", () => {
  it("reads aggregator errors and counts", () => {
    const output = {
      target: "jobs_grackle",
      scraped: 0,
      upserted: 0,
      errors: ["Script exited 137: "],
    };
    expect(readScrapeOutputErrors(output)).toEqual(["Script exited 137:"]);
    expect(readScrapeOutputCounts(output)).toEqual({ scraped: 0, upserted: 0 });
    expect(isFailedScrapeRun({ output, exitCode: 0 })).toBe(true);
  });

  it("treats non-zero exit as failure", () => {
    expect(isFailedScrapeRun({ output: { scraped: 5 }, exitCode: 137 })).toBe(true);
  });

  it("allows successful scrapes with no errors", () => {
    expect(
      isFailedScrapeRun({
        output: { scraped: 12, upserted: 12, errors: [] },
        exitCode: 0,
      }),
    ).toBe(false);
  });
});

import { isRecord } from "@bao/shared/utils/type-guards";

const readNonEmptyString = (value: unknown): string | null =>
  typeof value === "string" && value.trim().length > 0 ? value.trim() : null;

/**
 * Reads scrape pipeline error strings from an automation run output payload.
 * Supports both RPA `error` string fields and scrape aggregator `errors[]`.
 */
export function readScrapeOutputErrors(output: unknown): readonly string[] {
  if (!isRecord(output)) {
    return [];
  }

  const collected: string[] = [];
  const singular = readNonEmptyString(output.error);
  if (singular) {
    collected.push(singular);
  }

  if (Array.isArray(output.errors)) {
    for (const entry of output.errors) {
      const message = readNonEmptyString(entry);
      if (message) {
        collected.push(message);
      }
    }
  }

  return collected;
}

/**
 * Reads scraped/upserted counts when present on scrape output.
 */
export function readScrapeOutputCounts(output: unknown): {
  readonly scraped: number | null;
  readonly upserted: number | null;
} {
  if (!isRecord(output)) {
    return { scraped: null, upserted: null };
  }
  return {
    scraped: typeof output.scraped === "number" ? output.scraped : null,
    upserted: typeof output.upserted === "number" ? output.upserted : null,
  };
}

/**
 * True when the completed scrape should surface as an error in the hub UI:
 * non-zero exit, aborted/timed out, or output errors with zero scraped rows.
 */
export function isFailedScrapeRun(input: {
  readonly aborted?: boolean | null;
  readonly exitCode?: number | null;
  readonly output: unknown;
  readonly timedOut?: boolean | null;
}): boolean {
  if (input.aborted === true || input.timedOut === true) {
    return true;
  }
  if (typeof input.exitCode === "number" && input.exitCode !== 0) {
    return true;
  }
  const errors = readScrapeOutputErrors(input.output);
  if (errors.length === 0) {
    return false;
  }
  const counts = readScrapeOutputCounts(input.output);
  if (counts.scraped === null && counts.upserted === null) {
    return true;
  }
  return (counts.scraped ?? 0) === 0 && (counts.upserted ?? 0) === 0;
}

