  }));

export const buildOutputDirectory = async (payload: {
  outputDir?: string | null;
  runId: string;
}): Promise<string | null> => {
  const outputDir = payload.outputDir?.trim();
  if (outputDir) {
    const directoryResult = await settle(mkdir(outputDir, { recursive: true }));
    return directoryResult.status === "fulfilled" ? outputDir : null;
  }

  const fallbackDirectory = join(process.cwd(), "tmp", "automation", payload.runId);
  const fallbackResult = await settle(mkdir(fallbackDirectory, { recursive: true }));
  return fallbackResult.status === "fulfilled" ? fallbackDirectory : null;
};

const resolveResumeArtifactPath = async (
  outputDir: string,
  resume: Record<string, unknown>,
  resumeFilePath?: string,
): Promise<string | null> => {
  const providedPath = resumeFilePath?.trim();
  if (providedPath) {
    const providedFile = Bun.file(providedPath);
    if (await providedFile.exists()) {
      return providedPath;
    }
  }

  const artifactPath = join(outputDir, "resume.txt");
  const writeResult = await settle(Bun.write(artifactPath, serializeResumeArtifact(resume)));
  return writeResult.status === "fulfilled" ? artifactPath : null;
};

export const uploadResumeArtifact = async ({
  page,
  selectors,
  outputDir,
  resume,
  resumeFilePath,
}: UploadResumeArtifactOptions): Promise<boolean> => {
  const artifactPath = await resolveResumeArtifactPath(outputDir, resume, resumeFilePath);
  if (!artifactPath) {
    return false;
  }

  const uploadResult = await runOnFirstMatchingLocator(
    page,
    selectors,
    async (locator: Locator) => {
      const matchingResult = await settle(locator.setInputFiles(artifactPath));
      return matchingResult.status === "fulfilled" ? true : null;
    },
  );
  return uploadResult ?? false;
};

export const captureScreenshot = async ({
  page,
  outputDir,
  autoSaveScreenshots,
  screenshots,
  steps,
  label,
}: CaptureScreenshotOptions): Promise<void> => {
  if (!autoSaveScreenshots) {
    return;
  }

  const screenshotPath = join(
    outputDir,
    `${RUN_SCREENSHOT_PREFIX}-${String(screenshots.length + 1).padStart(2, "0")}.png`,
  );
  const screenshotResult = await settle(
    page.screenshot({
      path: screenshotPath,
      fullPage: false,
    }),
  );

  if (screenshotResult.status === "fulfilled") {
    screenshots.push(screenshotPath);
    addStep(steps, "screenshot", "ok", label);
    return;
  }

  addStep(steps, "screenshot", "error", label);
};

import type { JobApplyScriptEnvelope } from "@bao/shared/schemas/automation-scripts.schema";
import type { Page } from "playwright";
import type { AutomationBrowserSession } from "../runtime/browser";
import type { ProtocolEmitter } from "../runtime/protocol";
import type { JobApplySelectorBundle, JobApplyStrategy } from "./strategy-registry";

export type StepStatus = "ok" | "error" | "skipped";

export type StepRecord = {
  action: string;
  status: StepStatus;
  message?: string;
};

export type ResumeCandidateFields = {
  fullName: string;
  email: string;
  phone: string;
};

export type JobApplyExecutionState = {
  emitter: ProtocolEmitter;
  payload: JobApplyScriptEnvelope;
  outputDir: string;
  session: AutomationBrowserSession;
  steps: StepRecord[];
  screenshots: string[];
};

export type CaptureScreenshotOptions = {
  page: Page;
  outputDir: string;
  autoSaveScreenshots: boolean;
  screenshots: string[];
  steps: StepRecord[];
  label: string;
};

export type FillTextFieldStepOptions = {
  state: JobApplyExecutionState;
  strategy: JobApplyStrategy;
  selectorKey: keyof JobApplySelectorBundle;
  action: string;
  step: number;
  value: string;
  emptyMessage: string;
  missingMessage: string;
};

export type SelectorMapInput = JobApplyScriptEnvelope["selectorMap"];

export type LocatorControlDescriptor = {
  tagName: string;
  inputType: string;
  value: string;
  label: string;
  text: string;
  ariaLabel: string;
  placeholder: string;
};

export type UploadResumeArtifactOptions = {
  page: Page;
  selectors: readonly string[];
  outputDir: string;
  resume: Record<string, unknown>;
  resumeFilePath?: string;
};

export const BOOLEAN_TRUE_ANSWERS = new Set(["1", "checked", "on", "true", "yes"]);
export const BOOLEAN_FALSE_ANSWERS = new Set(["0", "false", "no", "off", "unchecked"]);

export const PLAYWRIGHT_ACTION_TIMEOUT_MS = 5_000;
export const PLAYWRIGHT_RETRY_MAX_ATTEMPTS = 3;
export const PLAYWRIGHT_RETRY_INITIAL_DELAY_MS = 500;

export const RUN_SCREENSHOT_PREFIX = "step";

export const JOB_APPLY_STEP_INDEX = {
  initBrowser: 1,
  followApplyLink: 2,
  detectFields: 3,
  fillName: 4,
  fillEmail: 5,
  fillPhone: 6,
  uploadResume: 7,
  fillCoverLetter: 8,
  fillCustomFields: 9,
  submit: 10,
  verifySubmission: 11,
} as const;

import {
  addStep,
  captureScreenshot,
  collectResumeCandidateFields,
  flattenJsonStrings,
  uploadResumeArtifact,
} from "./runtime-artifacts";
import type {
  FillTextFieldStepOptions,
  JobApplyExecutionState,
  ResumeCandidateFields,
} from "./runtime-contracts";
import { JOB_APPLY_STEP_INDEX } from "./runtime-contracts";
import {
  fillFirstMatchingAnswer,
  fillFirstMatchingField,
  getCustomFieldSelectorList,
} from "./runtime-locators";
import { getStrategySelectorList } from "./runtime-selector-map";
import type { JobApplyStrategy } from "./strategy-registry";
import { JOB_APPLY_TOTAL_STEPS } from "./strategy-registry";

const emitProgress = (state: JobApplyExecutionState, action: string, step: number): void => {
  state.emitter.emitProgress({
    action,
    status: "running",
    step,
    totalSteps: JOB_APPLY_TOTAL_STEPS,
  });
};

const fillNamedFields = async (
  state: JobApplyExecutionState,
  strategy: JobApplyStrategy,
  resumeFields: ResumeCandidateFields,
): Promise<void> => {
  emitProgress(state, "fill_name", JOB_APPLY_STEP_INDEX.fillName);
  const fullNameParts = resumeFields.fullName.split(" ").filter((part) => part.trim().length > 0);
  const primaryName = fullNameParts[0] ?? resumeFields.fullName;
  const nameFilled =
    strategy.id === "greenhouse"
      ? await fillFirstMatchingField(
          state.session.page,
          getStrategySelectorList(strategy, state.payload.selectorMap, "firstName"),
          primaryName,
        )
      : await fillFirstMatchingField(
          state.session.page,
          getStrategySelectorList(strategy, state.payload.selectorMap, "fullName"),
          resumeFields.fullName,
        );

  const lastName = fullNameParts.slice(1).join(" ").trim();
  if (strategy.id === "greenhouse" && lastName.length > 0) {
    await fillFirstMatchingField(
      state.session.page,
      getStrategySelectorList(strategy, state.payload.selectorMap, "lastName"),
      lastName,
    );
  }

  addStep(
    state.steps,
    "fill_name",
    nameFilled ? "ok" : "error",
    nameFilled ? resumeFields.fullName : "Name field not found",
  );
};

const fillTextFieldStep = async ({
  state,
  strategy,
  selectorKey,
  action,
  step,
  value,
  emptyMessage,
  missingMessage,
}: FillTextFieldStepOptions): Promise<void> => {
  emitProgress(state, action, step);
  const filled =
    value.trim().length > 0
      ? await fillFirstMatchingField(
          state.session.page,
          getStrategySelectorList(strategy, state.payload.selectorMap, selectorKey),
          value,
        )
      : false;

  const isEmpty = value.trim().length === 0;
  let detail: string | undefined;
  if (isEmpty) {
    detail = emptyMessage;
  } else if (!filled) {
    detail = missingMessage;
  }

  addStep(state.steps, action, isEmpty || filled ? "ok" : "error", detail);
};

const uploadResumeStep = async (
  state: JobApplyExecutionState,
  strategy: JobApplyStrategy,
): Promise<void> => {
  emitProgress(state, "upload_resume", JOB_APPLY_STEP_INDEX.uploadResume);
  const resumeUploaded = await uploadResumeArtifact({
    page: state.session.page,
    selectors: getStrategySelectorList(strategy, state.payload.selectorMap, "resume"),
    outputDir: state.outputDir,
    resume: state.payload.resume,
    resumeFilePath: state.payload.resumeFilePath,
  });
  addStep(
    state.steps,
    "upload_resume",
    resumeUploaded ? "ok" : "error",
    resumeUploaded ? undefined : "Resume upload field not found",
  );
};

const fillCustomFieldsRecursively = async (
  state: JobApplyExecutionState,
  entries: readonly [string, string][],
  index = 0,
): Promise<void> => {
  const entry = entries[index];
  if (!entry) {
    return;
  }

  const [key, value] = entry;
  const customFieldFilled = await fillFirstMatchingAnswer(
    state.session.page,
    [...(state.payload.selectorMap[key] ?? []), ...getCustomFieldSelectorList(key)],
    value,
  );
  addStep(
    state.steps,
    `fill_${key}`,
    customFieldFilled ? "ok" : "error",
    customFieldFilled ? undefined : `Field ${key} not found`,
  );
  return fillCustomFieldsRecursively(state, entries, index + 1);
};

export const fillPrimaryFields = async (
  state: JobApplyExecutionState,
  strategy: JobApplyStrategy,
): Promise<void> => {
  const resumeFields = collectResumeCandidateFields(state.payload.resume);
  const coverLetterText = flattenJsonStrings(state.payload.coverLetter?.content)
    .join("\n\n")
    .trim();

  await fillNamedFields(state, strategy, resumeFields);
  await fillTextFieldStep({
    state,
    strategy,
    selectorKey: "email",
    action: "fill_email",
    step: JOB_APPLY_STEP_INDEX.fillEmail,
    value: resumeFields.email,
    emptyMessage: "No email supplied",
    missingMessage: "Email field not found",
  });
  await fillTextFieldStep({
    state,
    strategy,
    selectorKey: "phone",
    action: "fill_phone",
    step: JOB_APPLY_STEP_INDEX.fillPhone,
    value: resumeFields.phone,
    emptyMessage: "No phone supplied",
    missingMessage: "Phone field not found",
  });
  await uploadResumeStep(state, strategy);
  await fillTextFieldStep({
    state,
    strategy,
    selectorKey: "coverLetter",
    action: "fill_cover_letter",
    step: JOB_APPLY_STEP_INDEX.fillCoverLetter,
    value: coverLetterText,
    emptyMessage: "No cover letter content supplied",
    missingMessage: "Cover-letter field not found",
  });
};

export const fillCustomFieldsStep = async (state: JobApplyExecutionState): Promise<void> => {
  emitProgress(state, "fill_custom_fields", JOB_APPLY_STEP_INDEX.fillCustomFields);
  await fillCustomFieldsRecursively(state, Object.entries(state.payload.customAnswers));
  await captureScreenshot({
    page: state.session.page,
    outputDir: state.outputDir,
    autoSaveScreenshots: state.payload.settings.autoSaveScreenshots,
    screenshots: state.screenshots,
    steps: state.steps,
    label: "Filled form fields",
  });
};

import { describe, expect, test } from "bun:test";
import type { Page } from "playwright";
import {
  detectAndFollowHostedApplyPage,
  isHostedApplyErrorUrl,
  resolveJobApplyRunOutcome,
} from "./runtime-page-setup";

const buildPage = (input: {
  url: string;
  href?: string | null;
  count?: number;
  gotoRejects?: boolean;
}): Page => {
  const count = input.count ?? (input.href ? 1 : 0);
  const locator = {
    first: () => locator,
    count: () => Promise.resolve(count),
    getAttribute: () => Promise.resolve(input.href ?? null),
  };
  return {
    url: () => input.url,
    locator: () => locator,
    goto: () => {
      if (input.gotoRejects) {
        return Promise.reject(new Error("nav failed"));
      }
      return Promise.resolve(null);
    },
    waitForLoadState: () => Promise.resolve(undefined),
  } as unknown as Page;
};

describe("detectAndFollowHostedApplyPage", () => {
  test("already_hosted when URL is Greenhouse/Lever", async () => {
    const outcome = await detectAndFollowHostedApplyPage(
      buildPage({ url: "https://boards.greenhouse.io/studio/jobs/1" }),
    );
    expect(outcome).toEqual({
      kind: "already_hosted",
      url: "https://boards.greenhouse.io/studio/jobs/1",
    });
  });

  test("followed when listing exposes hosted apply href", async () => {
    const page = buildPage({
      url: "https://example.com/careers/gameplay",
      href: "https://jobs.lever.co/studio/abc",
    });
    const outcome = await detectAndFollowHostedApplyPage(page);
    expect(outcome.kind).toBe("followed");
  });

  test("no_link when no apply anchor exists", async () => {
    const outcome = await detectAndFollowHostedApplyPage(
      buildPage({ url: "https://example.com/careers/gameplay", count: 0 }),
    );
    expect(outcome).toEqual({
      kind: "no_link",
      url: "https://example.com/careers/gameplay",
    });
  });

  test("nav_failed when hosted apply navigation rejects", async () => {
    const outcome = await detectAndFollowHostedApplyPage(
      buildPage({
        url: "https://example.com/careers/gameplay",
        href: "https://boards.greenhouse.io/studio/jobs/9",
        gotoRejects: true,
      }),
    );
    expect(outcome.kind).toBe("nav_failed");
    if (outcome.kind === "nav_failed") {
      expect(outcome.href).toContain("greenhouse");
    }
  });
});

describe("job-apply honesty gates", () => {
  test("isHostedApplyErrorUrl detects Greenhouse error landings", () => {
    expect(isHostedApplyErrorUrl("https://job-boards.greenhouse.io/discord?error=true")).toBe(
      true,
    );
    expect(isHostedApplyErrorUrl("https://job-boards.greenhouse.io/discord/jobs/1")).toBe(false);
  });

  test("resolveJobApplyRunOutcome fails closed on critical step errors", () => {
    expect(
      resolveJobApplyRunOutcome([
        { action: "fill_name", status: "ok" },
        { action: "fill_email", status: "error", message: "Email field not found" },
        { action: "verify", status: "ok", message: "Submission confirmation detected" },
      ]),
    ).toEqual({ success: false, error: "Email field not found" });

    expect(
      resolveJobApplyRunOutcome([
        { action: "fill_name", status: "ok" },
        { action: "fill_email", status: "ok" },
        { action: "upload_resume", status: "ok" },
        { action: "submit", status: "ok" },
        { action: "verify", status: "ok", message: "Submission confirmation detected" },
      ]),
    ).toEqual({ success: true, error: null });
  });
});

import { settle } from "@bao/shared/utils/promise";
import type { Locator, Page } from "playwright";
import {
  BOOLEAN_FALSE_ANSWERS,
  BOOLEAN_TRUE_ANSWERS,
  type LocatorControlDescriptor,
  PLAYWRIGHT_ACTION_TIMEOUT_MS,
  PLAYWRIGHT_RETRY_INITIAL_DELAY_MS,
  PLAYWRIGHT_RETRY_MAX_ATTEMPTS,
  type SelectorMapInput,
} from "./runtime-contracts";

export const anchorSelectorByText = (text: string): string => `a:has-text('${text}')`;

export const anchorSelectorByHrefFragment = (fragment: string): string => `a[href*='${fragment}']`;

export const inputSelectorByName = (fieldName: string): string => `input[name='${fieldName}']`;

export const inputSelectorById = (fieldId: string): string => `input[id='${fieldId}']`;

export const textareaSelectorByName = (fieldName: string): string =>
  `textarea[name='${fieldName}']`;

export const textareaSelectorById = (fieldId: string): string => `textarea[id='${fieldId}']`;

export const selectSelectorByName = (fieldName: string): string => `select[name='${fieldName}']`;

export const selectSelectorById = (fieldId: string): string => `select[id='${fieldId}']`;

export const APPLY_LINK_SELECTOR = [
  anchorSelectorByText("Apply"),
  anchorSelectorByHrefFragment(["boards", "greenhouse", "io"].join(".")),
  anchorSelectorByHrefFragment(["jobs", "lever", "co"].join(".")),
  anchorSelectorByHrefFragment("apply"),
].join(", ");

export const isRetryablePlaywrightError = (reason: unknown): boolean => {
  const msg = String(reason).toLowerCase();
  return msg.includes("timeout") || msg.includes("target closed") || msg.includes("network");
};

export const waitMs = (ms: number): Promise<void> =>
  new Promise((resolve) => {
    const t = setTimeout(resolve, ms);
    if (typeof t === "object" && t !== null && "unref" in t && typeof t.unref === "function") {
      t.unref();
    }
  });

export const getCustomSelectorList = (selectorMap: SelectorMapInput, key: string): string[] => {
  const selectors = selectorMap[key];
  return Array.isArray(selectors) ? selectors.filter((selector) => selector.trim().length > 0) : [];
};

export const getCustomFieldSelectorList = (fieldKey: string): string[] => [
  textareaSelectorByName(fieldKey),
  inputSelectorByName(fieldKey),
  selectSelectorByName(fieldKey),
  textareaSelectorById(fieldKey),
  inputSelectorById(fieldKey),
  selectSelectorById(fieldKey),
];

export const runOnFirstMatchingLocator = async <T>(
  page: Page,
  selectors: readonly string[],
  action: (locator: Locator) => Promise<T | null>,
): Promise<T | null> => {
  const [selector, ...remainingSelectors] = selectors;
  if (!selector) {
    return null;
  }

  const locator = page.locator(selector).first();
  const countResult = await settle(locator.count());
  if (countResult.status === "fulfilled" && countResult.value > 0) {
    const actionResult = await action(locator);
    if (actionResult !== null) {
      return actionResult;
    }
  }

  return runOnFirstMatchingLocator(page, remainingSelectors, action);
};

export const withRetry = async <T>(
  fn: () => Promise<T>,
  options: { maxAttempts?: number; delayMs?: number } = {},
): Promise<T | null> => {
  const runAttempt = async (attempt: number, delayMs: number): Promise<T | null> => {
    const result = await settle(fn());
    if (result.status === "fulfilled") {
      return result.value;
    }
    if (attempt >= (options.maxAttempts ?? PLAYWRIGHT_RETRY_MAX_ATTEMPTS)) {
      return null;
    }
    if (!isRetryablePlaywrightError(result.reason)) {
      return null;
    }
    await waitMs(delayMs);
    return runAttempt(attempt + 1, delayMs * 2);
  };

  return runAttempt(1, options.delayMs ?? PLAYWRIGHT_RETRY_INITIAL_DELAY_MS);
};

export const fillFirstMatchingField = async (
  page: Page,
  selectors: readonly string[],
  value: string,
): Promise<boolean> => {
  if (value.trim().length === 0) {
    return false;
  }

  const fillResult = await runOnFirstMatchingLocator(page, selectors, async (locator) => {
    const result = await withRetry(() =>
      locator.fill(value, { timeout: PLAYWRIGHT_ACTION_TIMEOUT_MS }).then(() => true),
    );
    return result ?? null;
  });
  return fillResult ?? false;
};

export const clickFirstMatchingField = async (
  page: Page,
  selectors: readonly string[],
): Promise<boolean> => {
  const clickResult = await runOnFirstMatchingLocator(page, selectors, async (locator) => {
    const result = await withRetry(() =>
      locator.click({ timeout: PLAYWRIGHT_ACTION_TIMEOUT_MS }).then(() => true),
    );
    return result ?? null;
  });
  return clickResult ?? false;
};

const normalizeAnswerText = (value: string): string =>
  value.trim().toLowerCase().replace(/\s+/gu, " ");

const isTruthyAnswer = (answer: string): boolean =>
  BOOLEAN_TRUE_ANSWERS.has(normalizeAnswerText(answer));

const isFalsyAnswer = (answer: string): boolean =>
  BOOLEAN_FALSE_ANSWERS.has(normalizeAnswerText(answer));

const readLocatorDescriptors = async (locator: Locator): Promise<LocatorControlDescriptor[]> => {
  const descriptorResult = await settle(
    locator.evaluateAll((elements) =>
      elements.map((element) => {
        const input = element instanceof HTMLInputElement ? element : null;
        const wrappingLabel = element instanceof HTMLElement ? element.closest("label") : null;
        return {
          tagName: element.tagName.toLowerCase(),
          inputType: input?.type?.toLowerCase() ?? "",
          value: input?.value?.trim() ?? "",
          label: (wrappingLabel?.textContent ?? "").trim(),
          text: (element.textContent ?? "").trim(),
          ariaLabel: element.getAttribute("aria-label")?.trim() ?? "",
          placeholder: element.getAttribute("placeholder")?.trim() ?? "",
        };
      }),
    ),
  );

  return descriptorResult.status === "fulfilled" ? descriptorResult.value : [];
};

const findMatchingDescriptorIndex = (
  descriptors: readonly LocatorControlDescriptor[],
  answer: string,
): number | null => {
  const normalizedAnswer = normalizeAnswerText(answer);
  if (normalizedAnswer.length === 0) {
    return null;
  }

  const matchedIndex = descriptors.findIndex((descriptor) => {
    const candidates = [
      descriptor.value,
      descriptor.label,
      descriptor.text,
      descriptor.ariaLabel,
      descriptor.placeholder,
    ]
      .map((candidate) => normalizeAnswerText(candidate))
      .filter((candidate) => candidate.length > 0);

    return candidates.some(
      (candidate) =>
        candidate === normalizedAnswer ||
        candidate.includes(normalizedAnswer) ||
        normalizedAnswer.includes(candidate),
    );
  });

  return matchedIndex >= 0 ? matchedIndex : null;
};

const selectOptionValue = async (locator: Locator, answer: string): Promise<boolean> => {
  const normalizedAnswer = answer.trim();
  if (normalizedAnswer.length === 0) {
    return false;
  }

  const directSelection = await settle(locator.selectOption(normalizedAnswer, { timeout: 5_000 }));
  if (directSelection.status === "fulfilled" && directSelection.value.length > 0) {
    return true;
  }

  const optionResult = await settle(
    locator.evaluate((element) => {
      if (!(element instanceof HTMLSelectElement)) {
        return [];
      }

      return Array.from(element.options).map((option) => ({
        label: option.label.trim(),
        value: option.value.trim(),
        text: option.textContent?.trim() ?? "",
      }));
    }),
  );
  if (optionResult.status === "rejected") {
    return false;
  }

  const normalizedTarget = normalizeAnswerText(answer);
  const matchingOption = optionResult.value.find((option) => {
    const candidates = [option.label, option.value, option.text]
      .map((candidate) => normalizeAnswerText(candidate))
      .filter((candidate) => candidate.length > 0);
    return candidates.some(
      (candidate) =>
        candidate === normalizedTarget ||
        candidate.includes(normalizedTarget) ||
        normalizedTarget.includes(candidate),
    );
  });
  if (!matchingOption) {
    return false;
  }

  const matchedSelection = matchingOption.label
    ? await settle(locator.selectOption({ label: matchingOption.label }, { timeout: 5_000 }))
    : await settle(locator.selectOption(matchingOption.value, { timeout: 5_000 }));

  return matchedSelection.status === "fulfilled" && matchedSelection.value.length > 0;
};

const setCheckboxValue = async (
  locator: Locator,
  descriptors: readonly LocatorControlDescriptor[],
  answer: string,
): Promise<boolean> => {
  if (isTruthyAnswer(answer)) {
    const checkResult = await settle(locator.first().check({ timeout: 5_000 }));
    return checkResult.status === "fulfilled";
  }

  if (isFalsyAnswer(answer)) {
    const uncheckResult = await settle(locator.first().uncheck({ timeout: 5_000 }));
    return uncheckResult.status === "fulfilled";
  }

  const matchedIndex = findMatchingDescriptorIndex(descriptors, answer);
  if (matchedIndex === null) {
    return false;
  }

  const checkResult = await settle(locator.nth(matchedIndex).check({ timeout: 5_000 }));
  return checkResult.status === "fulfilled";
};

const setRadioValue = async (
  locator: Locator,
  descriptors: readonly LocatorControlDescriptor[],
  answer: string,
): Promise<boolean> => {
  const matchedIndex = findMatchingDescriptorIndex(descriptors, answer);
  if (matchedIndex === null) {
    if (!isTruthyAnswer(answer)) {
      return false;
    }
    const fallbackCheckResult = await settle(locator.first().check({ timeout: 5_000 }));
    return fallbackCheckResult.status === "fulfilled";
  }

  const checkResult = await settle(locator.nth(matchedIndex).check({ timeout: 5_000 }));
  return checkResult.status === "fulfilled";
};

const applyAnswerToLocator = async (locator: Locator, answer: string): Promise<boolean> => {
  const descriptors = await readLocatorDescriptors(locator);
  const primaryDescriptor = descriptors[0];
  if (!primaryDescriptor) {
    return false;
  }

  if (primaryDescriptor.tagName === "select") {
    return selectOptionValue(locator.first(), answer);
  }

  if (primaryDescriptor.inputType === "checkbox") {
    return setCheckboxValue(locator, descriptors, answer);
  }

  if (primaryDescriptor.inputType === "radio") {
    return setRadioValue(locator, descriptors, answer);
  }

  const fillResult = await settle(locator.first().fill(answer, { timeout: 5_000 }));
  return fillResult.status === "fulfilled";
};

export const fillFirstMatchingAnswer = async (
  page: Page,
  selectors: readonly string[],
  answer: string,
): Promise<boolean> => {
  if (answer.trim().length === 0) {
    return false;
  }

  const fillResult = await runOnFirstMatchingLocator(page, selectors, async (locator) => {
    const matched = await applyAnswerToLocator(locator, answer);
    return matched ? true : null;
  });

  return fillResult ?? false;
};

import { MS_PER_SECOND } from "@bao/shared/constants/time";
import type { JobApplyScriptEnvelope } from "@bao/shared/schemas/automation-scripts.schema";
import type { RpaRunResult } from "@bao/shared/schemas/rpa-events.schema";
import { DEFAULT_AUTOMATION_SETTINGS } from "@bao/shared/types/settings-defaults";
import {
  automationBrowserLaunchFailureToDetails,
  formatAutomationBrowserLaunchFailureMessage,
} from "@bao/shared/utils/automation-browser-launch-failure";
import { settle } from "@bao/shared/utils/promise";
import type { Page } from "playwright";
import { closeAutomationBrowser, launchAutomationBrowser } from "../runtime/browser";
import { automationRuntimeConfig } from "../runtime/config";
import type { ProtocolEmitter } from "../runtime/protocol";
