/**
 * Stable ordered strategy list used for ATS detection.
 */
export const JOB_APPLY_STRATEGIES: readonly JobApplyStrategy[] = [
  GREENHOUSE_STRATEGY,
  LEVER_STRATEGY,
  GENERIC_STRATEGY,
];

/**
 * Resolves the ATS strategy for a URL.
 *
 * @param currentUrl Current page URL after any hosted-form redirect.
 * @returns Matching strategy definition.
 */
export const resolveJobApplyStrategy = (currentUrl: string): JobApplyStrategy => {
  const normalizedUrl = currentUrl.toLowerCase();
  return (
    JOB_APPLY_STRATEGIES.find((strategy) =>
      strategy.urlHints.some((hint) => normalizedUrl.includes(hint)),
    ) ?? GENERIC_STRATEGY
  );
};

import { describe, expect, test } from "bun:test";
import { assertVerifySubmitHostAllowed } from "./verify-run";

const PUBLIC_HOST_REJECTION_PATTERN = /not a loopback or private host/u;

describe("assertVerifySubmitHostAllowed", () => {
  test("allows loopback and private hosts", () => {
    expect(() => assertVerifySubmitHostAllowed("http://127.0.0.1:3000/jobs/1")).not.toThrow();
    expect(() => assertVerifySubmitHostAllowed("http://localhost:3000/jobs/1")).not.toThrow();
    expect(() => assertVerifySubmitHostAllowed("http://[::1]:3000/jobs/1")).not.toThrow();
    expect(() => assertVerifySubmitHostAllowed("http://10.0.0.5/apply")).not.toThrow();
    expect(() => assertVerifySubmitHostAllowed("http://172.16.0.10/apply")).not.toThrow();
    expect(() => assertVerifySubmitHostAllowed("http://192.168.1.20:8080/apply")).not.toThrow();
  });

  test("throws for public hosts before candidate PII is submitted", () => {
    expect(() =>
      assertVerifySubmitHostAllowed("https://boards.greenhouse.io/studio/jobs/1"),
    ).toThrow(PUBLIC_HOST_REJECTION_PATTERN);
    expect(() => assertVerifySubmitHostAllowed("https://example.com/careers")).toThrow(
      PUBLIC_HOST_REJECTION_PATTERN,
    );
    expect(() => assertVerifySubmitHostAllowed("https://8.8.8.8/submit")).toThrow(
      PUBLIC_HOST_REJECTION_PATTERN,
    );
  });
});

import { basename } from "node:path";
import { jobApplyScriptEnvelopeSchema } from "@bao/shared/schemas/automation-scripts.schema";
import { resumeDataSchema } from "@bao/shared/schemas/resume.schema";
import type { RpaRunResult } from "@bao/shared/schemas/rpa-events.schema";
import type { JsonObject, JsonValue } from "@bao/shared/utils/json";
import { isLoopbackOrPrivateHost } from "@bao/shared/utils/private-host";
import {
  VERIFY_PROGRESS_YIELD_MS,
  VERIFY_STEP_INDEX,
  VERIFY_TOTAL_STEPS,
} from "../constants/verify-run";
import { parseScriptInput } from "../runtime/io";
import { ProtocolEmitter } from "../runtime/protocol";

const flattenJsonStrings = (value: JsonValue, parts: string[] = []): string => {
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (trimmed.length > 0) {
      parts.push(trimmed);
    }
    return parts.join(" ");
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      flattenJsonStrings(item, parts);
    }
    return parts.join(" ");
  }

  if (value !== null && typeof value === "object") {
    for (const item of Object.values(value)) {
      flattenJsonStrings(item, parts);
    }
  }

  return parts.join(" ");
};

const resolveSubmitUrl = (jobUrl: string): string => {
  const parsed = new URL(jobUrl);
  return new URL("/submit", parsed.origin).toString();
};

/**
 * Verification submissions carry candidate PII multipart payloads; fail closed
 * unless the target host is loopback or private address space.
 */
export const assertVerifySubmitHostAllowed = (jobUrl: string): void => {
  const rawHostname = new URL(jobUrl).hostname;
  const hostname =
    rawHostname.startsWith("[") && rawHostname.endsWith("]")
      ? rawHostname.slice(1, -1)
      : rawHostname;
  if (!isLoopbackOrPrivateHost(hostname)) {
    throw new Error(
      `Verification submission refused: host "${hostname}" is not a loopback or private host.`,
    );
  }
};

const appendResumeArtifact = async (
  form: FormData,
  resumeFilePath: string | undefined,
): Promise<string | null> => {
  if (!resumeFilePath) {
    return null;
  }

  const file = Bun.file(resumeFilePath);
  if (!(await file.exists())) {
    return "Resume artifact missing for verification submission.";
  }

  const bytes = await file.arrayBuffer();
  const fileName = basename(resumeFilePath);
  form.append(
    "resume",
    new File([bytes], fileName, {
      type: file.type.length > 0 ? file.type : "application/pdf",
    }),
  );
  return null;
};

const emitProgress = (
  emitter: ProtocolEmitter,
  action: string,
  step: number,
  message: string,
): void => {
  emitter.emitProgress({
    action,
    status: "running",
    message,
    step,
    totalSteps: VERIFY_TOTAL_STEPS,
  });
};

const buildVerificationForm = (
  personalInfo: {
    name?: string | null;
    email?: string | null;
    phone?: string | null;
  },
  coverLetterContent: JsonObject | undefined,
  customAnswers: Record<string, string>,
): FormData => {
  const form = new FormData();
  form.set("name", personalInfo.name?.trim() ?? "");
  form.set("email", personalInfo.email?.trim() ?? "");
  form.set("phone", personalInfo.phone?.trim() ?? "");

  if (coverLetterContent) {
    form.set("coverLetter", flattenJsonStrings(coverLetterContent));
  }

  for (const [fieldName, fieldValue] of Object.entries(customAnswers)) {
    form.set(fieldName, fieldValue);
  }

  return form;
};

const submitVerificationForm = async (
  emitter: ProtocolEmitter,
  jobUrl: string,
  form: FormData,
): Promise<number> => {
  emitProgress(
    emitter,
    "verify_submission",
    VERIFY_STEP_INDEX.submission,
    "Completing deterministic verification submission.",
  );

  assertVerifySubmitHostAllowed(jobUrl);

  const submitResponse = await fetch(resolveSubmitUrl(jobUrl), {
    method: "POST",
    body: form,
  });

  if (!submitResponse.ok) {
    emitter.emitError(
      "SCRIPT_OUTPUT_INVALID",
      `Verification submission failed with status ${String(submitResponse.status)}.`,
    );
    return 1;
  }

  const result: RpaRunResult = {
    success: true,
    error: null,
    screenshots: [],
    artifacts: [],
    steps: [
      { action: "verify_bootstrap", status: "ok" },
      { action: "verify_fields", status: "ok" },
      { action: "verify_submission", status: "ok" },
    ],
  };
  emitter.emitResult(result);
  return 0;
};

/**
 * Deterministic job-apply path for BAO_ENABLE_AUTOMATION_VERIFY.
 * Posts multipart form fields to the job fixture submit URL without Playwright.
 */
export const emitVerificationRun = async (): Promise<number> => {
  const inputResult = await parseScriptInput(jobApplyScriptEnvelopeSchema);
  const runId = inputResult.ok ? inputResult.value.runId : "automation-verify-run";
  const emitter = new ProtocolEmitter(runId);

  if (!inputResult.ok) {
    emitter.emitError("OUTPUT_VALIDATION_ERROR", inputResult.message);
    return 1;
  }

  const envelope = inputResult.value;
  const resumeParsed = resumeDataSchema.safeParse(envelope.resume);
  if (!resumeParsed.success) {
    emitter.emitError("OUTPUT_VALIDATION_ERROR", "Verification resume payload is invalid.");
    return 1;
  }

  emitProgress(
    emitter,
    "verify_bootstrap",
    VERIFY_STEP_INDEX.bootstrap,
    "Preparing deterministic verification automation run.",
  );
  await Bun.sleep(VERIFY_PROGRESS_YIELD_MS);

  const form = buildVerificationForm(
    resumeParsed.data.personalInfo ?? {},
    envelope.coverLetter?.content,
    envelope.customAnswers,
  );

  emitProgress(
    emitter,
    "verify_fields",
    VERIFY_STEP_INDEX.fields,
    "Applying deterministic verification answers.",
  );
  await Bun.sleep(VERIFY_PROGRESS_YIELD_MS);

  const resumeError = await appendResumeArtifact(form, envelope.resumeFilePath);
  if (resumeError !== null) {
    emitter.emitError("SCRIPT_OUTPUT_INVALID", resumeError);
    return 1;
  }

  return submitVerificationForm(emitter, envelope.jobUrl, form);
};

