import type { ScrapedJob } from "@bao/shared/schemas/automation-scripts.schema";

/**
 * Narrow page contract used by scraper providers.
 */
export interface PageEvaluator {
  /**
   * Evaluate a synchronous DOM extraction callback without arguments.
   */
  evaluate<Result>(pageFunction: () => Result): Promise<Result>;
  /**
   * Evaluate a synchronous DOM extraction callback with a serializable argument.
   */
  evaluate<Result, Arg>(pageFunction: (arg: Arg) => Result, arg: Arg): Promise<Result>;
}

/**
 * Shared page-level extractor contract for portal scrapers.
 */
export type PortalJobExtractor = (
  /**
   * Page-like evaluator positioned on the target source URL.
   */
  page: PageEvaluator,
  /**
   * Canonical source URL supplied by provider settings.
   */
  sourceUrl: string,
) => Promise<ScrapedJob[]>;

import type { ScrapedJob } from "@bao/shared/schemas/automation-scripts.schema";
import {
  SCRAPED_JOB_COMPANY_LINE_MAX_LENGTH,
  SCRAPED_JOB_COMPANY_MAX_LENGTH,
  SCRAPED_JOB_TITLE_MAX_LENGTH,
  SCRAPED_JOB_TITLE_MIN_LENGTH,
} from "../constants/scrape-fields";
import { buildScraperHash } from "../runtime/hash";
import { toAbsoluteUrl, toBoundedText } from "./provider-helpers";
import type { PageEvaluator } from "./provider-types";

const REMOTE_GAME_JOBS_RESULT_LIMIT = 50;
const EMPLOYMENT_TYPE_TOKENS = ["full-time", "part-time", "contract", "freelance", "internship"];
const REMOTE_GAME_JOBS_BOX_SELECTOR = ".job-box";
const REMOTE_GAME_JOBS_PRIMARY_LINK_SELECTOR = "a.has-text-black";
const REMOTE_GAME_JOBS_SECONDARY_LINK_SELECTOR = "a[href*='/jobs/']";

type RemoteGameJobsCandidate = {
  title: string;
  company: string;
  href: string;
};

type RemoteGameJobsEvaluateArgs = {
  employmentTypeTokens: readonly string[];
  boxSelector: string;
  primaryLinkSelector: string;
  secondaryLinkSelector: string;
  resultLimit: number;
  titleMinLength: number;
  companyLineMaxLength: number;
};

const extractRemoteGameJobsCandidates = ({
  employmentTypeTokens,
  boxSelector,
  primaryLinkSelector,
  secondaryLinkSelector,
  resultLimit,
  titleMinLength,
  companyLineMaxLength,
}: RemoteGameJobsEvaluateArgs): RemoteGameJobsCandidate[] => {
  const findCompanyLine = (lines: string[], title: string): string =>
    lines.find((line) => {
      const lowered = line.toLowerCase();
      return (
        line !== title &&
        !employmentTypeTokens.includes(lowered) &&
        !line.startsWith("Remote") &&
        line.length > 2 &&
        line.length < companyLineMaxLength
      );
    }) ?? "Unknown";

  const boxes = Array.from(document.querySelectorAll<HTMLElement>(boxSelector));

  return boxes.slice(0, resultLimit).flatMap((box) => {
    const link =
      box.querySelector<HTMLAnchorElement>(primaryLinkSelector) ??
      box.querySelector<HTMLAnchorElement>(secondaryLinkSelector);
    if (!link) {
      return [];
    }

    const title = ((link.textContent ?? "").trim().split("\n")[0] ?? "").trim();
    if (title.length < titleMinLength) {
      return [];
    }

    const lines = (box.innerText ?? "")
      .split("\n")
      .map((line) => line.trim())
      .filter((line) => line.length > 0);

    return [
      {
        title,
        company: findCompanyLine(lines, title),
        href: link.getAttribute("href") ?? "",
      },
    ];
  });
};

/**
 * Extracts normalized RemoteGameJobs entries from the current Playwright page.
 *
 * @param page Page evaluator positioned on a RemoteGameJobs listing.
 * @param sourceUrl Canonical source URL supplied by settings.
 * @returns Normalized job rows.
 */
export const extractRemoteGameJobs = async (
  page: PageEvaluator,
  sourceUrl: string,
): Promise<ScrapedJob[]> => {
  const rows = await page.evaluate(extractRemoteGameJobsCandidates, {
    employmentTypeTokens: EMPLOYMENT_TYPE_TOKENS,
    boxSelector: REMOTE_GAME_JOBS_BOX_SELECTOR,
    primaryLinkSelector: REMOTE_GAME_JOBS_PRIMARY_LINK_SELECTOR,
    secondaryLinkSelector: REMOTE_GAME_JOBS_SECONDARY_LINK_SELECTOR,
    resultLimit: REMOTE_GAME_JOBS_RESULT_LIMIT,
    titleMinLength: SCRAPED_JOB_TITLE_MIN_LENGTH,
    companyLineMaxLength: SCRAPED_JOB_COMPANY_LINE_MAX_LENGTH,
  });

  return rows.slice(0, REMOTE_GAME_JOBS_RESULT_LIMIT).map((row) => {
    const title = toBoundedText(row.title, SCRAPED_JOB_TITLE_MAX_LENGTH);
    const company = toBoundedText(row.company, SCRAPED_JOB_COMPANY_MAX_LENGTH) || "Unknown";

    return {
      title,
      company,
      location: "Remote",
      remote: true,
      description: "",
      url: toAbsoluteUrl(sourceUrl, row.href || sourceUrl),
      source: "remotegamejobs",
      postedDate: "",
      contentHash: buildScraperHash("rgj", [title, company, "Remote"]),
    };
  });
};

import type { ScrapedJob } from "@bao/shared/schemas/automation-scripts.schema";
import {
  SCRAPED_JOB_COMPANY_LINE_MAX_LENGTH,
  SCRAPED_JOB_COMPANY_MAX_LENGTH,
  SCRAPED_JOB_LOCATION_MAX_LENGTH,
  SCRAPED_JOB_TITLE_MAX_LENGTH,
  SCRAPED_JOB_TITLE_MIN_LENGTH_SHORT,
} from "../constants/scrape-fields";
import { buildScraperHash } from "../runtime/hash";
import { normalizeWhitespace, toAbsoluteUrl, toBoundedText } from "./provider-helpers";
import type { PageEvaluator } from "./provider-types";

const WORK_WITH_INDIES_RESULT_LIMIT = 60;
const HIRING_PATTERN =
  /(.+?)\s+is hiring\s+(?:a |an )?(.+?)(?:to (?:work from|join)\s+(.+?))?(?:Learn More|$)/iu;

type WorkWithIndiesCandidate = {
  company: string;
  title: string;
  location: string;
  href: string;
};

/**
 * Extracts normalized Work With Indies jobs from the current Playwright page.
 *
 * @param page Page evaluator positioned on a Work With Indies listing.
 * @param sourceUrl Canonical source URL supplied by settings.
 * @returns Normalized job rows.
 */
export const extractWorkWithIndiesJobs = async (
  page: PageEvaluator,
  sourceUrl: string,
): Promise<ScrapedJob[]> => {
  const rows = await page.evaluate((resultLimit) => {
    const cards = Array.from(
      document.querySelectorAll<HTMLAnchorElement>("a.job-card, a[href*='/careers/']"),
    );

    return cards.slice(0, resultLimit).map((card) => ({
      text: (card.innerText ?? "").replaceAll("\n", " ").trim(),
      href: card.getAttribute("href") ?? "",
    }));
  }, WORK_WITH_INDIES_RESULT_LIMIT);

  const candidates: WorkWithIndiesCandidate[] = [];

  for (const row of rows) {
    const match = row.text.match(HIRING_PATTERN);
    if (!match) {
      continue;
    }

    const company = normalizeWhitespace(match[1] ?? "");
    const title = normalizeWhitespace(match[2] ?? "");
    const location = normalizeWhitespace(match[3] ?? "Remote");

    if (
      title.length < SCRAPED_JOB_TITLE_MIN_LENGTH_SHORT ||
      company.length > SCRAPED_JOB_COMPANY_LINE_MAX_LENGTH
    ) {
      continue;
    }

    const loweredCompany = company.toLowerCase();
    if (loweredCompany.includes("resume") || loweredCompany.includes("discord")) {
      continue;
    }

    candidates.push({
      company,
      title,
      location,
      href: row.href,
    });
  }

  return candidates.slice(0, WORK_WITH_INDIES_RESULT_LIMIT).map((row) => {
    const title = toBoundedText(row.title, SCRAPED_JOB_TITLE_MAX_LENGTH);
    const company = toBoundedText(row.company, SCRAPED_JOB_COMPANY_MAX_LENGTH);
    const location = toBoundedText(row.location, SCRAPED_JOB_LOCATION_MAX_LENGTH) || "Remote";

    return {
      title,
      company,
      location,
      remote:
        normalizeWhitespace(location).toLowerCase().includes("remote") ||
        normalizeWhitespace(location).toLowerCase().includes("anywhere"),
      description: "",
      url: toAbsoluteUrl(sourceUrl, row.href),
      source: "workwithindies",
      postDate: "",
      contentHash: buildScraperHash("wwi", [title, company, location]),
    };
  });
};

import { MS_PER_SECOND } from "@bao/shared/constants/time";
import type { AutomationBrowserLaunchFailureDetails } from "@bao/shared/schemas/error-envelope.schema";
import type { AutomationSettings } from "@bao/shared/types/settings-contracts";
import { DEFAULT_AUTOMATION_SETTINGS } from "@bao/shared/types/settings-defaults";
import { classifyAutomationBrowserLaunchFailure } from "@bao/shared/utils/automation-browser-launch-failure";
import { settle } from "@bao/shared/utils/promise";
import type { Browser, BrowserContext, Page } from "playwright";
import {
  automationRuntimeConfig,
  buildAutomationProcessEnvFromRuntimeEnv,
  sanitizePlaywrightBrowsersPathEnv,
} from "./config";

/**
 * Browser context bundle returned by Bun-based automation scripts.
 */
export interface AutomationBrowserSession {
  /** Chromium browser instance. */
  readonly browser: Browser;
  /** Browser context used for the current run. */
  readonly context: BrowserContext;
  /** Active page used for script execution. */
  readonly page: Page;
}

export type LaunchAutomationBrowserResult =
  | { readonly ok: true; readonly session: AutomationBrowserSession }
  | { readonly ok: false; readonly failure: AutomationBrowserLaunchFailureDetails };

const createContextOptions = () => ({
  locale: DEFAULT_AUTOMATION_SETTINGS.speech.locale,
});

const rejectLaunch = (
  reason: Error,
  stage: AutomationBrowserLaunchFailureDetails["stage"],
): LaunchAutomationBrowserResult => ({
  ok: false,
  failure: classifyAutomationBrowserLaunchFailure(
    reason,
    stage,
    buildAutomationProcessEnvFromRuntimeEnv().PLAYWRIGHT_BROWSERS_PATH,
  ),
});

/**
 * Launches a Playwright Chromium session using typed automation settings.
 *
 * @param settings Automation settings persisted by the server.
 * @returns Typed success session or classified launch failure (never silent null).
 */
export const launchAutomationBrowser = async (
  settings: AutomationSettings,
): Promise<LaunchAutomationBrowserResult> => {
  // Sanitize before dynamic import so Playwright registry resolution sees a
  // host-usable browsers path (agent sandboxes often inject a stale cache).
  sanitizePlaywrightBrowsersPathEnv();
  const { chromium } = await import("playwright");

  const browserResult = await settle(
    chromium.launch({
      headless: settings.headless,
    }),
  );
  if (browserResult.status === "rejected") {
    return rejectLaunch(browserResult.reason, "launch");
  }

  const browser = browserResult.value;
  const contextResult = await settle(browser.newContext(createContextOptions()));
  if (contextResult.status === "rejected") {
    await settle(browser.close());
    return rejectLaunch(contextResult.reason, "context");
  }

  const context = contextResult.value;
  const pageResult = await settle(context.newPage());
  if (pageResult.status === "rejected") {
    await settle(context.close());
    await settle(browser.close());
    return rejectLaunch(pageResult.reason, "page");
  }

  const page = pageResult.value;
  page.setDefaultTimeout(
    Math.max(settings.defaultTimeout * MS_PER_SECOND, automationRuntimeConfig.navigationTimeoutMs),
  );

  return {
    ok: true,
    session: {
      browser,
      context,
      page,
    },
  };
};

/**
 * Closes a browser session without using control-flow exceptions.
 *
 * @param session Browser session returned by `launchAutomationBrowser`.
 */
export const closeAutomationBrowser = async (
  session: AutomationBrowserSession | null,
): Promise<void> => {
  if (!session) {
    return;
  }

  await settle(session.context.close());
  await settle(session.browser.close());
};

import { existsSync } from "node:fs";
import { arch, homedir, platform, release } from "node:os";
import {
  AUTOMATION_PAGE_SETTLE_DELAY_MS_DEFAULT,
  AUTOMATION_POST_SUBMIT_DELAY_MS_DEFAULT,
  AUTOMATION_SECONDARY_NAVIGATION_DELAY_MS_DEFAULT,
} from "@bao/shared/constants/automation-timing";
import { DECIMAL_RADIX } from "@bao/shared/constants/client-config";
import { ENV_AUTOMATION_SCRIPT_TIMEOUT_MS_DEFAULT } from "@bao/shared/constants/env-bounds";
import {
  buildAutomationProcessEnv as buildAutomationProcessEnvFromShared,
  defaultPlaywrightBrowsersPathForPlatform,
  type PlaywrightBrowsersPathDeps,
  resolvePlaywrightBrowsersPath,
  resolvePlaywrightHostPlatformOverride,
} from "@bao/shared/utils/playwright-browsers-path";

const playwrightBrowsersPathDeps = (): PlaywrightBrowsersPathDeps => ({
  pathExists: existsSync,
  hostDefaultPath: defaultPlaywrightBrowsersPathForPlatform(process.platform, homedir()),
});

const resolveHostPlatformOverride = (): string | null =>
  resolvePlaywrightHostPlatformOverride(platform(), arch(), release());

/**
 * Sanitizes process.env Playwright browsers path and host-platform override
 * before Playwright resolves its registry. Prefer a host-usable cache over an
 * incomplete agent cache; avoid os.cpus() in agent sandboxes.
 */
export const sanitizePlaywrightBrowsersPathEnv = (): void => {
  const resolution = resolvePlaywrightBrowsersPath(
    process.env.PLAYWRIGHT_BROWSERS_PATH,
    playwrightBrowsersPathDeps(),
  );
  if (resolution.action === "set") {
    process.env.PLAYWRIGHT_BROWSERS_PATH = resolution.value;
  } else if (resolution.action === "unset") {
    delete process.env.PLAYWRIGHT_BROWSERS_PATH;
  }

  const hostOverride = resolveHostPlatformOverride();
  if (hostOverride && !process.env.PLAYWRIGHT_HOST_PLATFORM_OVERRIDE) {
    process.env.PLAYWRIGHT_HOST_PLATFORM_OVERRIDE = hostOverride;
  }
};

/**
 * Builds a child-process env with a non-polluted Playwright browsers path
 * and PLAYWRIGHT_HOST_PLATFORM_OVERRIDE when missing. Binds the shared pure
 * helper to the scraper runtime's own process.env (the server spawn-side
 * binding lives in @bao/server config/paths).
 */
export const buildAutomationProcessEnvFromRuntimeEnv = (
  baseEnv: NodeJS.ProcessEnv = process.env,
): NodeJS.ProcessEnv =>
  buildAutomationProcessEnvFromShared(
    baseEnv,
    playwrightBrowsersPathDeps(),
    resolveHostPlatformOverride(),
  );

const parsePositiveInt = (rawValue: string | undefined, defaultValue: number): number => {
  if (!rawValue) {
    return defaultValue;
  }

  const parsedValue = Number.parseInt(rawValue, DECIMAL_RADIX);
  return Number.isFinite(parsedValue) && parsedValue > 0 ? parsedValue : defaultValue;
};

/**
 * Typed runtime configuration for Bun-based scraper and job-apply scripts.
 */
export interface AutomationRuntimeConfig {
  /** Default timeout applied to scraper navigation. */
  readonly navigationTimeoutMs: number;
  /** Small delay after navigation to allow lazy DOM hydration. */
  readonly pageSettleDelayMs: number;
  /** Delay after follow-up navigation in ATS flows. */
  readonly secondaryNavigationDelayMs: number;
  /** Delay after submit actions before verification runs. */
  readonly postSubmitDelayMs: number;
  /** Enables deterministic verification runs instead of live automation. */
  readonly enableAutomationVerify: boolean;
}

/**
 * Shared runtime defaults with environment overrides for automation scripts.
 */
export const automationRuntimeConfig: AutomationRuntimeConfig = {
  navigationTimeoutMs: parsePositiveInt(
    Bun.env.AUTOMATION_NAVIGATION_TIMEOUT_MS,
    ENV_AUTOMATION_SCRIPT_TIMEOUT_MS_DEFAULT,
  ),
  pageSettleDelayMs: parsePositiveInt(
    Bun.env.AUTOMATION_PAGE_SETTLE_DELAY_MS,
    AUTOMATION_PAGE_SETTLE_DELAY_MS_DEFAULT,
  ),
  secondaryNavigationDelayMs: parsePositiveInt(
    Bun.env.AUTOMATION_SECONDARY_NAVIGATION_DELAY_MS,
    AUTOMATION_SECONDARY_NAVIGATION_DELAY_MS_DEFAULT,
  ),
  postSubmitDelayMs: parsePositiveInt(
    Bun.env.AUTOMATION_POST_SUBMIT_DELAY_MS,
    AUTOMATION_POST_SUBMIT_DELAY_MS_DEFAULT,
  ),
  get enableAutomationVerify(): boolean {
    return Bun.env.BAO_ENABLE_AUTOMATION_VERIFY === "true";
  },
};

import { afterAll, describe, expect, mock, test } from "bun:test";
import { mkdir, mkdtemp, realpath, rm, writeFile } from "node:fs/promises";
