import { SCRAPER_CONTENT_HASH_HEX_LENGTH } from "../constants/scrape-fields";

/**
 * Builds a deterministic content hash for normalized scraper rows.
 *
 * @param prefix Stable provider-specific prefix.
 * @param parts Canonical string parts used for hashing.
 * @returns Stable prefixed hash.
 */
export const buildScraperHash = (prefix: string, parts: readonly string[]): string => {
  const canonical = parts.map((part) => part.trim().toLowerCase()).join("|");
  const hasher = new Bun.CryptoHasher("sha256");
  hasher.update(canonical);
  return `${prefix}-${hasher.digest("hex").slice(0, SCRAPER_CONTENT_HASH_HEX_LENGTH)}`;
};

import { safeParseJson } from "@bao/shared/utils/json";
import type { ZodType } from "zod";

type ParseScriptInputSuccess<T> = {
  ok: true;
  value: T;
};

type ParseScriptInputFailure = {
  ok: false;
  message: string;
};

/**
 * Reads and validates stdin JSON against a supplied Zod schema.
 *
 * @param schema Runtime schema for the script payload.
 * @returns Parsed payload or a deterministic validation failure.
 */
export const parseScriptInput = async <T>(
  schema: ZodType<T>,
): Promise<ParseScriptInputSuccess<T> | ParseScriptInputFailure> => {
  const rawInput = await Bun.stdin.text();
  const normalizedInput = rawInput.trim().length > 0 ? rawInput : "{}";
  const parsedJson = safeParseJson(normalizedInput);

  if (parsedJson === null) {
    return {
      ok: false,
      message: "Automation script received invalid JSON input.",
    };
  }

  const parsedPayload = schema.safeParse(parsedJson);
  if (!parsedPayload.success) {
    const firstIssue = parsedPayload.error.issues[0];
    const issuePath = firstIssue?.path.join(".") || "root";
    return {
      ok: false,
      message: `Automation script payload is invalid at ${issuePath}.`,
    };
  }

  return {
    ok: true,
    value: parsedPayload.data,
  };
};

/**
 * Writes a plain JSON result payload to stdout for scraper-style scripts.
 *
 * @param payload JSON-serializable payload written to stdout.
 */
export const writeJsonResult = (payload: unknown): void => {
  process.stdout.write(`${JSON.stringify(payload)}\n`);
};

import type { ErrorEnvelope, RpaRunErrorCode } from "@bao/shared/schemas/error-envelope.schema";
import type { RpaRunEvent, RpaRunResult } from "@bao/shared/schemas/rpa-events.schema";
import { RPA_PROTOCOL_VERSION } from "@bao/shared/schemas/rpa-protocol.schema";
import type { JsonObject } from "@bao/shared/utils/json";

type ProtocolOutputStream = "stdout" | "stderr";

const writeProtocolLine = (stream: ProtocolOutputStream, event: RpaRunEvent): void => {
  const target = stream === "stdout" ? process.stdout : process.stderr;
  target.write(`${JSON.stringify(event)}\n`);
};

/**
 * Writes a single NDJSON protocol line to the requested stream.
 *
 * @param stream Output stream used for the event.
 * @param event Fully constructed protocol event.
 */
export const emitProtocolLine = (stream: ProtocolOutputStream, event: RpaRunEvent): void => {
  writeProtocolLine(stream, event);
};

/**
 * Contract-first protocol emitter for Bun-based job-apply automation scripts.
 */
export class ProtocolEmitter {
  private readonly runId: string;
  private sequence = 0;

  /**
   * Creates a protocol emitter for a single run identifier.
   *
   * @param runId Stable run identifier supplied by the server.
   */
  constructor(runId: string) {
    this.runId = runId;
  }

  private nextMetadata() {
    const metadata = {
      protocolVersion: RPA_PROTOCOL_VERSION,
      runId: this.runId,
      sequence: this.sequence,
      timestamp: new Date().toISOString(),
    } as const;
    this.sequence += 1;
    return metadata;
  }

  /**
   * Emits a progress event to stderr.
   *
   * @param event Progress payload without shared metadata.
   */
  emitProgress(
    event: Pick<
      Extract<RpaRunEvent, { eventType: "progress" }>,
      "action" | "status" | "message" | "step" | "totalSteps"
    >,
  ): void {
    emitProtocolLine("stderr", {
      ...this.nextMetadata(),
      eventType: "progress",
      ...event,
    });
  }

  /**
   * Emits a terminal result event to stdout.
   *
   * @param result Final automation result payload.
   */
  emitResult(result: RpaRunResult): void {
    emitProtocolLine("stdout", {
      ...this.nextMetadata(),
      eventType: "result",
      result,
    });
  }

  /**
   * Emits a terminal error event to stdout.
   *
   * @param code Runtime-neutral error classification.
   * @param message Human-readable error detail.
   * @param details Optional JSON details payload.
   */
  emitError(code: RpaRunErrorCode, message: string, details?: JsonObject): void {
    const error: ErrorEnvelope = {
      code,
      message,
      ...(details ? { details } : {}),
    };

    emitProtocolLine("stdout", {
      ...this.nextMetadata(),
      eventType: "error",
      error: {
        ...error,
        source: "@bao/scraper",
      },
    });
  }
}

import { scraperScriptEnvelopeSchema } from "@bao/shared/schemas/automation-scripts.schema";
import { DEFAULT_AUTOMATION_SETTINGS } from "@bao/shared/types/settings-defaults";
import { formatAutomationBrowserLaunchFailureMessage } from "@bao/shared/utils/automation-browser-launch-failure";
import { settle } from "@bao/shared/utils/promise";
