const createTraceId = (): string => {
  const bytes = new Uint8Array(TRACE_ID_BYTE_LENGTH);
  crypto.getRandomValues(bytes);
  return [...bytes].map((b) => b.toString(COUNT_SIXTEEN).padStart(2, "0")).join("");
};

