    const response = await requestJson<{
      id: string;
      studioId: string;
      role: string;
      totalQuestions: number;
      message: string;
    }>(harness.app, "POST", INTERVIEW_SESSIONS_ENDPOINT, {
      studioId: "activision-blizzard",
      config: {
        roleType: "Build Engineer",
        questionCount: 1,
      },
