import {
  API_ERROR_EMPTY_API_KEY,
  API_ERROR_INVALID_API_KEY,
  API_ERROR_MISSING_AUTH_HEADER,
} from "@bao/shared/constants/api-errors";
import { HTTP_STATUS_UNAUTHORIZED } from "@bao/shared/constants/http";
import { DEFAULT_PROFILE_ID } from "@bao/shared/types/settings-defaults";
import { eq } from "drizzle-orm";
import { Elysia } from "elysia";
import { isAuthDisabled } from "../config/env";
import { db } from "../db/client";
import { auth } from "../db/schema/auth";
import { verifyApiKey } from "../utils/crypto";

type AuthFailure = { error: string; status: typeof HTTP_STATUS_UNAUTHORIZED };

/**
 * Query parameter accepted as an alternative credential channel for clients
 * that cannot set headers (browser WebSocket, <img> screenshot loads).
 */
export const AUTH_QUERY_TOKEN_PARAM = "token";

type CredentialRead =
  | { kind: "missing" }
  | { kind: "wrong-scheme" }
  | { kind: "empty" }
  | { kind: "ok"; token: string };

function readBearerHeader(request: Request): CredentialRead {
  const raw = request.headers.get("authorization");
  if (raw === null) {
    return { kind: "missing" };
  }
  const trimmed = raw.trim();
  if (!trimmed.startsWith("Bearer")) {
    return { kind: "wrong-scheme" };
  }
  if (trimmed === "Bearer") {
    return { kind: "empty" };
  }
  if (!trimmed.startsWith("Bearer ")) {
    return { kind: "wrong-scheme" };
  }
  const token = trimmed.slice("Bearer ".length).trim();
  return token.length > 0 ? { kind: "ok", token } : { kind: "empty" };
}

function readQueryToken(request: Request): CredentialRead {
  if (!URL.canParse(request.url)) {
    return { kind: "missing" };
  }
  const raw = new URL(request.url).searchParams.get(AUTH_QUERY_TOKEN_PARAM);
  if (raw === null) {
    return { kind: "missing" };
  }
  const token = raw.trim();
  return token.length > 0 ? { kind: "ok", token } : { kind: "empty" };
}

function readCredential(request: Request): CredentialRead {
  const bearer = readBearerHeader(request);
  if (bearer.kind !== "missing") {
    return bearer;
  }
  return readQueryToken(request);
}

/**
 * Validates an API key credential against the persisted SHA-256 hash.
 *
 * The credential is read from the `Authorization: Bearer` header first; when
 * the header is absent, the `?token=` query parameter is used instead so
 * browser WebSocket handshakes and <img> screenshot loads can authenticate.
 *
 * The API key is hashed at creation and only the hash is stored in the
 * database. Verification re-hashes the provided bearer token and
 * compares it against the stored hash using `timingSafeEqual`.
 *
 * Keys are checked for revocation and expiry before hash comparison.
 */
export async function authenticateApiKey(request: Request): Promise<AuthFailure | null> {
  if (isAuthDisabled()) {
    return null;
  }

  const parsed = readCredential(request);
  switch (parsed.kind) {
    case "missing":
    case "wrong-scheme":
      return { error: API_ERROR_MISSING_AUTH_HEADER, status: HTTP_STATUS_UNAUTHORIZED };
    case "empty":
      return { error: API_ERROR_EMPTY_API_KEY, status: HTTP_STATUS_UNAUTHORIZED };
    case "ok":
      break;
    default: {
      const _exhaustive: never = parsed;
      return _exhaustive;
    }
  }

  const rows = await db.select().from(auth).where(eq(auth.id, DEFAULT_PROFILE_ID));
  const row = rows[0];
  const storedHash = row?.apiKeyHash;
  if (!storedHash) {
    return { error: API_ERROR_INVALID_API_KEY, status: HTTP_STATUS_UNAUTHORIZED };
  }

  if (row.apiKeyRevokedAt !== null) {
    return { error: API_ERROR_INVALID_API_KEY, status: HTTP_STATUS_UNAUTHORIZED };
  }

  if (row.apiKeyExpiresAt !== null) {
    const expiresAt = Date.parse(row.apiKeyExpiresAt);
    if (!Number.isFinite(expiresAt) || Date.now() > expiresAt) {
      return { error: API_ERROR_INVALID_API_KEY, status: HTTP_STATUS_UNAUTHORIZED };
    }
  }

  if (!verifyApiKey(parsed.token, storedHash)) {
    return { error: API_ERROR_INVALID_API_KEY, status: HTTP_STATUS_UNAUTHORIZED };
  }

  return null;
}

export const authGuard = new Elysia({ name: "auth-guard" })
  .beforeHandle(async ({ request, status }) => {
    const failure = await authenticateApiKey(request);
    if (failure) {
      return status(failure.status, { error: failure.error });
    }
  })
  .as("global");

import { HTTP_STATUS_NO_CONTENT } from "@bao/shared/constants/http";
import { Elysia } from "elysia";
import { config } from "../config/env";

const getRequestOrigin = (request: Request): string | null =>
  request.headers.get("origin") ?? request.headers.get("Origin");

type HeaderBag = {
  headers: {
    [key: string]: string | number | string[] | undefined;
  };
};

/**
 * Applies Access-Control-Allow-Origin when the request Origin is allow-listed.
 */
const applyAllowedOriginHeader = (set: HeaderBag, request: Request): void => {
  const requestOrigin = getRequestOrigin(request);
  if (!(requestOrigin && config.corsOrigins.includes(requestOrigin))) {
    return;
  }

  set.headers["access-control-allow-origin"] = requestOrigin;
  set.headers["access-control-allow-credentials"] = "true";
  const varyHeader = typeof set.headers.vary === "string" ? set.headers.vary : "";
  if (varyHeader !== "Origin" && varyHeader !== "*") {
    set.headers.vary = varyHeader ? `${varyHeader}, Origin` : "Origin";
  }
};

/**
 * Elysia 2 CORS plugin (replaces @elysiajs/cors which is incompatible with v2).
 */
export const corsPlugin = new Elysia({ name: "cors" })
  .request(({ request, set }) => {
    applyAllowedOriginHeader(set, request);

    if (request.method === "OPTIONS") {
      set.headers["access-control-allow-methods"] = "GET,POST,PUT,PATCH,DELETE,OPTIONS";
      set.headers["access-control-allow-headers"] =
        request.headers.get("access-control-request-headers") ?? "authorization,content-type";
      set.headers["access-control-max-age"] = "86400";
      set.status = HTTP_STATUS_NO_CONTENT;
      return new Response(null, {
        status: 204,
        headers: {
          "access-control-allow-origin": String(set.headers["access-control-allow-origin"] ?? ""),
          "access-control-allow-credentials": "true",
          "access-control-allow-methods": "GET,POST,PUT,PATCH,DELETE,OPTIONS",
          "access-control-allow-headers": String(
            set.headers["access-control-allow-headers"] ?? "authorization,content-type",
          ),
          "access-control-max-age": "86400",
        },
      });
    }
  })
  .afterHandle(({ request, set }) => {
    applyAllowedOriginHeader(set, request);
  });

import {
  API_ERROR_INTERNAL_SERVER,
  API_ERROR_NOT_FOUND,
  API_ERROR_VALIDATION_FAILED,
} from "@bao/shared/constants/api-errors";
import {
  HTTP_STATUS_BAD_REQUEST,
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_NOT_FOUND,
} from "@bao/shared/constants/http";
import { TRACE_ID_HEADER } from "@bao/shared/constants/runtime";
import { Elysia } from "elysia";
import { createServerLogger } from "../utils/logger";

interface ValidationField {
  path: string;
  message: string;
}

interface HasValidationAll {
  all: readonly ValidationField[] | (() => readonly ValidationField[]);
}

function hasValidationAll(value: object): value is HasValidationAll {
  return "all" in value && value.all !== null && value.all !== undefined;
}

function hasArrayAll(value: object): value is { all: readonly ValidationField[] } {
  return hasValidationAll(value) && Array.isArray(value.all);
}

function collectValidationFields(error: object): ValidationField[] | undefined {
  if (hasArrayAll(error)) {
    const entries = error.all;
    return entries.length > 0 ? [...entries] : undefined;
  }
  if (hasValidationAll(error)) {
    const fn = error.all;
    if (typeof fn === "function") {
      const entries = fn();
      return entries.length > 0 ? [...entries] : undefined;
    }
  }
  return undefined;
}

const logger = createServerLogger("error-handler");

/**
 * Centralized error handler for Elysia that extracts trace IDs and returns
 * typed JSON error responses for each error category.
 */
export const errorHandler = new Elysia({ name: "error-handler" }).error((context) => {
  const { error, set } = context;
  const code = "code" in context && typeof context.code === "string" ? context.code : undefined;
  const headerTrace = set.headers[TRACE_ID_HEADER];
  const traceId = typeof headerTrace === "string" ? headerTrace : undefined;

  if (code === "NOT_FOUND") {
    set.status = HTTP_STATUS_NOT_FOUND;
    return { error: API_ERROR_NOT_FOUND, code, traceId };
  }

  const isValidation =
    code === "VALIDATION" ||
    (typeof error === "object" &&
      error !== null &&
      "constructor" in error &&
      error.constructor.name === "ValidationError");

  if (isValidation && typeof error === "object" && error !== null) {
    const fields = collectValidationFields(error);
    set.status = HTTP_STATUS_BAD_REQUEST;
    return {
      error: API_ERROR_VALIDATION_FAILED,
      code: "VALIDATION",
      fields: fields ? fields.map((f) => f.path) : undefined,
      traceId,
    };
  }

  if (isValidation) {
    set.status = HTTP_STATUS_BAD_REQUEST;
    return { error: API_ERROR_VALIDATION_FAILED, code: "VALIDATION", traceId };
  }

  logger.error(
    `[${code}] traceId=${traceId}`,
    error instanceof Error ? error.message : String(error),
  );
  set.status = HTTP_STATUS_INTERNAL_SERVER_ERROR;
  return { error: API_ERROR_INTERNAL_SERVER, code, traceId };
});

import { API_ENDPOINTS } from "@bao/shared/constants/endpoints";
