  resumeId: string,
  fixtureBaseUrl: string,
): Promise<string> => {
  const recoveredRunId = crypto.randomUUID();
  const recoveredRunAt = new Date(Date.now() + SCHEDULE_LEAD_TIME_MS).toISOString();
  const now = new Date().toISOString();
  await db.insert(automationRuns).values({
    id: recoveredRunId,
    type: "job_apply",
    status: "pending",
    jobId: null,
    userId: null,
    input: {
      action: "job_apply",
      jobUrl: fixtureBaseUrl,
      resumeId,
      customAnswers: {},
      schedule: { runAt: recoveredRunAt },
    },
    progress: 0,
    currentStep: null,
    totalSteps: null,
    exitCode: null,
    timedOut: false,
    aborted: false,
    executionMs: null,
    startedAt: null,
    createdAt: now,
    updatedAt: now,
  });

  return recoveredRunId;
};

export const verifyRecoveredScheduledRun = async (
  resumeId: string,
  fixtureBaseUrl: string,
  getSubmissionCount: () => number,
  instantiateService: () => ApplicationAutomationService,
): Promise<void> => {
  const recoveredRunId = await insertRecoveredScheduledRun(resumeId, fixtureBaseUrl);
  instantiateService();

  const completedRecoveredRun = await waitForRunCompletion(recoveredRunId);
  expect(completedRecoveredRun.status).toBe("success");
  await waitForSubmissionCount(getSubmissionCount, COUNT_THREE);
};

import { expect } from "bun:test";
import { COUNT_FOUR_HUNDRED, MS_FIVE_SECONDS } from "@bao/shared/constants/numeric";
import {
  type RpaRunEvent,
  type RpaRunExecutionEnvelope,
  rpaRunEventSchema,
  rpaRunExecutionEnvelopeSchema,
} from "@bao/shared/schemas/rpa-events.schema";
import type { EmailTransportSettings } from "@bao/shared/types/settings-contracts";
import {
  DEFAULT_AUTOMATION_SETTINGS,
  DEFAULT_EMAIL_TRANSPORT_SETTINGS,
  DEFAULT_SETTINGS_ID,
} from "@bao/shared/types/settings-defaults";
import type { JsonObject } from "@bao/shared/utils/json";
import { parseJson, safeParseJson } from "@bao/shared/utils/json";
import { eq } from "drizzle-orm";
import { z } from "zod";
import { db } from "../db/client";
import { automationRuns } from "../db/schema/automation-runs";
