import { getCoverLetterById, normalizeTemplate } from "./cover-letter-route-support";

const coverLetterGenerationLogger = createServerLogger("cover-letter-generation");

type CoverLetterSender = {
  name: string;
  email?: string;
  phone?: string;
  location?: string;
};

const saveGeneratedCoverLetter = async (
  body: GenerateCoverLetterBody,
  content: GeneratedCoverLetterContent,
) => {
  const coverLetter = {
    id: generateId(),
    company: body.company,
    position: body.position,
    jobInfo: body.jobInfo || {},
    content,
    template: normalizeTemplate(body.template),
  };
  await db.insert(coverLetters).values(coverLetter);

  // Same contract as the manual create path: return the persisted row so the
  // database-defaulted timestamps are present and the insert is proven to have
  // landed, instead of echoing the in-memory payload.
  const [created] = await db.select().from(coverLetters).where(eq(coverLetters.id, coverLetter.id));
  if (!created) {
    throw new Error(API_ERROR_CREATE_COVER_LETTER);
  }
  return created;
};

const buildCoverLetterSender = async (): Promise<CoverLetterSender> => {
  const profileRows = await db
    .select()
    .from(userProfile)
    .where(eq(userProfile.id, DEFAULT_PROFILE_ID));
  const profile = profileRows[0];

  return {
    name: profile?.name || "",
    ...(profile?.email ? { email: profile.email } : {}),
    ...(profile?.phone ? { phone: profile.phone } : {}),
    ...(profile?.location ? { location: profile.location } : {}),
  };
};

const toJsonRecord = (value: unknown): Record<string, unknown> => {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return {};
  }
  const record: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(value)) {
    record[key] = entry;
  }
  return record;
};

const createCoverLetterExportError = (reason: unknown) => {
  coverLetterGenerationLogger.error("Cover letter export failed", {
    reason: reason instanceof Error ? reason.message : API_ERROR_UNKNOWN,
  });
  return {
    error: API_ERROR_EXPORT_COVER_LETTER,
  };
};

/**
 * Assembles the generation prompt from the candidate's resume plus the scraped
 * posting and studio records, so the prompt's "demonstrate knowledge of the company
 * and their games" instruction is backed by real data rather than whatever the
 * client happened to send.
 */
const buildCoverLetterGenerationPrompt = async (body: GenerateCoverLetterBody): Promise<string> => {
  const [resumeContext, entityContext] = await Promise.all([
    resolveResumeContext(body.resumeId),
    loadEntityPromptContext({
      jobId: body.jobId,
      studioId: body.studioId,
      includeSkills: true,
    }),
  ]);

  return coverLetterPrompt({
    company: body.company,
    position: body.position,
    jobInfo: body.jobInfo
      ? JSON.stringify(body.jobInfo, null, 2)
      : "No additional job information provided",
    resumeContext: resumeContext.promptContext,
    ...entityContext,
  });
};

export const handleGenerateCoverLetter = async (
  body: GenerateCoverLetterBody,
  set: RouteSetState,
) => {
  const settingsRows = await db.select().from(settings).where(eq(settings.id, DEFAULT_SETTINGS_ID));
  if (settingsRows.length === 0) {
    set.status = HTTP_STATUS_SERVICE_UNAVAILABLE;
    return { error: API_ERROR_AI_SETTINGS_NOT_CONFIGURED };
  }

  const aiService = AIService.fromSettings(settingsRows[0]);
  const aiResult = await settle(
    aiService.generate(await buildCoverLetterGenerationPrompt(body), {
      purpose: "coverLetter",
      temperature: AI_DEFAULT_TEMPERATURE_CREATIVE,
      maxTokens: AI_MAX_TOKENS_COVER_LETTER,
    }),
  );
  if (aiResult.status === "rejected") {
    coverLetterGenerationLogger.error("Cover letter AI generation rejected", {
      reason: aiResult.reason instanceof Error ? aiResult.reason.message : API_ERROR_UNKNOWN,
    });
    set.status = HTTP_STATUS_INTERNAL_SERVER_ERROR;
    return {
      error: API_ERROR_COVER_LETTER_GENERATION_FAILED,
    };
  }

  const response = aiResult.value;
  if (response.error) {
    coverLetterGenerationLogger.error("Cover letter AI generation returned provider error", {
      reason: response.error,
    });
    set.status = HTTP_STATUS_INTERNAL_SERVER_ERROR;
    return { error: API_ERROR_COVER_LETTER_GENERATION_FAILED };
  }

  const contentResult = validateGeneratedCoverLetterContent(
    toGeneratedCoverLetterContent(response.content),
  );
  if (!contentResult.success) {
    set.status = HTTP_STATUS_INTERNAL_SERVER_ERROR;
    return {
      error: API_ERROR_COVER_LETTER_INCOMPLETE_CONTENT,
      details: contentResult.error,
    };
  }

  const content = contentResult.data;
  if (!body.save) {
    return {
      message: API_MESSAGE_COVER_LETTER_GENERATED_ONLY,
      content,
    };
  }

  const coverLetter = await saveGeneratedCoverLetter(body, content);
  set.status = HTTP_STATUS_CREATED;
  return {
    message: API_MESSAGE_COVER_LETTER_GENERATED_SAVED,
    coverLetter,
  };
};

export const exportCoverLetterAttachment = async (
  id: string,
  format: string | undefined,
  set: RouteSetState,
  templateOverride?: string | null,
) => {
  const letter = await getCoverLetterById(id, set);
  if (!letter) {
    return { error: API_ERROR_COVER_LETTER_NOT_FOUND };
  }

  const payload = {
    company: letter.company,
    position: letter.position,
    content: toJsonRecord(letter.content),
    template: templateOverride ?? letter.template ?? undefined,
  };
  const sender = await buildCoverLetterSender();

  if (format === "docx") {
    const docxResult = await settle(docxExportService.exportCoverLetterDocx(payload, sender));
    if (docxResult.status === "rejected") {
      set.status = HTTP_STATUS_INTERNAL_SERVER_ERROR;
      return createCoverLetterExportError(docxResult.reason);
    }
    return createDocxAttachmentResponse(docxResult.value, `cover-letter-${id}.docx`);
  }

  const exportResult = await settle(exportService.exportCoverLetterPDF(payload, sender));
  if (exportResult.status === "rejected") {
    set.status = HTTP_STATUS_INTERNAL_SERVER_ERROR;
    return createCoverLetterExportError(exportResult.reason);
  }

  return createPdfAttachmentResponse(Buffer.from(exportResult.value), `cover-letter-${id}.pdf`);
};

import {
  API_ERROR_COVER_LETTER_NOT_FOUND,
  API_ERROR_CREATE_COVER_LETTER,
} from "@bao/shared/constants/api-errors";
import {
  COVER_LETTER_DEFAULT_TEMPLATE,
  type CoverLetterTemplate,
  isCoverLetterTemplate,
} from "@bao/shared/constants/cover-letter";
import { ROUTE_GAMIFICATION_XP } from "@bao/shared/constants/gamification";
import { HTTP_STATUS_CREATED, HTTP_STATUS_NOT_FOUND } from "@bao/shared/constants/http";
import { generateId } from "@bao/shared/utils/validation";
import { desc, eq } from "drizzle-orm";
import { db } from "../db/client";
import { coverLetters } from "../db/schema/cover-letters";
import { gamificationService } from "../services/gamification-service";
import type { RouteSetState } from "../types/route-state";

export const normalizeTemplate = (value: string | undefined): CoverLetterTemplate =>
  isCoverLetterTemplate(value) ? value : COVER_LETTER_DEFAULT_TEMPLATE;

export const listCoverLetters = async () =>
  db.select().from(coverLetters).orderBy(desc(coverLetters.createdAt));

export const createCoverLetter = async (body: {
  company: string;
  position: string;
  jobInfo?: Record<string, unknown>;
  content?: Record<string, unknown>;
  template?: string;
}) => {
  const coverLetter = {
    id: generateId(),
    company: body.company,
    position: body.position,
    jobInfo: body.jobInfo || {},
    content: body.content || {},
    template: normalizeTemplate(body.template),
  };

  await db.insert(coverLetters).values(coverLetter);

  // Read the row back rather than echoing the insert payload: `createdAt` /
  // `updatedAt` are database defaults, so echoing would return a cover letter
  // without the timestamps that every read path includes. Reading back also
  // proves the insert actually landed, matching the resume/portfolio services.
  const [created] = await db.select().from(coverLetters).where(eq(coverLetters.id, coverLetter.id));
  if (!created) {
    throw new Error(API_ERROR_CREATE_COVER_LETTER);
  }

  gamificationService.trackActionFireAndForget(
    "coverLettersGenerated",
    ROUTE_GAMIFICATION_XP.coverLettersGenerated,
    "cover_letter_created",
  );

  return { coverLetter: created, statusCode: HTTP_STATUS_CREATED };
};

export const getCoverLetterById = async (id: string, set: RouteSetState) => {
  const rows = await db.select().from(coverLetters).where(eq(coverLetters.id, id));
  if (rows.length === 0) {
    set.status = HTTP_STATUS_NOT_FOUND;
    return null;
  }
  return rows[0];
};

export const updateCoverLetter = async (
  id: string,
  body: {
    company?: string;
    position?: string;
    jobInfo?: Record<string, unknown>;
    content?: Record<string, unknown>;
    template?: string;
  },
  set: RouteSetState,
) => {
  const existing = await db.select().from(coverLetters).where(eq(coverLetters.id, id));
  if (existing.length === 0) {
    set.status = HTTP_STATUS_NOT_FOUND;
    return { error: API_ERROR_COVER_LETTER_NOT_FOUND };
  }

  const updates: Record<string, unknown> = {
    updatedAt: new Date().toISOString(),
  };

  if (body.company !== undefined) updates.company = body.company;
  if (body.position !== undefined) updates.position = body.position;
  if (body.jobInfo !== undefined) updates.jobInfo = body.jobInfo;
  if (body.content !== undefined) updates.content = body.content;
  if (body.template !== undefined) updates.template = normalizeTemplate(body.template);

  await db.update(coverLetters).set(updates).where(eq(coverLetters.id, id));
  const updatedRows = await db.select().from(coverLetters).where(eq(coverLetters.id, id));
  return updatedRows[0];
};

export const deleteCoverLetter = async (id: string, set: RouteSetState) => {
  const existing = await db.select().from(coverLetters).where(eq(coverLetters.id, id));
  if (existing.length === 0) {
    set.status = HTTP_STATUS_NOT_FOUND;
    return { error: API_ERROR_COVER_LETTER_NOT_FOUND };
  }

  await db.delete(coverLetters).where(eq(coverLetters.id, id));
  return { success: true, id };
};

import {
  API_ERROR_COVER_LETTER_NOT_FOUND,
  API_ERROR_UNKNOWN,
} from "@bao/shared/constants/api-errors";
import { API_ENDPOINTS, toApiChildPath, toApiScopedPath } from "@bao/shared/constants/endpoints";
import {
  HTTP_STATUS_CREATED,
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_NOT_FOUND,
  HTTP_STATUS_OK,
  HTTP_STATUS_SERVICE_UNAVAILABLE,
} from "@bao/shared/constants/http";
import { Elysia, type status } from "elysia";
import type { coverLetters } from "../db/schema/cover-letters";
import type { RouteSetState } from "../types/route-state";
import { openapiDetail } from "../utils/openapi-detail";
import {
  type CoverLetterExportBody,
  type CoverLetterIdParams,
  coverLetterDeleteResponses,
  coverLetterEntityResponses,
  coverLetterExportBodySchema,
  coverLetterExportResponses,
  coverLetterIdParamsSchema,
  coverLetterMutationBodySchema,
  coverLettersListResponses,
  coverLetterUpdateBodySchema,
  generateCoverLetterBodySchema,
  generateCoverLetterResponses,
} from "./cover-letter-route-contracts";
import {
  exportCoverLetterAttachment,
  handleGenerateCoverLetter,
} from "./cover-letter-route-generation";
import {
  createCoverLetter,
  deleteCoverLetter,
  getCoverLetterById,
  listCoverLetters,
  updateCoverLetter,
} from "./cover-letter-route-support";

type RouteStatus = typeof status;

/**
 * Derived from the table so the response mapper cannot drift from the schema.
 * The previous hand-written shape marked the `notNull()` timestamps optional,
 * which is what let the create path return a cover letter without them.
 */
type CoverLetterEntitySource = typeof coverLetters.$inferSelect;

const toRecordOrNull = (value: unknown) => {
  if (typeof value === "object" && value !== null && !Array.isArray(value)) {
    return { ...value };
  }
  return null;
};

const toCoverLetterEntityResponse = (letter: CoverLetterEntitySource) => ({
  id: letter.id,
  company: letter.company,
  position: letter.position,
  jobInfo: toRecordOrNull(letter.jobInfo),
  content: toRecordOrNull(letter.content),
  template: letter.template,
  createdAt: letter.createdAt,
  updatedAt: letter.updatedAt,
});

const toSimpleRouteErrorPayload = (payload: unknown, fallbackError: string) => {
  if (typeof payload === "object" && payload !== null && "error" in payload) {
    const error = payload.error;
    const details = "details" in payload ? payload.details : undefined;
    if (typeof error === "string" && typeof details === "string") {
      return { error, details };
    }
    if (typeof error === "string") {
      return { error };
    }
  }
  return { error: fallbackError };
};

export const coverLetterRoutes = new Elysia({
  prefix: toApiScopedPath(API_ENDPOINTS.coverLettersBase),
})
  .get(
    "/",
    {
      detail: openapiDetail("Cover Letters", "List saved cover letters for the current profile."),
      response: coverLettersListResponses,
    },
    async ({ status }) =>
      status(HTTP_STATUS_OK, (await listCoverLetters()).map(toCoverLetterEntityResponse)),
  )
  .post(
    "/",
    {
      detail: openapiDetail(
        "Cover Letters",
        "Create a cover letter from company, role, and body content.",
      ),
      body: coverLetterMutationBodySchema,
      response: coverLetterEntityResponses,
    },
    async ({ body, status }) => {
      const result = await createCoverLetter(body);
      return status(HTTP_STATUS_CREATED, toCoverLetterEntityResponse(result.coverLetter));
    },
  )
  .get(
    "/:id",
    {
      detail: openapiDetail("Cover Letters", "Retrieve a cover letter by id with full content."),
      params: coverLetterIdParamsSchema,
      response: coverLetterEntityResponses,
    },
    async ({ params, status }) => {
      const state: RouteSetState = {};
      const coverLetter = await getCoverLetterById(params.id, state);
      if (!coverLetter) {
        return status(HTTP_STATUS_NOT_FOUND, { error: API_ERROR_COVER_LETTER_NOT_FOUND });
      }
      return status(HTTP_STATUS_OK, toCoverLetterEntityResponse(coverLetter));
    },
  )
  .put(
    "/:id",
    {
      detail: openapiDetail(
        "Cover Letters",
        "Replace cover letter fields for an existing document.",
      ),
      params: coverLetterIdParamsSchema,
      body: coverLetterUpdateBodySchema,
      response: coverLetterEntityResponses,
    },
    async ({ params, body, status }) => {
      const state: RouteSetState = {};
      const result = await updateCoverLetter(params.id, body, state);
      if (!("id" in result) || state.status === HTTP_STATUS_NOT_FOUND) {
        return status(HTTP_STATUS_NOT_FOUND, { error: API_ERROR_COVER_LETTER_NOT_FOUND });
      }
      return status(HTTP_STATUS_OK, toCoverLetterEntityResponse(result));
    },
  )
  .delete(
    "/:id",
    {
      detail: openapiDetail("Cover Letters", "Delete a cover letter by id from saved documents."),
      params: coverLetterIdParamsSchema,
      response: coverLetterDeleteResponses,
    },
    async ({ params, status }) => {
      const state: RouteSetState = {};
      await deleteCoverLetter(params.id, state);
      if (state.status === HTTP_STATUS_NOT_FOUND) {
        return status(HTTP_STATUS_NOT_FOUND, { error: API_ERROR_COVER_LETTER_NOT_FOUND });
      }
      return status(HTTP_STATUS_OK, { success: true, id: params.id });
    },
  )
  .post(
    toApiChildPath(API_ENDPOINTS.coverLettersBase, API_ENDPOINTS.coverLettersGenerate),
    {
      detail: openapiDetail(
        "Cover Letters",
        "Generate a cover letter with AI from job and profile context.",
      ),
      body: generateCoverLetterBodySchema,
      response: generateCoverLetterResponses,
    },
    async ({ body, status }) => {
      const state: RouteSetState = {};
      const result = await handleGenerateCoverLetter(body, state);
      if (state.status === HTTP_STATUS_SERVICE_UNAVAILABLE) {
        return status(
          HTTP_STATUS_SERVICE_UNAVAILABLE,
          toSimpleRouteErrorPayload(result, API_ERROR_UNKNOWN),
        );
      }
      if (state.status === HTTP_STATUS_INTERNAL_SERVER_ERROR) {
        return status(
          HTTP_STATUS_INTERNAL_SERVER_ERROR,
          toSimpleRouteErrorPayload(result, API_ERROR_UNKNOWN),
        );
      }
      if (state.status === HTTP_STATUS_CREATED && "coverLetter" in result && result.coverLetter) {
        return status(HTTP_STATUS_CREATED, {
          message: result.message,
          coverLetter: toCoverLetterEntityResponse(result.coverLetter),
        });
      }
      if ("content" in result && result.content) {
        return status(HTTP_STATUS_OK, {
          message: result.message,
          content: result.content,
        });
      }
      return status(
        HTTP_STATUS_INTERNAL_SERVER_ERROR,
        toSimpleRouteErrorPayload(result, API_ERROR_UNKNOWN),
      );
    },
  )
  .post(
    "/:id/export",
    {
      detail: openapiDetail("Cover Letters", "Export a cover letter as a downloadable attachment."),
      params: coverLetterIdParamsSchema,
      body: coverLetterExportBodySchema,
      response: coverLetterExportResponses,
    },
    async ({
      params,
      body,
      status,
    }: {
      params: CoverLetterIdParams;
      body: CoverLetterExportBody;
      status: RouteStatus;
    }) => {
      const state: RouteSetState = {};
      const result = await exportCoverLetterAttachment(
        params.id,
        body.format,
        state,
        body.template,
      );
      if (state.status === HTTP_STATUS_NOT_FOUND) {
        return status(
          HTTP_STATUS_NOT_FOUND,
          toSimpleRouteErrorPayload(result, API_ERROR_COVER_LETTER_NOT_FOUND),
        );
      }
      if (state.status === HTTP_STATUS_INTERNAL_SERVER_ERROR) {
        return status(
          HTTP_STATUS_INTERNAL_SERVER_ERROR,
          toSimpleRouteErrorPayload(result, API_ERROR_UNKNOWN),
        );
      }
      return status(HTTP_STATUS_OK, result);
    },
  );

