import { and, desc, eq, like, or } from "drizzle-orm";
import { db } from "../db/client";
import { applications, jobs, savedJobs } from "../db/schema/jobs";
import { gamificationService } from "../services/gamification-service";
import type { JobListQuery } from "./jobs-route-contracts";

type JobRow = typeof jobs.$inferSelect;
type SavedJobRow = typeof savedJobs.$inferSelect;
type ApplicationRow = typeof applications.$inferSelect;
type RouteErrorBody = { error: string };
type SaveJobResult =
  | { status: typeof HTTP_STATUS_NOT_FOUND; body: RouteErrorBody }
  | { status: null; body: { message: string; saved: SavedJobRow } }
  | { status: typeof HTTP_STATUS_CREATED; body: SavedJobRow };
type NewApplicationBody = {
  id: string;
  jobId: string;
  status: string;
  appliedDate: string;
  notes: string;
  timeline: Array<{ status: string; date: string; notes: string }>;
};
type CreateApplicationResult =
  | { status: typeof HTTP_STATUS_NOT_FOUND; body: RouteErrorBody }
  | { status: null; body: { message: string; application: ApplicationRow } }
  | { status: typeof HTTP_STATUS_CREATED; body: NewApplicationBody };
type UpdateApplicationResult =
  | { status: typeof HTTP_STATUS_NOT_FOUND; body: RouteErrorBody }
  | { status: null; body: ApplicationRow };

const isOneOf = <T extends string>(values: readonly T[], value: string): value is T =>
  values.some((entry) => entry === value);

const parsePositiveInteger = (value: string, fallback: number): number => {
  const parsedValue = Number.parseInt(value, DECIMAL_RADIX);
  if (!Number.isFinite(parsedValue) || parsedValue < 1) {
    return fallback;
  }
  return parsedValue;
};

const buildJobsWhereClause = (query: JobListQuery) => {
  const conditions = [];
  if (query.q) {
    conditions.push(
      or(
        like(jobs.title, `%${query.q}%`),
        like(jobs.company, `%${query.q}%`),
        like(jobs.description, `%${query.q}%`),
      ),
    );
  }
  if (query.location) {
    conditions.push(like(jobs.location, `%${query.location}%`));
  }
  if (query.remote === "true") {
    conditions.push(eq(jobs.remote, true));
  }
  if (query.experienceLevel && isOneOf(JOB_EXPERIENCE_LEVELS, query.experienceLevel)) {
    conditions.push(eq(jobs.experienceLevel, query.experienceLevel));
  }
  if (query.studioType && isOneOf(JOB_STUDIO_TYPES, query.studioType)) {
    conditions.push(eq(jobs.studioType, query.studioType));
  }
  return conditions.length > 0 ? and(...conditions) : undefined;
};

const filterJobsByAttributes = (jobRows: JobRow[], query: JobListQuery): JobRow[] => {
  let filtered = jobRows;
  if (query.platform && isOneOf(JOB_SUPPORTED_PLATFORMS, query.platform)) {
    const platform = query.platform;
    filtered = filtered.filter((job) => job.platforms?.includes(platform));
  }
  if (query.genre && isOneOf(JOB_GAME_GENRES, query.genre)) {
    const genre = query.genre;
    filtered = filtered.filter((job) => job.gameGenres?.includes(genre));
  }
  return filtered;
};

export const listJobs = async (query: JobListQuery) => {
  const pageNum = parsePositiveInteger(
    query.page || String(JOB_QUERY_DEFAULT_PAGE),
    JOB_QUERY_DEFAULT_PAGE,
  );
  const requestedLimit = parsePositiveInteger(
    query.limit || String(JOB_QUERY_DEFAULT_LIMIT),
    JOB_QUERY_DEFAULT_LIMIT,
  );
  const limitNum = Math.min(requestedLimit, JOB_QUERY_MAX_LIMIT);
  const offset = (pageNum - 1) * limitNum;
  const results = await db
    .select()
    .from(jobs)
    .where(buildJobsWhereClause(query))
    .orderBy(desc(jobs.postedDate))
    .limit(limitNum)
    .offset(offset);
  const filtered = filterJobsByAttributes(results, query);

  return {
    jobs: filtered,
    page: pageNum,
    limit: limitNum,
    total: filtered.length,
  };
};

export const getJobById = async (id: string) => {
  const rows = await db.select().from(jobs).where(eq(jobs.id, id));
  return rows[0] ?? null;
};

export const saveJob = async (jobId: string): Promise<SaveJobResult> => {
  const job = await getJobById(jobId);
  if (!job) {
    return {
      status: HTTP_STATUS_NOT_FOUND,
      body: { error: API_ERROR_JOB_NOT_FOUND },
    };
  }

  const existing = await db.select().from(savedJobs).where(eq(savedJobs.jobId, jobId));
  if (existing.length > 0) {
    return {
      status: null,
      body: { message: API_MESSAGE_JOB_ALREADY_SAVED, saved: existing[0] },
    };
  }

  const newSaved = {
    id: generateId(),
    jobId,
    savedAt: new Date().toISOString(),
  };

  await db.insert(savedJobs).values(newSaved);
  gamificationService.trackActionFireAndForget(
    "jobsSaved",
    ROUTE_GAMIFICATION_XP.jobsSaved,
    "job_saved",
  );
  return {
    status: HTTP_STATUS_CREATED,
    body: newSaved,
  };
};

export const deleteSavedJob = async (jobId: string) => {
  const deletedRows = await db
    .delete(savedJobs)
    .where(eq(savedJobs.jobId, jobId))
    .returning({ id: savedJobs.id });
  return { success: true, deletedCount: deletedRows.length };
};

export const listSavedJobs = async () =>
  db
    .select({
      id: savedJobs.id,
      jobId: savedJobs.jobId,
      savedAt: savedJobs.savedAt,
      job: jobs,
    })
    .from(savedJobs)
    .leftJoin(jobs, eq(savedJobs.jobId, jobs.id))
    .orderBy(desc(savedJobs.savedAt));

export const createApplication = async (
  jobId: string,
  notes: string,
): Promise<CreateApplicationResult> => {
  const job = await getJobById(jobId);
  if (!job) {
    return {
      status: HTTP_STATUS_NOT_FOUND,
      body: { error: API_ERROR_JOB_NOT_FOUND },
    };
  }

  const existing = await db.select().from(applications).where(eq(applications.jobId, jobId));
  if (existing.length > 0) {
    return {
      status: null,
      body: { message: API_MESSAGE_ALREADY_APPLIED, application: existing[0] },
    };
  }

  const now = new Date().toISOString();
  const newApplication = {
    id: generateId(),
    jobId,
    status: "applied",
    appliedDate: now,
    notes,
    timeline: [
      {
        status: "applied",
        date: now,
        notes: "Application submitted",
      },
    ],
  };

  await db.insert(applications).values(newApplication);
  gamificationService.trackActionFireAndForget(
    "jobApplications",
    ROUTE_GAMIFICATION_XP.jobApplications,
    "job_applied",
  );
  return {
    status: HTTP_STATUS_CREATED,
    body: newApplication,
  };
};

export const updateApplication = async (
  id: string,
  newStatus: string | undefined,
  notes: string | undefined,
): Promise<UpdateApplicationResult> => {
  const existing = await db.select().from(applications).where(eq(applications.id, id));
  if (existing.length === 0) {
    return {
      status: HTTP_STATUS_NOT_FOUND,
      body: { error: API_ERROR_APPLICATION_NOT_FOUND },
    };
  }

  const app = existing[0];
  const timeline = app.timeline || [];

  if (newStatus && newStatus !== app.status) {
    timeline.push({
      status: newStatus,
      date: new Date().toISOString(),
      notes: notes || "",
    });
  }

  const updates: Record<string, unknown> = {
    updatedAt: new Date().toISOString(),
    timeline,
  };

  if (newStatus) updates.status = newStatus;
  if (notes !== undefined) updates.notes = notes;

  await db.update(applications).set(updates).where(eq(applications.id, id));
  const updated = await db.select().from(applications).where(eq(applications.id, id));
  return {
    status: null,
    body: updated[0],
  };
};

export const listApplications = async () =>
  db
    .select({
      id: applications.id,
      jobId: applications.jobId,
      status: applications.status,
      appliedDate: applications.appliedDate,
      notes: applications.notes,
      timeline: applications.timeline,
      createdAt: applications.createdAt,
      updatedAt: applications.updatedAt,
      job: jobs,
    })
    .from(applications)
    .leftJoin(jobs, eq(applications.jobId, jobs.id))
    .orderBy(desc(applications.appliedDate));

import { AI_DEFAULT_TEMPERATURE, AI_MAX_TOKENS_MATCH } from "@bao/shared/constants/ai-generation";
import { API_ERROR_UNKNOWN } from "@bao/shared/constants/api-errors";
import { DEFAULT_UNSPECIFIED_LABEL } from "@bao/shared/constants/default-labels";
import {
  JOB_DEFAULT_RECOMMENDATION_REASON,
  JOB_DEFAULT_RECOMMENDATION_SCORE,
  JOB_QUERY_DEFAULT_LIMIT,
} from "@bao/shared/constants/jobs";
import { safeParseJson } from "@bao/shared/utils/json";
import { settle } from "@bao/shared/utils/promise";
import { desc } from "drizzle-orm";
import { db } from "../db/client";
import { jobs } from "../db/schema/jobs";
import { settings } from "../db/schema/settings";
import { userProfile } from "../db/schema/user";
import { AIService } from "../services/ai/ai-service";
import { createServerLogger } from "../utils/logger";

type JobRecommendationMatch = {
  jobIndex: number;
  matchScore: number;
  matchReason: string;
};

type JobRow = typeof jobs.$inferSelect;
type UserProfileRow = typeof userProfile.$inferSelect;
type JobRecommendation = JobRow & {
  matchScore: number;
  matchReason: string;
  rank: number;
};

export type JobRecommendationsResponse = {
  recommendations: JobRecommendation[];
  reason: string;
  aiPowered: boolean;
  provider?: string;
};

const jobsRoutesLogger = createServerLogger("jobs-routes");
const RECOMMENDATION_JSON_REGEX = /\[[\s\S]*\]/;

const isJobRecommendationMatch = (value: unknown): value is JobRecommendationMatch =>
  typeof value === "object" &&
  value !== null &&
  "jobIndex" in value &&
  typeof value.jobIndex === "number" &&
  Number.isFinite(value.jobIndex) &&
  "matchScore" in value &&
  typeof value.matchScore === "number" &&
  Number.isFinite(value.matchScore) &&
  "matchReason" in value &&
  typeof value.matchReason === "string";

const toRecentPostingRecommendations = (recentJobs: JobRow[]): JobRecommendation[] =>
  recentJobs.map((job, index) => ({
    ...job,
    matchScore: JOB_DEFAULT_RECOMMENDATION_SCORE,
    matchReason: JOB_DEFAULT_RECOMMENDATION_REASON,
    rank: index + 1,
  }));

const toFallbackRecommendations = (
  recentJobs: JobRow[],
  reason: string,
): JobRecommendationsResponse => ({
  recommendations: toRecentPostingRecommendations(recentJobs),
  reason,
  aiPowered: false,
});

const buildRecommendationPrompt = (profile: UserProfileRow, recentJobs: JobRow[]): string => {
  const userSkills = [...(profile.technicalSkills || []), ...(profile.softSkills || [])].join(", ");
  const userExperience =
    profile.currentRole && profile.currentCompany
      ? `${profile.currentRole} at ${profile.currentCompany}`
      : profile.summary || "Gaming professional";
  const userGoals =
    typeof profile.careerGoals === "object" && profile.careerGoals !== null
      ? JSON.stringify(profile.careerGoals)
      : "Career growth in gaming industry";
  const jobsSummary = recentJobs
    .map(
      (job, idx) =>
        `Job ${idx + 1}: ${job.title} at ${job.company} - ${job.location} - ${job.experienceLevel || DEFAULT_UNSPECIFIED_LABEL}`,
    )
    .join("\n");

  return `You are a career matching AI assistant. Analyze these jobs against the user profile and score each job from 0-100 based on match quality.

User Profile:
- Skills: ${userSkills || DEFAULT_UNSPECIFIED_LABEL}
- Experience: ${userExperience}
- Career Goals: ${userGoals}
- Years of Experience: ${profile.yearsExperience || DEFAULT_UNSPECIFIED_LABEL}

Available Jobs:
${jobsSummary}

Return a JSON array with match analysis for each job. Format:
[
  {
    "jobIndex": 0,
    "matchScore": 85,
    "matchReason": "Strong skills alignment with technical requirements"
  }
]

Provide realistic scores based on skills match, experience level alignment, and career goals fit.`;
};

const parseRecommendationMatches = (responseContent: string): JobRecommendationMatch[] => {
  const jsonMatch = responseContent.match(RECOMMENDATION_JSON_REGEX);
  if (!jsonMatch) return [];
  const parsed = safeParseJson(jsonMatch[0]);
  return Array.isArray(parsed) ? parsed.filter(isJobRecommendationMatch) : [];
};

const mapRecommendationMatches = (
  recentJobs: JobRow[],
  matches: JobRecommendationMatch[],
): JobRecommendation[] =>
  matches
    .map((match) => {
      const job = recentJobs[match.jobIndex];
      if (!job) return null;
      return {
        ...job,
        matchScore: match.matchScore,
        matchReason: match.matchReason,
        rank: 0,
      };
    })
    .filter((job): job is JobRecommendation => job !== null)
    .sort((a, b) => b.matchScore - a.matchScore)
    .map((job, index) => ({
      ...job,
      rank: index + 1,
    }));

export const getRecommendations = async (): Promise<JobRecommendationsResponse> => {
  const profileRows = await db.select().from(userProfile).limit(1);
  const profile = profileRows[0];
  const recentJobs = await db
    .select()
    .from(jobs)
    .orderBy(desc(jobs.postedDate))
    .limit(JOB_QUERY_DEFAULT_LIMIT);
  if (!profile || recentJobs.length === 0) {
    return toFallbackRecommendations(
      recentJobs,
      profile ? "No jobs available" : "Create your profile for personalized recommendations",
    );
  }

  const settingsResult = await settle(db.select().from(settings).limit(1));
  if (settingsResult.status === "rejected") {
    jobsRoutesLogger.error("Job recommendations error:", settingsResult.reason);
    const details =
      settingsResult.reason instanceof Error ? settingsResult.reason.message : API_ERROR_UNKNOWN;
    return toFallbackRecommendations(recentJobs, `Error generating recommendations: ${details}`);
  }

  const aiService = AIService.fromSettings(settingsResult.value[0]);
  const response = await aiService.generate(buildRecommendationPrompt(profile, recentJobs), {
    purpose: "jobMatch",
    temperature: AI_DEFAULT_TEMPERATURE,
    maxTokens: AI_MAX_TOKENS_MATCH,
  });
  if (response.error) {
    return toFallbackRecommendations(recentJobs, `AI recommendations failed: ${response.error}`);
  }

  const matches = parseRecommendationMatches(response.content);
  if (matches.length === 0) {
    return toFallbackRecommendations(recentJobs, "AI analysis completed but no matches found");
  }

  return {
    recommendations: mapRecommendationMatches(recentJobs, matches),
    reason: "AI-powered personalized job recommendations",
    aiPowered: true,
    provider: response.provider,
  };
};

import { API_ERROR_JOB_NOT_FOUND, API_ERROR_UNKNOWN } from "@bao/shared/constants/api-errors";
import { API_MESSAGE_JOB_REFRESH_COMPLETE } from "@bao/shared/constants/api-messages";
import { API_ENDPOINTS, toApiScopedPath } from "@bao/shared/constants/endpoints";
import {
  HTTP_STATUS_CREATED,
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_NOT_FOUND,
  HTTP_STATUS_OK,
} from "@bao/shared/constants/http";
import { settle } from "@bao/shared/utils/promise";
import { Elysia } from "elysia";
import { JobAggregator } from "../services/jobs/job-aggregator";
import { createServerLogger } from "../utils/logger";
import { openapiDetail } from "../utils/openapi-detail";
import {
  applicationsListResponses,
  applyJobBodySchema,
  applyJobResponses,
  deleteSavedJobResponses,
  jobEntityResponses,
  jobIdParamsSchema,
  jobsListQuerySchema,
  jobsListResponses,
  jobsRefreshResponses,
  recommendationsResponses,
  savedJobParamsSchema,
  savedJobsListResponses,
  saveJobBodySchema,
  saveJobResponses,
  updateApplicationBodySchema,
  updateApplicationParamsSchema,
  updateApplicationResponses,
} from "./jobs-route-contracts";
import {
  createApplication,
  deleteSavedJob,
  getJobById,
  listApplications,
  listJobs,
  listSavedJobs,
  saveJob,
  updateApplication,
} from "./jobs-route-listing";
import { getRecommendations } from "./jobs-route-recommendations";

const jobsRoutesLogger = createServerLogger("jobs-routes");

export const jobsRoutes = new Elysia({
  prefix: toApiScopedPath(API_ENDPOINTS.jobsBase),
})
  .get(
    "/",
    {
      detail: openapiDetail("Jobs", "List jobs in the feed with filters and pagination."),
      query: jobsListQuerySchema,
      response: jobsListResponses,
    },
    async ({ query, status }) => status(HTTP_STATUS_OK, await listJobs(query)),
  )
  .get(
    "/:id",
    {
      detail: openapiDetail("Jobs", "Retrieve a single job posting by id with details."),
      params: jobIdParamsSchema,
      response: jobEntityResponses,
    },
    async ({ params, status }) => {
      const job = await getJobById(params.id);
      if (!job) {
        return status(HTTP_STATUS_NOT_FOUND, { error: API_ERROR_JOB_NOT_FOUND });
      }
      return status(HTTP_STATUS_OK, job);
    },
  )
  .post(
    "/save",
    {
      detail: openapiDetail("Jobs", "Save a job posting to the user's shortlist."),
      body: saveJobBodySchema,
      response: saveJobResponses,
    },
    async ({ body, status }) => {
      const result = await saveJob(body.jobId);
      if (result.status === HTTP_STATUS_NOT_FOUND) {
        return status(HTTP_STATUS_NOT_FOUND, result.body);
      }
      if (result.status === HTTP_STATUS_CREATED) {
        return status(HTTP_STATUS_CREATED, result.body);
      }
      return status(HTTP_STATUS_OK, result.body);
    },
  )
  .delete(
    "/save/:jobId",
    {
      detail: openapiDetail("Jobs", "Remove a job posting from the user's shortlist."),
      params: savedJobParamsSchema,
      response: deleteSavedJobResponses,
    },
    async ({ params, status }) => status(HTTP_STATUS_OK, await deleteSavedJob(params.jobId)),
  )
  .get(
    "/saved",
    {
      detail: openapiDetail("Jobs", "List jobs the user has saved to their shortlist."),
      response: savedJobsListResponses,
    },
    async ({ status }) => status(HTTP_STATUS_OK, await listSavedJobs()),
  )
  .post(
    "/apply",
    {
      detail: openapiDetail("Jobs", "Record a manual job application for a posting."),
      body: applyJobBodySchema,
      response: applyJobResponses,
    },
    async ({ body, status }) => {
      const result = await createApplication(body.jobId, body.notes ?? "");
      if (result.status === HTTP_STATUS_NOT_FOUND) {
        return status(HTTP_STATUS_NOT_FOUND, result.body);
      }
      if (result.status === HTTP_STATUS_CREATED) {
        return status(HTTP_STATUS_CREATED, result.body);
      }
      return status(HTTP_STATUS_OK, result.body);
    },
  )
  .put(
    "/apply/:id",
    {
      detail: openapiDetail("Jobs", "Update application status and notes for a job."),
      params: updateApplicationParamsSchema,
      body: updateApplicationBodySchema,
      response: updateApplicationResponses,
    },
    async ({ params, body, status }) => {
      const result = await updateApplication(params.id, body.status, body.notes);
      if (result.status === HTTP_STATUS_NOT_FOUND) {
        return status(HTTP_STATUS_NOT_FOUND, result.body);
      }
      return status(HTTP_STATUS_OK, result.body);
    },
  )
  .get(
    "/applications",
    {
      detail: openapiDetail("Jobs", "List job applications with status and timestamps."),
      response: applicationsListResponses,
    },
    async ({ status }) => status(HTTP_STATUS_OK, await listApplications()),
  )
  .get(
    "/recommendations",
    {
      detail: openapiDetail("Jobs", "Retrieve personalized job recommendations for the profile."),
      response: recommendationsResponses,
    },
    async ({ status }) => status(HTTP_STATUS_OK, await getRecommendations()),
  )
  .post(
    "/refresh",
    {
      detail: openapiDetail("Jobs", "Refresh the job feed from configured providers."),
      response: jobsRefreshResponses,
    },
    async ({ status }) => {
      const aggregator = new JobAggregator();
      const refreshResult = await settle(aggregator.refreshJobs());
      if (refreshResult.status === "rejected") {
        jobsRoutesLogger.error("Job refresh error:", refreshResult.reason);
        return status(HTTP_STATUS_INTERNAL_SERVER_ERROR, {
          error: `Job refresh failed: ${
            refreshResult.reason instanceof Error ? refreshResult.reason.message : API_ERROR_UNKNOWN
          }`,
        });
      }

      return status(HTTP_STATUS_OK, {
        message: API_MESSAGE_JOB_REFRESH_COMPLETE,
        status: "completed",
        totalJobs: refreshResult.value.total,
        newJobs: refreshResult.value.new,
        updatedJobs: refreshResult.value.updated,
      });
    },
  );

