    const res = await requestJson<{ error: string }>(app, "POST", API_ENDPOINTS.jobsApply, {
      jobId: "nonexistent",
    });
    expect(res.status).toBe(HTTP_STATUS_NOT_FOUND);
    expect(res.body.error).toBe("Job not found");
