import {
  HTTP_STATUS_NOT_FOUND,
  HTTP_STATUS_OK,
  HTTP_STATUS_UNAUTHORIZED,
} from "@bao/shared/constants/http";
import {
  SCHEMA_MAX_ITEMS_LARGE,
  SCHEMA_MAX_LENGTH_LONG,
} from "@bao/shared/constants/schema-limits";
import { t } from "elysia";
import type { Static } from "typebox";

export const openaiV1ChatMessageSchema = t.Object({
  role: t.Union([t.Literal("system"), t.Literal("user"), t.Literal("assistant")]),
  content: t.String({ maxLength: SCHEMA_MAX_LENGTH_LONG }),
});

export const openaiV1ChatCompletionsBodySchema = t.Object({
  model: t.String({ minLength: 1 }),
  messages: t.Array(openaiV1ChatMessageSchema, {
    minItems: 1,
    maxItems: SCHEMA_MAX_ITEMS_LARGE,
  }),
  temperature: t.Optional(t.Number({ minimum: 0, maximum: 2 })),
  max_tokens: t.Optional(t.Number({ minimum: 1, maximum: SCHEMA_MAX_LENGTH_LONG })),
  stream: t.Optional(t.Boolean()),
});

export type OpenAIV1ChatCompletionsBody = Static<typeof openaiV1ChatCompletionsBodySchema>;

export const openaiV1ModelParamsSchema = t.Object({
  model: t.String({ minLength: 1 }),
});

export type OpenAIV1ModelParams = Static<typeof openaiV1ModelParamsSchema>;

export const openaiV1ErrorBodySchema = t.Object({
  error: t.Object({
    message: t.String(),
    type: t.String(),
    code: t.Optional(t.Union([t.String(), t.Null()])),
  }),
});

export const openaiV1ModelObjectSchema = t.Object({
  id: t.String(),
  object: t.Literal("model"),
  created: t.Number(),
  owned_by: t.String(),
});

export const openaiV1ModelsListSchema = t.Object({
  object: t.Literal("list"),
  data: t.Array(openaiV1ModelObjectSchema),
});

export const openaiV1ModelsListResponses = {
  [HTTP_STATUS_OK]: openaiV1ModelsListSchema,
  [HTTP_STATUS_UNAUTHORIZED]: openaiV1ErrorBodySchema,
} as const;

export const openaiV1ModelGetResponses = {
  [HTTP_STATUS_OK]: openaiV1ModelObjectSchema,
  [HTTP_STATUS_NOT_FOUND]: openaiV1ErrorBodySchema,
  [HTTP_STATUS_UNAUTHORIZED]: openaiV1ErrorBodySchema,
} as const;

import { AI_DEFAULT_TEMPERATURE_CREATIVE } from "@bao/shared/constants/ai-generation";
import { AI_PROVIDER_CATALOG } from "@bao/shared/constants/ai-provider";
import {
  API_ERROR_OPENAI_V1_GENERATION_FAILED,
  API_ERROR_OPENAI_V1_MODEL_NOT_FOUND,
} from "@bao/shared/constants/api-errors";
import {
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_NOT_FOUND,
  HTTP_STATUS_OK,
} from "@bao/shared/constants/http";
import { COUNT_FOUR } from "@bao/shared/constants/numeric";
import { SCHEMA_MAX_LENGTH_LONG } from "@bao/shared/constants/schema-limits";
import { MS_PER_SECOND } from "@bao/shared/constants/time";
import { AI_PROVIDER_IDS, type AIProviderType } from "@bao/shared/types/ai";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import { generateId } from "@bao/shared/utils/validation";
import { getAIService } from "./ai-route-support";
import type { OpenAIV1ChatCompletionsBody } from "./openai-v1-route-contracts";

const isAIProviderType = (value: string): value is AIProviderType =>
  (AI_PROVIDER_IDS as readonly string[]).includes(value);

const MODEL_ID_SEPARATOR = "/";
const OPENAI_V1_EPOCH_SECONDS = () => Math.floor(Date.now() / MS_PER_SECOND);

export type OpenAIV1ModelRecord = {
  id: string;
  object: "model";
  created: number;
  owned_by: string;
};

const routeResult = <const Status extends number, Body>(status: Status, body: Body) => ({
  status,
  body,
});

export const toOpenAIV1Error = (
  message: string,
  type = "invalid_request_error",
  code: string | null = null,
) => ({
  error: { message, type, code },
});

export const buildOpenAIV1ModelId = (provider: AIProviderType, model: string): string =>
  `${provider}${MODEL_ID_SEPARATOR}${model}`;

export const parseOpenAIV1ModelId = (
  modelId: string,
): { provider: AIProviderType | null; model: string } => {
  const separatorIndex = modelId.indexOf(MODEL_ID_SEPARATOR);
  if (separatorIndex <= 0) {
    return { provider: null, model: modelId };
  }
  const provider = modelId.slice(0, separatorIndex);
  const model = modelId.slice(separatorIndex + 1);
  return {
    provider: isAIProviderType(provider) ? provider : null,
    model,
  };
};

export const listOpenAIV1Models = async (): Promise<OpenAIV1ModelRecord[]> => {
  const aiService = await getAIService();
  const created = OPENAI_V1_EPOCH_SECONDS();
  const statuses = await aiService.getAvailableProviders();
  const models: OpenAIV1ModelRecord[] = [];

  for (const status of statuses) {
    if (!status.available) {
      continue;
    }
    const activeModel = aiService.getActiveModel(status.provider);
    const modelCandidates = [
      activeModel,
      status.selectedModel,
      status.availableModels?.[0],
      "default",
    ].filter((entry): entry is string => typeof entry === "string" && entry.length > 0);
    const modelName = modelCandidates[0] ?? "default";
    models.push({
      id: buildOpenAIV1ModelId(status.provider, modelName),
      object: "model",
      created,
      owned_by: status.provider,
    });
  }

  // When no live providers are available, expose catalog hints so SDK clients can discover IDs.
  if (models.length === 0) {
    for (const provider of AI_PROVIDER_CATALOG) {
      const hint = provider.modelHints[0] ?? "default";
      models.push({
        id: buildOpenAIV1ModelId(provider.id, hint),
        object: "model",
        created,
        owned_by: provider.id,
      });
    }
  }

  return models;
};

export const getOpenAIV1Model = async (modelId: string) => {
  const models = await listOpenAIV1Models();
  const match = models.find((entry) => entry.id === modelId);
  if (!match) {
    return routeResult(
      HTTP_STATUS_NOT_FOUND,
      toOpenAIV1Error(
        API_ERROR_OPENAI_V1_MODEL_NOT_FOUND,
        "invalid_request_error",
        "model_not_found",
      ),
    );
  }
  return routeResult(HTTP_STATUS_OK, match);
};

const extractUserPrompt = (messages: OpenAIV1ChatCompletionsBody["messages"]): string => {
  const reversed = [...messages].reverse();
  const lastUser = reversed.find((message) => message.role === "user");
  return lastUser?.content ?? messages[messages.length - 1]?.content ?? "";
};

const extractSystemPrompt = (
  messages: OpenAIV1ChatCompletionsBody["messages"],
): string | undefined => {
  const systemMessages = messages.filter((message) => message.role === "system");
  if (systemMessages.length === 0) {
    return;
  }
  return systemMessages.map((message) => message.content).join("\n\n");
};

const generateOpenAIV1ChatContent = async (body: OpenAIV1ChatCompletionsBody) => {
  const parsed = parseOpenAIV1ModelId(body.model);
  const aiService = await getAIService();
  const prompt = extractUserPrompt(body.messages);
  const systemPrompt = extractSystemPrompt(body.messages);
  const conversationMessages = body.messages
    .filter((message) => message.role !== "system")
    .map((message) => ({
      role: message.role,
      content: message.content,
    }));

  const generationResult = await settle(
    aiService.generate(prompt, {
      purpose: "chat",
      systemPrompt,
      messages: conversationMessages,
      temperature: body.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
      maxTokens: body.max_tokens ?? SCHEMA_MAX_LENGTH_LONG,
      provider: parsed.provider ?? undefined,
      model: parsed.model || undefined,
    }),
  );

  if (generationResult.status === "rejected") {
    return {
      ok: false as const,
      error: toErrorMessage(generationResult.reason, API_ERROR_OPENAI_V1_GENERATION_FAILED),
    };
  }

  const response = generationResult.value;
  if (response.error) {
    return { ok: false as const, error: response.error };
  }

  return { ok: true as const, prompt, content: response.content };
};

const buildOpenAIV1ChatCompletionBody = (input: {
  model: string;
  prompt: string;
  content: string;
}) => {
  const promptTokens = Math.max(1, Math.ceil(input.prompt.length / COUNT_FOUR));
  const completionTokens = Math.max(1, Math.ceil(input.content.length / COUNT_FOUR));
  return {
    id: `chatcmpl-${generateId()}`,
    object: "chat.completion" as const,
    created: OPENAI_V1_EPOCH_SECONDS(),
    model: input.model,
    choices: [
      {
        index: 0,
        message: {
          role: "assistant" as const,
          content: input.content,
        },
        finish_reason: "stop" as const,
      },
    ],
    usage: {
      prompt_tokens: promptTokens,
      completion_tokens: completionTokens,
      total_tokens: promptTokens + completionTokens,
    },
  };
};

export const createOpenAIV1ChatCompletion = async (body: OpenAIV1ChatCompletionsBody) => {
  const models = await listOpenAIV1Models();
  const requested = models.find((entry) => entry.id === body.model);
  if (!requested) {
    return routeResult(
      HTTP_STATUS_NOT_FOUND,
      toOpenAIV1Error(
        API_ERROR_OPENAI_V1_MODEL_NOT_FOUND,
        "invalid_request_error",
        "model_not_found",
      ),
    );
  }

  const generated = await generateOpenAIV1ChatContent(body);
  if (!generated.ok) {
    return routeResult(
      HTTP_STATUS_INTERNAL_SERVER_ERROR,
      toOpenAIV1Error(generated.error, "server_error"),
    );
  }

  return routeResult(
    HTTP_STATUS_OK,
    buildOpenAIV1ChatCompletionBody({
      model: body.model,
      prompt: generated.prompt,
      content: generated.content,
    }),
  );
};

export const createOpenAIV1ChatCompletionStream = async (
  body: OpenAIV1ChatCompletionsBody,
): Promise<Response> => {
  const completionResult = await createOpenAIV1ChatCompletion(body);
  if (completionResult.status !== HTTP_STATUS_OK) {
    return new Response(JSON.stringify(completionResult.body), {
      status: completionResult.status,
      headers: { "content-type": "application/json" },
    });
  }

  const completion = completionResult.body;
  const chunkId = completion.id;
  const content = completion.choices[0]?.message.content ?? "";
  const encoder = new TextEncoder();

  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      const firstChunk = {
        id: chunkId,
        object: "chat.completion.chunk",
        created: completion.created,
        model: completion.model,
        choices: [
          {
            index: 0,
            delta: { role: "assistant", content },
            finish_reason: null,
          },
        ],
      };
      controller.enqueue(encoder.encode(`data: ${JSON.stringify(firstChunk)}\n\n`));
      const finalChunk = {
        id: chunkId,
        object: "chat.completion.chunk",
        created: completion.created,
        model: completion.model,
        choices: [
          {
            index: 0,
            delta: {},
            finish_reason: "stop",
          },
        ],
      };
      controller.enqueue(encoder.encode(`data: ${JSON.stringify(finalChunk)}\n\n`));
      controller.enqueue(encoder.encode("data: [DONE]\n\n"));
      controller.close();
    },
  });

  return new Response(stream, {
    status: HTTP_STATUS_OK,
    headers: {
      "content-type": "text/event-stream; charset=utf-8",
      "cache-control": "no-cache",
      connection: "keep-alive",
    },
  });
};

import {
  API_ERROR_INVALID_API_KEY,
  API_ERROR_MISSING_AUTH_HEADER,
} from "@bao/shared/constants/api-errors";
import { OPENAI_V1_ENDPOINT_PREFIX, OPENAI_V1_ENDPOINTS } from "@bao/shared/constants/endpoints";
import { HTTP_STATUS_NOT_FOUND, HTTP_STATUS_OK } from "@bao/shared/constants/http";
import { MS_PER_MINUTE } from "@bao/shared/constants/time";
import { Elysia } from "elysia";
import { authenticateApiKey } from "../middleware/auth";
import { corsPlugin } from "../middleware/cors";
import { openapiDetail } from "../utils/openapi-detail";
import { rateLimit } from "../utils/rate-limit";
import { resolveRateLimitClientKey } from "../utils/request";
import {
  openaiV1ChatCompletionsBodySchema,
  openaiV1ModelParamsSchema,
  openaiV1ModelGetResponses,
  openaiV1ModelsListResponses,
} from "./openai-v1-route-contracts";
import {
  createOpenAIV1ChatCompletion,
  createOpenAIV1ChatCompletionStream,
  getOpenAIV1Model,
  listOpenAIV1Models,
} from "./openai-v1-route-support";

const resolveOpenAIV1AuthErrorCode = (error: string): string => {
  if (error === API_ERROR_INVALID_API_KEY) {
    return "invalid_api_key";
  }
  if (error === API_ERROR_MISSING_AUTH_HEADER) {
    return "missing_authorization";
  }
  return "invalid_request_error";
};

function toOpenAIV1ChildPath(endpointPath: string): string {
  if (endpointPath === OPENAI_V1_ENDPOINT_PREFIX) {
    return "/";
  }
  if (!endpointPath.startsWith(OPENAI_V1_ENDPOINT_PREFIX)) {
    return endpointPath;
  }
  return endpointPath.slice(OPENAI_V1_ENDPOINT_PREFIX.length) || "/";
}

/**
 * OpenAI Chat Completions API surface for external SDK clients.
 * Mounted at OPENAI_V1_ENDPOINT_PREFIX alongside the main API app.
 */
export const openaiV1Routes = new Elysia({
  name: "openai-v1",
  prefix: OPENAI_V1_ENDPOINT_PREFIX,
})
  .use(corsPlugin)
  .beforeHandle(async ({ request, status }) => {
    const failure = await authenticateApiKey(request);
    if (!failure) {
      return;
    }
    return status(failure.status, {
      error: {
        message: failure.error,
        type: "invalid_request_error",
        code: resolveOpenAIV1AuthErrorCode(failure.error),
      },
    });
  })
  .use(
    rateLimit({
      duration: MS_PER_MINUTE,
      max: 60,
      generator: (request) => resolveRateLimitClientKey(request),
    }),
  )
  .get(
    toOpenAIV1ChildPath(OPENAI_V1_ENDPOINTS.models),
    {
      detail: openapiDetail(
        "OpenAI V1",
        "List available models through the OpenAI-compatible API.",
      ),
      response: openaiV1ModelsListResponses,
    },
    async ({ status }) => {
      const data = await listOpenAIV1Models();
      return status(HTTP_STATUS_OK, { object: "list" as const, data });
    },
  )
  .get(
    `${toOpenAIV1ChildPath(OPENAI_V1_ENDPOINTS.models)}/:model`,
    {
      detail: openapiDetail(
        "OpenAI V1",
        "Retrieve a single model by id through the OpenAI-compatible API.",
      ),
      params: openaiV1ModelParamsSchema,
      response: openaiV1ModelGetResponses,
    },
    async ({ params, status }) => {
      const result = await getOpenAIV1Model(decodeURIComponent(params.model));
      // Branch per status so each arm narrows to its declared response schema.
      if (result.status === HTTP_STATUS_NOT_FOUND) {
        return status(HTTP_STATUS_NOT_FOUND, result.body);
      }
      return status(HTTP_STATUS_OK, result.body);
    },
  )
  .post(
    toOpenAIV1ChildPath(OPENAI_V1_ENDPOINTS.chatCompletions),
    {
      detail: openapiDetail(
        "OpenAI V1",
        "Create a chat completion through the OpenAI-compatible API.",
      ),
      body: openaiV1ChatCompletionsBodySchema,
      // No response map: `stream: true` returns a raw SSE Response, which a
      // per-status body schema cannot describe alongside the JSON completion.
    },
    async ({ body, status }) => {
      if (body.stream) {
        return createOpenAIV1ChatCompletionStream(body);
      }
      const result = await createOpenAIV1ChatCompletion(body);
      return status(result.status, result.body);
    },
  );

import { afterEach, beforeAll, describe, expect, test } from "bun:test";
