let originalScrapeJobsForPortal: typeof scraperService.scrapeJobsForPortal;

const successfulScraperResult: ScraperOperationResult = {
  scraped: 2,
  upserted: 2,
  errors: [],
  enrichment: {
    enabled: true,
    enrichedRecords: 2,
    warnings: [],
