  };
};

const isNonEmptyString = (value?: string): value is string =>
  typeof value === "string" && value.trim().length > 0;

const NON_CONCRETE_MODELS = new Set([LOCAL_AI_AUTO_DETECT_MODEL, "auto-router"]);
const isSupportedHuggingFaceModel = (
  value: string,
): value is (typeof HUGGING_FACE_SUPPORTED_MODELS)[number] =>
  HUGGING_FACE_SUPPORTED_MODELS.some((model) => model === value);

const resolveProviderModel = (
  provider: AIProvider,
  providerName: AIProviderType,
  routingTarget: FailoverRequest["routingTarget"],
  providerOptions?: Omit<GenerateOptions, "messages">,
): string | undefined => {
  const providerModel = isNonEmptyString(provider.model) ? provider.model.trim() : undefined;
  const requestedModel =
    providerName === routingTarget.provider && isNonEmptyString(providerOptions?.model)
      ? providerOptions.model.trim()
      : undefined;
  const requestedModelIsConcrete =
    requestedModel &&
    !NON_CONCRETE_MODELS.has(requestedModel) &&
    (providerName !== "huggingface" || isSupportedHuggingFaceModel(requestedModel));

  return (requestedModelIsConcrete ? requestedModel : undefined) ?? providerModel;
};

const buildProviderOptionsForProvider = (
  request: FailoverRequest,
  providerName: AIProviderType,
  provider: AIProvider,
): Omit<GenerateOptions, "messages"> | undefined => {
  const providerOptions = withRequestedProvider(providerName, request.providerOptions);
  const model = resolveProviderModel(
    provider,
    providerName,
    request.routingTarget,
    providerOptions,
  );

  if (!providerOptions) {
    return model
      ? {
          purpose: request.routingTarget.purpose,
          provider: providerName,
          model,
        }
      : {
          purpose: request.routingTarget.purpose,
          provider: providerName,
        };
  }

  const { temperature, maxTokens, topP, topK, timeout, systemPrompt } = providerOptions;
  return {
    purpose: request.routingTarget.purpose,
    provider: providerName,
    ...(model ? { model } : {}),
    temperature,
    maxTokens,
    topP,
    topK,
    timeout,
    systemPrompt,
  };
};

export const mergePromptWithContext = (prompt: string, options?: GenerateOptions): string => {
  const messageHistory = options?.messages;
  if (!messageHistory || messageHistory.length === 0) {
    return prompt;
  }

  const historyLines = messageHistory
    .slice(-AI_CHAT_CONTEXT_MESSAGE_LIMIT)
    .map((message, index) => `${index + 1}. ${message.role.toUpperCase()}: ${message.content}`)
    .join("\n");

  return [
    "Use the following conversation history to keep responses contextually consistent.",
    "Conversation history:",
    historyLines,
    "Current user message:",
    prompt,
  ].join("\n\n");
};

export const toProviderOptions = (
  routingTarget: {
    purpose: GenerateOptions["purpose"] extends infer P ? P : string;
    provider: AIProviderType;
    model?: string;
  },
  options?: GenerateOptions,
): Omit<GenerateOptions, "messages"> | undefined => {
  if (!options) {
    return routingTarget.model
      ? {
          purpose: routingTarget.purpose,
          provider: routingTarget.provider,
          model: routingTarget.model,
        }
      : {
          purpose: routingTarget.purpose,
          provider: routingTarget.provider,
        };
  }

  const { temperature, maxTokens, topP, topK, timeout, systemPrompt } = options;
  return {
    purpose: routingTarget.purpose,
    provider: routingTarget.provider,
    model: routingTarget.model,
    temperature,
    maxTokens,
    topP,
    topK,
    timeout,
    systemPrompt,
  };
};

const resolveAvailableProvider = async (
  providers: Map<AIProviderType, AIProvider>,
  providerName: AIProviderType,
  errors: ProviderFailure[],
): Promise<AIProvider | null> => {
  const provider = providers.get(providerName);
  if (!provider) {
    return null;
  }

  const availabilityResult = await settle(provider.isAvailable());
  if (availabilityResult.status === "rejected") {
    pushProviderError(
      errors,
      providerName,
      describeProviderError(providerName, "isAvailable", availabilityResult.reason),
    );
    return null;
  }
  if (!availabilityResult.value) {
    pushProviderError(errors, providerName, "Provider not available");
    return null;
  }
  return provider;
};

const generateFromProvider = async (
  request: FailoverRequest,
  providerName: AIProviderType,
  errors: ProviderFailure[],
): Promise<AIResponse | null> => {
  const provider = await resolveAvailableProvider(request.providers, providerName, errors);
  if (!provider) {
    return null;
  }

  const providerOptions = buildProviderOptionsForProvider(request, providerName, provider);
  const generationResult = await settle(
    provider.generate(request.contextualPrompt, providerOptions),
  );
  if (generationResult.status === "rejected") {
    pushProviderError(
      errors,
      providerName,
      describeProviderError(providerName, "generate", generationResult.reason),
    );
    return null;
  }

  if (!generationResult.value) {
    return null;
  }
  if (generationResult.value.error) {
    pushProviderError(errors, providerName, generationResult.value.error);
    return null;
  }
  return generationResult.value;
};

export type GenerateFailoverResult =
  | { success: true; data: AIResponse; errors: ProviderFailure[] }
  | {
      success: false;
      error: { code: "ALL_PROVIDERS_GENERATE_FAILED"; message: string };
      errors: ProviderFailure[];
    };

export const generateWithProviderFailover = async (
  request: FailoverRequest,
): Promise<GenerateFailoverResult> => {
  const errors: ProviderFailure[] = [];
  const response = await generateWithFailoverAtIndex(request, errors, 0);
  if (response) {
    return { success: true, data: response, errors };
  }

  aiFailoverLogger.error("All providers failed to generate", {
    failures: errors,
  });

  return {
    success: false,
    error: {
      code: "ALL_PROVIDERS_GENERATE_FAILED",
      message: API_ERROR_ALL_PROVIDERS_GENERATE_FAILED,
    },
    errors,
  };
};

const generateWithFailoverAtIndex = async (
  request: FailoverRequest,
  errors: ProviderFailure[],
  index: number,
): Promise<AIResponse | null> => {
  const providerName = request.providerOrder[index];
  if (!providerName) {
    return null;
  }

  const response = await generateFromProvider(request, providerName, errors);
  if (response) {
    return response;
  }

  return generateWithFailoverAtIndex(request, errors, index + 1);
};

export const buildGenerateFailure = (errors: ProviderFailure[]): Error => {
  aiFailoverLogger.error("All providers failed to generate", {
    failures: errors,
  });
  return new Error(API_ERROR_ALL_PROVIDERS_GENERATE_FAILED);
};

export const streamWithProviderFailover = async function* (
  request: FailoverRequest,
): AsyncGenerator<
  { chunk: string; provider: AIProviderType },
  { streamed: boolean; errors: ProviderFailure[] }
> {
  const errors: ProviderFailure[] = [];
  return yield* streamWithFailoverAtIndex(request, errors, 0);
};

const streamProviderIterator = async function* (
  providerName: AIProviderType,
  iterator: AsyncIterator<string>,
  errors: ProviderFailure[],
  hasYielded: boolean,
): AsyncGenerator<
  { chunk: string; provider: AIProviderType },
  { hasYielded: boolean; failed: boolean }
> {
  const nextChunkResult = await settle(iterator.next());
  if (nextChunkResult.status === "rejected") {
    pushProviderError(
      errors,
      providerName,
      describeProviderError(providerName, "stream", nextChunkResult.reason),
    );
    return { hasYielded, failed: true };
  }
  if (nextChunkResult.value.done) {
    return { hasYielded, failed: false };
  }
  yield { chunk: nextChunkResult.value.value, provider: providerName };
  return yield* streamProviderIterator(providerName, iterator, errors, true);
};

const streamWithFailoverAtIndex = async function* (
  request: FailoverRequest,
  errors: ProviderFailure[],
  index: number,
): AsyncGenerator<
  { chunk: string; provider: AIProviderType },
  { streamed: boolean; errors: ProviderFailure[] }
> {
  const providerName = request.providerOrder[index];
  if (!providerName) {
    return { streamed: false, errors };
  }

  const provider = await resolveAvailableProvider(request.providers, providerName, errors);
  if (!provider) {
    return yield* streamWithFailoverAtIndex(request, errors, index + 1);
  }

  const providerStream = provider.stream(
    request.contextualPrompt,
    buildProviderOptionsForProvider(request, providerName, provider),
  );
  const iterator = providerStream[Symbol.asyncIterator]();
  const streamResult = yield* streamProviderIterator(providerName, iterator, errors, false);
  if (streamResult.hasYielded && !streamResult.failed) {
    return { streamed: true, errors };
  }

  return yield* streamWithFailoverAtIndex(request, errors, index + 1);
};

export const buildStreamFailure = (errors: ProviderFailure[]): Error => {
  aiFailoverLogger.error("All providers failed to stream", {
    failures: errors,
  });
  return new Error(API_ERROR_ALL_PROVIDERS_STREAM_FAILED);
};

import { AI_PROVIDER_DEFAULT_ORDER } from "@bao/shared/constants/ai-provider";
import type {
  AIProviderConfig,
  AIProviderType,
  AIRouting,
  AIRoutingPurpose,
  GenerateOptions,
} from "@bao/shared/types/ai";
import { createProvider, isConfiguredProviderConfig } from "./ai-provider-config";
import type { AIProvider } from "./provider-interface";

export const initializeProviders = (
  configs: AIProviderConfig[],
): Map<AIProviderType, AIProvider> => {
  const providers = new Map<AIProviderType, AIProvider>();

  for (const config of configs) {
    if (!(config.enabled && isConfiguredProviderConfig(config))) {
      continue;
    }

    const provider = createProvider(config);
    if (provider) {
      providers.set(config.provider, provider);
    }
  }

  return providers;
};

export const buildProviderFailoverOrder = (
  configs: readonly AIProviderConfig[],
  preferredProvider?: AIProviderType,
): AIProviderType[] => {
  const enabledProviders: AIProviderType[] = Array.from(
    new Set(
      configs
        .filter((config) => config.enabled && isConfiguredProviderConfig(config))
        .map((config) => config.provider),
    ),
  );

  const ordered: AIProviderType[] = [];
  const preferred =
    preferredProvider && enabledProviders.includes(preferredProvider)
      ? preferredProvider
      : undefined;

  if (preferred) {
    ordered.push(preferred);
  }

  for (const provider of AI_PROVIDER_DEFAULT_ORDER) {
    if (!ordered.includes(provider) && enabledProviders.includes(provider)) {
      ordered.push(provider);
    }
  }

  for (const provider of enabledProviders) {
    if (!ordered.includes(provider)) {
      ordered.push(provider);
    }
  }

  return ordered;
};

export const rebuildProviderFailoverOrderFromProviders = (
  providers: ReadonlyMap<AIProviderType, AIProvider>,
  preferredProvider?: AIProviderType,
): AIProviderType[] => {
  const providerConfigs: AIProviderConfig[] = [];

  for (const provider of providers.keys()) {
    providerConfigs.push({ provider, enabled: true });
  }

  return buildProviderFailoverOrder(providerConfigs, preferredProvider);
};

export const resolveRoutingTarget = (
  routing: AIRouting,
  preferredProvider: AIProviderType | undefined,
  options?: GenerateOptions,
): {
  purpose: AIRoutingPurpose;
  provider: AIProviderType;
  model?: string;
} => {
  const purpose = options?.purpose ?? "chat";
  const routedTarget = routing[purpose] ?? routing.chat;
  const provider =
    options?.provider ??
    routedTarget?.provider ??
    preferredProvider ??
    AI_PROVIDER_DEFAULT_ORDER[0];
  const model =
    typeof options?.model === "string" && options.model.trim().length > 0
      ? options.model.trim()
      : routedTarget?.model;

  return model ? { purpose, provider, model } : { purpose, provider };
};

export const buildProviderOrder = (
  failoverOrder: readonly AIProviderType[],
  routing: AIRouting,
  preferredProvider: AIProviderType | undefined,
  options?: GenerateOptions,
): AIProviderType[] => {
  const preferredTarget = resolveRoutingTarget(routing, preferredProvider, options);
  const ordered: AIProviderType[] = [preferredTarget.provider];

  if (preferredProvider && !ordered.includes(preferredProvider)) {
    ordered.push(preferredProvider);
  }

  for (const provider of failoverOrder) {
    if (!ordered.includes(provider)) {
      ordered.push(provider);
    }
  }

  return ordered;
};

import { expect, spyOn, test } from "bun:test";
import { HUGGING_FACE_DEFAULT_MODEL } from "@bao/shared/constants/ai-provider";
import { API_ERROR_ALL_PROVIDERS_GENERATE_FAILED } from "@bao/shared/constants/api-errors";
import type { AIProviderConfig, AIRouting } from "@bao/shared/types/ai";
import { settle } from "@bao/shared/utils/promise";
import { AIService } from "./ai-service";
import { LocalProvider } from "./local-provider";

const createFailoverConfigs = (): AIProviderConfig[] => [
  {
    provider: "local",
    enabled: true,
    baseUrl: "http://localhost:11434/v1",
    model: "local-model",
  },
  {
    provider: "huggingface",
    enabled: true,
    apiKey: "hf_test_token",
    model: HUGGING_FACE_DEFAULT_MODEL,
  },
];

const createFailoverRouting = (): AIRouting => ({
  chat: { provider: "local", model: "auto-router" },
  interviewQuestions: { provider: "local" },
  interviewFeedback: { provider: "local" },
  resume: { provider: "local" },
  coverLetter: { provider: "local" },
  emailResponse: { provider: "local" },
  jobMatch: { provider: "local" },
  scrapeEnrichment: { provider: "local" },
  automationFieldMapping: { provider: "local" },
});

test("generate fails over to the first healthy provider with a concrete provider model", async () => {
  const service = new AIService(createFailoverConfigs(), "local", createFailoverRouting());

  const localProvider = service.getProvider("local");
  const huggingfaceProvider = service.getProvider("huggingface");

  expect(localProvider).toBeDefined();
  expect(huggingfaceProvider).toBeDefined();
  if (!(localProvider && huggingfaceProvider)) {
    throw new Error("Expected local + huggingface providers to be registered");
  }

  spyOn(LocalProvider, "inspectEndpoint").mockResolvedValue({
    provider: "local",
    checkedAt: "2026-03-31T00:00:00.000Z",
    code: "unreachable",
    message: "Endpoint did not respond",
    endpoint: "http://localhost:11434/v1",
  });
  spyOn(huggingfaceProvider, "isAvailable").mockResolvedValue(true);

  let receivedProvider: string | undefined;
  let receivedModel: string | undefined;
  const generateSpy = spyOn(huggingfaceProvider, "generate");
  generateSpy.mockImplementation((_prompt, options) => {
    receivedProvider = options?.provider;
    receivedModel = options?.model;
    return Promise.resolve({
      id: "test-response",
      provider: "huggingface",
      model: options?.model ?? "",
      content: "ok",
    });
  });

  const response = await service.generate("hello", {
    provider: "local",
    model: "auto-router",
  });

  expect(generateSpy).toHaveBeenCalledTimes(1);
  expect(response.provider).toBe("huggingface");
  expect(response.model).toBe(HUGGING_FACE_DEFAULT_MODEL);
  expect(receivedProvider).toBe("huggingface");
  expect(receivedModel).toBe(HUGGING_FACE_DEFAULT_MODEL);
});

test("generate throws when every provider in the failover order fails", async () => {
  const service = new AIService(createFailoverConfigs(), "local", createFailoverRouting());

  const localProvider = service.getProvider("local");
  const huggingfaceProvider = service.getProvider("huggingface");

  expect(localProvider).toBeDefined();
  expect(huggingfaceProvider).toBeDefined();
  if (!(localProvider && huggingfaceProvider)) {
    throw new Error("Expected local + huggingface providers to be registered");
  }

  spyOn(LocalProvider, "inspectEndpoint").mockResolvedValue({
    provider: "local",
    checkedAt: "2026-03-31T00:00:00.000Z",
    code: "healthy",
    message: "Endpoint healthy",
    endpoint: "http://localhost:11434/v1",
    selectedModel: "local-model",
    availableModels: ["local-model"],
  });
  spyOn(localProvider, "isAvailable").mockResolvedValue(true);
  spyOn(huggingfaceProvider, "isAvailable").mockResolvedValue(true);
  spyOn(localProvider, "generate").mockResolvedValue({
    id: "local-failed",
    provider: "local",
    model: "local-model",
    content: "",
    error: "local generate failed",
  });
  spyOn(huggingfaceProvider, "generate").mockResolvedValue({
    id: "hf-failed",
    provider: "huggingface",
    model: HUGGING_FACE_DEFAULT_MODEL,
    content: "",
    error: "huggingface generate failed",
  });

  const result = await settle(service.generate("hello"));
  expect(result.status).toBe("rejected");
  if (result.status !== "rejected") {
    throw new Error("Expected generate to reject when all providers fail");
  }
  expect(result.reason).toBeInstanceOf(Error);
  expect(String(result.reason)).toBe(`Error: ${API_ERROR_ALL_PROVIDERS_GENERATE_FAILED}`);
  expect(String(result.reason)).not.toContain("local generate failed");
  expect(String(result.reason)).not.toContain("huggingface generate failed");
  expect(String(result.reason)).not.toContain("hf_test_token");
});

import {
  AI_PROVIDER_DEFAULT,
  AI_PROVIDER_DEFAULT_ORDER,
  DEFAULT_AI_ROUTING,
  LOCAL_AI_AUTO_DETECT_MODEL,
  normalizeAIRouting,
} from "@bao/shared/constants/ai-provider";
import type {
  AIProviderConfig,
  AIProviderStatus,
  AIProviderType,
  AIResponse,
  AIRouting,
  GenerateOptions,
} from "@bao/shared/types/ai";
import { settle } from "@bao/shared/utils/promise";
import { isTestRuntime } from "../../config/env";
import { TEST_AI_PROVIDER_NAME } from "./ai-deterministic-provider";
import {
  buildProviderConfigs,
  createDeterministicServiceState,
  createProvider,
  resolvePreferredProvider,
} from "./ai-provider-config";
import { detectLocalProviders, getProviderStatuses } from "./ai-provider-diagnostics";
import {
  buildGenerateFailure,
  buildStreamFailure,
  generateWithProviderFailover,
  mergePromptWithContext,
  streamWithProviderFailover,
  toProviderOptions,
} from "./ai-provider-failover";
import {
  buildProviderFailoverOrder,
  buildProviderOrder,
  initializeProviders,
  rebuildProviderFailoverOrderFromProviders,
  resolveRoutingTarget,
} from "./ai-provider-state";
import type { AIProvider } from "./provider-interface";

type AIServiceSettings = Parameters<typeof buildProviderConfigs>[0];

/**
 * Multi-provider AI service with ordered failover across configured providers.
 */
export class AIService {
  private providers: Map<AIProviderType, AIProvider> = new Map();
  private preferredProvider?: AIProviderType;
  private routing: AIRouting = DEFAULT_AI_ROUTING;
  private providerFailoverOrder: AIProviderType[] = [];

  constructor(
    configs: AIProviderConfig[],
    preferredProvider?: AIProviderType,
    routing?: AIRouting,
  ) {
    this.preferredProvider = preferredProvider;
    this.routing = normalizeAIRouting(routing, preferredProvider ?? AI_PROVIDER_DEFAULT);
    this.providers = initializeProviders(configs);
    this.providerFailoverOrder = buildProviderFailoverOrder(configs, this.preferredProvider);
  }

  /**
   * Create an AIService from a settings DB row.
   * Converts the flat settings config into AIProviderConfig[] format.
   * Used by WebSocket handlers, route handlers, and services.
   */
  static fromSettings(settings?: AIServiceSettings): AIService {
    if (isTestRuntime) {
      return AIService.createDeterministicTestService();
    }

    const configs = buildProviderConfigs(settings);
    const preferredProvider = resolvePreferredProvider(
      settings?.aiRouting?.chat?.provider ?? settings?.preferredProvider,
    );
    const routing = normalizeAIRouting(
      settings?.aiRouting,
      preferredProvider,
      settings?.preferredModel,
    );
    return new AIService(configs, preferredProvider, routing);
  }

  private static createDeterministicTestService(): AIService {
    const service = new AIService([], TEST_AI_PROVIDER_NAME, DEFAULT_AI_ROUTING);
    const deterministicState = createDeterministicServiceState();
    service.providers = deterministicState.providers;
    service.providerFailoverOrder = [...deterministicState.providerFailoverOrder];
    service.preferredProvider = deterministicState.preferredProvider;
    service.routing = deterministicState.routing;
    return service;
  }

  private refreshProviderFailoverOrder(): void {
    this.providerFailoverOrder = rebuildProviderFailoverOrderFromProviders(
      this.providers,
      this.preferredProvider,
    );
  }

  private async resolveHealthyProviderOrder(options?: GenerateOptions): Promise<AIProviderType[]> {
    const baseOrder = buildProviderOrder(
      this.providerFailoverOrder,
      this.routing,
      this.preferredProvider,
      options,
    );
    const availabilityResult = await settle(this.getAvailableProviders());
    if (availabilityResult.status === "rejected") {
      return baseOrder;
    }

    const healthyProviders = new Set(
      availabilityResult.value
        .filter((status) => status.available)
        .map((status) => status.provider),
    );
    if (healthyProviders.size === 0) {
      return baseOrder;
    }

    const healthyOrder = baseOrder.filter((provider) => healthyProviders.has(provider));
    return healthyOrder.length > 0 ? healthyOrder : baseOrder;
  }

  /**
   * Get a specific provider by name
   */
  getProvider(name?: AIProviderType): AIProvider | null {
    if (name) {
      return this.providers.get(name) || null;
    }

    if (this.preferredProvider && this.providers.has(this.preferredProvider)) {
      return this.providers.get(this.preferredProvider) || null;
    }

    return this.providers.values().next().value || null;
  }

  /**
   * Generate a response with ordered provider failover. Throws when every provider fails.
   */
  async generate(prompt: string, options?: GenerateOptions): Promise<AIResponse> {
    const contextualPrompt = mergePromptWithContext(prompt, options);
    const routingTarget = resolveRoutingTarget(this.routing, this.preferredProvider, options);
    const providerOrder = await this.resolveHealthyProviderOrder(options);
    const providerOptions = toProviderOptions(routingTarget, options);
    const failoverResult = await generateWithProviderFailover({
      providers: this.providers,
      providerOrder,
      routingTarget,
      contextualPrompt,
      providerOptions,
    });
    if (!failoverResult.success) {
      throw buildGenerateFailure(failoverResult.errors);
    }
    return failoverResult.data;
  }

  /**
   * Stream a response with ordered provider failover. Throws when every provider fails.
   */
  async *stream(
    prompt: string,
    options?: GenerateOptions,
  ): AsyncGenerator<{ chunk: string; provider: AIProviderType }> {
    const contextualPrompt = mergePromptWithContext(prompt, options);
    const routingTarget = resolveRoutingTarget(this.routing, this.preferredProvider, options);
    const providerOrder = await this.resolveHealthyProviderOrder(options);
    const providerOptions = toProviderOptions(routingTarget, options);
    const streamResult = yield* streamWithProviderFailover({
      providers: this.providers,
      providerOrder,
      routingTarget,
      contextualPrompt,
      providerOptions,
    });
    if (streamResult.streamed) {
      return;
    }
    throw buildStreamFailure(streamResult.errors);
  }

  /**
   * Get status of all providers
   */
  async getAvailableProviders(): Promise<AIProviderStatus[]> {
    return getProviderStatuses(this.providers, (providerType) => this.getActiveModel(providerType));
  }

  /**
   * Detect local AI providers (RamaLama, Ollama)
   */
  async detectLocalProviders(): Promise<
    Array<{
      baseUrl: string;
      name: string;
      available: boolean;
      availableModels?: readonly string[];
      diagnosticCode?: AIProviderStatus["diagnosticCode"];
      message?: string;
    }>
  > {
    return detectLocalProviders();
  }

  /**
   * Update preferred provider
   */
  setPreferredProvider(provider: AIProviderType): void {
    if (this.providers.has(provider)) {
      this.preferredProvider = provider;
      this.refreshProviderFailoverOrder();
    }
  }

  /**
   * Add a new provider at runtime
   */
  addProvider(config: AIProviderConfig): boolean {
    const provider = createProvider(config);
    if (!provider) {
      return false;
    }

    this.providers.set(config.provider, provider);
    this.refreshProviderFailoverOrder();
    return true;
  }

  /**
   * Remove a provider
   */
  removeProvider(provider: AIProviderType): boolean {
    const deleted = this.providers.delete(provider);

    if (deleted) {
      this.providerFailoverOrder = this.providerFailoverOrder.filter((p) => p !== provider);

      if (this.preferredProvider === provider) {
        this.preferredProvider = this.providerFailoverOrder[0];
        if (!this.preferredProvider) {
          this.preferredProvider = AI_PROVIDER_DEFAULT_ORDER[0];
        }
      }

      this.refreshProviderFailoverOrder();
    }

    return deleted;
  }

  /**
   * Get list of configured providers
   */
  getConfiguredProviders(): AIProviderType[] {
    return Array.from(this.providers.keys());
  }

  /**
   * Get the current provider failover order
   */
  getProviderFailoverOrder(): AIProviderType[] {
    return [...this.providerFailoverOrder];
  }

  /**
   * Get the current purpose-aware routing table.
   */
  getRouting(): AIRouting {
    return normalizeAIRouting(this.routing, this.preferredProvider ?? AI_PROVIDER_DEFAULT);
  }

  /**
   * Get the active model name for a given provider (detected or configured).
   */
  getActiveModel(providerType: AIProviderType): string | null {
    const provider = this.providers.get(providerType);
    if (!provider) return null;
    const model = provider.model;
    return model && model !== LOCAL_AI_AUTO_DETECT_MODEL ? model : null;
  }
}

import Anthropic from "@anthropic-ai/sdk";
import {
  AI_DEFAULT_MAX_TOKENS_CLAUDE,
  AI_DEFAULT_TEMPERATURE_CREATIVE,
} from "@bao/shared/constants/ai-generation";
import { API_ERROR_AI_STREAMING_FAILED } from "@bao/shared/constants/api-errors";
import type { AIResponse, GenerateOptions } from "@bao/shared/types/ai";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import { BaseAIProvider } from "./provider-interface";

/**
 * Anthropic Claude AI Provider
 */
export class ClaudeProvider extends BaseAIProvider {
  name = "claude" as const;
  model: string;
  private client: Anthropic;

  constructor(apiKey: string, model = "claude-sonnet-5") {
    super(apiKey);
    this.model = model;
    this.client = new Anthropic({ apiKey });
  }

  private resolveModel(options?: GenerateOptions): string {
    return typeof options?.model === "string" && options.model.trim().length > 0
      ? options.model.trim()
      : this.model;
  }

  async generate(prompt: string, options?: GenerateOptions): Promise<AIResponse> {
    const startTime = Date.now();
    const model = this.resolveModel(options);
    const responseResult = await settle(
      this.client.messages.create({
        model,
        max_tokens: options?.maxTokens ?? AI_DEFAULT_MAX_TOKENS_CLAUDE,
        temperature: options?.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
        system: options?.systemPrompt,
        messages: [
          {
            role: "user",
            content: prompt,
          },
        ],
      }),
    );
    if (responseResult.status === "rejected") {
      return {
        id: this.generateId(),
        provider: this.name,
        model,
        content: "",
        error: toErrorMessage(responseResult.reason),
        timing: this.createTimingMetrics(startTime),
      };
    }
    const response = responseResult.value;
    const text = response.content
      .filter((block): block is Anthropic.TextBlock => block.type === "text")
      .map((block) => block.text)
      .join("");

    return {
      id: this.generateId(),
      provider: this.name,
      model,
      content: text,
      usage: {
        inputTokens: response.usage.input_tokens,
        outputTokens: response.usage.output_tokens,
      },
      timing: this.createTimingMetrics(startTime),
    };
  }

  async *stream(prompt: string, options?: GenerateOptions): AsyncGenerator<string> {
    const model = this.resolveModel(options);
    const streamResult = await settle(
      Promise.resolve(
        this.client.messages.stream({
          model,
          max_tokens: options?.maxTokens ?? AI_DEFAULT_MAX_TOKENS_CLAUDE,
          temperature: options?.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
          system: options?.systemPrompt,
          messages: [
            {
              role: "user",
              content: prompt,
            },
          ],
        }),
      ),
    );
    if (streamResult.status === "rejected") {
      throw new Error(`${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(streamResult.reason)}`);
    }
    const stream = streamResult.value;

    const iterator = stream[Symbol.asyncIterator]();
    const emitTextEvents = async function* (): AsyncGenerator<string> {
      const nextEventResult = await settle(iterator.next());
      if (nextEventResult.status === "rejected") {
        throw new Error(
          `${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(nextEventResult.reason)}`,
        );
      }
      const nextEvent = nextEventResult.value;
      if (nextEvent.done) {
        return;
      }
      const event = nextEvent.value;
      if (event.type === "content_block_delta" && event.delta.type === "text_delta") {
        yield event.delta.text;
      }
      yield* emitTextEvents();
    };

    yield* emitTextEvents();
  }

  async isAvailable(): Promise<boolean> {
    // Make a minimal request to verify API key
    const model = this.model;
    return (
      (
        await settle(
          this.client.messages.create({
            model,
            max_tokens: 10,
            messages: [{ role: "user", content: "test" }],
          }),
        )
      ).status === "fulfilled"
    );
  }
}

