interface ConversationContext {
  systemPrompt: string;
  messages: Array<Pick<ChatMessage, "role" | "content">>;
}

const AUTOMATION_DOMAIN_PATTERN =
  /\b(automate|automation|rpa|auto[- ]?apply|fill.*form|run.*bot|bot.*apply)\b/i;
const RESUME_DOMAIN_PATTERN = /\b(resume|cv|bullet|experience|education|summary)\b/;
const JOB_SEARCH_DOMAIN_PATTERN = /\b(job|apply|salary|remote|position|company|hiring|opening)\b/;
const INTERVIEW_DOMAIN_PATTERN = /\b(interview|question|answer|practice|mock|prepare)\b/;
const PORTFOLIO_DOMAIN_PATTERN = /\b(portfolio|project|showcase|demo|sample)\b/;
const SKILLS_DOMAIN_PATTERN = /\b(skill|mapping|transfer|learn|career\s*path|gap)\b/;
const DOMAIN_PATTERN_ORDER: Array<[AIChatContextDomain, RegExp]> = [
  ["automation", AUTOMATION_DOMAIN_PATTERN],
  ["resume", RESUME_DOMAIN_PATTERN],
  ["job_search", JOB_SEARCH_DOMAIN_PATTERN],
  ["interview", INTERVIEW_DOMAIN_PATTERN],
  ["portfolio", PORTFOLIO_DOMAIN_PATTERN],
  ["skills", SKILLS_DOMAIN_PATTERN],
];

export class ConversationContextManager {
  private isChatRole(value: string): value is ChatMessage["role"] {
    return value === "user" || value === "assistant" || value === "system";
  }

  /**
   * Auto-detect domain from message content
   */
  inferDomain(message: string): AIChatContextDomain {
    const lower = message.toLowerCase();
    return DOMAIN_PATTERN_ORDER.find(([, pattern]) => pattern.test(lower))?.[0] ?? "general";
  }

  /**
   * Build full context for AI call with conversation history and domain-specific data
   */
  async buildContext(
    sessionId: string,
    currentMessage: string,
    preferredDomain?: AIChatContextDomain,
    runtimeBrand?: BrandSettings | null,
  ): Promise<ConversationContext> {
    const domain = preferredDomain ?? this.inferDomain(currentMessage);
    const messages = await this.loadConversationMessages(sessionId, currentMessage);
    const profile = await this.loadDefaultProfile();
    const domainContext = await this.loadDomainContext(domain);
    const systemPrompt = this.buildSystemPrompt(
      domain,
      profile,
      domainContext,
      runtimeBrand ?? resolveBrandSettings(undefined),
    );
    return { systemPrompt, messages };
  }

  /**
   * Loads recent conversation history and appends the current user message once.
   */
  private async loadConversationMessages(
    sessionId: string,
    currentMessage: string,
  ): Promise<Array<Pick<ChatMessage, "role" | "content">>> {
    const history = await db
      .select()
      .from(chatHistory)
      .where(eq(chatHistory.sessionId, sessionId))
      .orderBy(desc(chatHistory.timestamp))
      .limit(AI_CHAT_HISTORY_FETCH_LIMIT);

    const messages: Array<Pick<ChatMessage, "role" | "content">> = history
      .reverse()
      .flatMap((msg) =>
        this.isChatRole(msg.role)
          ? [
              {
                role: msg.role,
                content: msg.content,
              },
            ]
          : [],
      );

    const lastMessage = messages[messages.length - 1];
    const hasCurrentMessageAtTail =
      lastMessage?.role === "user" && lastMessage.content === currentMessage;
    if (!hasCurrentMessageAtTail) {
      messages.push({ role: "user", content: currentMessage });
    }

    return messages;
  }

  /**
   * Loads the default user profile row when available.
   */
  private async loadDefaultProfile() {
    const profileRows = await db
      .select()
      .from(userProfile)
      .where(eq(userProfile.id, DEFAULT_PROFILE_ID));
    return profileRows[0] ?? null;
  }

  /**
   * Builds the final system prompt from the selected domain and user context.
   */
  private buildSystemPrompt(
    domain: AIChatContextDomain,
    profile: typeof userProfile.$inferSelect | null,
    domainContext: string | null,
    runtimeBrand: BrandSettings,
  ): string {
    const domainSystemPrompts = buildDomainSystemPrompts(runtimeBrand);
    const userContext = profile
      ? `\n\nUser Context:\nName: ${profile.name || "Not set"}\nCurrent Role: ${profile.currentRole || "Not set"}\nYears Experience: ${profile.yearsExperience || "Not set"}\nLocation: ${profile.location || "Not set"}`
      : "";
    const relevantData = domainContext ? `\n\nRelevant Data:\n${domainContext}` : "";
    return `${domainSystemPrompts[domain] || domainSystemPrompts.general}${userContext}${relevantData}\n\n${GAMING_INDUSTRY_CONTEXT}`;
  }

  /**
   * Load domain-specific data from DB
   */
  private async loadDomainContext(domain: AIChatContextDomain): Promise<string | null> {
    const loader = this.getDomainContextLoader(domain);
    if (!loader) {
      return null;
    }
    const contextResult = await settle(loader());

    if (contextResult.status === "rejected") {
      return null;
    }

    return contextResult.value;
  }

  private getDomainContextLoader(
    domain: AIChatContextDomain,
  ): (() => Promise<string | null>) | null {
    const loaders = {
      automation: () => this.loadAutomationContext(),
      interview: () => this.loadInterviewContext(),
      job_search: () => this.loadJobSearchContext(),
      portfolio: () => this.loadPortfolioContext(),
      resume: () => this.loadResumeContext(),
      skills: () => this.loadSkillsContext(),
    } as const;
    return domain === "general" ? null : loaders[domain];
  }

  private async loadResumeContext(): Promise<string | null> {
    const defaultResume = await db.select().from(resumes).limit(1);
    if (defaultResume.length === 0) {
      return null;
    }
    const resume = defaultResume[0];
    return `User's Resume: "${resume.name}"\nSummary: ${resume.summary || "Not set"}\nSkills: ${JSON.stringify(resume.skills || {})}`;
  }

  private async loadJobSearchContext(): Promise<string | null> {
    const saved = await db
      .select({ title: jobs.title, company: jobs.company })
      .from(savedJobs)
      .leftJoin(jobs, eq(savedJobs.jobId, jobs.id))
      .limit(AI_CHAT_CONTEXT_SAVED_JOBS_LIMIT);
    if (saved.length === 0) {
      return null;
    }
    return `Saved Jobs:\n${saved.map((entry) => `- ${entry.title} at ${entry.company}`).join("\n")}`;
  }

  private async loadInterviewContext(): Promise<string | null> {
    const sessions = await db
      .select()
      .from(interviewSessions)
      .orderBy(desc(interviewSessions.createdAt))
      .limit(AI_CHAT_CONTEXT_INTERVIEW_SESSIONS_LIMIT);
    if (sessions.length === 0) {
      return null;
    }
    return `Recent Interview Sessions: ${sessions.length} completed`;
  }

  private async loadPortfolioContext(): Promise<string | null> {
    const projects = await db
      .select()
      .from(portfolioProjects)
      .limit(AI_CHAT_CONTEXT_PORTFOLIO_PROJECTS_LIMIT);
    if (projects.length === 0) {
      return null;
    }
    return `Portfolio Projects:\n${projects.map((project) => `- ${project.title}: ${project.technologies?.join(", ") || "No tech listed"}`).join("\n")}`;
  }

  private async loadSkillsContext(): Promise<string | null> {
    const mappings = await db
      .select()
      .from(skillMappings)
      .limit(AI_CHAT_CONTEXT_SKILL_MAPPINGS_LIMIT);
    if (mappings.length === 0) {
      return null;
    }
    return `Skill Mappings:\n${mappings.map((mapping) => `- ${mapping.gameExpression} → ${mapping.transferableSkill}`).join("\n")}`;
  }

  private async loadAutomationContext(): Promise<string | null> {
    const recentRuns = await db
      .select()
      .from(automationRuns)
      .orderBy(desc(automationRuns.createdAt))
      .limit(AI_CHAT_CONTEXT_AUTOMATION_RUNS_LIMIT);
    const availableResumes = await db
      .select()
      .from(resumes)
      .limit(AI_CHAT_CONTEXT_AVAILABLE_RESUMES_LIMIT);
    const runLines = recentRuns.map(
      (run) =>
        `- [${run.status}] ${run.type} (${run.createdAt})${run.error ? ` Error: ${run.error}` : ""}`,
    );
    const resumeLines = availableResumes.map((resume) => `- "${resume.name}" (ID: ${resume.id})`);
    const parts = [
      ...(runLines.length > 0
        ? [`Recent Automation Runs (${recentRuns.length}):`, ...runLines]
        : []),
      ...(resumeLines.length > 0 ? ["\nAvailable Resumes:", ...resumeLines] : []),
    ];
    return parts.length > 0 ? parts.join("\n") : null;
  }

  /**
   * Generate follow-up suggestions based on domain and last response
   */
  generateFollowUps(domain: AIChatContextDomain): string[] {
    return getContextManagerFollowUps(domain);
  }
}

export const contextManager = new ConversationContextManager();

import {
  AI_PROVIDER_CATALOG,
  AI_PROVIDER_DEFAULT,
  AI_PROVIDER_ID_LIST,
  LOCAL_AI_DEFAULT_ENDPOINT,
  normalizeAIRouting,
} from "@bao/shared/constants/ai-provider";
import { API_MESSAGE_AI_NO_PROVIDERS } from "@bao/shared/constants/api-messages";
import type { AIProviderDiagnostic, AIProviderStatus, AIProviderType } from "@bao/shared/types/ai";
import type { AIProviderDiagnostics } from "@bao/shared/types/settings-contracts";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import type { settings as settingsTable } from "../../db/schema/settings";
import { decryptProviderKeys } from "../../utils/settings-decrypt";
import { AIService } from "./ai-service";

type SettingsRow = typeof settingsTable.$inferSelect;

const resolveKnownProvider = (value?: string | null): (typeof AI_PROVIDER_ID_LIST)[number] =>
  AI_PROVIDER_ID_LIST.find((provider) => provider === value) ?? AI_PROVIDER_DEFAULT;

interface AIControlPlaneProviderRow {
  id: (typeof AI_PROVIDER_CATALOG)[number]["id"];
  nameKey: string;
  descriptionKey: string;
  iconId: (typeof AI_PROVIDER_CATALOG)[number]["iconId"];
  models: string[];
  available: boolean;
  health: "healthy" | "degraded" | "down" | "unconfigured";
  selectedModel?: string;
  diagnosticCode?: AIProviderStatus["diagnosticCode"];
  availableModels?: readonly string[];
  error?: string;
}

/**
 * Shared AI control-plane payload consumed by settings and provider-discovery routes.
 */
export interface AIControlPlaneState {
  aiRouting: ReturnType<typeof normalizeAIRouting>;
  configuredProviders: ReturnType<AIService["getConfiguredProviders"]>;
  error?: string;
  preferredModel: string | null;
  preferredProvider: SettingsRow["preferredProvider"];
  providerDiagnostics?: AIProviderDiagnostics;
  providers: AIControlPlaneProviderRow[];
}

/**
 * Diagnostics carry readonly model lists, while the HTTP response contracts
 * declare plain arrays. Routes serialize through here so settings and AI
 * provider-discovery share one conversion.
 */
export const toSerializableProviderDiagnostics = (
  diagnostics: AIProviderDiagnostics | undefined,
) =>
  diagnostics === undefined
    ? undefined
    : Object.fromEntries(
        Object.entries(diagnostics).map(([provider, { availableModels, ...diagnostic }]) => [
          provider,
          // Destructured out rather than set to undefined: an explicit undefined
          // fails TypeBox optional-property validation at runtime.
          availableModels ? { ...diagnostic, availableModels: [...availableModels] } : diagnostic,
        ]),
      );

/**
 * Provider rows carry the same readonly model lists as diagnostics; routes
 * serialize through here so the wire contract sees plain arrays.
 */
export const toSerializableProviderRows = (rows: readonly AIControlPlaneProviderRow[]) =>
  // Destructured out rather than set to undefined: an explicit undefined fails
  // TypeBox optional-property validation, and spreading the row back in would
  // keep the readonly array type the wire contract rejects.
  rows.map(({ availableModels, ...row }) =>
    availableModels ? { ...row, availableModels: [...availableModels] } : row,
  );

const toProviderDiagnosticEntry = (status: AIProviderStatus): AIProviderDiagnostic => ({
  provider: status.provider,
  code: status.diagnosticCode ?? (status.available ? "healthy" : "error"),
  checkedAt: new Date(status.lastCheck ?? Date.now()).toISOString(),
  endpoint: status.endpoint,
  selectedModel: status.selectedModel,
  availableModels: status.availableModels,
  message: status.error,
});

const buildProviderDiagnostics = (providerStatuses: AIProviderStatus[]): AIProviderDiagnostics => {
  const statusByProvider = new Map(
    providerStatuses.map((status) => [status.provider, status] as const),
  );

  return Object.fromEntries(
    AI_PROVIDER_CATALOG.map((provider) => {
      const status = statusByProvider.get(provider.id);
      return [
        provider.id,
        status
          ? toProviderDiagnosticEntry(status)
          : {
              provider: provider.id,
              code: "unconfigured",
              checkedAt: new Date(0).toISOString(),
            },
      ];
    }),
  );
};

/** Mirrors the local provider's own endpoint resolution so both agree on "configured". */
const resolveLocalEndpoint = (persistedEndpoint: string | null): string => {
  const trimmed = (persistedEndpoint ?? "").trim();
  return trimmed.length > 0 ? trimmed : LOCAL_AI_DEFAULT_ENDPOINT;
};

const hasConfiguredProvider = (row: SettingsRow, providerId: AIProviderType): boolean => {
  if (providerId === "local") {
    // The local provider needs no credential and already falls back to
    // LOCAL_AI_DEFAULT_ENDPOINT when the row holds none (`local-provider.ts`). Demanding
    // a persisted endpoint here reported a reachable on-device runtime as
    // "unconfigured", which emptied `configuredProviders`, made every generation fail
    // with "All providers failed to generate", and degraded the OpenAI-compatible
    // `/v1/models` list to static catalog hints instead of the live model.
    return resolveLocalEndpoint(row.localModelEndpoint).length > 0;
  }
  if (providerId === "gemini") {
    return typeof row.geminiApiKey === "string" && row.geminiApiKey.trim().length > 0;
  }
  if (providerId === "openai") {
    return typeof row.openaiApiKey === "string" && row.openaiApiKey.trim().length > 0;
  }
  if (providerId === "claude") {
    return typeof row.claudeApiKey === "string" && row.claudeApiKey.trim().length > 0;
  }
  return typeof row.huggingfaceToken === "string" && row.huggingfaceToken.trim().length > 0;
};

const resolveFallbackSelectedModel = (
  row: SettingsRow,
  providerId: AIProviderType,
  aiRouting: ReturnType<typeof normalizeAIRouting>,
): string | undefined => {
  if (providerId === "local") {
    return row.localModelName ?? aiRouting.chat.model;
  }
  if (aiRouting.chat.provider === providerId) {
    return aiRouting.chat.model ?? row.preferredModel ?? undefined;
  }
};

const resolveFallbackModels = (
  row: SettingsRow,
  providerId: AIProviderType,
  aiRouting: ReturnType<typeof normalizeAIRouting>,
): string[] => {
  const catalogProvider = AI_PROVIDER_CATALOG.find((provider) => provider.id === providerId);
  const selectedModel = resolveFallbackSelectedModel(row, providerId, aiRouting);
  return selectedModel
    ? [
        selectedModel,
        ...(catalogProvider?.modelHints.filter((hint) => hint !== selectedModel) ?? []),
      ]
    : [...(catalogProvider?.modelHints ?? [])];
};

const buildFallbackProviderRows = (
  row: SettingsRow,
  aiRouting: ReturnType<typeof normalizeAIRouting>,
): AIControlPlaneProviderRow[] =>
  AI_PROVIDER_CATALOG.map((provider) => {
    const configured = hasConfiguredProvider(row, provider.id);
    const selectedModel = resolveFallbackSelectedModel(row, provider.id, aiRouting);

    return {
      id: provider.id,
      nameKey: provider.nameKey,
      descriptionKey: provider.descriptionKey,
      iconId: provider.iconId,
      models: resolveFallbackModels(row, provider.id, aiRouting),
      available: false,
      health: configured ? "degraded" : "unconfigured",
      selectedModel,
      ...(provider.id === "local" &&
      typeof row.localModelEndpoint === "string" &&
      row.localModelEndpoint.trim().length > 0
        ? {
            availableModels: [row.localModelName].filter((value): value is string =>
              Boolean(value),
            ),
          }
        : {}),
    };
  });

const buildFallbackProviderDiagnostics = (
  row: SettingsRow,
  aiRouting: ReturnType<typeof normalizeAIRouting>,
  error: string,
): AIProviderDiagnostics => {
  const checkedAt = new Date().toISOString();

  return Object.fromEntries(
    AI_PROVIDER_CATALOG.map((provider) => {
      const configured = hasConfiguredProvider(row, provider.id);
      const selectedModel = resolveFallbackSelectedModel(row, provider.id, aiRouting);
      const localEndpoint =
        provider.id === "local" &&
        typeof row.localModelEndpoint === "string" &&
        row.localModelEndpoint.trim().length > 0
          ? row.localModelEndpoint.trim()
          : undefined;

      return [
        provider.id,
        {
          provider: provider.id,
          code: configured ? "error" : "unconfigured",
          checkedAt,
          selectedModel,
          ...(localEndpoint ? { endpoint: localEndpoint } : {}),
          ...(configured ? { message: error } : {}),
        } satisfies AIProviderDiagnostic,
      ];
    }),
  );
};

const resolveConfiguredProvidersFromRow = (
  row: SettingsRow,
): ReturnType<AIService["getConfiguredProviders"]> =>
  AI_PROVIDER_CATALOG.filter((provider) => hasConfiguredProvider(row, provider.id)).map(
    (provider) => provider.id,
  );

const buildFallbackControlPlaneState = (row: SettingsRow, error: string): AIControlPlaneState => {
  const aiRouting = normalizeAIRouting(
    row.aiRouting,
    resolveKnownProvider(row.preferredProvider),
    row.preferredModel,
  );

  return {
    aiRouting,
    configuredProviders: resolveConfiguredProvidersFromRow(row),
    preferredProvider: aiRouting.chat.provider,
    preferredModel: aiRouting.chat.model ?? row.preferredModel,
    providers: buildFallbackProviderRows(row, aiRouting),
    providerDiagnostics: buildFallbackProviderDiagnostics(row, aiRouting, error),
    ...(error ? { error } : {}),
  };
};

const buildProviderRows = (
  providerStatuses: AIProviderStatus[],
  aiRouting: ReturnType<typeof normalizeAIRouting>,
): AIControlPlaneProviderRow[] => {
  const statusByProvider = new Map(
    providerStatuses.map((status) => [status.provider, status] as const),
  );

  return AI_PROVIDER_CATALOG.map((provider) => {
    const status = statusByProvider.get(provider.id);
    const selectedModel = status?.selectedModel ?? aiRouting.chat.model;
    const models = selectedModel
      ? [selectedModel, ...provider.modelHints.filter((hint) => hint !== selectedModel)]
      : [...provider.modelHints];

    return {
      id: provider.id,
      nameKey: provider.nameKey,
      descriptionKey: provider.descriptionKey,
      iconId: provider.iconId,
      models,
      available: status?.available ?? false,
      health: status?.health ?? "unconfigured",
      selectedModel,
      diagnosticCode: status?.diagnosticCode,
      availableModels: status?.availableModels,
      error: status?.error,
    };
  });
};

/**
 * Builds the canonical AI control-plane state from one persisted settings row.
 */
export async function buildAIControlPlaneState(
  settingsRow: SettingsRow,
): Promise<AIControlPlaneState> {
  const decryptedKeys = decryptProviderKeys(settingsRow);
  const row = { ...settingsRow, ...decryptedKeys };
  const aiRouting = normalizeAIRouting(
    row.aiRouting,
    resolveKnownProvider(row.preferredProvider),
    row.preferredModel,
  );
  const aiServiceResult = await settle(Promise.resolve(AIService.fromSettings(row)));
  if (aiServiceResult.status !== "fulfilled") {
    return buildFallbackControlPlaneState(
      row,
      toErrorMessage(aiServiceResult.reason, API_MESSAGE_AI_NO_PROVIDERS),
    );
  }

  const aiService = aiServiceResult.value;
  const providerStatusesResult = await settle(aiService.getAvailableProviders());
  if (providerStatusesResult.status !== "fulfilled") {
    return buildFallbackControlPlaneState(
      row,
      toErrorMessage(providerStatusesResult.reason, API_MESSAGE_AI_NO_PROVIDERS),
    );
  }

  const providerStatuses = providerStatusesResult.value;

  return {
    aiRouting,
    configuredProviders: aiService.getConfiguredProviders(),
    preferredProvider: aiRouting.chat.provider,
    preferredModel: aiRouting.chat.model ?? row.preferredModel,
    providerDiagnostics: buildProviderDiagnostics(providerStatuses),
    providers: buildProviderRows(providerStatuses, aiRouting),
  };
}

import {
  AI_DEFAULT_MAX_TOKENS,
  AI_DEFAULT_TEMPERATURE_CREATIVE,
  AI_DEFAULT_TOP_P,
} from "@bao/shared/constants/ai-generation";
import { API_ERROR_AI_STREAMING_FAILED } from "@bao/shared/constants/api-errors";
import { COUNT_FORTY } from "@bao/shared/constants/numeric";
import type { AIResponse, GenerateOptions } from "@bao/shared/types/ai";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import { type GenerativeModel, GoogleGenerativeAI } from "@google/generative-ai";
import { BaseAIProvider } from "./provider-interface";

/**
 * Google Gemini AI Provider
 */
export class GeminiProvider extends BaseAIProvider {
  name = "gemini" as const;
  model: string;
  private client: GoogleGenerativeAI;
  private generativeModel: GenerativeModel;

  constructor(apiKey: string, model = "gemini-2.0-flash-exp") {
    super(apiKey);
    this.model = model;
    this.client = new GoogleGenerativeAI(apiKey);
    this.generativeModel = this.client.getGenerativeModel({ model: this.model });
  }

  private resolveModel(options?: GenerateOptions): string {
    return typeof options?.model === "string" && options.model.trim().length > 0
      ? options.model.trim()
      : this.model;
  }

  async generate(prompt: string, options?: GenerateOptions): Promise<AIResponse> {
    const startTime = Date.now();
    const model = this.resolveModel(options);
    const generativeModel =
      model === this.model ? this.generativeModel : this.client.getGenerativeModel({ model });
    const generationConfig = {
      temperature: options?.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
      maxOutputTokens: options?.maxTokens ?? AI_DEFAULT_MAX_TOKENS,
      topP: options?.topP ?? AI_DEFAULT_TOP_P,
      topK: options?.topK ?? COUNT_FORTY,
    };

    let fullPrompt = prompt;
    if (options?.systemPrompt) {
      fullPrompt = `${options.systemPrompt}\n\n${prompt}`;
    }

    const resultResponse = await settle(
      generativeModel.generateContent({
        contents: [{ role: "user", parts: [{ text: fullPrompt }] }],
        generationConfig,
      }),
    );
    if (resultResponse.status === "rejected") {
      return {
        id: this.generateId(),
        provider: this.name,
        model,
        content: "",
        error: toErrorMessage(resultResponse.reason),
        timing: this.createTimingMetrics(startTime),
      };
    }

    const response = resultResponse.value.response;
    const text = response.text();
    const usage = response.usageMetadata
      ? {
          inputTokens: response.usageMetadata.promptTokenCount || 0,
          outputTokens: response.usageMetadata.candidatesTokenCount || 0,
        }
      : undefined;

    return {
      id: this.generateId(),
      provider: this.name,
      model,
      content: text,
      usage,
      timing: this.createTimingMetrics(startTime),
    };
  }

  async *stream(prompt: string, options?: GenerateOptions): AsyncGenerator<string> {
    const model = this.resolveModel(options);
    const generativeModel =
      model === this.model ? this.generativeModel : this.client.getGenerativeModel({ model });
    const generationConfig = {
      temperature: options?.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
      maxOutputTokens: options?.maxTokens ?? AI_DEFAULT_MAX_TOKENS,
      topP: options?.topP ?? AI_DEFAULT_TOP_P,
      topK: options?.topK ?? COUNT_FORTY,
    };

    let fullPrompt = prompt;
    if (options?.systemPrompt) {
      fullPrompt = `${options.systemPrompt}\n\n${prompt}`;
    }

    const streamResult = await settle(
      generativeModel.generateContentStream({
        contents: [{ role: "user", parts: [{ text: fullPrompt }] }],
        generationConfig,
      }),
    );
    if (streamResult.status === "rejected") {
      throw new Error(`${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(streamResult.reason)}`);
    }
    const result = streamResult.value;

    const iterator = result.stream[Symbol.asyncIterator]();
    const emitTextChunks = async function* (): AsyncGenerator<string> {
      const nextChunkResult = await settle(iterator.next());
      if (nextChunkResult.status === "rejected") {
        throw new Error(
          `${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(nextChunkResult.reason)}`,
        );
      }
      const nextChunk = nextChunkResult.value;
      if (nextChunk.done) {
        return;
      }
      const text = nextChunk.value.text();
      if (text) {
        yield text;
      }
      yield* emitTextChunks();
    };

    yield* emitTextChunks();
  }

  async isAvailable(): Promise<boolean> {
    // Try to list models to verify API key and connectivity
    return (
      (await settle(Promise.resolve(this.client.getGenerativeModel({ model: "gemini-pro" }))))
        .status === "fulfilled"
    );
  }
}

import {
  AI_DEFAULT_MAX_TOKENS_HUGGINGFACE,
  AI_DEFAULT_TEMPERATURE_CREATIVE,
  AI_DEFAULT_TOP_P,
} from "@bao/shared/constants/ai-generation";
import { HUGGING_FACE_DEFAULT_MODEL } from "@bao/shared/constants/ai-provider";
import { API_ERROR_AI_STREAMING_FAILED } from "@bao/shared/constants/api-errors";
import type { AIResponse, GenerateOptions } from "@bao/shared/types/ai";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import { HfInference } from "@huggingface/inference";
import { BaseAIProvider } from "./provider-interface";

type ChatMessage = { role: "system" | "user" | "assistant"; content: string };
const buildChatMessages = (prompt: string, systemPrompt?: string): ChatMessage[] => {
  const messages: ChatMessage[] = [];
  if (systemPrompt) {
    messages.push({ role: "system", content: systemPrompt });
  }
  messages.push({ role: "user", content: prompt });
  return messages;
};

const HUGGING_FACE_INFERENCE_PROVIDER = "hf-inference" as const;

/**
 * Hugging Face AI Provider
 * Uses chatCompletion API for conversational models.
 * Works with free tier (no API key required) or with API token for better rate limits.
 */
export class HuggingFaceProvider extends BaseAIProvider {
  name = "huggingface" as const;
  model: string;
  private client: HfInference;

  constructor(apiKey?: string, model?: string) {
    super(apiKey);
    this.model =
      typeof model === "string" && model.trim().length > 0 ? model : HUGGING_FACE_DEFAULT_MODEL;
    this.client = new HfInference(apiKey);
  }

  private resolveModel(options?: GenerateOptions): string {
    return typeof options?.model === "string" && options.model.trim().length > 0
      ? options.model.trim()
      : this.model;
  }

  async generate(prompt: string, options?: GenerateOptions): Promise<AIResponse> {
    const startTime = Date.now();
    const model = this.resolveModel(options);
    const messages = buildChatMessages(prompt, options?.systemPrompt);

    const responseResult = await settle(
      this.client.chatCompletion({
        provider: HUGGING_FACE_INFERENCE_PROVIDER,
        model,
        messages,
        max_tokens: options?.maxTokens ?? AI_DEFAULT_MAX_TOKENS_HUGGINGFACE,
        temperature: options?.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
        top_p: options?.topP ?? AI_DEFAULT_TOP_P,
      }),
    );
    if (responseResult.status === "rejected") {
      return {
        id: this.generateId(),
        provider: this.name,
        model,
        content: "",
        error: toErrorMessage(responseResult.reason),
        timing: this.createTimingMetrics(startTime),
      };
    }

    const content = responseResult.value.choices[0]?.message?.content ?? "";

    return {
      id: this.generateId(),
      provider: this.name,
      model,
      content,
      timing: this.createTimingMetrics(startTime),
    };
  }

  async *stream(prompt: string, options?: GenerateOptions): AsyncGenerator<string> {
    const model = this.resolveModel(options);
    const messages = buildChatMessages(prompt, options?.systemPrompt);

    const stream = this.client.chatCompletionStream({
      provider: HUGGING_FACE_INFERENCE_PROVIDER,
      model,
      messages,
      max_tokens: options?.maxTokens ?? AI_DEFAULT_MAX_TOKENS_HUGGINGFACE,
      temperature: options?.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
      top_p: options?.topP ?? AI_DEFAULT_TOP_P,
    });

    const iterator = stream[Symbol.asyncIterator]();
    const emitTokens = async function* (): AsyncGenerator<string> {
      const nextChunkResult = await settle(iterator.next());
      if (nextChunkResult.status === "rejected") {
        throw new Error(
          `${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(nextChunkResult.reason)}`,
        );
      }
      const nextChunk = nextChunkResult.value;
      if (nextChunk.done) {
        return;
      }
      const delta = nextChunk.value.choices?.[0]?.delta?.content;
      if (delta) {
        yield delta;
      }
      yield* emitTokens();
    };

    yield* emitTokens();
  }

  isAvailable(): Promise<boolean> {
    return Promise.resolve(true);
  }
}

import { LOCAL_AI_AUTO_DETECT_MODEL, LOCAL_AI_SERVERS } from "@bao/shared/constants/ai-provider";
import type { AIProviderDiagnostic } from "@bao/shared/types/ai";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";

const LOCAL_PROVIDER_HEALTH_TIMEOUT_MS = 3_000;
export const LOCAL_PROVIDER_ERROR_CODE: AIProviderDiagnostic["code"] = "error";
const TRAILING_SLASH_PATTERN = /\/$/;

type LocalDiagnosticInput = {
  code: AIProviderDiagnostic["code"];
  endpoint: string;
  checkedAt: string;
  selectedModel?: string;
  message?: string;
  availableModels?: readonly string[];
};

type LocalModelDiscoveryResult =
  | {
      endpoint: string;
      checkedAt: string;
      availableModels: readonly string[];
    }
  | {
      diagnostic: AIProviderDiagnostic;
    };

const getModelIdFromPayloadEntry = (entry: unknown): string | null => {
  if (typeof entry !== "object" || entry === null || !("id" in entry)) {
    return null;
  }

  const candidateId = entry.id;
  return typeof candidateId === "string" && candidateId.trim().length > 0
    ? candidateId.trim()
    : null;
};

const buildDiagnosticResponse = ({
  code,
  endpoint,
  checkedAt,
  selectedModel,
  message,
  availableModels,
}: LocalDiagnosticInput): AIProviderDiagnostic => ({
  provider: "local",
  code,
  checkedAt,
  endpoint,
  selectedModel,
  availableModels,
  ...(message ? { message } : {}),
});

const buildModelsUrl = (endpoint: string): string =>
  endpoint.endsWith("/models")
    ? endpoint
    : `${endpoint.replace(TRAILING_SLASH_PATTERN, "")}/models`;

const extractAvailableModels = (payload: unknown): string[] => {
  const data =
    typeof payload === "object" && payload !== null && "data" in payload ? payload.data : null;
  return Array.isArray(data)
    ? data.flatMap((entry) => {
        const id = getModelIdFromPayloadEntry(entry);
        return id ? [id] : [];
      })
    : [];
};

const buildFetchFailureDiagnostic = (
  endpoint: string,
  checkedAt: string,
  selectedModel: string | undefined,
  error: unknown,
): AIProviderDiagnostic => {
  const message = toErrorMessage(error);
  return buildDiagnosticResponse({
    code: message.toLowerCase().includes("timeout") ? "timeout" : "unreachable",
    endpoint,
    checkedAt,
    selectedModel,
    message,
  });
};

const buildHttpFailureDiagnostic = (
  endpoint: string,
  checkedAt: string,
  selectedModel: string | undefined,
  status: number,
): LocalModelDiscoveryResult => ({
  diagnostic: buildDiagnosticResponse({
    code: "unreachable",
    endpoint,
    checkedAt,
    selectedModel,
    message: `HTTP ${status}`,
  }),
});

const buildPayloadDiagnostic = (
  endpoint: string,
  checkedAt: string,
  selectedModel: string | undefined,
  payload: unknown,
): LocalModelDiscoveryResult => {
  const availableModels = extractAvailableModels(payload);
  if (availableModels.length === 0) {
    return {
      diagnostic: buildDiagnosticResponse({
        code: "empty-model-list",
        endpoint,
        checkedAt,
        selectedModel,
        message: "Endpoint responded without any available models",
        availableModels,
      }),
    };
  }

  return {
    endpoint,
    checkedAt,
    availableModels,
  };
};

const loadAvailableModels = async (
  endpoint: string,
  checkedAt: string,
  selectedModel?: string,
): Promise<LocalModelDiscoveryResult> => {
  const responseResult = await settle(
    fetch(buildModelsUrl(endpoint), {
      method: "GET",
      signal: AbortSignal.timeout(LOCAL_PROVIDER_HEALTH_TIMEOUT_MS),
    }),
  );

  if (responseResult.status === "rejected") {
    return {
      diagnostic: buildFetchFailureDiagnostic(
        endpoint,
        checkedAt,
        selectedModel,
        responseResult.reason,
      ),
    };
  }

  const response = responseResult.value;
  if (!response.ok) {
    return buildHttpFailureDiagnostic(endpoint, checkedAt, selectedModel, response.status);
  }

  const payloadResult = await settle<unknown>(response.json());
  if (payloadResult.status === "rejected") {
    return {
      diagnostic: buildDiagnosticResponse({
        code: "error",
        endpoint,
        checkedAt,
        selectedModel,
        message: toErrorMessage(payloadResult.reason),
      }),
    };
  }

  return buildPayloadDiagnostic(endpoint, checkedAt, selectedModel, payloadResult.value);
};

export async function inspectLocalProviderEndpoint(
  baseUrl: string,
  selectedModel?: string,
): Promise<AIProviderDiagnostic> {
  const checkedAt = new Date().toISOString();
  const endpoint = baseUrl.trim();
  const modelDiscovery = await loadAvailableModels(endpoint, checkedAt, selectedModel);
  if ("diagnostic" in modelDiscovery) {
    return modelDiscovery.diagnostic;
  }

  const { availableModels } = modelDiscovery;
  if (
    selectedModel &&
    selectedModel !== LOCAL_AI_AUTO_DETECT_MODEL &&
    !availableModels.includes(selectedModel)
  ) {
    return buildDiagnosticResponse({
      code: "invalid-model",
      endpoint,
      checkedAt,
      selectedModel,
      message: "Configured model was not returned by the endpoint",
      availableModels,
    });
  }

  return buildDiagnosticResponse({
    code: "healthy",
    endpoint,
    checkedAt,
    selectedModel:
      selectedModel && selectedModel !== LOCAL_AI_AUTO_DETECT_MODEL
        ? selectedModel
        : availableModels[0],
    availableModels,
  });
}

export async function detectFirstLocalProviderModel(baseUrl: string): Promise<string | null> {
  const diagnostics = await inspectLocalProviderEndpoint(baseUrl);
  return diagnostics.availableModels?.[0] ?? null;
}

export async function detectLocalProviderServers(): Promise<
  Array<{
    id?: string;
    baseUrl: string;
    name: string;
    available: boolean;
    availableModels?: readonly string[];
    diagnosticCode?: AIProviderDiagnostic["code"];
    message?: string;
  }>
> {
  const servers = LOCAL_AI_SERVERS.map((server) => ({
    id: server.id,
    baseUrl: server.baseUrl,
    name: server.name,
  }));

  return await Promise.all(
    servers.map(async (server) => {
      const result = await settle(
        Promise.resolve().then(async () => {
          const diagnostics = await inspectLocalProviderEndpoint(server.baseUrl);
          return {
            ...server,
            available: diagnostics.code === "healthy",
            availableModels: diagnostics.availableModels
              ? [...diagnostics.availableModels]
              : undefined,
            diagnosticCode: diagnostics.code,
            message: diagnostics.message,
          };
        }),
      );

      if (result.status === "rejected") {
        return {
          ...server,
          available: false,
          diagnosticCode: LOCAL_PROVIDER_ERROR_CODE,
          message: toErrorMessage(result.reason),
        };
      }

      return result.value;
    }),
  );
}

