import {
  AI_DEFAULT_MAX_TOKENS,
  AI_DEFAULT_TEMPERATURE_CREATIVE,
} from "@bao/shared/constants/ai-generation";
import {
  LOCAL_AI_AUTO_DETECT_MODEL,
  LOCAL_AI_DEFAULT_ENDPOINT,
  LOCAL_AI_DEFAULT_MODEL,
} from "@bao/shared/constants/ai-provider";
import { API_ERROR_AI_STREAMING_FAILED } from "@bao/shared/constants/api-errors";
import type {
  AIProviderDiagnostic,
  AIProviderType,
  AIResponse,
  GenerateOptions,
} from "@bao/shared/types/ai";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { safeParseJson } from "@bao/shared/utils/json";
import { settle } from "@bao/shared/utils/promise";
import OpenAI from "openai";
import {
  detectFirstLocalProviderModel,
  detectLocalProviderServers,
  inspectLocalProviderEndpoint,
} from "./local-provider-diagnostics";
import { BaseAIProvider } from "./provider-interface";

const buildLocalProviderMessages = (
  prompt: string,
  systemPrompt?: string,
): OpenAI.Chat.ChatCompletionMessageParam[] => {
  const messages: OpenAI.Chat.ChatCompletionMessageParam[] = [];
  if (systemPrompt) {
    messages.push({
      role: "system",
      content: systemPrompt,
    });
  }
  messages.push({
    role: "user",
    content: prompt,
  });
  return messages;
};

const isJsonRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const readNonEmptyString = (value: unknown): string | null =>
  typeof value === "string" && value.trim().length > 0 ? value : null;

const readMessageReasoning = (completion: OpenAI.Chat.ChatCompletion): string => {
  const serializedMessage = JSON.stringify(completion.choices[0]?.message ?? null);
  const parsedMessage = safeParseJson(serializedMessage);
  if (!isJsonRecord(parsedMessage)) {
    return "";
  }

  return readNonEmptyString(parsedMessage.reasoning) ?? "";
};

const readCompletionContent = (
  completion: OpenAI.Chat.ChatCompletion,
  options?: GenerateOptions,
): string => {
  const content = completion.choices[0]?.message?.content;
  if (typeof content === "string" && content.trim().length > 0) {
    return content;
  }

  if (
    options?.purpose === "coverLetter" ||
    options?.purpose === "scrapeEnrichment" ||
    options?.purpose === "emailResponse"
  ) {
    return readMessageReasoning(completion);
  }

  return "";
};

/**
 * Local AI Provider for RamaLama, Ollama, and other OpenAI Chat Completions local servers
 * Uses the OpenAI SDK pointed at a local endpoint
 */
export class LocalProvider extends BaseAIProvider {
  name: AIProviderType = "local";
  model: string;
  private client: OpenAI;

  constructor(
    baseUrl = LOCAL_AI_DEFAULT_ENDPOINT,
    model = LOCAL_AI_DEFAULT_MODEL,
    apiKey = "not-needed",
  ) {
    super(apiKey, baseUrl);
    this.model = model;
    this.client = new OpenAI({
      apiKey, // Local servers usually don't need a real key
      baseURL: baseUrl,
    });
  }

  private async resolveRequestedModel(requestedModel?: string): Promise<string | null> {
    if (typeof requestedModel === "string" && requestedModel.trim().length > 0) {
      return requestedModel.trim();
    }

    const resolved = await this.resolveModelIfNeeded();
    return resolved ? this.model : null;
  }

  private async createCompletion(
    prompt: string,
    model: string,
    options?: GenerateOptions,
  ): Promise<OpenAI.Chat.ChatCompletion> {
    const messages = buildLocalProviderMessages(prompt, options?.systemPrompt);
    return this.client.chat.completions.create({
      model,
      messages,
      max_tokens: options?.maxTokens ?? AI_DEFAULT_MAX_TOKENS,
      temperature: options?.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
      top_p: options?.topP ?? 1,
      stream: false,
    });
  }

  async generate(prompt: string, options?: GenerateOptions): Promise<AIResponse> {
    const startTime = Date.now();
    const model = await this.resolveRequestedModel(options?.model);
    if (!model) {
      return {
        id: this.generateId(),
        provider: this.name,
        model: "",
        content: "",
        error: "No local model available",
        timing: this.createTimingMetrics(startTime),
      };
    }
    const responseResult = await settle(this.createCompletion(prompt, model, options));
    if (responseResult.status === "rejected") {
      return {
        id: this.generateId(),
        provider: this.name,
        model,
        content: "",
        error: toErrorMessage(responseResult.reason),
        timing: this.createTimingMetrics(startTime),
      };
    }
    const response = responseResult.value;
    const text = readCompletionContent(response, options);
    return {
      id: this.generateId(),
      provider: this.name,
      model,
      content: text,
      usage: response.usage
        ? {
            inputTokens: response.usage.prompt_tokens,
            outputTokens: response.usage.completion_tokens,
          }
        : undefined,
      timing: this.createTimingMetrics(startTime),
    };
  }

  async *stream(prompt: string, options?: GenerateOptions): AsyncGenerator<string> {
    const model = await this.resolveRequestedModel(options?.model);
    if (!model) {
      throw new Error("No local model available");
    }
    const messages = buildLocalProviderMessages(prompt, options?.systemPrompt);

    const streamResult = await settle(
      this.client.chat.completions.create({
        model,
        messages,
        max_tokens: options?.maxTokens ?? AI_DEFAULT_MAX_TOKENS,
        temperature: options?.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
        top_p: options?.topP ?? 1,
        stream: true,
      }),
    );
    if (streamResult.status === "rejected") {
      throw new Error(`${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(streamResult.reason)}`);
    }
    const stream = streamResult.value;

    const iterator = stream[Symbol.asyncIterator]();
    const emitContentChunks = async function* (): AsyncGenerator<string> {
      const nextChunkResult = await settle(iterator.next());
      if (nextChunkResult.status === "rejected") {
        throw new Error(
          `${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(nextChunkResult.reason)}`,
        );
      }
      const nextChunk = nextChunkResult.value;
      if (nextChunk.done) {
        return;
      }
      const content = nextChunk.value.choices[0]?.delta?.content;
      if (content) {
        yield content;
      }
      yield* emitContentChunks();
    };

    yield* emitContentChunks();
  }

  async isAvailable(): Promise<boolean> {
    const resolvedModel = await this.resolveModelIfNeeded();
    if (!resolvedModel) {
      return false;
    }
    return (await settle(this.client.models.list())).status === "fulfilled";
  }

  private async resolveModelIfNeeded(): Promise<boolean> {
    if (this.model && this.model !== LOCAL_AI_AUTO_DETECT_MODEL) {
      return true;
    }

    if (!this.baseUrl || typeof this.baseUrl !== "string" || this.baseUrl.trim().length === 0) {
      return false;
    }

    const detected = await settle(LocalProvider.detectFirstModel(this.baseUrl));
    if (detected.status === "rejected" || !detected.value) {
      return false;
    }

    this.model = detected.value;
    return true;
  }

  /**
   * Query the local server for available models and return the first one.
   * Returns null if the server is unreachable or has no models.
   */
  static async detectFirstModel(baseUrl: string): Promise<string | null> {
    return await detectFirstLocalProviderModel(baseUrl);
  }

  /**
   * Inspect a local OpenAI Chat Completions endpoint and return structured diagnostics.
   */
  static async inspectEndpoint(
    baseUrl: string,
    selectedModel?: string,
  ): Promise<AIProviderDiagnostic> {
    return await inspectLocalProviderEndpoint(baseUrl, selectedModel);
  }

  /**
   * Static method to detect local AI servers
   */
  static async detectLocalServers(): Promise<
    Array<{
      id?: string;
      baseUrl: string;
      name: string;
      available: boolean;
      availableModels?: readonly string[];
      diagnosticCode?: AIProviderDiagnostic["code"];
      message?: string;
    }>
  > {
    return await detectLocalProviderServers();
  }
}

import {
  AI_DEFAULT_MAX_TOKENS,
  AI_DEFAULT_TEMPERATURE_CREATIVE,
} from "@bao/shared/constants/ai-generation";
import { API_ERROR_AI_STREAMING_FAILED } from "@bao/shared/constants/api-errors";
import type { AIResponse, GenerateOptions } from "@bao/shared/types/ai";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import OpenAI from "openai";
import { BaseAIProvider } from "./provider-interface";

/**
 * OpenAI AI Provider
 */
export class OpenAIProvider extends BaseAIProvider {
  name = "openai" as const;
  model: string;
  private client: OpenAI;

  constructor(apiKey: string, model = "gpt-4o") {
    super(apiKey);
    this.model = model;
    this.client = new OpenAI({ apiKey });
  }

  private resolveModel(options?: GenerateOptions): string {
    return typeof options?.model === "string" && options.model.trim().length > 0
      ? options.model.trim()
      : this.model;
  }

  async generate(prompt: string, options?: GenerateOptions): Promise<AIResponse> {
    const startTime = Date.now();
    const model = this.resolveModel(options);
    const messages: OpenAI.Chat.ChatCompletionMessageParam[] = [];

    if (options?.systemPrompt) {
      messages.push({
        role: "system",
        content: options.systemPrompt,
      });
    }

    messages.push({
      role: "user",
      content: prompt,
    });

    const responseResult = await settle(
      this.client.chat.completions.create({
        model,
        messages,
        max_tokens: options?.maxTokens ?? AI_DEFAULT_MAX_TOKENS,
        temperature: options?.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
        top_p: options?.topP ?? 1,
      }),
    );
    if (responseResult.status === "rejected") {
      return {
        id: this.generateId(),
        provider: this.name,
        model,
        content: "",
        error: toErrorMessage(responseResult.reason),
        timing: this.createTimingMetrics(startTime),
      };
    }
    const response = responseResult.value;
    const text = response.choices[0]?.message?.content || "";
    return {
      id: this.generateId(),
      provider: this.name,
      model,
      content: text,
      usage: response.usage
        ? {
            inputTokens: response.usage.prompt_tokens,
            outputTokens: response.usage.completion_tokens,
          }
        : undefined,
      timing: this.createTimingMetrics(startTime),
    };
  }

  async *stream(prompt: string, options?: GenerateOptions): AsyncGenerator<string> {
    const model = this.resolveModel(options);
    const messages: OpenAI.Chat.ChatCompletionMessageParam[] = [];

    if (options?.systemPrompt) {
      messages.push({
        role: "system",
        content: options.systemPrompt,
      });
    }

    messages.push({
      role: "user",
      content: prompt,
    });

    const streamResult = await settle(
      this.client.chat.completions.create({
        model,
        messages,
        max_tokens: options?.maxTokens ?? AI_DEFAULT_MAX_TOKENS,
        temperature: options?.temperature ?? AI_DEFAULT_TEMPERATURE_CREATIVE,
        top_p: options?.topP ?? 1,
        stream: true,
      }),
    );
    if (streamResult.status === "rejected") {
      throw new Error(`${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(streamResult.reason)}`);
    }
    const stream = streamResult.value;

    const iterator = stream[Symbol.asyncIterator]();
    const emitContentChunks = async function* (): AsyncGenerator<string> {
      const nextChunkResult = await settle(iterator.next());
      if (nextChunkResult.status === "rejected") {
        throw new Error(
          `${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(nextChunkResult.reason)}`,
        );
      }
      const nextChunk = nextChunkResult.value;
      if (nextChunk.done) {
        return;
      }
      const content = nextChunk.value.choices[0]?.delta?.content;
      if (content) {
        yield content;
      }
      yield* emitContentChunks();
    };

    yield* emitContentChunks();
  }

  async isAvailable(): Promise<boolean> {
    // List models to verify API key
    return (await settle(this.client.models.list())).status === "fulfilled";
  }
}

import { describe, expect, test } from "bun:test";
import type { InterviewTargetJob } from "@bao/shared/types/interview";
import type { SkillMapping } from "@bao/shared/types/skill-mapping";
import {
  buildJobPromptContext,
  buildSkillPromptContext,
  buildStudioPromptContext,
  JOB_CONTEXT_NOT_PROVIDED,
  SKILL_CONTEXT_NOT_PROVIDED,
  type StudioPromptContext,
} from "./prompt-context-entities";

/**
 * These builders decide whether an AI surface knows anything about the studio, the
 * scraped posting, or the candidate's transferable skills. They had no tests, which
 * is exactly why cover letters shipped asking the model to "demonstrate knowledge of
 * the company" with no company data attached. Each assertion below checks that a
 * specific input fact reaches the prompt text, so dropping context fails loudly.
 */

const STUDIO: StudioPromptContext = {
  name: "Riot Games",
  description: "Developer of League of Legends.",
  interviewStyle: "Technical assessments, portfolio review",
  technologies: ["C++", "C#", "Proprietary Engine"],
  games: ["League of Legends", "Valorant", "Teamfight Tactics", "Legends of Runeterra", "Extra"],
  location: "Los Angeles, CA",
  type: "AAA",
  remoteWork: true,
  enrichment: {
    summary: "Competitive multiplayer specialist",
    hiringSignals: ["Live-service experience", "Netcode depth"],
    interviewFocusAreas: ["Systems design", "Latency"],
    candidatePitchAngles: ["Shipped live ops", "Player-first metrics"],
  },
};

const JOB: InterviewTargetJob = {
  id: "job-1",
  title: "Senior Gameplay Engineer",
  company: "Riot Games",
  location: "Los Angeles, CA",
  description: "Own gameplay systems for a live-service title.",
  requirements: ["5+ years C++", "Multiplayer netcode", "Profiling"],
  technologies: ["C++", "Perforce"],
  source: "greenhouse",
  enrichment: {
    summary: "Live-service gameplay role",
    hiringSignals: ["Netcode"],
    interviewFocusAreas: ["Replication"],
    candidatePitchAngles: ["Shipped multiplayer"],
  },
};

/** More mappings than the builder's six-entry cap, to prove the cap holds. */
const OVER_CAP_SKILL_COUNT = 8;
const MAX_CONFIDENCE = 100;

const buildSkill = (overrides: Partial<SkillMapping>): SkillMapping => ({
  id: "skill-1",
  gameExpression: "Guild raid leadership",
  transferableSkill: "Cross-functional team leadership",
  industryApplications: ["Engineering management", "Live ops coordination"],
  evidence: [],
  confidence: 80,
  category: "leadership",
  demandLevel: "high",
  verified: true,
  ...overrides,
});

describe("buildStudioPromptContext", () => {
  test("includes the studio identity, type and interview style", () => {
    const prompt = buildStudioPromptContext(STUDIO);
    expect(prompt).toContain("Riot Games");
    expect(prompt).toContain("AAA");
    expect(prompt).toContain("Technical assessments, portfolio review");
  });

  test("includes the technology stack the studio actually uses", () => {
    const prompt = buildStudioPromptContext(STUDIO);
    expect(prompt).toContain("C++");
    expect(prompt).toContain("Proprietary Engine");
  });

  test("includes the scraped persona enrichment signals", () => {
    const prompt = buildStudioPromptContext(STUDIO);
    expect(prompt).toContain("Competitive multiplayer specialist");
    expect(prompt).toContain("Live-service experience");
    expect(prompt).toContain("Systems design");
    expect(prompt).toContain("Player-first metrics");
  });

  test("caps key titles at four so prompt budget stays bounded", () => {
    const prompt = buildStudioPromptContext(STUDIO);
    expect(prompt).toContain("Legends of Runeterra");
    expect(prompt).not.toContain("Extra");
  });

  test("labels missing optional studio detail instead of emitting blanks", () => {
    const prompt = buildStudioPromptContext({
      name: "Unknown Studio",
      description: "",
      interviewStyle: "",
      technologies: [],
      games: [],
      location: "",
      type: "",
      remoteWork: false,
    });
    expect(prompt).toContain("Unknown Studio");
    expect(prompt).toContain("primarily on-site");
    expect(prompt).not.toContain("- Technologies: \n");
  });
});

describe("buildJobPromptContext", () => {
  test("includes the posting title, company and description", () => {
    const prompt = buildJobPromptContext(JOB);
    expect(prompt).toContain("Senior Gameplay Engineer");
    expect(prompt).toContain("Riot Games");
    expect(prompt).toContain("Own gameplay systems for a live-service title.");
  });

  test("includes the scraped requirements and source", () => {
    const prompt = buildJobPromptContext(JOB);
    expect(prompt).toContain("5+ years C++");
    expect(prompt).toContain("Multiplayer netcode");
    expect(prompt).toContain("greenhouse");
  });

  test("states absence explicitly so the model cannot invent a posting", () => {
    expect(buildJobPromptContext(null)).toBe(JOB_CONTEXT_NOT_PROVIDED);
    expect(buildJobPromptContext(undefined)).toBe(JOB_CONTEXT_NOT_PROVIDED);
  });

  test("caps requirements at eight entries", () => {
    const prompt = buildJobPromptContext({
      ...JOB,
      requirements: ["r1", "r2", "r3", "r4", "r5", "r6", "r7", "r8", "r9-overflow"],
    });
    expect(prompt).toContain("r8");
    expect(prompt).not.toContain("r9-overflow");
  });
});

describe("buildSkillPromptContext", () => {
  test("includes the game expression, transferable skill and applications", () => {
    const prompt = buildSkillPromptContext([buildSkill({})]);
    expect(prompt).toContain("Guild raid leadership");
    expect(prompt).toContain("Cross-functional team leadership");
    expect(prompt).toContain("Engineering management");
  });

  test("orders by confidence so the strongest translation leads", () => {
    const prompt = buildSkillPromptContext([
      buildSkill({ id: "low", gameExpression: "Low signal", confidence: 20 }),
      buildSkill({ id: "high", gameExpression: "High signal", confidence: 95 }),
    ]);
    expect(prompt.indexOf("High signal")).toBeLessThan(prompt.indexOf("Low signal"));
  });

  test("caps at six mappings", () => {
    const skills = Array.from({ length: OVER_CAP_SKILL_COUNT }, (_unused, index) =>
      buildSkill({
        id: `skill-${String(index)}`,
        gameExpression: `Expression ${String(index)}`,
        confidence: MAX_CONFIDENCE - index,
      }),
    );
    const prompt = buildSkillPromptContext(skills);
    expect(prompt).toContain("Expression 5");
    expect(prompt).not.toContain("Expression 6");
  });

  test("states absence explicitly for an empty mapping set", () => {
    expect(buildSkillPromptContext([])).toBe(SKILL_CONTEXT_NOT_PROVIDED);
  });
});

import { DEFAULT_UNSPECIFIED_LABEL } from "@bao/shared/constants/default-labels";
import { COUNT_EIGHT, COUNT_FOUR, COUNT_SIX } from "@bao/shared/constants/numeric";
import type { InterviewTargetJob } from "@bao/shared/types/interview";
import type { ScrapePersonaEnrichment } from "@bao/shared/types/jobs";
import type { SkillMapping } from "@bao/shared/types/skill-mapping";

/**
 * Canonical studio / job / skill prompt context, shared by every AI surface.
 *
 * These builders started out inside the interview service, so interviews were the
 * only surface whose prompts actually described the studio and the scraped job.
 * Cover letters asked the model to "demonstrate knowledge of the company and their
 * games" while being handed nothing but a company name, and resume enhancement had
 * no job at all. Keeping one implementation here means a surface either passes the
 * context or visibly does not — there is no second, thinner copy to drift into.
 */

export interface StudioPromptContext {
  readonly name: string;
  readonly description: string;
  readonly interviewStyle: string;
  readonly technologies: readonly string[];
  readonly games: readonly string[];
  readonly location: string;
  readonly type: string;
  readonly remoteWork: boolean;
  readonly enrichment?: ScrapePersonaEnrichment;
}

const joinOrUnspecified = (values: readonly string[]): string =>
  values.join(", ") || DEFAULT_UNSPECIFIED_LABEL;

const joinSignals = (values: readonly string[] | undefined): string =>
  (values ?? []).join("; ") || DEFAULT_UNSPECIFIED_LABEL;

export function buildStudioPromptContext(studio: StudioPromptContext): string {
  return `Studio context:
- Name: ${studio.name}
- Type: ${studio.type || DEFAULT_UNSPECIFIED_LABEL}
- Interview style: ${studio.interviewStyle || DEFAULT_UNSPECIFIED_LABEL}
- Technologies: ${joinOrUnspecified(studio.technologies)}
- Key titles: ${joinOrUnspecified(studio.games.slice(0, COUNT_FOUR))}
- Remote: ${studio.remoteWork ? "supported" : "primarily on-site"}
- Persona summary: ${studio.enrichment?.summary || DEFAULT_UNSPECIFIED_LABEL}
- Hiring signals: ${joinSignals(studio.enrichment?.hiringSignals)}
- Interview focus areas: ${joinSignals(studio.enrichment?.interviewFocusAreas)}
- Candidate pitch angles: ${joinSignals(studio.enrichment?.candidatePitchAngles)}`;
}

/** Absent job context is stated explicitly so the model never invents a posting. */
export const JOB_CONTEXT_NOT_PROVIDED = "Job context: not provided.";

export function buildJobPromptContext(job: InterviewTargetJob | null | undefined): string {
  if (!job) {
    return JOB_CONTEXT_NOT_PROVIDED;
  }

  return `Job context:
- Job title: ${job.title}
- Company: ${job.company}
- Location: ${job.location}
- Technologies: ${joinOrUnspecified(job.technologies ?? [])}
- Requirements: ${joinSignals(job.requirements?.slice(0, COUNT_EIGHT))}
- Description: ${job.description || "Not provided"}
- Source: ${job.source || "Unknown"}
- Persona summary: ${job.enrichment?.summary || DEFAULT_UNSPECIFIED_LABEL}
- Hiring signals: ${joinSignals(job.enrichment?.hiringSignals)}
- Interview focus areas: ${joinSignals(job.enrichment?.interviewFocusAreas)}
- Candidate pitch angles: ${joinSignals(job.enrichment?.candidatePitchAngles)}`;
}

/** Absent skill context is stated explicitly for the same reason as job context. */
export const SKILL_CONTEXT_NOT_PROVIDED = "Transferable skill context: not provided.";

/**
 * Renders the candidate's game-to-industry skill translations. Highest-confidence
 * mappings first, because prompt budget is finite and a low-confidence mapping is
 * the one most likely to mislead the model.
 */
export function buildSkillPromptContext(skills: readonly SkillMapping[]): string {
  if (skills.length === 0) {
    return SKILL_CONTEXT_NOT_PROVIDED;
  }

  const ranked = [...skills]
    .sort((left, right) => right.confidence - left.confidence)
    .slice(0, COUNT_SIX);

  const lines = ranked.map(
    (skill) =>
      `- ${skill.gameExpression} → ${skill.transferableSkill} (${skill.category}, demand ${skill.demandLevel}, confidence ${String(skill.confidence)}): ${joinOrUnspecified(skill.industryApplications)}`,
  );

  return `Transferable skill context:
${lines.join("\n")}`;
}

import type { InterviewTargetJob } from "@bao/shared/types/interview";
import type { ScrapePersonaEnrichment } from "@bao/shared/types/jobs";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { jobs } from "../../db/schema/jobs";
import { studios } from "../../db/schema/studios";
import { skillMappingService } from "../skill-mapping-service";
import {
  buildJobPromptContext,
  buildSkillPromptContext,
  buildStudioPromptContext,
  type StudioPromptContext,
} from "./prompt-context-entities";

/**
 * Loads the studio / job / skill blocks an AI surface needs, from ids.
 *
 * Cover letters and resume enhancement previously had no way to reach this data —
 * they only received whatever the client hand-marshalled — so their prompts were
 * blind to the scraped studios and postings sitting in the database. Unlike the
 * interview loader (`interview-service-context.ts:resolveStudioContext`) this one
 * does NOT substitute a fallback studio: for a cover letter, a missing studio must
 * read as "no studio context" rather than quietly describing a different company.
 */

export interface EntityPromptContext {
  readonly studioContext?: string;
  readonly jobContext?: string;
  readonly skillContext?: string;
}

export interface EntityPromptContextRequest {
  readonly jobId?: string | undefined;
  readonly studioId?: string | undefined;
  readonly includeSkills?: boolean;
}

type StudioRow = typeof studios.$inferSelect;
type JobRow = typeof jobs.$inferSelect;

/** JSON columns are declared `$type<string[]>()` but are nullable in SQLite. */
const toStringArray = (value: readonly string[] | null): readonly string[] => value ?? [];

const withEnrichment = (
  enrichment: ScrapePersonaEnrichment | null,
): { enrichment?: ScrapePersonaEnrichment } => (enrichment ? { enrichment } : {});

const toStudioPromptContext = (studio: StudioRow): StudioPromptContext => ({
  name: studio.name,
  description: studio.description ?? "",
  interviewStyle: studio.interviewStyle ?? "",
  technologies: toStringArray(studio.technologies),
  games: toStringArray(studio.games),
  location: studio.location ?? "",
  type: studio.type ?? "",
  remoteWork: studio.remoteWork === true,
  ...withEnrichment(studio.enrichment),
});

const toTargetJob = (job: JobRow): InterviewTargetJob => ({
  id: job.id,
  title: job.title,
  company: job.company,
  location: job.location,
  ...(job.description ? { description: job.description } : {}),
  requirements: [...toStringArray(job.requirements)],
  technologies: [...toStringArray(job.technologies)],
  ...(job.source ? { source: job.source } : {}),
  ...withEnrichment(job.enrichment),
});

/**
 * When only a job id is supplied, the job's own company name is used to find the
 * studio, so a cover letter written from a scraped posting still carries studio
 * culture and tech-stack detail without the caller knowing the studio id.
 */
const resolveStudioRow = async (
  studioId: string | undefined,
  jobRow: JobRow | undefined,
): Promise<StudioRow | undefined> => {
  if (studioId) {
    const rows = await db.select().from(studios).where(eq(studios.id, studioId));
    if (rows[0]) {
      return rows[0];
    }
  }
  if (jobRow) {
    const rows = await db.select().from(studios).where(eq(studios.name, jobRow.company));
    return rows[0];
  }
  return undefined;
};

export const loadEntityPromptContext = async (
  request: EntityPromptContextRequest,
): Promise<EntityPromptContext> => {
  const jobRows = request.jobId
    ? await db.select().from(jobs).where(eq(jobs.id, request.jobId))
    : [];
  const jobRow = jobRows[0];
  const studioRow = await resolveStudioRow(request.studioId, jobRow);
  const skills = request.includeSkills === true ? await skillMappingService.getMappings() : [];

  return {
    ...(studioRow
      ? { studioContext: buildStudioPromptContext(toStudioPromptContext(studioRow)) }
      : {}),
    ...(jobRow ? { jobContext: buildJobPromptContext(toTargetJob(jobRow)) } : {}),
    ...(skills.length > 0 ? { skillContext: buildSkillPromptContext(skills) } : {}),
  };
};

import type { BrandSettings } from "@bao/shared/types/settings-contracts";

export type BrandPromptIdentity = Pick<BrandSettings, "name" | "assistantName">;

export interface InterviewPersonaPromptInput {
  role: string;
  company: string;
  personality: string;
  interviewStyle: string;
  focusAreas: string[];
}

/**
 * Form field analysis prompt for AI-powered smart selectors in RPA automation.
 * Analyzes a job application page's HTML to map field names to selectors and infer answers.
 */
export function formFieldAnalysisPrompt(
  pageHtml: string,
  fieldsNeeded: string[],
  candidateContext: string,
): string {
  return `Analyze this job application page HTML and return JSON with selector candidates plus inferred answers for non-core fields.

Fields needed: ${fieldsNeeded.join(", ")}

Candidate context:
${candidateContext}

HTML (form-relevant elements only):
${pageHtml}

Requirements:
1. In selectorMap, include arrays of CSS selectors ordered by specificity.
2. Always include selectorMap entries for the requested core fields when you can identify them.
3. In fieldAnswers, include only extra non-core application questions when the answer can be derived from the candidate context or the existingAnswers section.
4. For yes/no controls, return lowercase "yes" or "no".
5. For dropdowns, radios, and checkboxes, return the exact visible option label whenever possible.
6. Keep fieldAnswers concise and factual. Do not invent experience, authorization, or demographic information.
7. Do not include resume, coverLetter, or submit in fieldAnswers.

Return ONLY valid JSON with this structure:
{
  "selectorMap": {
    "fullName": ["#full-name", "input[name='name']", "input[aria-label='Full name']"],
    "email": ["#email", "input[type='email']", "input[name='email']"],
    "phone": ["input[type='tel']", "input[name='phone']"],
    "resume": ["input[type='file']", "input[name='resume']"],
    "coverLetter": ["textarea[name='cover_letter']", "textarea#cover-letter"],
    "submit": ["button[type='submit']", "input[type='submit']"],
    "workAuthorization": ["select[name='work_authorization']"],
    "portfolioLink": ["input[name='portfolio_url']"]
  },
  "fieldAnswers": {
    "workAuthorization": "yes",
    "portfolioLink": "https://portfolio.example.com"
  }
}

Prioritize selectors with unique IDs, then name attributes, then aria-labels, then label-associated selectors, then type-based fallbacks.`;
}

