/**
 * Range coverage for the automation SSRF host classifier.
 *
 * `automation-validation.test.ts` exercises the env-gated wrapper with a single
 * loopback address and one public host, so the RFC 1918 and link-local ranges
 * the gate exists to stop had no assertions at all. A boundary regression there
 * silently turns job-apply into an SSRF vector, so every range — and the public
 * addresses immediately outside 172.16.0.0/12 — is pinned here against the pure
 * classifier, which needs no environment mutation.
 */
import { describe, expect, test } from "bun:test";
import { COUNT_SIXTEEN, COUNT_THIRTY_ONE } from "@bao/shared/constants/numeric";
import { isPrivateOrLoopbackAutomationHost } from "./automation-validation";

/** Every second octet of 172.16.0.0/12, both bounds included. */
const RFC1918_CLASS_B_SECOND_OCTETS = Array.from(
  { length: COUNT_THIRTY_ONE - COUNT_SIXTEEN + 1 },
  (_unused, offset) => COUNT_SIXTEEN + offset,
);

describe("isPrivateOrLoopbackAutomationHost", () => {
  test("blocks loopback and localhost forms", () => {
    for (const hostname of ["localhost", "localhost.localdomain", "127.0.0.1", "127.10.20.30"]) {
      expect(isPrivateOrLoopbackAutomationHost(hostname)).toBe(true);
    }
  });

  test("blocks 10.0.0.0/8", () => {
    expect(isPrivateOrLoopbackAutomationHost("10.0.0.1")).toBe(true);
    expect(isPrivateOrLoopbackAutomationHost("10.255.255.254")).toBe(true);
  });

  test("blocks 192.168.0.0/16", () => {
    expect(isPrivateOrLoopbackAutomationHost("192.168.1.1")).toBe(true);
  });

  test("blocks the 169.254.169.254 cloud metadata address", () => {
    expect(isPrivateOrLoopbackAutomationHost("169.254.169.254")).toBe(true);
  });

  test("blocks the full 172.16.0.0/12 range", () => {
    for (const secondOctet of RFC1918_CLASS_B_SECOND_OCTETS) {
      expect(isPrivateOrLoopbackAutomationHost(`172.${String(secondOctet)}.0.1`)).toBe(true);
    }
  });

  test("allows public addresses immediately outside 172.16.0.0/12", () => {
    expect(isPrivateOrLoopbackAutomationHost("172.15.0.1")).toBe(false);
    expect(isPrivateOrLoopbackAutomationHost("172.32.0.1")).toBe(false);
  });

  test("blocks IPv6 loopback and unique-local prefixes", () => {
    for (const hostname of ["::1", "fc00::1", "fd12:3456::1"]) {
      expect(isPrivateOrLoopbackAutomationHost(hostname)).toBe(true);
    }
  });

  test("allows ordinary public hosts", () => {
    for (const hostname of ["example.com", "8.8.8.8", "203.0.113.10"]) {
      expect(isPrivateOrLoopbackAutomationHost(hostname)).toBe(false);
    }
  });

  test("treats an empty hostname as disallowed", () => {
    expect(isPrivateOrLoopbackAutomationHost("")).toBe(true);
  });
});

import { createServerLogger } from "../../utils/logger";
import type { AutofillAnalysisOptions } from "./automation-service-contracts";
import { tryLoadAIService } from "./automation-settings-support";
import {
  type SmartFieldAnalysisContext,
  type SmartFieldAnalysisResult,
  smartFieldMapper,
} from "./smart-field-mapper";

const automationPreparationLogger = createServerLogger("automation-job-apply-preparation");

export const SMART_FIELD_CORE_KEYS = [
  "fullName",
  "email",
  "phone",
  "resume",
  "coverLetter",
  "submit",
] as const;

export const normalizeGeneratedFieldAnswers = (
  fieldAnswers: Record<string, string>,
): Record<string, string> => {
  const reservedFieldKeys = new Set<string>(SMART_FIELD_CORE_KEYS);
  const normalizedAnswers: Record<string, string> = {};

  for (const [key, value] of Object.entries(fieldAnswers)) {
    const normalizedKey = key.trim();
    const normalizedValue = value.trim();
    if (
      normalizedKey.length === 0 ||
      normalizedValue.length === 0 ||
      reservedFieldKeys.has(normalizedKey)
    ) {
      continue;
    }

    normalizedAnswers[normalizedKey] = normalizedValue;
  }

  return normalizedAnswers;
};

const createEmptyAutofillAnalysis = (): SmartFieldAnalysisResult => ({
  selectorMap: {},
  fieldAnswers: {},
});

const buildSmartFieldAnalysisContext = (
  options: Pick<AutofillAnalysisOptions, "resume" | "coverLetter" | "existingAnswers">,
): SmartFieldAnalysisContext => ({
  resume: Object.fromEntries(Object.entries(options.resume)),
  coverLetter: options.coverLetter ? { content: options.coverLetter.content || {} } : null,
  existingAnswers: options.existingAnswers,
});

export const resolveAutofillAnalysis = async (
  options: AutofillAnalysisOptions,
): Promise<SmartFieldAnalysisResult> => {
  if (!options.automationSettings.enableSmartSelectors) {
    automationPreparationLogger.debug("Smart field mapping skipped: enableSmartSelectors is off");
    return createEmptyAutofillAnalysis();
  }

  const aiService = await tryLoadAIService();
  if (!aiService) {
    automationPreparationLogger.debug("Smart field mapping skipped: AI service unavailable");
    return createEmptyAutofillAnalysis();
  }

  const result = await smartFieldMapper.analyze(
    options.jobUrl,
    [...SMART_FIELD_CORE_KEYS],
    buildSmartFieldAnalysisContext(options),
    aiService,
  );
  const isEmpty =
    Object.keys(result.selectorMap).length === 0 && Object.keys(result.fieldAnswers).length === 0;
  if (isEmpty) {
    automationPreparationLogger.debug("Smart field mapping returned empty result", {
      jobUrl: options.jobUrl,
    });
  }
  return result;
};

import {
  API_ERROR_JOB_APPLICATION_AUTOMATION_FAILED,
  API_ERROR_RUN_ID_INVALID,
} from "@bao/shared/constants/api-errors";
import { API_MESSAGE_JOB_APPLICATION_AUTOMATION_COMPLETED } from "@bao/shared/constants/api-messages";
import { ROUTE_GAMIFICATION_XP } from "@bao/shared/constants/gamification";
import type { AutomationSettings } from "@bao/shared/types/settings-contracts";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import { createServerLogger } from "../../utils/logger";
import { broadcastAutomationEvent } from "../../ws/automation.ws";
import { gamificationService } from "../gamification-service";
import {
  markRunCompleted,
  markRunFailed,
  normalizeExecutionResult,
} from "./automation-run-persistence";
import { resolveAutomationTimeoutMs } from "./automation-settings-support";
import type {
  CreateProgressEvent,
  JobApplyExecutionTracking,
  JobApplyRunPreparation,
} from "./automation-service-contracts";
import type { RpaScriptExecutionResult } from "./rpa-runner-contracts";
import { runRpaScript } from "./rpa-runner-protocol";

const logger = createServerLogger("automation-job-apply-execution");

type FailureReason = Error | string;

export const createExecutionTracking = (): JobApplyExecutionTracking => ({
  exitCode: null,
  timedOut: false,
  aborted: false,
  executionMs: null,
  errorEnvelope: null,
  terminalPersisted: false,
});

export const markJobApplyRunStarted = async (runId: string): Promise<void> => {
  const startedAt = new Date().toISOString();
  await db
    .update(automationRuns)
    .set({
      startedAt,
      status: "running",
      progress: 0,
      exitCode: null,
      timedOut: false,
      aborted: false,
      executionMs: null,
      completedAt: null,
      updatedAt: startedAt,
    })
    .where(eq(automationRuns.id, runId));
};

const runJobApplyScript = async (
  preparation: JobApplyRunPreparation,
  tracking: JobApplyExecutionTracking,
): Promise<RpaScriptExecutionResult> => {
  const execution = await runRpaScript({
    scriptId: "job-apply",
    scriptInput: {
      jobUrl: preparation.normalized.jobUrl,
      resume: preparation.resume,
      ...(preparation.resumeFilePath ? { resumeFilePath: preparation.resumeFilePath } : {}),
      coverLetter: preparation.coverLetter
        ? { content: preparation.coverLetter.content || {} }
        : null,
      customAnswers: preparation.normalized.customAnswers,
      selectorMap: preparation.selectorMap,
    },
    executionContext: {
      runId: preparation.runId,
      timeoutMs: resolveAutomationTimeoutMs(preparation.automationSettings),
      outputDir: preparation.runArtifactDir,
    },
    automationSettings: preparation.automationSettings,
    onEvent: preparation.progressHandler,
  });

  tracking.exitCode = execution.exitCode;
  tracking.timedOut = execution.timedOut;
  tracking.aborted = execution.aborted;
  tracking.executionMs = execution.executionMs;
  tracking.errorEnvelope = execution.error;

  if (execution.error) {
    throw new Error(execution.error.message);
  }

  return execution;
};

const finalizeJobApplySuccess = async (
  preparation: JobApplyRunPreparation,
  tracking: JobApplyExecutionTracking,
  execution: RpaScriptExecutionResult,
  createProgressEvent: CreateProgressEvent,
): Promise<void> => {
  const normalizedResult = await normalizeExecutionResult(
    preparation.runId,
    execution,
    API_ERROR_RUN_ID_INVALID,
  );
  await markRunCompleted(
    preparation.runId,
    normalizedResult,
    preparation.automationSettings,
    execution,
  );
  tracking.terminalPersisted = true;

  if (!normalizedResult.success) {
    throw new Error(normalizedResult.error || API_ERROR_JOB_APPLICATION_AUTOMATION_FAILED);
  }

  broadcastAutomationEvent(
    createProgressEvent({
      runId: preparation.runId,
      action: "completed",
      status: "success",
      message: API_MESSAGE_JOB_APPLICATION_AUTOMATION_COMPLETED,
    }),
  );

  const awardXpResult = await settle(
    gamificationService.awardXP(ROUTE_GAMIFICATION_XP.automationCompleted, "automation_success"),
  );
  if (awardXpResult.status === "rejected") {
    logger.warn("XP award failed after job apply automation", {
      err: String(awardXpResult.reason),
    });
  }
};

export const executePreparedJobApplyRun = async (
  preparation: JobApplyRunPreparation,
  tracking: JobApplyExecutionTracking,
  createProgressEvent: CreateProgressEvent,
): Promise<void> => {
  const execution = await runJobApplyScript(preparation, tracking);
  await finalizeJobApplySuccess(preparation, tracking, execution, createProgressEvent);
};

export const handleJobApplyExecutionFailure = async (params: {
  runId: string;
  automationSettings: AutomationSettings;
  tracking: JobApplyExecutionTracking;
  reason: FailureReason;
  createProgressEvent: CreateProgressEvent;
}): Promise<never> => {
  const message = toErrorMessage(params.reason, API_ERROR_JOB_APPLICATION_AUTOMATION_FAILED);
  if (!params.tracking.terminalPersisted) {
    await markRunFailed(params.runId, message, params.automationSettings, {
      exitCode: params.tracking.exitCode,
      timedOut: params.tracking.timedOut,
      aborted: params.tracking.aborted,
      executionMs: params.tracking.executionMs,
      errorEnvelope: params.tracking.errorEnvelope,
    });
  }
  broadcastAutomationEvent(
    params.createProgressEvent({
      runId: params.runId,
      action: "automation",
      status: "error",
      message,
    }),
  );
  throw params.reason instanceof Error ? params.reason : new Error(message);
};

import type { RpaRunEvent } from "@bao/shared/schemas/rpa-events.schema";
import { and, count, eq, ne } from "drizzle-orm";
