const MIN_RESUME_ID_LENGTH = 1;

const assertConcurrencyLimit = async (runId: string, maxConcurrentRuns: number): Promise<void> => {
  const runningRows = await db
    .select({ count: count() })
    .from(automationRuns)
    .where(
      and(
        eq(automationRuns.status, "running"),
        eq(automationRuns.type, "job_apply"),
        ne(automationRuns.id, runId),
      ),
    );
  const runningCount = runningRows[0]?.count || 0;
  if (runningCount >= maxConcurrentRuns) {
    throw new AutomationConcurrencyLimitError(runningCount, maxConcurrentRuns);
  }
};

const loadResumeOrFail = async (
  runId: string,
  resumeId: string,
  automationSettings: Awaited<ReturnType<typeof loadAutomationSettings>>,
  runArtifactDir: string,
) => {
  const resume = await resumeService.getResume(resumeId);
  if (!resume) {
    const error = new AutomationDependencyMissingError("resume", resumeId);
    await markRunFailed(runId, error.message, automationSettings);
    throw error;
  }
  const resumeFilePath = await createResumeUploadArtifact(runArtifactDir, resume);
  return { resume, resumeFilePath };
};

const loadCoverLetterOrFail = async (
  runId: string,
  coverLetterId: string | undefined,
  automationSettings: Awaited<ReturnType<typeof loadAutomationSettings>>,
) => {
  if (!coverLetterId) {
    return null;
  }

  const coverLetterRows = await db
    .select()
    .from(coverLetters)
    .where(eq(coverLetters.id, coverLetterId))
    .limit(1);
  if (coverLetterRows.length === 0) {
    const error = new AutomationDependencyMissingError("coverLetter", coverLetterId);
    await markRunFailed(runId, error.message, automationSettings);
    throw error;
  }
  return coverLetterRows[0];
};

export const normalizeJobApplyPayload = (payload: JobApplyPayload): JobApplyExecutionPayload => {
  const jobUrl = sanitizeAndValidateJobUrl(payload.jobUrl);
  const customAnswers = sanitizeCustomAnswers(payload.customAnswers);

  const resumeId = payload.resumeId?.trim() ?? "";
  if (!resumeId || resumeId.length < MIN_RESUME_ID_LENGTH) {
    throw new AutomationValidationError("resumeId is required");
  }

  const normalizedPayload: JobApplyExecutionPayload = {
    jobUrl,
    resumeId,
    customAnswers,
  };
  const jobId = payload.jobId?.trim();
  if (jobId) {
    normalizedPayload.jobId = jobId;
  }
  const coverLetterId = payload.coverLetterId?.trim();
  if (coverLetterId) {
    normalizedPayload.coverLetterId = coverLetterId;
  }

  return normalizedPayload;
};

export const assertJobApplyDependencies = async (
  payload: JobApplyExecutionPayload,
): Promise<void> => {
  const resumeRows = await db
    .select()
    .from(resumes)
    .where(eq(resumes.id, payload.resumeId))
    .limit(1);
  if (resumeRows.length === 0) {
    throw new AutomationDependencyMissingError("resume", payload.resumeId);
  }

  if (!payload.coverLetterId) {
    return;
  }

  const coverLetterRows = await db
    .select()
    .from(coverLetters)
    .where(eq(coverLetters.id, payload.coverLetterId))
    .limit(1);
  if (coverLetterRows.length === 0) {
    throw new AutomationDependencyMissingError("coverLetter", payload.coverLetterId);
  }
};

export const prepareJobApplyRun = async (params: {
  runId: string;
  payload: JobApplyPayload;
  progressHandler: (event: RpaRunEvent) => void;
  clearScheduledRunTimer: (runId: string) => void;
  invalidRunIdMessage: string;
}): Promise<JobApplyRunPreparation> => {
  params.clearScheduledRunTimer(params.runId);
  const normalized = normalizeJobApplyPayload(params.payload);
  await assertRunExists(
    params.runId,
    (missingRunId) => new AutomationRunNotFoundError(missingRunId),
  );

  const automationSettings = await loadAutomationSettings();
  await assertConcurrencyLimit(params.runId, resolveMaxConcurrentRuns(automationSettings));
  const runArtifactDir = ensureRunArtifactDir(params.runId, params.invalidRunIdMessage);

  const resumeDetails = await loadResumeOrFail(
    params.runId,
    normalized.resumeId,
    automationSettings,
    runArtifactDir,
  );
  const coverLetter = await loadCoverLetterOrFail(
    params.runId,
    normalized.coverLetterId,
    automationSettings,
  );
  const autofillAnalysis = await resolveAutofillAnalysis({
    automationSettings,
    jobUrl: normalized.jobUrl,
    resume: resumeDetails.resume,
    coverLetter,
    existingAnswers: normalized.customAnswers,
  });
  const generatedFieldAnswers = normalizeGeneratedFieldAnswers(autofillAnalysis.fieldAnswers);

  return {
    runId: params.runId,
    automationSettings,
    normalized: {
      ...normalized,
      customAnswers: {
        ...generatedFieldAnswers,
        ...normalized.customAnswers,
      },
    },
    resume: resumeDetails.resume,
    coverLetter,
    selectorMap: autofillAnalysis.selectorMap,
    resumeFilePath: resumeDetails.resumeFilePath,
    progressHandler: params.progressHandler,
    runArtifactDir,
  };
};

import { join } from "node:path";
import type { ResumeData } from "@bao/shared/types/resume";
import { settle } from "@bao/shared/utils/promise";
import { exportService } from "../export-service";

const collectResumeHeaderLines = (resume: ResumeData): string[] => {
  const lines: string[] = [];
  const personalInfo = resume.personalInfo;

  if (resume.name) {
    lines.push(resume.name);
  }
  if (personalInfo?.name && personalInfo.name !== resume.name) {
    lines.push(personalInfo.name);
  }

  const contactLines = [
    personalInfo?.email,
    personalInfo?.phone,
    personalInfo?.location,
    personalInfo?.website,
    personalInfo?.linkedIn,
    personalInfo?.github,
    personalInfo?.portfolio,
  ].filter((entry): entry is string => typeof entry === "string" && entry.trim().length > 0);
  if (contactLines.length > 0) {
    lines.push(contactLines.join(" | "));
  }

  return lines;
};

const appendSection = (lines: string[], title: string, entries: string[]): void => {
  if (entries.length === 0) {
    return;
  }

  lines.push("", title, ...entries);
};

const collectResumeExperienceLines = (resume: ResumeData): string[] => {
  const lines: string[] = [];

  for (const experience of resume.experience ?? []) {
    const headerParts = [experience.title, experience.company].filter(
      (entry): entry is string => typeof entry === "string" && entry.trim().length > 0,
    );
    if (headerParts.length > 0) {
      lines.push(headerParts.join(" - "));
    }
    if (experience.description?.trim()) {
      lines.push(experience.description.trim());
    }
    for (const achievement of experience.achievements ?? []) {
      if (achievement.trim().length > 0) {
        lines.push(`- ${achievement.trim()}`);
      }
    }
  }

  return lines;
};

const collectResumeEducationLines = (resume: ResumeData): string[] => {
  const lines: string[] = [];

  for (const education of resume.education ?? []) {
    const headerParts = [education.degree, education.field, education.school].filter(
      (entry): entry is string => typeof entry === "string" && entry.trim().length > 0,
    );
    if (headerParts.length > 0) {
      lines.push(headerParts.join(" - "));
    }
  }

  return lines;
};

const collectResumeSkillSections = (
  resume: ResumeData,
): Array<{ title: string; lines: string[] }> => {
  const skillSections = [
    ["Technical Skills", resume.skills?.technical],
    ["Soft Skills", resume.skills?.soft],
    ["Gaming Skills", resume.skills?.gaming],
  ] as const;

  return skillSections.reduce<Array<{ title: string; lines: string[] }>>(
    (sections, [title, values]) => {
      if (Array.isArray(values) && values.length > 0) {
        sections.push({ title, lines: [values.join(", ")] });
      }
      return sections;
    },
    [],
  );
};

const serializeResumeUploadFallback = (resume: ResumeData): string => {
  const lines = collectResumeHeaderLines(resume);
  appendSection(lines, "Summary", resume.summary?.trim() ? [resume.summary.trim()] : []);
  appendSection(lines, "Experience", collectResumeExperienceLines(resume));
  appendSection(lines, "Education", collectResumeEducationLines(resume));
  for (const section of collectResumeSkillSections(resume)) {
    appendSection(lines, section.title, section.lines);
  }
  return lines.join("\n").trim();
};

export const createResumeUploadArtifact = async (
  runArtifactDir: string,
  resume: ResumeData,
): Promise<string | undefined> => {
  const pdfResult = await settle(exportService.exportResumePDF(resume, resume.template));
  if (pdfResult.status === "fulfilled") {
    const pdfPath = join(runArtifactDir, "resume.pdf");
    const writePdfResult = await settle(Bun.write(pdfPath, pdfResult.value));
    if (writePdfResult.status === "fulfilled") {
      return pdfPath;
    }
  }

  const fallbackResumePath = join(runArtifactDir, "resume.txt");
  const fallbackResume = serializeResumeUploadFallback(resume);
  const writeFallbackResult = await settle(Bun.write(fallbackResumePath, fallbackResume));
  if (writeFallbackResult.status === "fulfilled") {
    return fallbackResumePath;
  }
};

import { type RpaRunEvent, rpaProgressEventSchema } from "@bao/shared/schemas/rpa-events.schema";
import { RPA_PROTOCOL_VERSION } from "@bao/shared/schemas/rpa-protocol.schema";
import { createServerLogger } from "../../utils/logger";
import { broadcastAutomationEvent } from "../../ws/automation.ws";
import { persistProgress } from "./automation-run-persistence";
import type { ProgressEventParams } from "./automation-service-contracts";

const automationProgressLogger = createServerLogger("automation-progress-events");

export class AutomationProgressEvents {
  private readonly runEventSequences = new Map<string, number>();

  private nextRunEventSequence(runId: string): number {
    const current = this.runEventSequences.get(runId) ?? 0;
    this.runEventSequences.set(runId, current + 1);
    return current;
  }

  createProgressEvent(params: ProgressEventParams): RpaRunEvent {
    const event = {
      protocolVersion: RPA_PROTOCOL_VERSION,
      runId: params.runId,
      sequence: this.nextRunEventSequence(params.runId),
      timestamp: new Date().toISOString(),
      eventType: "progress",
      action: params.action,
      status: params.status,
      ...(params.message ? { message: params.message } : {}),
      ...(typeof params.step === "number" ? { step: params.step } : {}),
      ...(typeof params.totalSteps === "number" ? { totalSteps: params.totalSteps } : {}),
    } as const;

    const parsed = rpaProgressEventSchema.safeParse(event);
    if (!parsed.success) {
      automationProgressLogger.warn("Invalid progress event shape", {
        params,
        error: parsed.error.flatten(),
      });
      const fallbackEvent: RpaRunEvent = {
        ...event,
        action: "validation_error",
        status: "error",
      };
      return fallbackEvent;
    }
    return parsed.data;
  }

  createProgressHandler(onProgress?: (event: RpaRunEvent) => void): (event: RpaRunEvent) => void {
    return (event: RpaRunEvent): void => {
      if (event.eventType !== "progress") {
        return;
      }

      const normalizedEvent = {
        ...event,
        sequence: this.nextRunEventSequence(event.runId),
        timestamp: new Date().toISOString(),
      } satisfies RpaRunEvent;

      persistProgress(normalizedEvent).then(
        () => undefined,
        (error) => {
          automationProgressLogger.error(
            "Failed to persist progress event",
            error instanceof Error ? error.message : String(error),
          );
        },
      );
      broadcastAutomationEvent(normalizedEvent);
      onProgress?.(normalizedEvent);
    };
  }
}

import type { AutomationScrapeTarget } from "@bao/shared/constants/automation";
import { SCHEMA_MAX_ITEMS_BOARDS } from "@bao/shared/constants/schema-limits";
import type { EmailResponseRequest } from "@bao/shared/schemas/automation-email.schema";
import { generateId } from "@bao/shared/utils/validation";
import { and, count, eq } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import { broadcastAutomationEvent } from "../../ws/automation.ws";
import { normalizeEmailResponsePayload } from "./automation-email-response-payload";
import { AutomationConcurrencyLimitError } from "./automation-errors";
import {
  assertJobApplyDependencies,
  normalizeJobApplyPayload,
} from "./automation-job-apply-preparation";
import {
  buildAuditInput,
  buildEmailResponseInput,
  buildScheduledJobApplyInput,
  buildScrapeInput,
  type JobApplyPayload,
  normalizeScrapeTarget,
  resolveScrapeAction,
} from "./automation-run-inputs";
import type { CreateProgressEvent } from "./automation-service-contracts";
import {
  loadAutomationSettings,
  normalizeScheduledRunAt,
  resolveMaxConcurrentRuns,
} from "./automation-settings-support";

const DEFAULT_PROGRESS = 0;
const SCHEDULED_ACTION_EMAIL_RESPONSE = "email_response";
const MAX_RECOVERABLE_SCHEDULED_RUNS = SCHEMA_MAX_ITEMS_BOARDS;

type ScheduledRunQueue = (runId: string, runAt: string) => void;

interface AutomationRunCreatorOptions {
  createProgressEvent: CreateProgressEvent;
  queueScheduledRun: ScheduledRunQueue;
}

export class AutomationRunCreator {
  static readonly maxRecoverableScheduledRuns = MAX_RECOVERABLE_SCHEDULED_RUNS;

  constructor(private readonly options: AutomationRunCreatorOptions) {}

  async createJobApplyRun(
    payload: JobApplyPayload,
    runOptions: { includeActionInPayload?: boolean } = {},
  ): Promise<string> {
    const normalized = normalizeJobApplyPayload(payload);
    const settingsSnapshot = await loadAutomationSettings();
    const maxConcurrentRuns = resolveMaxConcurrentRuns(settingsSnapshot);

    await assertJobApplyDependencies(normalized);

    const now = new Date().toISOString();

    return db.transaction(async (tx) => {
      const runningRows = await tx
        .select({ count: count() })
        .from(automationRuns)
        .where(and(eq(automationRuns.status, "running"), eq(automationRuns.type, "job_apply")));

      const runningCount = runningRows[0]?.count || 0;
      if (runningCount >= maxConcurrentRuns) {
        throw new AutomationConcurrencyLimitError(runningCount, maxConcurrentRuns);
      }

      const runId = generateId();
      await tx.insert(automationRuns).values({
        id: runId,
        type: "job_apply",
        status: "running",
        jobId: normalized.jobId || null,
        userId: null,
        input: buildAuditInput(normalized, runOptions.includeActionInPayload ?? false),
        progress: DEFAULT_PROGRESS,
        currentStep: null,
        totalSteps: null,
        exitCode: null,
        timedOut: false,
        aborted: false,
        executionMs: null,
        startedAt: now,
        createdAt: now,
        updatedAt: now,
      });

      return runId;
    });
  }

  async createScheduledJobApplyRun(
    payload: JobApplyPayload,
    runAt: string,
  ): Promise<{ runId: string; scheduledFor: string }> {
    const normalized = normalizeJobApplyPayload(payload);
    const scheduledFor = normalizeScheduledRunAt(runAt);
    await assertJobApplyDependencies(normalized);

    const now = new Date().toISOString();
    const runId = generateId();
    const scheduleInput = buildScheduledJobApplyInput(normalized, scheduledFor);

    await db.insert(automationRuns).values({
      id: runId,
      type: "job_apply",
      status: "pending",
      jobId: normalized.jobId || null,
      userId: null,
      input: scheduleInput,
      progress: DEFAULT_PROGRESS,
      currentStep: null,
      totalSteps: null,
      exitCode: null,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt: null,
      createdAt: now,
      updatedAt: now,
    });

    this.options.queueScheduledRun(runId, scheduledFor);
    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: "job_apply",
        status: "pending",
        message: `Scheduled for ${scheduledFor}`,
      }),
    );

    return { runId, scheduledFor };
  }

  async createScheduledEmailResponseRun(
    payload: EmailResponseRequest,
    runAt: string,
  ): Promise<{ runId: string; scheduledFor: string }> {
    const normalized = normalizeEmailResponsePayload(payload);
    const scheduledFor = normalizeScheduledRunAt(runAt);
    const now = new Date().toISOString();
    const runId = generateId();

    await db.insert(automationRuns).values({
      id: runId,
      type: "email",
      status: "pending",
      jobId: null,
      userId: null,
      input: buildEmailResponseInput(normalized, {
        includeAction: true,
        scheduledFor,
      }),
      progress: DEFAULT_PROGRESS,
      currentStep: null,
      totalSteps: null,
      exitCode: 0,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt: null,
      createdAt: now,
      updatedAt: now,
    });

    this.options.queueScheduledRun(runId, scheduledFor);
    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: SCHEDULED_ACTION_EMAIL_RESPONSE,
        status: "pending",
        message: `Scheduled for ${scheduledFor}`,
      }),
    );

    return { runId, scheduledFor };
  }

  async createScheduledScrapeRun(
    target: AutomationScrapeTarget,
    runAt: string,
  ): Promise<{ runId: string; scheduledFor: string }> {
    const normalizedTarget = normalizeScrapeTarget(target);
    const scheduledFor = normalizeScheduledRunAt(runAt);
    const now = new Date().toISOString();
    const runId = generateId();

    await db.insert(automationRuns).values({
      id: runId,
      type: "scrape",
      status: "pending",
      jobId: null,
      userId: null,
      input: buildScrapeInput(
        {
          target: normalizedTarget,
        },
        {
          includeAction: true,
          scheduledFor,
        },
      ),
      progress: DEFAULT_PROGRESS,
      currentStep: null,
      totalSteps: null,
      exitCode: 0,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt: null,
      createdAt: now,
      updatedAt: now,
    });

    this.options.queueScheduledRun(runId, scheduledFor);
    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: resolveScrapeAction(normalizedTarget),
        status: "pending",
        message: `Scheduled for ${scheduledFor}`,
      }),
    );

    return { runId, scheduledFor };
  }

  async createScrapeRun(target: AutomationScrapeTarget): Promise<string> {
    const normalizedTarget = normalizeScrapeTarget(target);
    const now = new Date().toISOString();
    const runId = generateId();

    await db.insert(automationRuns).values({
      id: runId,
      type: "scrape",
      status: "pending",
      jobId: null,
      userId: null,
      input: buildScrapeInput(
        {
          target: normalizedTarget,
        },
        {
          includeAction: false,
        },
      ),
      progress: DEFAULT_PROGRESS,
      currentStep: null,
      totalSteps: null,
      exitCode: 0,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt: null,
      createdAt: now,
      updatedAt: now,
    });

    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: resolveScrapeAction(normalizedTarget),
        status: "pending",
        message: `Queued ${normalizedTarget} scrape`,
      }),
    );

    return runId;
  }
}

import {
  AUTOMATION_SCRAPE_TARGETS,
  type AutomationScrapeTarget,
  automationScrapeTargetToAction,
} from "@bao/shared/constants/automation";
import type { EmailResponseTone } from "@bao/shared/schemas/automation-email.schema";
import type { JsonObject } from "@bao/shared/utils/json";
import { AutomationValidationError } from "./automation-errors";

export interface JobApplyPayload {
  jobUrl: string;
  resumeId: string;
  coverLetterId?: string;
  jobId?: string;
  customAnswers?: Record<string, string>;
}

export interface JobApplyExecutionPayload {
  jobUrl: string;
  resumeId: string;
  coverLetterId?: string;
  jobId?: string;
  customAnswers: Record<string, string>;
}

export interface EmailResponseExecutionPayload {
  subject: string;
  message: string;
  sender?: string;
  tone: EmailResponseTone;
  recipientEmail?: string;
  deliverAfterGeneration: boolean;
}

export interface ScheduledRunMetadata {
  runAt: string;
}

export interface ScrapeExecutionPayload {
  target: AutomationScrapeTarget;
}

const isScrapeTarget = (value: string): value is AutomationScrapeTarget =>
  AUTOMATION_SCRAPE_TARGETS.some((target) => target === value);

const withScheduleMetadata = (input: JsonObject, runAt: string): JsonObject => ({
  ...input,
  schedule: { runAt },
});

const parseCustomAnswers = (input: JsonObject | null): Record<string, string> => {
  if (!input) {
    return {};
  }

  const value = input.customAnswers;
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }

  const parsedAnswers: Record<string, string> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === "string" && entry.length > 0) {
      parsedAnswers[key] = entry;
    }
  }
  return parsedAnswers;
};

export const buildAuditInput = (
  payload: JobApplyExecutionPayload,
  includeAction: boolean,
): JsonObject => {
  const auditInput: JsonObject = {
    jobUrl: payload.jobUrl,
    resumeId: payload.resumeId,
    jobId: payload.jobId ?? null,
    customAnswers: payload.customAnswers,
  };

  if (payload.coverLetterId) {
    auditInput.coverLetterId = payload.coverLetterId;
  }

  if (includeAction) {
    auditInput.action = "job_apply";
  }

  return auditInput;
};

export const parseScheduledRunMetadata = (
  input: JsonObject | null,
): ScheduledRunMetadata | null => {
  if (!input) {
    return null;
  }

  const scheduleValue = input.schedule;
  if (!scheduleValue || typeof scheduleValue !== "object" || Array.isArray(scheduleValue)) {
    return null;
  }

  if (!("runAt" in scheduleValue)) {
    return null;
  }

  const runAt = scheduleValue.runAt;
  if (typeof runAt !== "string" || runAt.trim().length === 0) {
    return null;
  }

  return { runAt: runAt.trim() };
};

export const parseScheduledJobApplyPayload = (input: JsonObject | null): JobApplyPayload | null => {
  if (!input) {
    return null;
  }

  const jobUrl = typeof input.jobUrl === "string" ? input.jobUrl.trim() : "";
  const resumeId = typeof input.resumeId === "string" ? input.resumeId.trim() : "";
  if (jobUrl.length === 0 || resumeId.length === 0) {
    return null;
  }

  const payload: JobApplyPayload = {
    jobUrl,
    resumeId,
  };

  if (typeof input.coverLetterId === "string" && input.coverLetterId.trim().length > 0) {
    payload.coverLetterId = input.coverLetterId.trim();
  }
  if (typeof input.jobId === "string" && input.jobId.trim().length > 0) {
    payload.jobId = input.jobId.trim();
  }

  const customAnswers = parseCustomAnswers(input);
  if (Object.keys(customAnswers).length > 0) {
    payload.customAnswers = customAnswers;
  }

  return payload;
};

export const buildScheduledJobApplyInput = (
  payload: JobApplyExecutionPayload,
  scheduledFor: string,
): JsonObject => withScheduleMetadata(buildAuditInput(payload, true), scheduledFor);

export const buildEmailResponseInput = (
  normalized: EmailResponseExecutionPayload,
  options: { includeAction: boolean; scheduledFor?: string },
): JsonObject => {
  const baseInput: JsonObject = {
    subject: normalized.subject,
    message: normalized.message,
    tone: normalized.tone,
    deliverAfterGeneration: normalized.deliverAfterGeneration,
    ...(normalized.sender ? { sender: normalized.sender } : {}),
    ...(normalized.recipientEmail ? { recipientEmail: normalized.recipientEmail } : {}),
    ...(options.includeAction ? { action: "email_response" } : {}),
  };

  return options.scheduledFor ? withScheduleMetadata(baseInput, options.scheduledFor) : baseInput;
};

export const parseScheduledEmailResponsePayload = (
  input: JsonObject | null,
  options: {
    defaultTone: EmailResponseTone;
    isEmailResponseTone: (value: string) => value is EmailResponseTone;
  },
): EmailResponseExecutionPayload | null => {
  if (!input) {
    return null;
  }

  const subject = typeof input.subject === "string" ? input.subject.trim() : "";
  const message = typeof input.message === "string" ? input.message.trim() : "";
  if (subject.length === 0 || message.length === 0) {
    return null;
  }

  const toneCandidate = typeof input.tone === "string" ? input.tone.trim() : "";
  const tone = options.isEmailResponseTone(toneCandidate) ? toneCandidate : options.defaultTone;

  return {
    subject,
    message,
    tone,
    deliverAfterGeneration: input.deliverAfterGeneration === true,
    ...(typeof input.sender === "string" && input.sender.trim().length > 0
      ? { sender: input.sender.trim() }
      : {}),
    ...(typeof input.recipientEmail === "string" && input.recipientEmail.trim().length > 0
      ? { recipientEmail: input.recipientEmail.trim() }
      : {}),
  };
};

export const resolveScrapeAction = (target: AutomationScrapeTarget): string =>
  automationScrapeTargetToAction(target);

export const normalizeScrapeTarget = (target: string): AutomationScrapeTarget => {
  const normalized = target.trim();
  if (!isScrapeTarget(normalized)) {
    throw new AutomationValidationError("target must be a supported scrape target");
  }
  return normalized;
};

export const buildScrapeInput = (
  payload: ScrapeExecutionPayload,
  options: { includeAction: boolean; scheduledFor?: string },
): JsonObject => {
  const baseInput: JsonObject = {
    target: payload.target,
    ...(options.includeAction ? { action: resolveScrapeAction(payload.target) } : {}),
  };

  return options.scheduledFor ? withScheduleMetadata(baseInput, options.scheduledFor) : baseInput;
};

export const parseScheduledScrapePayload = (
  input: JsonObject | null,
): ScrapeExecutionPayload | null => {
  if (!input || typeof input.target !== "string") {
    return null;
  }

  const normalized = input.target.trim();
  if (!isScrapeTarget(normalized)) {
    return null;
  }

  return {
    target: normalized,
  };
};

import { join, resolve } from "node:path";
import {
  AUTOMATION_MAX_SCREENSHOT_NAME_LENGTH,
  AUTOMATION_MIN_ID_LENGTH,
} from "@bao/shared/constants/automation-limits";
import { COUNT_FOUR, COUNT_SIXTEEN, COUNT_THIRTY_ONE } from "@bao/shared/constants/numeric";
import type { RpaRunResult } from "@bao/shared/schemas/rpa-events.schema";
import { settle } from "@bao/shared/utils/promise";
import { AUTOMATION_SCREENSHOT_DIR } from "../../config/paths";
import {
  MAX_CUSTOM_ANSWER_KEY_LENGTH,
  MAX_CUSTOM_ANSWER_VALUE_LENGTH,
} from "./automation-validation";
import type { RpaScriptExecutionResult } from "./rpa-runner-contracts";

const SUPPORTED_SCREENSHOT_EXTENSIONS = [".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp"] as const;
const RUN_SCREENSHOT_PREFIX = "step";
const RUN_ID_PATTERN = /^[0-9a-f-]+$/i;

const sanitizeStep = (step: {
  action?: unknown;
  status?: unknown;
  message?: unknown;
}): { action: string; status: "ok" | "error" | "skipped"; message?: string } | null => {
  if (!step || typeof step !== "object") {
    return null;
  }
  if (typeof step.action !== "string" || step.action.length > MAX_CUSTOM_ANSWER_KEY_LENGTH) {
    return null;
  }

  const status =
    step.status === "error" || step.status === "ok" || step.status === "skipped"
      ? step.status
      : "ok";
  if (typeof step.message !== "string" || step.message.length > MAX_CUSTOM_ANSWER_VALUE_LENGTH) {
    return { action: step.action, status };
  }

  return { action: step.action, status, message: step.message };
};

const sanitizeSteps = (
  steps: Array<{ action?: unknown; status?: unknown; message?: unknown }>,
): Array<{ action: string; status: "ok" | "error" | "skipped"; message?: string }> =>
  steps
    .map((step) => sanitizeStep(step))
    .filter(
      (step): step is { action: string; status: "ok" | "error" | "skipped"; message?: string } =>
        step !== null,
    );

export const sanitizeRunId = (runId: string, invalidRunIdMessage: string): string => {
  const safeId = runId.trim();
  if (!RUN_ID_PATTERN.test(safeId) || safeId.length < AUTOMATION_MIN_ID_LENGTH) {
    throw new Error(invalidRunIdMessage);
  }
  return safeId;
};

export const resolveRunArtifactDir = (runId: string, invalidRunIdMessage: string): string =>
  join(AUTOMATION_SCREENSHOT_DIR, sanitizeRunId(runId, invalidRunIdMessage));

const resolveScreenshotExtension = (pathValue: string): string => {
  const lastDotIndex = pathValue.lastIndexOf(".");
  const extension = lastDotIndex >= 0 ? pathValue.slice(lastDotIndex).toLowerCase() : "";
  return SUPPORTED_SCREENSHOT_EXTENSIONS.some(
    (supportedExtension) => supportedExtension === extension,
  )
    ? extension
    : ".png";
};

const hashScreenshotSource = (sourcePath: string): string => {
  let hash = 0;
  for (let index = 0; index < sourcePath.length; index += 1) {
    hash = (hash * COUNT_THIRTY_ONE + sourcePath.charCodeAt(index)) >>> 0;
  }
  return hash.toString(COUNT_SIXTEEN).padStart(AUTOMATION_MIN_ID_LENGTH, "0");
};

const resolveScreenshotName = (index: number, sourcePath: string): string => {
  const extension = resolveScreenshotExtension(sourcePath);
  const stepToken = String(index + 1).padStart(2, "0");
  const shortName = `${RUN_SCREENSHOT_PREFIX}-${stepToken}${extension}`;
  if (shortName.length <= AUTOMATION_MAX_SCREENSHOT_NAME_LENGTH) {
    return shortName;
  }

  const fallbackHash = hashScreenshotSource(sourcePath);
  const base = `${RUN_SCREENSHOT_PREFIX}-${stepToken}-`;
  const maxSuffixLength = Math.max(
    COUNT_FOUR,
    AUTOMATION_MAX_SCREENSHOT_NAME_LENGTH - base.length - extension.length,
  );
  return `${base}${fallbackHash.slice(0, maxSuffixLength)}${extension}`;
};

const copySingleScreenshot = async (
  runDir: string,
  index: number,
  sourcePath: string,
): Promise<string | null> => {
  if (!sourcePath.trim()) {
    return null;
  }

  const sourceFile = Bun.file(sourcePath);
  if (!(await sourceFile.exists())) {
    return null;
  }

  const safeFileName = resolveScreenshotName(index, sourcePath);
  const sourceResolvedPath = resolve(sourcePath);
  const destination = join(runDir, safeFileName);
  if (sourceResolvedPath === destination) {
    return safeFileName;
  }

  const bytesResult = await settle(sourceFile.arrayBuffer());
  if (bytesResult.status === "rejected") {
    return null;
  }

  const writeResult = await settle(Bun.write(destination, bytesResult.value));
  if (writeResult.status === "rejected") {
    return null;
  }

  return safeFileName;
};

export const copyAndIndexScreenshots = async (
  runDir: string,
  sourceScreenshots: string[] | undefined,
): Promise<string[]> => {
  if (!Array.isArray(sourceScreenshots) || sourceScreenshots.length === 0) {
    return [];
  }

  const copiedScreenshots = await Promise.all(
    sourceScreenshots.map((sourcePath, index) => copySingleScreenshot(runDir, index, sourcePath)),
  );
  return copiedScreenshots.filter((fileName): fileName is string => typeof fileName === "string");
};

export const normalizeExecutionArtifacts = async (
  _runId: string,
  runDir: string,
  execution: RpaScriptExecutionResult,
): Promise<RpaRunResult> => {
  const terminalResult = execution.result;
  const copiedScreenshots = await copyAndIndexScreenshots(runDir, terminalResult?.screenshots);
  const mergedArtifacts = [
    ...(terminalResult?.artifacts ?? []),
    ...copiedScreenshots.map((fileName, index) => ({
      id: `screenshot-${String(index + 1).padStart(2, "0")}`,
      kind: "screenshot" as const,
      path: fileName,
    })),
  ];

  return {
    success: terminalResult?.success ?? false,
    error: terminalResult?.error ?? execution.error?.message ?? null,
    screenshots: copiedScreenshots,
    artifacts: mergedArtifacts,
    steps: sanitizeSteps(terminalResult?.steps ?? []),
  };
};

import { join } from "node:path";
import {
  AUTOMATION_CLEANUP_LIMIT,
  AUTOMATION_FINISHED_PROGRESS,
  AUTOMATION_MAX_PROGRESS_STEPS,
  AUTOMATION_MAX_SCREENSHOT_RETENTION_DAYS,
} from "@bao/shared/constants/automation-limits";
import { MS_PER_DAY } from "@bao/shared/constants/time";
import type { ErrorEnvelope } from "@bao/shared/schemas/error-envelope.schema";
import { jsonObjectSchema } from "@bao/shared/schemas/json.schema";
import type { RpaRunEvent, RpaRunResult } from "@bao/shared/schemas/rpa-events.schema";
import type { JsonObject } from "@bao/shared/utils/json";
import { safeParseJson } from "@bao/shared/utils/json";
import { and, inArray, sql } from "drizzle-orm";
import { AUTOMATION_SCREENSHOT_DIR } from "../../config/paths";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import type { RpaScriptExecutionResult } from "./rpa-runner-contracts";

const AUTOMATION_TERMINAL_STATUSES = ["success", "error"];
const DECIMAL_RADIX = 10;
const MIN_SCREENSHOT_RETENTION_DAYS = 1;
type ProgressRunEvent = Extract<RpaRunEvent, { eventType: "progress" }>;

const toJsonRecord = (value: object): JsonObject => {
  const parsed = safeParseJson(JSON.stringify(value));
  const objectResult = jsonObjectSchema.safeParse(parsed);
  return objectResult.success ? objectResult.data : {};
};

export const toFiniteNumber = <T>(value: T): number => {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : Number.NaN;
  }
  if (typeof value === "string") {
    const parsed = Number.parseInt(value.trim(), DECIMAL_RADIX);
    return Number.isFinite(parsed) ? parsed : Number.NaN;
  }
  return Number.NaN;
};

export const createProgressUpdate = (event: ProgressRunEvent) => {
  const step = toFiniteNumber(event.step);
  const totalSteps = toFiniteNumber(event.totalSteps);
  const updates: {
    status?: string;
    progress?: number;
    currentStep?: number | null;
    totalSteps?: number | null;
    updatedAt: string;
  } = {
    updatedAt: new Date().toISOString(),
  };

  if (Number.isFinite(totalSteps) && totalSteps > 0) {
    updates.totalSteps = Math.min(AUTOMATION_MAX_PROGRESS_STEPS, Math.trunc(totalSteps));
  }

  if (Number.isFinite(step)) {
    const safeStep = Math.max(0, Math.trunc(step));
    updates.currentStep = updates.totalSteps ? Math.min(safeStep, updates.totalSteps) : safeStep;
    if (Number.isFinite(totalSteps) && totalSteps > 0) {
      updates.progress = Math.min(
        AUTOMATION_FINISHED_PROGRESS,
        Math.max(
          0,
          Math.round(
            (updates.currentStep / (updates.totalSteps || 1)) * AUTOMATION_FINISHED_PROGRESS,
          ),
        ),
      );
    }
  }

  updates.status = typeof event.status === "string" ? event.status : "running";
  return updates;
};

export const purgeExpiredAutomationScreenshots = async (retentionDays: number): Promise<void> => {
  const retention = Math.trunc(
    Number.isFinite(retentionDays) ? retentionDays : MIN_SCREENSHOT_RETENTION_DAYS,
  );
  const safeRetention = Math.min(
    Math.max(retention, MIN_SCREENSHOT_RETENTION_DAYS),
    AUTOMATION_MAX_SCREENSHOT_RETENTION_DAYS,
  );
  const cutoffIso = new Date(Date.now() - safeRetention * MS_PER_DAY).toISOString();

  const staleRuns = await db
    .select({ id: automationRuns.id })
    .from(automationRuns)
    .where(
      and(
        sql`datetime(${automationRuns.createdAt}) < datetime(${cutoffIso})`,
        inArray(automationRuns.status, AUTOMATION_TERMINAL_STATUSES),
      ),
    )
    .limit(AUTOMATION_CLEANUP_LIMIT);

  await Promise.allSettled(
    staleRuns.map((run) =>
      Promise.resolve().then(() => {
        Bun.spawnSync(["rm", "-rf", join(AUTOMATION_SCREENSHOT_DIR, run.id)]);
      }),
    ),
  );
};

export const createFailedRunUpdate = (
  errorMessage: string,
  execution?: {
    exitCode?: number | null;
    timedOut?: boolean;
    aborted?: boolean;
    executionMs?: number | null;
    errorEnvelope?: ErrorEnvelope | null;
  },
) => {
  const now = new Date().toISOString();
  return {
    status: "error",
    output: {
      success: false,
      error: errorMessage,
      screenshots: [],
      steps: [
        {
          action: "automation",
          status: "error" as const,
          message: errorMessage,
        },
      ],
      errorEnvelope: execution?.errorEnvelope ?? null,
    },
    error: errorMessage,
    progress: AUTOMATION_FINISHED_PROGRESS,
    currentStep: 0,
    totalSteps: 0,
    exitCode: execution?.exitCode ?? null,
    timedOut: execution?.timedOut ?? false,
    aborted: execution?.aborted ?? false,
    executionMs: execution?.executionMs ?? null,
    completedAt: now,
    updatedAt: now,
  };
};

export const createCompletedRunUpdate = (
  output: RpaRunResult,
  execution: Pick<RpaScriptExecutionResult, "exitCode" | "timedOut" | "aborted" | "executionMs">,
) => {
  const now = new Date().toISOString();
  const finalStep = Array.isArray(output.steps) ? output.steps.length : 0;

  return {
    status: output.success ? "success" : "error",
    output: toJsonRecord(output),
    screenshots: output.screenshots,
    error: output.error,
    progress: AUTOMATION_FINISHED_PROGRESS,
    currentStep: finalStep,
    totalSteps: finalStep,
    exitCode: execution.exitCode,
    timedOut: execution.timedOut,
    aborted: execution.aborted,
    executionMs: execution.executionMs,
    completedAt: now,
    updatedAt: now,
  };
};

