import { AUTOMATION_RUN_STATUSES } from "@bao/shared/constants/automation";
import type { JsonObject, JsonValue } from "@bao/shared/utils/json";
import { and, eq, notInArray } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import { createServerLogger } from "../../utils/logger";
import { parseScheduledRunMetadata } from "./automation-run-inputs";
import { createFailedRunUpdate } from "./automation-run-persistence-updates";
import type { AutomationRunRow } from "./automation-service-contracts";

const automationSchedulerLogger = createServerLogger("automation-run-scheduler");
export const ORPHANED_RUNNING_RUN_RECLAIMED_MESSAGE = "Orphaned running run reclaimed on startup";
export const UNKNOWN_RUN_STATUS_RECLAIMED_MESSAGE =
  "Unknown automation run status normalized to error on startup";
export const PENDING_RUN_MISSING_SCHEDULE_METADATA_MESSAGE =
  "Pending automation run missing schedule metadata";

type SchedulerTimer = ReturnType<typeof setTimeout>;

const asJsonRecord = (value: JsonValue | null | undefined): JsonObject | null =>
  value && typeof value === "object" && !Array.isArray(value) ? value : null;

export class AutomationRunScheduler {
  private readonly scheduledRunTimers = new Map<string, SchedulerTimer>();
  private recoveryInFlight = false;

  constructor(private readonly executeScheduledRun: (runId: string) => Promise<void>) {}

  queue(runId: string, runAt: string): void {
    this.clear(runId);

    const delayMs = Math.max(0, new Date(runAt).getTime() - Date.now());
    const timer = setTimeout(() => {
      this.scheduledRunTimers.delete(runId);
      this.executeScheduledRun(runId).then(
        () => undefined,
        (error) => {
          automationSchedulerLogger.error(
            "[automation] scheduled run execution failed",
            error instanceof Error ? error.message : String(error),
          );
        },
      );
    }, delayMs);
    if (
      typeof timer === "object" &&
      timer !== null &&
      "unref" in timer &&
      typeof timer.unref === "function"
    ) {
      timer.unref();
    }

    this.scheduledRunTimers.set(runId, timer);
  }

  clear(runId: string): void {
    const timer = this.scheduledRunTimers.get(runId);
    if (!timer) {
      return;
    }

    clearTimeout(timer);
    this.scheduledRunTimers.delete(runId);
  }

  async reclaimRunningRuns(): Promise<void> {
    await db
      .update(automationRuns)
      .set(createFailedRunUpdate(UNKNOWN_RUN_STATUS_RECLAIMED_MESSAGE))
      .where(notInArray(automationRuns.status, [...AUTOMATION_RUN_STATUSES]));

    await db
      .update(automationRuns)
      .set(createFailedRunUpdate(ORPHANED_RUNNING_RUN_RECLAIMED_MESSAGE))
      .where(eq(automationRuns.status, "running"));
  }

  async restorePendingRuns(limit: number): Promise<void> {
    if (this.recoveryInFlight) {
      return;
    }

    this.recoveryInFlight = true;
    await this.restorePendingRunsUnlocked(limit).finally(() => {
      this.recoveryInFlight = false;
    });
  }

  private async restorePendingRunsUnlocked(limit: number): Promise<void> {
    const pendingRows = await db
      .select()
      .from(automationRuns)
      .where(eq(automationRuns.status, "pending"))
      .limit(limit);
    const pendingRunsWithoutSchedule: string[] = [];

    for (const row of pendingRows satisfies AutomationRunRow[]) {
      const metadata = parseScheduledRunMetadata(asJsonRecord(row.input));
      if (!metadata) {
        pendingRunsWithoutSchedule.push(row.id);
        continue;
      }

      this.queue(row.id, metadata.runAt);
    }

    await Promise.all(
      pendingRunsWithoutSchedule.map((runId) =>
        this.markPendingRunWithoutScheduleMetadata(runId),
      ),
    );
  }

  private async markPendingRunWithoutScheduleMetadata(runId: string): Promise<void> {
    await db
      .update(automationRuns)
      .set(createFailedRunUpdate(PENDING_RUN_MISSING_SCHEDULE_METADATA_MESSAGE))
      .where(and(eq(automationRuns.id, runId), eq(automationRuns.status, "pending")));
  }
}

import { API_ERROR_EMAIL_DELIVERY_SETTINGS_MISSING } from "@bao/shared/constants/api-errors";
import { AUTOMATION_SCHEDULE_RETRY_DELAY_MS } from "@bao/shared/constants/automation-limits";
import type { JsonObject, JsonValue } from "@bao/shared/utils/json";
import { settle } from "@bao/shared/utils/promise";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import { broadcastAutomationEvent } from "../../ws/automation.ws";
import { executeEmailResponseRun, markEmailResponseRunStarted } from "./automation-email-response";
import {
  DEFAULT_EMAIL_RESPONSE_TONE,
  isEmailResponseTone,
} from "./automation-email-response-payload";
import { AutomationConcurrencyLimitError } from "./automation-errors";
import { normalizeJobApplyPayload } from "./automation-job-apply-preparation";
import {
  buildScheduledJobApplyInput,
  type JobApplyPayload,
  parseScheduledEmailResponsePayload,
  parseScheduledJobApplyPayload,
  parseScheduledScrapePayload,
} from "./automation-run-inputs";
import { markRunFailed } from "./automation-run-persistence";
import { executeScrapeRun } from "./automation-scrape-run";
import type { AutomationRunRow, CreateProgressEvent } from "./automation-service-contracts";
import {
  loadAutomationSettings,
  loadEmailTransportConfig,
  tryLoadAIService,
} from "./automation-settings-support";

const SCHEDULED_ACTION_JOB_APPLY = "job_apply";

const asJsonRecord = (value: JsonValue | null | undefined): JsonObject | null =>
  value && typeof value === "object" && !Array.isArray(value) ? value : null;

type ScheduledRunQueue = (runId: string, runAt: string) => void;
type ReadRunRow = (runId: string) => Promise<AutomationRunRow | null>;
type RunJobApply = (runId: string, payload: JobApplyPayload) => Promise<void>;

interface AutomationScheduledRunExecutorOptions {
  createProgressEvent: CreateProgressEvent;
  queueScheduledRun: ScheduledRunQueue;
  readRunRow: ReadRunRow;
  runJobApply: RunJobApply;
}

export class AutomationScheduledRunExecutor {
  constructor(private readonly options: AutomationScheduledRunExecutorOptions) {}

  async execute(runId: string): Promise<void> {
    const row = await this.options.readRunRow(runId);
    if (row?.status !== "pending") {
      return;
    }

    if (row.type === "job_apply") {
      await this.executeJobApply(row);
      return;
    }

    if (row.type === "email") {
      await this.executeEmail(row);
      return;
    }

    if (row.type === "scrape") {
      await this.executeScrape(row);
    }
  }

  private async failValidation(runId: string, errorMessage: string): Promise<void> {
    const automationSettings = await loadAutomationSettings();
    await markRunFailed(runId, errorMessage, automationSettings);
    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: "automation",
        status: "error",
        message: errorMessage,
      }),
    );
  }

  private async executeJobApply(row: AutomationRunRow): Promise<void> {
    const payload = parseScheduledJobApplyPayload(asJsonRecord(row.input));
    if (!payload) {
      await this.failValidation(row.id, "Scheduled job-apply payload is invalid");
      return;
    }

    const executionResult = await settle(this.options.runJobApply(row.id, payload));
    if (executionResult.status === "fulfilled") {
      return;
    }

    if (executionResult.reason instanceof AutomationConcurrencyLimitError) {
      await this.requeueJobApplyRun(row.id, payload);
      return;
    }

    throw executionResult.reason;
  }

  private async requeueJobApplyRun(runId: string, payload: JobApplyPayload): Promise<void> {
    const nextRunAt = new Date(Date.now() + AUTOMATION_SCHEDULE_RETRY_DELAY_MS).toISOString();
    const normalizedPayload = normalizeJobApplyPayload(payload);

    await db
      .update(automationRuns)
      .set({
        input: buildScheduledJobApplyInput(normalizedPayload, nextRunAt),
        status: "pending",
        updatedAt: new Date().toISOString(),
      })
      .where(eq(automationRuns.id, runId));

    this.options.queueScheduledRun(runId, nextRunAt);
    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: SCHEDULED_ACTION_JOB_APPLY,
        status: "pending",
        message: `Concurrency limit reached, retrying at ${nextRunAt}`,
      }),
    );
  }

  private async executeEmail(row: AutomationRunRow): Promise<void> {
    const payload = parseScheduledEmailResponsePayload(asJsonRecord(row.input), {
      defaultTone: DEFAULT_EMAIL_RESPONSE_TONE,
      isEmailResponseTone,
    });
    if (!payload) {
      await this.failValidation(row.id, "Scheduled email payload is invalid");
      return;
    }

    await markEmailResponseRunStarted(row.id, payload);
    await executeEmailResponseRun(row.id, payload, {
      loadAIService: tryLoadAIService,
      loadEmailTransportConfig: () =>
        loadEmailTransportConfig(API_ERROR_EMAIL_DELIVERY_SETTINGS_MISSING),
      createProgressEvent: this.options.createProgressEvent,
      broadcastProgressEvent: broadcastAutomationEvent,
    });
  }

  private async executeScrape(row: AutomationRunRow): Promise<void> {
    const payload = parseScheduledScrapePayload(asJsonRecord(row.input));
    if (!payload) {
      await this.failValidation(row.id, "Scheduled scrape payload is invalid");
      return;
    }

    await executeScrapeRun(row.id, payload.target, this.options.createProgressEvent);
  }
}

import {
  AUTOMATION_SCRAPE_JOB_TARGETS,
  type AutomationScrapePortalId,
  automationScrapeTargetToPortalId,
  buildRpaCapabilityIdFromScrapeTarget,
  RPA_CAPABILITY_INSTALL_CHROMIUM_REMEDIATION,
  type RpaCapabilityAuditEntry,
  type RpaCapabilityAuditReport,
  type RpaCapabilityAuditSummary,
  type RpaCapabilityIssue,
} from "@bao/shared/constants/automation";
import { settle } from "@bao/shared/utils/promise";
import { resolveInstalledChromiumExecutable } from "../../config/paths";
import { loadJobProviderSettings } from "../jobs/providers/provider-settings";

interface ScrapePortalAuditConfig {
  name: string;
  enabled: boolean;
  fallbackUrl: string;
}

interface ScrapePortalAuditSnapshot {
  portalConfigById: Map<AutomationScrapePortalId, ScrapePortalAuditConfig>;
  sharedSettingsIssue: RpaCapabilityIssue | null;
}

/**
 * Job apply drives a real browser, so the capability is only honestly
 * "configured" when a Playwright Chromium build is actually installed.
 */
const createJobApplyCapabilityAuditEntry = (): RpaCapabilityAuditEntry => {
  const chromiumExecutable = resolveInstalledChromiumExecutable();
  const chromiumInstalled = chromiumExecutable !== null;

  return {
    id: "job_apply",
    category: "job_apply",
    name: "Job Apply",
    target: null,
    implemented: true,
    configured: chromiumInstalled,
    enabled: chromiumInstalled,
    manualRunAvailable: chromiumInstalled,
    scheduledRunAvailable: chromiumInstalled,
    runHistoryAvailable: true,
    liveUpdatesAvailable: true,
    issues: chromiumInstalled
      ? []
      : [
          {
            code: "chromium_executable_missing",
            remediation: RPA_CAPABILITY_INSTALL_CHROMIUM_REMEDIATION,
          },
        ],
  };
};

const createStudioScrapeCapabilityAuditEntry = (): RpaCapabilityAuditEntry => ({
  id: buildRpaCapabilityIdFromScrapeTarget("studios"),
  category: "scrape",
  name: "Studios",
  target: "studios",
  implemented: true,
  configured: true,
  enabled: true,
  manualRunAvailable: true,
  scheduledRunAvailable: true,
  runHistoryAvailable: true,
  liveUpdatesAvailable: true,
  issues: [],
});

const summarizeRpaCapabilities = (
  capabilities: readonly RpaCapabilityAuditEntry[],
): RpaCapabilityAuditSummary =>
  capabilities.reduce<RpaCapabilityAuditSummary>(
    (accumulator, capability) => ({
      total: accumulator.total + 1,
      configured: accumulator.configured + (capability.configured ? 1 : 0),
      manualRunAvailable: accumulator.manualRunAvailable + (capability.manualRunAvailable ? 1 : 0),
      scheduledRunAvailable:
        accumulator.scheduledRunAvailable + (capability.scheduledRunAvailable ? 1 : 0),
      runHistoryAvailable:
        accumulator.runHistoryAvailable + (capability.runHistoryAvailable ? 1 : 0),
      liveUpdatesAvailable:
        accumulator.liveUpdatesAvailable + (capability.liveUpdatesAvailable ? 1 : 0),
    }),
    {
      total: 0,
      configured: 0,
      manualRunAvailable: 0,
      scheduledRunAvailable: 0,
      runHistoryAvailable: 0,
      liveUpdatesAvailable: 0,
    },
  );

const loadScrapePortalAuditSnapshot = async (): Promise<ScrapePortalAuditSnapshot> => {
  const providerSettingsResult = await settle(loadJobProviderSettings());
  const portalConfigById = new Map<AutomationScrapePortalId, ScrapePortalAuditConfig>();
  const sharedSettingsIssue =
    providerSettingsResult.status === "rejected"
      ? ({ code: "provider_settings_unavailable" } satisfies RpaCapabilityIssue)
      : null;

  if (providerSettingsResult.status === "fulfilled") {
    for (const portal of providerSettingsResult.value.gamingPortals) {
      portalConfigById.set(portal.id, {
        name: portal.name,
        enabled: portal.enabled,
        fallbackUrl: portal.fallbackUrl,
      });
    }
  }

  return {
    portalConfigById,
    sharedSettingsIssue,
  };
};

const buildScrapeCapabilityIssues = (
  configuredPortal: ScrapePortalAuditConfig | null,
  portalId: AutomationScrapePortalId,
  sharedSettingsIssue: RpaCapabilityIssue | null,
): RpaCapabilityIssue[] => {
  if (sharedSettingsIssue) {
    return [sharedSettingsIssue];
  }

  if (!configuredPortal) {
    return [{ code: "portal_configuration_missing", portalId }];
  }

  const issues: RpaCapabilityIssue[] = [];
  if (!configuredPortal.enabled) {
    issues.push({
      code: "portal_disabled",
      portalId,
      portalName: configuredPortal.name,
    });
  }
  if (configuredPortal.fallbackUrl.trim().length === 0) {
    issues.push({
      code: "portal_fallback_url_missing",
      portalId,
      portalName: configuredPortal.name,
    });
  }
  return issues;
};

const buildJobScrapeCapabilityAuditEntry = (
  target: (typeof AUTOMATION_SCRAPE_JOB_TARGETS)[number],
  auditSnapshot: ScrapePortalAuditSnapshot,
): RpaCapabilityAuditEntry => {
  const portalId = automationScrapeTargetToPortalId(target);
  const configuredPortal = auditSnapshot.portalConfigById.get(portalId) ?? null;
  const issues = buildScrapeCapabilityIssues(
    configuredPortal,
    portalId,
    auditSnapshot.sharedSettingsIssue,
  );
  const enabled = configuredPortal?.enabled === true;
  const configured = Boolean(
    configuredPortal?.enabled && configuredPortal.fallbackUrl.trim().length > 0,
  );

  return {
    id: buildRpaCapabilityIdFromScrapeTarget(target),
    category: "scrape",
    name: configuredPortal?.name ?? portalId,
    target,
    implemented: true,
    configured,
    enabled,
    manualRunAvailable: true,
    scheduledRunAvailable: true,
    runHistoryAvailable: true,
    liveUpdatesAvailable: true,
    issues,
  };
};

export const createRpaCapabilityAuditReport = async (): Promise<RpaCapabilityAuditReport> => {
  const auditSnapshot = await loadScrapePortalAuditSnapshot();
  const capabilities: RpaCapabilityAuditEntry[] = [
    createJobApplyCapabilityAuditEntry(),
    createStudioScrapeCapabilityAuditEntry(),
    ...AUTOMATION_SCRAPE_JOB_TARGETS.map((target) =>
      buildJobScrapeCapabilityAuditEntry(target, auditSnapshot),
    ),
  ];

  return {
    generatedAt: new Date().toISOString(),
    summary: summarizeRpaCapabilities(capabilities),
    capabilities,
  };
};

import { describe, expect, test } from "bun:test";
import type { ScraperOperationResult } from "@bao/shared/types/jobs";
import { resolveScrapeRunOutcome } from "./automation-scrape-run";

/**
 * Regression cover for a false green found by running the real scrape endpoint: a
 * `jobs_hitmarker` run returned `scraped: 0` with
 * `errors: ["Missing enabled hitmarker portal fallbackUrl."]` and was still recorded
 * as `status: "success"`, `exitCode: 0`. Run history showed a misconfigured target as
 * a clean success, and no test asserted the recorded status at all.
 */

const buildResult = (overrides: Partial<ScraperOperationResult>): ScraperOperationResult => ({
  scraped: 0,
  upserted: 0,
  errors: [],
  enrichment: { enabled: true, enrichedRecords: 0, warnings: [] },
  ...overrides,
});

describe("resolveScrapeRunOutcome", () => {
  test("fails a run that collected nothing and reported errors", () => {
    const outcome = resolveScrapeRunOutcome(
      buildResult({ errors: ["Missing enabled hitmarker portal fallbackUrl."] }),
    );
    expect(outcome.status).toBe("error");
    expect(outcome.exitCode).toBe(1);
    expect(outcome.error).toBe("Missing enabled hitmarker portal fallbackUrl.");
  });

  test("joins multiple errors into the recorded reason", () => {
    const outcome = resolveScrapeRunOutcome(buildResult({ errors: ["first", "second"] }));
    expect(outcome.error).toBe("first; second");
  });

  test("succeeds a clean run", () => {
    const outcome = resolveScrapeRunOutcome(buildResult({ scraped: 12, upserted: 12 }));
    expect(outcome.status).toBe("success");
    expect(outcome.exitCode).toBe(0);
    expect(outcome.error).toBe(null);
  });

  test("keeps a partial harvest successful so one bad page does not discard the rest", () => {
    const outcome = resolveScrapeRunOutcome(
      buildResult({ scraped: 9, upserted: 9, errors: ["one listing page timed out"] }),
    );
    expect(outcome.status).toBe("success");
    expect(outcome.error).toBe(null);
  });

  test("succeeds an empty-but-clean run, which is a real no-new-results outcome", () => {
    const outcome = resolveScrapeRunOutcome(buildResult({}));
    expect(outcome.status).toBe("success");
  });
});

import {
  API_ERROR_SCRAPE_JOBS_FAILED,
  API_ERROR_SCRAPE_STUDIOS_FAILED,
} from "@bao/shared/constants/api-errors";
import {
  type AutomationScrapeTarget,
  isAutomationJobScrapeTarget,
  type RpaCapabilityAuditReport,
} from "@bao/shared/constants/automation";
import { AUTOMATION_FINISHED_PROGRESS } from "@bao/shared/constants/automation-limits";
import type { AutomationRunStatus } from "@bao/shared/constants/automation";
import { jsonObjectSchema } from "@bao/shared/schemas/json.schema";
import type { ScraperOperationResult } from "@bao/shared/types/jobs";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import type { JsonObject } from "@bao/shared/utils/json";
import { safeParseJson } from "@bao/shared/utils/json";
import { settle } from "@bao/shared/utils/promise";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import { broadcastAutomationEvent } from "../../ws/automation.ws";
import { scraperService } from "../scraper-service";
import {
  buildScrapeInput,
  normalizeScrapeTarget,
  resolveScrapeAction,
} from "./automation-run-inputs";
import { markRunFailed } from "./automation-run-persistence";
import { createRpaCapabilityAuditReport } from "./automation-scrape-audit";
import type { CreateProgressEvent } from "./automation-service-contracts";
import { loadAutomationSettings } from "./automation-settings-support";

const DEFAULT_PROGRESS = 0;

const toJsonRecord = (value: object): JsonObject => {
  const parsed = safeParseJson(JSON.stringify(value));
  const objectResult = jsonObjectSchema.safeParse(parsed);
  return objectResult.success ? objectResult.data : {};
};

const executeScrapeTarget = (target: AutomationScrapeTarget): Promise<ScraperOperationResult> => {
  if (!isAutomationJobScrapeTarget(target)) {
    return scraperService.scrapeStudios();
  }

  return scraperService.scrapeJobsForTarget(target);
};

/** Non-zero process exit used for every failed automation run. */
const AUTOMATION_FAILURE_EXIT_CODE = 1;

const resolveRunStartMessage = (target: AutomationScrapeTarget): string =>
  isAutomationJobScrapeTarget(target)
    ? `Running ${target} scrape`
    : "Importing the curated studio directory";

const resolveRunCompleteMessage = (
  target: AutomationScrapeTarget,
  result: ScraperOperationResult,
): string => {
  const upsertSummary = `${result.upserted} upserted, ${result.enrichment.enrichedRecords} enriched)`;
  return isAutomationJobScrapeTarget(target)
    ? `${target} scrape completed (${result.scraped} scraped, ${upsertSummary}`
    : `curated studio directory import completed (${result.scraped} imported, ${upsertSummary}`;
};

/**
 * A run that collected nothing because the target was misconfigured is a failure,
 * not a success.
 *
 * This used to be hardcoded to `success` with `exitCode: 0`, so a scrape that
 * returned `scraped: 0` alongside `errors: ["Missing enabled hitmarker portal
 * fallbackUrl."]` was indistinguishable in the run history from a scrape that
 * genuinely worked. Partial runs — some records collected despite errors — stay
 * successful so a single flaky portal page does not discard the rest of the harvest;
 * the errors remain in `output.errors` either way.
 */
export const resolveScrapeRunOutcome = (
  result: ScraperOperationResult,
): {
  status: Extract<AutomationRunStatus, "success" | "error">;
  error: string | null;
  exitCode: number;
} => {
  if (result.errors.length > 0 && result.scraped === 0) {
    return {
      status: "error",
      error: result.errors.join("; "),
      exitCode: AUTOMATION_FAILURE_EXIT_CODE,
    };
  }
  return { status: "success", error: null, exitCode: 0 };
};

const markScrapeRunStarted = async (
  runId: string,
  target: AutomationScrapeTarget,
  createProgressEvent: CreateProgressEvent,
): Promise<void> => {
  const now = new Date().toISOString();
  await db
    .update(automationRuns)
    .set({
      status: "running",
      input: buildScrapeInput({ target }, { includeAction: false }),
      progress: DEFAULT_PROGRESS,
      currentStep: 0,
      totalSteps: 1,
      exitCode: 0,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt: now,
      completedAt: null,
      updatedAt: now,
    })
    .where(eq(automationRuns.id, runId));

  broadcastAutomationEvent(
    createProgressEvent({
      runId,
      action: resolveScrapeAction(target),
      status: "running",
      message: resolveRunStartMessage(target),
      step: 0,
      totalSteps: 1,
    }),
  );
};

const failScrapeRun = async (params: {
  runId: string;
  target: AutomationScrapeTarget;
  reason: Error;
  executionMs: number;
  createProgressEvent: CreateProgressEvent;
}): Promise<void> => {
  const automationSettings = await loadAutomationSettings();
  const errorMessage = toErrorMessage(
    params.reason,
    params.target === "studios" ? API_ERROR_SCRAPE_STUDIOS_FAILED : API_ERROR_SCRAPE_JOBS_FAILED,
  );
  await markRunFailed(params.runId, errorMessage, automationSettings, {
    exitCode: AUTOMATION_FAILURE_EXIT_CODE,
    timedOut: false,
    aborted: false,
    executionMs: params.executionMs,
    errorEnvelope: null,
  });
  broadcastAutomationEvent(
    params.createProgressEvent({
      runId: params.runId,
      action: resolveScrapeAction(params.target),
      status: "error",
      message: errorMessage,
      step: 1,
      totalSteps: 1,
    }),
  );
};

const completeScrapeRun = async (params: {
  runId: string;
  target: AutomationScrapeTarget;
  result: ScraperOperationResult;
  executionMs: number;
  createProgressEvent: CreateProgressEvent;
}): Promise<void> => {
  const completedAt = new Date().toISOString();
  const output = toJsonRecord({
    target: params.target,
    scraped: params.result.scraped,
    upserted: params.result.upserted,
    errors: params.result.errors,
    enrichment: params.result.enrichment,
  });

  const outcome = resolveScrapeRunOutcome(params.result);

  await db
    .update(automationRuns)
    .set({
      status: outcome.status,
      output,
      error: outcome.error,
      progress: AUTOMATION_FINISHED_PROGRESS,
      currentStep: 1,
      totalSteps: 1,
      exitCode: outcome.exitCode,
      timedOut: false,
      aborted: false,
      executionMs: params.executionMs,
      completedAt,
      updatedAt: completedAt,
    })
    .where(eq(automationRuns.id, params.runId));

  broadcastAutomationEvent(
    params.createProgressEvent({
      runId: params.runId,
      action: resolveScrapeAction(params.target),
      status: outcome.status,
      message: outcome.error ?? resolveRunCompleteMessage(params.target, params.result),
      step: 1,
      totalSteps: 1,
    }),
  );
};

export const executeScrapeRun = async (
  runId: string,
  target: AutomationScrapeTarget,
  createProgressEvent: CreateProgressEvent,
): Promise<void> => {
  const normalizedTarget = normalizeScrapeTarget(target);
  const startedAt = Date.now();
  await markScrapeRunStarted(runId, normalizedTarget, createProgressEvent);
  const scrapeResult = await settle(executeScrapeTarget(normalizedTarget));

  if (scrapeResult.status === "rejected") {
    await failScrapeRun({
      runId,
      target: normalizedTarget,
      reason: scrapeResult.reason,
      executionMs: Date.now() - startedAt,
      createProgressEvent,
    });
    return;
  }

  await completeScrapeRun({
    runId,
    target: normalizedTarget,
    result: scrapeResult.value,
    executionMs: Date.now() - startedAt,
    createProgressEvent,
  });
};

