import type { EmailTransportRuntimeConfig } from "../email-delivery-service";
import { AutomationValidationError } from "./automation-errors";

const MIN_CONCURRENT_RUNS = 1;
const MIN_SCHEDULE_LEAD_TIME_MS = 1_000;
const LEGACY_AUTOMATION_TIMEOUT_SECONDS = 30;

type SettingsAutomationRow = {
  id: string;
  automationSettings: AutomationSettings | null;
};

export const normalizeAndPersistAutomationSettings = async (
  row: SettingsAutomationRow,
): Promise<AutomationSettings | null> => {
  if (!row.automationSettings) {
    return null;
  }

  const parsedSettings = automationSettingsSchema.safeParse(row.automationSettings);
  if (!parsedSettings.success) {
    return null;
  }

  const normalized = normalizeAutomationSettings(parsedSettings.data);
  if (
    parsedSettings.data.defaultTimeout === LEGACY_AUTOMATION_TIMEOUT_SECONDS &&
    normalized.defaultTimeout !== parsedSettings.data.defaultTimeout
  ) {
    await settle(
      db
        .update(settings)
        .set({
          automationSettings: normalized,
          updatedAt: new Date().toISOString(),
        })
        .where(eq(settings.id, row.id)),
    );
  }

  return normalized;
};

export const loadAutomationSettings = async (): Promise<AutomationSettings> => {
  const settingsQueryResult = await settle(
    db.select().from(settings).where(eq(settings.id, DEFAULT_SETTINGS_ID)).limit(1),
  );
  if (settingsQueryResult.status === "rejected") {
    return DEFAULT_AUTOMATION_SETTINGS;
  }

  const rows = settingsQueryResult.value;
  if (rows.length > 0) {
    return (await normalizeAndPersistAutomationSettings(rows[0])) ?? DEFAULT_AUTOMATION_SETTINGS;
  }

  return DEFAULT_AUTOMATION_SETTINGS;
};

/**
 * Resolve automation script timeout in ms from settings (legacy 30s normalized).
 */
export const resolveAutomationTimeoutMs = (settingsValue: AutomationSettings): number => {
  const normalized = normalizeAutomationSettings(settingsValue);
  const seconds =
    Number.isFinite(normalized.defaultTimeout) && normalized.defaultTimeout > 0
      ? Math.trunc(normalized.defaultTimeout)
      : SCHEMA_DEFAULT_AUTOMATION_TIMEOUT_SECONDS;
  const clamped = Math.min(Math.max(1, seconds), SCHEMA_MAX_AUTOMATION_TIMEOUT_SECONDS);
  return clamped * MS_PER_SECOND;
};

export const resolveMaxConcurrentRuns = (settingsValue: AutomationSettings): number => {
  const configured = Number.isFinite(settingsValue.maxConcurrentRuns)
    ? Math.trunc(settingsValue.maxConcurrentRuns)
    : DEFAULT_AUTOMATION_SETTINGS.maxConcurrentRuns;

  return Math.min(Math.max(MIN_CONCURRENT_RUNS, configured), AUTOMATION_MAX_CONCURRENT_RUNS);
};

export const tryLoadAIService = async (): Promise<AIService | null> => {
  const settingsQueryResult = await settle(
    db.select().from(settings).where(eq(settings.id, DEFAULT_SETTINGS_ID)).limit(1),
  );
  if (settingsQueryResult.status === "rejected") {
    return null;
  }

  const [row] = settingsQueryResult.value;
  return AIService.fromSettings({ ...row, ...decryptProviderKeys(row) });
};

export const loadEmailTransportConfig = async (
  missingSettingsMessage: string,
): Promise<EmailTransportRuntimeConfig> => {
  const settingsQueryResult = await settle(
    db.select().from(settings).where(eq(settings.id, DEFAULT_SETTINGS_ID)).limit(1),
  );
  if (settingsQueryResult.status === "rejected") {
    throw new Error(missingSettingsMessage);
  }

  const [row] = settingsQueryResult.value;
  const parsedTransportSettings = emailTransportSettingsSchema.safeParse(
    row?.emailTransportSettings ?? DEFAULT_EMAIL_TRANSPORT_SETTINGS,
  );

  if (!parsedTransportSettings.success) {
    throw new Error(missingSettingsMessage);
  }

  const hasPassword = Boolean(row?.emailTransportPassword);
  if (!isEmailTransportConfigured(parsedTransportSettings.data, hasPassword)) {
    throw new Error(missingSettingsMessage);
  }

  return {
    ...parsedTransportSettings.data,
    password: row?.emailTransportPassword ?? null,
  };
};

export const normalizeScheduledRunAt = (runAt: string): string => {
  const parsedRunAt = new Date(runAt);
  const targetMs = parsedRunAt.getTime();
  if (Number.isNaN(targetMs)) {
    throw new AutomationValidationError("runAt must be a valid ISO timestamp");
  }

  const leadTimeMs = targetMs - Date.now();
  if (leadTimeMs < MIN_SCHEDULE_LEAD_TIME_MS) {
    throw new AutomationValidationError("runAt must be at least 1 second in the future");
  }
  if (leadTimeMs > AUTOMATION_MAX_SCHEDULE_LEAD_TIME_MS) {
    throw new AutomationValidationError("runAt must be within 30 days");
  }

  return parsedRunAt.toISOString();
};

import { afterEach, describe, expect, test } from "bun:test";
import { API_ERROR_JOB_URL_DISALLOWED_HOST } from "@bao/shared/constants/api-errors";
import { sanitizeAndValidateJobUrl } from "./automation-validation";

const PRIVATE_FIXTURE_URL = "http://127.0.0.1:4173/apply";
const PUBLIC_FIXTURE_URL = "https://example.com/jobs/apply";

const originalAllowPrivateHosts = process.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS;

afterEach(() => {
  if (originalAllowPrivateHosts === undefined) {
    delete process.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS;
    delete Bun.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS;
    return;
  }
  process.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS = originalAllowPrivateHosts;
  Bun.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS = originalAllowPrivateHosts;
});

describe("sanitizeAndValidateJobUrl private-host SSRF gate", () => {
  test("denies loopback hosts by default", () => {
    delete process.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS;
    delete Bun.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS;

    expect(() => sanitizeAndValidateJobUrl(PRIVATE_FIXTURE_URL)).toThrow(
      API_ERROR_JOB_URL_DISALLOWED_HOST,
    );
  });

  test("allows private hosts only when BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS is true", () => {
    process.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS = "true";
    Bun.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS = "true";

    expect(sanitizeAndValidateJobUrl(PRIVATE_FIXTURE_URL)).toBe(PRIVATE_FIXTURE_URL);
  });

  test("still accepts public https job URLs when private-host opt-in is off", () => {
    delete process.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS;
    delete Bun.env.BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS;

    expect(sanitizeAndValidateJobUrl(PUBLIC_FIXTURE_URL)).toBe(PUBLIC_FIXTURE_URL);
  });
});

import {
  API_ERROR_CUSTOM_ANSWERS_KEY_EXCEEDS,
  API_ERROR_CUSTOM_ANSWERS_KEYS,
  API_ERROR_CUSTOM_ANSWERS_MAX_COUNT,
  API_ERROR_CUSTOM_ANSWERS_OBJECT,
  API_ERROR_CUSTOM_ANSWERS_VALUE_EXCEEDS,
  API_ERROR_CUSTOM_ANSWERS_VALUE_MUST_BE_STRING,
  API_ERROR_JOB_URL_ABSOLUTE,
  API_ERROR_JOB_URL_DISALLOWED_HOST,
  API_ERROR_JOB_URL_EXCEEDS_LENGTH,
  API_ERROR_JOB_URL_HTTP_ONLY,
  API_ERROR_JOB_URL_NO_CREDENTIALS,
  API_ERROR_JOB_URL_REQUIRED,
} from "@bao/shared/constants/api-errors";
import {
  AUTOMATION_MAX_CUSTOM_ANSWER_COUNT,
  AUTOMATION_MAX_CUSTOM_ANSWER_KEY_LENGTH,
  AUTOMATION_MAX_CUSTOM_ANSWER_VALUE_LENGTH,
  AUTOMATION_MAX_JOB_URL_LENGTH,
} from "@bao/shared/constants/automation-limits";
import { DEFAULT_HOST, LOOPBACK_HOST_IPV4 } from "@bao/shared/constants/runtime";
import { isLoopbackOrPrivateHost } from "@bao/shared/utils/private-host";
import { config } from "../../config/env";

/** Re-export shared limits for consumers that import from this module. */
export const MAX_CUSTOM_ANSWER_KEY_LENGTH = AUTOMATION_MAX_CUSTOM_ANSWER_KEY_LENGTH;
export const MAX_CUSTOM_ANSWER_VALUE_LENGTH = AUTOMATION_MAX_CUSTOM_ANSWER_VALUE_LENGTH;
export const MAX_CUSTOM_ANSWER_COUNT = AUTOMATION_MAX_CUSTOM_ANSWER_COUNT;

/**
 * Bypass SSRF guards when the process explicitly opts into private hosts.
 * Used by local fixture / integration runs; default remains deny.
 */
const allowAutomationPrivateHostsOptIn = (): boolean => config.allowAutomationPrivateHosts;

/**
 * Validate and normalize an automation URL while blocking unsafe host targets.
 */
export function sanitizeAndValidateJobUrl(rawJobUrl: string): string {
  const jobUrl = rawJobUrl.trim();
  if (!jobUrl) {
    throw new Error(API_ERROR_JOB_URL_REQUIRED);
  }

  if (jobUrl.length > AUTOMATION_MAX_JOB_URL_LENGTH) {
    throw new Error(
      API_ERROR_JOB_URL_EXCEEDS_LENGTH.replace("__MAX__", String(AUTOMATION_MAX_JOB_URL_LENGTH)),
    );
  }

  if (!URL.canParse(jobUrl)) {
    throw new Error(API_ERROR_JOB_URL_ABSOLUTE);
  }
  const parsedUrl = new URL(jobUrl);

  if (parsedUrl.protocol !== "http:" && parsedUrl.protocol !== "https:") {
    throw new Error(API_ERROR_JOB_URL_HTTP_ONLY);
  }

  if (parsedUrl.username || parsedUrl.password) {
    throw new Error(API_ERROR_JOB_URL_NO_CREDENTIALS);
  }

  const host = parsedUrl.hostname.toLowerCase();
  if (isDisallowedAutomationHost(host)) {
    throw new Error(API_ERROR_JOB_URL_DISALLOWED_HOST);
  }

  return parsedUrl.toString();
}

/**
 * Normalize custom answers payload by enforcing strict typing and length limits.
 */
export function sanitizeCustomAnswers(
  customAnswers: Record<string, unknown> | undefined,
): Record<string, string> {
  if (!customAnswers) {
    return {};
  }

  if (typeof customAnswers !== "object" || Array.isArray(customAnswers)) {
    throw new Error(API_ERROR_CUSTOM_ANSWERS_OBJECT);
  }

  const entries = Object.entries(customAnswers);
  if (entries.length > MAX_CUSTOM_ANSWER_COUNT) {
    throw new Error(
      API_ERROR_CUSTOM_ANSWERS_MAX_COUNT.replace("__MAX__", String(MAX_CUSTOM_ANSWER_COUNT)),
    );
  }

  const normalized: Record<string, string> = {};
  for (const [rawKey, rawValue] of entries) {
    const key = rawKey.trim();
    if (!key) {
      throw new Error(API_ERROR_CUSTOM_ANSWERS_KEYS);
    }
    if (key.length > MAX_CUSTOM_ANSWER_KEY_LENGTH) {
      throw new Error(
        API_ERROR_CUSTOM_ANSWERS_KEY_EXCEEDS.replace(
          "__MAX__",
          String(MAX_CUSTOM_ANSWER_KEY_LENGTH),
        ),
      );
    }

    if (typeof rawValue !== "string") {
      throw new Error(API_ERROR_CUSTOM_ANSWERS_VALUE_MUST_BE_STRING.replace("__KEY__", key));
    }

    const value = rawValue.trim();
    if (value.length > MAX_CUSTOM_ANSWER_VALUE_LENGTH) {
      throw new Error(
        API_ERROR_CUSTOM_ANSWERS_VALUE_EXCEEDS.replace("__KEY__", key).replace(
          "__MAX__",
          String(MAX_CUSTOM_ANSWER_VALUE_LENGTH),
        ),
      );
    }

    normalized[key] = value;
  }

  return normalized;
}

/**
 * Pure host classification: true when the hostname is loopback, RFC 1918
 * private space, or link-local. Separated from the opt-in policy below so the
 * range boundaries are testable without mutating process environment.
 */
export function isPrivateOrLoopbackAutomationHost(hostname: string): boolean {
  // Fail closed: an empty host is never a legitimate automation target.
  if (!hostname) {
    return true;
  }

  if (hostname === LOOPBACK_HOST_IPV4 || hostname === DEFAULT_HOST) {
    return true;
  }

  return isLoopbackOrPrivateHost(hostname);
}

function isDisallowedAutomationHost(hostname: string): boolean {
  if (!hostname) {
    return true;
  }

  if (allowAutomationPrivateHostsOptIn()) {
    return false;
  }

  return isPrivateOrLoopbackAutomationHost(hostname);
}

