setDefaultTimeout(JOB_APPLY_SCRIPT_TEST_TIMEOUT_MS);

const createTempDirectory = (): string => mkdtempSync(join(tmpdir(), TEMP_DIRECTORY_PREFIX));

const writeTempResumeFile = async (directory: string): Promise<string> => {
