const buildJobApplyScriptInput = (serverPort: number, resumeFilePath: string) => ({
  jobUrl: `http://127.0.0.1:${serverPort}/`,
  resume: {
    personalInfo: {
      name: "Bao Builder",
      email: "bao@example.com",
      phone: "555-0100",
    },
  },
  resumeFilePath,
  coverLetter: {
