  customAnswers: {
    [FORM_FIELD_NAME_WORK_AUTHORIZATION]: "Yes",
    [FORM_FIELD_NAME_REMOTE_PREFERENCE]: "Remote",
    [FORM_FIELD_NAME_TERMS_ACCEPTED]: "yes",
