import type {
  AutomationScriptExecutionResult,
  RpaScriptExecutionResult,
  RunRpaScriptOptions,
} from "./rpa-runner-contracts";
import { buildErrorEnvelope } from "./rpa-runner-contracts";
import { runAutomationScript } from "./rpa-runner-process";

const MAX_PROTOCOL_ERROR_LINES = 20;

type ParsedProtocolLine =
  | {
      ok: true;
      event: RpaRunEvent;
    }
  | {
      ok: false;
      reason: "invalid_json" | "invalid_event";
    };

type ProtocolCaptureState = {
  events: RpaRunEvent[];
  protocolErrors: string[];
  terminalResult: RpaRunResult | null;
  terminalError: ErrorEnvelope | null;
};

const pushBoundedLine = (target: string[], value: string, limit: number): void => {
  const normalized = value.trim();
  if (normalized.length === 0) {
    return;
  }
  target.push(normalized);
  if (target.length > limit) {
    target.shift();
  }
};

const isLikelyJsonLine = (line: string): boolean => {
  const normalized = line.trim();
  return normalized.startsWith("{") && normalized.endsWith("}");
};

const parseProtocolLine = (line: string): ParsedProtocolLine => {
  const parsedJson = safeParseJson(line);
  if (parsedJson === null) {
    return {
      ok: false,
      reason: "invalid_json",
    };
  }

  const parsedEvent = rpaRunEventSchema.safeParse(parsedJson);
  if (!parsedEvent.success) {
    return {
      ok: false,
      reason: "invalid_event",
    };
  }

  return {
    ok: true,
    event: parsedEvent.data,
  };
};

const createProtocolCaptureState = (): ProtocolCaptureState => ({
  events: [],
  protocolErrors: [],
  terminalResult: null,
  terminalError: null,
});

const pushProtocolError = (
  state: ProtocolCaptureState,
  source: "stdout" | "stderr",
  line: string,
  reason: string,
): void => {
  pushBoundedLine(state.protocolErrors, `${source}:${reason}:${line}`, MAX_PROTOCOL_ERROR_LINES);
};

const handleStdoutLine = (
  line: string,
  state: ProtocolCaptureState,
  onEvent: ((event: RpaRunEvent) => void) | undefined,
): void => {
  if (!isLikelyJsonLine(line)) {
    pushProtocolError(state, "stdout", line, "non_json_line");
    return;
  }
  const parsedLine = parseProtocolLine(line);
  if (!parsedLine.ok) {
    pushProtocolError(state, "stdout", line, parsedLine.reason);
    return;
  }

  const event = parsedLine.event;
  if (event.eventType === "progress") {
    pushProtocolError(state, "stdout", line, "unexpected_progress_event");
    return;
  }
  state.events.push(event);
  onEvent?.(event);
  if (event.eventType === "result") {
    state.terminalResult = event.result;
  } else if (event.eventType === "error") {
    state.terminalError = event.error;
  }
};

const handleStderrLine = (
  line: string,
  state: ProtocolCaptureState,
  onEvent: ((event: RpaRunEvent) => void) | undefined,
): void => {
  if (!isLikelyJsonLine(line)) {
    return;
  }
  const parsedLine = parseProtocolLine(line);
  if (!parsedLine.ok) {
    pushProtocolError(state, "stderr", line, parsedLine.reason);
    return;
  }
  if (parsedLine.event.eventType !== "progress") {
    pushProtocolError(state, "stderr", line, "unexpected_non_progress_event");
    return;
  }
  state.events.push(parsedLine.event);
  onEvent?.(parsedLine.event);
};

const resolveTerminalError = (
  state: ProtocolCaptureState,
  processResult: AutomationScriptExecutionResult,
  timeoutMs: number | undefined,
): ErrorEnvelope | null => {
  let terminalError = state.terminalError;
  if (processResult.timedOut) {
    terminalError = buildErrorEnvelope("AUTOMATION_TIMEOUT", "Automation script timed out", {
      timeoutMs: timeoutMs ?? config.automationScriptTimeoutMs,
    });
  }
  if (!terminalError && processResult.aborted) {
    terminalError = buildErrorEnvelope(
      "AUTOMATION_CANCELLED",
      "Automation script execution was cancelled",
    );
  }
  if (!terminalError && processResult.exitCode !== 0) {
    terminalError = buildErrorEnvelope(
      "AUTOMATION_RUNTIME_ERROR",
      "Automation script exited with an error",
      {
        exitCode: processResult.exitCode,
        stderrTail: processResult.stderrLines,
        stdoutTail: processResult.stdoutLines,
      },
    );
  }
  if (!terminalError && state.protocolErrors.length > 0) {
    terminalError = buildErrorEnvelope(
      "SCRIPT_PROTOCOL_ERROR",
      "Automation script emitted malformed protocol lines",
      {
        protocolErrors: state.protocolErrors,
        stdoutTail: processResult.stdoutLines,
        stderrTail: processResult.stderrLines,
      },
    );
  }
  if (!(terminalError || state.terminalResult)) {
    terminalError = buildErrorEnvelope(
      "SCRIPT_OUTPUT_INVALID",
      "Automation script did not emit a terminal result event",
      { stdoutTail: processResult.stdoutLines },
    );
  }
  return terminalError;
};

/**
 * Runs an RPA script and validates protocol events using shared schemas.
 */
export async function runRpaScript(
  options: RunRpaScriptOptions,
): Promise<RpaScriptExecutionResult> {
  const state = createProtocolCaptureState();

  const processResult = await runAutomationScript({
    scriptId: options.scriptId,
    scriptPath: options.scriptPath,
    scriptInput: {
      ...options.scriptInput,
      settings: options.automationSettings ?? DEFAULT_AUTOMATION_SETTINGS,
    },
    runId: options.executionContext.runId,
    timeoutMs: options.executionContext.timeoutMs,
    signal: options.executionContext.signal,
    outputDir: options.executionContext.outputDir,
    onStdoutLine: (line) => {
      handleStdoutLine(line, state, options.onEvent);
    },
    onStderrLine: (line) => {
      handleStderrLine(line, state, options.onEvent);
    },
  });

  const terminalError = resolveTerminalError(
    state,
    processResult,
    options.executionContext.timeoutMs,
  );

  return {
    result: state.terminalResult,
    error: terminalError,
    events: state.events,
    exitCode: processResult.exitCode,
    timedOut: processResult.timedOut,
    aborted: processResult.aborted,
    executionMs: processResult.executionMs,
    stdoutLines: processResult.stdoutLines,
    stderrLines: processResult.stderrLines,
  };
}

import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { rmSync } from "node:fs";
import { join } from "node:path";
import { MS_FIVE_SECONDS, PERCENT_MAX } from "@bao/shared/constants/numeric";
import { generateId } from "@bao/shared/utils/validation";
import { SCRAPER_DIR } from "../../config/paths";
import { runRpaScript } from "./rpa-runner-protocol";

const TEST_SCRIPT_NAME = "rpa_runner_contract_test.ts";
const TEST_SCRIPT_PATH = join(SCRAPER_DIR, TEST_SCRIPT_NAME);

beforeAll(async () => {
  await Bun.write(
    TEST_SCRIPT_PATH,
    `const payload = JSON.parse((await Bun.stdin.text()) || "{}");
const runId = typeof payload.runId === "string" && payload.runId.length > 0 ? payload.runId : "run-missing";
const protocolVersion =
  typeof payload.protocolVersion === "string" && payload.protocolVersion.length > 0
    ? payload.protocolVersion
    : "1.0";
const mode = typeof payload.mode === "string" ? payload.mode : "success";

if (mode === "success") {
  process.stderr.write(
    \`\${JSON.stringify({
      protocolVersion,
      runId,
      sequence: 0,
      timestamp: "2026-02-23T00:00:00+00:00",
      eventType: "progress",
      action: "fill_form",
      status: "running",
      step: 1,
      totalSteps: 2,
    })}\\n\`,
  );
  process.stdout.write(
    \`\${JSON.stringify({
      protocolVersion,
      runId,
      sequence: 1,
      timestamp: "2026-02-23T00:00:01+00:00",
      eventType: "result",
      result: {
        success: true,
        error: null,
        screenshots: [],
        artifacts: [],
        steps: [{ action: "fill_form", status: "ok" }],
      },
    })}\\n\`,
  );
  process.exit(0);
}

if (mode === "malformed") {
  process.stdout.write("not-json\\n");
  process.exit(0);
}

if (mode === "stdout_progress") {
  process.stdout.write(
    \`\${JSON.stringify({
      protocolVersion,
      runId,
      sequence: 0,
      timestamp: "2026-02-23T00:00:00+00:00",
      eventType: "progress",
      action: "wrong_stream",
      status: "running",
    })}\\n\`,
  );
  process.exit(0);
}

if (mode === "timeout") {
  await Bun.sleep(2_000);
  process.exit(0);
}

if (mode === "browser_missing" || mode === "browser_crash" || mode === "browser_polluted") {
  const failureMode =
    mode === "browser_missing"
      ? "BROWSER_EXECUTABLE_MISSING"
      : mode === "browser_crash"
        ? "BROWSER_PROCESS_CRASHED"
        : "BROWSER_PATH_POLLUTED";
  const causeMessage =
    mode === "browser_missing"
      ? "browserType.launch: Executable doesn't exist at /tmp/chromium"
      : mode === "browser_crash"
        ? "browserType.launch: Target closed (Received signal SIGSEGV)"
        : "browserType.launch: Failed to launch browser from cursor-sandbox-cache";
  process.stdout.write(
    \`\${JSON.stringify({
      protocolVersion,
      runId,
      sequence: 0,
      timestamp: "2026-02-23T00:00:02+00:00",
      eventType: "error",
      error: {
        code: "AUTOMATION_RUNTIME_ERROR",
        message: \`Unable to launch automation browser (\${failureMode}).\`,
        source: "@bao/scraper",
        details: {
          failureMode,
          causeMessage,
          stage: "launch",
        },
      },
    })}\\n\`,
  );
  process.exit(1);
}

process.stderr.write("runtime failure\\n");
process.exit(1);
`,
  );
});

afterAll(() => {
  rmSync(TEST_SCRIPT_PATH, { force: true });
});

const createExecutionContext = (timeoutMs: number): { runId: string; timeoutMs: number } => ({
  runId: generateId(),
  timeoutMs,
});

const registerSuccessCase = (): void => {
  test("parses NDJSON protocol progress/result events", async () => {
    const context = createExecutionContext(MS_FIVE_SECONDS);
    const execution = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: {
        mode: "success",
      },
      executionContext: context,
    });

    expect(execution.error).toBeNull();
    expect(execution.result?.success).toBe(true);
    expect(execution.events.length).toBe(2);
    expect(execution.events[0]?.eventType).toBe("progress");
    expect(execution.events[1]?.eventType).toBe("result");
  });
};

const registerMalformedPayloadCase = (): void => {
  test("returns protocol error for malformed terminal payload", async () => {
    const context = createExecutionContext(MS_FIVE_SECONDS);
    const execution = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: {
        mode: "malformed",
      },
      executionContext: context,
    });

    expect(execution.result).toBeNull();
    expect(execution.error?.code).toBe("SCRIPT_PROTOCOL_ERROR");
  });
};

const registerRuntimeFailureCase = (): void => {
  test("returns runtime error when script exits non-zero", async () => {
    const context = createExecutionContext(MS_FIVE_SECONDS);
    const execution = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: {
        mode: "runtime",
      },
      executionContext: context,
    });

    expect(execution.result).toBeNull();
    expect(execution.error?.code).toBe("AUTOMATION_RUNTIME_ERROR");
    expect(execution.exitCode).not.toBe(0);
  });
};

const registerUnexpectedProgressCase = (): void => {
  test("returns protocol error when stdout emits unexpected progress events", async () => {
    const context = createExecutionContext(MS_FIVE_SECONDS);
    const execution = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: {
        mode: "stdout_progress",
      },
      executionContext: context,
    });

    expect(execution.result).toBeNull();
    expect(execution.error?.code).toBe("SCRIPT_PROTOCOL_ERROR");
  });
};

const registerTimeoutCase = (): void => {
  test("returns timeout error when process exceeds timeout", async () => {
    const context = createExecutionContext(PERCENT_MAX);
    const execution = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: {
        mode: "timeout",
      },
      executionContext: context,
    });

    expect(execution.result).toBeNull();
    expect(execution.timedOut).toBe(true);
    expect(execution.error?.code).toBe("AUTOMATION_TIMEOUT");
  });
};

const registerBrowserLaunchFailureDifferentiationCase = (): void => {
  test("surfaces distinct browser launch failure modes through protocol error details", async () => {
    const missing = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: { mode: "browser_missing" },
      executionContext: createExecutionContext(MS_FIVE_SECONDS),
    });
    const crashed = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: { mode: "browser_crash" },
      executionContext: createExecutionContext(MS_FIVE_SECONDS),
    });
    const polluted = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: { mode: "browser_polluted" },
      executionContext: createExecutionContext(MS_FIVE_SECONDS),
    });

    expect(missing.error?.code).toBe("AUTOMATION_RUNTIME_ERROR");
    expect(crashed.error?.code).toBe("AUTOMATION_RUNTIME_ERROR");
    expect(polluted.error?.code).toBe("AUTOMATION_RUNTIME_ERROR");

    expect(missing.error?.details?.failureMode).toBe("BROWSER_EXECUTABLE_MISSING");
    expect(crashed.error?.details?.failureMode).toBe("BROWSER_PROCESS_CRASHED");
    expect(polluted.error?.details?.failureMode).toBe("BROWSER_PATH_POLLUTED");

    expect(missing.error?.details?.failureMode).not.toBe(crashed.error?.details?.failureMode);
    expect(crashed.error?.details?.failureMode).not.toBe(polluted.error?.details?.failureMode);
    expect(polluted.error?.details?.failureMode).not.toBe(missing.error?.details?.failureMode);

    expect(String(missing.error?.details?.causeMessage)).toContain("Executable doesn't exist");
    expect(String(crashed.error?.details?.causeMessage)).toContain("SIGSEGV");
    expect(String(polluted.error?.details?.causeMessage)).toContain("cursor-sandbox-cache");

    expect(missing.error?.message).toContain("BROWSER_EXECUTABLE_MISSING");
    expect(crashed.error?.message).toContain("BROWSER_PROCESS_CRASHED");
    expect(polluted.error?.message).toContain("BROWSER_PATH_POLLUTED");
  });
};

describe("runRpaScript", () => {
  registerSuccessCase();
  registerMalformedPayloadCase();
  registerRuntimeFailureCase();
  registerUnexpectedProgressCase();
  registerTimeoutCase();
  registerBrowserLaunchFailureDifferentiationCase();
});

import {
  AI_DEFAULT_TEMPERATURE_STRUCTURED,
  AI_MAX_TOKENS_FIELD_MAPPER,
} from "@bao/shared/constants/ai-generation";
import { safeParseJson } from "@bao/shared/utils/json";
import { config } from "../../config/env";
import { formFieldAnalysisPrompt } from "../ai/prompts-automation";
import {
  EMPTY_FIELD_ANALYSIS_RESULT,
  type FieldMapperAIClient,
  fieldAnalysisSchema,
  type SmartFieldAnalysisResult,
  selectorMapSchema,
} from "./smart-field-mapper-contracts";
import { wait } from "./smart-field-mapper-fetch";

const parseFieldAnalysisResponse = (content: string): SmartFieldAnalysisResult => {
  const cleaned = content
    .replace(/```json\n?/gu, "")
    .replace(/```\n?/gu, "")
    .trim();
  const parsedValue = safeParseJson(cleaned);
  const parsedAnalysis = fieldAnalysisSchema.safeParse(parsedValue);
  if (parsedAnalysis.success) {
    return parsedAnalysis.data;
  }

  const parsedSelectors = selectorMapSchema.safeParse(parsedValue);
  if (parsedSelectors.success) {
    return {
      selectorMap: parsedSelectors.data,
      fieldAnswers: {},
    };
  }

  return EMPTY_FIELD_ANALYSIS_RESULT;
};

export const stripToFormElements = (html: string): string => {
  const formElementRegex =
    /<(?:form|input|textarea|select|option|label|button|fieldset|legend)\b[^>]*(?:\/>|>(?:[\s\S]*?)<\/(?:form|input|textarea|select|option|label|button|fieldset|legend)>|>)/giu;

  const matches = html.match(formElementRegex);
  if (!matches) {
    return "";
  }

  let result = "";
  for (const match of matches) {
    if (result.length + match.length > config.smartFieldMapperMaxFormHtmlChars) {
      break;
    }
    result += `${match}\n`;
  }

  return result.trim();
};

export const generateFieldAnalysisWithRetry = (params: {
  aiService: FieldMapperAIClient;
  strippedHtml: string;
  fieldsNeeded: string[];
  candidateContext: string;
  attemptsRemaining: number;
  delayMs: number;
}): Promise<SmartFieldAnalysisResult> => {
  const prompt = formFieldAnalysisPrompt(
    params.strippedHtml,
    params.fieldsNeeded,
    params.candidateContext,
  );

  return params.aiService
    .generate(prompt, {
      purpose: "automationFieldMapping",
      temperature: AI_DEFAULT_TEMPERATURE_STRUCTURED,
      maxTokens: AI_MAX_TOKENS_FIELD_MAPPER,
    })
    .then(
      async (response) => {
        if (response.error || !response.content) {
          if (params.attemptsRemaining > 1) {
            await wait(params.delayMs);
            return generateFieldAnalysisWithRetry({
              ...params,
              attemptsRemaining: params.attemptsRemaining - 1,
              delayMs: params.delayMs * 2,
            });
          }
          return EMPTY_FIELD_ANALYSIS_RESULT;
        }

        const parsedAnalysis = parseFieldAnalysisResponse(response.content);
        if (
          Object.keys(parsedAnalysis.selectorMap).length > 0 ||
          Object.keys(parsedAnalysis.fieldAnswers).length > 0
        ) {
          return parsedAnalysis;
        }

        if (params.attemptsRemaining > 1) {
          await wait(params.delayMs);
          return generateFieldAnalysisWithRetry({
            ...params,
            attemptsRemaining: params.attemptsRemaining - 1,
            delayMs: params.delayMs * 2,
          });
        }

        return EMPTY_FIELD_ANALYSIS_RESULT;
      },
      async () => {
        if (params.attemptsRemaining > 1) {
          await wait(params.delayMs);
          return generateFieldAnalysisWithRetry({
            ...params,
            attemptsRemaining: params.attemptsRemaining - 1,
            delayMs: params.delayMs * 2,
          });
        }
        return EMPTY_FIELD_ANALYSIS_RESULT;
      },
    );
};

import { COUNT_THREE } from "@bao/shared/constants/numeric";
import type { SmartFieldAnalysisContext } from "./smart-field-mapper-contracts";

const FIELD_CONTEXT_ITEM_LIMIT = 6;
const FIELD_CONTEXT_TEXT_LIMIT = 280;
const FIELD_CONTEXT_SECTION_LIMIT = 4;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const getRecord = (value: unknown, key: string): Record<string, unknown> | null => {
  if (!isRecord(value)) {
    return null;
  }
  const entry = value[key];
  return isRecord(entry) ? entry : null;
};

const getTrimmedString = (value: unknown): string =>
  typeof value === "string" ? value.trim() : "";

const truncateText = (value: string): string =>
  value.length > FIELD_CONTEXT_TEXT_LIMIT
    ? `${value.slice(0, FIELD_CONTEXT_TEXT_LIMIT)}...`
    : value;

const uniqueNonEmptyStrings = (value: unknown): string[] => {
  if (!Array.isArray(value)) {
    return [];
  }

  return Array.from(
    new Set(
      value
        .filter((entry): entry is string => typeof entry === "string")
        .map((entry) => entry.trim())
        .filter((entry) => entry.length > 0),
    ),
  );
};

const getResumeHighlights = (resume: Record<string, unknown>): string[] => {
  const experience = Array.isArray(resume.experience) ? resume.experience : [];
  const highlights: string[] = [];

  for (const entry of experience) {
    if (!(isRecord(entry) && highlights.length < FIELD_CONTEXT_ITEM_LIMIT)) {
      continue;
    }

    const title = getTrimmedString(entry.title);
    const company = getTrimmedString(entry.company);
    const description = truncateText(getTrimmedString(entry.description));
    const achievements = uniqueNonEmptyStrings(entry.achievements).slice(0, 2);
    const parts = [title, company, description, ...achievements].filter((part) => part.length > 0);
    if (parts.length > 0) {
      highlights.push(parts.join(" | "));
    }
  }

  return highlights;
};

const getProjectHighlights = (resume: Record<string, unknown>): string[] => {
  const projects = Array.isArray(resume.projects) ? resume.projects : [];
  const highlights: string[] = [];

  for (const entry of projects) {
    if (!(isRecord(entry) && highlights.length < FIELD_CONTEXT_SECTION_LIMIT)) {
      continue;
    }

    const title = getTrimmedString(entry.title);
    const description = truncateText(getTrimmedString(entry.description));
    const technologies = uniqueNonEmptyStrings(entry.technologies).slice(0, COUNT_THREE).join(", ");
    const parts = [title, description, technologies].filter((part) => part.length > 0);
    if (parts.length > 0) {
      highlights.push(parts.join(" | "));
    }
  }

  return highlights;
};

export const getCandidateContextSummary = (context: SmartFieldAnalysisContext): string => {
  const personalInfo = getRecord(context.resume, "personalInfo");
  const skills = getRecord(context.resume, "skills");
  const coverLetterContent = getRecord(context.coverLetter ?? null, "content");
  const coverLetterSections = [
    getTrimmedString(coverLetterContent?.opening),
    getTrimmedString(coverLetterContent?.body),
    getTrimmedString(coverLetterContent?.closing),
    getTrimmedString(coverLetterContent?.introduction),
    getTrimmedString(coverLetterContent?.main),
    getTrimmedString(coverLetterContent?.conclusion),
  ]
    .filter((entry) => entry.length > 0)
    .slice(0, FIELD_CONTEXT_SECTION_LIMIT)
    .map((entry) => truncateText(entry));

  const candidateProfile = {
    personalInfo: {
      name: getTrimmedString(personalInfo?.name),
      email: getTrimmedString(personalInfo?.email),
      phone: getTrimmedString(personalInfo?.phone),
      location: getTrimmedString(personalInfo?.location),
      website: getTrimmedString(personalInfo?.website),
      linkedIn: getTrimmedString(personalInfo?.linkedIn),
      github: getTrimmedString(personalInfo?.github),
      portfolio: getTrimmedString(personalInfo?.portfolio),
    },
    summary: truncateText(getTrimmedString(context.resume.summary)),
    experienceHighlights: getResumeHighlights(context.resume),
    projectHighlights: getProjectHighlights(context.resume),
    skills: {
      technical: uniqueNonEmptyStrings(skills?.technical).slice(0, FIELD_CONTEXT_ITEM_LIMIT),
      soft: uniqueNonEmptyStrings(skills?.soft).slice(0, FIELD_CONTEXT_ITEM_LIMIT),
      gaming: uniqueNonEmptyStrings(skills?.gaming).slice(0, FIELD_CONTEXT_ITEM_LIMIT),
    },
    coverLetterHighlights: coverLetterSections,
    existingAnswers: context.existingAnswers,
  };

  return JSON.stringify(candidateProfile, null, 2);
};

import {
  AUTOMATION_MAX_CUSTOM_ANSWER_KEY_LENGTH,
  AUTOMATION_MAX_CUSTOM_ANSWER_VALUE_LENGTH,
} from "@bao/shared/constants/automation-limits";
import {
  SCHEMA_MAX_ITEMS_SMALL,
  SCHEMA_MAX_LENGTH_SHORT,
  SCHEMA_MAX_LENGTH_URL,
} from "@bao/shared/constants/schema-limits";
import type { AIResponse } from "@bao/shared/types/ai";
import { z } from "zod";

export interface FieldMapperAIClient {
  generate: (
    prompt: string,
    options?: { purpose?: "automationFieldMapping"; temperature?: number; maxTokens?: number },
  ) => Promise<AIResponse>;
}

export interface SmartFieldAnalysisContext {
  readonly resume: Record<string, unknown>;
  readonly coverLetter?: Record<string, unknown> | null;
  readonly existingAnswers?: Record<string, string>;
}

export interface SmartFieldAnalysisResult {
  readonly selectorMap: Record<string, string[]>;
  readonly fieldAnswers: Record<string, string>;
}

export type FetchPageResult =
  | {
      ok: true;
      html: string;
    }
  | {
      ok: false;
      statusCode?: number;
      message: string;
    };

export const selectorMapSchema = z.record(
  z.string().trim().min(1).max(SCHEMA_MAX_LENGTH_SHORT),
  z.array(z.string().trim().min(1).max(SCHEMA_MAX_LENGTH_URL)).min(1).max(SCHEMA_MAX_ITEMS_SMALL),
);

export const fieldAnswersSchema = z.record(
  z.string().trim().min(1).max(AUTOMATION_MAX_CUSTOM_ANSWER_KEY_LENGTH),
  z.string().trim().max(AUTOMATION_MAX_CUSTOM_ANSWER_VALUE_LENGTH),
);

export const fieldAnalysisSchema = z.object({
  selectorMap: selectorMapSchema.default({}),
  fieldAnswers: fieldAnswersSchema.default({}),
});

export const EMPTY_FIELD_ANALYSIS_RESULT = {
  selectorMap: {},
  fieldAnswers: {},
} satisfies SmartFieldAnalysisResult;

import { API_ERROR_NETWORK_REQUEST_FAILED } from "@bao/shared/constants/api-errors";
import {
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_TOO_MANY_REQUESTS,
} from "@bao/shared/constants/http";
import { config } from "../../config/env";
import type { FetchPageResult } from "./smart-field-mapper-contracts";

export const wait = (delayMs: number): Promise<void> =>
  new Promise((resolve) => {
    const timer = setTimeout(() => resolve(), delayMs);
    if (
      typeof timer === "object" &&
      timer !== null &&
      "unref" in timer &&
      typeof timer.unref === "function"
    ) {
      timer.unref();
    }
  });

const isRetryableFetchFailure = (result: FetchPageResult): boolean => {
  if (result.ok) {
    return false;
  }
  if (typeof result.statusCode !== "number") {
    return true;
  }
  return (
    result.statusCode === HTTP_STATUS_TOO_MANY_REQUESTS ||
    result.statusCode >= HTTP_STATUS_INTERNAL_SERVER_ERROR
  );
};

const fetchPage = (url: string): Promise<FetchPageResult> =>
  fetch(url, {
    signal: AbortSignal.timeout(config.smartFieldMapperFetchTimeoutMs),
    headers: {
      "User-Agent": config.smartFieldMapperUserAgent,
    },
  }).then(
    async (response) => {
      if (!response.ok) {
        return {
          ok: false,
          statusCode: response.status,
          message: `HTTP ${response.status}`,
        } satisfies FetchPageResult;
      }

      return {
        ok: true,
        html: await response.text(),
      } satisfies FetchPageResult;
    },
    () =>
      ({
        ok: false,
        message: API_ERROR_NETWORK_REQUEST_FAILED,
      }) satisfies FetchPageResult,
  );

export const fetchPageWithRetry = (params: {
  url: string;
  attemptsRemaining: number;
  delayMs: number;
}): Promise<FetchPageResult> =>
  fetchPage(params.url).then(async (result) => {
    if (!isRetryableFetchFailure(result) || params.attemptsRemaining <= 1) {
      return result;
    }

    await wait(params.delayMs);
    return fetchPageWithRetry({
      ...params,
      attemptsRemaining: params.attemptsRemaining - 1,
      delayMs: params.delayMs * 2,
    });
  });

