  imported: Record<string, number>,
  errors: string[],
): Promise<void> => {
  if (!data.profile) {
    return;
  }

  await runWithErrorHandler(
    async () => {
      const existing = await db
        .select()
        .from(userProfile)
        .where(eq(userProfile.id, DEFAULT_PROFILE_ID));
      const profile = isRecord(data.profile) ? data.profile : {};
      if (existing.length > 0) {
        const rest = omitImportMetadata(profile);
        await db
          .update(userProfile)
          .set({ ...rest, updatedAt: new Date().toISOString() })
          .where(eq(userProfile.id, DEFAULT_PROFILE_ID));
      } else {
        await db.insert(userProfile).values({ ...profile, id: DEFAULT_PROFILE_ID });
      }
      imported.profile = 1;
    },
    (message) => {
      errors.push(`Profile import failed: ${message}`);
    },
  );
};

export const importSettingsSection = async (
  data: BaoImportData,
  imported: Record<string, number>,
  errors: string[],
): Promise<void> => {
  if (!data.settings) {
    return;
  }

  await runWithErrorHandler(
    async () => {
      const normalized = sanitizeImportedSettings(data.settings);
      const existing = await db.select().from(settings).where(eq(settings.id, DEFAULT_SETTINGS_ID));
      if (existing.length > 0) {
        await db
          .update(settings)
          .set({ ...normalized, updatedAt: new Date().toISOString() })
          .where(eq(settings.id, DEFAULT_SETTINGS_ID));
      } else {
        await db.insert(settings).values({ ...normalized, id: DEFAULT_SETTINGS_ID });
      }
      imported.settings = 1;
    },
    (message) => {
      errors.push(`Settings import failed: ${message}`);
    },
  );
};

export const importGamificationSection = async (
  data: BaoImportData,
  imported: Record<string, number>,
  errors: string[],
): Promise<void> => {
  if (!data.gamification) {
    return;
  }

  await runWithErrorHandler(
    async () => {
      const existing = await db
        .select()
        .from(gamification)
        .where(eq(gamification.id, DEFAULT_PROFILE_ID));
      const parsedGamification = parseGamificationInsert(data.gamification);
      if (!parsedGamification) throw new Error(API_ERROR_INVALID_GAMIFICATION_PAYLOAD);
      if (existing.length > 0) {
        const rest = omitImportMetadata(parsedGamification);
        await db
          .update(gamification)
          .set({ ...rest, updatedAt: new Date().toISOString() })
          .where(eq(gamification.id, DEFAULT_PROFILE_ID));
      } else {
        await db.insert(gamification).values({ ...parsedGamification, id: DEFAULT_PROFILE_ID });
      }
      imported.gamification = 1;
    },
    (message) => {
      errors.push(`Gamification import failed: ${message}`);
    },
  );
};

import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import { sqlite } from "../db/client";
import type { BaoImportData, ImportResult } from "./data-service-contracts";
import { DATA_EXPORT_VERSION } from "./data-service-contracts";
import {
  importChatHistorySection,
  importCoverLettersSection,
  importInterviewSessionsSection,
  importPortfolioProjectsSection,
  importResumesSection,
  importSkillMappingsSection,
} from "./data-service-import-content";
import {
  importGamificationSection,
  importProfileSection,
  importSettingsSection,
} from "./data-service-import-foundation";

const executeImportTransaction = async (
  data: BaoImportData,
  imported: Record<string, number>,
  errors: string[],
): Promise<void> => {
  await importProfileSection(data, imported, errors);
  await importSettingsSection(data, imported, errors);
  await importResumesSection(data, imported, errors);
  await importCoverLettersSection(data, imported, errors);
  await importPortfolioProjectsSection(data, imported, errors);
  await importInterviewSessionsSection(data, imported, errors);
  await importGamificationSection(data, imported, errors);
  await importSkillMappingsSection(data, imported, errors);
  await importChatHistorySection(data, imported);
  sqlite.exec("COMMIT");
};

/**
 * Import data from a BaoBuildBuddy export JSON.
 * Uses a transaction for atomicity.
 */
export const importAllData = async (data: BaoImportData): Promise<ImportResult> => {
  const imported: Record<string, number> = {};
  const skipped: Record<string, number> = {};
  const errors: string[] = [];

  if (data.version !== DATA_EXPORT_VERSION) {
    errors.push(`Unsupported export version: ${data.version}`);
    return { imported, skipped, errors };
  }

  sqlite.exec("BEGIN");
  const transactionResult = await settle(executeImportTransaction(data, imported, errors));
  if (transactionResult.status === "rejected") {
    sqlite.exec("ROLLBACK");
    errors.push(`Transaction failed: ${toErrorMessage(transactionResult.reason)}`);
  }

  return { imported, skipped, errors };
};

