          bold: true,
          size: DOCX_COVER_LETTER_FONT_BODY_PT * 2,
          color: theme.primaryColorHex,
          font: theme.fontFamily,
        }),
      ],
    }),
    new Paragraph({
      children: [
        new TextRun({
          text: `Re: ${coverLetter.position}`,
          italics: true,
