        ],
      }),
      ...buildPortfolioDescriptionParagraph(metadata, theme),
      ...buildPortfolioContactParagraph(metadata, theme),
      createDivider(theme.lineColorHex),
      buildPortfolioProjectsHeading(theme),
      ...projects.flatMap((project, index) =>
