export async function exportPortfolioDocxDocument(
  metadata: PortfolioMetadata,
  projects: PortfolioProject[],
  template?: string,
): Promise<Uint8Array> {
  const theme = resolvePortfolioDocxTheme(template);
  const doc = new Document({
