  return new Uint8Array(buffer);
}

import type { ResumeData } from "@bao/shared/types/resume";
import { Paragraph, TextRun } from "docx";
import {
  DOCX_RESUME_FONT_ACCENT_PT,
  DOCX_RESUME_FONT_BODY_PT,
