  type ResumeEducationItem,
  type ResumeExperienceItem,
  type ResumeProjectItem,
  type ResumeSkillsData,
} from "./docx-export-contracts";

export function buildExperienceItem(
  item: ResumeExperienceItem,
  config: DocxTemplateConfig,
): Paragraph[] {
  const items: Paragraph[] = [
    new Paragraph({
      children: [
        new TextRun({
          text: item.title ?? "",
          bold: true,
          size: DOCX_RESUME_FONT_BODY_PT * 2,
          font: config.fontFamily,
        }),
        new TextRun({
          text: item.company ? ` — ${item.company}` : "",
          size: DOCX_RESUME_FONT_BODY_PT * 2,
          color: config.secondaryColorHex,
          font: config.fontFamily,
        }),
      ],
      spacing: { before: 100 },
    }),
  ];

  const dateParts = [item.startDate, item.endDate ?? "Present"].filter(Boolean);
  if (dateParts.length > 0) {
    const locationLine = item.location ? ` | ${item.location}` : "";
    items.push(
      new Paragraph({
        children: [
          new TextRun({
            text: dateParts.join(" – ") + locationLine,
            italics: true,
            size: DOCX_RESUME_FONT_ACCENT_PT * 2,
            color: config.mutedColorHex,
            font: config.fontFamily,
          }),
        ],
        spacing: { after: 40 },
      }),
    );
  }

  if (item.achievements && item.achievements.length > 0) {
    for (const achievement of item.achievements) {
      items.push(
        new Paragraph({
          bullet: { level: 0 },
          children: [
            new TextRun({
              text: achievement,
              size: DOCX_RESUME_FONT_BODY_PT * 2,
              font: config.fontFamily,
            }),
          ],
        }),
      );
    }
  }

  return items;
}

export function buildEducationItem(
  item: ResumeEducationItem,
  config: DocxTemplateConfig,
): Paragraph[] {
  const items: Paragraph[] = [
    new Paragraph({
      children: [
        new TextRun({
          text: item.degree ?? "",
          bold: true,
          size: DOCX_RESUME_FONT_BODY_PT * 2,
          font: config.fontFamily,
        }),
        new TextRun({
          text: item.school ? ` — ${item.school}` : "",
          size: DOCX_RESUME_FONT_BODY_PT * 2,
          color: config.secondaryColorHex,
          font: config.fontFamily,
        }),
      ],
      spacing: { before: 100 },
    }),
  ];

  if (item.year) {
    items.push(
      new Paragraph({
        children: [
          new TextRun({
            text: item.year,
            italics: true,
            size: DOCX_RESUME_FONT_ACCENT_PT * 2,
            color: config.mutedColorHex,
            font: config.fontFamily,
          }),
        ],
        spacing: { after: 40 },
      }),
    );
  }

  if (item.gpa) {
    items.push(
      new Paragraph({
        children: [
          new TextRun({
            text: "GPA: ",
            bold: true,
            size: DOCX_RESUME_FONT_ACCENT_PT * 2,
            font: config.fontFamily,
          }),
          new TextRun({
            text: item.gpa,
            size: DOCX_RESUME_FONT_ACCENT_PT * 2,
            font: config.fontFamily,
          }),
        ],
      }),
    );
  }

  return items;
}

function buildSkillParagraph(
  label: string,
  values: string[],
  config: DocxTemplateConfig,
