import { COUNT_TWO_TWENTY } from "@bao/shared/constants/numeric";
import { settle } from "@bao/shared/utils/promise";
import type { PendingDrainReader, SmtpConnectionState } from "./email-delivery-connection-state";

import {
  assertExpectedCode,
  handleClose,
  handleData,
  handleHandshake,
  readResponse,
  rejectAllPending,
  resolvePendingDrain,
} from "./email-delivery-connection-state";
import {
  type EmailTransportRuntimeConfig,
  SmtpConnectionClosedError,
} from "./email-delivery-contracts";

const createSocketLifecycle = (state: SmtpConnectionState) => ({
  binaryType: "uint8array" as const,
  close: (_socket: Bun.Socket<undefined>, error?: Error) => {
    handleClose(state, error);
  },
  connectError: (_socket: Bun.Socket<undefined>, error: Error) => {
    rejectAllPending(state, error);
  },
  data: (_socket: Bun.Socket<undefined>, data: Uint8Array) => {
    handleData(state, data);
  },
  drain: () => {
    resolvePendingDrain(state);
  },
  error: (_socket: Bun.Socket<undefined>, error: Error) => {
    rejectAllPending(state, error);
  },
  handshake: (
    _socket: Bun.Socket<undefined>,
    success: boolean,
    authorizationError: Error | null,
  ) => {
    handleHandshake(state, success, authorizationError);
  },
  timeout: (socket: Bun.Socket<undefined>) => {
    const timeoutError = new SmtpConnectionClosedError("SMTP connection timed out");
    rejectAllPending(state, timeoutError);
    socket.close();
  },
});

export const connectSmtpSocket = async (
  state: SmtpConnectionState,
  config: EmailTransportRuntimeConfig,
): Promise<void> => {
  const socketResult = await settle(
    Bun.connect({
      hostname: config.host,
      port: config.port,
      tls: config.security === "tls",
      socket: createSocketLifecycle(state),
    }),
  );

  if (socketResult.status === "rejected") {
    throw socketResult.reason;
  }

  state.socket = socketResult.value;
  state.socket.timeout(config.connectionTimeoutSeconds);
  const greeting = await readResponse(state);
  assertExpectedCode(greeting, [COUNT_TWO_TWENTY], "SMTP greeting");
};

const waitForTlsUpgrade = async (
  state: SmtpConnectionState,
  upgrade: () => [Bun.Socket<undefined>, Bun.Socket<undefined>] | undefined,
): Promise<Bun.Socket<undefined>> => {
  const tlsPromise = new Promise<void>((resolve, reject) => {
    state.pendingTlsUpgrade = { resolve, reject };
  });
  const upgradedSocket = upgrade();
  if (!upgradedSocket) {
    state.pendingTlsUpgrade = null;
    throw new SmtpConnectionClosedError("SMTP socket is not available");
  }

  const [, tlsSocket] = upgradedSocket;
  const tlsResult = await settle(tlsPromise);
  if (tlsResult.status === "rejected") {
    throw tlsResult.reason;
  }

  return tlsSocket;
};

export const upgradeSmtpSocket = async (
  state: SmtpConnectionState,
  _config: EmailTransportRuntimeConfig,
  socket: Bun.Socket<undefined>,
): Promise<Bun.Socket<undefined>> =>
  waitForTlsUpgrade(state, () =>
    socket.upgradeTLS({
      tls: true,
      socket: createSocketLifecycle(state),
    }),
  );

export const writeBytes = async (
  state: SmtpConnectionState,
  socket: Bun.Socket<undefined>,
  bytes: Uint8Array,
  offset: number,
): Promise<void> => {
  const remainingLength = bytes.byteLength - offset;
  if (remainingLength <= 0) {
    return;
  }

  const written = socket.write(bytes, offset, remainingLength);
  if (written < 0) {
    throw new SmtpConnectionClosedError("SMTP socket closed during write");
  }

  if (written >= remainingLength) {
    return;
  }

  await new Promise<void>((resolve, reject) => {
    state.pendingDrain = { resolve, reject } satisfies PendingDrainReader;
  });
  await writeBytes(state, socket, bytes, offset + written);
};

import { createServerLogger } from "../utils/logger";
import {
  SmtpConnectionClosedError,
  SmtpProtocolError,
  type SmtpResponse,
} from "./email-delivery-contracts";
import { SMTP_LINE_BREAK } from "./email-delivery-message";

const SMTP_RESPONSE_LINE_PATTERN = /^(\d{3})([ -])(.*)$/;

export interface PendingResponseReader {
  reject: (reason?: unknown) => void;
  resolve: (response: SmtpResponse) => void;
}

export interface PendingDrainReader {
  reject: (reason?: unknown) => void;
  resolve: () => void;
}

export interface PendingTlsUpgrade {
  reject: (reason?: unknown) => void;
  resolve: () => void;
}

export interface SmtpConnectionState {
  decoder: TextDecoder;
  encoder: TextEncoder;
  queuedResponses: SmtpResponse[];
  pendingReaders: PendingResponseReader[];
  logger: ReturnType<typeof createServerLogger>;
  currentResponse: SmtpResponse | null;
  buffer: string;
  socket: Bun.Socket<undefined> | null;
  pendingDrain: PendingDrainReader | null;
  pendingTlsUpgrade: PendingTlsUpgrade | null;
  closed: boolean;
}

export const createSmtpConnectionState = (): SmtpConnectionState => ({
  decoder: new TextDecoder(),
  encoder: new TextEncoder(),
  queuedResponses: [],
  pendingReaders: [],
  logger: createServerLogger("smtp-connection"),
  currentResponse: null,
  buffer: "",
  socket: null,
  pendingDrain: null,
  pendingTlsUpgrade: null,
  closed: false,
});

export const readResponse = async (state: SmtpConnectionState): Promise<SmtpResponse> => {
  if (state.queuedResponses.length > 0) {
    const queuedResponse = state.queuedResponses.shift();
    if (queuedResponse) {
      return queuedResponse;
    }
  }

  return new Promise<SmtpResponse>((resolve, reject) => {
    state.pendingReaders.push({ resolve, reject });
  });
};

export const handleData = (state: SmtpConnectionState, data: Uint8Array): void => {
  state.buffer += state.decoder.decode(data, { stream: true });

  for (;;) {
    const lineBreakIndex = state.buffer.indexOf(SMTP_LINE_BREAK);
    if (lineBreakIndex < 0) {
      return;
    }

    const line = state.buffer.slice(0, lineBreakIndex);
    state.buffer = state.buffer.slice(lineBreakIndex + SMTP_LINE_BREAK.length);
    handleResponseLine(state, line);
  }
};

const handleResponseLine = (state: SmtpConnectionState, line: string): void => {
  const parsed = SMTP_RESPONSE_LINE_PATTERN.exec(line);
  if (!parsed) {
    return;
  }

  const code = Number.parseInt(parsed[1] ?? "", 10);
  const separator = parsed[2] ?? " ";
  const message = parsed[3] ?? "";

  if (!state.currentResponse || state.currentResponse.code !== code) {
    state.currentResponse = {
      code,
      lines: [],
    };
  }

  state.currentResponse.lines.push(message);
  if (separator !== " ") {
    return;
  }

  const completedResponse = state.currentResponse;
  state.currentResponse = null;

  const nextReader = state.pendingReaders.shift();
  if (nextReader) {
    nextReader.resolve(completedResponse);
    return;
  }

  state.queuedResponses.push(completedResponse);
};

export const handleClose = (state: SmtpConnectionState, error?: Error): void => {
  state.closed = true;
  rejectAllPending(state, error ?? new SmtpConnectionClosedError("SMTP connection closed"));
};

export const handleHandshake = (
  state: SmtpConnectionState,
  success: boolean,
  authorizationError: Error | null,
): void => {
  if (!state.pendingTlsUpgrade) {
    return;
  }

  const pendingTlsUpgrade = state.pendingTlsUpgrade;
  state.pendingTlsUpgrade = null;

  if (!success && authorizationError) {
    pendingTlsUpgrade.reject(authorizationError);
    return;
  }

  pendingTlsUpgrade.resolve();
};

export const resolvePendingDrain = (state: SmtpConnectionState): void => {
  if (!state.pendingDrain) {
    return;
  }

  const pendingDrain = state.pendingDrain;
  state.pendingDrain = null;
  pendingDrain.resolve();
};

export const rejectAllPending = (state: SmtpConnectionState, reason: unknown): void => {
  const pendingReaders = state.pendingReaders.splice(0);
  for (const pendingReader of pendingReaders) {
    pendingReader.reject(reason);
  }

  if (state.pendingDrain) {
    state.pendingDrain.reject(reason);
    state.pendingDrain = null;
  }

  if (state.pendingTlsUpgrade) {
    state.pendingTlsUpgrade.reject(reason);
    state.pendingTlsUpgrade = null;
  }
};

export const assertExpectedCode = (
  response: SmtpResponse,
  expectedCodes: readonly number[],
  context: string,
): void => {
  if (expectedCodes.some((expectedCode) => expectedCode === response.code)) {
    return;
  }

  throw new SmtpProtocolError(response.code, response.lines, `Unexpected response for ${context}`);
};

export const assertSocket = (state: SmtpConnectionState): Bun.Socket<undefined> => {
  if (!state.socket || state.closed) {
    throw new SmtpConnectionClosedError("SMTP socket is not available");
  }

  return state.socket;
};

import {
  COUNT_THREE_FIFTY_FOUR,
  COUNT_THREE_THIRTY_FOUR,
  COUNT_TWO_FIFTY,
  COUNT_TWO_FIFTY_ONE,
  COUNT_TWO_THIRTY_FIVE,
  COUNT_TWO_TWENTY,
  COUNT_TWO_TWENTY_ONE,
} from "@bao/shared/constants/numeric";
import { settle } from "@bao/shared/utils/promise";
import {
  connectSmtpSocket,
  upgradeSmtpSocket,
  writeBytes,
} from "./email-delivery-connection-socket";
import {
  assertExpectedCode,
  assertSocket,
  createSmtpConnectionState,
  readResponse,
  type SmtpConnectionState,
} from "./email-delivery-connection-state";
import type { EmailTransportRuntimeConfig, SmtpResponse } from "./email-delivery-contracts";
import { dotStuffMessage, encodeBase64Utf8, SMTP_LINE_BREAK } from "./email-delivery-message";

const SMTP_DATA_ENDING = `${SMTP_LINE_BREAK}.${SMTP_LINE_BREAK}`;
const SMTP_QUIT_COMMAND = "QUIT";

export class SmtpConnection {
  private readonly state: SmtpConnectionState = createSmtpConnectionState();

  constructor(private readonly config: EmailTransportRuntimeConfig) {}

  async connect(): Promise<void> {
    await connectSmtpSocket(this.state, this.config);
  }

  async ehlo(clientHost: string): Promise<SmtpResponse> {
    return this.command(`EHLO ${clientHost}`, [COUNT_TWO_FIFTY], "EHLO");
  }

  async startTls(): Promise<void> {
    const socket = assertSocket(this.state);
    await this.command("STARTTLS", [COUNT_TWO_TWENTY], "STARTTLS");

    this.state.socket = await upgradeSmtpSocket(this.state, this.config, socket);
    this.state.socket.timeout(this.config.connectionTimeoutSeconds);
  }

  async authPlain(username: string, password: string): Promise<void> {
    const encoded = encodeBase64Utf8(`\u0000${username}\u0000${password}`);
    await this.command(`AUTH PLAIN ${encoded}`, [COUNT_TWO_THIRTY_FIVE], "AUTH PLAIN");
  }

  async authLogin(username: string, password: string): Promise<void> {
    await this.command("AUTH LOGIN", [COUNT_THREE_THIRTY_FOUR], "AUTH LOGIN");
    await this.command(
      encodeBase64Utf8(username),
      [COUNT_THREE_THIRTY_FOUR],
      "AUTH LOGIN username",
    );
    await this.command(encodeBase64Utf8(password), [COUNT_TWO_THIRTY_FIVE], "AUTH LOGIN password");
  }

  async sendMail(fromEmail: string, recipientEmail: string, message: string): Promise<void> {
    await this.command(`MAIL FROM:<${fromEmail}>`, [COUNT_TWO_FIFTY], "MAIL FROM");
    await this.command(
      `RCPT TO:<${recipientEmail}>`,
      [COUNT_TWO_FIFTY, COUNT_TWO_FIFTY_ONE],
      "RCPT TO",
    );
    await this.command("DATA", [COUNT_THREE_FIFTY_FOUR], "DATA");
    await this.writeCommand(`${dotStuffMessage(message)}${SMTP_DATA_ENDING}`);
    const dataResult = await readResponse(this.state);
    assertExpectedCode(dataResult, [COUNT_TWO_FIFTY], "message body");
  }

  async quit(): Promise<void> {
    if (this.state.closed) {
      return;
    }

    const quitResult = await settle(
      this.command(SMTP_QUIT_COMMAND, [COUNT_TWO_TWENTY_ONE], "QUIT"),
    );
    if (quitResult.status === "rejected") {
      this.state.logger.warn("smtp quit failed", quitResult.reason);
    }
  }

  close(): void {
    if (!this.state.socket || this.state.closed) {
      return;
    }

    this.state.closed = true;
    this.state.socket.close();
  }

  private async command(
    command: string,
    expectedCodes: readonly number[],
    context: string,
  ): Promise<SmtpResponse> {
    await this.writeCommand(`${command}${SMTP_LINE_BREAK}`);
    const response = await readResponse(this.state);
    assertExpectedCode(response, expectedCodes, context);
    return response;
  }

  private async writeCommand(command: string): Promise<void> {
    const socket = assertSocket(this.state);
    await writeBytes(this.state, socket, this.state.encoder.encode(command), 0);
  }
}

import type { EmailTransportSettings } from "@bao/shared/types/settings-contracts";

export type SmtpAuthMode = EmailTransportSettings["authMethod"];

/**
 * Runtime transport config with the secret SMTP password attached.
 */
export interface EmailTransportRuntimeConfig extends EmailTransportSettings {
  password?: string | null;
}

/**
 * Outbound email delivery request payload.
 */
export interface EmailDeliveryRequest {
  recipientEmail: string;
  subject: string;
  body: string;
}

/**
 * Email delivery success metadata returned to automation flows.
 */
export interface EmailDeliveryResult {
  recipientEmail: string;
  fromEmail: string;
  deliveredAt: string;
  messageId: string;
}

export interface SmtpResponse {
  code: number;
  lines: string[];
}

export interface DeliveryEnvelopeMetadata {
  clientHost: string;
  deliveredAt: string;
  messageId: string;
}

export class SmtpProtocolError extends Error {
  constructor(
    public readonly code: number,
    public readonly lines: string[],
    context: string,
  ) {
    super(`${context}: ${lines.join(" ")}`.trim());
  }
}

export class SmtpConnectionClosedError extends Error {}

import { generateId } from "@bao/shared/utils/validation";
import type {
  EmailDeliveryRequest,
  EmailTransportRuntimeConfig,
  SmtpAuthMode,
  SmtpResponse,
} from "./email-delivery-contracts";

export const SMTP_LINE_BREAK = "\r\n";
const SMTP_BASE64_LINE_LENGTH = 76;
const SMTP_DEFAULT_EHLO_HOST = "localhost";
const SMTP_HEADER_NEWLINE_PATTERN = /\r?\n+/g;
const SMTP_ASCII_HEADER_PATTERN = /^[\x20-\x7E]*$/;
const SMTP_WHITESPACE_PATTERN = /\s+/g;

export const sanitizeHeaderValue = (value: string): string =>
  value.replace(SMTP_HEADER_NEWLINE_PATTERN, " ").replace(SMTP_WHITESPACE_PATTERN, " ").trim();

export const encodeBase64Utf8 = (value: string): string =>
  Buffer.from(value, "utf8").toString("base64");

const encodeHeaderValue = (value: string): string => {
  const sanitized = sanitizeHeaderValue(value);
  if (SMTP_ASCII_HEADER_PATTERN.test(sanitized)) {
    return sanitized;
  }
  return `=?UTF-8?B?${encodeBase64Utf8(sanitized)}?=`;
};

const formatAddress = (email: string, displayName: string): string => {
  const sanitizedName = sanitizeHeaderValue(displayName);
  if (sanitizedName.length === 0) {
    return `<${email}>`;
  }
  return `${encodeHeaderValue(sanitizedName)} <${email}>`;
};

const splitBase64Lines = (value: string): string[] => {
  const lines: string[] = [];
  for (let index = 0; index < value.length; index += SMTP_BASE64_LINE_LENGTH) {
    lines.push(value.slice(index, index + SMTP_BASE64_LINE_LENGTH));
  }
  return lines.length > 0 ? lines : [""];
};

export const dotStuffMessage = (value: string): string =>
  value
    .split(SMTP_LINE_BREAK)
    .map((line) => (line.startsWith(".") ? `.${line}` : line))
    .join(SMTP_LINE_BREAK);

export const resolveEhloHost = (fromEmail: string, fallbackHost: string): string => {
  const domain = fromEmail.split("@")[1]?.trim();
  if (domain && domain.length > 0) {
    return domain;
  }

  const sanitizedHost = fallbackHost.trim();
  return sanitizedHost.length > 0 ? sanitizedHost : SMTP_DEFAULT_EHLO_HOST;
};

export const createMessageId = (domain: string): string => `<${generateId()}@${domain}>`;

export const smtpSupportsCapability = (capabilities: SmtpResponse, capability: string): boolean => {
  const normalizedCapability = capability.toUpperCase();
  return capabilities.lines.some((line) => line.toUpperCase().startsWith(normalizedCapability));
};

export const smtpSupportsAuthMode = (
  capabilities: SmtpResponse,
  authMode: SmtpAuthMode,
): boolean => {
  const authLine = capabilities.lines.find((line) => line.toUpperCase().startsWith("AUTH "));
  if (!authLine) {
    return false;
  }

  const normalizedAuthLine = authLine.toUpperCase();
  if (authMode === "login") {
    return normalizedAuthLine.includes(" LOGIN");
  }

  return normalizedAuthLine.includes(" PLAIN");
};

export const buildRfc822Message = (
  config: EmailTransportRuntimeConfig,
  request: EmailDeliveryRequest,
  deliveredAt: string,
  messageId: string,
): string => {
  const encodedBody = splitBase64Lines(
    encodeBase64Utf8(request.body.replace(/\r?\n/g, SMTP_LINE_BREAK)),
  );
  const fromAddress = formatAddress(config.fromEmail, config.fromName);
  const toAddress = formatAddress(request.recipientEmail, "");

  return [
    `From: ${fromAddress}`,
    `To: ${toAddress}`,
    `Subject: ${encodeHeaderValue(request.subject)}`,
    `Date: ${new Date(deliveredAt).toUTCString()}`,
    `Message-ID: ${messageId}`,
    "MIME-Version: 1.0",
    'Content-Type: text/plain; charset="UTF-8"',
    "Content-Transfer-Encoding: base64",
    "",
    ...encodedBody,
    "",
  ].join(SMTP_LINE_BREAK);
};

import { isValidEmail } from "@bao/shared/utils/validation";
import type { SmtpConnection } from "./email-delivery-connection";
import type {
  DeliveryEnvelopeMetadata,
  EmailDeliveryRequest,
  EmailDeliveryResult,
  EmailTransportRuntimeConfig,
  SmtpResponse,
} from "./email-delivery-contracts";
import {
  buildRfc822Message,
  createMessageId,
  resolveEhloHost,
  smtpSupportsAuthMode,
  smtpSupportsCapability,
} from "./email-delivery-message";

export const createDeliveryEnvelopeMetadata = (
  config: EmailTransportRuntimeConfig,
): DeliveryEnvelopeMetadata => {
  const clientHost = resolveEhloHost(config.fromEmail, config.host);
  return {
    clientHost,
    deliveredAt: new Date().toISOString(),
    messageId: createMessageId(clientHost),
  };
};

export const validateTransport = (
  config: EmailTransportRuntimeConfig,
  recipientEmail: string,
): void => {
  if (config.host.trim().length === 0) {
    throw new Error("Email delivery host is not configured");
  }

  if (!isValidEmail(config.fromEmail)) {
    throw new Error("Email delivery sender address is invalid");
  }

  if (!isValidEmail(recipientEmail)) {
    throw new Error("Email delivery recipient address is invalid");
  }

  if (config.username.trim().length > 0 && !config.password) {
    throw new Error("Email delivery password is required for authenticated SMTP");
  }
};

export const performSmtpDelivery = async (
  connection: SmtpConnection,
  config: EmailTransportRuntimeConfig,
  request: EmailDeliveryRequest,
  metadata: DeliveryEnvelopeMetadata,
): Promise<EmailDeliveryResult> => {
  const initialCapabilities = await connection.ehlo(metadata.clientHost);
  const securedCapabilities =
    config.security === "starttls"
      ? await performStartTls(connection, initialCapabilities, metadata.clientHost)
      : initialCapabilities;

  await authenticateIfNeeded(connection, config, securedCapabilities);
  await connection.sendMail(
    config.fromEmail,
    request.recipientEmail,
    buildRfc822Message(config, request, metadata.deliveredAt, metadata.messageId),
  );

  return {
    recipientEmail: request.recipientEmail,
    fromEmail: config.fromEmail,
    deliveredAt: metadata.deliveredAt,
    messageId: metadata.messageId,
  };
};

const performStartTls = async (
  connection: SmtpConnection,
  capabilities: SmtpResponse,
  clientHost: string,
): Promise<SmtpResponse> => {
  if (!smtpSupportsCapability(capabilities, "STARTTLS")) {
    throw new Error("SMTP server does not support STARTTLS");
  }

  await connection.startTls();
  return connection.ehlo(clientHost);
};

const authenticateIfNeeded = async (
  connection: SmtpConnection,
  config: EmailTransportRuntimeConfig,
  capabilities: SmtpResponse,
): Promise<void> => {
  const username = config.username.trim();
  if (username.length === 0) {
    return;
  }

  const password = config.password ?? "";
  if (!smtpSupportsAuthMode(capabilities, config.authMethod)) {
    throw new Error(`SMTP server does not advertise AUTH ${config.authMethod.toUpperCase()}`);
  }

  if (config.authMethod === "login") {
    await connection.authLogin(username, password);
    return;
  }

  await connection.authPlain(username, password);
};

