const expectRejectedDelivery = async (deliveryPromise: Promise<unknown>): Promise<Error> => {
  const result = await deliveryPromise.then(
    () => null,
    (error: unknown) => error,
  );
  expect(result).toBeInstanceOf(Error);
  return result as Error;
};

