function renderPortfolioProjectHeading(
  context: PortfolioRenderContext,
  project: PortfolioProject,
  index: number,
): void {
  if (context.layout !== "compact") {
    context.page.drawText(
      context.layout === "showcase" ? `SHIP ${index + 1}` : `CASE STUDY ${index + 1}`,
      {
        x: context.margin,
        y: context.yPosition,
        size: PORTFOLIO_PROJECT_LABEL_SIZE,
        font: context.boldFont,
        color: context.colors.accent,
      },
    );
    context.yPosition -= COUNT_THIRTEEN;
  }

  const titleSize = PORTFOLIO_PROJECT_TITLE_SIZE_BY_LAYOUT[context.layout];
  context.page.drawText(
    context.layout === "compact" ? project.title : `${index + 1}. ${project.title}`,
    {
      x: context.margin,
      y: context.yPosition,
      size: titleSize,
      font: context.boldFont,
      color: context.colors.primary,
    },
  );
  context.yPosition -= COUNT_TWENTY_TWO;

  if (!project.featured) {
    return;
  }

  if (context.layout === "showcase") {
    context.page.drawRectangle({
      x: context.margin,
      y: context.yPosition - PORTFOLIO_FEATURED_BADGE_BASELINE_OFFSET_Y,
      width: PORTFOLIO_FEATURED_BADGE_WIDTH,
      height: PORTFOLIO_FEATURED_BADGE_HEIGHT,
      color: context.colors.featured,
    });
    context.page.drawText("FEATURED", {
      x: context.margin + PORTFOLIO_FEATURED_BADGE_INSET_X,
      y: context.yPosition,
      size: PORTFOLIO_PROJECT_LABEL_SIZE,
      font: context.boldFont,
      color: toPdfColor(PORTFOLIO_BANNER_TITLE_COLOR),
    });
    context.yPosition -= COUNT_FIFTEEN;
    return;
  }

  context.page.drawText("* FEATURED", {
    x: context.margin,
    y: context.yPosition,
    size: 9,
    font: context.boldFont,
    color: context.colors.featured,
  });
  context.yPosition -= COUNT_FIFTEEN;
}

function renderPortfolioProjectRole(context: PortfolioRenderContext, role?: string): void {
  if (!role) {
    return;
  }

  context.page.drawText(`Role: ${role}`, {
    x: context.margin,
    y: context.yPosition,
    size: PORTFOLIO_PROJECT_BODY_SIZE,
    font: context.boldFont,
    color: context.colors.muted,
  });
  context.yPosition -= COUNT_FIFTEEN;
}

function renderPortfolioProjectTechnologies(
  context: PortfolioRenderContext,
  technologies?: string[],
): void {
  if (!Array.isArray(technologies) || technologies.length === 0) {
    return;
  }

  ensurePortfolioSpace(context, COUNT_TWENTY_FIVE);
  context.page.drawText(`Technologies: ${technologies.join(", ")}`, {
    x: context.margin,
    y: context.yPosition,
    size: PORTFOLIO_PROJECT_LABEL_SIZE,
    font: context.font,
    color: context.colors.accent,
  });
  context.yPosition -= COUNT_FIFTEEN;
}

function renderPortfolioTechnicalDetails(
  context: PortfolioRenderContext,
  project: PortfolioProject,
): void {
  const details = collectDefinedStringValues([
    project.platforms && project.platforms.length > 0
      ? `Platforms: ${project.platforms.join(", ")}`
      : undefined,
    project.engines && project.engines.length > 0
      ? `Engines: ${project.engines.join(", ")}`
      : undefined,
  ]);
  if (details.length === 0) {
    return;
  }

  ensurePortfolioSpace(context, COUNT_TWENTY_FIVE);
  context.page.drawText(details.join(" | "), {
    x: context.margin,
    y: context.yPosition,
    size: PORTFOLIO_PROJECT_LABEL_SIZE,
    font: context.font,
    color: context.colors.muted,
  });
  context.yPosition -= COUNT_FIFTEEN;
}

function renderPortfolioProjectLinks(
  context: PortfolioRenderContext,
  project: PortfolioProject,
): void {
  const links = collectDefinedStringValues([
    project.liveUrl ? `Live: ${project.liveUrl}` : undefined,
    project.githubUrl ? `GitHub: ${project.githubUrl}` : undefined,
  ]);
  if (links.length === 0) {
    return;
  }

  ensurePortfolioSpace(context, COUNT_TWENTY_FIVE);
  context.page.drawText(links.join(" | "), {
    x: context.margin,
    y: context.yPosition,
    size: PORTFOLIO_PROJECT_LABEL_SIZE,
    font: context.font,
    color: context.colors.accent,
  });
  context.yPosition -= COUNT_FIFTEEN;
}

function renderPortfolioProjectTags(context: PortfolioRenderContext, tags?: string[]): void {
  if (!Array.isArray(tags) || tags.length === 0) {
    return;
  }

  ensurePortfolioSpace(context, COUNT_TWENTY_FIVE);
  context.page.drawText(`Tags: ${tags.join(", ")}`, {
    x: context.margin,
    y: context.yPosition,
    size: PORTFOLIO_PROJECT_TAGS_SIZE,
    font: context.font,
    color: context.colors.footer,
  });
  context.yPosition -= COUNT_TWENTY;
}

function renderPortfolioProjectSeparator(
  context: PortfolioRenderContext,
  shouldRender: boolean,
): void {
  if (!shouldRender) {
    return;
  }

  ensurePortfolioSpace(context, COUNT_TWENTY);
  context.page.drawLine({
    start: { x: context.margin, y: context.yPosition },
    end: { x: context.width - context.margin, y: context.yPosition },
    thickness: PORTFOLIO_PROJECT_SEPARATOR_THICKNESS,
    color: context.colors.line,
  });
  context.yPosition -= COUNT_TWENTY;
}

export function renderPortfolioProject(
  context: PortfolioRenderContext,
  project: PortfolioProject,
  index: number,
  totalProjects: number,
): void {
  ensurePortfolioSpace(context, PORTFOLIO_PROJECT_SPACE);
  renderPortfolioProjectHeading(context, project, index);
  renderPortfolioProjectRole(context, project.role);

  drawPortfolioWrappedText(context, {
    text: project.description,
    x: context.margin,
    size: PORTFOLIO_PROJECT_BODY_SIZE,
    color: context.colors.text,
    font: context.font,
    maxWidth: context.width - context.margin * 2,
  });
  context.yPosition -= PORTFOLIO_PROJECT_DESCRIPTION_GAP;

  renderPortfolioProjectTechnologies(context, project.technologies);
  renderPortfolioTechnicalDetails(context, project);
  renderPortfolioProjectLinks(context, project);
  renderPortfolioProjectTags(context, project.tags);

  context.yPosition -= COUNT_FIFTEEN;
  renderPortfolioProjectSeparator(context, index < totalProjects - 1);
}

import type { PortfolioMetadata, PortfolioProject } from "@bao/shared/types/portfolio";
import {
  addPortfolioPageNumbers,
  createPortfolioContext,
} from "./export-service-portfolio-context";
import {
  renderPortfolioCoverPage,
  startPortfolioProjectsSection,
} from "./export-service-portfolio-cover";
import { renderPortfolioProject } from "./export-service-portfolio-projects";

export async function exportPortfolioPdf(
  metadata: PortfolioMetadata,
  projects: PortfolioProject[],
  template?: string | null,
): Promise<Uint8Array> {
  const context = await createPortfolioContext(template);
  renderPortfolioCoverPage(context, metadata);
  startPortfolioProjectsSection(context);

  for (let index = 0; index < projects.length; index += 1) {
    renderPortfolioProject(context, projects[index], index, projects.length);
  }

  addPortfolioPageNumbers(context);
  return context.pdfDoc.save();
}

import {
  RESUME_CONTACT_SPACING,
  RESUME_DIVIDER_SPACING,
  RESUME_HEADER_NAME_SPACING,
  RESUME_LINKS_SPACING,
} from "@bao/shared/constants/export-layout";
import { COUNT_THREE, COUNT_TWENTY } from "@bao/shared/constants/numeric";
import type { ResumeData } from "@bao/shared/types/resume";
import { collectDefinedStringValues } from "@bao/shared/utils/export-contract";
import {
  type ResumePersonalInfo,
  type ResumeRenderContext,
  toPdfColor,
} from "./export-service-contracts";
import { drawResumeWrappedText, renderResumeSectionHeader } from "./export-service-resume-layout";

function renderResumeName(context: ResumeRenderContext, name: string): void {
  if (context.layout.headerStyle === "banner") {
    context.page.drawRectangle({
      x: 0,
      y: context.yPosition - 10,
      width: context.width,
      height: context.fonts.name + COUNT_TWENTY,
      color: context.palette.primary,
    });
    context.page.drawText(name, {
      x: context.width / 2 - context.font.widthOfTextAtSize(name, context.fonts.name) / 2,
      y: context.yPosition,
      size: context.fonts.name,
      font: context.boldFont,
      color: toPdfColor(context.background),
    });
    return;
  }

  if (context.layout.headerStyle === "centered") {
    context.page.drawText(name, {
      x: context.width / 2 - context.font.widthOfTextAtSize(name, context.fonts.name) / 2,
      y: context.yPosition,
      size: context.fonts.name,
      font: context.boldFont,
      color: context.palette.primary,
    });
    return;
  }

  context.page.drawText(name, {
    x: context.margin,
    y: context.yPosition,
    size: context.fonts.name,
    font: context.boldFont,
    color: context.palette.primary,
  });
}

function renderResumeContact(context: ResumeRenderContext, info?: ResumePersonalInfo): void {
  const contactItems = collectDefinedStringValues([info?.email, info?.phone, info?.location]);
  if (contactItems.length === 0) {
    return;
  }

  context.page.drawText(contactItems.join(" | "), {
    x: context.margin,
    y: context.yPosition,
    size: context.fonts.body,
    font: context.font,
    color: context.palette.text,
  });
  context.yPosition -= RESUME_CONTACT_SPACING;
}

function renderResumeLinks(context: ResumeRenderContext, info?: ResumePersonalInfo): void {
  const linkItems = collectDefinedStringValues([info?.website, info?.linkedIn, info?.github]);
  if (linkItems.length === 0) {
    return;
  }

  context.page.drawText(linkItems.join(" | "), {
    x: context.margin,
    y: context.yPosition,
    size: context.fonts.accent,
    font: context.font,
    color: context.palette.accent,
  });
  context.yPosition -= RESUME_LINKS_SPACING;
}

function renderResumeDivider(context: ResumeRenderContext): void {
  if (context.layout.dividerStyle === "line") {
    context.page.drawLine({
      start: { x: context.margin, y: context.yPosition },
      end: { x: context.width - context.margin, y: context.yPosition },
      thickness: 1,
      color: context.palette.line,
    });
    context.yPosition -= RESUME_DIVIDER_SPACING;
    return;
  }

  if (context.layout.dividerStyle === "accent-bar") {
    context.page.drawRectangle({
      x: context.margin,
      y: context.yPosition - COUNT_THREE,
      width: context.width - context.margin * 2,
      height: 5,
      color: context.palette.accent,
    });
    context.yPosition -= RESUME_DIVIDER_SPACING;
    return;
  }

  context.yPosition -= 10;
}

export function renderResumeHeader(context: ResumeRenderContext, resume: ResumeData): void {
  const name = resume.personalInfo?.name;
  if (name) {
    renderResumeName(context, name);
    context.yPosition -= RESUME_HEADER_NAME_SPACING;
  }

  renderResumeContact(context, resume.personalInfo);
  renderResumeLinks(context, resume.personalInfo);
  renderResumeDivider(context);
}

export function renderResumeSummary(context: ResumeRenderContext, resume: ResumeData): void {
  if (!resume.summary) {
    return;
  }

  renderResumeSectionHeader(context, "SUMMARY");
  drawResumeWrappedText(context, {
    text: resume.summary,
    x: context.margin,
    size: context.fonts.body,
    color: context.palette.text,
    font: context.font,
    maxWidth: context.width - context.margin * 2,
  });
  context.yPosition -= 10;
}

import { API_ERROR_UNSUPPORTED_RESUME_TEMPLATE } from "@bao/shared/constants/api-errors";
import {
  A4_PAGE_HEIGHT,
  A4_PAGE_WIDTH,
  RESUME_BODY_LINE_GAP,
  RESUME_SECTION_HEADER_SPACING,
  RESUME_SECTION_SPACE,
} from "@bao/shared/constants/export-layout";
import { RESUME_EXPORT_THEME_CONFIGS } from "@bao/shared/constants/export-resume-theme";
import { RATIO_HALF } from "@bao/shared/constants/numeric";
import { RESUME_TEMPLATE_DEFAULT, type ResumeTemplate } from "@bao/shared/constants/resume";
import { resolveResumeExportTemplate } from "@bao/shared/utils/export-contract";
import { PDFDocument, StandardFonts } from "pdf-lib";

import {
  addA4Page,
  type ResumeRenderContext,
  type ResumeTemplateDefinition,
  toPdfColor,
  type WrappedTextOptions,
} from "./export-service-contracts";

export function resolveResumePdfTemplate(
  requestedTemplate: string | undefined,
  resumeTemplate: ResumeTemplate | undefined,
): ResumeTemplateDefinition {
  const resolvedTemplate = resolveResumeExportTemplate(requestedTemplate, resumeTemplate);
  const template =
    RESUME_EXPORT_THEME_CONFIGS[resolvedTemplate]?.pdf ??
    RESUME_EXPORT_THEME_CONFIGS[RESUME_TEMPLATE_DEFAULT]?.pdf;
  if (!template) {
    throw new Error(`${API_ERROR_UNSUPPORTED_RESUME_TEMPLATE}: ${resolvedTemplate}`);
  }
  return template;
}

export function applyResumeBackground(context: ResumeRenderContext, page = context.page): void {
  if (context.background.r >= RATIO_HALF) {
    return;
  }

  page.drawRectangle({
    x: 0,
    y: 0,
    width: A4_PAGE_WIDTH,
    height: A4_PAGE_HEIGHT,
    color: toPdfColor(context.background),
  });
}

export function ensureResumeSpace(context: ResumeRenderContext, requiredSpace: number): void {
  if (context.yPosition - requiredSpace >= context.margin) {
    return;
  }

  context.page = addA4Page(context.pdfDoc);
  applyResumeBackground(context, context.page);
  context.yPosition = context.height - context.margin;
}

export function drawResumeWrappedLine(
  context: ResumeRenderContext,
  options: WrappedTextOptions,
  line: string,
): void {
  const lineGap = options.lineGap ?? RESUME_BODY_LINE_GAP;
  ensureResumeSpace(context, options.size + lineGap);
  context.page.drawText(line, {
    x: options.x,
    y: context.yPosition,
    size: options.size,
    font: options.font,
    color: options.color,
  });
  context.yPosition -= options.size + lineGap;
}

export function drawResumeWrappedText(
  context: ResumeRenderContext,
  options: WrappedTextOptions,
): void {
  const words = options.text.split(" ");
  let line = "";

  for (const word of words) {
    const testLine = `${line}${word} `;
    const testWidth = options.font.widthOfTextAtSize(testLine, options.size);
    if (testWidth > options.maxWidth && line.length > 0) {
      drawResumeWrappedLine(context, options, line.trim());
      line = `${word} `;
      continue;
    }
    line = testLine;
  }

  if (line.trim().length > 0) {
    drawResumeWrappedLine(context, options, line.trim());
  }
}

export async function createResumeContext(
  template: ResumeTemplateDefinition,
): Promise<ResumeRenderContext> {
  const pdfDoc = await PDFDocument.create();
  const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const boldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const page = addA4Page(pdfDoc);
  const { width, height } = page.getSize();

  const context: ResumeRenderContext = {
    pdfDoc,
    page,
    width,
    height,
    margin: template.spacing.margins.left,
    yPosition: height - template.spacing.margins.left,
    fonts: template.fonts,
    layout: template.layout,
    palette: {
      primary: toPdfColor(template.colors.primary),
      text: toPdfColor(template.colors.text),
      line: toPdfColor(template.colors.secondary),
      accent: toPdfColor(template.colors.accent),
    },
    background: template.colors.background,
    font,
    boldFont,
  };

  applyResumeBackground(context);
  return context;
}

