import type { Achievement } from "@bao/shared/types/gamification";
import { ACHIEVEMENT_DEFINITIONS, type NumericGamificationStats } from "./gamification-definitions";
import { areAchievementRequirementsMet } from "./gamification-progress";

export function buildAchievementStatuses(unlockedIds: string[]): Achievement[] {
  const unlocked = new Set(unlockedIds);
  return ACHIEVEMENT_DEFINITIONS.map((achievement) => ({
    ...achievement,
    unlocked: unlocked.has(achievement.id),
  }));
}

export function findUnlockableAchievements(input: {
  achievements: Achievement[];
  existingStats: NumericGamificationStats;
  pendingStats: NumericGamificationStats;
}): Achievement[] {
  return input.achievements.filter(
    (achievement) =>
      !achievement.unlocked &&
      areAchievementRequirementsMet(achievement, input.pendingStats, input.existingStats),
  );
}

import { MS_PER_DAY } from "@bao/shared/constants/time";
import type { DailyChallenge } from "@bao/shared/types/gamification";
import { getDefinedChallenges } from "./gamification-progress";

export function buildDailyChallengesView(
  dailyChallenges: Record<string, string[]>,
  now: Date,
): DailyChallenge[] {
  const today = now.toISOString().split("T")[0];
  const todaysChallenges = dailyChallenges[today] || [];

  if (todaysChallenges.length > 0) {
    return getDefinedChallenges().map((challenge) => ({
      ...challenge,
      completed: todaysChallenges.includes(challenge.id),
    }));
  }

  return getDefinedChallenges().map((challenge) => ({
    ...challenge,
    completed: false,
    validUntil: new Date(now.getTime() + MS_PER_DAY).toISOString(),
  }));
}

export function completeChallengeState(input: {
  challengeId: string;
  dailyChallenges: Record<string, string[]>;
  now: Date;
}): { challenge: DailyChallenge; updatedChallenges: Record<string, string[]> } | null {
  const today = input.now.toISOString().split("T")[0];
  const todaysChallenges = input.dailyChallenges[today] || [];

  if (todaysChallenges.includes(input.challengeId)) {
    return null;
  }

  const challenge = getDefinedChallenges().find((candidate) => candidate.id === input.challengeId);
  if (!challenge) {
    return null;
  }

  return {
    challenge,
    updatedChallenges: {
      ...input.dailyChallenges,
      [today]: [...todaysChallenges, input.challengeId],
    },
  };
}

import { SCHEMA_MAX_ITEMS_BOARDS } from "@bao/shared/constants/schema-limits";
import type { GamificationActionHistoryEntry } from "@bao/shared/types/gamification";
import { DEFAULT_PROFILE_ID } from "@bao/shared/types/settings-defaults";
import {
  ACHIEVEMENT_DEFINITIONS,
  GAMIFICATION_STAT_KEYS,
} from "./gamification-achievement-definitions";
import { DAILY_CHALLENGE_DEFINITIONS } from "./gamification-challenge-definitions";

export const GAMIFICATION_DEFAULT_ID = DEFAULT_PROFILE_ID;
export const MAX_ACTION_HISTORY = SCHEMA_MAX_ITEMS_BOARDS;
export const WEEK_DAYS = 7;
export type ActionHistoryEntry = GamificationActionHistoryEntry;
export type NumericGamificationStats = Partial<Record<string, number>>;
export type WeeklyDaySummary = { date: string; actions: number; xpEarned: number };
export type WeeklyProgressResult = {
  challengesCompleted: number;
  xpEarned: number;
  actionsCount: number;
  days: WeeklyDaySummary[];
  topCategory: string;
};

export { ACHIEVEMENT_DEFINITIONS, DAILY_CHALLENGE_DEFINITIONS, GAMIFICATION_STAT_KEYS };

import {
  COUNT_FOURTEEN,
  COUNT_SEVEN,
  COUNT_THIRTY,
  COUNT_THREE,
  PERCENT_MAX,
  RATIO_FIVE_QUARTERS,
  RATIO_ONE,
  RATIO_THREE,
  RATIO_THREE_HALVES,
  RATIO_TWO,
} from "@bao/shared/constants/numeric";
import { MS_PER_DAY } from "@bao/shared/constants/time";
import type {
  Achievement,
  DailyChallenge,
  GamificationStats,
} from "@bao/shared/types/gamification";
import { isRecord } from "@bao/shared/utils/type-guards";

import {
  type ActionHistoryEntry,
  DAILY_CHALLENGE_DEFINITIONS,
  GAMIFICATION_STAT_KEYS,
  type NumericGamificationStats,
  WEEK_DAYS,
  type WeeklyDaySummary,
  type WeeklyProgressResult,
} from "./gamification-definitions";

export function typeSafeStats(
  stats: Partial<GamificationStats> | null | undefined,
): Partial<GamificationStats> & { actionHistory: ActionHistoryEntry[] } {
  return {
    ...toNumericStats(stats),
    actionHistory: toActionHistory(stats),
  };
}

export function toNumericStats(
  stats: Partial<GamificationStats> | null | undefined,
): NumericGamificationStats {
  if (!stats || typeof stats !== "object") {
    return {};
  }

  const normalized: NumericGamificationStats = {};
  for (const key of GAMIFICATION_STAT_KEYS) {
    const value = stats[key];
    if (typeof value === "number" && Number.isFinite(value)) {
      normalized[key] = value;
    }
  }
  return normalized;
}

export function toActionHistory<T>(stats: T): ActionHistoryEntry[] {
  if (!isRecord(stats)) {
    return [];
  }

  const rawHistory = stats.actionHistory;
  if (!Array.isArray(rawHistory)) {
    return [];
  }

  const entries: ActionHistoryEntry[] = [];
  for (const entry of rawHistory) {
    if (!isRecord(entry)) {
      continue;
    }
    if (typeof entry.action !== "string") {
      continue;
    }
    if (typeof entry.xpGained !== "number") {
      continue;
    }
    if (typeof entry.timestamp !== "string") {
      continue;
    }
    entries.push({
      action: entry.action,
      xpGained: entry.xpGained,
      timestamp: entry.timestamp,
    });
  }
  return entries;
}

export function getNumericStat(stats: NumericGamificationStats, key: string): number {
  const value = stats[key];
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

const STREAK_MULTIPLIER_STEPS = [
  [COUNT_THIRTY, RATIO_THREE],
  [COUNT_FOURTEEN, RATIO_TWO],
  [COUNT_SEVEN, RATIO_THREE_HALVES],
  [COUNT_THREE, RATIO_FIVE_QUARTERS],
] as const;

export function getStreakMultiplier(currentStreak: number): number {
  return (
    STREAK_MULTIPLIER_STEPS.find(([threshold]) => currentStreak >= threshold)?.[1] ?? RATIO_ONE
  );
}

export function areAchievementRequirementsMet(
  achievement: Achievement,
  pendingStats: NumericGamificationStats,
  existingStats: NumericGamificationStats,
): boolean {
  for (const [key, requiredValue] of Object.entries(achievement.requirements)) {
    const pendingValue = getNumericStat(pendingStats, key);
    const existingValue = getNumericStat(existingStats, key);
    const statValue = pendingValue || existingValue;
    if (statValue < requiredValue) {
      return false;
    }
  }
  return true;
}

export function getDefinedChallenges(): DailyChallenge[] {
  return DAILY_CHALLENGE_DEFINITIONS.map((challenge) => ({ ...challenge }));
}

export function filterActionsByDate(
  actions: ActionHistoryEntry[],
  start: Date,
  end: Date,
): ActionHistoryEntry[] {
  return actions.filter((action) => {
    const timestamp = new Date(action.timestamp);
    return timestamp >= start && timestamp <= end;
  });
}

export function groupActionsByDate(
  actions: ActionHistoryEntry[],
): Map<string, { actions: number; xpEarned: number }> {
  const dayMap = new Map<string, { actions: number; xpEarned: number }>();
  for (const action of actions) {
    const day = action.timestamp.split("T")[0];
    const existing = dayMap.get(day) || { actions: 0, xpEarned: 0 };
    dayMap.set(day, {
      actions: existing.actions + 1,
      xpEarned: existing.xpEarned + (action.xpGained || 0),
    });
  }
  return dayMap;
}

export function groupCategoriesByAction(actions: ActionHistoryEntry[]): Map<string, number> {
  const categoryCount = new Map<string, number>();
  for (const action of actions) {
    const category = action.action?.split(":")[0] || "general";
    categoryCount.set(category, (categoryCount.get(category) || 0) + 1);
  }
  return categoryCount;
}

export function buildWeeklyDaySummaries(
  now: Date,
  dayMap: Map<string, { actions: number; xpEarned: number }>,
): WeeklyDaySummary[] {
  const days: WeeklyDaySummary[] = [];
  for (let offset = WEEK_DAYS - 1; offset >= 0; offset--) {
    const date = new Date(now.getTime() - offset * MS_PER_DAY).toISOString().split("T")[0];
    const dayData = dayMap.get(date) || { actions: 0, xpEarned: 0 };
    days.push({ date, ...dayData });
  }
  return days;
}

export function resolveTopCategory(categoryCount: Map<string, number>): string {
  let topCategory = "general";
  let topCount = 0;
  for (const [category, count] of categoryCount) {
    if (count > topCount) {
      topCategory = category;
      topCount = count;
    }
  }
  return topCategory;
}

export function countCompletedChallenges(
  dailyChallenges: Record<string, string[]>,
  start: Date,
  end: Date,
): number {
  return Object.entries(dailyChallenges).reduce((total, [dateKey, completed]) => {
    const date = new Date(dateKey);
    return date >= start && date <= end && Array.isArray(completed)
      ? total + completed.length
      : total;
  }, 0);
}

export function buildWeeklyProgress(
  stats: Partial<GamificationStats> | null | undefined,
  dailyChallenges: Record<string, string[]>,
): WeeklyProgressResult {
  const now = new Date();
  const weekAgo = new Date(now.getTime() - WEEK_DAYS * MS_PER_DAY);
  const actionHistory = typeSafeStats(stats).actionHistory;
  const weekActions = filterActionsByDate(actionHistory, weekAgo, now);
  const dayMap = groupActionsByDate(weekActions);
  const categoryCount = groupCategoriesByAction(weekActions);

  return {
    challengesCompleted: countCompletedChallenges(dailyChallenges, weekAgo, now),
    xpEarned: weekActions.reduce((sum, action) => sum + (action.xpGained || 0), 0),
    actionsCount: weekActions.length,
    days: buildWeeklyDaySummaries(now, dayMap),
    topCategory: resolveTopCategory(categoryCount),
  };
}

export function buildMonthlyStats(input: {
  currentStreak: number;
  dailyChallenges: Record<string, string[]>;
  stats: Partial<GamificationStats> | null | undefined;
}) {
  const actionHistory = typeSafeStats(input.stats).actionHistory;
  const now = new Date();
  const monthAgo = new Date(now.getTime() - COUNT_THIRTY * MS_PER_DAY);
  const monthActions = filterActionsByDate(actionHistory, monthAgo, now);
  const totalXP = monthActions.reduce((sum, action) => sum + (action.xpGained || 0), 0);

  return {
    totalXP,
    levelsGained: Math.floor(totalXP / PERCENT_MAX),
    achievementsUnlocked: monthActions.filter((action) =>
      action.action?.startsWith("Achievement unlocked:"),
    ).length,
    challengesCompleted: countCompletedChallenges(input.dailyChallenges, monthAgo, now),
    actionsCount: monthActions.length,
    streakDays: Math.min(input.currentStreak, COUNT_THIRTY),
  };
}

export function appendActionHistoryEntry(
  actionHistory: ActionHistoryEntry[],
  entry: ActionHistoryEntry,
  maxEntries: number,
): ActionHistoryEntry[] {
  const updated = [...actionHistory, entry];
  if (updated.length <= maxEntries) {
    return updated;
  }
  return updated.slice(updated.length - maxEntries);
}

import { MS_PER_DAY } from "@bao/shared/constants/time";
import { getLevelForXP } from "@bao/shared/constants/xp-levels";
import type {
  Achievement,
  DailyChallenge,
  GamificationStats,
  LevelUpResult,
  UserGamificationData,
} from "@bao/shared/types/gamification";
import { settle } from "@bao/shared/utils/promise";
import { createServerLogger } from "../utils/logger";
import { buildAchievementStatuses, findUnlockableAchievements } from "./gamification-achievements";
import { buildDailyChallengesView, completeChallengeState } from "./gamification-challenges";
import { GAMIFICATION_DEFAULT_ID, type WeeklyProgressResult } from "./gamification-definitions";
import {
  buildMonthlyStats,
  buildWeeklyProgress,
  getNumericStat,
  getStreakMultiplier,
  toNumericStats,
  typeSafeStats,
} from "./gamification-progress";
import {
  getOrCreateGamificationProgress,
  persistAchievements,
  persistAwardedXP,
  persistDailyChallenges,
  persistStats,
  persistStreak,
} from "./gamification-storage";

const gamificationLogger = createServerLogger("gamification");

export class GamificationService {
  private readonly DEFAULT_ID = GAMIFICATION_DEFAULT_ID;

  async getProgress(): Promise<UserGamificationData> {
    return await getOrCreateGamificationProgress(this.DEFAULT_ID);
  }

  async awardXP(amount: number, reason: string): Promise<LevelUpResult | null> {
    const progress = await this.getProgress();
    const multiplier = getStreakMultiplier(progress.currentStreak);
    const adjustedAmount = Math.round(amount * multiplier);
    const oldLevelData = getLevelForXP(progress.xp);
    const newXP = progress.xp + adjustedAmount;
    const newLevelData = getLevelForXP(newXP);
    const now = new Date().toISOString();

    await this.updateStreak();
    await persistAwardedXP({
      actionEntry: {
        action: reason,
        xpGained: adjustedAmount,
        multiplier,
        timestamp: now,
      },
      id: this.DEFAULT_ID,
      newLevel: newLevelData.level,
      newXP,
      stats: typeSafeStats(progress.stats),
    });

    if (newLevelData.level <= progress.level) {
      return null;
    }

    return {
      xpGained: adjustedAmount,
      oldLevel: progress.level,
      newLevel: newLevelData.level,
      oldTitle: oldLevelData.title,
      newTitle: newLevelData.title,
      unlockedFeatures: newLevelData.features || [],
      bonusXP: adjustedAmount - amount,
    };
  }

  async getAchievements(): Promise<Achievement[]> {
    const progress = await this.getProgress();
    return buildAchievementStatuses(progress.achievements);
  }

  async checkAchievements(stats: Partial<GamificationStats>): Promise<Achievement[]> {
    const progress = await this.getProgress();
    const unlockable = findUnlockableAchievements({
      achievements: await this.getAchievements(),
      existingStats: toNumericStats(progress.stats),
      pendingStats: toNumericStats(stats),
    });

    if (unlockable.length === 0) {
      return [];
    }

    const now = new Date().toISOString();
    const unlockedIds = Array.from(
      new Set([...progress.achievements, ...unlockable.map((achievement) => achievement.id)]),
    );
    await persistAchievements({
      achievements: unlockedIds,
      id: this.DEFAULT_ID,
      updatedAt: now,
    });

    await this.awardAchievementsSequentially(unlockable, 0);
    return unlockable.map((achievement) => ({ ...achievement, unlocked: true, unlockedAt: now }));
  }

  private async awardAchievementsSequentially(
    achievements: Achievement[],
    index: number,
  ): Promise<void> {
    if (index >= achievements.length) {
      return;
    }

    const achievement = achievements[index];
    await this.awardXP(achievement.xpReward, `Achievement unlocked: ${achievement.name}`);
    await this.awardAchievementsSequentially(achievements, index + 1);
  }

  async getDailyChallenges(): Promise<DailyChallenge[]> {
    const progress = await this.getProgress();
    return buildDailyChallengesView(progress.dailyChallenges, new Date());
  }

  async completeChallenge(challengeId: string): Promise<boolean> {
    const progress = await this.getProgress();
    const now = new Date();
    const completedChallenge = completeChallengeState({
      challengeId,
      dailyChallenges: progress.dailyChallenges,
      now,
    });

    if (!completedChallenge) {
      return false;
    }

    await persistDailyChallenges({
      dailyChallenges: completedChallenge.updatedChallenges,
      id: this.DEFAULT_ID,
      updatedAt: now.toISOString(),
    });
    await this.awardXP(
      completedChallenge.challenge.xpReward,
      `Daily challenge completed: ${completedChallenge.challenge.name}`,
    );

    return true;
  }

  async updateStreak(): Promise<void> {
    const progress = await this.getProgress();
    const today = new Date().toISOString().split("T")[0];
    const lastActive = progress.lastActiveDate?.split("T")[0];

    if (!lastActive || lastActive === today) {
      return;
    }

    const yesterday = new Date(Date.now() - MS_PER_DAY).toISOString().split("T")[0];
    const currentStreak = lastActive === yesterday ? progress.currentStreak + 1 : 1;
    const longestStreak = Math.max(progress.longestStreak, currentStreak);
    const now = new Date().toISOString();

    await persistStreak({
      currentStreak,
      id: this.DEFAULT_ID,
      lastActiveDate: now,
      longestStreak,
      updatedAt: now,
    });
  }

  async getWeeklyProgress(): Promise<WeeklyProgressResult> {
    const progress = await this.getProgress();
    return buildWeeklyProgress(progress.stats, progress.dailyChallenges);
  }

  async getMonthlyStats(): Promise<{
    totalXP: number;
    levelsGained: number;
    achievementsUnlocked: number;
    challengesCompleted: number;
    actionsCount: number;
    streakDays: number;
  }> {
    const progress = await this.getProgress();
    return buildMonthlyStats({
      currentStreak: progress.currentStreak,
      dailyChallenges: progress.dailyChallenges,
      stats: progress.stats,
    });
  }

  async trackAction(
    statKey: keyof GamificationStats,
    xpAmount: number,
    reason: string,
  ): Promise<void> {
    const progress = await this.getProgress();
    const currentStats = toNumericStats(progress.stats);
    const updatedStats: Partial<GamificationStats> = {
      ...currentStats,
      [statKey]: getNumericStat(currentStats, statKey) + 1,
    };

    const now = new Date().toISOString();
    await persistStats({
      id: this.DEFAULT_ID,
      stats: updatedStats,
      updatedAt: now,
    });

    await this.awardXP(xpAmount, reason);
    await this.checkAchievements(updatedStats);
  }

  trackActionFireAndForget(
    statKey: keyof GamificationStats,
    xpAmount: number,
    reason: string,
  ): void {
    settle(this.trackAction(statKey, xpAmount, reason)).then(
      (result) => {
        if (result.status === "rejected") {
          gamificationLogger.error("trackAction failed", {
            statKey,
            reason,
            err: result.reason instanceof Error ? result.reason.message : String(result.reason),
          });
        }
      },
      () => undefined,
    );
  }
}

