const SUMMARY_HIGHLIGHT_SPLIT_PATTERN = /[;,]/u;

function extractSummaryValue(summary: string, label: string): string {
  const matcher = new RegExp(`^- ${label}:\\s*(.+)$`, "im");
  return summary.match(matcher)?.[1]?.trim() ?? "";
}

function extractSummaryHighlights(summary: string, label: string, maxItems = 3): string[] {
  return extractSummaryValue(summary, label)
    .split(SUMMARY_HIGHLIGHT_SPLIT_PATTERN)
    .map((value) => value.trim())
    .filter((value) => value.length > 0 && value !== DEFAULT_UNSPECIFIED_LABEL)
    .slice(0, maxItems);
}

function buildFallbackInterviewContext(
  studio: StudioContext,
  config: InterviewConfig,
  candidateContext: CandidateInterviewContext,
): FallbackInterviewContext {
  const targetJob = config.targetJob;
  const interviewEntity =
    config.interviewMode === "job" && targetJob?.company ? targetJob.company : studio.name;
  const roleTarget = targetJob?.title || config.roleType;
  const technicalHighlights =
    targetJob?.technologies?.filter((value) => value.trim().length > 0) ??
    extractSummaryHighlights(candidateContext.resumeSummary, "Technical skills");

  return {
    interviewEntity,
    roleTarget,
    primaryTechnology:
      technicalHighlights.find((value) => value.length > 0) ?? "your strongest technical stack",
    experienceHighlight:
      extractSummaryHighlights(candidateContext.resumeSummary, "Experience highlights", 1)[0] ??
      extractSummaryHighlights(candidateContext.profileSummary, "Current role", 1)[0] ??
      "recent game-industry delivery work",
    projectHighlight:
      extractSummaryHighlights(candidateContext.resumeSummary, "Project highlights", 1)[0] ??
      extractSummaryHighlights(candidateContext.portfolioSummary, "Featured work", 1)[0] ??
      "a player-facing system you shipped",
    focusArea:
      targetJob?.enrichment?.interviewFocusAreas?.[0] ??
      studio.enrichment?.interviewFocusAreas?.[0] ??
      "cross-functional delivery",
    hiringSignal:
      targetJob?.enrichment?.hiringSignals?.[0] ??
      studio.enrichment?.hiringSignals?.[0] ??
      "shipping velocity and collaborative execution",
    pitchAngle:
      targetJob?.enrichment?.candidatePitchAngles?.[0] ??
      studio.enrichment?.candidatePitchAngles?.[0] ??
      "measurable player impact and ownership",
  };
}

function buildFallbackQuestionText(
  seed: Omit<InterviewQuestion, "id">,
  context: FallbackInterviewContext,
): { question: string; followUps: string[]; tags: string[] } {
  switch (seed.type) {
    case "intro":
      return {
        question: `Your background highlights ${context.experienceHighlight}. How does that prepare you for the ${context.roleTarget} role at ${context.interviewEntity}?`,
        followUps: [
          `Which result from ${context.projectHighlight} is most relevant to ${context.interviewEntity}?`,
          "How did you validate the outcome with teammates, stakeholders, or players?",
          "What tradeoff from that work would you handle differently now?",
        ],
        tags: [...seed.tags, "candidate-context", "role-context"],
      };
    case "behavioral":
      return {
        question: `Tell me about a time you aligned design, QA, or production partners to deliver ${context.focusArea} work with a clear outcome.`,
        followUps: [
          "What disagreement or constraint made the collaboration difficult?",
          "How did you keep the team aligned when priorities shifted?",
          "What evidence told you the collaboration was successful?",
        ],
        tags: [...seed.tags, "candidate-context", "collaboration"],
      };
    case "studio-specific":
      return {
        question: `${context.interviewEntity} is signaling ${context.hiringSignal}. How would you ramp up in your first 30 days and show that ${context.pitchAngle}?`,
        followUps: [
          `Which stakeholder would you meet first to support ${context.focusArea}?`,
          "What deliverable would you aim to own by the end of your first sprint?",
          "How would you tailor your communication to this studio context?",
        ],
        tags: [...seed.tags, "studio-context", "scrape-enrichment"],
      };
    case "technical":
      return {
        question: `Walk me through a system from ${context.projectHighlight} where you used ${context.primaryTechnology} in a way that would transfer directly to the ${context.roleTarget} scope at ${context.interviewEntity}.`,
        followUps: [
          `What constraints shaped your use of ${context.primaryTechnology}?`,
          "What telemetry, QA checks, or player signals told you the solution was healthy?",
          "How would you scale that approach for a larger team or live-service environment?",
        ],
        tags: [...seed.tags, "candidate-context", "technical-context"],
      };
    case "closing":
      return {
        question: `What is the strongest evidence from your resume, cover letter, or portfolio that you are ready for ${context.roleTarget} at ${context.interviewEntity} right now?`,
        followUps: [
          "Which accomplishment best proves that claim?",
          "How does that evidence connect to this studio's priorities?",
          "What would you aim to deliver in your first 30 days?",
        ],
        tags: [...seed.tags, "candidate-context", "closing"],
      };
    default: {
      const _exhaustive: never = seed.type;
      return _exhaustive;
    }
  }
}

export function buildFallbackQuestions(
  config: InterviewConfig,
  studio: StudioContext,
  candidateContext: CandidateInterviewContext,
): InterviewQuestion[] {
  const filtered = FALLBACK_INTERVIEW_QUESTIONS.filter((question) => {
    if (question.type === "technical") {
      return Boolean(config.includeTechnical);
    }
    if (question.type === "behavioral") {
      return Boolean(config.includeBehavioral);
    }
    if (question.type === "studio-specific") {
      return Boolean(config.includeStudioSpecific);
    }
    return true;
  });

  const normalizedQuestionCount = Math.max(1, config.questionCount);
  const pool = filtered.length > 0 ? filtered : FALLBACK_INTERVIEW_QUESTIONS;
  const context = buildFallbackInterviewContext(studio, config, candidateContext);
  const questions: InterviewQuestion[] = [];

  while (questions.length < normalizedQuestionCount) {
    const seed = pool[questions.length % pool.length];
    const contextualized = buildFallbackQuestionText(seed, context);
    questions.push({
      ...seed,
      id: `fallback-${questions.length + 1}`,
      question: contextualized.question,
      followUps: contextualized.followUps,
      tags: contextualized.tags,
    });
  }

  return questions.slice(0, normalizedQuestionCount);
}

export function buildFallbackNaturalQuestion(
  session: { config: InterviewConfig; responses: InterviewResponse[] },
  studio: StudioContext,
  candidateContext: CandidateInterviewContext,
): InterviewQuestion | null {
  const nextFallback = buildFallbackQuestions(session.config, studio, candidateContext)[
    session.responses.length
  ];

  if (!nextFallback) {
    return null;
  }

  return {
    ...nextFallback,
    id: `natural-fallback-${session.responses.length + 1}`,
  };
}

import {
  AI_DEFAULT_TEMPERATURE_INTERVIEW,
  AI_MAX_TOKENS_QUESTION,
} from "@bao/shared/constants/ai-generation";
import { COUNT_FIVE } from "@bao/shared/constants/numeric";
import {
  SCORE_PASS_THRESHOLD,
  SCORE_WARNING_THRESHOLD,
} from "@bao/shared/constants/score-thresholds";
import type {
  InterviewAnalysis,
  InterviewConfig,
  InterviewResponse,
} from "@bao/shared/types/interview";
import { resolveInterviewAnalysisProvenance } from "@bao/shared/utils/interview-analysis-provenance";
import { settle } from "@bao/shared/utils/promise";
import { isRecord } from "@bao/shared/utils/type-guards";
import { interviewPersonaPrompt } from "./ai/prompts-interview";
import { withAiOperationTimeout } from "./interview-service-ai";
import { createAIService, resolveCandidateInterviewContext } from "./interview-service-context";
import type { FinalAnalysisPromptContext, StudioContext } from "./interview-service-contracts";
import { normalizeScore } from "./interview-service-normalizers";
import { buildStudioPromptContext } from "./ai/prompt-context-entities";
import {
  buildCandidatePromptContext,
  buildInterviewerPersona,
  buildInterviewJobPromptContext,
} from "./interview-service-prompt-context";
import { parseStringArray, safeParseJSON } from "./interview-service-value-parsers";

function calculateDefaultAnalysis(responses: InterviewResponse[]): InterviewAnalysis {
  if (responses.length === 0) {
    return {
      overallScore: 0,
      strengths: [],
      improvements: ["Complete all responses for a full analysis."],
      recommendations: ["Answer with measurable outcomes and concrete examples."],
      feedback: "No responses were recorded.",
    };
  }

  const validScores = responses
    .map((entry) => entry.aiAnalysis?.score)
    .filter((value): value is number => typeof value === "number");
  const average =
    validScores.length > 0
      ? Math.round(validScores.reduce((sum, value) => sum + value, 0) / validScores.length)
      : 0;

  const strengths = Array.from(
    new Set(responses.flatMap((response) => response.aiAnalysis?.strengths || [])),
  );
  const improvements = Array.from(
    new Set(responses.flatMap((response) => response.aiAnalysis?.improvements || [])),
  );

  return {
    overallScore: average,
    strengths: strengths.slice(0, COUNT_FIVE),
    improvements: improvements.slice(0, COUNT_FIVE),
    recommendations: resolveFinalAnalysisRecommendations(average),
    feedback: resolveFinalAnalysisFeedback(average),
  };
}

function resolveFinalAnalysisRecommendations(average: number): string[] {
  if (average >= SCORE_PASS_THRESHOLD) {
    return ["Sustain your structured communication and add extra quantification."];
  }
  if (average >= SCORE_WARNING_THRESHOLD) {
    return ["Work on measurable examples and deeper technical justification."];
  }
  return ["Practice response structure using situation, action, result examples."];
}

function resolveFinalAnalysisFeedback(average: number): string {
  if (average >= SCORE_PASS_THRESHOLD) {
    return "Strong session across technical and behavioral areas.";
  }
  return "Good foundation; improve depth, metrics, and real project examples.";
}

function buildFinalAnalysisPrompt({
  studio,
  config,
  responses,
  persona,
  candidateContext,
}: FinalAnalysisPromptContext): string {
  const responseLines = responses.map(
    (response, index) =>
      `Q${index + 1}: "${response.questionId}"\nA${index + 1}: ${response.transcript}`,
  );

  return `${interviewPersonaPrompt({
    role: config.targetJob?.title || config.roleType,
    company: config.targetJob?.company || studio.name,
    personality: persona.name,
    interviewStyle: studio.interviewStyle,
    focusAreas: config.focusAreas,
  })}
Interview mode: ${config.interviewMode || "studio"}
Conversation style: ${candidateContext.conversationStyle}
${buildStudioPromptContext(studio)}
${buildInterviewJobPromptContext(config)}
${buildCandidatePromptContext(candidateContext)}
You are analyzing the following interview responses.

Responses:
${responseLines.join("\n")}

Return strict JSON only:
{
  "overallScore": 0-100,
  "strengths": ["..."],
  "improvements": ["..."],
  "recommendations": ["..."],
  "feedback": "Short summary"
}
`;
}

function normalizeFinalFromAI(raw: string): InterviewAnalysis | null {
  const parsed = safeParseJSON(raw) ?? {
    overallScore: Number.NaN,
    strengths: [],
    improvements: [],
    recommendations: [],
  };

  if (!isRecord(parsed)) {
    return null;
  }
  if (typeof parsed.overallScore !== "number" || !Number.isFinite(parsed.overallScore)) {
    return null;
  }

  const feedback = typeof parsed.feedback === "string" ? parsed.feedback : "";
  return {
    overallScore: normalizeScore(parsed.overallScore),
    strengths: parseStringArray(parsed.strengths),
    improvements: parseStringArray(parsed.improvements),
    recommendations: parseStringArray(parsed.recommendations),
    ...(feedback ? { feedback } : {}),
  };
}

/**
 * Stamp session-level provenance onto an analysis so the UI can state whether
 * the feedback came from a real AI provider, a heuristic fallback, or a mix.
 */
function withAnalysisProvenance(
  analysis: InterviewAnalysis,
  responses: readonly InterviewResponse[],
): InterviewAnalysis {
  const provenance = resolveInterviewAnalysisProvenance(responses);
  return {
    ...analysis,
    analysisSource: provenance.analysisSource,
    aiAverageScore: provenance.aiAverageScore,
    provenanceCounts: provenance.provenanceCounts,
  };
}

export async function generateFinalAnalysis(
  session: { config: InterviewConfig; responses: InterviewResponse[] },
  studio: StudioContext,
): Promise<InterviewAnalysis> {
  const persona = buildInterviewerPersona(studio, session.config);
  const candidateContext = await resolveCandidateInterviewContext(session.config);
  const prompt = buildFinalAnalysisPrompt({
    studio,
    config: session.config,
    responses: session.responses,
    persona,
    candidateContext,
  });
  const aiServiceResult = await settle(createAIService());
  if (aiServiceResult.status === "rejected") {
    return withAnalysisProvenance(calculateDefaultAnalysis(session.responses), session.responses);
  }

  const response = await withAiOperationTimeout(() =>
    aiServiceResult.value.generate(prompt, {
      purpose: "interviewFeedback",
      temperature: AI_DEFAULT_TEMPERATURE_INTERVIEW,
      maxTokens: AI_MAX_TOKENS_QUESTION,
    }),
  );

  if (!response || response.error) {
    return withAnalysisProvenance(calculateDefaultAnalysis(session.responses), session.responses);
  }

  const parsed = normalizeFinalFromAI(response.content);
  if (parsed) {
    return withAnalysisProvenance(parsed, session.responses);
  }
  return withAnalysisProvenance(calculateDefaultAnalysis(session.responses), session.responses);
}

import {
  COUNT_NINETY,
  COUNT_THIRTY,
  COUNT_THREE_HUNDRED,
  PERCENT_MAX,
} from "@bao/shared/constants/numeric";
import { resolveInterviewAnalysisSource } from "@bao/shared/utils/interview-analysis-provenance";
import type { JsonObject, JsonValue } from "@bao/shared/utils/json";
import type {
  InterviewAnalysis,
  InterviewConfig,
  InterviewQuestion,
  InterviewResponse,
  InterviewSession,
} from "@bao/shared/types/interview";
import { asJsonArray, isRecord } from "@bao/shared/utils/type-guards";
import { normalizeConfig } from "./interview-service-config-normalizers";
import type { DBInterviewSession } from "./interview-service-contracts";
import { parseNumber, parseStringArray } from "./interview-service-value-parsers";

const questionTypePattern = new Set<string>([
  "behavioral",
  "technical",
  "studio-specific",
  "intro",
  "closing",
]);

const difficultyPattern = new Set<string>(["easy", "medium", "hard"]);

export function normalizeQuestionType(
  value: unknown,
  fallback: InterviewQuestion["type"],
): InterviewQuestion["type"] {
  if (typeof value !== "string" || !questionTypePattern.has(value)) {
    return fallback;
  }

  if (
    value === "behavioral" ||
    value === "technical" ||
    value === "studio-specific" ||
    value === "intro" ||
    value === "closing"
  ) {
    return value;
  }

  return fallback;
}

export function normalizeDifficulty(value: unknown): InterviewQuestion["difficulty"] {
  if (typeof value !== "string" || !difficultyPattern.has(value)) {
    return "medium";
  }
  if (value === "easy" || value === "medium" || value === "hard") {
    return value;
  }
  return "medium";
}

export function normalizeQuestions(raw: unknown): InterviewQuestion[] {
  // `Array.isArray` on a wide input narrows to `any[]`, which then spreads
  // `any` through every member access below; asJsonArray keeps elements typed.
  const entries = asJsonArray(raw);
  if (!entries) {
    return [];
  }

  return entries
    .map((value, index): InterviewQuestion | null => {
      if (!isRecord(value)) {
        return null;
      }

      const rawId = value.id;
      const id =
        typeof rawId === "string"
          ? rawId.trim() || `generated-${index + 1}`
          : `generated-${Number(rawId) || index + 1}`;
      const followUps = Array.isArray(value.followUps) ? value.followUps : [];
      if (typeof value.question !== "string" || !value.question.trim()) {
        return null;
      }

      return {
        id,
        type: normalizeQuestionType(value.type, "behavioral"),
        question: value.question.trim(),
        followUps: parseStringArray(followUps),
        expectedDuration: parseNumber(
          value.expectedDuration,
          COUNT_NINETY,
          COUNT_THIRTY,
          COUNT_THREE_HUNDRED,
        ),
        difficulty: normalizeDifficulty(value.difficulty),
        tags: parseStringArray(value.tags),
      };
    })
    .filter((entry): entry is InterviewQuestion => entry !== null);
}

export function normalizeScore(value: number): number {
  if (!Number.isFinite(value)) {
    return 0;
  }
  return Math.max(0, Math.min(PERCENT_MAX, Math.round(value)));
}

export function normalizeAiAnalysisScore(scoreCandidate: unknown): number {
  if (typeof scoreCandidate === "number" && Number.isFinite(scoreCandidate)) {
    return normalizeScore(Math.round(scoreCandidate));
  }
  return 0;
}

/** Shape a persisted response row must satisfy before it is trusted. */
interface PersistedResponseFields {
  readonly questionId: string;
  readonly transcript: string;
  readonly duration: number;
  readonly timestamp: number;
  readonly confidence: number;
}

const toPersistedResponseFields = (value: JsonObject): PersistedResponseFields | null =>
  typeof value.questionId === "string" &&
  typeof value.transcript === "string" &&
  typeof value.duration === "number" &&
  typeof value.timestamp === "number" &&
  typeof value.confidence === "number"
    ? {
        questionId: value.questionId,
        transcript: value.transcript,
        duration: value.duration,
        timestamp: value.timestamp,
        confidence: value.confidence,
      }
    : null;

const toPersistedAiAnalysis = (
  raw: JsonValue | undefined,
): NonNullable<InterviewResponse["aiAnalysis"]> | null => {
  if (!isRecord(raw)) {
    return null;
  }
  return {
    score: normalizeAiAnalysisScore(raw.score),
    feedback: typeof raw.feedback === "string" ? raw.feedback : "",
    strengths: parseStringArray(raw.strengths),
    improvements: parseStringArray(raw.improvements),
    // Persisted rows predate provenance tracking, so an absent or unrecognised
    // marker resolves to "unknown" rather than claiming AI.
    source: resolveInterviewAnalysisSource(raw.source),
    ...(typeof raw.provider === "string" ? { provider: raw.provider } : {}),
    ...(typeof raw.model === "string" ? { model: raw.model } : {}),
  };
};

export function normalizeResponses(raw: unknown): InterviewResponse[] {
  // `Array.isArray` on a wide input narrows to `any[]`, which then spreads
  // `any` through every member access below; asJsonArray keeps elements typed.
  const entries = asJsonArray(raw);
  if (!entries) {
    return [];
  }

  const parsed: InterviewResponse[] = [];
  for (const value of entries) {
    if (!isRecord(value)) {
      continue;
    }
    const fields = toPersistedResponseFields(value);
    if (!fields) {
      continue;
    }
    const aiAnalysis = toPersistedAiAnalysis(value.aiAnalysis);
    parsed.push({ ...fields, ...(aiAnalysis ? { aiAnalysis } : {}) });
  }

  return parsed;
}

export function normalizeFinalAnalysis(raw: unknown): InterviewAnalysis | null {
  if (!isRecord(raw)) {
    return null;
  }
  if (typeof raw.overallScore !== "number") {
    return null;
  }

  const feedback = typeof raw.feedback === "string" ? raw.feedback : "";
  return {
    overallScore: normalizeScore(raw.overallScore),
    strengths: parseStringArray(raw.strengths),
    improvements: parseStringArray(raw.improvements),
    recommendations: parseStringArray(raw.recommendations),
    ...(feedback ? { feedback } : {}),
    // Provenance is stamped at generation time and must survive the round trip,
    // otherwise a reloaded session silently loses its AI-vs-heuristic attribution.
    ...normalizePersistedProvenance(raw),
  };
}

/**
 * Restores session-level analysis provenance from a persisted row. Rows written
 * before provenance tracking simply carry none, and stay unattributed.
 */
function normalizePersistedProvenance(
  raw: JsonObject,
): Pick<InterviewAnalysis, "analysisSource" | "aiAverageScore" | "provenanceCounts"> {
  const source = raw.analysisSource;
  const counts = raw.provenanceCounts;
  return {
    ...(source === "ai" || source === "heuristic" || source === "mixed" || source === "unknown"
      ? { analysisSource: source }
      : {}),
    ...(typeof raw.aiAverageScore === "number" || raw.aiAverageScore === null
      ? { aiAverageScore: raw.aiAverageScore }
      : {}),
    ...(isRecord(counts) &&
    typeof counts.ai === "number" &&
    typeof counts.heuristic === "number" &&
    typeof counts.unknown === "number"
      ? {
          provenanceCounts: {
            ai: counts.ai,
            heuristic: counts.heuristic,
            unknown: counts.unknown,
          },
        }
      : {}),
  };
}

export function normalizeInterviewSessionStatus(value: unknown): InterviewSession["status"] {
  if (
    value === "preparing" ||
    value === "active" ||
    value === "paused" ||
    value === "completed" ||
    value === "cancelled"
  ) {
    return value;
  }
  return "active";
}

export function normalizeSessionConfig(row: DBInterviewSession): InterviewConfig {
  return normalizeConfig(isRecord(row.config) ? row.config : {});
}

import type { InterviewConfig, InterviewerPersona } from "@bao/shared/types/interview";
