const mapQuestionSetToConfig = (raw: string): InterviewQuestion[] => {
  const parsed = safeParseJSON(raw);
  return normalizeQuestions(Array.isArray(parsed) ? parsed : []);
};

const normalizeSingleQuestion = (raw: JsonValue | null): InterviewQuestion | null =>
  normalizeQuestions([raw])[0] ?? null;

const filterGeneratedQuestions = (
  questions: InterviewQuestion[],
  config: InterviewConfig,
): InterviewQuestion[] =>
  questions.filter((question) => {
    if (question.type === "technical" && !config.includeTechnical) {
      return false;
    }
    if (question.type === "behavioral" && !config.includeBehavioral) {
      return false;
    }
    if (question.type === "studio-specific" && !config.includeStudioSpecific) {
      return false;
    }
    return true;
  });

const buildGeneratedQuestionSlice = (
  parsedQuestions: InterviewQuestion[],
  config: InterviewConfig,
  candidateContext: CandidateInterviewContext,
) => {
  const filtered = filterGeneratedQuestions(parsedQuestions, config);
  if (filtered.length === 0) {
    throw new Error(API_ERROR_AI_NO_QUESTIONS);
  }

  return filtered.slice(
    0,
    candidateContext.conversationStyle === "natural" ? 1 : config.questionCount,
  );
};

const tryGenerateQuestions = async (input: {
  aiService: Awaited<ReturnType<typeof createAIService>>;
  prompt: string;
  config: InterviewConfig;
  candidateContext: CandidateInterviewContext;
}): Promise<InterviewQuestion[]> => {
  const response = await withAiOperationTimeout(() =>
    input.aiService.generate(input.prompt, {
      purpose: "interviewQuestions",
      temperature: AI_DEFAULT_TEMPERATURE_INTERVIEW_QUESTIONS,
      maxTokens: AI_MAX_TOKENS_ANALYSIS,
    }),
  );

  if (!response) {
    throw new Error(API_ERROR_AI_OPERATION_TIMEOUT);
  }
  if (response.error) {
    throw new Error(response.error);
  }

  return buildGeneratedQuestionSlice(
    mapQuestionSetToConfig(response.content),
    input.config,
    input.candidateContext,
  );
};

export async function generateNextNaturalQuestion(
  session: { config: InterviewConfig; responses: InterviewResponse[] },
  studio: StudioContext,
  latestResponse: InterviewResponse,
  previousQuestion: InterviewQuestion,
): Promise<InterviewQuestion | null> {
  const candidateContext = await resolveCandidateInterviewContext(session.config);
  const aiServiceResult = await settle(createAIService());
  if (aiServiceResult.status === "rejected") {
    return buildFallbackNaturalQuestion(session, studio, candidateContext);
  }

  const prompt = buildNaturalNextQuestionPrompt({
    studio,
    config: session.config,
    candidateContext,
    previousQuestion,
    latestResponse,
    responses: [...session.responses, latestResponse],
  });

  const response =
    (await withAiOperationTimeout(() =>
      aiServiceResult.value.generate(prompt, {
        purpose: "interviewQuestions",
        temperature: AI_DEFAULT_TEMPERATURE_INTERVIEW,
        maxTokens: AI_MAX_TOKENS_QUESTION,
      }),
    )) ?? null;

  if (!response || response.error) {
    return buildFallbackNaturalQuestion(session, studio, candidateContext);
  }

  const parsed = normalizeSingleQuestion(safeParseJSON(response.content));
  if (parsed) {
    return {
      ...parsed,
      id: `natural-${session.responses.length + 2}`,
    };
  }

  return buildFallbackNaturalQuestion(session, studio, candidateContext);
}

export async function generateQuestions(
  config: InterviewConfig,
  studio: StudioContext,
): Promise<InterviewQuestion[]> {
  const aiService = await createAIService();
  const candidateContext = await resolveCandidateInterviewContext(config);
  const fullPrompt = buildQuestionGenerationPrompt(studio, config, candidateContext);
  const role = config.targetJob?.title || config.roleType || INTERVIEW_DEFAULT_ROLE_TYPE;
  const level = config.experienceLevel;

  const primaryResult = await settle(
    tryGenerateQuestions({
      aiService,
      prompt: fullPrompt,
      config,
      candidateContext,
    }),
  );
  if (primaryResult.status === "fulfilled") {
    return primaryResult.value;
  }
  interviewServiceQuestionsLogger.warn(
    "AI question generation failed on primary prompt, attempting fallback prompt.",
    toErrorMessage(primaryResult.reason),
  );

  const fallbackResult = await settle(
    tryGenerateQuestions({
      aiService,
      prompt: buildSimpleQuestionPrompt(role, level, config.questionCount),
      config,
      candidateContext,
    }),
  );
  if (fallbackResult.status === "fulfilled") {
    return fallbackResult.value;
  }
  interviewServiceQuestionsLogger.warn(
    "AI question generation failed on fallback prompt, using deterministic local questions.",
    toErrorMessage(fallbackResult.reason),
  );

  return buildFallbackQuestions(config, studio, candidateContext);
}

import {
  AI_DEFAULT_TEMPERATURE_INTERVIEW,
  AI_MAX_TOKENS_FEEDBACK,
} from "@bao/shared/constants/ai-generation";
import {
  COUNT_EIGHT,
  COUNT_NINETY,
  COUNT_ONE_FORTY,
  COUNT_SEVEN,
  COUNT_THIRTY_FIVE,
  COUNT_TWELVE,
  COUNT_TWENTY,
  COUNT_TWENTY_FIVE,
  PERCENT_HIGH,
} from "@bao/shared/constants/numeric";
import type {
  InterviewConfig,
  InterviewQuestion,
  InterviewResponse,
} from "@bao/shared/types/interview";
import type { JsonValue } from "@bao/shared/utils/json";
import { settle } from "@bao/shared/utils/promise";
import { isRecord } from "@bao/shared/utils/type-guards";
import { interviewFeedbackPrompt, interviewPersonaPrompt } from "./ai/prompts-interview";
import { withAiOperationTimeout } from "./interview-service-ai";
import { createAIService, resolveCandidateInterviewContext } from "./interview-service-context";
import type { CandidateInterviewContext, StudioContext } from "./interview-service-contracts";
import { normalizeScore } from "./interview-service-normalizers";
import { buildStudioPromptContext } from "./ai/prompt-context-entities";
import {
  buildCandidatePromptContext,
  buildInterviewerPersona,
  buildInterviewJobPromptContext,
} from "./interview-service-prompt-context";
import { parseStringArray, safeParseJSON } from "./interview-service-value-parsers";

function fallbackResponseScore(transcript: string): number {
  const normalizedTranscript = transcript.trim().toLowerCase();
  const base = Math.min(
    COUNT_NINETY,
    COUNT_TWENTY + Math.floor(normalizedTranscript.length / COUNT_SEVEN),
  );
  if (normalizedTranscript.length < PERCENT_HIGH) {
    return Math.max(COUNT_THIRTY_FIVE, base - COUNT_TWENTY_FIVE);
  }
  if (normalizedTranscript.includes("example") || normalizedTranscript.includes("result")) {
    return base + COUNT_TWELVE;
  }
  if (normalizedTranscript.includes("metric") || normalizedTranscript.includes("kpi")) {
    return base + COUNT_EIGHT;
  }
  return base;
}

function fallbackResponseFeedback(
  transcript: string,
): NonNullable<InterviewResponse["aiAnalysis"]> {
  return {
    score: fallbackResponseScore(transcript),
    feedback:
      transcript.length >= COUNT_ONE_FORTY
        ? "Response shows useful depth and relevant structure."
        : "Add measurable outcomes and a clearer step-by-step breakdown.",
    strengths: ["Clear attempt to answer the asked question.", "Shows structured thinking."],
    improvements:
      transcript.length < COUNT_ONE_FORTY
        ? ["Add specific examples and impact metrics."]
        : ["Keep responses concise and concrete."],
    source: "heuristic",
  };
}

function buildResponseFeedbackPrompt(input: {
  studio: StudioContext;
  config: InterviewConfig;
  candidateContext: CandidateInterviewContext;
  question: InterviewQuestion;
  responseText: string;
  priorResponses: InterviewResponse[];
}): string {
  const { studio, config, candidateContext, question, responseText, priorResponses } = input;
  const persona = buildInterviewerPersona(studio, config);

  return `${interviewPersonaPrompt({
    role: config.targetJob?.title || config.roleType,
    company: config.targetJob?.company || studio.name,
    personality: persona.name,
    interviewStyle: studio.interviewStyle,
    focusAreas: config.focusAreas,
  })}

Interview mode: ${config.interviewMode || "studio"}
Conversation style: ${candidateContext.conversationStyle}
${buildStudioPromptContext(studio)}
${buildInterviewJobPromptContext(config)}
${buildCandidatePromptContext(candidateContext)}

Prior answers:
${priorResponses.length > 0 ? priorResponses.map((response) => `- ${response.questionId}: ${response.transcript}`).join("\n") : "- None yet"}

Question asked:
${question.question}

Candidate response:
${responseText}

Return strict JSON only:
{
  "score": 0-100,
  "feedback": "One paragraph feedback",
  "strengths": ["..."],
  "improvements": ["..."]
}
Use the existing structure as baseline:
${interviewFeedbackPrompt(question.question, responseText)}
`;
}

function normalizeQuestionFeedback(
  raw: JsonValue | null,
  attribution: { provider: string; model: string },
): NonNullable<InterviewResponse["aiAnalysis"]> | null {
  if (!isRecord(raw)) {
    return null;
  }

  let parsedScore = Number.NaN;
  if (typeof raw.score === "number") {
    parsedScore = raw.score;
  } else if (typeof raw.score === "string") {
    parsedScore = Number.parseInt(raw.score, 10);
  }
  if (!Number.isFinite(parsedScore)) {
    return null;
  }

  return {
    score: normalizeScore(parsedScore),
    feedback: typeof raw.feedback === "string" && raw.feedback.trim() ? raw.feedback.trim() : "",
    strengths: parseStringArray(raw.strengths),
    improvements: parseStringArray(raw.improvements),
    source: "ai",
    // Attribution travels with the assessment so the UI can name the provider
    // and model that produced it rather than asserting an unsourced "AI" badge.
    provider: attribution.provider,
    model: attribution.model,
  };
}

export async function generateResponseFeedback(
  session: { config: InterviewConfig; responses: InterviewResponse[] },
  studio: StudioContext,
  question: InterviewQuestion,
  transcript: string,
): Promise<NonNullable<InterviewResponse["aiAnalysis"]>> {
  if (transcript.trim().length === 0) {
    return {
      score: 0,
      feedback: "Response is empty and cannot be assessed.",
      strengths: [],
      improvements: ["Provide a complete and structured response."],
      source: "heuristic",
    };
  }

  const candidateContext = await resolveCandidateInterviewContext(session.config);
  const prompt = buildResponseFeedbackPrompt({
    studio,
    config: session.config,
    candidateContext,
    question,
    responseText: transcript,
    priorResponses: session.responses,
  });
  const aiServiceResult = await settle(createAIService());
  if (aiServiceResult.status === "rejected") {
    return fallbackResponseFeedback(transcript);
  }

  // A timeout resolves to null; there is no provider response to attribute, so
  // the heuristic fallback owns the assessment rather than a fabricated record.
  const response = await withAiOperationTimeout(() =>
    aiServiceResult.value.generate(prompt, {
      purpose: "interviewFeedback",
      temperature: AI_DEFAULT_TEMPERATURE_INTERVIEW,
      maxTokens: AI_MAX_TOKENS_FEEDBACK,
    }),
  );

  if (!response || response.error) {
    return fallbackResponseFeedback(transcript);
  }

  const parsedPayload = safeParseJSON(response.content) ?? {
    score: Number.NaN,
    feedback: "",
    strengths: [],
    improvements: [],
  };
  const parsed = normalizeQuestionFeedback(parsedPayload, {
    provider: response.provider,
    model: response.model,
  });
  if (!parsed) {
    return fallbackResponseFeedback(transcript);
  }
  if (parsed.feedback === "") {
    parsed.feedback = "Good response with room for greater specificity.";
  }

  return parsed;
}

import type { InterviewSession } from "@bao/shared/types/interview";
import { resolveStudioContext } from "./interview-service-context";
import type { DBInterviewSession } from "./interview-service-contracts";
import {
  normalizeFinalAnalysis,
  normalizeInterviewSessionStatus,
  normalizeQuestions,
  normalizeResponses,
  normalizeSessionConfig,
} from "./interview-service-normalizers";
import { buildInterviewerPersona } from "./interview-service-prompt-context";

export async function toInterviewSessionFromRow(row: DBInterviewSession): Promise<InterviewSession> {
  const config = normalizeSessionConfig(row);
  const studio = await resolveStudioContext(row.studioId);
  const questions = normalizeQuestions(row.questions);
  const responses = normalizeResponses(row.responses);
  const finalAnalysis = normalizeFinalAnalysis(row.finalAnalysis);

  return {
    id: row.id,
    studioId: row.studioId,
    config,
    questions,
    currentQuestionIndex: Math.min(responses.length, questions.length),
    totalQuestions: questions.length,
    startTime: row.startTime || Date.now(),
    status: normalizeInterviewSessionStatus(row.status),
    responses,
    interviewerPersona: buildInterviewerPersona(studio, config),
    ...(row.endTime ? { endTime: row.endTime } : {}),
    ...(finalAnalysis ? { finalAnalysis } : {}),
  };
}

import { COUNT_THREE } from "@bao/shared/constants/numeric";
import type { InterviewSession } from "@bao/shared/types/interview";

export function calculateInterviewStats(sessions: InterviewSession[]): {
  totalInterviews: number;
  completedInterviews: number;
  averageScore: number;
  strongestAreas: string[];
  improvementAreas: string[];
  totalTimeSpent: number;
  favoriteStudios: string[];
} {
  const totalInterviews = sessions.length;
  const completedInterviews = sessions.filter((session) => session.status === "completed").length;
  const completedWithScore = sessions.filter(
    (session) => session.status === "completed" && session.finalAnalysis,
  );
  const averageScore =
    completedWithScore.length > 0
      ? Math.round(
          completedWithScore.reduce(
            (accumulator, session) => accumulator + (session.finalAnalysis?.overallScore || 0),
            0,
          ) / completedWithScore.length,
        )
      : 0;

  const strongestAreas = [
    ...new Set(sessions.flatMap((session) => session.finalAnalysis?.strengths || [])),
  ].slice(0, COUNT_THREE);
  const improvementAreas = [
    ...new Set(sessions.flatMap((session) => session.finalAnalysis?.improvements || [])),
  ].slice(0, COUNT_THREE);
  const totalTimeSpent = sessions.reduce((accumulator, session) => {
    if (session.startTime && session.endTime) {
      return accumulator + (session.endTime - session.startTime);
    }
    return accumulator;
  }, 0);
  const studioCounts = new Map<string, number>();
  for (const session of sessions) {
    studioCounts.set(session.studioId, (studioCounts.get(session.studioId) ?? 0) + 1);
  }
  const favoriteStudios = [...studioCounts.entries()]
    .sort((left, right) => right[1] - left[1])
    .slice(0, COUNT_THREE)
    .map(([studioId]) => studioId);

  return {
    totalInterviews,
    completedInterviews,
    averageScore,
    strongestAreas,
    improvementAreas,
    totalTimeSpent,
    favoriteStudios,
  };
}

import { DECIMAL_RADIX } from "@bao/shared/constants/client-config";
import { type JsonValue, safeParseJson } from "@bao/shared/utils/json";

const JSON_CODE_FENCE_PATTERN = /```(?:json)?\s*([\s\S]*?)```/i;
const JSON_ARRAY_PATTERN = /\[[\s\S]*\]/;
const JSON_OBJECT_PATTERN = /\{[\s\S]*\}/;

export const toPersistedRecord = (value: object): Record<string, unknown> => {
  const record: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(value)) {
    record[key] = entry;
  }
  return record;
};

export function parseNumber(value: unknown, fallback: number, min: number, max: number): number {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(min, Math.min(Math.floor(value), max));
  }

  if (typeof value === "string") {
    const parsed = Number.parseInt(value, DECIMAL_RADIX);
    if (Number.isFinite(parsed)) {
      return Math.max(min, Math.min(parsed, max));
    }
  }

  return fallback;
}

export function parseBoolean(value: unknown, fallback: boolean): boolean {
  if (typeof value === "boolean") {
    return value;
  }
  if (typeof value === "string") {
    if (value.toLowerCase() === "true") {
      return true;
    }
    if (value.toLowerCase() === "false") {
      return false;
    }
  }
  return fallback;
}

export function parseString(value: unknown, fallback: string): string {
  return typeof value === "string" && value.trim() ? value.trim() : fallback;
}

export function parseStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return [];
  }
  const strings = value.filter(
    (entry): entry is string => typeof entry === "string" && entry.trim().length > 0,
  );
  return strings.map((entry) => entry.trim());
}

export function extractJSON(text: string): string {
  const codeFenceMatch = text.match(JSON_CODE_FENCE_PATTERN);
  if (codeFenceMatch?.[1]) {
    return codeFenceMatch[1].trim();
  }

  const arrayMatch = text.match(JSON_ARRAY_PATTERN);
  if (arrayMatch) {
    return arrayMatch[0];
  }

  const objectMatch = text.match(JSON_OBJECT_PATTERN);
  if (objectMatch) {
    return objectMatch[0];
  }

  return text.trim();
}

/**
 * Parses a model-authored payload (optionally fenced) into a typed JSON value.
 * Returns null when the payload is not parseable JSON.
 */
export function safeParseJSON(payload: string): JsonValue | null {
  return safeParseJson(extractJSON(payload));
}

import { RATIO_FOUR_FIFTHS } from "@bao/shared/constants/numeric";
import type {
  InterviewQuestion,
  InterviewResponse,
  InterviewSession,
} from "@bao/shared/types/interview";
import { generateId } from "@bao/shared/utils/validation";
import { desc, eq } from "drizzle-orm";
import { db } from "../db/client";
import { interviewSessions } from "../db/schema/interviews";
import { normalizeConfig } from "./interview-service-config-normalizers";
import { resolveStudioContext } from "./interview-service-context";
import type { InterviewConfigInput } from "./interview-service-contracts";
import { generateFinalAnalysis } from "./interview-service-final-analysis";
import { generateNextNaturalQuestion, generateQuestions } from "./interview-service-questions";
import { generateResponseFeedback } from "./interview-service-response-feedback";
import { toInterviewSessionFromRow } from "./interview-service-session-mapper";
import { calculateInterviewStats } from "./interview-service-stats";
import { toPersistedRecord } from "./interview-service-value-parsers";

export class InterviewService {
  async startSession(
    studioId: string,
    rawConfig?: InterviewConfigInput,
  ): Promise<InterviewSession> {
    const config = normalizeConfig(rawConfig || {});
    const studio = await resolveStudioContext(studioId);
    const questionSet = await generateQuestions(config, studio);

    const id = generateId();
    const now = Date.now();
    const nowIso = new Date(now).toISOString();
    const persistedConfig = toPersistedRecord(config);

    await db.insert(interviewSessions).values({
      id,
      studioId: studio.id,
      config: persistedConfig,
      questions: questionSet,
      responses: [],
      finalAnalysis: null,
      status: "active",
      startTime: now,
      endTime: null,
      createdAt: nowIso,
      updatedAt: nowIso,
    });

    return toInterviewSessionFromRow({
      id,
      studioId: studio.id,
      config: persistedConfig,
      questions: questionSet,
      responses: [],
      finalAnalysis: null,
      status: "active",
      startTime: now,
      endTime: null,
      createdAt: nowIso,
      updatedAt: nowIso,
    });
  }

  async getSessions(): Promise<InterviewSession[]> {
    const sessions = await db
      .select()
      .from(interviewSessions)
      .orderBy(desc(interviewSessions.createdAt));
    return Promise.all(sessions.map((session) => toInterviewSessionFromRow(session)));
  }

  async getSession(id: string): Promise<InterviewSession | null> {
    const rows = await db.select().from(interviewSessions).where(eq(interviewSessions.id, id));
    const row = rows[0];
    return row ? toInterviewSessionFromRow(row) : null;
  }

  private selectQuestionForResponse(
    session: InterviewSession,
    response: InterviewResponse,
  ): InterviewQuestion | null {
    return (
      session.questions.find((entry) => entry.id === response.questionId) ??
      session.questions[session.currentQuestionIndex] ??
      session.questions[session.questions.length - 1] ??
      null
    );
  }

  private buildAnalyzedResponse(
    response: InterviewResponse,
    questionId: string,
    analysis: NonNullable<InterviewResponse["aiAnalysis"]>,
  ): InterviewResponse {
    return {
      ...response,
      questionId,
      duration: Math.max(1, response.duration),
      transcript: response.transcript.trim(),
      timestamp: response.timestamp || Date.now(),
      confidence: Math.max(0, Math.min(1, response.confidence || RATIO_FOUR_FIFTHS)),
      aiAnalysis: analysis,
    };
  }

  private async persistSessionResponses(options: {
    sessionId: string;
    responses: InterviewResponse[];
    questions: InterviewQuestion[];
    endTime: number | null;
    nowIso: string;
  }): Promise<InterviewSession["status"]> {
    const status: InterviewSession["status"] =
      options.responses.length >= options.questions.length ? "completed" : "active";

    await db
      .update(interviewSessions)
      .set({
        responses: options.responses,
        questions: options.questions,
        status,
        endTime: status === "completed" ? Date.now() : options.endTime,
        updatedAt: options.nowIso,
      })
      .where(eq(interviewSessions.id, options.sessionId));

    return status;
  }

  private async persistFinalAnalysis(sessionId: string, nowIso: string): Promise<void> {
    const finalized = await this.getSession(sessionId);
    if (!finalized) {
      return;
    }

    const studioContext = await resolveStudioContext(finalized.studioId);
    const finalAnalysis = await generateFinalAnalysis(finalized, studioContext);

    await db
      .update(interviewSessions)
      .set({
        finalAnalysis: toPersistedRecord(finalAnalysis),
        updatedAt: nowIso,
      })
      .where(eq(interviewSessions.id, sessionId));
  }

  async addResponse(
    sessionId: string,
    response: InterviewResponse,
  ): Promise<InterviewSession | null> {
    const session = await this.getSession(sessionId);
    if (!session || session.status === "completed") {
      return session;
    }

    const question = this.selectQuestionForResponse(session, response);
    if (!question) {
      return session;
    }

    const studioContext = await resolveStudioContext(session.studioId);
    const analysis = await generateResponseFeedback(
      session,
      studioContext,
      question,
      response.transcript,
    );
    const nowIso = new Date().toISOString();
    const responseWithAnalysis = this.buildAnalyzedResponse(response, question.id, analysis);
    const responses = [...session.responses, responseWithAnalysis];
    const shouldGenerateFollowUp =
      session.config.conversationStyle === "natural" &&
      responses.length < session.config.questionCount;
    const followUpQuestion = shouldGenerateFollowUp
      ? await generateNextNaturalQuestion(session, studioContext, responseWithAnalysis, question)
      : null;
    const questions =
      followUpQuestion && !session.questions.some((entry) => entry.id === followUpQuestion.id)
        ? [...session.questions, followUpQuestion]
        : session.questions;
    const status = await this.persistSessionResponses({
      sessionId,
      responses,
      questions,
      endTime: session.endTime ?? null,
      nowIso,
    });

    if (status === "completed") {
      await this.persistFinalAnalysis(sessionId, nowIso);
    }

    return this.getSession(sessionId);
  }

  async completeSession(id: string): Promise<InterviewSession | null> {
    const session = await this.getSession(id);
    if (!session) {
      return null;
    }
    if (session.status === "completed") {
      return session;
    }

    const studioContext = await resolveStudioContext(session.studioId);
    const finalAnalysis = await generateFinalAnalysis(session, studioContext);
    const now = new Date().toISOString();

    await db
      .update(interviewSessions)
      .set({
        status: "completed",
        endTime: Date.now(),
        finalAnalysis: toPersistedRecord(finalAnalysis),
        updatedAt: now,
      })
      .where(eq(interviewSessions.id, id));

    return this.getSession(id);
  }

  async getStats(): Promise<{
    totalInterviews: number;
    completedInterviews: number;
    averageScore: number;
    strongestAreas: string[];
    improvementAreas: string[];
    totalTimeSpent: number;
    favoriteStudios: string[];
  }> {
    return calculateInterviewStats(await this.getSessions());
  }
}

export const interviewService = new InterviewService();

/**
 * Job deduplication service
 * Uses content-based hashing to identify duplicate job postings
 */

import type { RawJob } from "./providers/provider-interface";

/**
 * Generate a content hash for a job posting
 * Uses title + company + location to create a unique identifier
 */
export function generateContentHash(
  job: RawJob | { title: string; company: string; location: string },
): string {
  // Normalize the content for consistent hashing
  const normalizedTitle = job.title.toLowerCase().trim().replace(/\s+/g, " ");
  const normalizedCompany = job.company.toLowerCase().trim().replace(/\s+/g, " ");
  const normalizedLocation = job.location.toLowerCase().trim().replace(/\s+/g, " ");

  const content = `${normalizedTitle}|${normalizedCompany}|${normalizedLocation}`;

  // Use Bun's native crypto hasher
  const hasher = new Bun.CryptoHasher("sha256");
  hasher.update(content);

  return hasher.digest("hex");
}

/**
 * Remove duplicate jobs based on content hash
 * Keeps the first occurrence of each unique job
 */
export function deduplicateJobs<T extends RawJob>(jobs: T[]): T[] {
  const seen = new Set<string>();
  const unique: T[] = [];

  for (const job of jobs) {
    const hash = generateContentHash(job);

    if (!seen.has(hash)) {
      seen.add(hash);
      unique.push(job);
    }
  }

  return unique;
}

