      job: jobs,
    })
    .from(applications)
    .innerJoin(jobs, eq(applications.jobId, jobs.id))
    .orderBy(desc(applications.appliedDate));

  return result.map((row) => ({
    ...row.application,
    job: dbRowToJob(row.job),
  }));
};

export const updateApplicationStatus = async (
  applicationId: string,
  status: string,
  note?: string,
): Promise<void> => {
  const app = await db
    .select()
    .from(applications)
    .where(eq(applications.id, applicationId))
    .limit(1);

  if (app.length === 0) {
    throw new Error(API_ERROR_APPLICATION_NOT_FOUND);
  }

  const timeline = app[0].timeline || [];
  const normalizedStatus = status.trim() || "applied";
  timeline.push({
    id: crypto.randomUUID(),
    type: normalizedStatus,
    date: new Date().toISOString(),
    description: note || `Status changed to ${normalizedStatus}`,
  });

  await db
    .update(applications)
    .set({
      status,
      timeline,
      updatedAt: new Date().toISOString(),
    })
    .where(eq(applications.id, applicationId));
};

import { DECIMAL_RADIX } from "@bao/shared/constants/client-config";
import { JOB_SALARY_PARSE_MULTIPLIER } from "@bao/shared/constants/jobs";
import { MS_PER_DAY } from "@bao/shared/constants/time";
import type { GameGenre, Job, JobFilters, Platform } from "@bao/shared/types/jobs";
import { eq, gte, inArray, like, type SQLWrapper, sql } from "drizzle-orm";
import { jobs } from "../../db/schema/jobs";

const SALARY_NUMBER_PATTERN = /\d+/g;

const extractSalaryBounds = (
  salary: Job["salary"],
): {
  min: number | undefined;
  max: number | undefined;
} => {
  if (!salary) {
    return { min: undefined, max: undefined };
  }

  if (typeof salary === "string") {
    const numbers = salary.match(SALARY_NUMBER_PATTERN);
    if (!numbers) {
      return { min: undefined, max: undefined };
    }

    const min = Number.parseInt(numbers[0], DECIMAL_RADIX) * JOB_SALARY_PARSE_MULTIPLIER;
    const max =
      numbers.length > 1
        ? Number.parseInt(numbers[1], DECIMAL_RADIX) * JOB_SALARY_PARSE_MULTIPLIER
        : min;
    return { min, max };
  }

  return {
    min: salary.min,
    max: salary.max,
  };
};

const applyTechnologyFilter = (allJobs: Job[], technologies: string[] | undefined): Job[] => {
  if (!(technologies && technologies.length > 0)) {
    return allJobs;
  }

  return allJobs.filter((job) => {
    if (!job.technologies) {
      return false;
    }
    const jobTechs = job.technologies.map((technology) => technology.toLowerCase());
    return technologies.some((technology) => jobTechs.includes(technology.toLowerCase()));
  });
};

const applyGenreFilter = (allJobs: Job[], gameGenres: GameGenre[] | undefined): Job[] => {
  if (!(gameGenres && gameGenres.length > 0)) {
    return allJobs;
  }

  return allJobs.filter(
    (job) => Boolean(job.gameGenres) && gameGenres.some((genre) => job.gameGenres?.includes(genre)),
  );
};

const applyPlatformFilter = (allJobs: Job[], platforms: Platform[] | undefined): Job[] => {
  if (!(platforms && platforms.length > 0)) {
    return allJobs;
  }

  return allJobs.filter(
    (job) =>
      Boolean(job.platforms) && platforms.some((platform) => job.platforms?.includes(platform)),
  );
};

const applySalaryFilter = (
  allJobs: Job[],
  salaryMin: number | undefined,
  salaryMax: number | undefined,
): Job[] => {
  if (!(salaryMin || salaryMax)) {
    return allJobs;
  }

  return allJobs.filter((job) => {
    const bounds = extractSalaryBounds(job.salary);
    if (!(bounds.min && bounds.max)) {
      return false;
    }
    if (salaryMin && bounds.max < salaryMin) {
      return false;
    }
    if (salaryMax && bounds.min > salaryMax) {
      return false;
    }
    return true;
  });
};

export const buildSearchConditions = (filters: JobFilters): SQLWrapper[] => {
  const conditions: SQLWrapper[] = [];

  if (filters.query) {
    const searchPattern = `%${filters.query}%`;
    conditions.push(
      sql`(
        ${jobs.title} LIKE ${searchPattern} OR
        ${jobs.company} LIKE ${searchPattern} OR
        ${jobs.description} LIKE ${searchPattern}
      )`,
    );
  }

  if (filters.company) {
    conditions.push(like(jobs.company, `%${filters.company}%`));
  }
  if (filters.location) {
    conditions.push(like(jobs.location, `%${filters.location}%`));
  }
  if (filters.remote !== undefined) {
    conditions.push(eq(jobs.remote, filters.remote));
  }
  if (filters.hybrid !== undefined) {
    conditions.push(eq(jobs.hybrid, filters.hybrid));
  }
  if (filters.experienceLevel) {
    conditions.push(eq(jobs.experienceLevel, filters.experienceLevel));
  }
  if (filters.jobType) {
    conditions.push(eq(jobs.type, filters.jobType));
  }
  if (filters.studioTypes && filters.studioTypes.length > 0) {
    conditions.push(inArray(jobs.studioType, filters.studioTypes));
  }
  if (filters.postedWithin) {
    const cutoffDate = new Date(Date.now() - filters.postedWithin * MS_PER_DAY);
    conditions.push(gte(jobs.postedDate, cutoffDate.toISOString()));
  }

  return conditions;
};

export const applyPostFilters = (allJobs: Job[], filters: JobFilters): Job[] => {
  let filtered = applyTechnologyFilter(allJobs, filters.technologies);
  filtered = applyGenreFilter(filtered, filters.gameGenres);
  filtered = applyPlatformFilter(filtered, filters.platforms);
  filtered = applySalaryFilter(filtered, filters.salaryMin, filters.salaryMax);

  const minMatchScore = filters.minMatchScore;
  if (minMatchScore !== undefined) {
    filtered = filtered.filter(
      (job) => job.matchScore !== undefined && job.matchScore >= minMatchScore,
    );
  }

  if (filters.featured !== undefined) {
    filtered = filtered.filter((job) => job.featured === filters.featured);
  }

  return filtered;
};

import type { Job, SalaryRange } from "@bao/shared/types/jobs";
import { normalizeJobType } from "@bao/shared/utils/job-normalizers";
import type { jobs } from "../../db/schema/jobs";
import { generateContentHash } from "./deduplication";
import {
  detectExperienceLevel,
  detectHybrid,
  detectJobType,
  detectRemote,
  detectStudioType,
  extractGenres,
  extractPlatforms,
  extractRequirements,
  extractTechnologies,
  generateTags,
  normalizeExperienceLevel,
  normalizeGameGenres,
  normalizePlatforms,
  normalizeStudioType,
} from "./job-aggregator-taxonomy";
import type { RawJob } from "./providers/provider-interface";

const normalizeSalary = (value: Record<string, unknown> | null): Job["salary"] | undefined => {
  if (!value) {
    return;
  }

  if (typeof value.label === "string" && value.label.trim().length > 0) {
    return value.label;
  }

  const min = typeof value.min === "number" ? value.min : undefined;
  const max = typeof value.max === "number" ? value.max : undefined;
  if (min !== undefined && max !== undefined) {
    const normalized: SalaryRange = {
      min,
      max,
      currency: typeof value.currency === "string" ? value.currency : undefined,
      frequency:
        value.frequency === "yearly" ||
        value.frequency === "monthly" ||
        value.frequency === "hourly"
          ? value.frequency
          : undefined,
    };
    return normalized;
  }
};

const applyOptionalRowFields = (job: Job, row: typeof jobs.$inferSelect): Job => ({
  ...job,
  hybrid: row.hybrid ?? undefined,
  requirements: Array.isArray(row.requirements) ? row.requirements : undefined,
  technologies: Array.isArray(row.technologies) ? row.technologies : undefined,
  experienceLevel: normalizeExperienceLevel(row.experienceLevel),
  url: row.url ?? undefined,
  source: row.source ?? undefined,
  contentHash: row.contentHash ?? undefined,
  tags: Array.isArray(row.tags) ? row.tags : undefined,
  companyLogo: row.companyLogo ?? undefined,
  applicationUrl: row.applicationUrl ?? undefined,
});

export const rawJobToInsert = async (raw: RawJob): Promise<typeof jobs.$inferInsert> => {
  const contentHash = generateContentHash(raw);
  const applyUrl = typeof raw.applyUrl === "string" && raw.applyUrl.trim() ? raw.applyUrl : null;
  const [remote, hybrid, requirements, technologies, studioType, gameGenres, platforms, tags] =
    await Promise.all([
      detectRemote(raw.location),
      detectHybrid(raw.location),
      extractRequirements(raw.description),
      extractTechnologies(raw.description),
      detectStudioType(raw.company),
      extractGenres(raw.description),
      extractPlatforms(raw.description),
      generateTags(raw),
    ]);

  return {
    id: crypto.randomUUID(),
    title: raw.title,
    company: raw.company,
    location: raw.location,
    remote,
    hybrid,
    description: raw.description || "",
    requirements,
    technologies,
    experienceLevel: detectExperienceLevel(raw.title),
    type: detectJobType(raw.title),
    postedDate: raw.postedDate || new Date().toISOString(),
    url: raw.url,
    source: raw.source || "unknown",
    contentHash,
    studioType,
    gameGenres,
    platforms,
    tags,
    applicationUrl: applyUrl || raw.url,
  };
};

export const dbRowToJob = (row: typeof jobs.$inferSelect): Job => {
  const baseJob: Job = {
    id: row.id,
    title: row.title,
    company: row.company,
    location: row.location,
    remote: row.remote ?? false,
    salary: normalizeSalary(row.salary),
    description: row.description ?? "",
    type: normalizeJobType(row.type),
    postedDate: row.postedDate || new Date().toISOString(),
    studioType: normalizeStudioType(row.studioType),
    gameGenres: normalizeGameGenres(row.gameGenres),
    platforms: normalizePlatforms(row.platforms),
  };

  return applyOptionalRowFields(baseJob, row);
};

import { desc } from "drizzle-orm";
import { db } from "../../db/client";
import { jobs } from "../../db/schema/jobs";

export const needsRefresh = async (cacheExpiry: number): Promise<boolean> => {
  const result = await db
    .select({ updatedAt: jobs.updatedAt })
    .from(jobs)
    .orderBy(desc(jobs.updatedAt))
    .limit(1);

  if (result.length === 0) {
    return true;
  }

  const lastUpdate = new Date(result[0].updatedAt).getTime();
  return Date.now() - lastUpdate > cacheExpiry;
};

export const getJobStats = async (): Promise<{
  total: number;
  bySource: Record<string, number>;
  byExperienceLevel: Record<string, number>;
  remoteCount: number;
  lastUpdated: string | null;
}> => {
  const allJobs = await db.select().from(jobs);
  const bySource: Record<string, number> = {};
  const byExperienceLevel: Record<string, number> = {};
  let remoteCount = 0;

  for (const job of allJobs) {
    const source = job.source || "Unknown";
    bySource[source] = (bySource[source] || 0) + 1;

    if (job.experienceLevel) {
      byExperienceLevel[job.experienceLevel] = (byExperienceLevel[job.experienceLevel] || 0) + 1;
    }

    if (job.remote) {
      remoteCount += 1;
    }
  }

  const lastUpdated =
    allJobs.length > 0
      ? allJobs.reduce(
          (latest, job) => (new Date(job.updatedAt) > new Date(latest) ? job.updatedAt : latest),
          allJobs[0].updatedAt,
        )
      : null;

  return {
    total: allJobs.length,
    bySource,
    byExperienceLevel,
    remoteCount,
    lastUpdated,
  };
};

import {
  JOB_EXPERIENCE_LEVELS,
  JOB_GAME_GENRES,
  JOB_STUDIO_TYPES,
  JOB_SUPPORTED_PLATFORMS,
} from "@bao/shared/constants/jobs";
import type {
  GameGenre,
  JobExperienceLevel,
  JobType,
  Platform,
  StudioType,
} from "@bao/shared/types/jobs";
import type {
  JobTaxonomyKeywordCategory,
  JobTaxonomyKeywordEntry,
} from "@bao/shared/types/jobs-taxonomy";
import { getJobTaxonomy } from "./job-taxonomy-service";
import type { RawJob } from "./providers/provider-interface";

const isOneOf = <T extends string>(values: readonly T[], value: unknown): value is T => {
  if (typeof value !== "string") {
    return false;
  }
  return values.some((entry) => entry === value);
};

const readCategoryEntries = async (
  category: JobTaxonomyKeywordCategory,
): Promise<JobTaxonomyKeywordEntry[]> => {
  const taxonomy = await getJobTaxonomy();
  return taxonomy.keywords
    .filter((entry) => entry.enabled && entry.category === category)
    .sort((left, right) => left.sortOrder - right.sortOrder);
};

const matchesKeyword = (haystack: string, entry: JobTaxonomyKeywordEntry): boolean => {
  const candidates = [entry.label, ...entry.synonyms];
  return candidates.some((candidate) => haystack.includes(candidate.toLowerCase()));
};

const extractCategoryLabels = async (
  category: JobTaxonomyKeywordCategory,
  description?: string,
): Promise<string[]> => {
  if (!description) {
    return [];
  }

  const entries = await readCategoryEntries(category);
  const descLower = description.toLowerCase();
  return entries.filter((entry) => matchesKeyword(descLower, entry)).map((entry) => entry.label);
};

export const detectRemote = async (location: string): Promise<boolean> => {
  const locationLower = location.toLowerCase();
  const entries = await readCategoryEntries("remote-location");
  return entries.some((entry) => matchesKeyword(locationLower, entry));
};

export const detectHybrid = async (location: string): Promise<boolean> => {
  const locationLower = location.toLowerCase();
  const entries = await readCategoryEntries("hybrid-location");
  return entries.some((entry) => matchesKeyword(locationLower, entry));
};

export const normalizeStudioType = (value: string | null): StudioType | undefined => {
  if (!isOneOf(JOB_STUDIO_TYPES, value)) {
    return;
  }
  return value;
};

export const normalizeGameGenres = (value: string[] | null): GameGenre[] | undefined => {
  if (!Array.isArray(value)) {
    return;
  }
  return value.filter((genre): genre is GameGenre => isOneOf(JOB_GAME_GENRES, genre));
};

export const normalizePlatforms = (value: string[] | null): Platform[] | undefined => {
  if (!Array.isArray(value)) {
    return;
  }
  return value.filter((platform): platform is Platform =>
    isOneOf(JOB_SUPPORTED_PLATFORMS, platform),
  );
};

export const normalizeExperienceLevel = (value: string | null): JobExperienceLevel | undefined => {
  if (!isOneOf(JOB_EXPERIENCE_LEVELS, value)) {
    return;
  }
  return value;
};

export const detectExperienceLevel = (title: string): JobExperienceLevel | undefined => {
  const titleLower = title.toLowerCase();

  if (titleLower.includes("director") || titleLower.includes("vp")) return "director";
  if (titleLower.includes("principal") || titleLower.includes("staff")) return "principal";
  if (titleLower.includes("senior") || titleLower.includes("sr")) return "senior";
  if (titleLower.includes("mid") || titleLower.includes("intermediate")) return "mid";
  if (titleLower.includes("junior") || titleLower.includes("jr")) return "junior";
  if (titleLower.includes("entry") || titleLower.includes("intern")) return "entry";
};

export const detectJobType = (title: string): JobType => {
  const titleLower = title.toLowerCase();

  if (titleLower.includes("contract") || titleLower.includes("contractor")) return "contract";
  if (titleLower.includes("intern") || titleLower.includes("internship")) return "internship";
  if (titleLower.includes("part-time") || titleLower.includes("part time")) return "part-time";
  if (titleLower.includes("freelance")) return "freelance";

  return "full-time";
};

export const detectStudioType = async (company: string): Promise<StudioType> => {
  const companyLower = company.toLowerCase();
  const taxonomy = await getJobTaxonomy();
  const match = taxonomy.studioRules
    .filter((rule) => rule.enabled)
    .sort((left, right) => left.sortOrder - right.sortOrder)
    .find((rule) => companyLower.includes(rule.keyword.toLowerCase()));

  return match?.studioType ?? "Indie";
};

export const extractRequirements = async (description?: string): Promise<string[]> =>
  extractCategoryLabels("requirement", description);

export const extractTechnologies = async (description?: string): Promise<string[]> =>
  extractCategoryLabels("technology", description);

export const extractGenres = async (description?: string): Promise<string[]> =>
  extractCategoryLabels("genre", description);

export const extractPlatforms = async (description?: string): Promise<string[]> =>
  extractCategoryLabels("platform", description);

export const generateTags = async (raw: RawJob): Promise<string[]> => {
  const tags: string[] = [];

  if (await detectRemote(raw.location)) {
    tags.push("Remote");
  }
  if (await detectHybrid(raw.location)) {
    tags.push("Hybrid");
  }

  const description = raw.description?.toLowerCase() || "";
  if (description.includes("senior")) {
    tags.push("Senior");
  }
  if (description.includes("junior")) {
    tags.push("Junior");
  }
  if (description.includes("lead")) {
    tags.push("Leadership");
  }

  return tags;
};

/**
 * Job Aggregator Service
 * Orchestrates job fetching, caching, and searching across multiple providers.
 */

import {
  JOB_AGGREGATOR_CACHE_EXPIRY_MS,
  JOB_QUERY_DEFAULT_LIMIT,
  JOB_QUERY_DEFAULT_PAGE,
} from "@bao/shared/constants/jobs";
import type { Job, JobFilters, JobSearchResult } from "@bao/shared/types/jobs";
import { and, desc, eq } from "drizzle-orm";
import { db } from "../../db/client";
import type { applications } from "../../db/schema/jobs";
import { jobs, savedJobs } from "../../db/schema/jobs";
import { createServerLogger } from "../../utils/logger";
import { deduplicateJobs } from "./deduplication";
import {
  applyToJob,
  getApplications,
  updateApplicationStatus,
} from "./job-aggregator-applications";
import { applyPostFilters, buildSearchConditions } from "./job-aggregator-filters";
import { dbRowToJob, rawJobToInsert } from "./job-aggregator-mappers";
import { getJobStats, needsRefresh } from "./job-aggregator-stats";
import { CompanyBoardsProvider } from "./providers/company-board";
import {
  gamesJobsDirectProvider,
  grackleProvider,
  hitmarkerPortalProvider,
  pocketGamerProvider,
  remoteGameJobsProvider,
  workWithIndiesProvider,
} from "./providers/gaming-providers";
import { GreenhouseProvider } from "./providers/greenhouse";
import { LeverProvider } from "./providers/lever";
import type { JobProvider, RawJob } from "./providers/provider-interface";

export class JobAggregator {
  private readonly providers: JobProvider[];
  private readonly cacheExpiry: number;
  private readonly logger = createServerLogger("job-aggregator");

  constructor() {
    this.providers = [
      new GreenhouseProvider(),
      new LeverProvider(),
      hitmarkerPortalProvider,
      grackleProvider,
      workWithIndiesProvider,
      remoteGameJobsProvider,
      gamesJobsDirectProvider,
      pocketGamerProvider,
      new CompanyBoardsProvider(),
    ];
    this.cacheExpiry = JOB_AGGREGATOR_CACHE_EXPIRY_MS;
  }

  private async fetchProviderJobs(): Promise<RawJob[]> {
    const results = await Promise.allSettled(
      this.providers.map((provider) => provider.fetchJobs()),
    );

    return results.flatMap((result, index) => {
      const providerName = this.providers[index]?.name || "unknown-provider";
      if (result.status === "fulfilled") {
        this.logger.info(`${providerName}: fetched ${result.value.length} jobs`);
        return result.value;
      }
      this.logger.error(
        `${providerName}: failed`,
        result.reason instanceof Error ? result.reason.message : String(result.reason),
      );
      return [];
    });
  }

  private async saveOrUpdateJob(rawJob: RawJob): Promise<"new" | "updated" | "skipped"> {
    const job = await rawJobToInsert(rawJob);
    if (!job.contentHash) {
      return "skipped";
    }

    const existing = await db
      .select()
      .from(jobs)
      .where(eq(jobs.contentHash, job.contentHash))
      .limit(1);

    if (existing.length === 0) {
      await db.insert(jobs).values(job);
      return "new";
    }

    await db
      .update(jobs)
      .set({
        ...job,
        updatedAt: new Date().toISOString(),
      })
      .where(eq(jobs.id, existing[0].id));
    return "updated";
  }

  async refreshJobs(): Promise<{ total: number; new: number; updated: number }> {
    this.logger.info("Starting job refresh from all providers");

    const allRawJobs = await this.fetchProviderJobs();
    const uniqueJobs = deduplicateJobs(allRawJobs);
    this.logger.debug(`Deduplicated: ${allRawJobs.length} -> ${uniqueJobs.length} jobs`);

    let newCount = 0;
    let updatedCount = 0;
    const saveResults = await Promise.allSettled(
      uniqueJobs.map((rawJob) => this.saveOrUpdateJob(rawJob)),
    );

    for (const result of saveResults) {
      if (result.status === "fulfilled") {
        if (result.value === "new") {
          newCount += 1;
        }
        if (result.value === "updated") {
          updatedCount += 1;
        }
        continue;
      }
      this.logger.error(
        "Failed to save job:",
        result.reason instanceof Error ? result.reason.message : String(result.reason),
      );
    }

    this.logger.info(`Refresh complete: ${newCount} new, ${updatedCount} updated`);

    return {
      total: uniqueJobs.length,
      new: newCount,
      updated: updatedCount,
    };
  }

  async searchJobs(filters: JobFilters = {}): Promise<JobSearchResult> {
    const limit = filters.limit ?? JOB_QUERY_DEFAULT_LIMIT;
    const page = filters.page ?? JOB_QUERY_DEFAULT_PAGE;
    const conditions = buildSearchConditions(filters);
    const queryBuilder =
      conditions.length > 0
        ? db
            .select()
            .from(jobs)
            .where(and(...conditions))
        : db.select().from(jobs);
    const offset = (page - 1) * limit;
    const results = await queryBuilder.orderBy(desc(jobs.postedDate)).limit(limit).offset(offset);
    const jobResults = results.map((row) => dbRowToJob(row));
    const filteredJobs = applyPostFilters(jobResults, filters);

    return {
      jobs: filteredJobs,
      total: filteredJobs.length,
      page,
      limit,
      filters,
    };
  }

  async getJobById(id: string): Promise<Job | null> {
    const result = await db.select().from(jobs).where(eq(jobs.id, id)).limit(1);
    if (result.length === 0) {
      return null;
    }
    return dbRowToJob(result[0]);
  }

  async saveJob(jobId: string): Promise<void> {
    await db.insert(savedJobs).values({
      id: crypto.randomUUID(),
      jobId,
      savedAt: new Date().toISOString(),
    });
  }

  async getSavedJobs(): Promise<Job[]> {
    const result = await db
      .select({ job: jobs })
      .from(savedJobs)
      .innerJoin(jobs, eq(savedJobs.jobId, jobs.id))
      .orderBy(desc(savedJobs.savedAt));

    return result.map((row) => dbRowToJob(row.job));
  }

  async unsaveJob(jobId: string): Promise<void> {
    await db.delete(savedJobs).where(eq(savedJobs.jobId, jobId));
  }

  async applyToJob(jobId: string, notes?: string): Promise<string> {
    return applyToJob(jobId, notes);
  }

  async getApplications(): Promise<Array<typeof applications.$inferSelect & { job: Job }>> {
    return getApplications();
  }

  async updateApplicationStatus(
    applicationId: string,
    status: string,
    note?: string,
  ): Promise<void> {
    await updateApplicationStatus(applicationId, status, note);
  }

  async needsRefresh(): Promise<boolean> {
    return needsRefresh(this.cacheExpiry);
  }

  async getStats(): Promise<{
    total: number;
    bySource: Record<string, number>;
    byExperienceLevel: Record<string, number>;
    remoteCount: number;
    lastUpdated: string | null;
  }> {
    return getJobStats();
  }
}

