import {
  API_ERROR_SPEECH_SYNTHESIZE,
  API_ERROR_SPEECH_TTS_EMPTY_TEXT,
  API_ERROR_SPEECH_TTS_ENDPOINT_INVALID,
  API_ERROR_SPEECH_TTS_NOT_CONFIGURED,
} from "@bao/shared/constants/api-errors";
import { COUNT_FORTY_FOUR, COUNT_TWO_THOUSAND, RATIO_ONE } from "@bao/shared/constants/numeric";
import {
  DEFAULT_LOCAL_TTS_ENDPOINT,
  DEFAULT_LOCAL_TTS_VOICE,
  type SpeechProviderOption,
} from "@bao/shared/constants/settings";
import { validateLocalAiEndpoint } from "@bao/shared/utils/local-ai-endpoint";
import { settle } from "@bao/shared/utils/promise";
import { loadAutomationSettings } from "../automation/automation-settings-support";

const TRAILING_SLASH_PATTERN = /\/$/u;
const MAX_TTS_CHARS = COUNT_TWO_THOUSAND;

export type SpeechSynthesizeInput = {
  readonly text: string;
  readonly voice?: string;
};

export type SpeechSynthesizeResult =
  | {
      readonly ok: true;
      readonly audioBase64: string;
      readonly mimeType: "audio/wav";
      readonly provider: SpeechProviderOption;
      readonly model: string;
      readonly voice: string;
      readonly bytes: number;
    }
  | { readonly ok: false; readonly error: string; readonly status: 400 | 422 | 502 };

const resolveSpeechUrl = (
  endpoint: string,
): { readonly ok: true; readonly url: string } | { readonly ok: false; readonly error: string } => {
  const trimmed = endpoint.trim().length > 0 ? endpoint.trim() : DEFAULT_LOCAL_TTS_ENDPOINT;
  const validated = validateLocalAiEndpoint(trimmed);
  if (!validated.ok) {
    return { ok: false, error: API_ERROR_SPEECH_TTS_ENDPOINT_INVALID };
  }
  const base = validated.endpoint.replace(TRAILING_SLASH_PATTERN, "");
  const withV1 = base.endsWith("/v1") ? base : `${base}/v1`;
  return { ok: true, url: `${withV1}/audio/speech` };
};

const validateSynthesizeText = (
  text: string,
): SpeechSynthesizeResult | { readonly ok: true; readonly text: string } => {
  if (text.length === 0) {
    return { ok: false, error: API_ERROR_SPEECH_TTS_EMPTY_TEXT, status: 400 };
  }
  if (text.length > MAX_TTS_CHARS) {
    return { ok: false, error: API_ERROR_SPEECH_TTS_EMPTY_TEXT, status: 400 };
  }
  return { ok: true, text };
};

const parseRiffWavBytes = (
  bytes: Uint8Array,
): SpeechSynthesizeResult | { readonly ok: true; readonly bytes: Uint8Array } => {
  if (bytes.byteLength < COUNT_FORTY_FOUR) {
    return { ok: false, error: API_ERROR_SPEECH_SYNTHESIZE, status: 502 };
  }
  // RIFF header check — refuse empty/non-wav false greens
  const b0 = bytes[0];
  const b1 = bytes[1];
  const b2 = bytes[2];
  const b3 = bytes[3];
  if (b0 === undefined || b1 === undefined || b2 === undefined || b3 === undefined) {
    return { ok: false, error: API_ERROR_SPEECH_SYNTHESIZE, status: 502 };
  }
  const header = String.fromCharCode(b0, b1, b2, b3);
  if (header !== "RIFF") {
    return { ok: false, error: API_ERROR_SPEECH_SYNTHESIZE, status: 502 };
  }
  return { ok: true, bytes };
};

const fetchSynthesizeAudioBytes = async (input: {
  readonly url: string;
  readonly model: string;
  readonly text: string;
  readonly voice: string;
}): Promise<SpeechSynthesizeResult | { readonly ok: true; readonly bytes: Uint8Array }> => {
  const requestResult = await settle(
    fetch(input.url, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        model: input.model,
        input: input.text,
        voice: input.voice,
        response_format: "wav",
        speed: RATIO_ONE,
      }),
    }),
  );
  if (requestResult.status === "rejected" || !requestResult.value.ok) {
    return { ok: false, error: API_ERROR_SPEECH_SYNTHESIZE, status: 502 };
  }
  const bytesResult = await settle(requestResult.value.arrayBuffer());
  if (bytesResult.status === "rejected") {
    return { ok: false, error: API_ERROR_SPEECH_SYNTHESIZE, status: 502 };
  }
  return parseRiffWavBytes(new Uint8Array(bytesResult.value));
};

/**
 * Synthesize speech via local Kokoro OpenAI-compatible TTS (on-device neural).
 * Cloud OpenAI/HF TTS paths are intentionally not used.
 */
export const synthesizeSpeechAudio = async (
  input: SpeechSynthesizeInput,
): Promise<SpeechSynthesizeResult> => {
  const textResult = validateSynthesizeText(input.text.trim());
  if (!textResult.ok) {
    return textResult;
  }
  if (!("text" in textResult)) {
    return { ok: false, error: API_ERROR_SPEECH_SYNTHESIZE, status: 502 };
  }

  const automation = await loadAutomationSettings();
  const provider = automation.speech.tts.provider;
  if (provider !== "local" && provider !== "custom") {
    return { ok: false, error: API_ERROR_SPEECH_TTS_NOT_CONFIGURED, status: 422 };
  }

  const endpointResolved = resolveSpeechUrl(automation.speech.tts.endpoint);
  if (!endpointResolved.ok) {
    return { ok: false, error: endpointResolved.error, status: 422 };
  }

  const voice =
    (input.voice && input.voice.trim().length > 0
      ? input.voice.trim()
      : automation.speech.tts.voice.trim()) || DEFAULT_LOCAL_TTS_VOICE;
  const model = automation.speech.tts.model.trim() || "kokoro";

  const audioResult = await fetchSynthesizeAudioBytes({
    url: endpointResolved.url,
    model,
    text: textResult.text,
    voice,
  });
  if (!audioResult.ok) {
    return audioResult;
  }
  if (!("bytes" in audioResult) || !(audioResult.bytes instanceof Uint8Array)) {
    return { ok: false, error: API_ERROR_SPEECH_SYNTHESIZE, status: 502 };
  }

  return {
    ok: true,
    audioBase64: Buffer.from(audioResult.bytes).toString("base64"),
    mimeType: "audio/wav",
    provider,
    model,
    voice,
    bytes: audioResult.bytes.byteLength,
  };
};

import {
  API_ERROR_SPEECH_STT_ENDPOINT_INVALID,
  API_ERROR_SPEECH_STT_NOT_CONFIGURED,
  API_ERROR_SPEECH_TRANSCRIBE,
} from "@bao/shared/constants/api-errors";
import {
  BYTES_KILO,
  COUNT_EIGHT,
  COUNT_ONE_EIGHTY,
  MS_TWO_MINUTES,
} from "@bao/shared/constants/numeric";
import type { SpeechProviderOption } from "@bao/shared/constants/settings";
import { safeParseJson } from "@bao/shared/utils/json";
import { validateLocalAiEndpoint } from "@bao/shared/utils/local-ai-endpoint";
import { settle } from "@bao/shared/utils/promise";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { DEFAULT_SETTINGS_ID, settings } from "../../db/schema/settings";
import { decryptProviderKeys } from "../../utils/settings-decrypt";
import { loadAutomationSettings } from "../automation/automation-settings-support";

const MAX_AUDIO_BYTES = COUNT_EIGHT * BYTES_KILO * BYTES_KILO;
const BASE64_PAYLOAD_PATTERN = /^[A-Za-z0-9+/]+=*$/u;
const TRAILING_SLASH_PATTERN = /\/$/u;

const resolveRecordingFilename = (mimeType: string): string => {
  if (mimeType.includes("wav")) {
    return "recording.wav";
  }
  if (mimeType.includes("mp3")) {
    return "recording.mp3";
  }
  return "recording.webm";
};

export type SpeechTranscribeInput = {
  readonly audioBase64: string;
  readonly mimeType: string;
  readonly filename?: string;
};

export type SpeechTranscribeResult =
  | {
      readonly ok: true;
      readonly text: string;
      readonly provider: SpeechProviderOption;
      readonly model: string;
    }
  | { readonly ok: false; readonly error: string; readonly status: 400 | 422 | 502 };

const SERVER_STT_PROVIDERS = new Set<SpeechProviderOption>([
  "local",
  "openai",
  "huggingface",
  "custom",
]);

const decodeAudio = (audioBase64: string): Uint8Array | null => {
  const trimmed = audioBase64.trim();
  if (trimmed.length === 0 || !BASE64_PAYLOAD_PATTERN.test(trimmed)) {
    return null;
  }
  const bytes = Uint8Array.from(Buffer.from(trimmed, "base64"));
  return bytes.byteLength > 0 ? bytes : null;
};

const resolveUpstreamAuth = async (
  provider: SpeechProviderOption,
): Promise<{ readonly apiKey: string | null }> => {
  const rows = await db
    .select()
    .from(settings)
    .where(eq(settings.id, DEFAULT_SETTINGS_ID))
    .limit(1);
  const row = rows[0];
  if (!row) {
    return { apiKey: null };
  }
  const decrypted = decryptProviderKeys(row);
  if (provider === "openai") {
    return { apiKey: decrypted.openaiApiKey ?? null };
  }
  if (provider === "huggingface") {
    return { apiKey: decrypted.huggingfaceToken ?? null };
  }
  return { apiKey: null };
};

const resolveTranscriptionUrl = (
  provider: SpeechProviderOption,
  endpoint: string,
): { readonly ok: true; readonly url: string } | { readonly ok: false; readonly error: string } => {
  const trimmed = endpoint.trim();
  if (provider === "openai") {
    const base =
      trimmed.length > 0
        ? trimmed.replace(TRAILING_SLASH_PATTERN, "")
        : "https://api.openai.com/v1";
    return { ok: true, url: `${base}/audio/transcriptions` };
  }
  if (provider === "huggingface") {
    if (trimmed.length === 0) {
      return { ok: false, error: API_ERROR_SPEECH_STT_ENDPOINT_INVALID };
    }
    return { ok: true, url: trimmed };
  }
  if (provider === "local" || provider === "custom") {
    const validated = validateLocalAiEndpoint(trimmed);
    if (!validated.ok) {
      return { ok: false, error: API_ERROR_SPEECH_STT_ENDPOINT_INVALID };
    }
    const base = validated.endpoint.replace(TRAILING_SLASH_PATTERN, "");
    const withV1 = base.endsWith("/v1") ? base : `${base}/v1`;
    return { ok: true, url: `${withV1}/audio/transcriptions` };
  }
  return { ok: false, error: API_ERROR_SPEECH_STT_NOT_CONFIGURED };
};

const postOpenAiTranscription = async (input: {
  readonly url: string;
  readonly apiKey: string | null;
  readonly bytes: Uint8Array;
  readonly mimeType: string;
  readonly filename: string;
  readonly model: string;
}): Promise<
  { readonly ok: true; readonly text: string } | { readonly ok: false; readonly error: string }
> => {
  const form = new FormData();
  form.append(
    "file",
    new File([Buffer.from(input.bytes)], input.filename, { type: input.mimeType }),
  );
  form.append("model", input.model);
  const headers: Record<string, string> = {};
  if (input.apiKey) {
    headers.Authorization = `Bearer ${input.apiKey}`;
  }
  const responseResult = await settle(
    fetch(input.url, {
      method: "POST",
      headers,
      body: form,
      signal: AbortSignal.timeout(MS_TWO_MINUTES),
    }),
  );
  if (responseResult.status === "rejected") {
    return { ok: false, error: API_ERROR_SPEECH_TRANSCRIBE };
  }
  const response = responseResult.value;
  const bodyText = await response.text();
  if (!response.ok) {
    return {
      ok: false,
      error: `${API_ERROR_SPEECH_TRANSCRIBE}: ${bodyText.slice(0, COUNT_ONE_EIGHTY)}`,
    };
  }
  const parsed = safeParseJson(bodyText);
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    return { ok: false, error: API_ERROR_SPEECH_TRANSCRIBE };
  }
  const textValue = parsed.text;
  // Empty string is a valid Whisper result (silence / no speech).
  if (typeof textValue !== "string") {
    return { ok: false, error: API_ERROR_SPEECH_TRANSCRIBE };
  }
  return { ok: true, text: textValue.trim() };
};

export const transcribeSpeechAudio = async (
  input: SpeechTranscribeInput,
): Promise<SpeechTranscribeResult> => {
  const automation = await loadAutomationSettings();
  const provider = automation.speech.stt.provider;
  const model = automation.speech.stt.model;
  const endpoint = automation.speech.stt.endpoint;

  if (!SERVER_STT_PROVIDERS.has(provider)) {
    return { ok: false, error: API_ERROR_SPEECH_STT_NOT_CONFIGURED, status: 422 };
  }

  const bytes = decodeAudio(input.audioBase64);
  if (!bytes || bytes.byteLength === 0) {
    return { ok: false, error: "Audio payload is empty or invalid base64", status: 400 };
  }
  if (bytes.byteLength > MAX_AUDIO_BYTES) {
    return { ok: false, error: "Audio payload exceeds 8MB limit", status: 400 };
  }

  const urlResult = resolveTranscriptionUrl(provider, endpoint);
  if (!urlResult.ok) {
    return { ok: false, error: urlResult.error, status: 422 };
  }

  const auth = await resolveUpstreamAuth(provider);
  const filename = input.filename?.trim() || resolveRecordingFilename(input.mimeType);

  const upstream = await postOpenAiTranscription({
    url: urlResult.url,
    apiKey: auth.apiKey,
    bytes,
    mimeType: input.mimeType || "audio/webm",
    filename,
    model,
  });
  if (!upstream.ok) {
    return { ok: false, error: upstream.error, status: 502 };
  }
  return { ok: true, text: upstream.text, provider, model };
};

import { PERCENT_MAX } from "@bao/shared/constants/numeric";
import { STATISTICS_SKILL_COVERAGE_TARGET } from "@bao/shared/constants/statistics";
import type { CareerProgress, WeeklyActivity } from "@bao/shared/types/search";
import { asJsonArray, isRecord } from "@bao/shared/utils/type-guards";

type ActionHistoryEntry = { action: string; xpGained: number; timestamp: string };

export const parseActionHistory = <T>(value: T): ActionHistoryEntry[] => {
  const rawHistory = asJsonArray(value);
  if (!rawHistory) {
    return [];
  }

  const entries: ActionHistoryEntry[] = [];
  for (const entry of rawHistory) {
    if (!isRecord(entry)) {
      continue;
    }
    const action = typeof entry.action === "string" ? entry.action : "other";
    const xpGained = typeof entry.xpGained === "number" ? entry.xpGained : 0;
    const timestamp = typeof entry.timestamp === "string" ? entry.timestamp : "";
    if (timestamp.length === 0) {
      continue;
    }
    entries.push({ action, xpGained, timestamp });
  }
  return entries;
};

export const buildWeeklyActivity = (actionHistory: ActionHistoryEntry[]): WeeklyActivity => {
  const now = new Date();
  const days: Array<{ date: string; actions: number; xpEarned: number }> = [];
  const categoryCounts: Record<string, number> = {};

  for (let index = 6; index >= 0; index -= 1) {
    const date = new Date(now);
    date.setDate(date.getDate() - index);
    const dateStr = date.toISOString().split("T")[0];
    const dayActions = actionHistory.filter((action) => action.timestamp?.startsWith(dateStr));
    const xpEarned = dayActions.reduce((sum, action) => sum + (action.xpGained || 0), 0);

    days.push({ date: dateStr, actions: dayActions.length, xpEarned });

    for (const action of dayActions) {
      categoryCounts[action.action || "other"] =
        (categoryCounts[action.action || "other"] || 0) + 1;
    }
  }

  return {
    days,
    topCategory:
      Object.entries(categoryCounts).sort(([, left], [, right]) => right - left)[0]?.[0] || "none",
    totalXP: days.reduce((sum, day) => sum + day.xpEarned, 0),
  };
};

export const buildCareerProgress = (
  mappedSkills: number,
  applicationStatuses: string[],
): CareerProgress => {
  const skillCoverage = Math.min(
    PERCENT_MAX,
    Math.round((mappedSkills / STATISTICS_SKILL_COVERAGE_TARGET) * PERCENT_MAX),
  );
  const offeredApplications = applicationStatuses.filter((status) => status === "offered").length;
  const applicationSuccessRate =
    applicationStatuses.length > 0
      ? Math.round((offeredApplications / applicationStatuses.length) * PERCENT_MAX)
      : 0;

  return {
    skillCoverage,
    applicationSuccessRate,
    interviewTrend: [],
  };
};

import { afterEach, beforeEach, describe, expect, mock, test } from "bun:test";
