import { config } from "../config/env";

const ENCRYPTION_KEY_RAW = config.encryptionKey;
const ENCRYPTION_KEY_BYTES: Buffer | null = ENCRYPTION_KEY_RAW
  ? Buffer.from(
      ENCRYPTION_KEY_RAW.padEnd(COUNT_THIRTY_TWO, "\0").slice(0, COUNT_THIRTY_TWO),
      "utf8",
    )
  : null;

const IV_LENGTH = 12;
const AUTH_TAG_LENGTH = 16;
const ENCRYPTION_ALGORITHM = "aes-256-gcm" as const;

/**
 * Hash a raw API key using SHA-256 via Bun.CryptoHasher.
 * Only the hash is persisted. Verification compares hashes.
 */
export function hashApiKey(rawKey: string): string {
  const hasher = new Bun.CryptoHasher("sha256");
  hasher.update(rawKey);
  return hasher.digest("base64");
}

/**
 * Compare a raw API key against a stored hash using SHA-256 + timingSafeEqual.
 */
export function verifyApiKey(rawKey: string, storedHash: string): boolean {
  const computed = Buffer.from(hashApiKey(rawKey));
  const expected = Buffer.from(storedHash);
  if (computed.length !== expected.length) {
    return false;
  }
  return timingSafeEqual(computed, expected);
}

/**
 * Encrypt a provider API key for at-rest storage.
 * Uses AES-256-GCM with BAO_ENCRYPTION_KEY from env.
 * Returns "enc:" prefixed base64: iv + ciphertext + authTag.
 *
 * If BAO_ENCRYPTION_KEY is not set, throws — no plaintext fallback.
 */
export function encryptProviderKey(plaintext: string): string {
  if (!ENCRYPTION_KEY_BYTES) {
    throw new Error("BAO_ENCRYPTION_KEY must be set to encrypt provider keys");
  }
  const iv = randomBytes(IV_LENGTH);
  const cipher = createCipheriv(ENCRYPTION_ALGORITHM, ENCRYPTION_KEY_BYTES, iv, {
    authTagLength: AUTH_TAG_LENGTH,
  });
  const encrypted = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
  const authTag = cipher.getAuthTag();
  const combined = Buffer.concat([iv, encrypted, authTag]);
  return `enc:${combined.toString("base64")}`;
}

/**
 * Decrypt a provider API key from at-rest storage.
 * Expects "enc:" prefixed base64: iv + ciphertext + authTag.
 */
export function decryptProviderKey(ciphertext: string): string {
  if (!ENCRYPTION_KEY_BYTES) {
    throw new Error("BAO_ENCRYPTION_KEY must be set to decrypt provider keys");
  }
  if (!ciphertext.startsWith("enc:")) {
    throw new Error("Ciphertext missing encryption prefix");
  }
  const combined = Buffer.from(ciphertext.slice(COUNT_FOUR), "base64");
  const iv = combined.subarray(0, IV_LENGTH);
  const ct = combined.subarray(IV_LENGTH, combined.length - AUTH_TAG_LENGTH);
  const authTag = combined.subarray(combined.length - AUTH_TAG_LENGTH);
  const decipher = createDecipheriv(ENCRYPTION_ALGORITHM, ENCRYPTION_KEY_BYTES, iv, {
    authTagLength: AUTH_TAG_LENGTH,
  });
  decipher.setAuthTag(authTag);
  return Buffer.concat([decipher.update(ct), decipher.final()]).toString("utf8");
}

/**
 * Check if BAO_ENCRYPTION_KEY is available for encryption operations.
 */
export function isEncryptionAvailable(): boolean {
  return ENCRYPTION_KEY_BYTES !== null;
}

/**
 * Canonical HTTP header key for response content type.
 */
export const HEADER_CONTENT_TYPE = "content-type";

/**
 * Canonical HTTP header key for attachment disposition metadata.
 */
export const HEADER_CONTENT_DISPOSITION = "content-disposition";

/**
 * Canonical HTTP header key controlling downstream caching.
 */
export const HEADER_CACHE_CONTROL = "cache-control";

/**
 * Canonical PDF content-type value used by binary export endpoints.
 */
export const MIME_TYPE_PDF = "application/pdf";

/**
 * Canonical DOCX content-type value used by Word document export endpoints.
 */
import { MIME_TYPE_DOCX } from "@bao/shared/constants/export-layout";

export { MIME_TYPE_DOCX };

/**
 * Canonical generic binary content-type fallback value.
 */
export const MIME_TYPE_OCTET_STREAM = "application/octet-stream";

/**
 * Canonical cache-control directive used for private, non-cacheable payloads.
 */
export const CACHE_CONTROL_PRIVATE_NO_STORE = "private, no-store, no-cache";

/**
 * Binary payload shape used by response helpers.
 */
export type BinaryPayload = ArrayBuffer | Uint8Array;

const normalizeBinaryPayload = (payload: BinaryPayload): ArrayBuffer => {
  if (payload instanceof ArrayBuffer) {
    return payload;
  }

  const normalized = new Uint8Array(payload.byteLength);
  normalized.set(payload);
  return normalized.buffer;
};

/**
 * Builds a safe attachment disposition header value for a file name.
 */
export const createAttachmentDisposition = (fileName: string): string =>
  `attachment; filename="${fileName}"`;

/**
 * Creates canonical headers for a PDF attachment response.
 */
export const createPdfAttachmentHeaders = (fileName: string): Readonly<Record<string, string>> => ({
  [HEADER_CONTENT_TYPE]: MIME_TYPE_PDF,
  [HEADER_CONTENT_DISPOSITION]: createAttachmentDisposition(fileName),
});

/**
 * Creates a binary PDF attachment response with canonical headers.
 */
export const createPdfAttachmentResponse = (payload: BinaryPayload, fileName: string): Response =>
  new Response(new Blob([normalizeBinaryPayload(payload)]), {
    headers: createPdfAttachmentHeaders(fileName),
  });

/**
 * Creates canonical headers for a DOCX attachment response.
 */
export const createDocxAttachmentHeaders = (
  fileName: string,
): Readonly<Record<string, string>> => ({
  [HEADER_CONTENT_TYPE]: MIME_TYPE_DOCX,
  [HEADER_CONTENT_DISPOSITION]: createAttachmentDisposition(fileName),
});

/**
 * Creates a binary DOCX attachment response with canonical headers.
 */
export const createDocxAttachmentResponse = (payload: BinaryPayload, fileName: string): Response =>
  new Response(new Blob([normalizeBinaryPayload(payload)]), {
    headers: createDocxAttachmentHeaders(fileName),
  });

/**
 * Creates a binary response with optional cache-control metadata.
 */
export const createBinaryResponse = (
  payload: BinaryPayload,
  options: {
    contentType: string;
    cacheControl?: string;
  },
): Response => {
  const headers: Record<string, string> = {
    [HEADER_CONTENT_TYPE]: options.contentType,
  };

  if (options.cacheControl) {
    headers[HEADER_CACHE_CONTROL] = options.cacheControl;
  }

  return new Response(new Blob([normalizeBinaryPayload(payload)]), {
    headers,
  });
};

import { log } from "../middleware/logger";

type LogDetail = object | string | number | boolean | null;

/**
 * Minimal logger contract used by runtime modules to avoid direct console usage.
 */
export type ServerLogger = {
  debug: (message: string, detail?: LogDetail) => void;
  info: (message: string, detail?: LogDetail) => void;
  warn: (message: string, detail?: LogDetail) => void;
  error: (message: string, detail?: LogDetail) => void;
};

/**
 * Creates a scoped logger instance with component metadata attached to each entry.
 *
 * @param component - Source component name for traceability in structured logs.
 * @returns A logger with shared lifecycle as Bun-native pino integration.
 */
export const createServerLogger = (component: string): ServerLogger => {
  const scopedLogger = log.child({ component });

  return {
    debug: (message: string, detail?: LogDetail) => {
      scopedLogger.debug(detail !== undefined ? { details: detail } : {}, message);
    },
    info: (message: string, detail?: LogDetail) => {
      scopedLogger.info(detail !== undefined ? { details: detail } : {}, message);
    },
    warn: (message: string, detail?: LogDetail) => {
      scopedLogger.warn(detail !== undefined ? { details: detail } : {}, message);
    },
    error: (message: string, detail?: LogDetail) => {
      scopedLogger.error(detail !== undefined ? { details: detail } : {}, message);
    },
  };
};

import { COUNT_TWELVE } from "@bao/shared/constants/numeric";
/**
 * OpenAPI operation detail SSOT — every documented route must ship tags + description.
 */
export const openapiDetail = (tag: string, description: string) => {
  const trimmed = description.trim();
  if (tag.length === 0) {
    throw new Error("openapiDetail requires a non-empty tag");
  }
  if (trimmed.length < COUNT_TWELVE) {
    throw new Error(`openapiDetail description too short for tag "${tag}"`);
  }
  return {
    tags: [tag],
    description: trimmed,
  };
};

import { API_ERROR_RATE_LIMIT_EXCEEDED } from "@bao/shared/constants/api-errors";
import { HTTP_STATUS_TOO_MANY_REQUESTS } from "@bao/shared/constants/http";
import { MS_PER_SECOND } from "@bao/shared/constants/time";
import { Elysia } from "elysia";
import {
  RATE_LIMIT_DURATION_MS,
  RATE_LIMIT_MAX_AUTOMATION,
  RATE_LIMIT_MAX_SKILL_ANALYSIS,
} from "../config/rate-limit";
import { resolveRateLimitClientKey } from "./request";

type RateLimitBucket = {
  count: number;
  resetAt: number;
};

type CreateRateLimitOptions = {
  durationMs: number;
  max: number;
  name: string;
  generator?: (request: Request) => string;
};

/**
 * Builds an in-memory Elysia 2 rate-limit plugin keyed by client IP headers.
 */
export function createRateLimitPlugin(options: CreateRateLimitOptions) {
  const buckets = new Map<string, RateLimitBucket>();
  const resolveKey = options.generator ?? resolveRateLimitClientKey;

  return new Elysia({ name: options.name }).beforeHandle(({ request, set }) => {
    const now = Date.now();
    const key = resolveKey(request);
    const existing = buckets.get(key);

    if (!existing || existing.resetAt <= now) {
      buckets.set(key, { count: 1, resetAt: now + options.durationMs });
      set.headers["x-ratelimit-limit"] = String(options.max);
      set.headers["x-ratelimit-remaining"] = String(options.max - 1);
      return;
    }

    existing.count += 1;
    buckets.set(key, existing);

    const remaining = Math.max(0, options.max - existing.count);
    set.headers["x-ratelimit-limit"] = String(options.max);
    set.headers["x-ratelimit-remaining"] = String(remaining);
    set.headers["x-ratelimit-reset"] = String(Math.ceil(existing.resetAt / MS_PER_SECOND));

    if (existing.count > options.max) {
      set.status = HTTP_STATUS_TOO_MANY_REQUESTS;
      return {
        error: API_ERROR_RATE_LIMIT_EXCEEDED,
        code: "RATE_LIMIT_EXCEEDED",
      };
    }
  });
}

/**
 * Rate limit plugin for expensive AI/automation operations.
 */
export const automationRateLimit = createRateLimitPlugin({
  name: "rate-limit-automation",
  durationMs: RATE_LIMIT_DURATION_MS,
  max: RATE_LIMIT_MAX_AUTOMATION,
});

/**
 * Rate limit plugin for skill analysis (AI) operations.
 */
export const skillAnalysisRateLimit = createRateLimitPlugin({
  name: "rate-limit-skill-analysis",
  durationMs: RATE_LIMIT_DURATION_MS,
  max: RATE_LIMIT_MAX_SKILL_ANALYSIS,
});

/**
 * Factory matching previous `elysia-rate-limit` call sites.
 */
export function rateLimit(options: {
  duration: number;
  max: number;
  generator?: (request: Request) => string;
  scoping?: string;
}) {
  return createRateLimitPlugin({
    name: `rate-limit-${options.max}-${options.duration}`,
    durationMs: options.duration,
    max: options.max,
    generator: options.generator,
  });
}

/**
 * Resolves a client identifier for rate limiting from request headers.
 * Checks x-forwarded-for, cf-connecting-ip, x-real-ip; falls back to request host.
 */
export const resolveRateLimitClientKey = (request: Request): string => {
  const forwardedFor = request.headers.get("x-forwarded-for");
  if (forwardedFor && forwardedFor.trim().length > 0) {
    const firstHop = forwardedFor.split(",")[0]?.trim();
    if (firstHop) return firstHop;
  }

  const cloudflareIp = request.headers.get("cf-connecting-ip");
  if (cloudflareIp && cloudflareIp.trim().length > 0) {
    return cloudflareIp.trim();
  }

  const realIp = request.headers.get("x-real-ip");
  if (realIp && realIp.trim().length > 0) {
    return realIp.trim();
  }

  return new URL(request.url).host;
};

import { decryptProviderKey, isEncryptionAvailable } from "./crypto";

interface ProviderKeysRow {
  geminiApiKey: string | null;
  openaiApiKey: string | null;
  claudeApiKey: string | null;
  huggingfaceToken: string | null;
  emailTransportPassword: string | null;
}

interface DecryptedProviderKeys {
  geminiApiKey: string | null;
  openaiApiKey: string | null;
  claudeApiKey: string | null;
  huggingfaceToken: string | null;
  emailTransportPassword: string | null;
}

function maybeDecrypt(value: string | null): string | null {
  if (!value) return null;
  if (!value.startsWith("enc:")) return value;
  if (!isEncryptionAvailable()) return null;
  return decryptProviderKey(value);
}

export function decryptProviderKeys(row: ProviderKeysRow): DecryptedProviderKeys {
  return {
    geminiApiKey: maybeDecrypt(row.geminiApiKey),
    openaiApiKey: maybeDecrypt(row.openaiApiKey),
    claudeApiKey: maybeDecrypt(row.claudeApiKey),
    huggingfaceToken: maybeDecrypt(row.huggingfaceToken),
    emailTransportPassword: maybeDecrypt(row.emailTransportPassword),
  };
}

import { SCHEMA_MAX_LENGTH_RUN_ID } from "@bao/shared/constants/schema-limits";
import { t } from "elysia";
import type { Static } from "typebox";

export const automationWebSocketBodySchema = t.Object({
  type: t.Union([t.Literal("subscribe"), t.Literal("unsubscribe")]),
  runId: t.Optional(t.String({ minLength: 8, maxLength: SCHEMA_MAX_LENGTH_RUN_ID })),
});

export type AutomationWebSocketMessage = Static<typeof automationWebSocketBodySchema>;

import { toApiScopedPath, WS_ENDPOINTS } from "@bao/shared/constants/endpoints";
import { type RpaRunEvent, rpaRunEventSchema } from "@bao/shared/schemas/rpa-events.schema";
import { Elysia } from "elysia";
import { authenticateApiKey } from "../middleware/auth";
import {
  type AutomationWebSocketMessage,
  automationWebSocketBodySchema,
} from "./automation-ws-contracts";

const WS_READY_STATE_OPEN = 1;

type SubscriberSocket = {
  send: (message: string) => void;
  readyState?: number;
};

const subscribers = new Map<string, Set<SubscriberSocket>>();

const subscribeSocket = (runId: string, socket: SubscriberSocket): void => {
  const existing = subscribers.get(runId);
  if (existing) {
    existing.add(socket);
    return;
  }
  subscribers.set(runId, new Set([socket]));
};

const unsubscribeSocket = (runId: string, socket: SubscriberSocket): void => {
  const existing = subscribers.get(runId);
  if (!existing) {
    return;
  }

  existing.delete(socket);
  if (existing.size === 0) {
    subscribers.delete(runId);
  }
};

const unsubscribeSocketEverywhere = (socket: SubscriberSocket): void => {
  for (const [runId, set] of subscribers.entries()) {
    set.delete(socket);
    if (set.size === 0) {
      subscribers.delete(runId);
    }
  }
};

const isSocketOpen = (socket: SubscriberSocket): boolean =>
  typeof socket.readyState !== "number" || socket.readyState === WS_READY_STATE_OPEN;

/**
 * Broadcasts a validated automation event to subscribers of the matching run.
 */
export function broadcastAutomationEvent(event: RpaRunEvent): void {
  const validatedEvent = rpaRunEventSchema.safeParse(event);
  if (!validatedEvent.success) {
    return;
  }

  const runSubscribers = subscribers.get(validatedEvent.data.runId);
  if (!runSubscribers || runSubscribers.size === 0) {
    return;
  }

  const payload = JSON.stringify(validatedEvent.data);
  for (const socket of runSubscribers) {
    if (!isSocketOpen(socket)) {
      runSubscribers.delete(socket);
      continue;
    }
    socket.send(payload);
  }

  if (runSubscribers.size === 0) {
    subscribers.delete(validatedEvent.data.runId);
  }
}

/**
 * Automation websocket endpoint for run-scoped event subscriptions.
 */
export const automationWebSocket = new Elysia().ws(toApiScopedPath(WS_ENDPOINTS.automation), {
  body: automationWebSocketBodySchema,

  async beforeHandle({ request }) {
    const failure = await authenticateApiKey(request);
    if (failure) {
      return new Response(JSON.stringify({ error: failure.error }), {
        status: failure.status,
        headers: { "content-type": "application/json" },
      });
    }
  },

  message(ws, payload: AutomationWebSocketMessage) {
    if (!payload.runId) {
      return;
    }

    if (payload.type === "subscribe") {
      subscribeSocket(payload.runId, ws);
      return;
    }

    unsubscribeSocket(payload.runId, ws);
  },

  close(ws) {
    unsubscribeSocketEverywhere(ws);
  },
});

import {
  SCHEMA_MAX_LENGTH_ID,
  SCHEMA_MAX_LENGTH_MESSAGE,
} from "@bao/shared/constants/schema-limits";
import { t } from "elysia";
import type { Static } from "typebox";

export const chatWebSocketBodySchema = t.Object({
  content: t.String({ maxLength: SCHEMA_MAX_LENGTH_MESSAGE }),
  sessionId: t.Optional(t.String({ maxLength: SCHEMA_MAX_LENGTH_ID })),
});

export type ChatWebSocketBody = Static<typeof chatWebSocketBodySchema>;

import {
  AI_DEFAULT_TEMPERATURE_CREATIVE,
  AI_MAX_TOKENS_WS,
} from "@bao/shared/constants/ai-generation";
import { API_ERROR_GENERATE_RESPONSE } from "@bao/shared/constants/api-errors";
import { resolveBrandSettings } from "@bao/shared/constants/branding";
import { toApiScopedPath, WS_ENDPOINTS } from "@bao/shared/constants/endpoints";
import { safeParseJson } from "@bao/shared/utils/json";
import { settle } from "@bao/shared/utils/promise";
import { generateId } from "@bao/shared/utils/validation";
import { eq } from "drizzle-orm";
import { Elysia } from "elysia";
import { db } from "../db/client";
import { chatHistory } from "../db/schema/chat-history";
import { DEFAULT_SETTINGS_ID, settings } from "../db/schema/settings";
import { authenticateApiKey } from "../middleware/auth";
import type { AIService } from "../services/ai/ai-service";
import { contextManager } from "../services/ai/context-manager";
import { type ChatWebSocketBody, chatWebSocketBodySchema } from "./chat-ws-contracts";

type AIServiceInstance = AIService;
type SettingsRow = typeof settings.$inferSelect;
type ChatContext = Awaited<ReturnType<typeof contextManager.buildContext>>;
type ChatSocket = { send: (data: string) => void };
type ChatMessage = ChatWebSocketBody;
type StreamAssistantResponseInput = {
  socket: ChatSocket;
  aiService: AIServiceInstance;
  input: string;
  context: ChatContext;
  sessionId: string;
};

type AutomationActionPayload = {
  action: string;
  jobUrl?: string;
  resumeId?: string;
  coverLetterId?: string;
};

type RuntimeBrand = ReturnType<typeof resolveBrandSettings>;

const JOB_APPLY_ACTION_PATTERN = /\{"action"\s*:\s*"job_apply"[^{}]*\}/;

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function parseAutomationActionPayload(raw: string): AutomationActionPayload | null {
  const parsed = safeParseJson(raw);
  if (!isRecord(parsed)) {
    return null;
  }

  if (typeof parsed.action !== "string") {
    return null;
  }

  return {
    action: parsed.action,
    ...(typeof parsed.jobUrl === "string" ? { jobUrl: parsed.jobUrl } : {}),
    ...(typeof parsed.resumeId === "string" ? { resumeId: parsed.resumeId } : {}),
    ...(typeof parsed.coverLetterId === "string" ? { coverLetterId: parsed.coverLetterId } : {}),
  };
}

function sendSocketPayload(socket: ChatSocket, payload: Record<string, unknown>): void {
  socket.send(JSON.stringify(payload));
}

function sendChatError(socket: ChatSocket, sessionId: string): void {
  sendSocketPayload(socket, {
    type: "error",
    message: API_ERROR_GENERATE_RESPONSE,
    sessionId,
  });
}

async function saveChatMessage(
  role: "user" | "assistant",
  content: string,
  sessionId: string,
): Promise<void> {
  await db.insert(chatHistory).values({
    id: generateId(),
    role,
    content,
    timestamp: new Date().toISOString(),
    sessionId,
  });
}

async function getSettingsRow(): Promise<SettingsRow | undefined> {
  const rows = await db.select().from(settings).where(eq(settings.id, DEFAULT_SETTINGS_ID));
  return rows[0];
}

function resolveRuntimeBrand(config: SettingsRow | undefined): RuntimeBrand {
  return resolveBrandSettings(config?.brandSettings);
}

async function createAiService(config: SettingsRow | undefined): Promise<AIServiceInstance> {
  const { AIService } = await import("../services/ai/ai-service");
  return AIService.fromSettings(config);
}

function getAutomationActionMessage(
  streamedText: string,
  sessionId: string,
): Record<string, unknown> | null {
  const actionMatch = streamedText.match(JOB_APPLY_ACTION_PATTERN);
  if (!actionMatch) {
    return null;
  }

  const action = parseAutomationActionPayload(actionMatch[0]);
  if (!action) {
    return {
      type: "automation_action_detected",
      action: null,
      sessionId,
      parseError: true,
    };
  }

  const isValidAction =
    action.action === "job_apply" && Boolean(action.jobUrl) && Boolean(action.resumeId);
  return {
    type: "automation_action_detected",
    action: isValidAction ? action : null,
    sessionId,
  };
}

async function streamAssistantResponse({
  socket,
  aiService,
  input,
  context,
  sessionId,
}: StreamAssistantResponseInput): Promise<string> {
  let streamedText = "";
  sendSocketPayload(socket, { type: "stream_start", sessionId });

  const generator = aiService.stream(input, {
    purpose: "chat",
    systemPrompt: context.systemPrompt,
    messages: context.messages,
    temperature: AI_DEFAULT_TEMPERATURE_CREATIVE,
    maxTokens: AI_MAX_TOKENS_WS,
  });

  for await (const { chunk } of generator) {
    streamedText += chunk;
    sendSocketPayload(socket, { type: "stream_chunk", chunk, sessionId });
  }

  const domain = contextManager.inferDomain(input);
  const followUps = contextManager.generateFollowUps(domain);
  sendSocketPayload(socket, { type: "stream_end", sessionId, followUps });

  const automationActionPayload = getAutomationActionMessage(streamedText, sessionId);
  if (automationActionPayload) {
    sendSocketPayload(socket, automationActionPayload);
  }

  return streamedText;
}

async function handleChatMessage(socket: ChatSocket, data: ChatMessage): Promise<void> {
  const sessionId = data.sessionId || generateId();
  await saveChatMessage("user", data.content, sessionId);

  sendSocketPayload(socket, { type: "message_received", sessionId });

  const settingsResult = await settle(getSettingsRow());
  if (settingsResult.status === "rejected") {
    sendChatError(socket, sessionId);
    return;
  }

  const aiService = await createAiService(settingsResult.value);
  const runtimeBrand = resolveRuntimeBrand(settingsResult.value);
  const contextResult = await settle(
    contextManager.buildContext(sessionId, data.content, undefined, runtimeBrand),
  );
  if (contextResult.status === "rejected") {
    sendChatError(socket, sessionId);
    return;
  }

  const responseText = await streamAssistantResponse({
    socket,
    aiService,
    input: data.content,
    context: contextResult.value,
    sessionId,
  });

  const persistResult = await settle(saveChatMessage("assistant", responseText, sessionId));
  if (persistResult.status === "rejected") {
    sendChatError(socket, sessionId);
  }
}

export const chatWebSocket = new Elysia().ws(toApiScopedPath(WS_ENDPOINTS.chat), {
  body: chatWebSocketBodySchema,
  async beforeHandle({ request }) {
    const failure = await authenticateApiKey(request);
    if (failure) {
      return new Response(JSON.stringify({ error: failure.error }), {
        status: failure.status,
        headers: { "content-type": "application/json" },
      });
    }
  },
  async open(ws) {
    const brand = resolveRuntimeBrand(await getSettingsRow());
    sendSocketPayload(ws, {
      type: "connected",
      message: `Connected to ${brand.assistantName} chat`,
    });
  },
  async message(ws, data: ChatWebSocketBody) {
    if (!data.content) {
      sendSocketPayload(ws, {
        type: "error",
        message: API_ERROR_GENERATE_RESPONSE,
        sessionId: data.sessionId ?? generateId(),
      });
      return;
    }

    await handleChatMessage(ws, {
      content: data.content,
      ...(data.sessionId ? { sessionId: data.sessionId } : {}),
    });
  },
  close() {
    /* connection teardown handled by Elysia */
  },
});

import {
  SCHEMA_MAX_LENGTH_ID,
  SCHEMA_MAX_LENGTH_LABEL,
  SCHEMA_MAX_LENGTH_MESSAGE,
} from "@bao/shared/constants/schema-limits";
import { t } from "elysia";
import type { Static } from "typebox";
import { sessionConfigSchema } from "../routes/interview-route-contracts";

export const interviewWebSocketBodySchema = t.Object({
  type: t.String({ maxLength: SCHEMA_MAX_LENGTH_LABEL }),
  sessionId: t.Optional(t.String({ maxLength: SCHEMA_MAX_LENGTH_ID })),
  content: t.Optional(t.String({ maxLength: SCHEMA_MAX_LENGTH_MESSAGE })),
