  DESKTOP_RELEASE_MACOS_AARCH64_TARGET,
  DESKTOP_RELEASE_MACOS_UNIVERSAL_ARCH,
  DESKTOP_RELEASE_MACOS_UNIVERSAL_TARGET,
  DESKTOP_RELEASE_MACOS_X64_ARCH,
  DESKTOP_RELEASE_MACOS_X64_TARGET,
  DESKTOP_RELEASE_WINDOWS_ARCH,
  DESKTOP_RELEASE_WINDOWS_MSI_LANGUAGE,
  DESKTOP_RELEASE_WINDOWS_TARGET,
} from "../constants/scripts";
import { resolveDesktopRuntimeTargetInfo } from "./desktop-runtime-contract";

/**
 * Canonical desktop release staging targets.
 */
export type DesktopReleaseTarget = (typeof DESKTOP_RELEASE_TARGETS)[number];

/**
 * Minimum metadata required to build canonical desktop release artifact names.
 */
export type DesktopReleaseArtifactNaming = {
  readonly productName: string;
  readonly version: string;
};

/**
 * Supported macOS architecture labels for release artifact naming.
 */
export type DesktopReleaseMacosArchitecture =
  | typeof DESKTOP_RELEASE_MACOS_AARCH64_ARCH
  | typeof DESKTOP_RELEASE_MACOS_X64_ARCH
  | typeof DESKTOP_RELEASE_MACOS_UNIVERSAL_ARCH;

/**
 * Canonical desktop release artifact kinds produced by matching-host native builds.
 */
export type DesktopReleaseArtifactKind =
  | "appimage"
  | "deb"
  | "dmg"
  | "msi"
  | "portable"
  | "rpm"
  | "sig"
  | "setup";

/**
 * Optional profile-driven release variant toggles.
 */
export type DesktopReleaseArtifactProfile = {
  readonly includeLinuxAppImage: boolean;
  readonly includeLinuxSignatures: boolean;
  readonly includeWindowsMsi: boolean;
  readonly macosArchitectures: readonly DesktopReleaseMacosArchitecture[];
};

/**
 * Default profile for canonical release outputs.
 * Set `include*` fields to true (or `DESKTOP_RELEASE_*=true` in build/verify scripts) to opt in.
 *
 * Linux signatures require GPG signing infrastructure.
 * Windows MSI requires the WiX toolchain.
 * Enable these flags only when the build environment supports them.
 */
export const DEFAULT_DESKTOP_RELEASE_ARTIFACT_PROFILE: DesktopReleaseArtifactProfile = {
  includeLinuxAppImage: false,
  includeLinuxSignatures: false,
  includeWindowsMsi: false,
  macosArchitectures: [DESKTOP_RELEASE_MACOS_AARCH64_ARCH],
};

const DESKTOP_RELEASE_MACOS_ARCHITECTURE_ORDER: readonly DesktopReleaseMacosArchitecture[] = [
  DESKTOP_RELEASE_MACOS_AARCH64_ARCH,
  DESKTOP_RELEASE_MACOS_X64_ARCH,
  DESKTOP_RELEASE_MACOS_UNIVERSAL_ARCH,
];

/**
 * Canonical artifact entry within the assembled desktop release directory.
 */
export type DesktopReleaseArtifactSpec = {
  readonly fileName: string;
  readonly kind: DesktopReleaseArtifactKind;
  readonly relativePath: string;
  readonly target: DesktopReleaseTarget;
};

const dedupeMacosArchitectures = (
  architectures: readonly DesktopReleaseMacosArchitecture[],
): readonly DesktopReleaseMacosArchitecture[] => {
  const selectedArchitectures = new Set(architectures);
  return DESKTOP_RELEASE_MACOS_ARCHITECTURE_ORDER.filter((architecture) =>
    selectedArchitectures.has(architecture),
  );
};

/**
 * Resolves a partial release profile into the canonical artifact profile.
 */
export const normalizeDesktopReleaseArtifactProfile = (
  profile: Partial<DesktopReleaseArtifactProfile> = {},
): DesktopReleaseArtifactProfile => ({
  includeLinuxAppImage:
    profile.includeLinuxAppImage ?? DEFAULT_DESKTOP_RELEASE_ARTIFACT_PROFILE.includeLinuxAppImage,
  includeLinuxSignatures:
    profile.includeLinuxSignatures ??
    DEFAULT_DESKTOP_RELEASE_ARTIFACT_PROFILE.includeLinuxSignatures,
  includeWindowsMsi:
    profile.includeWindowsMsi ?? DEFAULT_DESKTOP_RELEASE_ARTIFACT_PROFILE.includeWindowsMsi,
  macosArchitectures:
    profile.macosArchitectures === undefined || profile.macosArchitectures.length === 0
      ? DEFAULT_DESKTOP_RELEASE_ARTIFACT_PROFILE.macosArchitectures
      : dedupeMacosArchitectures(profile.macosArchitectures),
});

const createDesktopReleaseArtifactSpec = (
  target: DesktopReleaseTarget,
  fileName: string,
  kind: DesktopReleaseArtifactKind,
): DesktopReleaseArtifactSpec => ({
  fileName,
  kind,
  relativePath: `${target}/${fileName}`,
  target,
});

const isLinuxTarget = (target: DesktopReleaseTarget): target is "linux-x64" | "linux-arm64" =>
  target === "linux-x64" || target === "linux-arm64";

const buildLinuxAppImageSpecs = (
  metadata: DesktopReleaseArtifactNaming,
  target: "linux-x64" | "linux-arm64",
): readonly DesktopReleaseArtifactSpec[] => [
  createDesktopReleaseArtifactSpec(
    target,
    `${metadata.productName}_${metadata.version}_${
      target === "linux-x64"
        ? DESKTOP_RELEASE_LINUX_X64_DEB_ARCH
        : DESKTOP_RELEASE_LINUX_ARM64_DEB_ARCH
    }.AppImage`,
    "appimage",
  ),
];

const buildLinuxCoreSpecs = (
  metadata: DesktopReleaseArtifactNaming,
  target: DesktopReleaseTarget,
) =>
  target === "linux-x64"
    ? [
        createDesktopReleaseArtifactSpec(
          target,
          `${metadata.productName}_${metadata.version}_${DESKTOP_RELEASE_LINUX_X64_DEB_ARCH}.deb`,
          "deb",
        ),
        createDesktopReleaseArtifactSpec(
          target,
          `${metadata.productName}-${metadata.version}-1.${DESKTOP_RELEASE_LINUX_X64_RPM_ARCH}.rpm`,
          "rpm",
        ),
      ]
    : [
        createDesktopReleaseArtifactSpec(
          target,
          `${metadata.productName}_${metadata.version}_${DESKTOP_RELEASE_LINUX_ARM64_DEB_ARCH}.deb`,
          "deb",
        ),
        createDesktopReleaseArtifactSpec(
          target,
          `${metadata.productName}-${metadata.version}-1.${DESKTOP_RELEASE_LINUX_ARM64_RPM_ARCH}.rpm`,
          "rpm",
        ),
      ];

const appendLinuxSignatures = (
  artifacts: readonly DesktopReleaseArtifactSpec[],
): readonly DesktopReleaseArtifactSpec[] =>
  artifacts.concat(
    artifacts.map((artifact) =>
      createDesktopReleaseArtifactSpec(artifact.target, `${artifact.fileName}.sig`, "sig"),
    ),
  );

const resolveMacosTargetForArchitecture = (
  architecture: DesktopReleaseMacosArchitecture,
): string => {
  if (architecture === DESKTOP_RELEASE_MACOS_X64_ARCH) {
    return DESKTOP_RELEASE_MACOS_X64_TARGET;
  }
  if (architecture === DESKTOP_RELEASE_MACOS_UNIVERSAL_ARCH) {
    return DESKTOP_RELEASE_MACOS_UNIVERSAL_TARGET;
  }
  return DESKTOP_RELEASE_MACOS_AARCH64_TARGET;
};

/**
 * Builds the target release config profile for a requested release target.
 */
export const resolveDesktopReleaseTauriTargetsFromProfile = (
  profile: DesktopReleaseArtifactProfile,
): readonly string[] => {
  const normalizedProfile = normalizeDesktopReleaseArtifactProfile(profile);
  const explicitTargets = [
    ...normalizedProfile.macosArchitectures.map(resolveMacosTargetForArchitecture),
    DESKTOP_RELEASE_WINDOWS_TARGET,
    DESKTOP_RELEASE_LINUX_X64_TARGET,
    DESKTOP_RELEASE_LINUX_ARM64_TARGET,
  ];
  return explicitTargets.filter(
    (target, index, targetCandidates) => targetCandidates.indexOf(target) === index,
  );
};

/**
 * Builds canonical assembled release artifact specs for a target.
 */
export const buildDesktopReleaseArtifactSpecs = (
  metadata: DesktopReleaseArtifactNaming,
  target: DesktopReleaseTarget,
  profile: Partial<DesktopReleaseArtifactProfile> = {},
): readonly DesktopReleaseArtifactSpec[] => {
  const normalizedProfile = normalizeDesktopReleaseArtifactProfile(profile);

  if (target === "macos") {
    return normalizedProfile.macosArchitectures.map((architecture) =>
      createDesktopReleaseArtifactSpec(
        target,
        `${metadata.productName}_${metadata.version}_${architecture}.dmg`,
        "dmg",
      ),
    );
  }

  if (isLinuxTarget(target)) {
    const linuxArtifacts = [...buildLinuxCoreSpecs(metadata, target)];
    if (normalizedProfile.includeLinuxAppImage && target === "linux-x64") {
      linuxArtifacts.push(...buildLinuxAppImageSpecs(metadata, target));
    }
    return normalizedProfile.includeLinuxSignatures
      ? appendLinuxSignatures(linuxArtifacts)
      : linuxArtifacts;
  }

  const windowsArtifacts = [
    createDesktopReleaseArtifactSpec(
      target,
      `${metadata.productName}_${metadata.version}_${DESKTOP_RELEASE_WINDOWS_ARCH}-setup.exe`,
      "setup",
    ),
    createDesktopReleaseArtifactSpec(
      target,
      `${metadata.productName}_${metadata.version}_${DESKTOP_RELEASE_WINDOWS_ARCH}-portable.zip`,
      "portable",
    ),
  ];

  if (normalizedProfile.includeWindowsMsi) {
    windowsArtifacts.push(
      createDesktopReleaseArtifactSpec(
        target,
        `${metadata.productName}_${metadata.version}_${DESKTOP_RELEASE_WINDOWS_ARCH}_${DESKTOP_RELEASE_WINDOWS_MSI_LANGUAGE}.msi`,
        "msi",
      ),
    );
  }

  return windowsArtifacts;
};

/**
 * Builds the canonical artifact file names for a target.
 */
export const buildDesktopReleaseArtifactFileNames = (
  metadata: DesktopReleaseArtifactNaming,
  target: DesktopReleaseTarget,
  profile: Partial<DesktopReleaseArtifactProfile> = {},
): readonly string[] =>
  buildDesktopReleaseArtifactSpecs(metadata, target, profile).map((artifact) => artifact.fileName);

/**
 * Builds the candidate Cargo release directories used by native Tauri builds for a target.
 */
export const buildDesktopReleaseDirectoryCandidates = (
  target: DesktopReleaseTarget,
  tauriTarget?: string,
): readonly string[] => {
  const targetInfo = resolveDesktopRuntimeTargetInfo(target);
  return ["target/release", `target/${tauriTarget ?? targetInfo.tauriTarget}/release`] as const;
};

/**
 * Builds the candidate Tauri bundle directories used by native Tauri builds for a target.
 */
export const buildDesktopBundleDirectoryCandidates = (
  target: DesktopReleaseTarget,
  tauriTarget?: string,
): readonly string[] =>
  buildDesktopReleaseDirectoryCandidates(target, tauriTarget).map(
    (releaseDirectory) => `${releaseDirectory}/bundle`,
  );

/**
 * Maps a profile-defined macOS architecture to a Tauri bundle build target.
 */
export const resolveMacosTargetFromProfileArchitecture = (
  architecture: DesktopReleaseMacosArchitecture,
): string => resolveMacosTargetForArchitecture(architecture);

import { describe, expect, test } from "bun:test";
import {
  buildDesktopRuntimeManifest,
  getDesktopRuntimeManifestMismatches,
  listDesktopRuntimeContractPaths,
  parseDesktopRuntimeManifest,
  resolveDesktopRuntimeTargetInfo,
  resolveDesktopRuntimeTargetInfoFromHost,
  resolveDesktopRuntimeTargetInfoFromTauriTarget,
} from "./desktop-runtime-contract";

describe("desktop runtime contract: target resolution", () => {
  test("resolves the canonical Windows runtime layout", () => {
    const runtimeTargetInfo = resolveDesktopRuntimeTargetInfo("windows");

    expect(runtimeTargetInfo.hostPlatform).toBe("win32");
    expect(runtimeTargetInfo.hostArch).toBe("x64");
    expect(runtimeTargetInfo.serverExecutable).toBe("server/bao-desktop-server.exe");
    expect(runtimeTargetInfo.scriptRunnerExecutable).toBe("bin/bao-bun-runner.exe");
    expect(runtimeTargetInfo.defaultWebviewBootstrapperExecutable).toBe(
      "bin/MicrosoftEdgeWebview2Setup.exe",
    );
  });

  test("resolves Linux runtime layout from the Tauri target triple", () => {
    const runtimeTargetInfo = resolveDesktopRuntimeTargetInfoFromTauriTarget(
      "x86_64-unknown-linux-gnu",
    );

    expect(runtimeTargetInfo.target).toBe("linux-x64");
    expect(runtimeTargetInfo.scriptRunnerExecutable).toBe("bin/bao-bun");
    expect(runtimeTargetInfo.defaultWebviewBootstrapperExecutable).toBeNull();
  });

  test("builds and normalizes the canonical runtime manifest", () => {
    const windowsManifest = buildDesktopRuntimeManifest("windows");
    const normalizedManifest = parseDesktopRuntimeManifest(
      {
        ...windowsManifest,
        webviewBootstrapperExecutable: undefined,
      },
      "test-manifest",
    );

    expect(windowsManifest.webviewBootstrapperExecutable).toBe(
      "bin/MicrosoftEdgeWebview2Setup.exe",
    );
    expect(normalizedManifest.webviewBootstrapperExecutable).toBeNull();
    expect(
      getDesktopRuntimeManifestMismatches(windowsManifest, buildDesktopRuntimeManifest("windows")),
    ).toHaveLength(0);
  });

  test("falls back to canonical host target resolution", () => {
    expect(resolveDesktopRuntimeTargetInfoFromHost("darwin", "x64").target).toBe("macos");
    expect(resolveDesktopRuntimeTargetInfoFromHost("linux", "arm64").target).toBe("linux-arm64");
    expect(resolveDesktopRuntimeTargetInfoFromHost("win32", "x64").target).toBe("windows");
  });
});

describe("desktop runtime contract: packaged payload entries", () => {
  test("lists all runtime contract paths for packaged verification", () => {
    const manifest = buildDesktopRuntimeManifest("linux-arm64");
    const contractPaths = listDesktopRuntimeContractPaths(manifest, ["playwright", "zod"]);

    expect(contractPaths).toEqual([
      "manifest.json",
      "server/bao-desktop-server",
      "bin/bao-bun",
      "bin/bao-bun-entrypoint-runner.mjs",
      "scraper/package.json",
      "scraper/node_modules/playwright/package.json",
      "scraper/node_modules/zod/package.json",
    ]);
  });
});

import { z } from "zod";
import {
  DESKTOP_RELEASE_LINUX_ARM64_TARGET,
  DESKTOP_RELEASE_LINUX_X64_TARGET,
  DESKTOP_RELEASE_MACOS_AARCH64_TARGET,
  DESKTOP_RELEASE_TARGETS,
  DESKTOP_RELEASE_WINDOWS_TARGET,
  DESKTOP_RUNTIME_CORS_ORIGINS,
  DESKTOP_RUNTIME_HOST,
  DESKTOP_RUNTIME_LINUX_BUN_PATH,
  DESKTOP_RUNTIME_SCRAPER_DIR,
  DESKTOP_RUNTIME_SCRIPT_RUNNER_ENTRYPOINT_PATH,
  DESKTOP_RUNTIME_SCRIPT_RUNNER_PATH,
  DESKTOP_RUNTIME_SERVER_EXECUTABLE_PATH,
  DESKTOP_RUNTIME_SERVER_PORT,
  DESKTOP_RUNTIME_WEBVIEW_BOOTSTRAPPER_PATH,
} from "../constants/scripts";

/**
 * Canonical desktop runtime release targets.
 */
export type DesktopRuntimeReleaseTarget = (typeof DESKTOP_RELEASE_TARGETS)[number];

/**
 * Supported desktop runtime host platforms.
 */
export type DesktopRuntimeHostPlatform = Extract<NodeJS.Platform, "darwin" | "linux" | "win32">;

/**
 * Supported desktop runtime host architectures.
 */
export type DesktopRuntimeHostArch = "arm64" | "x64";

/**
 * Typed runtime manifest contract consumed by the desktop host and verification scripts.
 */
export const desktopRuntimeManifestSchema = z.object({
  serverExecutable: z.string().min(1),
  scriptRunnerExecutable: z.string().min(1),
  scriptRunnerEntrypoint: z.string().min(1).nullable(),
  webviewBootstrapperExecutable: z.string().min(1).nullable().optional(),
  scraperDir: z.string().min(1),
  serverHost: z.string().min(1),
  serverPort: z.number().int().positive(),
  corsOrigins: z.array(z.string().min(1)),
});

/**
 * Parsed desktop runtime manifest shape.
 */
export type DesktopRuntimeManifest = z.infer<typeof desktopRuntimeManifestSchema>;

/**
 * Canonical per-target runtime layout resolved from Tauri target metadata.
 */
export type DesktopRuntimeTargetInfo = {
  readonly target: DesktopRuntimeReleaseTarget;
  readonly tauriTarget: string;
  readonly hostPlatform: DesktopRuntimeHostPlatform;
  readonly hostArch: DesktopRuntimeHostArch;
  readonly serverExecutable: string;
  readonly scriptRunnerExecutable: string;
  readonly scriptRunnerEntrypoint: string;
  readonly scraperDir: string;
  readonly defaultWebviewBootstrapperExecutable: string | null;
};

const WINDOWS_EXECUTABLE_SUFFIX = ".exe" as const;

const appendWindowsExecutableSuffix = (relativePath: string): string =>
  `${relativePath}${WINDOWS_EXECUTABLE_SUFFIX}`;

const DESKTOP_RUNTIME_TARGET_INFO = {
  macos: {
    defaultWebviewBootstrapperExecutable: null,
    hostArch: "arm64",
    hostPlatform: "darwin",
    scraperDir: DESKTOP_RUNTIME_SCRAPER_DIR,
    scriptRunnerEntrypoint: DESKTOP_RUNTIME_SCRIPT_RUNNER_ENTRYPOINT_PATH,
    scriptRunnerExecutable: DESKTOP_RUNTIME_SCRIPT_RUNNER_PATH,
    serverExecutable: DESKTOP_RUNTIME_SERVER_EXECUTABLE_PATH,
    tauriTarget: DESKTOP_RELEASE_MACOS_AARCH64_TARGET,
  },
  windows: {
    defaultWebviewBootstrapperExecutable: appendWindowsExecutableSuffix(
      DESKTOP_RUNTIME_WEBVIEW_BOOTSTRAPPER_PATH,
    ),
    hostArch: "x64",
    hostPlatform: "win32",
    scraperDir: DESKTOP_RUNTIME_SCRAPER_DIR,
    scriptRunnerEntrypoint: DESKTOP_RUNTIME_SCRIPT_RUNNER_ENTRYPOINT_PATH,
    scriptRunnerExecutable: appendWindowsExecutableSuffix(DESKTOP_RUNTIME_SCRIPT_RUNNER_PATH),
    serverExecutable: appendWindowsExecutableSuffix(DESKTOP_RUNTIME_SERVER_EXECUTABLE_PATH),
    tauriTarget: DESKTOP_RELEASE_WINDOWS_TARGET,
  },
  "linux-x64": {
    defaultWebviewBootstrapperExecutable: null,
    hostArch: "x64",
    hostPlatform: "linux",
    scraperDir: DESKTOP_RUNTIME_SCRAPER_DIR,
    scriptRunnerEntrypoint: DESKTOP_RUNTIME_SCRIPT_RUNNER_ENTRYPOINT_PATH,
    scriptRunnerExecutable: DESKTOP_RUNTIME_LINUX_BUN_PATH,
    serverExecutable: DESKTOP_RUNTIME_SERVER_EXECUTABLE_PATH,
    tauriTarget: DESKTOP_RELEASE_LINUX_X64_TARGET,
  },
  "linux-arm64": {
    defaultWebviewBootstrapperExecutable: null,
    hostArch: "arm64",
    hostPlatform: "linux",
    scraperDir: DESKTOP_RUNTIME_SCRAPER_DIR,
    scriptRunnerEntrypoint: DESKTOP_RUNTIME_SCRIPT_RUNNER_ENTRYPOINT_PATH,
    scriptRunnerExecutable: DESKTOP_RUNTIME_LINUX_BUN_PATH,
    serverExecutable: DESKTOP_RUNTIME_SERVER_EXECUTABLE_PATH,
    tauriTarget: DESKTOP_RELEASE_LINUX_ARM64_TARGET,
  },
} as const satisfies Record<DesktopRuntimeReleaseTarget, Omit<DesktopRuntimeTargetInfo, "target">>;

/**
 * Resolves the canonical runtime layout for a release target.
 */
export const resolveDesktopRuntimeTargetInfo = (
  target: DesktopRuntimeReleaseTarget,
): DesktopRuntimeTargetInfo => ({
  target,
  ...DESKTOP_RUNTIME_TARGET_INFO[target],
});

/**
 * Resolves the canonical runtime layout from a Tauri target triple.
 */
export const resolveDesktopRuntimeTargetInfoFromTauriTarget = (
  tauriTarget: string,
): DesktopRuntimeTargetInfo => {
  const resolvedTarget = DESKTOP_RELEASE_TARGETS.find(
    (target) => DESKTOP_RUNTIME_TARGET_INFO[target].tauriTarget === tauriTarget,
  );
  if (!resolvedTarget) {
    throw new Error(`Unsupported desktop Tauri target: ${tauriTarget}`);
  }

  return resolveDesktopRuntimeTargetInfo(resolvedTarget);
};

/**
 * Resolves the canonical runtime layout from the current host platform.
 */
export const resolveDesktopRuntimeTargetInfoFromHost = (
  platform: NodeJS.Platform,
  arch: string,
): DesktopRuntimeTargetInfo => {
  if (platform === "darwin") {
    return resolveDesktopRuntimeTargetInfo("macos");
  }

  if (platform === "win32") {
    return resolveDesktopRuntimeTargetInfo("windows");
  }

  if (platform === "linux") {
    return resolveDesktopRuntimeTargetInfo(arch === "arm64" ? "linux-arm64" : "linux-x64");
  }

  throw new Error(`Unsupported desktop runtime host platform: ${platform}/${arch}`);
};

/**
 * Builds the canonical desktop runtime manifest for a target.
 */
export const buildDesktopRuntimeManifest = (
  target: DesktopRuntimeReleaseTarget,
  options: {
    readonly webviewBootstrapperExecutable?: string | null;
  } = {},
): DesktopRuntimeManifest => {
  const targetInfo = resolveDesktopRuntimeTargetInfo(target);

  return {
    corsOrigins: [...DESKTOP_RUNTIME_CORS_ORIGINS],
    scraperDir: targetInfo.scraperDir,
    scriptRunnerEntrypoint: targetInfo.scriptRunnerEntrypoint,
    scriptRunnerExecutable: targetInfo.scriptRunnerExecutable,
    serverExecutable: targetInfo.serverExecutable,
    serverHost: DESKTOP_RUNTIME_HOST,
    serverPort: DESKTOP_RUNTIME_SERVER_PORT,
    webviewBootstrapperExecutable:
      options.webviewBootstrapperExecutable ?? targetInfo.defaultWebviewBootstrapperExecutable,
  };
};

/**
 * Parses and normalizes a desktop runtime manifest payload.
 */
export const parseDesktopRuntimeManifest = (
  payload: unknown,
  sourceLabel: string,
): DesktopRuntimeManifest => {
  const parsedManifest = desktopRuntimeManifestSchema.safeParse(payload);
  if (!parsedManifest.success) {
    const flattenedErrors = parsedManifest.error.issues
      .map((issue) => `${issue.path.join(".") || "<root>"}: ${issue.message}`)
      .join("; ");
    throw new Error(`Invalid desktop runtime manifest at ${sourceLabel}: ${flattenedErrors}`);
  }

  return {
    ...parsedManifest.data,
    webviewBootstrapperExecutable: parsedManifest.data.webviewBootstrapperExecutable ?? null,
  };
};

/**
 * Returns field-level mismatches between two runtime manifests.
 */
export const getDesktopRuntimeManifestMismatches = (
  actualManifest: DesktopRuntimeManifest,
  expectedManifest: DesktopRuntimeManifest,
): readonly string[] => {
  const mismatches: string[] = [];

  if (actualManifest.serverExecutable !== expectedManifest.serverExecutable) {
    mismatches.push(
      `serverExecutable expected=${expectedManifest.serverExecutable} actual=${actualManifest.serverExecutable}`,
    );
  }
  if (actualManifest.scriptRunnerExecutable !== expectedManifest.scriptRunnerExecutable) {
    mismatches.push(
      `scriptRunnerExecutable expected=${expectedManifest.scriptRunnerExecutable} actual=${actualManifest.scriptRunnerExecutable}`,
    );
  }
  if (actualManifest.scriptRunnerEntrypoint !== expectedManifest.scriptRunnerEntrypoint) {
    mismatches.push(
      `scriptRunnerEntrypoint expected=${expectedManifest.scriptRunnerEntrypoint ?? "null"} actual=${actualManifest.scriptRunnerEntrypoint ?? "null"}`,
    );
  }
  if (
    actualManifest.webviewBootstrapperExecutable !== expectedManifest.webviewBootstrapperExecutable
  ) {
    mismatches.push(
      `webviewBootstrapperExecutable expected=${expectedManifest.webviewBootstrapperExecutable ?? "null"} actual=${actualManifest.webviewBootstrapperExecutable ?? "null"}`,
    );
  }
  if (actualManifest.scraperDir !== expectedManifest.scraperDir) {
    mismatches.push(
      `scraperDir expected=${expectedManifest.scraperDir} actual=${actualManifest.scraperDir}`,
    );
  }
  if (actualManifest.serverHost !== expectedManifest.serverHost) {
    mismatches.push(
      `serverHost expected=${expectedManifest.serverHost} actual=${actualManifest.serverHost}`,
    );
  }
  if (actualManifest.serverPort !== expectedManifest.serverPort) {
    mismatches.push(
      `serverPort expected=${expectedManifest.serverPort} actual=${actualManifest.serverPort}`,
    );
  }
  if (
    actualManifest.corsOrigins.length !== expectedManifest.corsOrigins.length ||
    actualManifest.corsOrigins.some(
      (origin, index) => origin !== expectedManifest.corsOrigins[index],
    )
  ) {
    mismatches.push(
      `corsOrigins expected=${expectedManifest.corsOrigins.join(",")} actual=${actualManifest.corsOrigins.join(",")}`,
    );
  }

  return mismatches;
};

/**
 * Lists files that must exist inside the runtime resource tree for a manifest.
 */
export const listDesktopRuntimeContractPaths = (
  manifest: DesktopRuntimeManifest,
  dependencyPackageNames: readonly string[],
): readonly string[] => {
  const manifestReferencedPaths = [
    "manifest.json",
    manifest.serverExecutable,
    manifest.scriptRunnerExecutable,
    manifest.scriptRunnerEntrypoint,
    manifest.webviewBootstrapperExecutable,
    `${manifest.scraperDir}/package.json`,
    ...dependencyPackageNames.map(
      (packageName) => `${manifest.scraperDir}/node_modules/${packageName}/package.json`,
    ),
  ];

  return manifestReferencedPaths.filter(
    (path): path is string => typeof path === "string" && path.length > 0,
  );
};

import { MAX_PORT, MIN_PORT } from "../constants/ports";
import { SCHEMA_MAX_AUTOMATION_TIMEOUT_SECONDS } from "../constants/schema-limits";
import type { EmailTransportSettings } from "../types/settings";
import { isValidEmail } from "./validation";

/**
 * Returns whether a persisted outbound email transport configuration is complete enough to send mail.
 *
 * @param settings - Persisted transport settings.
 * @param hasPassword - Whether a secret password is stored alongside the public settings.
 * @returns `true` when the transport can be used for delivery.
 */
export function isEmailTransportConfigured(
  settings: EmailTransportSettings | null | undefined,
  hasPassword: boolean,
): boolean {
  if (!settings) {
    return false;
  }

  const host = settings.host.trim();
  const fromEmail = settings.fromEmail.trim();
  const username = settings.username.trim();
  const port = Math.trunc(settings.port);
  const timeout = Math.trunc(settings.connectionTimeoutSeconds);

  if (host.length === 0 || !isValidEmail(fromEmail)) {
    return false;
  }

  if (!Number.isFinite(port) || port < MIN_PORT || port > MAX_PORT) {
    return false;
  }

  if (!Number.isFinite(timeout) || timeout < 1 || timeout > SCHEMA_MAX_AUTOMATION_TIMEOUT_SECONDS) {
    return false;
  }

  if (username.length === 0) {
    return !hasPassword;
  }

  return hasPassword;
}

/**
 * Shared error message extraction. Single source of truth for server and client.
 * Handles Error, Eden/API error shapes (Record with message, value.message).
 */
import { API_ERROR_UNKNOWN } from "../constants/api-errors";
import { isRecord } from "./type-guards";

function toMessage(value: string | undefined): string | null {
  if (typeof value === "string" && value.trim().length > 0) {
    return value;
  }
  return null;
}

/**
 * Extracts a user-facing error message from boundary error values.
 * Supports Error instances, Eden API error shape (Record with message/value.message).
 *
 * @param error - Boundary error value (Error, API response, etc.)
 * @param fallback - Fallback when no message can be extracted. Defaults to API_ERROR_UNKNOWN.
 */
export function toErrorMessage<T>(error: T, fallback?: string): string {
  const resolvedFallback = fallback ?? API_ERROR_UNKNOWN;

  if (error instanceof Error) {
    return toMessage(error.message) ?? resolvedFallback;
  }

  if (typeof error === "string") {
    return toMessage(error) ?? resolvedFallback;
  }

  if (!isRecord(error)) {
    return resolvedFallback;
  }

  const direct = toMessage(typeof error.message === "string" ? error.message : undefined);
  if (direct) {
    return direct;
  }

  const nested = error.value;
  if (!isRecord(nested)) {
    return resolvedFallback;
  }

  return (
    toMessage(typeof nested.message === "string" ? nested.message : undefined) ?? resolvedFallback
  );
}

import { describe, expect, test } from "bun:test";
import {
  collectDefinedStringValues,
  formatExportDate,
  resolveResumeExportTemplate,
  toCoverLetterParagraphs,
} from "./export-contract";

describe("export contract", () => {
  test("collects only defined non-empty string values", () => {
    expect(collectDefinedStringValues(["alpha", undefined, "", " beta ", "   "])).toEqual([
      "alpha",
      " beta ",
    ]);
  });

  test("resolves the explicit resume template first", () => {
    expect(resolveResumeExportTemplate("creative", "modern")).toBe("creative");
    expect(resolveResumeExportTemplate(undefined, "modern")).toBe("modern");
    expect(resolveResumeExportTemplate("not-a-template", "modern")).toBe("modern");
    expect(resolveResumeExportTemplate("not-a-template", "also-invalid")).toBe("modern");
  });

  test("formats export dates with the shared locale contract", () => {
    expect(formatExportDate(new Date("2026-03-25T00:00:00.000Z"))).toBe("March 25, 2026");
  });

  test("normalizes canonical cover-letter content sections", () => {
    expect(
      toCoverLetterParagraphs({
        opening: "Intro",
        body: ["Impact one", "Impact two"],
        closing: "Close",
      }),
    ).toEqual(["Intro", "Impact one", "Impact two", "Close"]);
  });

  test("falls back to alternate cover-letter section names", () => {
    expect(
      toCoverLetterParagraphs({
        introduction: "Intro",
        main: ["Body"],
        conclusion: "Close",
      }),
    ).toEqual(["Intro", "Body", "Close"]);
  });

