      "First paragraph",
      "Second paragraph",
    ]);
  });
});

import { EXPORT_DATE_LOCALE } from "../constants/export-layout";
import type { ResumeTemplate } from "../constants/resume";
import { isResumeTemplate, RESUME_TEMPLATE_DEFAULT } from "../constants/resume";
import { isRecord } from "./type-guards";

const EXPORT_DATE_FORMATTER = new Intl.DateTimeFormat(EXPORT_DATE_LOCALE, {
  year: "numeric",
  month: "long",
  day: "numeric",
});

const normalizeParagraphInput = (value: unknown): string[] => {
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed.length > 0 ? [trimmed] : [];
  }

  if (Array.isArray(value)) {
    return value
      .filter((entry): entry is string => typeof entry === "string")
      .map((entry) => entry.trim())
      .filter((entry) => entry.length > 0);
  }

  return [];
};

/**
 * Collects only defined, non-empty string values.
 */
export const collectDefinedStringValues = (values: ReadonlyArray<string | undefined>): string[] =>
  values.filter((value): value is string => typeof value === "string" && value.trim().length > 0);

/**
 * Resolves the canonical resume export template from explicit and persisted values.
 */
export const resolveResumeExportTemplate = (
  templateName?: string,
  resumeTemplate?: string,
): ResumeTemplate => {
  if (isResumeTemplate(templateName)) {
    return templateName;
  }

  if (isResumeTemplate(resumeTemplate)) {
    return resumeTemplate;
  }

  return RESUME_TEMPLATE_DEFAULT;
};

/**
 * CSS theme class applied to the resume preview shell for a template.
 * Class definitions are generated from RESUME_EXPORT_THEME_CONFIGS into
 * assets/css/resume-preview.generated.css (see scripts/generate-resume-preview-css.ts).
 */
export const resumePreviewThemeClass = (template: ResumeTemplate): string =>
  `resume-preview-theme-${template}`;

/**
 * Formats export dates with the shared locale contract.
 */
export const formatExportDate = (date: Date): string => EXPORT_DATE_FORMATTER.format(date);

/**
 * Normalizes cover-letter content into canonical paragraph blocks for all export renderers.
 */
export const toCoverLetterParagraphs = (content: unknown): string[] => {
  if (typeof content === "string") {
    return content
      .split("\n\n")
      .map((entry) => entry.trim())
      .filter((entry) => entry.length > 0);
  }

  if (!isRecord(content)) {
    return [];
  }

  return [
    ...normalizeParagraphInput(content.opening).concat(
      normalizeParagraphInput(content.introduction),
    ),
    ...normalizeParagraphInput(content.body).concat(normalizeParagraphInput(content.main)),
    ...normalizeParagraphInput(content.closing).concat(normalizeParagraphInput(content.conclusion)),
  ];
};

import { describe, expect, test } from "bun:test";
import type { InterviewResponse } from "../types/interview";
import {
  resolveInterviewAnalysisAttributions,
  resolveInterviewAnalysisProvenance,
  resolveInterviewAnalysisSource,
} from "./interview-analysis-provenance";

type Analysis = NonNullable<InterviewResponse["aiAnalysis"]>;

const analyzed = (analysis: Partial<Analysis>): Pick<InterviewResponse, "aiAnalysis"> => ({
  aiAnalysis: {
    score: 0,
    feedback: "",
    strengths: [],
    improvements: [],
    source: "unknown",
    ...analysis,
  },
});

/** Averages asserted below, named so the arithmetic under test is explicit. */
const AI_AVERAGE_OF_EIGHTY_AND_NINETY = 85;
const AI_AVERAGE_OF_SINGLE_PERFECT_SCORE = 100;

describe("resolveInterviewAnalysisSource normalizes persisted markers", () => {
  test("keeps the two real markers", () => {
    expect(resolveInterviewAnalysisSource("ai")).toBe("ai");
    expect(resolveInterviewAnalysisSource("heuristic")).toBe("heuristic");
  });

  test("legacy rows without a marker never claim AI", () => {
    expect(resolveInterviewAnalysisSource(undefined)).toBe("unknown");
    expect(resolveInterviewAnalysisSource(null)).toBe("unknown");
    expect(resolveInterviewAnalysisSource("AI")).toBe("unknown");
    expect(resolveInterviewAnalysisSource(1)).toBe("unknown");
  });
});

describe("resolveInterviewAnalysisProvenance aggregates a session", () => {
  test("all-AI responses report an ai aggregate and an AI-only average", () => {
    const result = resolveInterviewAnalysisProvenance([
      analyzed({ source: "ai", score: 80 }),
      analyzed({ source: "ai", score: 90 }),
    ]);
    expect(result.analysisSource).toBe("ai");
    expect(result.aiAverageScore).toBe(AI_AVERAGE_OF_EIGHTY_AND_NINETY);
    expect(result.provenanceCounts).toEqual({ ai: 2, heuristic: 0, unknown: 0 });
  });

  test("all-heuristic responses report heuristic with no AI average", () => {
    const result = resolveInterviewAnalysisProvenance([
      analyzed({ source: "heuristic", score: 40 }),
    ]);
    expect(result.analysisSource).toBe("heuristic");
    expect(result.aiAverageScore).toBe(null);
    expect(result.provenanceCounts).toEqual({ ai: 0, heuristic: 1, unknown: 0 });
  });

  test("a mix reports mixed and averages only the AI-sourced scores", () => {
    const result = resolveInterviewAnalysisProvenance([
      analyzed({ source: "ai", score: 100 }),
      analyzed({ source: "heuristic", score: 0 }),
    ]);
    expect(result.analysisSource).toBe("mixed");
    expect(result.aiAverageScore).toBe(AI_AVERAGE_OF_SINGLE_PERFECT_SCORE);
    expect(result.provenanceCounts).toEqual({ ai: 1, heuristic: 1, unknown: 0 });
  });

  test("unattributed responses alone stay unknown, not AI", () => {
    const result = resolveInterviewAnalysisProvenance([analyzed({ score: 70 })]);
    expect(result.analysisSource).toBe("unknown");
    expect(result.aiAverageScore).toBe(null);
    expect(result.provenanceCounts).toEqual({ ai: 0, heuristic: 0, unknown: 1 });
  });

  test("an empty session is unknown with zeroed counts", () => {
    const result = resolveInterviewAnalysisProvenance([]);
    expect(result.analysisSource).toBe("unknown");
    expect(result.aiAverageScore).toBe(null);
    expect(result.provenanceCounts).toEqual({ ai: 0, heuristic: 0, unknown: 0 });
  });

  test("responses with no analysis at all are ignored entirely", () => {
    const result = resolveInterviewAnalysisProvenance([{}, analyzed({ source: "ai", score: 60 })]);
    expect(result.analysisSource).toBe("ai");
    expect(result.provenanceCounts).toEqual({ ai: 1, heuristic: 0, unknown: 0 });
  });
});

describe("resolveInterviewAnalysisAttributions names only real AI calls", () => {
  test("returns distinct provider/model pairs in first-seen order", () => {
    expect(
      resolveInterviewAnalysisAttributions([
        analyzed({ source: "ai", provider: "claude", model: "claude-opus-5" }),
        analyzed({ source: "ai", provider: "claude", model: "claude-opus-5" }),
        analyzed({ source: "ai", provider: "openai", model: "gpt-x" }),
      ]),
    ).toEqual([
      { provider: "claude", model: "claude-opus-5" },
      { provider: "openai", model: "gpt-x" },
    ]);
  });

  test("heuristic responses never contribute an attribution", () => {
    expect(
      resolveInterviewAnalysisAttributions([
        analyzed({ source: "heuristic", provider: "claude", model: "claude-opus-5" }),
      ]),
    ).toEqual([]);
  });

  test("AI responses with no recorded provider or model are omitted", () => {
    expect(resolveInterviewAnalysisAttributions([analyzed({ source: "ai" })])).toEqual([]);
  });

  test("a partial attribution still surfaces what is known", () => {
    expect(
      resolveInterviewAnalysisAttributions([analyzed({ source: "ai", provider: "local" })]),
    ).toEqual([{ provider: "local", model: "" }]);
  });

  test("an empty session yields no attributions", () => {
    expect(resolveInterviewAnalysisAttributions([])).toEqual([]);
  });
});

import type {
  InterviewAnalysisAggregateSource,
  InterviewAnalysisProvenanceCounts,
  InterviewAnalysisSource,
  InterviewResponse,
} from "../types/interview";

/**
 * Aggregated provenance for a set of analyzed interview responses.
 */
export interface InterviewAnalysisProvenance {
  analysisSource: InterviewAnalysisAggregateSource;
  aiAverageScore: number | null;
  provenanceCounts: InterviewAnalysisProvenanceCounts;
}

type AnalyzableResponse = Pick<InterviewResponse, "aiAnalysis">;

/**
 * Normalizes a persisted analysis source tag; legacy rows without a stored
 * source read as "unknown".
 */
export const resolveInterviewAnalysisSource = (value: unknown): InterviewAnalysisSource =>
  value === "ai" || value === "heuristic" ? value : "unknown";

const resolveAggregateSource = (
  counts: InterviewAnalysisProvenanceCounts,
): InterviewAnalysisAggregateSource => {
  if (counts.ai > 0 && counts.heuristic === 0 && counts.unknown === 0) {
    return "ai";
  }
  if (counts.ai === 0 && counts.heuristic > 0 && counts.unknown === 0) {
    return "heuristic";
  }
  if (counts.ai === 0 && counts.heuristic === 0) {
    return "unknown";
  }
  return "mixed";
};

/**
 * Aggregates per-response analysis provenance into session-level fields.
 * `aiAverageScore` is the mean of AI-sourced response scores only, or null
 * when no response was analyzed by a real AI provider.
 */
export const resolveInterviewAnalysisProvenance = (
  responses: readonly AnalyzableResponse[],
): InterviewAnalysisProvenance => {
  const provenanceCounts: InterviewAnalysisProvenanceCounts = {
    ai: 0,
    heuristic: 0,
    unknown: 0,
  };
  let aiScoreTotal = 0;

  for (const response of responses) {
    const analysis = response.aiAnalysis;
    if (!analysis) {
      continue;
    }
    const source = resolveInterviewAnalysisSource(analysis.source);
    provenanceCounts[source] += 1;
    if (source === "ai") {
      aiScoreTotal += analysis.score;
    }
  }

  return {
    analysisSource: resolveAggregateSource(provenanceCounts),
    aiAverageScore: provenanceCounts.ai > 0 ? Math.round(aiScoreTotal / provenanceCounts.ai) : null,
    provenanceCounts,
  };
};

/**
 * A distinct provider/model pair that contributed an AI-sourced assessment.
 */
export interface InterviewAnalysisAttribution {
  provider: string;
  model: string;
}

/**
 * Lists the distinct provider/model pairs behind the AI-sourced responses in a
 * session, in first-seen order. Heuristic and unattributed responses contribute
 * nothing, so a session with no real AI call yields an empty list and the UI
 * states that rather than implying a model it cannot name.
 */
export const resolveInterviewAnalysisAttributions = (
  responses: readonly AnalyzableResponse[],
): InterviewAnalysisAttribution[] => {
  const seen = new Set<string>();
  const attributions: InterviewAnalysisAttribution[] = [];

  for (const response of responses) {
    const analysis = response.aiAnalysis;
    if (!analysis || resolveInterviewAnalysisSource(analysis.source) !== "ai") {
      continue;
    }
    const provider = analysis.provider ?? "";
    const model = analysis.model ?? "";
    if (provider.length === 0 && model.length === 0) {
      continue;
    }
    const key = `${provider}�${model}`;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    attributions.push({ provider, model });
  }

  return attributions;
};

import { JOB_TYPES } from "../constants/jobs";
import type { JobType } from "../types/jobs";

/**
 * Canonical job-type guard: membership in the shared JOB_TYPES contract.
 */
export const isJobType = (value: unknown): value is JobType =>
  typeof value === "string" && JOB_TYPES.some((jobType) => jobType === value);

/**
 * Normalizes an untrusted boundary value (API payload, DB row) to a JobType,
 * falling back to "full-time" when the value is not a known job type.
 */
export const normalizeJobType = (value: unknown): JobType =>
  isJobType(value) ? value : "full-time";

import type { z } from "zod";
import { safeParseJson } from "./json";

/** Outcome of {@link parseJsonExplained}: the value, or why it could not be produced. */
export type ExplainedJsonParse<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly reason: string };

/**
 * Validates JSON against a Zod schema and reports why it failed.
 *
 * `parseJson` collapses malformed JSON and schema violations alike to `null`, so a
 * caller can only report "invalid". That is what made a failing job-provider settings
 * save undiagnosable: the toast said "Provider configuration JSON is invalid" without
 * naming the collection or the offending field. Use this wherever the failure is shown
 * to a person.
 */
export function parseJsonExplained<T>(json: string, schema: z.ZodType<T>): ExplainedJsonParse<T> {
  const parsed = safeParseJson(json);
  if (parsed === null) {
    return { ok: false, reason: "not valid JSON" };
  }

  const result = schema.safeParse(parsed);
  if (result.success) {
    return { ok: true, value: result.data };
  }

  const [firstIssue] = result.error.issues;
  if (!firstIssue) {
    return { ok: false, reason: "failed schema validation" };
  }

  const path = firstIssue.path.join(".");
  return {
    ok: false,
    reason: path.length > 0 ? `${path}: ${firstIssue.message}` : firstIssue.message,
  };
}

import type { z } from "zod";
import {
  COUNT_SIXTEEN,
  UNICODE_ESCAPE_HEX_DIGITS,
  UNICODE_ESCAPE_SEQUENCE_LENGTH,
} from "../constants/numeric";

const UNICODE_HEX_RADIX = COUNT_SIXTEEN;

/**
 * Primitive JSON value.
 */
export type JsonPrimitive = string | number | boolean | null;

/**
 * Object JSON value.
 */
export interface JsonObject {
  [key: string]: JsonValue;
}

/**
 * Array JSON value.
 */
export type JsonArray = JsonValue[];

/**
 * JSON value.
 */
export type JsonValue = JsonPrimitive | JsonObject | JsonArray;

type ParseSuccess<T extends JsonValue> = {
  ok: true;
  value: T;
  index: number;
};

type ParseFailure = {
  ok: false;
  index: number;
};

type ParseResult<T extends JsonValue> = ParseSuccess<T> | ParseFailure;

type EscapeParseResult =
  | {
      ok: true;
      value: string;
      nextCursor: number;
    }
  | {
      ok: false;
      index: number;
    };

const ESCAPE_MAP: Record<string, string> = {
  '"': '"',
  "\\": "\\",
  "/": "/",
  b: "\b",
  f: "\f",
  n: "\n",
  r: "\r",
  t: "\t",
};

const isWhitespace = (char: string | undefined): boolean =>
  char === " " || char === "\n" || char === "\r" || char === "\t";

const isDigit = (char: string | undefined): boolean =>
  typeof char === "string" && char >= "0" && char <= "9";

const isHexDigit = (char: string): boolean =>
  (char >= "0" && char <= "9") || (char >= "a" && char <= "f") || (char >= "A" && char <= "F");

const isControlCharacter = (char: string): boolean => char <= "\u001F";

function skipWhitespace(input: string, index: number): number {
  let cursor = index;
  while (cursor < input.length && isWhitespace(input[cursor])) {
    cursor += 1;
  }
  return cursor;
}

function parseUnicodeEscape(input: string, cursor: number): EscapeParseResult {
  const unicode = input.slice(cursor + 2, cursor + UNICODE_ESCAPE_SEQUENCE_LENGTH);
  if (unicode.length !== UNICODE_ESCAPE_HEX_DIGITS || !unicode.split("").every(isHexDigit)) {
    return { ok: false, index: cursor };
  }
  return {
    ok: true,
    value: String.fromCodePoint(Number.parseInt(unicode, UNICODE_HEX_RADIX)),
    nextCursor: cursor + UNICODE_ESCAPE_SEQUENCE_LENGTH,
  };
}

function parseMappedEscape(escaped: string, cursor: number): EscapeParseResult {
  const replacement = ESCAPE_MAP[escaped];
  if (replacement === undefined) {
    return { ok: false, index: cursor };
  }
  return {
    ok: true,
    value: replacement,
    nextCursor: cursor + 2,
  };
}

function parseEscapedToken(input: string, cursor: number): EscapeParseResult {
  const escaped = input[cursor + 1];
  if (!escaped) {
    return { ok: false, index: cursor };
  }
  if (escaped === "u") {
    return parseUnicodeEscape(input, cursor);
  }
  return parseMappedEscape(escaped, cursor);
}

function parseString(input: string, startIndex: number): ParseResult<string> {
  if (input[startIndex] !== '"') {
    return { ok: false, index: startIndex };
  }

  let cursor = startIndex + 1;
  let value = "";

  while (cursor < input.length) {
    const char = input[cursor];
    if (!char) {
      return { ok: false, index: cursor };
    }

    if (char === '"') {
      return { ok: true, value, index: cursor + 1 };
    }

    if (char === "\\") {
      const escapedResult = parseEscapedToken(input, cursor);
      if (!escapedResult.ok) {
        return { ok: false, index: escapedResult.index };
      }
      value += escapedResult.value;
      cursor = escapedResult.nextCursor;
      continue;
    }

    if (isControlCharacter(char)) {
      return { ok: false, index: cursor };
    }

    value += char;
    cursor += 1;
  }

  return { ok: false, index: cursor };
}

function parseLiteral<T extends JsonPrimitive>(
  input: string,
  startIndex: number,
  literal: string,
  value: T,
): ParseResult<T> {
  if (input.slice(startIndex, startIndex + literal.length) !== literal) {
    return { ok: false, index: startIndex };
  }
  return { ok: true, value, index: startIndex + literal.length };
}

function consumeOptionalMinus(input: string, cursor: number): number {
  return input[cursor] === "-" ? cursor + 1 : cursor;
}

function consumeIntegerPart(input: string, cursor: number): number | null {
  if (input[cursor] === "0") {
    return cursor + 1;
  }
  if (!isDigit(input[cursor])) {
    return null;
  }

  let nextCursor = cursor;
  while (isDigit(input[nextCursor])) {
    nextCursor += 1;
  }
  return nextCursor;
}

function consumeFractionPart(input: string, cursor: number): number | null {
  if (input[cursor] !== ".") {
    return cursor;
  }
  const nextCursor = cursor + 1;
  if (!isDigit(input[nextCursor])) {
    return null;
  }
  let fractionCursor = nextCursor;
  while (isDigit(input[fractionCursor])) {
    fractionCursor += 1;
  }
  return fractionCursor;
}

function consumeExponentPart(input: string, cursor: number): number | null {
  const exponentToken = input[cursor];
  if (!(exponentToken === "e" || exponentToken === "E")) {
    return cursor;
  }

  let exponentCursor = cursor + 1;
  const signToken = input[exponentCursor];
  if (signToken === "+" || signToken === "-") {
    exponentCursor += 1;
  }
  if (!isDigit(input[exponentCursor])) {
    return null;
  }
  while (isDigit(input[exponentCursor])) {
    exponentCursor += 1;
  }
  return exponentCursor;
}

function parseNumber(input: string, startIndex: number): ParseResult<number> {
  const integerStart = consumeOptionalMinus(input, startIndex);
  const integerCursor = consumeIntegerPart(input, integerStart);
  if (integerCursor === null) {
    return { ok: false, index: startIndex };
  }

  const fractionCursor = consumeFractionPart(input, integerCursor);
  if (fractionCursor === null) {
    return { ok: false, index: startIndex };
  }

  const cursor = consumeExponentPart(input, fractionCursor);
  if (cursor === null) {
    return { ok: false, index: startIndex };
  }

  const parsedValue = Number(input.slice(startIndex, cursor));
  if (!Number.isFinite(parsedValue)) {
    return { ok: false, index: startIndex };
  }

  return { ok: true, value: parsedValue, index: cursor };
}

function parseArray(input: string, startIndex: number): ParseResult<JsonArray> {
  if (input[startIndex] !== "[") {
    return { ok: false, index: startIndex };
  }

  let cursor = skipWhitespace(input, startIndex + 1);
  const values: JsonArray = [];

  if (input[cursor] === "]") {
    return { ok: true, value: values, index: cursor + 1 };
  }

  while (cursor < input.length) {
    const item = parseValue(input, cursor);
    if (!item.ok) {
      return { ok: false, index: item.index };
    }
    values.push(item.value);

    cursor = skipWhitespace(input, item.index);
    const separator = input[cursor];
    if (separator === ",") {
      cursor = skipWhitespace(input, cursor + 1);
      continue;
    }
    if (separator === "]") {
      return { ok: true, value: values, index: cursor + 1 };
    }
    return { ok: false, index: cursor };
  }

  return { ok: false, index: cursor };
}

function parseObject(input: string, startIndex: number): ParseResult<JsonObject> {
  if (input[startIndex] !== "{") {
    return { ok: false, index: startIndex };
  }

  let cursor = skipWhitespace(input, startIndex + 1);
  const output: JsonObject = {};

  if (input[cursor] === "}") {
    return { ok: true, value: output, index: cursor + 1 };
  }

  while (cursor < input.length) {
    const keyResult = parseString(input, cursor);
    if (!keyResult.ok) {
      return { ok: false, index: keyResult.index };
    }

    cursor = skipWhitespace(input, keyResult.index);
    if (input[cursor] !== ":") {
      return { ok: false, index: cursor };
    }

    cursor = skipWhitespace(input, cursor + 1);
    const valueResult = parseValue(input, cursor);
    if (!valueResult.ok) {
      return { ok: false, index: valueResult.index };
    }

    output[keyResult.value] = valueResult.value;
    cursor = skipWhitespace(input, valueResult.index);

    const separator = input[cursor];
    if (separator === ",") {
      cursor = skipWhitespace(input, cursor + 1);
      continue;
    }
    if (separator === "}") {
      return { ok: true, value: output, index: cursor + 1 };
    }
    return { ok: false, index: cursor };
  }

  return { ok: false, index: cursor };
}

function parseValue(input: string, startIndex: number): ParseResult<JsonValue> {
  const cursor = skipWhitespace(input, startIndex);
  const token = input[cursor];

  if (!token) {
    return { ok: false, index: cursor };
  }

  if (token === '"') {
    return parseString(input, cursor);
  }
  if (token === "{") {
    return parseObject(input, cursor);
  }
  if (token === "[") {
    return parseArray(input, cursor);
  }
  if (token === "t") {
    return parseLiteral(input, cursor, "true", true);
  }
  if (token === "f") {
    return parseLiteral(input, cursor, "false", false);
  }
  if (token === "n") {
    return parseLiteral(input, cursor, "null", null);
  }
  if (token === "-" || isDigit(token)) {
    return parseNumber(input, cursor);
  }

  return { ok: false, index: cursor };
}

function parseJsonValue(json: string): JsonValue | null {
  const valueResult = parseValue(json, 0);
  if (!valueResult.ok) {
    return null;
  }

  const trailingIndex = skipWhitespace(json, valueResult.index);
  if (trailingIndex !== json.length) {
    return null;
  }

  return valueResult.value;
}

/**
 * Safely parses JSON without throwing. Returns null on invalid input.
 */
export function safeParseJson(json: string): JsonValue | null {
  if (typeof json !== "string" || json.trim().length === 0) {
    return null;
  }
  return parseJsonValue(json);
}

/**
 * Parses JSON and validates with a Zod schema. Returns null on parse or validation failure.
 */
export function parseJson<T>(json: string, schema: z.ZodType<T>): T | null {
  const parsed = safeParseJson(json);
  if (parsed === null) return null;
  const result = schema.safeParse(parsed);
  return result.success ? result.data : null;
}

import { describe, expect, test } from "bun:test";
