describe("local AI endpoint validation", () => {
  test("allows loopback Ollama-style endpoints", () => {
    expect(validateLocalAiEndpoint("http://localhost:11434/v1")).toEqual({
      ok: true,
      endpoint: "http://localhost:11434/v1",
    });
    expect(validateLocalAiEndpoint("http://127.0.0.1:1234")).toEqual({
      ok: true,
      endpoint: "http://127.0.0.1:1234/",
    });
  });

  test("denies non-loopback and credentialed URLs", () => {
    const credentialed = new URL("http://localhost:11434/v1");
    credentialed.username = "probe-user";
    credentialed.password = "x";
    expect(validateLocalAiEndpoint("http://169.254.169.254/latest").ok).toEqual(false);
    expect(validateLocalAiEndpoint("http://metadata.google.internal/").ok).toEqual(false);
    expect(validateLocalAiEndpoint("http://example.com/v1").ok).toEqual(false);
    expect(validateLocalAiEndpoint(credentialed.toString()).ok).toEqual(false);
    expect(validateLocalAiEndpoint("file:///tmp/not-a-model").ok).toEqual(false);
  });
});

import { LOOPBACK_HOST, LOOPBACK_HOST_IPV4, LOOPBACK_HOST_IPV6 } from "../constants/runtime";

export type LocalAiEndpointValidationResult =
  | { readonly ok: true; readonly endpoint: string }
  | {
      readonly ok: false;
      readonly code: "INVALID_URL" | "DISALLOWED_PROTOCOL" | "DISALLOWED_HOST" | "CREDENTIALS";
    };

const ALLOWED_LOCAL_AI_HOSTS = new Set<string>([
  LOOPBACK_HOST,
  LOOPBACK_HOST_IPV4,
  LOOPBACK_HOST_IPV6,
]);

/**
 * Validates a local-inference endpoint for server-side fetch.
 * Default-deny: only loopback hosts may be probed (SSRF fail-closed).
 */
export const validateLocalAiEndpoint = (rawEndpoint: string): LocalAiEndpointValidationResult => {
  const trimmed = rawEndpoint.trim();
  if (!trimmed || !URL.canParse(trimmed)) {
    return { ok: false, code: "INVALID_URL" };
  }

  const parsed = new URL(trimmed);
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    return { ok: false, code: "DISALLOWED_PROTOCOL" };
  }

  if (parsed.username || parsed.password) {
    return { ok: false, code: "CREDENTIALS" };
  }

  const host = parsed.hostname.toLowerCase();
  if (!ALLOWED_LOCAL_AI_HOSTS.has(host)) {
    return { ok: false, code: "DISALLOWED_HOST" };
  }

  return { ok: true, endpoint: parsed.toString() };
};

import { deflateSync } from "node:zlib";
import { describe, expect, it } from "bun:test";
import {
  extractPdfContentStreams,
  isZlibCompressed,
  pdfRgbFillOperator,
  pdfStreamsContainRgbFill,
} from "./pdf-streams";

const wrapPdfStreams = (bodies: readonly Buffer[]): Uint8Array => {
  const parts = bodies.map(
    (body) => `stream\n${body.toString("latin1")}\nendstream`,
  );
  return Buffer.from(parts.join("\n"), "latin1");
};

describe("pdf-streams", () => {
  it("detects RFC 1950 zlib headers and rejects raw bodies", () => {
    const compressed = deflateSync(Buffer.from("0.2 0.4 0.6 rg", "latin1"));
    expect(isZlibCompressed(compressed)).toBe(true);
    expect(isZlibCompressed(Buffer.from("BT /F1 12 Tf", "latin1"))).toBe(false);
    expect(isZlibCompressed(Buffer.from(""))).toBe(false);
  });

  it("decodes inflated streams and passes raw streams through", () => {
    const compressed = deflateSync(Buffer.from("0.16 0.38 1 rg", "latin1"));
    const raw = Buffer.from("0 0.59 0.53 rg", "latin1");
    const decoded = extractPdfContentStreams(wrapPdfStreams([compressed, raw]));
    expect(decoded).toContain("0.16 0.38 1 rg");
    expect(decoded).toContain("0 0.59 0.53 rg");
  });

  it("matches exact RGB fill operators only", () => {
    const compressed = deflateSync(Buffer.from("0.54 0.17 0.89 rg", "latin1"));
    const pdf = wrapPdfStreams([compressed]);
    expect(pdfRgbFillOperator({ r: 0.54, g: 0.17, b: 0.89 })).toBe("0.54 0.17 0.89 rg");
    expect(pdfStreamsContainRgbFill(pdf, { r: 0.54, g: 0.17, b: 0.89 })).toBe(true);
    expect(pdfStreamsContainRgbFill(pdf, { r: 0.1, g: 0.2, b: 0.3 })).toBe(false);
  });
});

/**
 * PDF content-stream decoding utilities.
 * Canonical owner for stream inflation used by export theme tests (server)
 * and live PDF assertion helpers (scripts). pdf-lib writes FlateDecode
 * (RFC 1950 zlib) streams; uncompressed streams pass through raw.
 */
import { inflateSync } from "node:zlib";

const STREAM_BODY_PATTERN = /stream\r?\n([\s\S]*?)\r?\nendstream/g;

/** RFC 1950 zlib CMF byte: deflate, 32 KiB window. */
const ZLIB_CMF = 0x78;
/** RFC 1950 FCHECK: (CMF * 256 + FLG) must be a multiple of 31. */
const ZLIB_FCHECK_MODULUS = 31;
/** CMF/FLG are packed big-endian into a 16-bit header word. */
const HEADER_BYTE_RADIX = 256;

/**
 * True when the stream body carries a valid RFC 1950 zlib header.
 * Sniffing replaces a throw-probe: only header-valid bodies are inflated.
 */
export const isZlibCompressed = (body: Buffer): boolean =>
  body.length > 1 &&
  body[0] === ZLIB_CMF &&
  (body[0] * HEADER_BYTE_RADIX + body[1]) % ZLIB_FCHECK_MODULUS === 0;

/**
 * Decode all PDF stream bodies (inflated when compressed) into one latin1 string.
 */
export const extractPdfContentStreams = (pdfBytes: Uint8Array): string => {
  const source = Buffer.from(pdfBytes).toString("latin1");
  const chunks: string[] = [];
  for (const match of source.matchAll(STREAM_BODY_PATTERN)) {
    const body = Buffer.from(match[1] ?? "", "latin1");
    chunks.push(
      isZlibCompressed(body) ? inflateSync(body).toString("latin1") : body.toString("latin1"),
    );
  }
  return chunks.join("\n");
};

/**
 * Build a pdf-lib fill operator needle for an RGB triple (e.g. "0.62 0.18 0.42 rg").
 */
export const pdfRgbFillOperator = (color: {
  readonly r: number;
  readonly g: number;
  readonly b: number;
}): string => `${String(color.r)} ${String(color.g)} ${String(color.b)} rg`;

/**
 * True when inflated PDF streams include the exact fill operator for the color.
 */
export const pdfStreamsContainRgbFill = (
  pdfBytes: Uint8Array,
  color: { readonly r: number; readonly g: number; readonly b: number },
): boolean => extractPdfContentStreams(pdfBytes).includes(pdfRgbFillOperator(color));

/** A single drawn text run: the decoded string plus the font size in effect. */
export type PdfTextRun = {
  readonly text: string;
  readonly fontName: string;
  readonly fontSize: number;
};

/** `/Helvetica-Bold-123 18 Tf` selects a font; `<48656C6C6F> Tj` draws hex text. */
const TEXT_OPERATOR_PATTERN = /\/([^\s/]+)\s+([\d.]+)\s+Tf|<([\dA-Fa-f]*)>\s*Tj/gu;
/** Hex string radix used by PDF `<...>` string literals. */
const PDF_HEX_RADIX = 16;
/** Each PDF hex literal character occupies two hex digits. */
const PDF_HEX_PAIR_LENGTH = 2;

const decodePdfHexString = (hex: string): string => {
  let decoded = "";
  for (let index = 0; index + PDF_HEX_PAIR_LENGTH <= hex.length; index += PDF_HEX_PAIR_LENGTH) {
    decoded += String.fromCharCode(
      Number.parseInt(hex.slice(index, index + PDF_HEX_PAIR_LENGTH), PDF_HEX_RADIX),
    );
  }
  return decoded;
};

/**
 * Decode every drawn text run with the font size active when it was drawn.
 * Lets export tests assert rendered geometry (per-layout sizes) rather than
 * colour alone, so a layout constant that is imported but never applied fails.
 */
export const extractPdfTextRuns = (pdfBytes: Uint8Array): PdfTextRun[] => {
  const streams = extractPdfContentStreams(pdfBytes);
  const runs: PdfTextRun[] = [];
  let activeFontName = "";
  let activeFontSize = 0;

  TEXT_OPERATOR_PATTERN.lastIndex = 0;
  for (const match of streams.matchAll(TEXT_OPERATOR_PATTERN)) {
    const [, fontName, fontSize, hexText] = match;
    if (fontName !== undefined && fontSize !== undefined) {
      activeFontName = fontName;
      activeFontSize = Number.parseFloat(fontSize);
      continue;
    }
    if (hexText !== undefined) {
      runs.push({
        text: decodePdfHexString(hexText),
        fontName: activeFontName,
        fontSize: activeFontSize,
      });
    }
  }

  return runs;
};

/** Font size the given text was drawn at, or null when the text is absent. */
export const pdfTextRunFontSize = (pdfBytes: Uint8Array, text: string): number | null =>
  extractPdfTextRuns(pdfBytes).find((run) => run.text === text)?.fontSize ?? null;

