import { join } from "node:path";

/**
 * Filesystem dependencies for the deterministic Chromium probe (injectable
 * so tests can run without touching a real browser cache).
 */
export type ChromiumExecutableProbeDeps = {
  pathExists: (candidatePath: string) => boolean;
  readDir: (directoryPath: string) => string[];
};

const CHROMIUM_BUILD_DIR_PATTERN = /^chromium(?:_headless_shell)?-\d+$/;
const REVISION_NUMBER_PATTERN = /\d+$/;

/**
 * Current Playwright builds ship "Google Chrome for Testing.app" on macOS and
 * `headless_shell` in a separate `chromium_headless_shell-<rev>` directory.
 * The older `Chromium.app` names are kept so pinned older caches still resolve.
 */
const EXECUTABLE_RELATIVE_PATHS: Readonly<Record<string, readonly string[]>> = {
  darwin: [
    "chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing",
    "chrome-mac/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing",
    "chrome-mac-arm64/Chromium.app/Contents/MacOS/Chromium",
    "chrome-mac/Chromium.app/Contents/MacOS/Chromium",
    "chrome-mac-arm64/headless_shell",
    "chrome-mac/headless_shell",
  ],
  linux: [
    "chrome-linux/chrome",
    "chrome-linux/headless_shell",
    "chrome-linux-arm64/chrome",
    "chrome-linux-arm64/headless_shell",
  ],
  win32: ["chrome-win/chrome.exe", "chrome-win/headless_shell.exe"],
};

const FALLBACK_EXECUTABLE_RELATIVE_PATHS: readonly string[] = [
  "chrome-linux/chrome",
  "chrome-linux/headless_shell",
];

const revisionOf = (directoryName: string): number => {
  const match = REVISION_NUMBER_PATTERN.exec(directoryName);
  return match ? Number.parseInt(match[0], 10) : 0;
};

const executableRelativePaths = (platform: NodeJS.Platform): readonly string[] =>
  EXECUTABLE_RELATIVE_PATHS[platform] ?? FALLBACK_EXECUTABLE_RELATIVE_PATHS;

/**
 * Resolves the Playwright-managed Chromium executable inside a browsers
 * directory without launching a browser. Returns null when no Chromium
 * build is installed.
 */
export const resolvePlaywrightChromiumExecutable = (
  browsersPath: string,
  platform: NodeJS.Platform,
  deps: ChromiumExecutableProbeDeps,
): string | null => {
  if (!deps.pathExists(browsersPath)) {
    return null;
  }

  const buildDirs = deps
    .readDir(browsersPath)
    .filter((entry) => CHROMIUM_BUILD_DIR_PATTERN.test(entry))
    .sort((left, right) => revisionOf(right) - revisionOf(left));

  for (const buildDir of buildDirs) {
    for (const relativePath of executableRelativePaths(platform)) {
      const candidate = join(browsersPath, buildDir, relativePath);
      if (deps.pathExists(candidate)) {
        return candidate;
      }
    }
  }

  return null;
};

/**
 * SSRF gate coverage for the loopback / RFC 1918 host check.
 *
 * The 172.16.0.0/12 branch previously compared the first octet against an
 * arithmetic expression that evaluated to 180, so every 172.16–172.31 address
 * was treated as public. Nothing exercised that range, so the hole was silent.
 */
import { describe, expect, test } from "bun:test";
import { COUNT_SIXTEEN, COUNT_THIRTY_ONE } from "../constants/numeric";
import { isLoopbackOrPrivateHost } from "./private-host";

describe("isLoopbackOrPrivateHost", () => {
  test("blocks loopback hosts", () => {
    for (const hostname of ["localhost", "127.0.0.1", "127.10.20.30", "app.localhost"]) {
      expect(isLoopbackOrPrivateHost(hostname)).toBe(true);
    }
  });

  test("blocks RFC 1918 10.0.0.0/8", () => {
    for (const hostname of ["10.0.0.1", "10.255.255.254"]) {
      expect(isLoopbackOrPrivateHost(hostname)).toBe(true);
    }
  });

  test("blocks RFC 1918 192.168.0.0/16", () => {
    expect(isLoopbackOrPrivateHost("192.168.1.1")).toBe(true);
  });

  test("blocks every second octet of RFC 1918 172.16.0.0/12", () => {
    for (let secondOctet = COUNT_SIXTEEN; secondOctet <= COUNT_THIRTY_ONE; secondOctet += 1) {
      expect(isLoopbackOrPrivateHost(`172.${String(secondOctet)}.0.1`)).toBe(true);
    }
  });

  test("allows public addresses just outside 172.16.0.0/12", () => {
    expect(isLoopbackOrPrivateHost("172.15.0.1")).toBe(false);
    expect(isLoopbackOrPrivateHost("172.32.0.1")).toBe(false);
  });

  test("allows ordinary public hosts", () => {
    for (const hostname of ["example.com", "8.8.8.8", "203.0.113.10"]) {
      expect(isLoopbackOrPrivateHost(hostname)).toBe(false);
    }
  });
});

import { DECIMAL_RADIX } from "../constants/client-config";
import {
  COUNT_FOUR,
  COUNT_SIXTEEN,
  COUNT_THIRTY_ONE,
  COUNT_TWO_FIFTY_FIVE,
} from "../constants/numeric";
import { LOOPBACK_HOST, LOOPBACK_HOST_IPV4, LOOPBACK_HOST_IPV6 } from "../constants/runtime";

/** IPv4 octet boundaries for loopback, RFC 1918, and link-local ranges. */
const LOOPBACK_FIRST_OCTET = 127;
const PRIVATE_FIRST_OCTET_A = 10;
const PRIVATE_FIRST_OCTET_B = 172;
const PRIVATE_FIRST_OCTET_C = 192;
const PRIVATE_C_SECOND_OCTET = 168;
const LINK_LOCAL_FIRST_OCTET = 169;
const LINK_LOCAL_SECOND_OCTET = 254;

const IP_SEGMENT_PATTERN = /^\d+$/;
const LOCALHOST_SUFFIX_PATTERN = /\.localhost$/i;
const INTERNAL_SUFFIX_PATTERN = /\.internal$/i;
const IPV6_PRIVATE_PREFIX_PATTERN = /^(fc|fd|fe80)/i;

/**
 * Parses a dotted-quad IPv4 host into numeric octets, or null when the host
 * is not a canonical IPv4 literal.
 */
const parseIpv4Segments = (hostname: string): number[] | null => {
  const segments = hostname.split(".");
  if (segments.length !== COUNT_FOUR) {
    return null;
  }

  const parsed: number[] = [];
  for (const segment of segments) {
    if (!IP_SEGMENT_PATTERN.test(segment)) {
      return null;
    }
    const value = Number.parseInt(segment, DECIMAL_RADIX);
    if (!Number.isFinite(value) || value < 0 || value > COUNT_TWO_FIFTY_FIVE) {
      return null;
    }
    parsed.push(value);
  }
  return parsed;
};

const isPrivateOrLoopbackIpv4 = (segments: number[]): boolean => {
  const [first = 0, second = 0] = segments;
  if (first === LOOPBACK_FIRST_OCTET || first === PRIVATE_FIRST_OCTET_A) {
    return true;
  }
  if (first === PRIVATE_FIRST_OCTET_C && second === PRIVATE_C_SECOND_OCTET) {
    return true;
  }
  if (first === LINK_LOCAL_FIRST_OCTET && second === LINK_LOCAL_SECOND_OCTET) {
    return true;
  }
  return (
    first === PRIVATE_FIRST_OCTET_B && second >= COUNT_SIXTEEN && second <= COUNT_THIRTY_ONE
  );
};

/**
 * Returns true when a URL hostname is loopback, RFC 1918 private space, or
 * link-local. Used to fail closed before sending candidate data to
 * automation targets.
 */
export const isLoopbackOrPrivateHost = (rawHostname: string): boolean => {
  const hostname = rawHostname.trim().toLowerCase();
  if (hostname.length === 0) {
    return false;
  }

  if (
    hostname === LOOPBACK_HOST ||
    hostname === LOOPBACK_HOST_IPV4 ||
    hostname === LOOPBACK_HOST_IPV6 ||
    hostname === "localhost.localdomain" ||
    LOCALHOST_SUFFIX_PATTERN.test(hostname) ||
    INTERNAL_SUFFIX_PATTERN.test(hostname) ||
    IPV6_PRIVATE_PREFIX_PATTERN.test(hostname)
  ) {
    return true;
  }

  const ipv4Segments = parseIpv4Segments(hostname);
  if (!ipv4Segments) {
    return false;
  }
  return isPrivateOrLoopbackIpv4(ipv4Segments);
};

/**
 * Wraps a single Promise in Promise.allSettled and returns the first (and only) result.
 * Used for consistent error handling without try-catch.
 * Rejection reasons are normalized to Error at the boundary (throw-safe).
 */

export type SettledResult<T> =
  | { status: "fulfilled"; value: T }
  | { status: "rejected"; reason: Error };

export const settle = async <T>(operation: Promise<T>): Promise<SettledResult<T>> => {
  const outcomes = await Promise.allSettled([operation]);
  const result = outcomes[0];
  if (!result) {
    return { status: "rejected", reason: new Error("settle produced no outcome") };
  }
  if (result.status === "fulfilled") {
    return { status: "fulfilled", value: result.value };
  }

  const rejection: { reason?: Error | string | number | boolean | null | object } = result;
  const reason = rejection.reason;
  if (reason instanceof Error) {
    return { status: "rejected", reason };
  }
  if (typeof reason === "string") {
    return { status: "rejected", reason: new Error(reason) };
  }
  if (typeof reason === "number" || typeof reason === "boolean") {
    return { status: "rejected", reason: new Error(String(reason)) };
  }
  if (reason === null || reason === undefined) {
    return { status: "rejected", reason: new Error("null rejection") };
  }
  return { status: "rejected", reason: new Error("object rejection") };
};

import {
  RESUME_TEMPLATE_DEFAULT,
  type ResumeTemplate,
  isResumeTemplate,
} from "../constants/resume";
import type {
  GamingExperience,
  ResumeData,
  ResumeEducationItem,
  ResumeExperienceItem,
  ResumePersonalInfo,
  ResumeProject,
  ResumeSkills,
} from "../types/resume";

/**
 * Form data structure used by resume builder (flat + form-specific shapes).
 */
export interface ResumeFormData {
  name: string;
  email: string;
  phone: string;
  location: string;
  summary: string;
  linkedIn: string;
  portfolio: string;
  template: ResumeTemplate;
  experience: ResumeFormExperience[];
  education: ResumeFormEducation[];
  skills: string[];
  projects: ResumeFormProject[];
  gaming: {
    roles: string | string[];
    genres: string | string[];
    achievements: string | string[];
  };
}

export interface ResumeFormExperience {
  title: string;
  company: string;
  location: string;
  startDate: string;
  endDate: string;
  current: boolean;
  description: string;
}

export interface ResumeFormEducation {
  degree: string;
  school: string;
  location: string;
  graduationDate: string;
  gpa: string;
}

export interface ResumeFormProject {
  name: string;
  description: string;
  technologies: string[];
  url: string;
}

function toArray(val: string | string[]): string[] {
  if (Array.isArray(val)) return val;
  if (typeof val === "string") {
    return val
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
  }
  return [];
}

function buildPersonalInfo(form: Partial<ResumeFormData>): ResumePersonalInfo {
  return {
    ...(form.name ? { name: form.name } : {}),
    ...(form.email ? { email: form.email } : {}),
    ...(form.phone ? { phone: form.phone } : {}),
    ...(form.location ? { location: form.location } : {}),
    ...(form.linkedIn ? { linkedIn: form.linkedIn } : {}),
    ...(form.portfolio ? { portfolio: form.portfolio } : {}),
  };
}

function mapFormExperienceToResumeExperience(
  experience: ResumeFormExperience[] | undefined,
): ResumeExperienceItem[] {
  return (experience || []).map((exp) => ({
    title: exp.title,
    company: exp.company,
    startDate: exp.startDate,
    ...(!exp.current && exp.endDate ? { endDate: exp.endDate } : {}),
    ...(exp.location ? { location: exp.location } : {}),
    ...(exp.description ? { description: exp.description } : {}),
  }));
}

function mapFormEducationToResumeEducation(
  education: ResumeFormEducation[] | undefined,
): ResumeEducationItem[] {
  return (education || []).map((edu) => ({
    degree: edu.degree,
    school: edu.school,
    field: "",
    year: edu.graduationDate,
    ...(edu.gpa ? { gpa: edu.gpa } : {}),
  }));
}

function buildSkillsFromForm(skillsInput: string[] | undefined): ResumeSkills {
  return (skillsInput ?? []).length > 0 ? { technical: skillsInput } : {};
}

function mapFormProjectsToResumeProjects(
  projects: ResumeFormProject[] | undefined,
): ResumeProject[] {
  return (projects || []).map((project) => ({
    title: project.name,
    description: project.description,
    ...((project.technologies ?? []).length > 0 ? { technologies: project.technologies } : {}),
    ...(project.url ? { link: project.url } : {}),
  }));
}

function buildGamingExperience(gaming: ResumeFormData["gaming"] | undefined): GamingExperience {
  if (!gaming) return {};

  const roles = toArray(gaming.roles);
  const genres = toArray(gaming.genres);
  const achievements = toArray(gaming.achievements);
  return {
    ...(roles.length > 0 ? { gameEngines: roles.join(", ") } : {}),
    ...(genres.length > 0 ? { genres: genres.join(", ") } : {}),
    ...(achievements.length > 0 ? { shippedTitles: achievements.join("; ") } : {}),
  };
}

function buildResumeData(input: {
  form: Partial<ResumeFormData>;
  personalInfo: ResumePersonalInfo;
  experience: ResumeExperienceItem[];
  education: ResumeEducationItem[];
  skills: ResumeSkills;
  projects: ResumeProject[];
  gamingExperience: GamingExperience;
}): Partial<ResumeData> {
  return {
    ...(Object.keys(input.personalInfo).length > 0 ? { personalInfo: input.personalInfo } : {}),
    ...(input.form.summary ? { summary: input.form.summary } : {}),
    ...(input.form.template && isResumeTemplate(input.form.template)
      ? { template: input.form.template }
      : {}),
    ...(input.experience.length > 0 ? { experience: input.experience } : {}),
    ...(input.education.length > 0 ? { education: input.education } : {}),
    ...(Object.keys(input.skills).length > 0 ? { skills: input.skills } : {}),
    ...(input.projects.length > 0 ? { projects: input.projects } : {}),
    ...(Object.keys(input.gamingExperience).length > 0
      ? { gamingExperience: input.gamingExperience }
      : {}),
  };
}

function mapResumeExperienceToFormExperience(
  experience: ResumeExperienceItem[] | undefined,
): ResumeFormExperience[] {
  return (experience || []).map((exp) => ({
    title: exp.title,
    company: exp.company,
    location: exp.location || "",
    startDate: exp.startDate,
    endDate: exp.endDate || "",
    current: !exp.endDate,
    description: exp.description || "",
  }));
}

function mapResumeEducationToFormEducation(
  education: ResumeEducationItem[] | undefined,
): ResumeFormEducation[] {
  return (education || []).map((edu) => ({
    degree: edu.degree,
    school: edu.school,
    location: "",
    graduationDate: edu.year,
    gpa: edu.gpa || "",
  }));
}

function mapResumeProjectsToFormProjects(
  projects: ResumeProject[] | undefined,
): ResumeFormProject[] {
  return (projects || []).map((project) => ({
    name: project.title,
    description: project.description,
    technologies: project.technologies || [],
    url: project.link || "",
  }));
}

function splitDelimited(value: string | undefined, delimiter: string): string[] {
  return value ? value.split(delimiter).map((entry) => entry.trim()) : [];
}

/**
 * Convert form data to canonical ResumeData.
 */
export function formDataToResumeData(form: Partial<ResumeFormData>): Partial<ResumeData> {
  const personalInfo = buildPersonalInfo(form);
  const experience = mapFormExperienceToResumeExperience(form.experience);
  const education = mapFormEducationToResumeEducation(form.education);
  const skills = buildSkillsFromForm(form.skills);
  const projects = mapFormProjectsToResumeProjects(form.projects);
  const gamingExperience = buildGamingExperience(form.gaming);

  return buildResumeData({
    form,
    personalInfo,
    experience,
    education,
    skills,
    projects,
    gamingExperience,
  });
}

/**
 * Convert canonical ResumeData to form data.
 */
export function resumeDataToFormData(resume: Partial<ResumeData>): ResumeFormData {
  const pi = resume.personalInfo || {};
  return {
    name: pi.name || "",
    email: pi.email || "",
    phone: pi.phone || "",
    location: pi.location || "",
    summary: resume.summary || "",
    template: isResumeTemplate(resume.template) ? resume.template : RESUME_TEMPLATE_DEFAULT,
    linkedIn: pi.linkedIn || "",
    portfolio: pi.portfolio || "",
    experience: mapResumeExperienceToFormExperience(resume.experience),
    education: mapResumeEducationToFormEducation(resume.education),
    skills: [...(resume.skills?.technical || []), ...(resume.skills?.soft || [])],
    projects: mapResumeProjectsToFormProjects(resume.projects),
    gaming: {
      roles: splitDelimited(resume.gamingExperience?.gameEngines, ","),
      genres: splitDelimited(resume.gamingExperience?.genres, ","),
      achievements: splitDelimited(resume.gamingExperience?.shippedTitles, ";"),
    },
  };
}

import { AI_PROVIDER_IDS, type AIProviderType } from "../types/ai";
import type { ScrapePersonaEnrichment } from "../types/jobs";
import { asRecord, asString, asStringArray } from "./type-guards";

const SCRAPE_ENRICHMENT_LIST_LIMIT = 4;

const isAIProviderType = (value: string): value is AIProviderType =>
  AI_PROVIDER_IDS.some((provider) => provider === value);

/**
 * Normalizes unknown scrape-enrichment payloads into the shared contract.
 */
export function normalizeScrapePersonaEnrichment(
  value: unknown,
): ScrapePersonaEnrichment | undefined {
  const record = asRecord(value);
  if (!record) {
    return;
  }

  const summary = asString(record.summary);
  if (!summary) {
    return;
  }

  const normalized: ScrapePersonaEnrichment = {
    summary,
    hiringSignals: asStringArray(record.hiringSignals).slice(0, SCRAPE_ENRICHMENT_LIST_LIMIT),
    interviewFocusAreas: asStringArray(record.interviewFocusAreas).slice(
      0,
      SCRAPE_ENRICHMENT_LIST_LIMIT,
    ),
    candidatePitchAngles: asStringArray(record.candidatePitchAngles).slice(
      0,
      SCRAPE_ENRICHMENT_LIST_LIMIT,
    ),
  };

  const provider = asString(record.provider);
  const model = asString(record.model);
  const updatedAt = asString(record.updatedAt);

  if (provider && isAIProviderType(provider)) {
    normalized.provider = provider;
  }
  if (model) {
    normalized.model = model;
  }
  if (updatedAt) {
    normalized.updatedAt = updatedAt;
  }

  return normalized;
}

/**
 * String utility helpers.
 */

/**
 * Escapes special regex characters in a string for use in RegExp constructors.
 */
export function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
}

/**
 * Shared type guards for runtime validation of boundary values.
 * Single source of truth — do not duplicate in composables or services.
 */
import type { JsonObject, JsonValue } from "./json";
import { safeParseJson } from "./json";

export const isRecord = <T>(v: T): v is T & JsonObject =>
  typeof v === "object" && v !== null && !Array.isArray(v);

export const asString = <T>(v: T): string | undefined =>
  typeof v === "string" && v.trim().length > 0 ? v : undefined;

export const asStringArray = <T>(v: T): string[] =>
  Array.isArray(v) ? v.filter((e): e is string => typeof e === "string") : [];

export const asNumber = <T>(v: T): number | undefined =>
  typeof v === "number" && !Number.isNaN(v) ? v : undefined;

export const asBoolean = <T>(v: T): boolean | undefined => (typeof v === "boolean" ? v : undefined);

export const asRecord = <T>(v: T): JsonObject | undefined => {
  if (typeof v !== "object" || v === null || Array.isArray(v)) {
    return undefined;
  }
  const parsed = safeParseJson(JSON.stringify(v));
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    return undefined;
  }
  return parsed;
};

export const asJsonArray = <T>(v: T): JsonValue[] | undefined => {
  if (!Array.isArray(v)) {
    return undefined;
  }
  const parsed = safeParseJson(JSON.stringify(v));
  return Array.isArray(parsed) ? parsed : undefined;
};

/**
 * Shared validation utilities
 */

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function isValidEmail(email: string): boolean {
  return EMAIL_PATTERN.test(email);
}

export function generateId(): string {
  // Bun.randomUUIDv7 is faster and produces monotonic, sortable UUIDs
  // Falls back to crypto.randomUUID for non-Bun environments (shared package)
  return typeof Bun !== "undefined" ? Bun.randomUUIDv7() : crypto.randomUUID();
}

const LINE_BREAK_PATTERN = /\r?\n/;
const FETCH_TIMEOUT_MS = 8_000;
const FETCH_RETRY_COUNT = 3;

const LLM_SOURCES = [
  {
    name: "Elysia",
    url: "https://elysiajs.com/llms.txt",
    requiredMarkers: ["Ergonomic Framework for Humans", "Essential", "Best Practice - ElysiaJS"],
  },
  {
    name: "Nuxt",
    url: "https://nuxt.com/llms.txt",
    requiredMarkers: ["Nuxt v4 Documentation", "useAsyncData", "useFetch"],
  },
  {
    name: "Bun",
    url: "https://bun.sh/llms.txt",
    requiredMarkers: ["# Bun", "Welcome to Bun", "bun install"],
  },
  {
    name: "daisyUI",
    url: "https://daisyui.com/llms.txt",
    requiredMarkers: ["daisyUI 5", "btn", "card", "drawer"],
  },
] as const;

type LlmSource = (typeof LLM_SOURCES)[number];

type SourceAudit = {
  name: string;
  url: string;
  finalUrl: string;
  statusCode: number;
  ok: boolean;
  redirected: boolean;
  lineCount: number;
  contentLength: number;
  missingMarkers: string[];
  fetchError: string | null;
  failureClass: "none" | "timeout" | "network" | "http" | "marker" | "unknown";
  attempts: number;
};

const countLines = (text: string): number =>
  text.length === 0 ? 0 : text.split(LINE_BREAK_PATTERN).length;

const classifyFetchError = (reason: string): SourceAudit["failureClass"] => {
  if (reason.toLowerCase().includes("timeout")) {
    return "timeout";
  }
  if (
    reason.toLowerCase().includes("network") ||
    reason.toLowerCase().includes("fetch") ||
    reason.toLowerCase().includes("dns")
  ) {
    return "network";
  }
  return "unknown";
};

const auditResponse = async (
  source: LlmSource,
  attempts: number,
  response: Response,
): Promise<SourceAudit> => {
  const content = await response.text();
  const missingMarkers = source.requiredMarkers.filter((marker) => !content.includes(marker));
  let failureClass: "http" | "marker" | "none" = "none";
  if (!response.ok) {
    failureClass = "http";
  } else if (missingMarkers.length > 0) {
    failureClass = "marker";
  }

  return {
    name: source.name,
    url: source.url,
    finalUrl: response.url,
    statusCode: response.status,
    ok: response.ok && missingMarkers.length === 0,
    redirected: response.url !== source.url,
    lineCount: countLines(content),
    contentLength: content.length,
    missingMarkers,
    fetchError: null,
    failureClass,
    attempts,
  };
};

const createFetchErrorAudit = (
  source: LlmSource,
  reason: unknown,
  attempts: number,
): SourceAudit => {
  const errorMessage = String(reason);

  return {
    name: source.name,
    url: source.url,
    finalUrl: source.url,
    statusCode: 0,
    ok: false,
    redirected: false,
    lineCount: 0,
    contentLength: 0,
    missingMarkers: [...source.requiredMarkers],
    fetchError: errorMessage,
    failureClass: classifyFetchError(errorMessage),
    attempts,
  };
};

const attemptAudit = async (source: LlmSource, attempts: number): Promise<SourceAudit> => {
  const result = await Promise.allSettled([
    fetch(source.url, {
      redirect: "follow",
      signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
    }),
  ]);
  const fetchResult = result[0];

  if (fetchResult.status === "rejected") {
    return createFetchErrorAudit(source, fetchResult.reason, attempts);
  }

  return auditResponse(source, attempts, fetchResult.value);
};

const auditSource = async (source: LlmSource, attempts = 1): Promise<SourceAudit> => {
  const audit = await attemptAudit(source, attempts);
  if (
    attempts >= FETCH_RETRY_COUNT ||
    audit.failureClass === "none" ||
    audit.failureClass === "marker"
  ) {
    return audit;
  }

  return auditSource(source, attempts + 1);
};

const formatResult = (audit: SourceAudit): string => {
  const statusToken = audit.ok ? "PASS" : "FAIL";
  const markerStatus =
    audit.missingMarkers.length === 0
      ? "markers=ok"
      : `markers=missing(${audit.missingMarkers.join(" | ")})`;
  const errorStatus = audit.fetchError ? `error=${audit.fetchError}` : "error=none";
  const failureStatus = `failureClass=${audit.failureClass}`;
  const attemptStatus = `attempts=${audit.attempts}`;

  return [
    `[${statusToken}]`,
    audit.name,
    `source=${audit.url}`,
    `final=${audit.finalUrl}`,
    `status=${audit.statusCode}`,
    `redirected=${audit.redirected}`,
    `lines=${audit.lineCount}`,
    `bytes=${audit.contentLength}`,
    markerStatus,
    failureStatus,
    attemptStatus,
    errorStatus,
  ].join(" ");
};

const writeLine = (line: string): void => {
  process.stdout.write(`${line}\n`);
};

const settledAudits = await Promise.allSettled(LLM_SOURCES.map((source) => auditSource(source)));
const audits: SourceAudit[] = settledAudits.map((result, index) =>
  result.status === "fulfilled"
    ? result.value
    : createFetchErrorAudit(LLM_SOURCES[index], result.reason, FETCH_RETRY_COUNT),
);

writeLine("Official llms.txt audit results");
for (const audit of audits) {
  writeLine(formatResult(audit));
}

const failedAudits = audits.filter((audit) => !audit.ok);
writeLine(
  failedAudits.length === 0
    ? "Summary: all official llms.txt sources are reachable and contain required markers."
    : `Summary: ${failedAudits.length} source(s) failed validation.`,
);

if (failedAudits.length > 0) {
  process.exitCode = 1;
}

