const NUM_180 = 180;
const NUM_200 = 200;
const NUM_600 = 600;
const NUM_8 = 8;
const NUM_80 = 80;

/**
 * Interaction actions for browser-interaction-burndown (complexity + size split).
 */
import { mkdir } from "node:fs/promises";
import { join } from "node:path";
import type { Page } from "playwright";
import { settle } from "../packages/shared/src/utils/promise";
import { type ChromeSignals, collectChromeSignals } from "./browser-interaction-burndown-chrome";

export type Finding = {
  readonly viewport: string;
  readonly route: string;
  readonly action: string;
  readonly severity: "error" | "warn";
  readonly detail: string;
  readonly screenshot: string | null;
};

const NON_SLUG_RE = /[^\w-]+/gu;
/**
 * Filename-safe token for screenshot artifacts. Distinct from the shared
 * URL-slug `slugify` (validation.ts): keeps case, maps runs of non-word
 * characters to underscores, and caps length for filesystem safety.
 */
export const toFilenameSlug = (value: string): string =>
  value.replace(NON_SLUG_RE, "_").slice(0, NUM_80);

export const mapSequential = async <TItem, TResult>(
  items: readonly TItem[],
  mapper: (item: TItem) => Promise<TResult>,
  index = 0,
): Promise<TResult[]> => {
  const item = items[index];
  if (item === undefined) return [];
  const head = await mapper(item);
  return [head, ...(await mapSequential(items, mapper, index + 1))];
};

export const waitForPageReady = async (page: Page, timeout: number): Promise<void> => {
  await page
    .locator("body")
    .waitFor({ state: "visible", timeout })
    .then(
      () => undefined,
      () => undefined,
    );
  await page.waitForLoadState("domcontentloaded", { timeout }).then(
    () => undefined,
    () => undefined,
  );
};

export const captureFinding = async (
  page: Page,
  findings: Finding[],
  outDir: string,
  viewport: string,
  route: string,
  action: string,
  detail: string,
  severity: "error" | "warn" = "error",
): Promise<void> => {
  let screenshot: string | null = null;
  if (severity === "error") {
    screenshot = join(outDir, viewport, `${toFilenameSlug(route)}__${toFilenameSlug(action)}.png`);
    await mkdir(join(outDir, viewport), { recursive: true });
    await page.screenshot({ path: screenshot, fullPage: false });
  }
  findings.push({ viewport, route, action, severity, detail, screenshot });
};

export const openRoute = async (
  page: Page,
  clientBase: string,
  route: string,
  consoleBucket: string[],
  pageErrorBucket: string[],
): Promise<void> => {
  consoleBucket.length = 0;
  pageErrorBucket.length = 0;
  await page.goto(`${clientBase}${route}`, {
    waitUntil: "domcontentloaded",
    timeout: 60_000,
  });
  await waitForPageReady(page, NUM_600);
};

const pushShellFinding = async (
  page: Page,
  findings: Finding[],
  outDir: string,
  viewport: string,
  route: string,
  action: string,
  detail: string,
  condition: boolean,
): Promise<void> => {
  if (!condition) return;
  await captureFinding(page, findings, outDir, viewport, route, action, detail);
};

const shellFindingSpecs = (
  shell: ChromeSignals,
): readonly { action: string; detail: string; condition: boolean }[] => [
  {
    action: "shell-main",
    detail: `expected 1 main, got ${String(shell.mains)}`,
    condition: shell.mains !== 1,
  },
  { action: "shell-h1", detail: "missing h1", condition: shell.h1.length === 0 },
  { action: "shell-title", detail: "empty document title", condition: shell.title.length === 0 },
  {
    action: "overflow-x",
    detail: `document overflowX=${String(shell.overflowX)}`,
    condition: shell.overflowX > NUM_8,
  },
  { action: "truncated-chrome", detail: "navbar ellipsis gut", condition: shell.truncatedChrome },
  {
    action: "clipped-section-tabs",
    detail: "section tab label scrollWidth>clientWidth",
    condition: shell.clippedSectionTabs,
  },
  {
    action: "duplicate-chrome-copy",
    detail: shell.duplicateChromeCopy[0] ?? "dup",
    condition: shell.duplicateChromeCopy.length > 0,
  },
  { action: "raw-glass", detail: "backdrop outside glass-*", condition: shell.rawGlass },
];

export const probeRouteShell = async (
  page: Page,
  findings: Finding[],
  outDir: string,
  viewport: string,
  route: string,
): Promise<ChromeSignals> => {
  const shell = await collectChromeSignals(page);
  await mapSequential(shellFindingSpecs(shell), async (spec) => {
    await pushShellFinding(
      page,
      findings,
      outDir,
      viewport,
      route,
      spec.action,
      spec.detail,
      spec.condition,
    );
  });
  return shell;
};

const listClickableControlLabels = async (
  page: Page,
  maxClicks: number,
): Promise<readonly string[]> => {
  const evaluated = await settle(
    page.evaluate((limit: number) => {
      const main = document.querySelector("main");
      if (!main) return [];
      return [
        ...new Set(
          Array.from(main.querySelectorAll("button, a.btn, a[href]"))
            .filter((control): control is HTMLElement => control instanceof HTMLElement)
            .filter(
              (control) =>
                !control.hasAttribute("disabled") &&
                control.getAttribute("aria-disabled") !== "true",
            )
            .filter((control) => {
              const style = window.getComputedStyle(control);
              return style.visibility !== "hidden" && style.display !== "none";
            })
            .map((control) => {
              const aria = control.getAttribute("aria-label")?.replace(/\s+/gu, " ").trim() ?? "";
              const text = control.textContent?.replace(/\s+/gu, " ").trim() ?? "";
              return aria.length > 0 ? aria : text;
            })
            .filter((label) => label.length > 0 && label.length < NUM_80),
        ),
      ].slice(0, limit);
    }, maxClicks),
  );
  return evaluated.status === "fulfilled" ? evaluated.value : [];
};

const tryClickLabelInPage = async (page: Page, label: string): Promise<boolean> => {
  const clickResult = await settle(
    page.evaluate((targetLabel) => {
      const normalize = (value: string): string => value.replace(/\s+/gu, " ").trim();
      const match = Array.from(
        document.querySelectorAll("main button, main a.btn, main a[href]"),
      ).find((control) => {
        if (!(control instanceof HTMLElement)) return false;
        if (control.hasAttribute("disabled") || control.getAttribute("aria-disabled") === "true") {
          return false;
        }
        const aria = normalize(control.getAttribute("aria-label") ?? "");
        const text = normalize(control.textContent ?? "");
        return (aria.length > 0 ? aria : text) === targetLabel;
      });
      if (!(match instanceof HTMLElement)) return false;
      match.click();
      return true;
    }, label),
  );
  return clickResult.status === "fulfilled" && clickResult.value;
};

const clickOneLabel = async (
  page: Page,
  clientBase: string,
  outDir: string,
  viewport: string,
  route: string,
  label: string,
  findings: Finding[],
  consoleBucket: string[],
  pageErrorBucket: string[],
  maxClicks: number,
): Promise<void> => {
  consoleBucket.length = 0;
  pageErrorBucket.length = 0;
  const clicked = await tryClickLabelInPage(page, label);
  if (!clicked) {
    const stillListedResult = await settle(listClickableControlLabels(page, maxClicks));
    const stillListed =
      stillListedResult.status === "fulfilled" && stillListedResult.value.includes(label);
    if (stillListed) {
      await captureFinding(
        page,
        findings,
        outDir,
        viewport,
        route,
        `click-${toFilenameSlug(label)}`,
        "control not found",
        "warn",
      );
    }
  }
  await waitForPageReady(page, NUM_180);
  const origin = `${clientBase}${route}`;
  if (!page.url().startsWith(origin)) {
    await openRoute(page, clientBase, route, consoleBucket, pageErrorBucket);
  }
  if (pageErrorBucket.length > 0) {
    await captureFinding(
      page,
      findings,
      outDir,
      viewport,
      route,
      `after-click-${toFilenameSlug(label)}`,
      pageErrorBucket[0] ?? "",
    );
  }
};

export const clickVisibleControls = async (
  page: Page,
  clientBase: string,
  outDir: string,
  viewport: string,
  route: string,
  findings: Finding[],
  consoleBucket: string[],
  pageErrorBucket: string[],
  maxClicks: number,
): Promise<number> => {
  const labels = await listClickableControlLabels(page, maxClicks);
  await mapSequential(labels, async (label) => {
    await clickOneLabel(
      page,
      clientBase,
      outDir,
      viewport,
      route,
      label,
      findings,
      consoleBucket,
      pageErrorBucket,
      maxClicks,
    );
    const origin = `${clientBase}${route}`;
    if (page.url() !== origin) {
      await openRoute(page, clientBase, route, consoleBucket, pageErrorBucket);
    }
  });
  return labels.length;
};

export const probeFirstTextInput = async (
  page: Page,
  outDir: string,
  viewport: string,
  route: string,
  findings: Finding[],
  consoleBucket: string[],
  pageErrorBucket: string[],
): Promise<void> => {
  const input = page.getByRole("textbox").first();
  if ((await input.count()) === 0) return;
  consoleBucket.length = 0;
  pageErrorBucket.length = 0;
  await input.fill("burndown-probe");
  await waitForPageReady(page, NUM_200);
  if (pageErrorBucket.length > 0) {
    await captureFinding(
      page,
      findings,
      outDir,
      viewport,
      route,
      "textbox-probe",
      pageErrorBucket[0] ?? "",
    );
  }
};

const NUM_122 = 122;
const NUM_4 = 4;
const NUM_40 = 40;
const NUM_65 = 65;
const NUM_90 = 90;
const NUM_97 = 97;

/**
 * Chrome signal collectors for browser-interaction-burndown (complexity split).
 */
import type { Page } from "playwright";

export type ChromeSignals = {
  readonly mains: number;
  readonly h1: string;
  readonly title: string;
  readonly overflowX: number;
  readonly truncatedChrome: boolean;
  readonly clippedSectionTabs: boolean;
  readonly duplicateChromeCopy: readonly string[];
  readonly rawGlass: boolean;
  readonly bodyLen: number;
};

const collectShellLandmarks = async (page: Page) =>
  page.evaluate(() => {
    const collapseWs = (value: string): string => {
      let out = "";
      let prevSpace = false;
      for (const ch of value) {
        const isSpace = ch === " " || ch === "\n" || ch === "\t" || ch === "\r";
        if (isSpace) {
          if (!prevSpace) out += " ";
          prevSpace = true;
          continue;
        }
        out += ch;
        prevSpace = false;
      }
      return out.trim();
    };
    return {
      mains: document.querySelectorAll("main").length,
      h1: collapseWs(document.querySelector("h1")?.textContent ?? ""),
      title: document.title.trim(),
      overflowX:
        Math.max(document.documentElement.scrollWidth, document.body?.scrollWidth ?? 0) -
        window.innerWidth,
      bodyLen: collapseWs(document.body?.innerText ?? "").length,
    };
  });

const collectChromeQuality = async (page: Page) =>
  page.evaluate(() => {
    const isAsciiLetter = (ch: string): boolean => {
      const code = ch.charCodeAt(0);
      return (code >= NUM_65 && code <= NUM_90) || (code >= NUM_97 && code <= NUM_122);
    };
    const isNavbarEllipsisGut = (text: string): boolean => {
      if (text.length === 2) return isAsciiLetter(text[0] ?? "") && text[1] === "…";
      if (text.length === NUM_4) return isAsciiLetter(text[0] ?? "") && text.slice(1) === "...";
      return false;
    };
    const collapseWs = (value: string): string => value.replace(/\s+/gu, " ").trim();
    const clippedSectionTabs = [...document.querySelectorAll(".tabs .tab")].some((el) => {
      const label =
        el.querySelector("span.truncate, span.font-medium, span.whitespace-nowrap") ??
        (el instanceof HTMLElement ? el : null);
      if (!(label instanceof HTMLElement)) return false;
      if (label.scrollWidth <= label.clientWidth + 1) return false;
      const className = label.className?.toString?.() ?? "";
      const style = getComputedStyle(label);
      const intentionalTruncate =
        className.includes("truncate") || style.textOverflow === "ellipsis";
      return !intentionalTruncate;
    });
    const texts = [...document.querySelectorAll("p")]
      .filter((el) => !el.closest(".grid, .stats, [role='log']"))
      .map((el) => collapseWs(el.textContent ?? ""))
      .filter((text) => text.length > NUM_40);
    const counts = new Map<string, number>();
    for (const text of texts) {
      counts.set(text, (counts.get(text) ?? 0) + 1);
    }
    const rawGlass = [...document.querySelectorAll("*")].some((el) => {
      const style = getComputedStyle(el);
      const filter =
        style.getPropertyValue("backdrop-filter") ||
        style.getPropertyValue("-webkit-backdrop-filter") ||
        "";
      if (!filter || filter === "none") return false;
      return !(el.className?.toString?.() ?? "").includes("glass");
    });
    return {
      truncatedChrome: [...document.querySelectorAll(".navbar *")]
        .map((el) => (el.textContent ?? "").trim())
        .some((text) => isNavbarEllipsisGut(text)),
      clippedSectionTabs,
      duplicateChromeCopy: [...counts.entries()]
        .filter(([, count]) => count > 1)
        .map(([text]) => text),
      rawGlass,
    };
  });

export const collectChromeSignals = async (page: Page): Promise<ChromeSignals> => {
  const landmarks = await collectShellLandmarks(page);
  const quality = await collectChromeQuality(page);
  return {
    mains: landmarks.mains,
    h1: landmarks.h1,
    title: landmarks.title,
    overflowX: landmarks.overflowX,
    bodyLen: landmarks.bodyLen,
    truncatedChrome: quality.truncatedChrome,
    clippedSectionTabs: quality.clippedSectionTabs,
    duplicateChromeCopy: quality.duplicateChromeCopy,
    rawGlass: quality.rawGlass,
  };
};

const NUM_220 = 220;
const NUM_4 = 4;
const NUM_40 = 40;
const NUM_8 = 8;

/**
 * Browser interaction burndown — Playwright only (no curl / API inject).
 * Mobile → tablet → desktop. Canonical proof script for `proof:browser-burndown`.
 *
 * Env: PAGE_PROOF_CLIENT_BASE / BROWSER_BURNOUT_OUT read via scripts/utils/proof-script-env.ts.
 */
import { mkdir } from "node:fs/promises";
import { join } from "node:path";
import { type ConsoleMessage, chromium, type Page } from "playwright";
import { APP_ROUTES } from "../packages/shared/src/constants/routes";
import {
  captureFinding,
  clickVisibleControls,
  type Finding,
  mapSequential,
  openRoute,
  probeFirstTextInput,
  probeRouteShell,
  toFilenameSlug,
} from "./browser-interaction-burndown-actions";
import type { ChromeSignals } from "./browser-interaction-burndown-chrome";
import { writeError, writeOutput } from "./utils/cli-output";
import { resolveProofClientBase, resolveProofOutDir } from "./utils/proof-script-env";

const CLIENT_BASE = resolveProofClientBase("http://127.0.0.1:3001");
const OUT_DIR = resolveProofOutDir(
  "BROWSER_BURNOUT_OUT",
  join("/opt/cursor/artifacts/interactive-burndown"),
);
const MAX_CLICKS_PER_ROUTE = 4;

const VIEWPORTS = [
  { name: "mobile", width: 320, height: 720, isMobile: true, hasTouch: true },
  { name: "tablet", width: 768, height: 1024, isMobile: false, hasTouch: true },
  { name: "desktop", width: 1440, height: 900, isMobile: false, hasTouch: false },
] as const;

const ROUTES = [
  APP_ROUTES.dashboard,
  APP_ROUTES.jobs,
  APP_ROUTES.resume,
  APP_ROUTES.resumeBuild,
  APP_ROUTES.resumePreview,
  APP_ROUTES.coverLetter,
  APP_ROUTES.portfolio,
  APP_ROUTES.portfolioPreview,
  APP_ROUTES.interview,
  APP_ROUTES.interviewHistory,
  APP_ROUTES.interviewSession,
  APP_ROUTES.skills,
  APP_ROUTES.skillsPathways,
  APP_ROUTES.studios,
  APP_ROUTES.studiosAnalytics,
  APP_ROUTES.ai,
  APP_ROUTES.aiDashboard,
  APP_ROUTES.aiChat,
  APP_ROUTES.automation,
  APP_ROUTES.automationJobApply,
  APP_ROUTES.automationScraper,
  APP_ROUTES.automationEmail,
  APP_ROUTES.automationRuns,
  APP_ROUTES.gamification,
  APP_ROUTES.apiDocs,
  APP_ROUTES.settings,
  APP_ROUTES.setup,
] as const;

type FiveQ = {
  readonly shouldBeHere: string;
  readonly ssotUx: string;
  readonly interactions: string;
  readonly glassDry: string;
  readonly logs: string;
};

type RouteLedger = {
  readonly viewport: string;
  readonly route: string;
  readonly screenshot: string;
  readonly fiveQ: FiveQ;
  readonly ok: boolean;
};

const APP_MANIFEST_ERROR_RE = /Error fetching app manifest/iu;
const isIgnorableConsole = (text: string): boolean => APP_MANIFEST_ERROR_RE.test(text);

const buildFiveQ = (
  shell: ChromeSignals,
  clicks: number,
  consoleErrors: readonly string[],
  pageErrors: readonly string[],
  routeFindings: readonly Finding[],
): FiveQ => {
  const hardErrors = routeFindings.filter((finding) => finding.severity === "error");
  return {
    shouldBeHere:
      shell.mains === 1 && shell.h1.length > 0 && shell.title.length > 0
        ? "landmarks ok"
        : "FAIL: landmarks",
    ssotUx:
      shell.overflowX <= NUM_8 && !shell.truncatedChrome && !shell.clippedSectionTabs
        ? "layout ok"
        : "FAIL: overflow/clip",
    interactions: clicks > 0 ? `clicked ${String(clicks)}` : "FAIL: no clickable controls",
    glassDry:
      !shell.rawGlass && shell.duplicateChromeCopy.length === 0
        ? "no raw glass; chrome copy unique"
        : "FAIL: glass/DRY",
    logs:
      consoleErrors.length === 0 && pageErrors.length === 0 && hardErrors.length === 0
        ? "0 console/page errors"
        : `FAIL: console=${String(consoleErrors.length)} page=${String(pageErrors.length)} findings=${String(hardErrors.length)}`,
  };
};

const burnRoute = async (
  page: Page,
  viewport: string,
  route: string,
  findings: Finding[],
  consoleBucket: string[],
  pageErrorBucket: string[],
): Promise<RouteLedger> => {
  await openRoute(page, CLIENT_BASE, route, consoleBucket, pageErrorBucket);
  const screenshot = join(OUT_DIR, viewport, `${toFilenameSlug(route)}.png`);
  await mkdir(join(OUT_DIR, viewport), { recursive: true });
  await page.screenshot({ path: screenshot, fullPage: false });

  const loadErrors = [
    ...pageErrorBucket,
    ...consoleBucket.filter((line) => !isIgnorableConsole(line)),
  ];
  if (loadErrors.some((line) => line.includes("500") || line.includes("TypeError"))) {
    await captureFinding(
      page,
      findings,
      OUT_DIR,
      viewport,
      route,
      "load",
      loadErrors.slice(0, NUM_4).join(" | "),
    );
  }

  const shell = await probeRouteShell(page, findings, OUT_DIR, viewport, route);
  const clicks = await clickVisibleControls(
    page,
    CLIENT_BASE,
    OUT_DIR,
    viewport,
    route,
    findings,
    consoleBucket,
    pageErrorBucket,
    MAX_CLICKS_PER_ROUTE,
  );
  if (route === APP_ROUTES.settings) {
    await openRoute(page, CLIENT_BASE, route, consoleBucket, pageErrorBucket);
    await probeFirstTextInput(
      page,
      OUT_DIR,
      viewport,
      route,
      findings,
      consoleBucket,
      pageErrorBucket,
    );
  }

  const routeFindings = findings.filter(
    (finding) => finding.viewport === viewport && finding.route === route,
  );
  const fiveQ = buildFiveQ(
    shell,
    clicks,
    consoleBucket.filter((line) => !isIgnorableConsole(line)),
    pageErrorBucket,
    routeFindings,
  );
  const fiveQFailed = Object.values(fiveQ).some((value) => value.startsWith("FAIL:"));
  const ok = !fiveQFailed && routeFindings.every((finding) => finding.severity !== "error");
  return { viewport, route, screenshot, fiveQ, ok };
};

const burnViewport = async (
  browser: Awaited<ReturnType<typeof chromium.launch>>,
  viewport: (typeof VIEWPORTS)[number],
  findings: Finding[],
): Promise<RouteLedger[]> => {
  const page = await browser.newPage({
    viewport: { width: viewport.width, height: viewport.height },
    isMobile: viewport.isMobile,
    hasTouch: viewport.hasTouch,
  });
  const consoleBucket: string[] = [];
  const pageErrorBucket: string[] = [];
  page.on("console", (message: ConsoleMessage) => {
    if (message.type() === "error" && !isIgnorableConsole(message.text())) {
      consoleBucket.push(message.text());
    }
  });
  page.on("pageerror", (error: Error) => {
    pageErrorBucket.push(error.message);
  });

  const ledger = await mapSequential(ROUTES, async (route) =>
    burnRoute(page, viewport.name, route, findings, consoleBucket, pageErrorBucket),
  );
  await page.close();
  return ledger;
};

const main = async (): Promise<void> => {
  await mkdir(OUT_DIR, { recursive: true });
  const browser = await chromium.launch({ headless: true });
  const findings: Finding[] = [];
  const ledger = (
    await mapSequential(VIEWPORTS, async (viewport) => burnViewport(browser, viewport, findings))
  ).flat();
  await browser.close();

  const errors = findings.filter((finding) => finding.severity === "error");
  const ledgerFailures = ledger.filter((item) => !item.ok);
  const reportPath = join(OUT_DIR, "burndown-report.json");
  const ledgerPath = join(OUT_DIR, "fiveq-ledger.json");
  await Bun.write(
    reportPath,
    JSON.stringify(
      {
        CLIENT_BASE,
        viewports: VIEWPORTS.map((viewport) => viewport.name),
        findings,
        errorCount: errors.length,
        ledgerOk: ledger.filter((item) => item.ok).length,
        ledgerTotal: ledger.length,
        ledgerFailures: ledgerFailures.length,
      },
      null,
      2,
    ),
  );
  await Bun.write(ledgerPath, JSON.stringify(ledger, null, 2));
  await writeOutput(
    `browser-interaction-burndown: ${String(ledger.length)} page×viewport, ${String(errors.length)} errors, ${String(ledgerFailures.length)} ledger fails, ${String(findings.length)} findings → ${reportPath}`,
  );
  if (errors.length > 0 || ledgerFailures.length > 0) {
    const findingLines = errors
      .slice(0, NUM_40)
      .map(
        (finding) =>
          `- ${finding.viewport} ${finding.route} [${finding.action}]: ${finding.detail.slice(0, NUM_220)}`,
      );
    const ledgerLines = ledgerFailures.slice(0, NUM_40).map((item) => {
      const failedKeys = Object.entries(item.fiveQ)
        .filter(([, value]) => value.startsWith("FAIL:"))
        .map(([key, value]) => `${key}=${value}`)
        .join("; ");
      return `- ${item.viewport} ${item.route}: ${failedKeys || "ledger ok=false"}`;
    });
    await writeError([...findingLines, ...ledgerLines].join("\n"));
    process.exitCode = 1;
  }
};

await main();

const NUM_12 = 12;
const NUM_200 = 200;
const NUM_2000 = 2_000;
const NUM_20000 = 20_000;
const NUM_2500 = 2_500;
const NUM_3000 = 3_000;
const NUM_45000 = 45_000;
const NUM_48 = 48;
const NUM_800 = 800;

/**
 * Portal toggle scrape proof phases (main() size split).
 */
import { join } from "node:path";
import type { Page } from "playwright";
import { APP_ROUTE_BUILDERS, APP_ROUTES } from "../packages/shared/src/constants/routes";
import { writeOutput } from "./utils/cli-output";

const RE_SAVE_PROVIDERS = /Save Provider Config/i;
const RE_REFRESH_JOBS = /Refresh Jobs/i;
const RE_STUDIO = /Studio/i;
const RE_JOB_INTELLIGENCE = /Job Intelligence/i;
const RE_CONFIGURED_COUNT = /Configured\s+(\d+)/u;
const RE_ENABLE_WWI = /Enable Work With Indies/i;
const RE_ENABLE_GRACKLE = /Enable GrackleHQ/i;
const RE_ENABLE_REMOTE = /Enable RemoteGameJobs/i;

export type ScraperState = {
  readonly configured: string | null;
  readonly runButtons: readonly { t: string; dis: boolean; a: string | null }[];
};

export type JobsState = {
  readonly empty: boolean;
  readonly titles: readonly string[];
};

export const wait = async (page: Page, ms: number): Promise<void> => {
  await page
    .locator("body")
    .waitFor({ state: "visible", timeout: ms })
    .then(
      () => undefined,
      () => undefined,
    );
  await page.waitForLoadState("domcontentloaded", { timeout: ms }).then(
    () => undefined,
    () => undefined,
  );
};

export const shot = async (page: Page, out: string, name: string): Promise<void> => {
  await page.screenshot({
    path: join(out, "stills", `${name}.png`),
    fullPage: name.includes("full"),
  });
};

export const enablePortal = async (
  page: Page,
  namePattern: RegExp,
  label: string,
): Promise<void> => {
  const toggle = page.getByRole("checkbox", { name: namePattern });
  if ((await toggle.count()) === 0) {
    await writeOutput(`missing toggle: ${label}`);
    return;
  }
  if (!(await toggle.isChecked())) {
    await toggle.click();
    await wait(page, NUM_200);
  }
  await writeOutput(`enabled ${label}=${String(await toggle.isChecked())}`);
};

export const phaseEnablePortals = async (
  page: Page,
  clientBase: string,
  out: string,
): Promise<void> => {
  await page.goto(`${clientBase}${APP_ROUTE_BUILDERS.settingsSection("jobIntelligence")}`, {
    waitUntil: "domcontentloaded",
    timeout: 90_000,
  });
  await wait(page, NUM_2500);
  const jobIntelNav = page.getByRole("button", { name: RE_JOB_INTELLIGENCE }).first();
  if ((await jobIntelNav.count()) > 0) {
    await jobIntelNav.click();
    await wait(page, NUM_800);
  }
  await shot(page, out, "01-settings-mobile-full");
  const toggleCount = await page
    .locator('section[aria-label="Gaming job portals"] input.toggle')
    .count();
  await writeOutput(`portal toggles=${String(toggleCount)}`);
  await enablePortal(page, RE_ENABLE_WWI, "Work With Indies");
  await enablePortal(page, RE_ENABLE_GRACKLE, "GrackleHQ");
  await enablePortal(page, RE_ENABLE_REMOTE, "RemoteGameJobs");
  const saveProviders = page.locator("button").filter({ hasText: RE_SAVE_PROVIDERS }).first();
  await saveProviders.click();
  await wait(page, NUM_2500);
  await shot(page, out, "02-saved");
};

export const phaseRunScraper = async (
  page: Page,
  clientBase: string,
  out: string,
): Promise<ScraperState> => {
  await page.goto(`${clientBase}${APP_ROUTES.automationScraper}`, {
    waitUntil: "domcontentloaded",
    timeout: 90_000,
  });
  await wait(page, NUM_3000);
  const scraperState = await page.evaluate((configuredPatternSource) => {
    const text = document.body.innerText;
    const configuredMatch = new RegExp(configuredPatternSource, "u").exec(text);
    return {
      configured: configuredMatch?.[1] ?? null,
      runButtons: [...document.querySelectorAll("main button")].map((button) => ({
        t: (button.textContent ?? "").trim().slice(0, NUM_48),
        dis: (button as HTMLButtonElement).disabled,
        a: button.getAttribute("aria-label"),
      })),
    };
  }, RE_CONFIGURED_COUNT.source);
  await writeOutput(`SCRAPER ${JSON.stringify(scraperState)}`);
  await shot(page, out, "03-scraper-full");
  const jobRuns = page.locator("main button.btn-primary").filter({ hasNotText: RE_STUDIO });
  await writeOutput(`jobRun buttons=${String(await jobRuns.count())}`);
  const enabledJobRun = jobRuns.filter({ hasNot: page.locator(":disabled") }).first();
  if ((await enabledJobRun.count()) > 0) {
    await writeOutput(`click ${String(await enabledJobRun.getAttribute("aria-label"))}`);
    await enabledJobRun.click();
    await wait(page, NUM_45000);
  }
  await shot(page, out, "04-after-run");
  return scraperState;
};

export const phaseVerifyJobs = async (
  page: Page,
  clientBase: string,
  out: string,
): Promise<JobsState> => {
  await page.goto(`${clientBase}${APP_ROUTES.jobs}`, {
    waitUntil: "domcontentloaded",
    timeout: 90_000,
  });
  await wait(page, NUM_2000);
  const refresh = page.getByRole("button", { name: RE_REFRESH_JOBS });
  if ((await refresh.count()) > 0) {
    await refresh.click();
    await wait(page, NUM_20000);
  }
  await shot(page, out, "05-jobs");
  return page.evaluate(() => ({
    empty: document.body.innerText.includes("No jobs loaded yet"),
    titles: [...document.querySelectorAll("main .card-title, main h3")]
      .map((element) => element.textContent?.trim())
      .filter((value): value is string => Boolean(value))
      .slice(0, NUM_12),
  }));
};

const NUM_12 = 12;
const NUM_240 = 240;

/**
 * Headed proof: enable gaming portal toggles via UI, run scrape, verify jobs feed.
 */
import { mkdir } from "node:fs/promises";
import { join } from "node:path";
import { chromium, type Response } from "playwright";
import { API_ENDPOINTS } from "../packages/shared/src/constants/endpoints";
import {
  phaseEnablePortals,
  phaseRunScraper,
  phaseVerifyJobs,
} from "./browser-portal-toggle-phases";
import { writeOutput } from "./utils/cli-output";

const WATCHED_API_PREFIXES = [
  API_ENDPOINTS.settings,
  API_ENDPOINTS.automationBase,
  API_ENDPOINTS.jobs,
  API_ENDPOINTS.scraperBase,
] as const;

const ORIGIN_PREFIX_PATTERN = /^https?:\/\/[^/]+/u;

const CLIENT_BASE = (process.env.PAGE_PROOF_CLIENT_BASE ?? "http://localhost:3001").replace(
  /\/$/u,
  "",
);
const OUT =
  process.env.PORTAL_PROOF_OUT ?? join("/opt/cursor/artifacts/baseline/portal-toggle-proof");

const captureApiResponse = async (
  res: Response,
  api: Array<{ s: number; u: string; b: string }>,
): Promise<void> => {
  const url = res.url();
  if (!WATCHED_API_PREFIXES.some((prefix) => url.includes(prefix))) {
    return;
  }
  const textResult = await res.text().then(
    (value) => value,
    () => "",
  );
  api.push({
    s: res.status(),
    u: url.replace(ORIGIN_PREFIX_PATTERN, ""),
    b: textResult.slice(0, NUM_240),
  });
};

const main = async (): Promise<void> => {
  await mkdir(join(OUT, "stills"), { recursive: true });
  await mkdir(join(OUT, "raw"), { recursive: true });

  const browser = await chromium.launch({ headless: false, args: ["--disable-dev-shm-usage"] });
  const context = await browser.newContext({
    recordVideo: { dir: join(OUT, "raw"), size: { width: 390, height: 844 } },
    viewport: { width: 390, height: 844 },
  });
  const page = await context.newPage();
  const api: Array<{ s: number; u: string; b: string }> = [];
  page.on("response", (res) => {
    captureApiResponse(res, api).then(
      () => undefined,
      () => undefined,
    );
  });

  await phaseEnablePortals(page, CLIENT_BASE, OUT);
  const scraperState = await phaseRunScraper(page, CLIENT_BASE, OUT);
  const jobs = await phaseVerifyJobs(page, CLIENT_BASE, OUT);
  await writeOutput(`JOBS ${JSON.stringify(jobs)}`);

  const video = page.video();
  await context.close();
  await browser.close();
  let videoPath: string | null = null;
  if (video) {
    videoPath = join(OUT, "portal-toggle-scrape.webm");
    await Bun.write(videoPath, Bun.file(await video.path()));
  }

  const report = { scraperState, jobs, api: api.slice(-NUM_12), videoPath };
  await Bun.write(join(OUT, "report.json"), JSON.stringify(report, null, 2));
  await writeOutput(JSON.stringify(report, null, 2));
  if (jobs.empty) {
    process.exitCode = 1;
  }
};

await main();

/**
 * Headed proof: DOM reactivity + fluidity via real click/type (no API inject).
 * Fail-closed (LDL): any finding → exit 1.
 */

import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { chromium, type Page } from "playwright";
import { APP_ROUTES } from "../packages/shared/src/constants/routes";
import { settle } from "../packages/shared/src/utils/promise";
import {
  COUNT_FIVE_HUNDRED,
  COUNT_THIRTY_SIX,
  MS_EIGHT_HUNDRED,
  MS_FOUR_HUNDRED,
  MS_ONE_TWO_HUNDRED,
  MS_SECOND,
  MS_SEVEN_HUNDRED,
  MS_SIX_HUNDRED,
  VIEWPORT_HEIGHT_DESKTOP,
  VIEWPORT_HEIGHT_MOBILE_PROOF,
  VIEWPORT_WIDTH_DESKTOP,
  VIEWPORT_WIDTH_MOBILE_PROOF,
} from "./constants/numeric-literals";
import { writeError, writeOutput } from "./utils/cli-output";
import { settlePage } from "./utils/playwright-settle";
import { reportFindingsAndExit } from "./utils/proof-findings";

const CLIENT_BASE = (process.env.PAGE_PROOF_CLIENT_BASE ?? "http://127.0.0.1:3001").replace(
  /\/$/u,
  "",
);
const OUT =
  process.env.DOM_REACTIVITY_OUT ?? "/opt/cursor/artifacts/live-capabilities/dom-reactivity";

const RE_EDIT_RESUME = /Edit resume/i;
const RE_SEARCH = /Search|Omni|workspace search/i;
const DESKTOP_VIEWPORT = {
  width: VIEWPORT_WIDTH_DESKTOP,
  height: VIEWPORT_HEIGHT_DESKTOP,
} as const;

const wait = settlePage;

const shot = async (page: Page, name: string): Promise<void> => {
  await page.screenshot({ path: join(OUT, "stills", `${name}.png`), fullPage: false });
};

const probeResumeCm6 = async (
  page: Page,
  findings: string[],
  navCount: () => number,
): Promise<void> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.resume}`, { waitUntil: "domcontentloaded" });
  await wait(page, MS_SECOND);
  const navBeforeEdit = navCount();
  await page.getByRole("button", { name: RE_EDIT_RESUME }).first().click();
  await wait(page, MS_ONE_TWO_HUNDRED);
  const cm = page.locator(".cm-content").first();
  if ((await cm.count()) === 0) {
    findings.push("Resume: CodeMirror not mounted");
  } else {
    const marker = ` REACT_${Date.now().toString(COUNT_THIRTY_SIX)}`;
    await cm.click();
    await page.keyboard.type(marker);
    await wait(page, MS_FOUR_HUNDRED);
    const text = (await cm.innerText()) ?? "";
    if (!text.includes(marker.trim())) {
      findings.push("Resume CM6: typed text not reflected in DOM");
    }
    if (navCount() > navBeforeEdit + 1) {
      findings.push("Resume edit: unexpected full navigation while typing");
    }
  }
  await shot(page, "01-resume-cm6-react");
};

const probeThemeFlip = async (page: Page, findings: string[]): Promise<void> => {
  const themeBefore = await page.locator("html").getAttribute("data-theme");
  const swap = page.locator("label.swap.swap-rotate").first();
  if ((await swap.count()) === 0) {
    findings.push("Theme swap control missing");
  } else {
    await swap.click();
    await wait(page, COUNT_FIVE_HUNDRED);
    const themeAfter = await page.locator("html").getAttribute("data-theme");
    if (!themeAfter || themeAfter === themeBefore) {
      findings.push(`Theme did not flip (${themeBefore} → ${themeAfter})`);
    }
  }
  await shot(page, "02-theme-flip");
};

const probeOmniSearch = async (page: Page, findings: string[]): Promise<void> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.dashboard}`, { waitUntil: "domcontentloaded" });
  await wait(page, MS_EIGHT_HUNDRED);
  const metaK = await settle(page.keyboard.press("Meta+k"));
  if (metaK.status === "rejected") {
    const ctrlK = await settle(page.keyboard.press("Control+k"));
    if (ctrlK.status === "rejected") {
      findings.push("OmniSearch shortcut failed (Meta/Control+K)");
    }
  }
  await wait(page, MS_SIX_HUNDRED);
  const searchInput = page.getByRole("searchbox").or(page.getByPlaceholder(RE_SEARCH)).first();
  if ((await searchInput.count()) > 0) {
    await searchInput.fill("resume");
    await wait(page, MS_SEVEN_HUNDRED);
    const value = await searchInput.inputValue();
    if (value !== "resume") {
      findings.push("OmniSearch input not reactive");
    }
    await shot(page, "03-omnisearch");
    await page.keyboard.press("Escape");
    return;
  }
  findings.push("OmniSearch input not found after shortcut");
  await shot(page, "03-omnisearch-missing");
};

const probeViewports = async (
  page: Page,
  findings: string[],
): Promise<{ dockVisible: boolean; sidebarVisible: boolean }> => {
  await page.setViewportSize({
    width: VIEWPORT_WIDTH_MOBILE_PROOF,
    height: VIEWPORT_HEIGHT_MOBILE_PROOF,
  });
  await wait(page, MS_SIX_HUNDRED);
  const dock = page.locator("[data-testid='app-dock'], nav.dock, .dock").first();
  let dockVisible = false;
  if ((await dock.count()) > 0) {
    const dockVis = await settle(dock.isVisible());
    dockVisible = dockVis.status === "fulfilled" && dockVis.value;
  }
  await shot(page, "04-mobile-viewport");
  await page.setViewportSize(DESKTOP_VIEWPORT);
  await wait(page, MS_SIX_HUNDRED);
  const sidebar = page.locator("aside").first();
  let sidebarVisible = false;
  if ((await sidebar.count()) > 0) {
    const sideVis = await settle(sidebar.isVisible());
    sidebarVisible = sideVis.status === "fulfilled" && sideVis.value;
  }
  if (!sidebarVisible) {
    findings.push("Desktop sidebar not visible at 1440");
  }
  await shot(page, "05-desktop-viewport");
  if (!dockVisible) {
    findings.push("Mobile dock not visibly present at 390 (check selector/IA)");
  }
  return { dockVisible, sidebarVisible };
};

const main = async (): Promise<void> => {
  await mkdir(join(OUT, "stills"), { recursive: true });
  await mkdir(join(OUT, "raw"), { recursive: true });
  const findings: string[] = [];
  const browser = await chromium.launch({
    headless: false,
    args: ["--disable-dev-shm-usage"],
  });
  const context = await browser.newContext({
    recordVideo: { dir: join(OUT, "raw"), size: DESKTOP_VIEWPORT },
    viewport: DESKTOP_VIEWPORT,
  });
  const page = await context.newPage();
  let navCount = 0;
  page.on("framenavigated", (frame) => {
    if (frame === page.mainFrame()) {
      navCount += 1;
    }
  });
  await probeResumeCm6(page, findings, () => navCount);
  await probeThemeFlip(page, findings);
  await probeOmniSearch(page, findings);
  const { dockVisible, sidebarVisible } = await probeViewports(page, findings);
  const floatingChat = await page
    .locator("[aria-label*='floating chat' i], [aria-label*='Show floating chat' i]")
    .count();
  if (floatingChat > 0) {
    findings.push("Floating chat still present — dual chrome");
  }
  const video = page.video();
  await context.close();
  await browser.close();
  let videoPath: string | null = null;
  if (video) {
    const raw = await video.path();
    videoPath = join(OUT, "dom-reactivity.webm");
    await Bun.write(videoPath, Bun.file(raw));
  }
  const report = { ok: findings.length === 0, findings, videoPath, dockVisible, sidebarVisible };
  await writeFile(join(OUT, "report.json"), `${JSON.stringify(report, null, 2)}\n`);
  await writeOutput(
    `dom-reactivity: findings=${String(findings.length)} video=${videoPath ?? "none"}`,
  );
  await reportFindingsAndExit(findings);
};

const runResult = await settle(main());
if (runResult.status === "rejected") {
  await writeError(runResult.reason.message);
  process.exit(1);
}

