const probeMobileDock = async (mobile: Page, findings: Finding[]): Promise<void> => {
  await mobile.goto(`${CLIENT_BASE}${APP_ROUTES.dashboard}`, { waitUntil: "domcontentloaded" });
  await settlePage(mobile, MS_NINE_HUNDRED);
  const dockHrefs = await mobile
    .locator("nav.dock a")
    .evaluateAll((els) => els.map((el) => el.getAttribute("href") ?? ""));
  const expectedDockPaths = [
    APP_ROUTES.dashboard,
    APP_ROUTES.jobs,
    APP_ROUTES.resume,
    APP_ROUTES.aiChat,
    APP_ROUTES.settings,
  ];
  const dockOk =
    dockHrefs.length === DOCK_NAVIGATION_IDS.length &&
    expectedDockPaths.every((path, index) => dockHrefs[index] === path);
  findings.push({
    check: "mobile-dock-set",
    ok: dockOk,
    detail: `dock=${JSON.stringify(dockHrefs)}`,
  });
