const RE_TARGET_POSITION = /Target position/i;
const RE_EDIT_COVER = /Edit cover letter/i;
const COVER_LETTER_DETAIL_URL_PATTERN = /\/cover-letter\/[^/]+/u;
const RE_OPEN_PROJECT = /Open project creation dialog/i;
const RE_PROJECT_TITLE = /Project title/i;
const RE_PROJECT_DESCRIPTION = /Project description/i;
const RE_TECH_INPUT = /Technology input/i;
const RE_ADD_TECH = /Add technology to project/i;
const RE_SAVE_PROJECT = /Save project changes/i;
const RE_CANCEL_PROJECT = /Cancel project changes|Close project modal/i;
const RE_EXPORT_PORTFOLIO = /Export portfolio/i;

const wait = settlePage;

const saveDownload = async (download: Download, name: string): Promise<string> => {
  const target = join(OUT, "downloads", name);
  await download.saveAs(target);
  return target;
};

const dismissCreateDialogIfOpen = async (page: Page): Promise<void> => {
  const cancel = page.getByRole("button", { name: RE_CANCEL_CREATE }).first();
  if ((await cancel.count()) > 0 && (await cancel.isVisible())) {
    await cancel.click();
    await wait(page, COUNT_FIVE_HUNDRED);
  }
};

const ensureResumeViaUi = async (page: Page): Promise<void> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.resume}`, {
    waitUntil: "domcontentloaded",
    timeout: 60_000,
  });
  await wait(page, MS_ONE_AND_HALF_SECONDS);
  await dismissCreateDialogIfOpen(page);

  const editButton = page.getByRole("button", { name: RE_EDIT_ARIA }).first();
  if ((await editButton.count()) > 0 && (await editButton.isVisible())) {
    await editButton.click();
    await wait(page, MS_ONE_TWO_HUNDRED);
    await page.screenshot({ path: join(OUT, "stills", "00-edit-existing.png") });
    return;
  }

  await page.getByRole("button", { name: RE_CREATE_ARIA }).click();
  await wait(page, MS_EIGHT_HUNDRED);
  const nameInput = page.getByLabel(RE_FULL_NAME).first();
  if ((await nameInput.count()) > 0) {
    await nameInput.click();
    await nameInput.fill("");
    await nameInput.pressSequentially("Bao UI Proof", { delay: 20 });
  }
  await page.getByRole("button", { name: RE_CREATE_SUBMIT }).click();
  await wait(page, MS_ONE_AND_HALF_SECONDS);
  const saveButton = page.getByRole("button", { name: RE_SAVE }).first();
  if ((await saveButton.count()) > 0 && (await saveButton.isVisible())) {
    await saveButton.click();
    await wait(page, MS_ONE_AND_HALF_SECONDS);
  }
  await page.screenshot({ path: join(OUT, "stills", "00-created-via-ui.png") });
};

const exportPdfViaUi = async (page: Page): Promise<string> => {
  await page.getByRole("button", { name: RE_EXPORT }).first().click();
  await wait(page, COUNT_FIVE_HUNDRED);
  const downloadPromise = page.waitForEvent("download", { timeout: 45_000 });
  await page.getByRole("menuitem", { name: RE_EXPORT_PDF }).first().click();
  const downloadResult = await settle(downloadPromise);
  if (downloadResult.status === "rejected") {
    await page.screenshot({ path: join(OUT, "stills", "pdf-failed.png") });
    throw new Error(`PDF download failed: ${downloadResult.reason.message}`);
  }
  return saveDownload(downloadResult.value, "resume-ui.pdf");
};

const openOrGenerateCoverLetter = async (page: Page): Promise<void> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.coverLetter}`, {
    waitUntil: "domcontentloaded",
    timeout: 60_000,
  });
  await wait(page, MS_ONE_AND_HALF_SECONDS);
  const existingCover = page.getByRole("button", { name: RE_EDIT_COVER }).first();
  if ((await existingCover.count()) > 0 && (await existingCover.isVisible())) {
    await existingCover.click();
    await wait(page, MS_ONE_AND_HALF_SECONDS);
    return;
  }
  await page.getByRole("button", { name: RE_OPEN_COVER_GENERATE }).click();
  await wait(page, MS_EIGHT_HUNDRED);
  const company = page.getByLabel(RE_TARGET_COMPANY);
  await company.click();
  await company.fill("");
  await company.pressSequentially("Riot Games", { delay: 20 });
  const position = page.getByLabel(RE_TARGET_POSITION);
  await position.click();
  await position.fill("");
  await position.pressSequentially("Gameplay Engineer", { delay: 20 });
  await page.getByRole("button", { name: RE_COVER_GENERATE }).click();
  await page.waitForURL(COVER_LETTER_DETAIL_URL_PATTERN, { timeout: 180_000 });
  await wait(page, MS_ONE_AND_HALF_SECONDS);
};

const proofCoverLetterPdf = async (page: Page) => {
  await openOrGenerateCoverLetter(page);
  await page.screenshot({ path: join(OUT, "stills", "02-cover-letter-detail.png") });
  await page.getByRole("button", { name: RE_EXPORT }).first().click();
  await wait(page, COUNT_FIVE_HUNDRED);
  const coverDownloadPromise = page.waitForEvent("download", { timeout: 45_000 });
  await page.getByRole("menuitem", { name: RE_EXPORT_PDF }).first().click();
  const coverDownload = await settle(coverDownloadPromise);
  if (coverDownload.status === "rejected") {
    await page.screenshot({ path: join(OUT, "stills", "cover-pdf-failed.png") });
    throw new Error(`Cover letter PDF download failed: ${coverDownload.reason.message}`);
  }
  const coverPath = await saveDownload(coverDownload.value, "cover-letter-ui.pdf");
  const coverLetterPdf = await assertRealPdfFile(coverPath);
  await page.screenshot({ path: join(OUT, "stills", "03-cover-letter-pdf-exported.png") });
  return coverLetterPdf;
};

const ensurePortfolioProject = async (page: Page): Promise<void> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.portfolio}`, {
    waitUntil: "domcontentloaded",
    timeout: 60_000,
  });
  await wait(page, MS_ONE_TWO_HUNDRED);
  await settle(
    page.getByRole("button", { name: RE_CANCEL_PROJECT }).first().click({ timeout: 2_000 }),
  );
  await wait(page, MS_FOUR_HUNDRED);
  const exportPortfolio = page.getByRole("button", { name: RE_EXPORT_PORTFOLIO }).first();
  if ((await exportPortfolio.count()) > 0 && (await exportPortfolio.isVisible())) {
    return;
  }
  await page.getByRole("button", { name: RE_OPEN_PROJECT }).click();
  await wait(page, MS_SIX_HUNDRED);
  const title = page.getByLabel(RE_PROJECT_TITLE);
  await title.click();
  await title.fill("");
  await title.pressSequentially("Bao RPA Dungeon Demo", { delay: 15 });
  const description = page.getByLabel(RE_PROJECT_DESCRIPTION);
  await description.click();
  await description.fill("");
  await description.pressSequentially(
    "Shipped a multiplayer dungeon crawler prototype with networked combat and live ops tooling for game-industry hiring demos.",
    { delay: 5 },
  );
  const tech = page.getByLabel(RE_TECH_INPUT);
  await tech.click();
  await tech.fill("");
  await tech.pressSequentially("TypeScript", { delay: 15 });
  await page.getByRole("button", { name: RE_ADD_TECH }).click();
  await page.getByRole("button", { name: RE_SAVE_PROJECT }).click();
  await wait(page, MS_TWO_SECONDS);
};

const proofPortfolioPdf = async (page: Page) => {
  await ensurePortfolioProject(page);
  const templateSelect = page.getByLabel("Portfolio export template");
  await templateSelect.waitFor({ state: "visible", timeout: 30_000 });
  await templateSelect.selectOption("gaming");
  await wait(page, COUNT_FIVE_HUNDRED);
  await page.screenshot({ path: join(OUT, "stills", "04-portfolio-ready.png") });
  await page.getByRole("button", { name: RE_EXPORT_PORTFOLIO }).click();
  await wait(page, COUNT_FIVE_HUNDRED);
  const portfolioDownloadPromise = page.waitForEvent("download", { timeout: 45_000 });
  await page.getByRole("menuitem", { name: RE_EXPORT_PDF }).first().click();
  const portfolioDownload = await settle(portfolioDownloadPromise);
  if (portfolioDownload.status === "rejected") {
    await page.screenshot({ path: join(OUT, "stills", "portfolio-pdf-failed.png") });
    throw new Error(`Portfolio PDF download failed: ${portfolioDownload.reason.message}`);
  }
  const portfolioPath = await saveDownload(portfolioDownload.value, "portfolio-ui.pdf");
  const portfolioPdf = await assertRealPdfFile(portfolioPath);
  const paletteOk = await assertPdfContainsRgbFill(
    portfolioPath,
    PORTFOLIO_EXPORT_THEME_BY_TEMPLATE.gaming.primary,
    "portfolio-gaming-primary",
  );
  if (!paletteOk) {
    throw new Error("Portfolio gaming PDF missing SSOT primary fill");
  }
  await page.screenshot({ path: join(OUT, "stills", "05-portfolio-pdf-exported.png") });
  return portfolioPdf;
};

const writePdfReport = async (
  resumeAssertion: Awaited<ReturnType<typeof assertRealPdfFile>>,
  coverLetterPdf: Awaited<ReturnType<typeof assertRealPdfFile>>,
  portfolioPdf: Awaited<ReturnType<typeof assertRealPdfFile>>,
): Promise<void> => {
  if (!resumeAssertion.ok || !coverLetterPdf.ok || !portfolioPdf.ok) {
    process.exit(1);
  }
  await Bun.write(
    join(OUT, "report.json"),
    `${JSON.stringify(
      {
        ok: true,
        mode: "ui-click-type",
        resumePdf: resumeAssertion,
        coverLetterPdf,
        portfolioPdf,
      },
      null,
      2,
    )}\n`,
  );
  await writeOutput(`browser-proof-pdf-live OK (UI) → ${OUT}`);
};

const main = async (): Promise<void> => {
  await mkdir(join(OUT, "stills"), { recursive: true });
  await mkdir(join(OUT, "downloads"), { recursive: true });

  const browser = await chromium.launch({ headless: false, args: ["--disable-dev-shm-usage"] });
  const context = await browser.newContext({ acceptDownloads: true });
  const page = await context.newPage();
  await page.setViewportSize({ width: 1440, height: 900 });

  await ensureResumeViaUi(page);
  const resumePath = await exportPdfViaUi(page);
  const resumeAssertion = await assertRealPdfFile(resumePath);
  await page.screenshot({ path: join(OUT, "stills", "01-resume-pdf-exported.png") });

  const coverLetterPdf = await proofCoverLetterPdf(page);
  const portfolioPdf = await proofPortfolioPdf(page);
  await browser.close();
  await writePdfReport(resumeAssertion, coverLetterPdf, portfolioPdf);
};

const runResult = await settle(main());
if (runResult.status === "rejected") {
  await writeError(runResult.reason.message);
  process.exit(1);
}

/**
 * Fail-closed headed RPA proof — UI click/type only (no API inject).
 * Flow: Settings enable portal → Scraper Run → Runs history → Job Apply.
 */

import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { chromium, type Page } from "playwright";
import { API_ENDPOINTS } from "../packages/shared/src/constants/endpoints";
import { APP_ROUTE_BUILDERS, APP_ROUTES } from "../packages/shared/src/constants/routes";
import { settle } from "../packages/shared/src/utils/promise";
import {
  COUNT_FIVE_HUNDRED,
  MS_MINUTE,
  MS_ONE_AND_HALF_SECONDS,
  MS_SECOND,
  MS_TEN_SECONDS,
  MS_TWO_AND_HALF_SECONDS,
  MS_TWO_MINUTES,
  MS_TWO_SECONDS,
} from "./constants/numeric-literals";
import { pollUntil } from "./utils/async-control";
import { writeError, writeOutput } from "./utils/cli-output";
import { settlePage } from "./utils/playwright-settle";

const CLIENT_BASE = (process.env.PAGE_PROOF_CLIENT_BASE ?? "http://127.0.0.1:3001").replace(
  /\/$/u,
  "",
);
const OUT = process.env.RPA_PROOF_OUT ?? "/opt/cursor/artifacts/live-capabilities/rpa-live-ui";

const RE_ENABLE_WWI = /Enable Work With Indies job portal scraper/i;
const RE_SAVE_PROVIDERS = /Save job provider configuration/i;
const RE_JOB_URL = /Job posting URL/i;
const RE_JOB_URL_PLACEHOLDER = /Paste the job posting URL/i;
const RE_SELECT_RESUME = /Select resume/i;
const RE_RUN_APPLICATION = /Run job application automation/i;
const RE_RUN_JOB_SCRAPER = /Run job scraper/i;
const RE_RUN_STUDIO_SCRAPER = /Run studio scraper/i;
const RUNS_URL_PATTERN = /\/automation\/runs/u;
const RUN_STATUS_SIGNAL_PATTERN = /queued|running|completed|success|failed|scrape/iu;

const wait = settlePage;

const shot = async (page: Page, name: string): Promise<void> => {
  await page.screenshot({ path: join(OUT, "stills", `${name}.png`), fullPage: false });
};

const enablePortalViaUi = async (page: Page): Promise<void> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTE_BUILDERS.settingsSection("jobIntelligence")}`, {
    waitUntil: "domcontentloaded",
  });
  await wait(page, MS_ONE_AND_HALF_SECONDS);
  const toggle = page.getByLabel(RE_ENABLE_WWI);
  await toggle.scrollIntoViewIfNeeded();
  if (!(await toggle.isChecked())) {
    await toggle.click();
  }
  await page.getByRole("button", { name: RE_SAVE_PROVIDERS }).click();
  await wait(page, MS_TWO_SECONDS);
  await shot(page, "01-providers-enabled");
};

const API_BASE = (process.env.PAGE_PROOF_API_BASE ?? "http://127.0.0.1:3000").replace(/\/$/u, "");

const countRunsViaApi = async (): Promise<number> => {
  const response = await fetch(`${API_BASE}${API_ENDPOINTS.automationRuns}`, {
    signal: AbortSignal.timeout(MS_TEN_SECONDS),
  });
  if (!response.ok) {
    throw new Error(`GET ${API_ENDPOINTS.automationRuns} → ${String(response.status)}`);
  }
  const body: unknown = await response.json();
  return Array.isArray(body) ? body.length : 0;
};

const pickEnabledRunner = async (page: Page) => {
  // Prefer job scraper (portal feeds) over long studio crawls when both are armed.
  const preferred = [
    page.getByRole("button", { name: RE_RUN_JOB_SCRAPER }),
    page.getByRole("button", { name: RE_RUN_STUDIO_SCRAPER }),
  ];
  const candidateGroups = await Promise.all(
    preferred.map(async (locator) => {
      const total = await locator.count();
      return Array.from({ length: total }, (_, index) => locator.nth(index));
    }),
  );
  const probes = await Promise.all(
    candidateGroups.flat().map(async (candidate) => ({
      candidate,
      enabled: (await candidate.isVisible()) && !(await candidate.isDisabled()),
    })),
  );
  return probes.find((probe) => probe.enabled)?.candidate ?? null;
};

const runScraperViaUi = async (page: Page): Promise<void> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.automationScraper}`, {
    waitUntil: "domcontentloaded",
  });
  await wait(page, MS_ONE_AND_HALF_SECONDS);
  await shot(page, "02-scraper-hub");

  // Wait out in-flight scrapes that disable Run buttons (pendingAction global).
  const runner = await pollUntil({
    probe: async () => {
      const candidate = await pickEnabledRunner(page);
      if (candidate) {
        return candidate;
      }
      await page.reload({ waitUntil: "domcontentloaded" });
      await wait(page, MS_ONE_AND_HALF_SECONDS);
      return null;
    },
    intervalMs: MS_TWO_SECONDS,
    timeoutMs: MS_TWO_MINUTES,
    sleep: (milliseconds) => wait(page, milliseconds),
  });
  if (!runner) {
    throw new Error("No enabled Run Scraper button in UI after waiting for idle");
  }
  await runner.scrollIntoViewIfNeeded();
  await runner.click();
  await wait(page, MS_TWO_SECONDS);
  await shot(page, "03-scraper-clicked");
};

const countRunRows = async (page: Page): Promise<number> =>
  page.locator("main table tbody tr").count();

const waitForApiRunGrowth = async (beforeCount: number): Promise<number> => {
  const after = await pollUntil({
    probe: async () => {
      const count = await countRunsViaApi();
      return count > beforeCount ? count : null;
    },
    intervalMs: MS_SECOND,
    timeoutMs: MS_MINUTE,
    sleep: (milliseconds) => Bun.sleep(milliseconds),
  });
  if (after === null) {
    throw new Error(
      `Automation runs API did not grow after scraper click (before=${String(beforeCount)}) — RPA not integrated`,
    );
  }
  return after;
};

const assertRunsViaUi = async (page: Page, beforeCount: number): Promise<number> => {
  const apiAfter = await waitForApiRunGrowth(beforeCount);
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.automationRuns}`, {
    waitUntil: "domcontentloaded",
  });
  await page.waitForURL(RUNS_URL_PATTERN, { timeout: 30_000 });
  await wait(page, MS_TWO_AND_HALF_SECONDS);
  await shot(page, "04-runs-history");
  const afterCount = await countRunRows(page);
  const body = await page.locator("main").innerText();
  // Fail-closed: UI table must show growth (API already confirmed a new run).
  if (!(afterCount > beforeCount)) {
    throw new Error(
      `Runs history UI stale after scraper click (before=${String(beforeCount)} ui=${String(afterCount)} api=${String(apiAfter)} bodyHasScrapeSignal=${String(RUN_STATUS_SIGNAL_PATTERN.test(body))}) — RPA not integrated`,
    );
  }
  return afterCount;
};

const jobApplyViaUi = async (page: Page): Promise<void> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.automationJobApply}`, {
    waitUntil: "domcontentloaded",
  });
  await wait(page, MS_ONE_AND_HALF_SECONDS);
  const urlInput = page.getByPlaceholder(RE_JOB_URL_PLACEHOLDER).or(page.getByLabel(RE_JOB_URL));
  await urlInput.first().waitFor({ state: "visible", timeout: MS_TEN_SECONDS });
  await urlInput.first().click();
  await urlInput.first().fill("");
  await urlInput.first().pressSequentially("https://boards.greenhouse.io/discord/jobs/6982349", {
    delay: 10,
  });
  const resumeSelect = page.getByLabel(RE_SELECT_RESUME);
  await resumeSelect.waitFor({ state: "visible", timeout: MS_TEN_SECONDS });
  // Wait until bootstrap finishes populating resume options.
  await pollUntil({
    probe: async () => ((await resumeSelect.locator("option").count()) > 1 ? true : null),
    intervalMs: MS_SECOND,
    timeoutMs: MS_TEN_SECONDS,
    sleep: (milliseconds) => wait(page, milliseconds),
  });
  await resumeSelect.selectOption({ index: 1 });
  const runApply = page.getByRole("button", { name: RE_RUN_APPLICATION });
  await pollUntil({
    probe: async () => ((await runApply.isDisabled()) ? null : true),
    intervalMs: COUNT_FIVE_HUNDRED,
    timeoutMs: MS_TEN_SECONDS,
    sleep: (milliseconds) => wait(page, milliseconds),
  });
  if (await runApply.isDisabled()) {
    await shot(page, "05-job-apply-form-filled");
    throw new Error("Run Application stayed disabled after typing URL + selecting resume");
  }
  await shot(page, "05-job-apply-form-ready");
  await runApply.click();
  await wait(page, MS_TEN_SECONDS);
  await shot(page, "05-job-apply-ran");
};

const main = async (): Promise<void> => {
  await mkdir(join(OUT, "stills"), { recursive: true });
  await mkdir(join(OUT, "raw"), { recursive: true });
  const browser = await chromium.launch({ headless: false, args: ["--disable-dev-shm-usage"] });
  const context = await browser.newContext({
    recordVideo: { dir: join(OUT, "raw"), size: { width: 1440, height: 900 } },
    viewport: { width: 1440, height: 900 },
  });
  const page = await context.newPage();

  await enablePortalViaUi(page);

  const beforeCount = await countRunsViaApi();

  await runScraperViaUi(page);
  const afterCount = await assertRunsViaUi(page, beforeCount);

  let jobApplyOk = false;
  let jobApplyError: string | null = null;
  const applyResult = await settle(jobApplyViaUi(page));
  if (applyResult.status === "fulfilled") {
    jobApplyOk = true;
  } else {
    jobApplyError = applyResult.reason.message;
    await writeError(`job-apply UI: ${jobApplyError}`);
  }

  const video = page.video();
  await context.close();
  await browser.close();

  let videoPath: string | null = null;
  if (video) {
    const raw = await video.path();
    videoPath = join(OUT, "rpa-integration-demo.webm");
    await Bun.write(videoPath, Bun.file(raw));
  }

  const scraperDeltaOk = afterCount > beforeCount;
  const ok = scraperDeltaOk && jobApplyOk;
  await writeFile(
    join(OUT, "report.json"),
    `${JSON.stringify(
      {
        ok,
        mode: "ui-click-type+video",
        scraper: { ran: scraperDeltaOk, runsBefore: beforeCount, runsAfter: afterCount },
        jobApply: { ok: jobApplyOk, error: jobApplyError },
        videoPath,
      },
      null,
      2,
    )}\n`,
  );
  if (!ok) {
    throw new Error(
      `browser-proof-rpa-live FAIL scraperDelta=${String(scraperDeltaOk)} jobApply=${String(jobApplyOk)} error=${jobApplyError ?? "none"}`,
    );
  }
  await writeOutput(`browser-proof-rpa-live OK (UI) video=${videoPath ?? "none"} → ${OUT}`);
};

const runResult = await settle(main());
if (runResult.status === "rejected") {
  await writeError(runResult.reason.message);
  process.exit(1);
}

