  COUNT_TWELVE,
  MS_EIGHT_HUNDRED,
  MS_FORTY_FIVE_SECONDS,
  MS_FOUR_HUNDRED,
  MS_ONE_AND_HALF_SECONDS,
  MS_ONE_TWO_HUNDRED,
  MS_SIX_HUNDRED,
  MS_SIXTY_SECONDS,
