const CLIENT_BASE = (process.env.PAGE_PROOF_CLIENT_BASE ?? "http://127.0.0.1:3001").replace(
  /\/$/u,
  "",
);
const OUT = process.env.AI_PDF_DEMO_OUT ?? "/opt/cursor/artifacts/baseline/ai-pdf-video";
