/**
 * Live LLM + Whisper probes and settings seed for product demo.
 */
import {
  FAKE_AUDIO_WAV,
  LOCAL_ENDPOINT,
  RE_BAO_DEMO_DETERMINISTIC,
  RE_BUILD_DETERMINISTIC_CONTENT,
  RE_DETERMINISTIC_AI,
  SERVER_BASE,
  WHISPER_ENDPOINT,
} from "./browser-record-product-demo-shared";
