const capturePageSignals = async (page: PageInstance): Promise<PageSignalSnapshot> =>
  page.evaluate(() => {
    const collectTexts = (selector: string): readonly string[] =>
      Array.from(document.querySelectorAll(selector))
        .map((node) => node.textContent?.replace(/\s+/gu, " ").trim() ?? "")
        .filter((value) => value.length > 0);

    const headingText =
      [...collectTexts("main h1"), ...collectTexts("h1")]
        .sort((left, right) => right.length - left.length)
        .at(0) ?? "";
    const bodyText = document.body.textContent?.replace(/\s+/gu, " ").trim() ?? "";

    return {
      heading: headingText.length > 0 ? headingText : null,
      alerts: collectTexts('[role="alert"], .alert, [data-page-state="error"]'),
      bodyText,
    };
  });

const pageStillLoading = async (page: PageInstance): Promise<boolean> =>
  page.evaluate(() => {
    const skeletonCount = document.querySelectorAll(".skeleton").length;
    const loadingIndicatorCount = document.querySelectorAll(".loading").length;
    const mainText =
      document.querySelector("main")?.textContent?.replace(/\s+/gu, " ").trim() ?? "";

    if (skeletonCount > 0) {
      return true;
    }

    if (loadingIndicatorCount === 0) {
      return false;
    }

    return mainText.length === 0;
  });

const waitForSettledIteration = async (page: PageInstance, waitedMs: number): Promise<void> => {
  if (waitedMs >= DEFAULT_SETTLE_TIMEOUT_MS) {
    return;
  }

  const stillLoading = await pageStillLoading(page);
  if (!stillLoading) {
    return;
  }

  await page.waitForLoadState("domcontentloaded", {
    timeout: DEFAULT_SETTLE_POLL_INTERVAL_MS,
  });
  return waitForSettledIteration(page, waitedMs + DEFAULT_SETTLE_POLL_INTERVAL_MS);
};

const waitForPageToSettle = async (page: PageInstance): Promise<void> => {
  await page.waitForLoadState("load", {
    timeout: DEFAULT_WAIT_AFTER_NAVIGATION_MS,
  });
  return waitForSettledIteration(page, 0);
};

const capturePageProof = async (
  browser: BrowserInstance,
  clientBase: string,
  outputDirectory: string,
  spec: PageProofRouteSpec,
): Promise<PageProofReportItem> => {
  const page = await browser.newPage({ viewport: DEFAULT_VIEWPORT });
  const url = `${clientBase}${spec.route}`;
  await page.goto(url, {
    waitUntil: "domcontentloaded",
    timeout: DEFAULT_NAVIGATION_TIMEOUT_MS,
  });
  await waitForPageToSettle(page);

  const title = normalizeText(await page.title());
  const snapshot = await capturePageSignals(page);
  const screenshotPath = join(outputDirectory, `${spec.slug}.png`);
  await page.screenshot({
    path: screenshotPath,
    fullPage: true,
  });

  const loweredAlertText = snapshot.alerts.join(" ").toLowerCase();
  const flaggedKeywords = FLAGGED_KEYWORDS.filter((keyword) => loweredAlertText.includes(keyword));

  return {
    slug: spec.slug,
    route: spec.route,
    url,
    screenshotPath,
    title,
    h1: snapshot.heading,
    alerts: snapshot.alerts,
    flaggedKeywords,
  };
};

const buildMarkdownReport = (report: readonly PageProofReportItem[]): string => {
  const lines = [
    "# Page Proof Report",
    "",
    `Generated at ${new Date().toISOString()}`,
    "",
    "| Slug | Route | Title | H1 | Alerts | Flagged keywords | Screenshot |",
    "|------|-------|-------|----|--------|------------------|------------|",
  ];

  for (const item of report) {
    lines.push(
      `| ${item.slug} | ${item.route} | ${item.title || "n/a"} | ${item.h1 || "n/a"} | ${item.alerts.length} | ${
        item.flaggedKeywords.length > 0 ? item.flaggedKeywords.join(", ") : "none"
      } | ${item.screenshotPath} |`,
    );
  }

  return `${lines.join("\n")}\n`;
};

const capturePageProofReport = async (
  input: CapturePageProofReportInput,
): Promise<readonly PageProofReportItem[]> => {
  const { browser, clientBase, outputDirectory, remainingSpecs, captured = [] } = input;
  const [nextSpec, ...nextSpecs] = remainingSpecs;
  if (!nextSpec) {
    return captured;
  }

  const nextItem = await capturePageProof(browser, clientBase, outputDirectory, nextSpec);
  return capturePageProofReport({
    browser,
    clientBase,
    outputDirectory,
    remainingSpecs: nextSpecs,
    captured: [...captured, nextItem],
  });
};

const main = async (): Promise<void> => {
  const apiBase = resolveApiBase();
  const clientBase = resolveClientBase();
  const outputDirectory = resolveOutputDirectory();
  await writeOutput(`page-proof: writing screenshots to ${outputDirectory}`);
  await rm(outputDirectory, { recursive: true, force: true });
  await mkdir(outputDirectory, { recursive: true });

  const ids = await resolvePageIdentifiers(apiBase);
  const routeSpecs = buildRouteSpecs(ids);
  const browser = await chromium.launch({ headless: true });
  const report = await capturePageProofReport({
    browser,
    clientBase,
    outputDirectory,
    remainingSpecs: routeSpecs,
  });
  await browser.close();

  const jsonPath = join(outputDirectory, "report.json");
  const markdownPath = join(outputDirectory, "report.md");
  await writeFile(jsonPath, `${JSON.stringify(report, null, 2)}\n`);
  await writeFile(markdownPath, buildMarkdownReport(report));
  await writeOutput(`page-proof: captured ${report.length} routes`);
  await writeOutput(`page-proof: report.json -> ${jsonPath}`);
  await writeOutput(`page-proof: report.md -> ${markdownPath}`);
};

await main().then(undefined, async (error: unknown) => {
  const message =
    error instanceof Error ? error.message : `Unknown page proof failure: ${String(error)}`;
  await writeError(`page-proof: ${message}`);
  process.exitCode = 1;
});

import {
  AGENTIFLOW_CAPABILITY_MATRIX_PATH,
  buildAgentiflowCapabilityMatrix,
  resolveAgentiflowCapabilityMatrixRelativePath,
} from "./utils/agentiflow-capability-matrix";
import { captureResult, toErrorMessage } from "./utils/async-control";
import { formatJsonWithBiome } from "./utils/biome-format";
import { writeError, writeOutput } from "./utils/cli-output";

type JsonRecord = Record<string, unknown>;

const isRecord = (value: unknown): value is JsonRecord =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const normalizeMatrixForComparison = (value: unknown): unknown => {
  if (!isRecord(value)) {
    return value;
  }

  const normalizedValue = { ...value };
  normalizedValue.generatedAt = undefined;
  return normalizedValue;
};

const main = async (): Promise<void> => {
  const matrix = await buildAgentiflowCapabilityMatrix();
  const expectedText = await formatJsonWithBiome(
    AGENTIFLOW_CAPABILITY_MATRIX_PATH,
    normalizeMatrixForComparison(matrix),
  );
  const matrixFile = Bun.file(AGENTIFLOW_CAPABILITY_MATRIX_PATH);
  const currentText = (await matrixFile.exists()) ? await matrixFile.text() : "";

  if (currentText.length === 0) {
    throw new Error(
      `Capability matrix drift detected in ${resolveAgentiflowCapabilityMatrixRelativePath()}. Run bun run capability:matrix.`,
    );
  }

  const currentValue: unknown = JSON.parse(currentText);
  const normalizedCurrentText = await formatJsonWithBiome(
    AGENTIFLOW_CAPABILITY_MATRIX_PATH,
    normalizeMatrixForComparison(currentValue),
  );

  if (normalizedCurrentText !== expectedText) {
    throw new Error(
      `Capability matrix drift detected in ${resolveAgentiflowCapabilityMatrixRelativePath()}. Run bun run capability:matrix.`,
    );
  }

  await writeOutput(
    `agentiflow capability matrix is current: ${resolveAgentiflowCapabilityMatrixRelativePath()}`,
  );
};

const result = await captureResult(main);
if (!result.ok) {
  await writeError(
    toErrorMessage(result.error, "Failed to validate the agentiflow capability matrix."),
  );
  process.exit(1);
}

import { rm, stat } from "node:fs/promises";
import { join, resolve } from "node:path";
import { writeError, writeOutput } from "./utils/cli-output";

type MountedDesktopImage = {
  readonly imagePath: string;
  readonly mountPaths: readonly string[];
};

const REPO_ROOT = resolve(import.meta.dir, "..");
const DESKTOP_TAURI_ROOT = join(REPO_ROOT, "packages", "desktop", "src-tauri");
const DESKTOP_TEMP_DMG_GLOB = new Bun.Glob("target/**/bundle/**/rw.*.dmg");
const DESKTOP_MOUNTED_IMAGE_PATTERN = /\/bundle\/(?:dmg|macos)\/rw\..+\.dmg$/;
const MOUNT_LINE_SPLIT_PATTERN = /\t+/;

const runCommand = async (
  command: readonly string[],
  cwd: string = REPO_ROOT,
  env: Record<string, string | undefined> = process.env,
): Promise<number> => {
  const proc = Bun.spawn(command as string[], {
    cwd,
    env,
    stdout: "inherit",
    stderr: "inherit",
  });

  return proc.exited;
};

const readCommand = async (command: readonly string[]): Promise<string> => {
  const proc = Bun.spawn(command as string[], {
    cwd: REPO_ROOT,
    env: process.env,
    stdout: "pipe",
    stderr: "inherit",
  });
  const exitCode = await proc.exited;
  if (exitCode !== 0 || !(proc.stdout instanceof ReadableStream)) {
    await writeError(`${command.join(" ")} failed with exit code ${exitCode}.`);
    process.exit(exitCode || 1);
  }

  return new Response(proc.stdout).text();
};

const pathExists = async (candidatePath: string): Promise<boolean> =>
  stat(candidatePath).then(
    () => true,
    () => false,
  );

const parseMountedDesktopImages = (infoText: string): readonly MountedDesktopImage[] =>
  infoText.split("================================================").flatMap((sectionText) => {
    const lines = sectionText
      .split("\n")
      .map((line) => line.trim())
      .filter((line) => line.length > 0);
    const imagePathLine = lines.find((line) => line.startsWith("image-path"));
    if (!imagePathLine) {
      return [];
    }

    const imagePath = imagePathLine.split(":").slice(1).join(":").trim();
    if (
      !(imagePath.startsWith(DESKTOP_TAURI_ROOT) && DESKTOP_MOUNTED_IMAGE_PATTERN.test(imagePath))
    ) {
      return [];
    }

    const mountPaths = lines.flatMap((line) => {
      const parts = line.split(MOUNT_LINE_SPLIT_PATTERN);
      return parts.filter((part) => part.startsWith("/Volumes/"));
    });

    return [{ imagePath, mountPaths }];
  });

const collectTemporaryDiskImages = async (): Promise<readonly string[]> => {
  const imagePaths: string[] = [];
  for await (const relativePath of DESKTOP_TEMP_DMG_GLOB.scan({
    cwd: DESKTOP_TAURI_ROOT,
  })) {
    imagePaths.push(join(DESKTOP_TAURI_ROOT, relativePath));
  }

  return imagePaths;
};

const detachMountPathsSequentially = async (
  mountPaths: readonly string[],
  index: number = 0,
): Promise<void> => {
  const mountPath = mountPaths[index];
  if (!mountPath) {
    return;
  }

  await writeOutput(`Detaching stale desktop image mount ${mountPath}`);
  const exitCode = await runCommand(["hdiutil", "detach", mountPath]);
  if (exitCode !== 0) {
    await writeError(`Failed to detach stale desktop image mount ${mountPath}.`);
    process.exit(exitCode);
  }

  await detachMountPathsSequentially(mountPaths, index + 1);
};

const detachMountedImages = async (
  mountedImages: readonly MountedDesktopImage[],
): Promise<void> => {
  const mountPaths = mountedImages.flatMap((mountedImage) => mountedImage.mountPaths);
  await detachMountPathsSequentially(mountPaths);
};

const removeTemporaryDiskImages = async (imagePaths: readonly string[]): Promise<void> => {
  await Promise.all(
    imagePaths.map(async (imagePath) => {
      if (!(await pathExists(imagePath))) {
        return;
      }

      await rm(imagePath, { force: true });
      await writeOutput(`Removed stale desktop disk image ${imagePath}`);
    }),
  );
};

const runPrebuildCleanup = async (): Promise<void> => {
  if (process.platform !== "darwin") {
    await writeOutput("Skipping desktop disk image cleanup outside macOS.");
    return;
  }

  const mountedImages = parseMountedDesktopImages(await readCommand(["hdiutil", "info"]));
  await detachMountedImages(mountedImages);
  await removeTemporaryDiskImages(await collectTemporaryDiskImages());
};

const command = process.argv[2];
if (command !== "prebuild") {
  await writeError("Usage: bun scripts/cleanup-desktop-build.ts prebuild");
  process.exit(1);
}

await runPrebuildCleanup();

/**
 * One-shot codemod: detail: { tags: ["X"] } → openapiDetail("X", "<inferred>")
 */
import { readdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

const ROUTES_ROOT = join(import.meta.dir, "../packages/server/src/routes");
const DETAIL_PATTERN = /detail:\s*\{\s*tags:\s*\["([^"]+)"\]\s*,?\s*\}/gu;
const METHOD_PATH_PATTERN =
  /\.(get|post|put|patch|delete|options|head)\(\s*(?:\n\s*)?["'`]([^"'`]+)["'`]/gu;
const PATH_PARAM_PATTERN = /\{([^}]+)\}/gu;
const PATH_SEPARATOR_PATTERN = /[-_/]+/gu;
const LEADING_SLASH_PATTERN = /^\//u;
const QUOTE_PATTERN = /"/gu;

const verbPhrase = (method: string): string => {
  switch (method.toLowerCase()) {
    case "get":
      return "Retrieve";
    case "post":
      return "Create or execute";
    case "put":
      return "Replace";
    case "patch":
      return "Update";
    case "delete":
      return "Delete";
    default:
      return "Invoke";
  }
};

const humanizePath = (path: string): string => {
  const cleaned = path
    .replace(LEADING_SLASH_PATTERN, "")
    .replace(PATH_PARAM_PATTERN, "$1")
    .replace(PATH_SEPARATOR_PATTERN, " ")
    .trim();
  return cleaned.length > 0 ? cleaned : "resource";
};

const inferDescription = (tag: string, method: string, path: string): string => {
  const action = verbPhrase(method);
  const target = humanizePath(path);
  return `${action} ${tag.toLowerCase()} ${target} for BaoBuildBuddy career automation.`;
};

const nearestMethodPath = (
  content: string,
  detailIndex: number,
): { method: string; path: string } => {
  METHOD_PATH_PATTERN.lastIndex = 0;
  let best: { method: string; path: string; index: number } | null = null;
  let match: RegExpExecArray | null = METHOD_PATH_PATTERN.exec(content);
  while (match) {
    const index = match.index;
    if (index < detailIndex && (best === null || index > best.index)) {
      best = { method: match[1] ?? "get", path: match[2] ?? "/", index };
    }
    match = METHOD_PATH_PATTERN.exec(content);
  }
  return best ?? { method: "get", path: "/" };
};

const ensureImport = (content: string): string => {
  if (content.includes("openapiDetail")) {
    return content;
  }
  const importLine = 'import { openapiDetail } from "../utils/openapi-detail";\n';
  const lastImport = content.lastIndexOf("\nimport ");
  if (lastImport === -1) {
    return `${importLine}${content}`;
  }
  const endOfLine = content.indexOf("\n", lastImport + 1);
  const insertAt = endOfLine === -1 ? content.length : endOfLine + 1;
  return `${content.slice(0, insertAt)}${importLine}${content.slice(insertAt)}`;
};

const transformFile = async (filePath: string): Promise<number> => {
  const original = await readFile(filePath, "utf8");
  if (!DETAIL_PATTERN.test(original)) {
    return 0;
  }
  DETAIL_PATTERN.lastIndex = 0;
  let count = 0;
  const next = original.replace(DETAIL_PATTERN, (_full, tag: string, offset: number) => {
    count += 1;
    const { method, path } = nearestMethodPath(original, offset);
    const description = inferDescription(tag, method, path).replace(QUOTE_PATTERN, "'");
    return `detail: openapiDetail("${tag}", "${description}")`;
  });
  if (count === 0) {
    return 0;
  }
  await writeFile(filePath, ensureImport(next), "utf8");
  return count;
};

const walkTs = async (dir: string): Promise<string[]> => {
  const entries = await readdir(dir, { withFileTypes: true });
  const nested = await Promise.all(
    entries.map(async (entry) => {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        return walkTs(full);
      }
      if (entry.name.endsWith(".ts") && !entry.name.endsWith(".test.ts")) {
        return [full];
      }
      return [] as string[];
    }),
  );
  return nested.flat();
};

const main = async (): Promise<void> => {
  const files = await walkTs(ROUTES_ROOT);
  const appPath = join(import.meta.dir, "../packages/server/src/app.ts");
  files.push(appPath);
  await Promise.all(files.map((file) => transformFile(file)));
};

await main();

