/**
 * Bun installs `@typescript/native` as an alias of `typescript@7`, which makes
 * nested `require("typescript")` from typescript-eslint resolve to TS 7 (no
 * programmatic API → `ts.Extension.Cjs` crash). Pin eslint/ts-api-utils peers
 * to the TS 6.0.3 package that carries the API typescript-eslint needs.
 *
 * Idempotent. Invoked from root `postinstall` after `bun install`.
 */
import { existsSync, mkdirSync, readdirSync, rmSync, symlinkSync } from "node:fs";
import { join } from "node:path";
import { writeError, writeOutput } from "./utils/cli-output";

const ROOT = process.cwd();
const BUN_STORE = join(ROOT, "node_modules", ".bun");
const TS6_RELATIVE = "../../typescript@6.0.3/node_modules/typescript";
const TS6_ABSOLUTE = join(BUN_STORE, "typescript@6.0.3", "node_modules", "typescript");

const PACKAGE_PREFIXES = [
  "@typescript-eslint+typescript-estree@",
  "@typescript-eslint+parser@",
  "@typescript-eslint+eslint-plugin@",
  "@typescript-eslint+type-utils@",
  "@typescript-eslint+project-service@",
  "@typescript-eslint+utils@",
  "typescript-eslint@",
  "ts-api-utils@",
  "eslint-plugin-vue@",
  "vue-eslint-parser@",
] as const;

const linkTypescript6 = (packageDir: string): void => {
  const nodeModulesDir = join(packageDir, "node_modules");
  const linkPath = join(nodeModulesDir, "typescript");
  mkdirSync(nodeModulesDir, { recursive: true });
  rmSync(linkPath, { force: true });
  symlinkSync(TS6_RELATIVE, linkPath);
};

if (!existsSync(TS6_ABSOLUTE)) {
  await writeError("typescript@6.0.3 not found in bun store; skip eslint TS6 peer link.");
  process.exit(0);
}

if (!existsSync(BUN_STORE)) {
  await writeError("bun store missing; skip eslint TS6 peer link.");
  process.exit(0);
}

let linked = 0;
for (const entry of readdirSync(BUN_STORE)) {
  if (!PACKAGE_PREFIXES.some((prefix) => entry.startsWith(prefix))) continue;
  const packageDir = join(BUN_STORE, entry);
  if (!existsSync(packageDir)) continue;
  linkTypescript6(packageDir);
  linked += 1;
}

// Workspace package node_modules may also host eslint-plugin-vue / parsers.
const workspacePackageDirs = [
  "packages/client",
  "packages/server",
  "packages/shared",
  "packages/scraper",
];
for (const workspacePackage of workspacePackageDirs) {
  for (const nestedName of [
    "eslint-plugin-vue",
    "vue-eslint-parser",
    "typescript-eslint",
    "ts-api-utils",
  ]) {
    const packageDir = join(ROOT, workspacePackage, "node_modules", nestedName);
    if (!existsSync(packageDir)) continue;
    // Workspace packages resolve typescript via the root bun store; use an absolute-relative link.
    const nodeModulesDir = join(packageDir, "node_modules");
    const linkPath = join(nodeModulesDir, "typescript");
    mkdirSync(nodeModulesDir, { recursive: true });
    rmSync(linkPath, { force: true });
    symlinkSync(TS6_ABSOLUTE, linkPath);
    linked += 1;
  }
}

await writeOutput(`Linked typescript@6.0.3 into ${String(linked)} eslint peer package(s).`);

/**
 * Marks upstream declaration files with `// @ts-nocheck` so TypeScript 7 can
 * keep `skipLibCheck: false` while Elysia/Drizzle ship `.d.ts` that fail libcheck.
 *
 * Idempotent. Invoked from the root `postinstall` script after `bun install`.
 */
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { writeError, writeOutput } from "./utils/cli-output";

const ROOT = process.cwd();
const PACKAGE_GLOBS = [
  "node_modules/elysia",
  "node_modules/.bun/elysia@*",
  "packages/*/node_modules/elysia",
  "node_modules/drizzle-orm",
  "node_modules/.bun/drizzle-orm@*",
  "packages/*/node_modules/drizzle-orm",
  "node_modules/@elysiajs/openapi",
  "node_modules/.bun/@elysiajs+openapi@*",
  "packages/*/node_modules/@elysiajs/openapi",
  "node_modules/happy-dom",
  "node_modules/.bun/happy-dom@*",
  "packages/*/node_modules/happy-dom",
] as const;

const NOCHECK = "// @ts-nocheck\n";
const TRAILING_SLASH_PATTERN = /\/$/;
const LEADING_SLASH_PATTERN = /^\//;

const expandGlobDir = (pattern: string): string[] => {
  if (!pattern.includes("*")) {
    return [join(ROOT, pattern)];
  }
  const [prefix, suffix] = pattern.split("*");
  const parent = join(ROOT, prefix.replace(TRAILING_SLASH_PATTERN, ""));
  if (!existsSync(parent)) {
    return [];
  }
  return readdirSync(parent)
    .filter((entry) => {
      const full = join(parent, entry);
      return existsSync(full) && statSync(full).isDirectory();
    })
    .map((entry) => join(parent, entry, suffix.replace(LEADING_SLASH_PATTERN, "")));
};

const collectDtsFiles = (dir: string, out: string[]): void => {
  if (!existsSync(dir)) {
    return;
  }
  const entries = readdirSync(dir);
  for (const entry of entries) {
    const full = join(dir, entry);
    if (!existsSync(full)) {
      continue;
    }
    if (statSync(full).isDirectory()) {
      collectDtsFiles(full, out);
      continue;
    }
    if (entry.endsWith(".d.ts")) {
      out.push(full);
    }
  }
};

const hasNocheck = (content: string): boolean =>
  content.startsWith("// @ts-nocheck") || content.trimStart().startsWith("// @ts-nocheck");

const main = async (): Promise<void> => {
  const dirs = PACKAGE_GLOBS.flatMap((pattern) => expandGlobDir(pattern));
  const uniqueDirs = Array.from(new Set(dirs));
  let patched = 0;
  for (const dir of uniqueDirs) {
    const files: string[] = [];
    collectDtsFiles(dir, files);
    for (const filePath of files) {
      const content = readFileSync(filePath, "utf8");
      if (hasNocheck(content)) {
        continue;
      }
      writeFileSync(filePath, `${NOCHECK}${content}`);
      patched += 1;
    }
  }
  await writeOutput(`Upstream .d.ts nocheck patch applied (${patched} files).`);
};

if (import.meta.main) {
  await main().then(
    () => undefined,
    async (error: unknown) => {
      await writeError(
        `Upstream .d.ts nocheck patch failed: ${error instanceof Error ? error.message : String(error)}`,
      );
      process.exit(1);
    },
  );
}

