import { toErrorMessage as sharedToErrorMessage } from "../../packages/shared/src/utils/error-helpers";

/**
 * Tagged result for operations that may fail.
 */
export type OperationResult<T> = { ok: true; value: T } | { ok: false; error: Error };

/**
 * Narrows an arbitrary runtime value to a stable Error instance.
 * Kept generic so callers may pass values typed as `any` (e.g. Promise
 * rejection reasons) without widening the public contract to the unsafe top
 * type.
 */
export const asError = <T>(value: T): Error => {
  if (value instanceof Error) {
    return value;
  }
  if (typeof value === "string" && value.trim().length > 0) {
    return new Error(value);
  }
  return new Error(String(value));
};

/**
 * Captures a sync or async operation result without using try/catch syntax.
 */
export const captureResult = <T>(operation: () => Promise<T> | T): Promise<OperationResult<T>> =>
  Promise.resolve()
    .then(operation)
    .then(
      (value) => ({ ok: true, value }),
      (error) => ({ ok: false, error: asError(error) }),
    );

/**
 * Runs an operation and always executes the cleanup callback afterward.
 */
export const withCleanup = <T>(
  operation: () => Promise<T> | T,
  cleanup: () => Promise<void> | void,
): Promise<T> =>
  Promise.resolve()
    .then(operation)
    .then(
      (value) => Promise.resolve(cleanup()).then(() => value),
      (error) =>
        Promise.resolve(cleanup()).then(() => {
          throw asError(error);
        }),
    );

/**
 * Converts a rejection value into a human-readable message.
 * Canonical implementation lives in shared error-helpers; this alias keeps
 * the script-side import surface stable. Callers that relied on the former
 * local default pass "Unexpected error." explicitly.
 */
export const toErrorMessage = sharedToErrorMessage;

export type PollUntilOptions<T> = {
  /** Probe returning the resolved value, or null/undefined to keep polling. */
  readonly probe: () => Promise<T | null | undefined>;
  /** Delay between probes. */
  readonly intervalMs: number;
  /** Maximum total wait budget. */
  readonly timeoutMs: number;
  /** Sleep implementation (page-bound settle for browser proofs, Bun.sleep elsewhere). */
  readonly sleep: (milliseconds: number) => Promise<unknown>;
};

/**
 * Polls a probe until it resolves a value or the timeout elapses.
 * Recursive by construction: live browser capture requires strictly sequential
 * probing, so recursion is the honest no-await-in-loop shape.
 */
export const pollUntil = async <T>(options: PollUntilOptions<T>): Promise<T | null> => {
  const deadline = Date.now() + options.timeoutMs;
  const attempt = async (): Promise<T | null> => {
    const hit = await options.probe();
    if (hit !== null && hit !== undefined) {
      return hit;
    }
    if (Date.now() >= deadline) {
      return null;
    }
    await options.sleep(options.intervalMs);
    return attempt();
  };
  return attempt();
};

import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";

const REPO_ROOT = resolve(import.meta.dir, "../..");

/**
 * Build the command prefix used to invoke Biome. Uses `bunx` (i.e. `bun x`)
 * so that Bun resolves the locally-installed @biomejs/biome binary itself,
 * which works consistently across Windows, macOS and Linux regardless of
 * the extension or launcher format that `bun install` wrote into node_modules/.bin/.
 */
const BIOME_COMMAND_PREFIX = [process.execPath, "x", "biome"];
const TEXT_ENCODER = new TextEncoder();

const readStreamText = async (
  stream: number | ReadableStream<Uint8Array> | undefined,
): Promise<string> => {
  if (!(stream instanceof ReadableStream)) {
    return "";
  }

  return (await new Response(stream).text()).trim();
};

const formatTextWithBiomeFromStdin = async (
  filePathHint: string,
  text: string,
): Promise<string> => {
  const proc = Bun.spawn([...BIOME_COMMAND_PREFIX, "format", `--stdin-file-path=${filePathHint}`], {
    cwd: REPO_ROOT,
    env: process.env,
    stdin: TEXT_ENCODER.encode(text),
    stdout: "pipe",
    stderr: "pipe",
  });
  const [exitCode, stdout, stderr] = await Promise.all([
    proc.exited,
    readStreamText(proc.stdout),
    readStreamText(proc.stderr),
  ]);

  if (exitCode !== 0) {
    const output = [stdout, stderr].filter((value) => value.length > 0).join("\n");
    throw new Error(
      output.length > 0
        ? `Biome failed to format stdin for ${filePathHint}.\n${output}`
        : `Biome failed to format stdin for ${filePathHint}.`,
    );
  }

  return `${stdout}\n`;
};

/**
 * Formats one or more files with the repository-local Biome binary.
 *
 * @param filePaths Absolute or repo-relative file paths to format in place.
 */

/**
 * Serializes JSON with a trailing newline, then normalizes the file with Biome.
 *
 * @param filePath Absolute or repo-relative target path.
 * @param value JSON-serializable value to persist.
 */
export const writeFormattedJsonFile = async (filePath: string, value: unknown): Promise<void> => {
  const absolutePath = resolve(filePath);
  await mkdir(dirname(absolutePath), { recursive: true });
  await writeFile(absolutePath, await formatJsonWithBiome(filePath, value), "utf8");
};

/**
 * Returns the Biome-formatted JSON text for a value without mutating repository files.
 *
 * @param filePathHint Representative path used for Biome parser inference.
 * @param value JSON-serializable value to format.
 */
export const formatJsonWithBiome = async (
  filePathHint: string,
  value: unknown,
): Promise<string> => {
  return formatTextWithBiomeFromStdin(filePathHint, `${JSON.stringify(value, null, 2)}\n`);
};

/**
 * Biome ratchet additions for industry-best-practice UI/UX/wiring rules.
 *
 * Extracted from biome-softener-ratchet.ts to stay under the HB023 400-line
 * file ceiling. These predicates enforce the rules added in the 2026-07-21
 * lint-hardening pass: noMagicNumbers, noShoutyConstants, noCommonJs,
 * useThrowOnlyError, useExplicitLengthCheck, noDoneCallback,
 * noEmptyBlockStatements, noTemplateCurlyInString.
 *
 * noUndeclaredClasses and noUnusedClasses are intentionally NOT enforced:
 * they produce false positives on Tailwind/daisyUI utility classes (the rule
 * cannot resolve classes generated by the Tailwind compiler). Enforcing them
 * would require 268+ suppressions or a custom class allowlist that drifts from
 * the Tailwind config. The canonical fix is to wait for biome to support
 * Tailwind class resolution (tracked in
 * scripts/docs/biome-tailwind-incompatibility.md).
 */
import type { SoftenerJsonValue } from "./biome-softener-ratchet";
import { isSoftenerRecord, requireRuleError } from "./biome-softener-ratchet";
import type { ValidationViolation } from "./validation-helpers";

export const validateStyleAdditionsRatchet = (
  style: { [key: string]: SoftenerJsonValue },
  violations: ValidationViolation[],
  biomePath: string,
): void => {
  for (const ruleName of [
    "noShoutyConstants",
    "noCommonJs",
    "useThrowOnlyError",
    "useExplicitLengthCheck",
    "noDoneCallback",
  ] as const) {
    requireRuleError(style, ruleName, "linter.rules.style", violations, biomePath);
  }
  const magicNumbers = style.noMagicNumbers;
  const magicNumbersOk =
    magicNumbers === "error" || (isSoftenerRecord(magicNumbers) && magicNumbers.level === "error");
  if (!magicNumbersOk) {
    violations.push({
      filePath: biomePath,
      line: 1,
      message:
        'linter.rules.style.noMagicNumbers must be "error" (extract magic numbers to named constants).',
    });
  }
};

export const validateSuspiciousAdditionsRatchet = (
  suspicious: { [key: string]: SoftenerJsonValue },
  violations: ValidationViolation[],
  biomePath: string,
): void => {
  for (const ruleName of ["noEmptyBlockStatements", "noTemplateCurlyInString"] as const) {
    requireRuleError(suspicious, ruleName, "linter.rules.suspicious", violations, biomePath);
  }
};

/**
 * Biome UI/complexity ratchet predicates — extracted so softener gate stays ≤400 lines.
 */
import {
  validateStyleAdditionsRatchet,
  validateSuspiciousAdditionsRatchet,
} from "./biome-softener-ratchet-v2";
import type { ValidationViolation } from "./validation-helpers";

export type SoftenerJsonValue =
  | null
  | boolean
  | number
  | string
  | SoftenerJsonValue[]
  | { [key: string]: SoftenerJsonValue };
export const isSoftenerRecord = (
  value: SoftenerJsonValue,
): value is { [key: string]: SoftenerJsonValue } =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const MAX_LINES_PER_FUNCTION = 60;

export const requireRuleError = (
  group: { [key: string]: SoftenerJsonValue },
  ruleName: string,
  path: string,
  violations: ValidationViolation[],
  biomePath: string,
): void => {
  const value = group[ruleName];
  const isStringError = value === "error";
  const isObjectError = isSoftenerRecord(value) && value.level === "error";
  if (!isStringError && !isObjectError) {
    violations.push({
      filePath: biomePath,
      line: 1,
      message: `${path}.${ruleName} must be "error" or { level: "error" } (info/off/warn/delete is softener).`,
    });
  }
};

export const validateComplexityRatchet = (
  complexity: { [key: string]: SoftenerJsonValue },
  violations: ValidationViolation[],
  biomePath: string,
): void => {
  if (complexity.noVoid !== "error") {
    violations.push({
      filePath: biomePath,
      line: 1,
      message: 'linter.rules.complexity.noVoid must be "error".',
    });
  }
  if (complexity.noExcessiveCognitiveComplexity !== "error") {
    violations.push({
      filePath: biomePath,
      line: 1,
      message:
        'linter.rules.complexity.noExcessiveCognitiveComplexity must be "error" (info/off/warn/delete is softener).',
    });
  }
  requireRuleError(
    complexity,
    "noUselessContinue",
    "linter.rules.complexity",
    violations,
    biomePath,
  );
  requireRuleError(
    complexity,
    "noUselessStringConcat",
    "linter.rules.complexity",
    violations,
    biomePath,
  );
  requireRuleError(
    complexity,
    "noImplicitCoercions",
    "linter.rules.complexity",
    violations,
    biomePath,
  );
  const implicitCoercions = complexity.noImplicitCoercions;
  const implicitCoercionsOk =
    isSoftenerRecord(implicitCoercions) &&
    implicitCoercions.level === "error" &&
    isSoftenerRecord(implicitCoercions.options) &&
    implicitCoercions.options.allowDoubleNegation === false;
  if (!implicitCoercionsOk) {
    violations.push({
      filePath: biomePath,
      line: 1,
      message:
        "linter.rules.complexity.noImplicitCoercions must be error with allowDoubleNegation=false (no implicit type coercion shorthand).",
    });
  }
  const linesPerFn = complexity.noExcessiveLinesPerFunction;
  const linesOk =
    isSoftenerRecord(linesPerFn) &&
    linesPerFn.level === "error" &&
    isSoftenerRecord(linesPerFn.options) &&
    linesPerFn.options.maxLines === MAX_LINES_PER_FUNCTION;
  if (!linesOk) {
    violations.push({
      filePath: biomePath,
      line: 1,
      message: `linter.rules.complexity.noExcessiveLinesPerFunction must be error with maxLines=${String(MAX_LINES_PER_FUNCTION)} (info/off/warn/delete/ceiling-raise is softener).`,
    });
  }
};

