  const performance = rules.performance;
  if (!isSoftenerRecord(performance) || performance.noBarrelFile !== "error") {
    push(
      'linter.rules.performance.noBarrelFile must be "error" (info/off/warn/delete is softener).',
    );
  }
  validateRecordOrPush(
    rules.nursery,
    push,
    "linter.rules.nursery must opt into floating-promise / vue / drizzle / playwright / UI gates.",
    (nursery) => validateNurseryUiRatchet(nursery, violations, biomePath),
  );
};

export const MAX_LINES_PER_FUNCTION_CEILING = MAX_LINES_PER_FUNCTION;

/**
 * Stream writers that resolve only once the payload is flushed.
 *
 * `process.stdout` / `process.stderr` buffer when the write exceeds the pipe
 * capacity, and `process.exit()` discards whatever is still buffered. Callers
 * that report a long violation list and then exit non-zero were losing the tail
 * of their own output, so every writer awaits `drain` before resolving.
 */
const writeStream = (stream: NodeJS.WriteStream, value: string): Promise<void> =>
  new Promise((resolve) => {
    if (stream.write(`${value}\n`)) {
      resolve();
      return;
    }
    stream.once("drain", resolve);
  });

/**
 * Emit a standard output message.
 */
export const writeOutput = (value: string): Promise<void> => writeStream(process.stdout, value);

/**
 * Emit a standard error message.
 */
export const writeError = (value: string): Promise<void> => writeStream(process.stderr, value);

export type CommandCaptureLike = {
  readonly exitCode: number;
  readonly stdout: string;
  readonly stderr: string;
  readonly timedOut: boolean;
};

export const resolveCommandDetails = (
  commandResult: CommandCaptureLike,
  labels: { readonly success: string; readonly timeout: string },
): string => {
  if (commandResult.exitCode === 0) {
    return labels.success;
  }
  if (commandResult.timedOut) {
    return labels.timeout;
  }
  return commandResult.stderr || commandResult.stdout || `exitCode=${commandResult.exitCode}`;
};

/**
 * Symbol-level reference counting for the dead-export gate.
 *
 * Split out of `validate-no-dead-exports.ts` to keep both modules under the
 * monolith ceiling. The counting rules live here; the violation reporting and
 * module-level resolution stay in the validator.
 */

/**
 * Removes comments while leaving string and template-literal bodies intact.
 *
 * Comments routinely spell out `export { … } from` in prose, and scanning them would
 * mine documentation for export names. String bodies must survive, though: Vue
 * templates bind constants from inside quoted attributes (`:class="SHELL_CLASS"`) and
 * template literals hold live references in `${…}`, so blanking quoted spans erases
 * real usage and reports live symbols as dead.
 *
 * That combination rules out regex replacement. A pattern cannot tell a comment
 * opener from the same characters inside a string, and this repo has one:
 * `` `${API_ENDPOINT_PREFIX}/**` `` in `packages/client/nuxt.config.ts`. A
 * non-greedy block-comment regex treated it as an opener and ran to the next real
 * close delimiter far below, deleting ~7KB of code — every use site in between — and
 * reporting nine live constants as dead exports.
 *
 * So walk the source once, tracking whether we are inside a quote, a template
 * literal, a line comment or a block comment, and drop only real comment spans.
 * (A `/*` inside a regex literal is still treated as a comment opener; regex
 * literals cannot be told from division without a full parser, and no such literal
 * exists here.)
 */
const QUOTE_CHARACTERS = new Set(['"', "'", "`"]);

/** Copies a quoted span verbatim; returns the index just past its closing quote. */
const copyQuotedSpan = (content: string, start: number, output: string[]): number => {
  const quote = content[start] ?? "";
  output.push(quote);
  let index = start + 1;

  while (index < content.length) {
    const character = content[index] ?? "";
    output.push(character);
    if (character === "\\") {
      output.push(content[index + 1] ?? "");
      index += 2;
      continue;
    }
    index += 1;
    if (character === quote) {
      return index;
    }
  }
  return index;
};

/** Returns the index just past the comment that starts at `start`, or the content end. */
const skipComment = (content: string, start: number): number => {
  if (content[start + 1] === "/") {
    const lineEnd = content.indexOf("\n", start);
    return lineEnd === -1 ? content.length : lineEnd;
  }
  const blockEnd = content.indexOf("*/", start + 2);
  return blockEnd === -1 ? content.length : blockEnd + 2;
};

const startsComment = (content: string, index: number): boolean =>
  content[index] === "/" && (content[index + 1] === "/" || content[index + 1] === "*");

export const stripComments = (content: string): string => {
  const output: string[] = [];
  let index = 0;

  while (index < content.length) {
    const character = content[index] ?? "";
    if (QUOTE_CHARACTERS.has(character)) {
      index = copyQuotedSpan(content, index, output);
      continue;
    }
    if (startsComment(content, index)) {
      output.push(" ");
      index = skipComment(content, index);
      continue;
    }
    output.push(character);
    index += 1;
  }

  return output.join("");
};

const IMPORT_STATEMENT_PATTERN = /\bimport\b[^;'"]*?\bfrom\b\s*['"`][^'"`]*['"`]/gu;
const EXPORT_FROM_STATEMENT_PATTERN = /\bexport\b[^;'"]*?\bfrom\b\s*['"`][^'"`]*['"`]/gu;
const IDENTIFIER_PATTERN = /[A-Za-z_$][\w$]*/gu;
/** `originalName as localAlias` inside an import or export-from clause. */
const RENAMED_BINDING_PATTERN = /\b([A-Za-z_$][\w$]*)\s+as\s+([A-Za-z_$][\w$]*)/gu;

/**
 * Module-specifier statements are stripped before reference counting so that an
 * import which names a symbol but never uses it cannot keep that export alive.
 */
export const stripModuleSpecifierStatements = (content: string): string =>
  stripComments(content)
    .replace(IMPORT_STATEMENT_PATTERN, " ")
    .replace(EXPORT_FROM_STATEMENT_PATTERN, " ");

/**
 * Names consumed through a rename (`import { a as b }`) never appear in the
 * body under their original spelling, so the stripped text alone would report
 * them dead. Each rename whose local alias is actually used counts as one
 * reference to the original name; an unused aliased import stays dead and is
 * separately caught by the unused-import lint.
 */
const collectRenamedBindingUses = (content: string): string[] => {
  const withoutComments = stripComments(content);
  const body = stripModuleSpecifierStatements(content);
  const statements = [
    ...(withoutComments.match(IMPORT_STATEMENT_PATTERN) ?? []),
    ...(withoutComments.match(EXPORT_FROM_STATEMENT_PATTERN) ?? []),
  ];

  const uses: string[] = [];
  for (const statement of statements) {
    RENAMED_BINDING_PATTERN.lastIndex = 0;
    for (const match of statement.matchAll(RENAMED_BINDING_PATTERN)) {
      const [, originalName, localAlias] = match;
      if (originalName === undefined || localAlias === undefined) {
        continue;
      }
      if (new RegExp(`\\b${localAlias}\\b`, "u").test(body)) {
        uses.push(originalName);
      }
    }
  }
  return uses;
};

/**
 * Count how often every identifier appears across all sources with import and
 * export-from clauses stripped. A declaration contributes exactly one
 * occurrence, so a symbol whose total count is 1 is referenced by nothing —
 * not by another module, not by a test, not even by its own file. An unused
 * import can no longer keep such a symbol alive, because the clause naming it
 * is removed before counting.
 */
export const collectIdentifierOccurrences = (
  sources: Array<{ filePath: string; content: string }>,
): Map<string, number> => {
  const occurrences = new Map<string, number>();
  for (const { content } of sources) {
    const body = stripModuleSpecifierStatements(content);
    IDENTIFIER_PATTERN.lastIndex = 0;
    for (const match of body.matchAll(IDENTIFIER_PATTERN)) {
      const identifier = match[0];
      occurrences.set(identifier, (occurrences.get(identifier) ?? 0) + 1);
    }
    for (const renamed of collectRenamedBindingUses(content)) {
      occurrences.set(renamed, (occurrences.get(renamed) ?? 0) + 1);
    }
  }
  return occurrences;
};

import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import {
  DESKTOP_RELEASE_METADATA_DIR,
  DESKTOP_RELEASE_PROVENANCE_FILENAME,
  DESKTOP_RELEASE_TARGETS,
} from "../../packages/shared/src/constants/scripts";

type DesktopReleaseTarget = (typeof DESKTOP_RELEASE_TARGETS)[number];

const DESKTOP_RELEASE_TARGET_SET = new Set<string>(DESKTOP_RELEASE_TARGETS);
const STAGE_ONLY_BUILD_COMMAND_PREFIX = "stage-only ";

type NativeDesktopReleaseProvenance = {
  readonly schemaVersion?: unknown;
  readonly target?: unknown;
  readonly strategy?: unknown;
  readonly tauriCli?: unknown;
  readonly hostPlatform?: unknown;
  readonly hostArch?: unknown;
  readonly tauriTarget?: unknown;
  readonly artifactNames?: unknown;
  readonly buildCommands?: unknown;
};

const isArtifactNameList = (value: unknown): value is readonly string[] =>
  Array.isArray(value) &&
  value.length > 0 &&
  value.every((entry) => typeof entry === "string" && entry.length > 0);

const isBuildCommandList = (value: unknown): value is readonly string[] =>
  Array.isArray(value) &&
  value.length > 0 &&
  value.every((entry) => typeof entry === "string" && entry.length > 0);

const isNativeBuildCommandList = (value: unknown): value is readonly string[] =>
  isBuildCommandList(value) &&
  value.every((entry) => !entry.startsWith(STAGE_ONLY_BUILD_COMMAND_PREFIX));

/**
 * Returns true when a string matches a canonical desktop release target bucket.
 */
export const isDesktopReleaseTarget = (value: string): value is DesktopReleaseTarget =>
  DESKTOP_RELEASE_TARGET_SET.has(value);

/**
 * Returns true when a provenance payload is structurally valid for release assembly.
 */
export const isDesktopReleaseProvenance = (value: NativeDesktopReleaseProvenance): boolean =>
  value.schemaVersion === 1 &&
  typeof value.target === "string" &&
  isDesktopReleaseTarget(value.target) &&
  value.strategy === "matching-host-native" &&
  value.tauriCli === "repo-local-bun" &&
  typeof value.hostPlatform === "string" &&
  value.hostPlatform.length > 0 &&
  typeof value.hostArch === "string" &&
  value.hostArch.length > 0 &&
  typeof value.tauriTarget === "string" &&
  value.tauriTarget.length > 0 &&
  isArtifactNameList(value.artifactNames) &&
  isBuildCommandList(value.buildCommands);

/**
 * Returns true when a provenance payload represents a fresh native build instead of staged carry-forward artifacts.
 */
export const hasNativeDesktopReleaseProvenance = (value: NativeDesktopReleaseProvenance): boolean =>
  isDesktopReleaseProvenance(value) && isNativeBuildCommandList(value.buildCommands);

/**
 * Parses an explicit `--targets` CLI argument into canonical release targets.
 */
export const parseDesktopReleaseRefreshTargets = (
  argv: readonly string[],
): readonly DesktopReleaseTarget[] | null => {
  const targetsIndex = argv.indexOf("--targets");
  if (targetsIndex === -1) {
    return null;
  }

  const rawTargets = argv[targetsIndex + 1] ?? "";
  const selectedTargets = rawTargets
    .split(",")
    .map((target) => target.trim())
    .filter(isDesktopReleaseTarget);

  if (selectedTargets.length === 0) {
    throw new Error(`No supported desktop targets were supplied via --targets (${rawTargets}).`);
  }

  return selectedTargets;
};

/**
 * Discovers staged release targets that contain both a target root and an assembly-safe provenance manifest.
 */
export const discoverStagedDesktopReleaseTargets = async (
  sourceRoot: string,
  pathExists: (absolutePath: string) => Promise<boolean>,
): Promise<readonly DesktopReleaseTarget[]> => {
  const stagedTargets = await Promise.all(
    DESKTOP_RELEASE_TARGETS.map(async (target) => {
      const targetRoot = join(sourceRoot, target);
      const provenancePath = join(
        targetRoot,
        DESKTOP_RELEASE_METADATA_DIR,
        DESKTOP_RELEASE_PROVENANCE_FILENAME,
      );
      if (!((await pathExists(targetRoot)) && (await pathExists(provenancePath)))) {
        return null;
      }

      const provenance = JSON.parse(
        await Bun.file(provenancePath).text(),
      ) as NativeDesktopReleaseProvenance;
      return isDesktopReleaseProvenance(provenance) ? target : null;
    }),
  );

  return stagedTargets.filter((target): target is DesktopReleaseTarget => target !== null);
};

/**
 * Writes a minimal staged provenance manifest for a target in a fixture directory.
 */
export const stageDesktopReleaseProvenanceFixture = async (
  sourceRoot: string,
  target: DesktopReleaseTarget,
  buildCommands: readonly string[] = ["bun tauri build --bundles default"],
): Promise<void> => {
  const metadataRoot = join(sourceRoot, target, DESKTOP_RELEASE_METADATA_DIR);
  await mkdir(metadataRoot, { recursive: true });
  await writeFile(
    join(metadataRoot, DESKTOP_RELEASE_PROVENANCE_FILENAME),
    JSON.stringify({
      schemaVersion: 1,
      target,
      strategy: "matching-host-native",
      tauriCli: "repo-local-bun",
      hostPlatform: "darwin",
      hostArch: "arm64",
      tauriTarget: "fixture-target",
      artifactNames: ["fixture.bin"],
      buildCommands,
    }),
  );
};

import { DESKTOP_RELEASE_TARGETS } from "../../packages/shared/src/constants/scripts";

export type DesktopReleaseVerifyTarget = (typeof DESKTOP_RELEASE_TARGETS)[number];

/**
 * Returns canonical desktop release targets that appear in the assembled provenance map,
 * in stable DESKTOP_RELEASE_TARGETS order.
 */
export const orderTargetsPresentInProvenance = (
  provenanceTargetKeys: ReadonlySet<string>,
): readonly DesktopReleaseVerifyTarget[] =>
  DESKTOP_RELEASE_TARGETS.filter((target) => provenanceTargetKeys.has(target));

import { realpath } from "node:fs/promises";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { captureResult, toErrorMessage } from "./async-control";

type PackageDependencyMap = Record<string, string>;

type PackageManifest = {
  dependencies: PackageDependencyMap;
  optionalDependencies: PackageDependencyMap;
};

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isDependencyMap = (value: unknown): value is PackageDependencyMap =>
  isRecord(value) && Object.values(value).every((entry) => typeof entry === "string");

const readPackageManifest = async (packageRoot: string): Promise<PackageManifest> => {
  const rawManifest: unknown = JSON.parse(await Bun.file(join(packageRoot, "package.json")).text());
  if (!isRecord(rawManifest)) {
    throw new Error(`Expected package manifest object at ${join(packageRoot, "package.json")}`);
  }

  return {
    dependencies: isDependencyMap(rawManifest.dependencies) ? rawManifest.dependencies : {},
    optionalDependencies: isDependencyMap(rawManifest.optionalDependencies)
      ? rawManifest.optionalDependencies
      : {},
  };
};

const resolvePackageManifestPath = async (
  packageName: string,
  fromPackageRoot: string,
): Promise<string> => {
  const packageResolver = createRequire(join(fromPackageRoot, "package.json"));
  const manifestPathResult = await captureResult(() =>
    realpath(packageResolver.resolve(`${packageName}/package.json`)),
  );
  if (manifestPathResult.ok) {
    return manifestPathResult.value;
  }

  throw new Error(
    `Unable to resolve packaged scraper dependency "${packageName}" from ${fromPackageRoot}: ${toErrorMessage(
      manifestPathResult.error,
      "Unexpected error.",
    )}`,
    { cause: manifestPathResult.error },
  );
};

const sortDependencyNames = (dependencyMap: PackageDependencyMap): string[] =>
  Object.keys(dependencyMap).sort((left, right) => left.localeCompare(right));

const visitDependencyNamesSequentially = async (
  dependencyNames: readonly string[],
  visitor: (dependencyName: string) => Promise<void>,
  index: number = 0,
): Promise<void> => {
  const dependencyName = dependencyNames[index];
  if (!dependencyName) {
    return;
  }

  await visitor(dependencyName);
  await visitDependencyNamesSequentially(dependencyNames, visitor, index + 1);
};

const visitOptionalDependencies = async (
  packageRoot: string,
  optionalDependencies: PackageDependencyMap,
  visitedPackages: Map<string, string>,
): Promise<void> => {
  await visitDependencyNamesSequentially(
    sortDependencyNames(optionalDependencies),
    async (dependencyName) => {
      // Optional dependencies are allowed to be missing from the host install tree.
      // Bun may surface that absence as MODULE_NOT_FOUND or as a generic resolver error.
      const sourceRootResult = await captureResult(() =>
        resolvePackageSourceRoot(dependencyName, packageRoot),
      );
      if (!sourceRootResult.ok) {
        return;
      }

      await visitRuntimeDependencyTree(dependencyName, sourceRootResult.value, visitedPackages);
    },
  );
};

const visitRuntimeDependencyTree = async (
  packageName: string,
  packageRoot: string,
  visitedPackages: Map<string, string>,
): Promise<void> => {
  const existingRoot = visitedPackages.get(packageName);
  if (existingRoot) {
    if (existingRoot !== packageRoot) {
      throw new Error(
        `Packaged scraper runtime dependency "${packageName}" resolved to multiple package roots: ${existingRoot} and ${packageRoot}`,
      );
    }
    return;
  }

  visitedPackages.set(packageName, packageRoot);
  const manifest = await readPackageManifest(packageRoot);

  await visitDependencyNamesSequentially(
    sortDependencyNames(manifest.dependencies),
    async (dependencyName) => {
      const dependencyRoot = await resolvePackageSourceRoot(dependencyName, packageRoot);
      await visitRuntimeDependencyTree(dependencyName, dependencyRoot, visitedPackages);
    },
  );

  await visitOptionalDependencies(packageRoot, manifest.optionalDependencies, visitedPackages);
};

/**
 * Files and directories that make up the scraper package source contract inside the desktop runtime.
 */
export const SCRAPER_RUNTIME_STAGE_SOURCE_PATHS = ["package.json", "src", "tsconfig.json"] as const;

/**
 * Resolve the real package root for a Bun-installed dependency from the perspective of another package.
 */
export const resolvePackageSourceRoot = async (
  packageName: string,
  fromPackageRoot: string,
): Promise<string> => dirname(await resolvePackageManifestPath(packageName, fromPackageRoot));

/**
 * Collect the flattened production dependency closure required by the packaged scraper runtime.
 */
export const collectRuntimeDependencySourceRoots = async (
  packageRoot: string,
): Promise<ReadonlyMap<string, string>> => {
  const visitedPackages = new Map<string, string>();
  const manifest = await readPackageManifest(packageRoot);

  await visitDependencyNamesSequentially(
    sortDependencyNames(manifest.dependencies),
    async (dependencyName) => {
      const dependencyRoot = await resolvePackageSourceRoot(dependencyName, packageRoot);
      await visitRuntimeDependencyTree(dependencyName, dependencyRoot, visitedPackages);
    },
  );

  await visitOptionalDependencies(packageRoot, manifest.optionalDependencies, visitedPackages);
  return visitedPackages;
};

/**
 * Shared live local-AI probe (Ollama OpenAI-compatible /v1).
 * Fail-closed: empty, missing model, or mock markers → throw.
 */
import {
  COUNT_ONE_TWENTY,
  COUNT_THIRTY_SIX,
  COUNT_THREE,
  COUNT_TWO_FORTY,
  MS_TEN_SECONDS,
  MS_TWO_MINUTES,
} from "../constants/numeric-literals";
import { writeOutput } from "./cli-output";

const TRAILING_SLASH_PATTERN = /\/$/u;

const BANNED_AI_MARKERS: readonly RegExp[] = [
  /lorem ipsum/iu,
  /mock completion/iu,
  /deterministic stub/iu,
  /TBD:\s*generate/iu,
];

export type LiveAiProbeResult = {
  readonly endpoint: string;
  readonly modelId: string;
  readonly nonce: string;
  readonly sample: string;
};

export const resolveLocalAiEndpoint = (): string =>
  (
    process.env.LOCAL_MODEL_ENDPOINT ??
    process.env.PRODUCT_DEMO_LOCAL_ENDPOINT ??
    "http://127.0.0.1:11434/v1"
  ).replace(TRAILING_SLASH_PATTERN, "");

/**
 * Probes /v1/models + /v1/chat/completions with a nonce the model must echo.
 */
export const assertLiveInference = async (
  options: {
    readonly endpoint?: string;
    readonly modelId?: string;
    readonly timeoutMs?: number;
  } = {},
): Promise<LiveAiProbeResult> => {
  const endpoint = (options.endpoint ?? resolveLocalAiEndpoint()).replace(
    TRAILING_SLASH_PATTERN,
    "",
  );
  const timeoutMs = options.timeoutMs ?? MS_TWO_MINUTES;
  const modelsUrl = `${endpoint}/models`;
  const modelsResponse = await fetch(modelsUrl, { signal: AbortSignal.timeout(MS_TEN_SECONDS) });
  if (!modelsResponse.ok) {
    throw new Error(`Live AI probe failed: GET ${modelsUrl} → ${String(modelsResponse.status)}`);
  }
  const modelsJson = (await modelsResponse.json()) as {
    data?: Array<{ id?: string }>;
  };
  const modelId =
    options.modelId?.trim() ||
    process.env.LOCAL_MODEL_NAME?.trim() ||
    process.env.PRODUCT_DEMO_MODEL?.trim() ||
    modelsJson.data?.find((entry) => typeof entry.id === "string" && entry.id.length > 0)?.id;
  if (!modelId) {
    throw new Error(`Live AI probe failed: no model id at ${modelsUrl}`);
  }

  const nonce = `BAO_LIVE_${Date.now().toString(COUNT_THIRTY_SIX)}`;
  const chatResponse = await fetch(`${endpoint}/chat/completions`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    signal: AbortSignal.timeout(timeoutMs),
    body: JSON.stringify({
      model: modelId,
      temperature: 0,
      max_tokens: 48,
      messages: [
        {
          role: "system",
          content: "You are a literal echo bot. Output only the user message with no extra words.",
        },
        {
          role: "user",
          content: nonce,
        },
      ],
    }),
  });
  if (!chatResponse.ok) {
    const body = await chatResponse.text();
    throw new Error(
      `Live AI probe failed: chat/completions → ${String(chatResponse.status)} ${body.slice(0, COUNT_TWO_FORTY)}`,
    );
  }
  const chatJson = (await chatResponse.json()) as {
    choices?: Array<{ message?: { content?: string } }>;
  };
  const sample = chatJson.choices?.[0]?.message?.content?.trim() ?? "";
  if (sample.length < COUNT_THREE) {
    throw new Error("Live AI probe failed: empty completion (refusing mock/empty provider).");
  }
  if (BANNED_AI_MARKERS.some((pattern) => pattern.test(sample))) {
    throw new Error("Live AI probe failed: response looks like a mock/deterministic stub.");
  }
  if (!sample.includes(nonce)) {
    throw new Error(
      `Live AI probe failed: nonce missing from sample (got ${sample.slice(0, COUNT_ONE_TWENTY)}).`,
    );
  }
  await writeOutput(
    `live AI ok endpoint=${endpoint} model=${modelId} sample=${sample.slice(0, COUNT_ONE_TWENTY)}`,
  );
  return { endpoint, modelId, nonce, sample };
};

/**
 * Shared PDF download assertions — magic header + SSOT RGB fill operators.
 */
import {
  extractPdfContentStreams,
  pdfRgbFillOperator,
} from "../../packages/shared/src/utils/pdf-streams";
import { COUNT_FIVE } from "../constants/numeric-literals";
import { writeError, writeOutput } from "./cli-output";

export const PDF_MAGIC = "%PDF-";
export const PDF_MIN_BYTES = 1_000;

export type PdfAssertResult = {
  readonly ok: boolean;
  readonly path: string;
  readonly bytes: number;
  readonly header: string;
};

/**
 * Fail-closed: inflated PDF streams must include the exact SSOT fill operator.
 */
export const assertPdfContainsRgbFill = async (
  path: string,
  color: { readonly r: number; readonly g: number; readonly b: number },
  label: string,
): Promise<boolean> => {
  const file = Bun.file(path);
  if (!(await file.exists())) {
    await writeError(`PDF missing for palette assert (${label}): ${path}`);
    return false;
  }
  const buffer = Buffer.from(await file.arrayBuffer());
  const needle = pdfRgbFillOperator(color);
  const ok = extractPdfContentStreams(buffer).includes(needle);
  await writeOutput(`PDF palette ${label} path=${path} needle=${needle} ok=${String(ok)}`);
  if (!ok) {
    await writeError(`PDF missing expected palette fill (${label}): ${needle}`);
  }
  return ok;
};

/**
 * Validates a downloaded file is a real PDF payload.
 */
export const assertRealPdfFile = async (path: string): Promise<PdfAssertResult> => {
  const file = Bun.file(path);
  if (!(await file.exists())) {
    await writeError(`PDF missing: ${path}`);
    return { ok: false, path, bytes: 0, header: "" };
  }
  const buffer = Buffer.from(await file.arrayBuffer());
  const header = buffer.subarray(0, COUNT_FIVE).toString("utf8");
  const bytes = buffer.byteLength;
  await writeOutput(`PDF path=${path} bytes=${String(bytes)} header=${header}`);
  const ok = header === PDF_MAGIC && bytes >= PDF_MIN_BYTES;
  if (!ok) {
    await writeError("Downloaded file is not a real PDF");
  }
  return { ok, path, bytes, header };
};

/**
 * Canonical Playwright probe: scans chat bubbles for a nonce token.
 * pollUntil-ready — returns true on hit, null to keep polling.
 */
import type { Page } from "playwright";

export const createChatNonceProbe =
  (page: Page, bubbleLocator: string, nonce: string) =>
  async (): Promise<true | null> => {
    const bubbles = page.locator(bubbleLocator);
    const count = await bubbles.count();
    const texts = await Promise.all(
      Array.from({ length: count }, (_, index) => bubbles.nth(index).innerText()),
    );
    return texts.some((text) => text.trim().includes(nonce)) ? true : null;
  };

/**
 * Playwright settle helpers that avoid waitForTimeout / networkidle
 * (both banned under nursery Playwright rules).
 */
import type { Page } from "playwright";

/**
 * Soft-settle: wait for body visibility then DOMContentLoaded, ignoring timeouts.
 * Replaces page.waitForTimeout(ms) in proof/record scripts.
 */
export const settlePage = async (page: Page, timeoutMs: number): Promise<void> => {
  await page
    .locator("body")
    .waitFor({ state: "visible", timeout: timeoutMs })
    .then(
      () => undefined,
      () => undefined,
    );
  await page.waitForLoadState("domcontentloaded", { timeout: timeoutMs }).then(
    () => undefined,
    () => undefined,
  );
};

/**
 * Shared helpers for headed proof / record scripts.
 */
import { writeError } from "./cli-output";

export const reportFindingsAndExit = async (findings: readonly string[]): Promise<void> => {
  if (findings.length === 0) {
    return;
  }
  await Promise.all(findings.map((finding) => writeError(finding)));
  process.exit(1);
};

/**
 * Module-level env reader for browser proof scripts.
 * Sole allowed env surface for PAGE_PROOF_* / browser artifact paths.
 */
type EnvMap = Readonly<Record<string, string | undefined>>;

const TRAILING_SLASH_RE = /\/$/u;

const readRuntimeEnv = (): EnvMap => {
  const runtime = globalThis as {
    process?: { env?: EnvMap };
  };
  return runtime.process?.env ?? {};
};

export const resolveProofClientBase = (defaultBase: string): string => {
  const raw = readRuntimeEnv().PAGE_PROOF_CLIENT_BASE ?? defaultBase;
  return raw.replace(TRAILING_SLASH_RE, "");
};

export const resolveProofOutDir = (key: string, defaultDir: string): string => {
  const value = readRuntimeEnv()[key];
  return value && value.length > 0 ? value : defaultDir;
};

export const resolveProofEnv = (key: string): string | undefined => readRuntimeEnv()[key];

/**
 * Shared validation utilities for lint/audit scripts.
 * Single source of truth for file scanning and violation reporting.
 */

export const IGNORED_DIRECTORY_NAMES = new Set([
  "node_modules",
  ".git",
  ".nuxt",
  ".output",
  "dist",
  "dist-types",
  "coverage",
  "target",
]);

export type ValidationViolation = {
  filePath: string;
  line: number;
  message: string;
};

export const DEFAULT_SOURCE_EXTENSIONS = new Set([
  ".ts",
  ".tsx",
  ".js",
  ".jsx",
  ".mjs",
  ".cjs",
  ".vue",
  ".html",
  ".css",
]);
const LINE_BREAK_PATTERN = /\r?\n/u;

/**
 * Maps a character offset to a 1-based line number.
 */
export function getLineFromOffset(text: string, offset: number): number {
  if (offset <= 0) {
    return 1;
  }
  let line = 1;
  for (let index = 0; index < offset; index += 1) {
    if (text.charCodeAt(index) === 10) {
      line += 1;
    }
  }
  return line;
}

/**
 * Find the offset of a `<template>` block in Vue SFC content. Returns the
 * offset of the `<` in `<template>`, or -1 if no template block exists.
 * Use this to translate a `match.index` returned from `template.matchAll(...)`
 * (which is relative to the template slice) into an offset into the full
 * content (so `getLineFromOffset(content, offset)` reports the correct line).
 */
export function getTemplateOffset(content: string): number {
  return content.indexOf("<template>");
}

/**
 * Returns true if the path contains any ignored directory segment.
 */
export function shouldIgnorePath(
  pathValue: string,
  ignoredDirs: Set<string> = IGNORED_DIRECTORY_NAMES,
): boolean {
  return pathValue.split("/").some((segment) => ignoredDirs.has(segment));
}

export function hasAllowedExtension(
  pathValue: string,
  allowedExtensions: Set<string> = DEFAULT_SOURCE_EXTENSIONS,
): boolean {
  for (const extension of allowedExtensions) {
    if (pathValue.endsWith(extension)) {
      return true;
    }
  }
  return false;
}

export async function collectProjectFiles(options: {
  rootDir?: string;
  scanRoots: readonly string[];
  allowedExtensions?: Set<string>;
  ignoredDirs?: Set<string>;
}): Promise<string[]> {
  const rootDir = options.rootDir ?? process.cwd();
  const allowedExtensions = options.allowedExtensions ?? DEFAULT_SOURCE_EXTENSIONS;
  const ignoredDirs = options.ignoredDirs ?? IGNORED_DIRECTORY_NAMES;

  const fileGroups = await Promise.all(
    options.scanRoots.map(async (scanRoot) => {
      const glob = new Bun.Glob(`${scanRoot}/**/*`);
      return Array.fromAsync(glob.scan({ cwd: rootDir, onlyFiles: true }));
    }),
  );

  return fileGroups
    .flat()
    .map((filePath) => filePath.replace(/\\/gu, "/"))
    .filter(
      (filePath) =>
        !shouldIgnorePath(filePath, ignoredDirs) &&
        hasAllowedExtension(filePath, allowedExtensions),
    );
}

export async function collectProjectFileEntries(options: {
  rootDir?: string;
  scanRoots: readonly string[];
  allowedExtensions?: Set<string>;
  ignoredDirs?: Set<string>;
}): Promise<Array<{ filePath: string; content: string }>> {
  const files = await collectProjectFiles(options);
  return Promise.all(
    files.map(async (filePath) => ({
      filePath,
      content: await Bun.file(filePath).text(),
    })),
  );
}

export function countLines(text: string): number {
  return text.split(LINE_BREAK_PATTERN).length;
}

export async function reportViolations(
  heading: string,
  violations: ValidationViolation[],
  successMessage: string,
): Promise<void> {
  if (violations.length === 0) {
    await import("./cli-output").then(({ writeOutput }) => writeOutput(successMessage));
    return;
  }

  const { writeError } = await import("./cli-output");
  await writeError(heading);
  const lines = violations.map(
    (violation) => `- ${violation.filePath}:${violation.line} ${violation.message}`,
  );
  if (lines.length > 0) {
    await writeError(lines.join("\n"));
  }
  process.exit(1);
}

