  test("flags unsafe-inline script-src", () => {
    expect(
      UNSAFE_INLINE_SCRIPT_SRC_PATTERN.test("script-src 'self' 'unsafe-inline'; style-src 'self'"),
    ).toBe(true);
    expect(
      UNSAFE_INLINE_SCRIPT_SRC_PATTERN.test("script-src 'self'; style-src 'self' 'unsafe-inline'"),
    ).toBe(false);
  });
