/**
 * Fail-closed: product TTS must be local Kokoro — not cloud, not speechSynthesis-only lies.
 */
import { readFile } from "node:fs/promises";
import { reportViolations, type ValidationViolation } from "./utils/validation-helpers";

const collectLocalKokoroTtsViolations = async (): Promise<ValidationViolation[]> => {
  const violations: ValidationViolation[] = [];
  const settingsPath = "packages/shared/src/constants/settings.ts";
  const speakPath = "packages/client/composables/useSpeech.ts";
  const synthesizePath = "packages/server/src/services/speech/speech-synthesize-service.ts";
  const [settings, speak, synthesize] = await Promise.all([
    readFile(settingsPath, "utf8"),
    readFile(speakPath, "utf8"),
    readFile(synthesizePath, "utf8"),
  ]);

  if (!settings.includes('DEFAULT_TTS_PROVIDER: SpeechProviderOption = "local"')) {
    violations.push({
      filePath: settingsPath,
      line: 1,
      message: 'DEFAULT_TTS_PROVIDER must be "local" (Kokoro on-device).',
    });
  }
  if (!settings.includes("DEFAULT_LOCAL_TTS_ENDPOINT")) {
    violations.push({
      filePath: settingsPath,
      line: 1,
      message: "DEFAULT_LOCAL_TTS_ENDPOINT missing for Kokoro OpenAI-compatible base.",
    });
  }
  if (!speak.includes("synthesizeSpeechViaServer") || !speak.includes("shouldUseLocalKokoroTts")) {
    violations.push({
      filePath: speakPath,
      line: 1,
      message: "useSpeech must route local TTS through synthesizeSpeechViaServer (Kokoro).",
    });
  }
  if (!synthesize.includes("/audio/speech") || !synthesize.includes("RIFF")) {
    violations.push({
      filePath: synthesizePath,
      line: 1,
      message: "speech-synthesize-service must call /audio/speech and verify RIFF WAV bytes.",
    });
  }
  // Soft-ban: browser-only on-device proof must not be the sole TTS gate claim in ledger without Kokoro.
  return violations;
};

if (import.meta.main) {
  await reportViolations(
    "Local Kokoro TTS validation failed:",
    await collectLocalKokoroTtsViolations(),
    "Local Kokoro TTS validation passed.",
  );
}

import enUS, { type AppTranslationOverrides } from "../packages/client/locales/en-US";
import esES from "../packages/client/locales/es-ES/catalog";
import frFR from "../packages/client/locales/fr-FR/catalog";
import jaJP from "../packages/client/locales/ja-JP/catalog";
import { writeError, writeOutput } from "./utils/cli-output";

type Violation = {
  locale: string;
  key: string;
  message: string;
};

type LocaleDefinition = {
  locale: string;
  messages: AppTranslationOverrides;
};

const localeDefinitions: readonly LocaleDefinition[] = [
  { locale: "es-ES", messages: esES },
  { locale: "fr-FR", messages: frFR },
  { locale: "ja-JP", messages: jaJP },
] as const;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const serializeLeafValue = (value: unknown): string => {
  if (typeof value === "string") {
    return value;
  }
  return JSON.stringify(value);
};

const flattenLocaleNode = (path: string, value: unknown, output: Map<string, string>): void => {
  if (isRecord(value)) {
    for (const [key, childValue] of Object.entries(value)) {
      const childPath = path.length > 0 ? `${path}.${key}` : key;
      flattenLocaleNode(childPath, childValue, output);
    }
    return;
  }

  output.set(path, serializeLeafValue(value));
};

const toFlatMap = (value: unknown): Map<string, string> => {
  const flattened = new Map<string, string>();

  if (!isRecord(value)) {
    return flattened;
  }

  for (const [key, childValue] of Object.entries(value)) {
    flattenLocaleNode(key, childValue, flattened);
  }

  return flattened;
};

const collectViolations = (): Violation[] => {
  const baseMessages = toFlatMap(enUS);
  const violations: Violation[] = [];

  for (const localeDefinition of localeDefinitions) {
    const overrideMessages = toFlatMap(localeDefinition.messages);

    for (const [key, overrideValue] of overrideMessages) {
      const baseValue = baseMessages.get(key);
      if (baseValue === undefined) {
        violations.push({
          locale: localeDefinition.locale,
          key,
          message: "Override key does not exist in source locale schema.",
        });
        continue;
      }

      if (overrideValue === baseValue) {
        violations.push({
          locale: localeDefinition.locale,
          key,
          message: "Override value matches source locale value and should be removed.",
        });
      }
    }
  }

  return violations;
};

const main = async (): Promise<void> => {
  const violations = collectViolations();

  if (violations.length === 0) {
    await writeOutput(
      "Locale override validation passed: no schema drift or cross-locale copy detected.",
    );
    return;
  }

  await writeError("Locale override validation failed:");
  const lines = violations.map(
    (violation) => `- [${violation.locale}] ${violation.key}: ${violation.message}`,
  );
  if (lines.length > 0) {
    await writeError(lines.join("\n"));
  }
  process.exit(1);
};

await main();

