    if (!(NAVIGATION_GROUP_IDS as readonly string[]).includes(item.groupId)) {
      violations.push({
        filePath: "packages/client/constants/navigation.ts",
        line: 1,
        message: `Sidebar item "${item.id}" missing/invalid groupId`,
      });
    }
