describe("stripComments", () => {
  test("keeps code that follows a template literal containing a comment opener", () => {
    // `packages/client/nuxt.config.ts` really does hold `${PREFIX}/**`. A regex-based
    // stripper treated it as a block-comment opener and deleted everything up to the
    // next close delimiter, hiding every use site in between.
    const source = [
      `const WILDCARD = \`$\{PREFIX}/**\`;`,
      "/** Doc comment that closes here. */",
      "const used = LIVE_SYMBOL;",
    ].join("\n");

    const stripped = stripComments(source);

    expect(stripped).toContain("LIVE_SYMBOL");
    expect(stripped).toContain("WILDCARD");
    expect(stripped).not.toContain("Doc comment");
  });

  test("keeps code after a line comment that mentions a glob", () => {
    const source = ["// mentions #build/* in prose", "const used = LIVE_SYMBOL;"].join("\n");
    const stripped = stripComments(source);
    expect(stripped).toContain("LIVE_SYMBOL");
    expect(stripped).not.toContain("prose");
  });

  test("removes real comments but preserves quoted attribute bindings", () => {
    const source = [
      "/* block */",
      "// line",
      'const markup = "<div :class=\\"SHELL_CLASS\\"></div>";',
    ].join("\n");
    const stripped = stripComments(source);
    expect(stripped).toContain("SHELL_CLASS");
    expect(stripped).not.toContain("block");
    expect(stripped).not.toContain("line");
  });

  test("does not treat an escaped quote as closing the string", () => {
    const source = ['const value = "a\\"b";', "const used = LIVE_SYMBOL;"].join("\n");
    expect(stripComments(source)).toContain("LIVE_SYMBOL");
  });
});

import { collectIdentifierOccurrences, stripComments } from "./utils/dead-export-references";
import {
  collectProjectFileEntries,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const importPathPattern = /from\s+['"`]([^'"`]+)['"`]/gu;
const sideEffectImportPathPattern = /\bimport\s+['"`]([^'"`]+)['"`]/gu;
const dynamicImportPathPattern = /import\(\s*['"`]([^'"`]+)['"`]\s*\)/gu;
const namedExportPattern =
  /\bexport\s+(?:async\s+)?(?:class|function|const|let|var|type|interface)\s+([A-Za-z0-9_]+)/gu;
const reExportPattern = /\bexport\s*\{\s*([^}]+)\s*\}/gu;
const exportFromPathPattern =
  /\bexport\s+(?:\*\s*(?:as\s+[A-Za-z0-9_]+\s*)?|\{[^}]+\})\s*from\s*['"`]([^'"`]+)['"`]/gu;
const defaultExportPattern = /\bexport\s+default\b/gu;
const LEADING_SLASH_PATTERN = /^\/+/u;
const FILE_EXTENSION_PATTERN = /\.(ts|vue)$/u;
const NUXT_IMPORTS_MANIFEST_PATH = "packages/client/.nuxt/imports.d.ts";
const autoImportExportPattern = /\bexport\s*\{\s*([^}]+)\s*\}\s*from\s*['"`][^'"`]+['"`]/gu;
const AS_CLAUSE_PATTERN = /\s+as\s+/u;
const SOURCE_FILE_EXTENSIONS = [".ts", ".tsx", ".vue", ".js", ".mjs", ".cjs"] as const;

/** Occurrence count contributed by the export declaration itself. */
const DECLARATION_OCCURRENCE_COUNT = 1;

/**
 * Flags exported symbols that nothing references anywhere. Unlike the
 * module-level check above, this is symbol-granular, so a module kept alive by
 * one live import cannot hide dead siblings inside it.
 */
export const isOrphanExportViolation = (options: {
  filePath: string;
  content: string;
  identifierOccurrences: Map<string, number>;
}): ValidationViolation[] => {
  const { filePath, content, identifierOccurrences } = options;
  if (isFrameworkEntrypointFile(filePath)) {
    return [];
  }

  return collectExportedRuntimeNames(content).flatMap((exportName) => {
    const total = identifierOccurrences.get(exportName) ?? 0;
    return total > DECLARATION_OCCURRENCE_COUNT
      ? []
      : [
          {
            filePath,
            line: 1,
            message: `Exported symbol "${exportName}" is referenced nowhere in the workspace. Wire it into a real caller or delete it.`,
          },
        ];
  });
};

const stripSourceExtension = (pathValue: string): string => {
  for (const extension of SOURCE_FILE_EXTENSIONS) {
    if (pathValue.endsWith(extension)) {
      return pathValue.slice(0, -extension.length);
    }
  }
  return pathValue;
};

const collectSourceCandidates = (pathValue: string): string[] => {
  const basePath = stripSourceExtension(pathValue);
  const candidates = new Set<string>([pathValue, basePath]);

  for (const extension of SOURCE_FILE_EXTENSIONS) {
    candidates.add(`${basePath}${extension}`);
    candidates.add(`${basePath}/index${extension}`);
  }

  return [...candidates];
};

const LOCALE_ENTRY_FILE_PATTERN = /^packages\/client\/locales\/[^/]+\.ts$/u;
const LOCALE_CATALOG_FILE_PATTERN = /^packages\/client\/locales\/[^/]+\/catalog\.ts$/u;

const isLocaleCatalogEntrypoint = (filePath: string): boolean =>
  LOCALE_ENTRY_FILE_PATTERN.test(filePath) || LOCALE_CATALOG_FILE_PATTERN.test(filePath);

const isFrameworkEntrypointFile = (filePath: string): boolean =>
  filePath.endsWith(".test.ts") ||
  filePath.endsWith(".d.ts") ||
  filePath === "packages/client/app.vue" ||
  filePath === "packages/client/error.vue" ||
  filePath === "packages/client/nuxt.config.ts" ||
  filePath === "packages/client/vitest.config.ts" ||
  filePath.startsWith("packages/client/pages/") ||
  filePath.startsWith("packages/client/plugins/") ||
  filePath.startsWith("packages/client/layouts/") ||
  filePath.startsWith("packages/client/middleware/") ||
  isLocaleCatalogEntrypoint(filePath);

const normalizeImportTargets = (sourceFilePath: string, importPath: string): string[] => {
  if (importPath.startsWith("@bao/shared/")) {
    const relative = importPath.slice("@bao/shared/".length);
    return collectSourceCandidates(`packages/shared/src/${relative}`);
  }

  if (importPath.startsWith(".")) {
    const sourceDir = sourceFilePath.slice(0, sourceFilePath.lastIndexOf("/"));
    const joined = new URL(`${sourceDir}/${importPath}`, "file:///").pathname.replace(
      LEADING_SLASH_PATTERN,
      "",
    );
    return collectSourceCandidates(joined);
  }

  if (importPath.startsWith("~/")) {
    const relative = importPath.slice(2);
    return collectSourceCandidates(`packages/client/${relative}`);
  }

  return [];
};

const collectExportedRuntimeNames = (rawContent: string): string[] => {
  const content = stripComments(rawContent);
  const exportedNames = new Set<string>();
  const runtimeExportPattern =
    /\bexport\s+(?:async\s+)?(?:class|function|const|let|var)\s+([A-Za-z0-9_]+)/gu;
  runtimeExportPattern.lastIndex = 0;
  for (const match of content.matchAll(runtimeExportPattern)) {
    const exportedName = match[1];
    if (exportedName) {
      exportedNames.add(exportedName);
    }
  }

  reExportPattern.lastIndex = 0;
  for (const match of content.matchAll(reExportPattern)) {
    const clause = match[1] ?? "";
    for (const part of clause.split(",")) {
      const normalized = part.trim().split(AS_CLAUSE_PATTERN).at(-1)?.trim();
      if (normalized) {
        exportedNames.add(normalized);
      }
    }
  }

  return [...exportedNames];
};

const collectNuxtAutoImportNames = async (): Promise<Set<string>> => {
  const manifest = Bun.file(NUXT_IMPORTS_MANIFEST_PATH);
  if (!(await manifest.exists())) {
    return new Set();
  }

  const content = await manifest.text();
  const names = new Set<string>();

  autoImportExportPattern.lastIndex = 0;
  for (const match of content.matchAll(autoImportExportPattern)) {
    const clause = match[1] ?? "";
    for (const part of clause.split(",")) {
      const normalized = part.trim().split(AS_CLAUSE_PATTERN).at(-1)?.trim();
      if (normalized) {
        names.add(normalized);
      }
    }
  }

  return names;
};

const hasExports = (content: string): boolean => {
  namedExportPattern.lastIndex = 0;
  if (namedExportPattern.test(content)) {
    return true;
  }

  reExportPattern.lastIndex = 0;
  if (reExportPattern.test(content)) {
    return true;
  }

  exportFromPathPattern.lastIndex = 0;
  if (exportFromPathPattern.test(content)) {
    return true;
  }

  defaultExportPattern.lastIndex = 0;
  return defaultExportPattern.test(content);
};

const hasAutoImportConsumer = (
  filePath: string,
  exportName: string,
  sourceFiles: Array<{ filePath: string; content: string }>,
  autoImportNames: Set<string>,
): boolean => {
  const usagePattern = new RegExp(
    `\\b${exportName.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&")}\\b`,
    "u",
  );
  const isNuxtAutoImport = autoImportNames.has(exportName);
  return sourceFiles.some(({ filePath: sourceFilePath, content }) => {
    if (sourceFilePath === filePath) {
      return false;
    }
    if (!(isNuxtAutoImport || exportName.startsWith("use"))) {
      return false;
    }
    usagePattern.lastIndex = 0;
    return usagePattern.test(content);
  });
};

export const collectImportedTargets = (
  importSources: Array<{ filePath: string; content: string }>,
): Set<string> => {
  const importedTargets = new Set<string>();
  const importPatterns = [
    importPathPattern,
    sideEffectImportPathPattern,
    dynamicImportPathPattern,
    exportFromPathPattern,
  ];

  const collectPatternTargets = (filePath: string, content: string, pattern: RegExp): string[] => {
    pattern.lastIndex = 0;
    const targets: string[] = [];
    for (const match of content.matchAll(pattern)) {
      const importPath = match[1] ?? "";
      targets.push(...normalizeImportTargets(filePath, importPath));
    }
    return targets;
  };

  for (const { filePath, content } of importSources) {
    for (const importPattern of importPatterns) {
      for (const normalizedTarget of collectPatternTargets(filePath, content, importPattern)) {
        importedTargets.add(normalizedTarget);
      }
    }
  }

  return importedTargets;
};

export const isDeadExportViolation = (options: {
  filePath: string;
  content: string;
  importSources: Array<{ filePath: string; content: string }>;
  autoImportNames: Set<string>;
  importedTargets: Set<string>;
}): ValidationViolation[] => {
  const { filePath, content, importSources, autoImportNames, importedTargets } = options;
  if (isFrameworkEntrypointFile(filePath) || !hasExports(content)) {
    return [];
  }

  const exportedNames = collectExportedRuntimeNames(content);
  // Composables: only `use*` hooks must have callers. Co-located constants/types
  // (e.g. KEYBOARD_ROUTE_SHORTCUTS) do not require separate importers — otherwise
  // cold clones without .nuxt falsely flag live auto-imported hooks.
  const useExports = exportedNames.filter((exportName) => exportName.startsWith("use"));
  if (
    filePath.startsWith("packages/client/composables/") &&
    useExports.length > 0 &&
    useExports.every((exportName) =>
      hasAutoImportConsumer(filePath, exportName, importSources, autoImportNames),
    )
  ) {
    return [];
  }

  const candidatePaths = [filePath, filePath.replace(FILE_EXTENSION_PATTERN, "/index.ts")];
  const isImported = candidatePaths.some((candidatePath) => importedTargets.has(candidatePath));
  return isImported
    ? []
    : [
        {
          filePath,
          line: 1,
          message:
            "Exported module has no internal consumers. Remove the dead export or wire it into a real caller.",
        },
      ];
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots: [
      "packages/client",
      "packages/server/src",
      "packages/shared/src",
      "packages/scraper/src",
      "scripts",
    ],
    allowedExtensions: new Set([".ts", ".vue"]),
  });
  const importSources = await collectProjectFileEntries({
    scanRoots: [
      "packages/client",
      "packages/server/src",
      "packages/shared/src",
      "packages/scraper/src",
      "scripts",
    ],
    allowedExtensions: new Set([".ts", ".vue"]),
  });
  const autoImportNames = await collectNuxtAutoImportNames();
  const importedTargets = collectImportedTargets(importSources);
  const identifierOccurrences = collectIdentifierOccurrences(importSources);

  return files.flatMap(({ filePath, content }) => [
    ...isDeadExportViolation({
      filePath,
      content,
      importSources,
      autoImportNames,
      importedTargets,
    }),
    ...isOrphanExportViolation({ filePath, content, identifierOccurrences }),
  ]);
};

if (import.meta.main) {
  await reportViolations(
    "Dead export validation failed:",
    await collectViolations(),
    "Dead export validation passed.",
  );
}

import { describe, expect, test } from "bun:test";
import { findDeadKeys } from "./validate-no-dead-i18n-keys";

const TODAY = "2026-07-24";

describe("findDeadKeys consumers", () => {
  test("flags a key with no literal or dynamic consumer (VACUOUS_GATE_TEST)", () => {
    const keys = ["app.tagline", "app.consumed", "dashboard.dynamic.metric"];
    const corpus = ['t("app.consumed")', `t(\`dashboard.dynamic.\${variable}\`)`].join("\n");
    const violations = findDeadKeys(keys, corpus, [], TODAY);
    expect(violations).toHaveLength(1);
    expect(violations[0]?.message).toContain("app.tagline");
  });

  test("flags a key that only appears unquoted (comment/prose does not count)", () => {
    const keys = ["app.tagline"];
    const corpus = "// shows app.tagline near the footer\nconst x = app.taglineish;";
    const violations = findDeadKeys(keys, corpus, [], TODAY);
    expect(violations).toHaveLength(1);
    expect(violations[0]?.message).toContain("app.tagline");
  });

  test("does not let a key ride on being a substring of a longer literal", () => {
    const keys = ["jobs.saved"];
    const corpus = 't("jobs.savedJobsEmpty")';
    const violations = findDeadKeys(keys, corpus, [], TODAY);
    expect(violations).toHaveLength(1);
  });

  test("allows a key consumed via dynamic template prefix", () => {
    const keys = ["apiDocs.state.errorRetryable", "apiDocs.state.loading"];
    const corpus = `t(\`apiDocs.state.\${docsUiState}\`)`;
    const violations = findDeadKeys(keys, corpus, [], TODAY);
    expect(violations).toHaveLength(0);
  });

  test("allows a key consumed via string concatenation prefix", () => {
    const keys = ["jobsPage.options.studioType.aaa"];
    const corpus = 't("jobsPage.options.studioType." + value)';
    const violations = findDeadKeys(keys, corpus, [], TODAY);
    expect(violations).toHaveLength(0);
  });
});

describe("findDeadKeys allowlist", () => {
  test("allows an exact key in the allowlist with a future expires date", () => {
    const keys = ["legacy.unused"];
    const allowlist = [
      {
        key: "legacy.unused",
        reason: "Retained for backward compatibility.",
        expires: "2026-12-31",
      },
    ];
    const violations = findDeadKeys(keys, "", allowlist, TODAY);
    expect(violations).toHaveLength(0);
  });

  test("fails an exact-key allowlist entry without expires", () => {
    const allowlist = [{ key: "legacy.unused", reason: "No date given." }];
    const violations = findDeadKeys([], "", allowlist, TODAY);
    expect(violations).toHaveLength(1);
    expect(violations[0]?.message).toContain("expires");
  });

  test("fails an expired allowlist entry", () => {
    const allowlist = [
      { key: "legacy.unused", reason: "Should be resolved by now.", expires: "2026-07-01" },
    ];
    const violations = findDeadKeys([], "", allowlist, TODAY);
    expect(violations).toHaveLength(1);
    expect(violations[0]?.message).toContain("expired");
  });

  test("fails a stale allowlist entry whose key is now literally consumed", () => {
    const allowlist = [{ key: "jobs.saved", reason: "Consumer wired.", expires: "2026-12-31" }];
    const violations = findDeadKeys([], 't("jobs.saved")', allowlist, TODAY);
    expect(violations).toHaveLength(1);
    expect(violations[0]?.message).toContain("Stale allowlist entry");
  });

  test("fails duplicate allowlist entries", () => {
    const allowlist = [
      { key: "legacy.a", reason: "First.", expires: "2026-12-31" },
      { key: "legacy.a", reason: "Second.", expires: "2026-12-31" },
    ];
    const violations = findDeadKeys([], "", allowlist, TODAY);
    expect(violations.some((v) => v.message.includes("Duplicate"))).toBe(true);
  });

  test("wildcard prefix entries do not require expires and still shield keys", () => {
    const keys = ["legacy.a", "legacy.b", "other.dead"];
    const allowlist = [
      {
        key: "legacy.*",
        reason: "Legacy keys retained for plugin compatibility.",
      },
    ];
    const violations = findDeadKeys(keys, "", allowlist, TODAY);
    expect(violations).toHaveLength(1);
    expect(violations[0]?.message).toContain("other.dead");
  });
});

import enUSCatalog from "../packages/client/locales/en-US";
import { type JsonValue, safeParseJson } from "../packages/shared/src/utils/json";
import {
  collectProjectFileEntries,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

/**
 * Dead i18n key detector — flags en-US catalog leaf keys that are never
 * referenced as quoted string literals in any consumer (components, pages,
 * composables, utils, layouts, middleware, plugins, constants, app/error).
 *
 * Root cause this locks forward: an orphan catalog block
 * (`resumeComponentPersonalInfo`) with placeholder values ("John Doe",
 * "john@example.com", ...) shipped undetected because the parity validator
 * only checks cross-locale structure (and all locales merge the en-US base,
 * inheriting every key). This gate fails closed on dead base keys.
 *
 * Dynamic-key consumers (e.g. `t(\`apiDocs.state.${state}\`)`) are allowlisted
 * via `scripts/no-dead-i18n-keys-allowlist.json` (SSOT-declared, with the
 * dynamic prefix that is actually consumed and a justification reason).
 *
 * Allowlist hygiene is gated too: exact-key entries must carry a structured
 * `expires` date, expired entries fail, entries whose key is now literally
 * consumed fail as stale (the consumer got wired — prune the entry), duplicate
 * entries fail, and the total entry count is ratchet-capped at
 * MAX_ALLOWLIST_ENTRIES (may only shrink).
 */

type CatalogNode =
  | string
  | number
  | boolean
  | readonly CatalogNode[]
  | { readonly [key: string]: CatalogNode };

/** Client UI + shared constants that hold i18n key literals (e.g. ai-voice). */
const CONSUMER_SCAN_ROOTS = ["packages/client", "packages/shared"] as const;

/**
 * Definition directory for the en-US base + override catalogs — these DEFINE
 * keys, they do not consume them, so they are excluded from the consumer
 * corpus to avoid self-reference false negatives.
 */
const LOCALE_DEFINITION_DIR = "packages/client/locales/";

const isLocaleDefinition = (filePath: string): boolean =>
  filePath.startsWith(LOCALE_DEFINITION_DIR);

const ALLOWLIST_PATH = "scripts/no-dead-i18n-keys-allowlist.json";

/**
 * Allowlist size ratchet: the entry count may never exceed this ceiling.
 * Lower the constant whenever entries are pruned; never raise it.
 *
 * Now zero. The allowlist previously held 247 entries sharing one boilerplate
 * reason ("dynamic or deferred consumers"), which disabled this gate wholesale and
 * concealed abandoned namespaces, superseded designs, and genuinely unwired UI —
 * a resume preview that never rendered GitHub links, and unnamed loading regions.
 * Every entry was resolved by wiring the consumer or deleting the copy, so any new
 * entry must now justify itself against an empty baseline.
 */
const MAX_ALLOWLIST_ENTRIES = 0;

const EXPIRES_PATTERN = /^\d{4}-\d{2}-\d{2}$/u;

const collectLeafPaths = (value: CatalogNode, prefix = ""): string[] => {
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return prefix.length > 0 ? [prefix] : [];
  }
  if (Array.isArray(value)) {
    return value.flatMap((entry, index) =>
      collectLeafPaths(entry as CatalogNode, prefix.length > 0 ? `${prefix}.${index}` : `${index}`),
    );
  }
  return Object.entries(value).flatMap(([key, nestedValue]) =>
    collectLeafPaths(nestedValue, prefix.length > 0 ? `${prefix}.${key}` : key),
  );
};

type AllowlistEntry = {
  readonly key: string;
  readonly reason: string;
  readonly expires?: string;
};

const isAllowlistEntry = (value: JsonValue): value is AllowlistEntry => {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const record = value;
  if (typeof record.key !== "string" || typeof record.reason !== "string") {
    return false;
  }
  return record.expires === undefined || typeof record.expires === "string";
};

const loadAllowlist = async (): Promise<AllowlistEntry[]> => {
  const file = Bun.file(ALLOWLIST_PATH);
  if (!(await file.exists())) {
    return [];
  }
  const parsed = safeParseJson(await file.text());
  if (parsed === null || !Array.isArray(parsed)) {
    return [];
  }
  return parsed.filter(isAllowlistEntry);
};

const matchesAllowlist = (keyPath: string, allowlist: readonly AllowlistEntry[]): boolean => {
  for (const entry of allowlist) {
    if (entry.key === keyPath) {
      return true;
    }
    if (entry.key.endsWith(".*")) {
      const prefix = entry.key.slice(0, -2);
      if (keyPath.startsWith(`${prefix}.`)) {
        return true;
      }
    }
  }
  return false;
};

const DYNAMIC_PREFIX_PATTERNS = [
  /`([a-zA-Z0-9_.]+)\.\$\{/gu,
  /["']([a-zA-Z0-9_.]+)\.["']\s*\+\s*[a-zA-Z_]/gu,
] as const;

const collectDynamicPrefixes = (corpus: string): Set<string> => {
  const prefixes = new Set<string>();
  for (const pattern of DYNAMIC_PREFIX_PATTERNS) {
    pattern.lastIndex = 0;
    for (const match of corpus.matchAll(pattern)) {
      const prefix = match[1];
      if (prefix) {
        prefixes.add(prefix);
      }
    }
  }
  return prefixes;
};

const startsWithDynamicPrefix = (
  keyPath: string,
  dynamicPrefixes: ReadonlySet<string>,
): boolean => {
  for (const prefix of dynamicPrefixes) {
    if (keyPath.startsWith(`${prefix}.`)) {
      return true;
    }
  }
  return false;
};

const escapeRegExp = (value: string): string => value.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");

/**
 * A key counts as consumed only when it appears as a complete quoted string
 * literal (single, double, or backtick). Bare substring matches — comments,
 * prose, or prefixes of longer keys — do not count.
 */
const isLiterallyConsumed = (keyPath: string, corpus: string): boolean =>
  new RegExp(`["'\`]${escapeRegExp(keyPath)}["'\`]`, "u").test(corpus);

const allowlistViolation = (message: string): ValidationViolation => ({
  filePath: ALLOWLIST_PATH,
  line: 1,
  message,
});

const lintAllowlistEntry = (
  entry: AllowlistEntry,
  corpus: string,
  today: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  const isWildcard = entry.key.endsWith(".*");
  if (!isWildcard && entry.expires === undefined) {
    violations.push(
      allowlistViolation(
        `Allowlist entry "${entry.key}" has no "expires" date. Exact-key debt must be time-boxed (YYYY-MM-DD).`,
      ),
    );
  }
  if (entry.expires !== undefined && !EXPIRES_PATTERN.test(entry.expires)) {
    violations.push(
      allowlistViolation(
        `Allowlist entry "${entry.key}" has malformed "expires" (need YYYY-MM-DD).`,
      ),
    );
  }
  if (entry.expires !== undefined && EXPIRES_PATTERN.test(entry.expires) && entry.expires < today) {
    violations.push(
      allowlistViolation(
        `Allowlist entry "${entry.key}" expired ${entry.expires}. Resolve the key (wire or delete) instead of extending debt.`,
      ),
    );
  }
  if (!isWildcard && isLiterallyConsumed(entry.key, corpus)) {
    violations.push(
      allowlistViolation(
        `Stale allowlist entry "${entry.key}": the key is literally consumed. Remove the entry so the gate protects it.`,
      ),
    );
  }
  return violations;
};

const lintAllowlist = (
  allowlist: readonly AllowlistEntry[],
  corpus: string,
  today: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  if (allowlist.length > MAX_ALLOWLIST_ENTRIES) {
    violations.push(
      allowlistViolation(
        `Allowlist has ${allowlist.length} entries, above the ratchet cap of ${MAX_ALLOWLIST_ENTRIES}. Prune entries; the cap may only shrink.`,
      ),
    );
  }
  const seen = new Set<string>();
  for (const entry of allowlist) {
    if (seen.has(entry.key)) {
      violations.push(allowlistViolation(`Duplicate allowlist entry "${entry.key}".`));
    }
    seen.add(entry.key);
    violations.push(...lintAllowlistEntry(entry, corpus, today));
  }
  return violations;
};

const collectDeadKeyViolations = (
  keyPaths: readonly string[],
  corpus: string,
  allowlist: readonly AllowlistEntry[],
  dynamicPrefixes: ReadonlySet<string>,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  for (const keyPath of keyPaths) {
    if (matchesAllowlist(keyPath, allowlist)) {
      continue;
    }
    if (isLiterallyConsumed(keyPath, corpus)) {
      continue;
    }
    if (startsWithDynamicPrefix(keyPath, dynamicPrefixes)) {
      continue;
    }
    violations.push({
      filePath: "packages/client/locales/en-US/catalog.ts",
      line: 1,
      message: `Dead i18n key "${keyPath}" has no consumer. If consumed dynamically, add to ${ALLOWLIST_PATH} with a reason.`,
    });
  }
  return violations;
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const referenceKeys = collectLeafPaths(enUSCatalog);
  const allowlist = await loadAllowlist();

  const consumerFiles = (
    await collectProjectFileEntries({
      scanRoots: [...CONSUMER_SCAN_ROOTS],
    })
  ).filter((entry) => !isLocaleDefinition(entry.filePath));

  // Single concatenated corpus: a key is "consumed" if its dotted path appears
  // as a quoted string literal, OR its prefix is dynamically interpolated.
  // `t("a.b.c")` and a constants file holding `c: "a.b.c"` surface the literal
  // path string; `t(`a.b.${x}`)` surfaces a dynamic prefix `a.b`.
  const corpus = consumerFiles.map((entry) => entry.content).join("\n");
  const today = new Date().toISOString().slice(0, 10);
  return findDeadKeys(referenceKeys, corpus, allowlist, today);
};

/**
 * Pure dead-key detector — given key paths, a consumer corpus, an allowlist,
 * and today's date (YYYY-MM-DD), returns violations for keys that are neither
 * literally consumed, dynamically prefixed, nor allowlisted, plus violations
 * for allowlist hygiene (oversize, duplicates, missing/malformed/expired
 * `expires`, stale entries). Extracted for testing.
 */
const findDeadKeys = (
  keyPaths: readonly string[],
  corpus: string,
  allowlist: readonly AllowlistEntry[],
  today: string,
): ValidationViolation[] => {
  const dynamicPrefixes = collectDynamicPrefixes(corpus);
  return [
    ...lintAllowlist(allowlist, corpus, today),
    ...collectDeadKeyViolations(keyPaths, corpus, allowlist, dynamicPrefixes),
  ];
};

if (import.meta.main) {
  await reportViolations(
    "Dead i18n key validation failed:",
    await collectViolations(),
    "Dead i18n key validation passed.",
  );
}

export { collectLeafPaths, collectViolations, findDeadKeys };

