import { APP_ROUTES } from "../packages/shared/src/constants/routes";
import { getLineFromOffset, shouldIgnorePath } from "./utils/validation-helpers";

type ViolationCategory = "route" | "api";

type Violation = {
  filePath: string;
  line: number;
  literal: string;
  category: ViolationCategory;
};

const projectRoot = process.cwd();
const clientRoot = "packages/client";
const allowedExtensions = new Set([".ts", ".tsx", ".vue", ".js", ".mjs", ".cjs"]);
const appRouteLiterals = Object.values(APP_ROUTES).filter((route) => route !== "/");
const hardcodedApiLiteralPattern = /(["'])\/api(?:\/[^"']+)?\1/gu;

const hasAllowedExtension = (pathValue: string): boolean => {
  const normalized = pathValue.toLowerCase();
  for (const extension of allowedExtensions) {
    if (normalized.endsWith(extension)) {
      return true;
    }
  }
  return false;
};

import { escapeRegExp } from "../packages/shared/src/utils/string";

const collectClientFiles = async (): Promise<string[]> => {
  const files: string[] = [];
  const glob = new Bun.Glob(`${clientRoot}/**/*`);
  for await (const relativeFilePath of glob.scan({ cwd: projectRoot, onlyFiles: true })) {
    const normalizedPath = relativeFilePath.replace(/\\/gu, "/");
    if (!hasAllowedExtension(normalizedPath) || shouldIgnorePath(normalizedPath)) {
      continue;
    }
    files.push(normalizedPath);
  }
  return files;
};

const collectRouteViolations = (filePath: string, content: string): Violation[] => {
  const violations: Violation[] = [];
  for (const routeLiteral of appRouteLiterals) {
    const routePattern = new RegExp(`(["'])${escapeRegExp(routeLiteral)}\\1`, "gu");
    for (const match of content.matchAll(routePattern)) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        literal: routeLiteral,
        category: "route",
      });
    }
  }
  return violations;
};

const collectApiViolations = (filePath: string, content: string): Violation[] => {
  const violations: Violation[] = [];
  hardcodedApiLiteralPattern.lastIndex = 0;
  for (const match of content.matchAll(hardcodedApiLiteralPattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      literal: match[0],
      category: "api",
    });
  }
  return violations;
};

export const collectHardcodedPathViolationsForContent = (
  filePath: string,
  content: string,
): Violation[] => [
  ...collectRouteViolations(filePath, content),
  ...collectApiViolations(filePath, content),
];

const collectViolations = async (): Promise<Violation[]> => {
  const files = await collectClientFiles();
  const violationGroups = await Promise.all(
    files.map(async (filePath) => {
      const fileContent = await Bun.file(filePath).text();
      return collectHardcodedPathViolationsForContent(filePath, fileContent);
    }),
  );
  return violationGroups.flat();
};

const main = async (): Promise<void> => {
  const violations = await collectViolations();
  if (violations.length === 0) {
    process.stdout.write(
      "Hardcoded path validation passed: client routes and API endpoints use shared constants.\n",
    );
    return;
  }

  process.stderr.write("Hardcoded path validation failed:\n");
  const lines = violations.map((violation) => {
    const reason =
      violation.category === "route"
        ? "Use APP_ROUTES/APP_ROUTE_BUILDERS instead of a route literal."
        : "Use API_ENDPOINTS/builders instead of a hardcoded /api path literal.";
    return `- ${violation.filePath}:${violation.line} ${violation.literal} ${reason}`;
  });
  process.stderr.write(`${lines.join("\n")}\n`);
  process.exit(1);
};

if (import.meta.main) {
  await main();
}

import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue", ".ts"]);
const keyedLiteralFieldNames = [
  "title",
  "description",
  "label",
  "message",
  "placeholder",
  "alt",
  "ariaLabel",
  "ariaDescription",
  "emptyLabel",
  "errorLabel",
  "header",
  "heading",
  "subtitle",
  "body",
  "text",
  "copy",
  "ctaLabel",
  "confirmLabel",
  "cancelLabel",
  "retryLabel",
  "closeLabel",
  "closeAriaLabel",
  "submitLabel",
  "tableLabel",
] as const;
const BACKTICK = "`";
const quoteClassPattern = `['"${BACKTICK}]`;
const literalBodyPattern = `[^'"${BACKTICK}\\n]+`;
const keyedLiteralPattern = new RegExp(
  `\\b(?:${keyedLiteralFieldNames.join("|")})\\s*:\\s*(${quoteClassPattern})(${literalBodyPattern})\\1`,
  "gu",
);
const seoLiteralPattern =
  /\b(?:useServerSeoMeta|useSeoMeta)\s*\([\s\S]*?\b(?:title|description)\s*:\s*(['"`])([^'"`\n]+)\1/gu;
const toastLiteralPattern =
  /\b(?:\$toast|toast)\s*\.\s*(?:success|error|info|warning)\s*\(\s*(['"`])([^'"`\n]+)\1/gu;
const isIgnoredFile = (filePath: string): boolean =>
  filePath.endsWith(".spec.ts") ||
  filePath.endsWith(".test.ts") ||
  filePath.includes("/locales/") ||
  filePath.includes("/.nuxt/") ||
  filePath.includes("/dist/");
const ASCII_LETTER_PATTERN = /[A-Za-z]/u;
const LOCALE_KEY_PATTERN = /^[a-z0-9]+(?:[._-][a-z0-9]+)+$/u;

const isAllowedLiteral = (value: string): boolean =>
  value.startsWith("http") ||
  value.startsWith("/") ||
  LOCALE_KEY_PATTERN.test(value) ||
  !ASCII_LETTER_PATTERN.test(value);

const collectPatternViolations = (
  filePath: string,
  content: string,
  pattern: RegExp,
  messageFactory: (literalValue: string) => string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  pattern.lastIndex = 0;
  for (const match of content.matchAll(pattern)) {
    const literalValue = match[2] ?? "";
    if (isAllowedLiteral(literalValue)) {
      continue;
    }
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: messageFactory(literalValue),
    });
  }
  return violations;
};

export const collectHardcodedUserStringViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isIgnoredFile(filePath)) {
    return [];
  }

  return [
    ...collectPatternViolations(
      filePath,
      content,
      keyedLiteralPattern,
      (literalValue) =>
        `User-facing literal "${literalValue}" should come from i18n, not inline source text.`,
    ),
    ...collectPatternViolations(
      filePath,
      content,
      seoLiteralPattern,
      (literalValue) =>
        `SEO literal "${literalValue}" should come from i18n or shared copy constants.`,
    ),
    ...collectPatternViolations(
      filePath,
      content,
      toastLiteralPattern,
      (literalValue) =>
        `Toast literal "${literalValue}" should come from i18n, not inline source text.`,
    ),
  ];
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions: sourceExtensions,
  });

  return files.flatMap(({ filePath, content }) =>
    collectHardcodedUserStringViolationsForContent(filePath, content),
  );
};

