const SOFT_SCRIPT_PATTERN = /"(lint|typecheck)"\s*:\s*"echo\s+/u;

export const collectSoftPackageScriptViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (!SOFT_SCRIPT_PATTERN.test(content)) {
