import { writeError, writeOutput } from "./utils/cli-output";
import { getLineFromOffset, shouldIgnorePath } from "./utils/validation-helpers";

type Violation = {
  filePath: string;
  line: number;
  tagName: string;
  message: string;
};

const projectRoot = process.cwd();
const clientRoot = "packages/client";
const interactiveRoleNames = ["button", "menuitem", "menuitemradio", "menuitemcheckbox"] as const;
const formControlTagNames = ["input", "select", "textarea"] as const;
const accessibleNameAttributePattern = /(?:\s|:|v-bind:)(?:aria-label|aria-labelledby|title)\s*=/u;
const dialogModalPattern = /(?:\s|:|v-bind:)aria-modal\s*=\s*["']true["']/u;
const hiddenInputPattern = /type\s*=\s*["']hidden["']/u;
const ariaHiddenElementPattern = /aria-hidden\s*=\s*["']true["']/u;
const ariaControlsPattern = /(?:\s|:|v-bind:)aria-controls\s*=/u;
const menuRolePattern = /role\s*=\s*["']menu["']/u;
const menuItemRolePattern = /role\s*=\s*["']menuitem(?:radio|checkbox)?["']/u;
const templateInterpolationPattern = /\{\{[\s\S]*?\}\}/gu;
const markupPattern = /<[^>]+>/gu;
const whitespacePattern = /\s+/gu;
const tagNamePattern = /^<([a-zA-Z0-9:-]+)/;
const roleAttributePattern = /role\s*=\s*["']([^"']+)["']/u;
const daisySwapClassPattern = /\bswap\b/u;
const daisySwapRotateClassPattern = /\bswap-rotate\b/u;

const interactiveRolePattern = new RegExp(
  `<[^>]+role\\s*=\\s*["'](?:${interactiveRoleNames.join("|")})["'][^>]*>`,
  "gu",
);
const tabbablePattern = /<[^>]+tabindex\s*=\s*["']?-?\d+["']?[^>]*>/gu;
const programmaticFocusOnlyPattern = /tabindex\s*=\s*["']-1["']/u;
const landmarkTagNames = [
  "main",
  "section",
  "nav",
  "header",
  "footer",
  "aside",
  "form",
  "article",
] as const;
const menuTriggerPattern = /<[^>]+aria-haspopup\s*=\s*["']menu["'][^>]*>/gu;
const dialogTagPattern = /<dialog\b[\s\S]*?>/gu;
const iconOnlyControlPattern = /<(button|a|NuxtLink|summary)\b[\s\S]*?>([\s\S]*?)<\/\1>/gu;
const detailsBlockPattern = /<details\b[\s\S]*?<\/details>/gu;
const labelControlPattern = /<label\b[\s\S]*?>/gu;
const tabListBlockPattern = /<[^>]+role\s*=\s*["']tablist["'][^>]*>[\s\S]*?<\/div>/gu;
const tabButtonPattern = /<button\b[\s\S]*?role\s*=\s*["']tab["'][\s\S]*?>/gu;
const tabPanelTagPattern = /<[^>]+role\s*=\s*["']tabpanel["'][^>]*>/gu;
const boundIdAttributePattern = /(?:\s|:|v-bind:)id\s*=/u;
const boundAriaLabelledByPattern = /(?:\s|:|v-bind:)aria-labelledby\s*=/u;
const buttonLikeLabelPattern = /(?:drawer-overlay|drawer-button|\bbtn\b)/u;
const labelForAttributePattern = /(?:\s|:|v-bind:)for\s*=/u;
const tabindexAttributePattern = /tabindex\s*=/u;
const conditionalTabPanelPattern = /v-if\s*=|v-else-if\s*=/u;
const ariaCurrentPattern = /aria-current\s*=/u;
const pageButtonPattern =
  /<button\b[\s\S]*?v-for\s*=\s*["'][^"']*page[^"']*["'][\s\S]*?:class\s*=\s*["'][^"']*btn-active[^"']*["'][\s\S]*?>/gu;
const arrowMenuKeyPattern = /ArrowDown|ArrowUp/u;

const hasAccessibleNameAttribute = (tagMarkup: string): boolean =>
  accessibleNameAttributePattern.test(tagMarkup);

const isHiddenInput = (tagMarkup: string): boolean => hiddenInputPattern.test(tagMarkup);

const isAriaHiddenElement = (tagMarkup: string): boolean =>
  ariaHiddenElementPattern.test(tagMarkup);

const extractTagName = (tagMarkup: string): string => {
  const tagNameMatch = tagNamePattern.exec(tagMarkup);
  return tagNameMatch?.[1]?.toLowerCase() ?? "unknown";
};

const isNativeFocusableTag = (tagName: string): boolean =>
  ["a", "button", "input", "select", "summary", "textarea", "nuxtlink"].includes(tagName);

const isAllowedInteractiveRoleTag = (tagName: string, roleName: string): boolean => {
  if (roleName === "button") {
    return ["a", "button", "nuxtlink", "summary"].includes(tagName);
  }

  return ["a", "button", "nuxtlink"].includes(tagName);
};

const isDrawerToggleLabel = (tagMarkup: string): boolean =>
  extractTagName(tagMarkup) === "label" &&
  buttonLikeLabelPattern.test(tagMarkup) &&
  labelForAttributePattern.test(tagMarkup);

const isDaisyThemeSwapLabel = (tagMarkup: string): boolean =>
  extractTagName(tagMarkup) === "label" &&
  daisySwapClassPattern.test(tagMarkup) &&
  daisySwapRotateClassPattern.test(tagMarkup);

const stripMarkupToText = (content: string): string =>
  content
    .replace(templateInterpolationPattern, " dynamic-text ")
    .replace(markupPattern, " ")
    .replace(whitespacePattern, " ")
    .trim();

const collectVueFiles = async (): Promise<string[]> => {
  const files: string[] = [];
  const glob = new Bun.Glob(`${clientRoot}/**/*.vue`);

  for await (const relativeFilePath of glob.scan({ cwd: projectRoot, onlyFiles: true })) {
    const normalizedPath = relativeFilePath.replace(/\\/gu, "/");
    if (shouldIgnorePath(normalizedPath)) {
      continue;
    }
    files.push(normalizedPath);
  }

  return files;
};

const collectFormControlViolations = (
  filePath: string,
  fileContent: string,
  tagName: "input" | "select" | "textarea",
): Violation[] => {
  const violations: Violation[] = [];
  const tagPattern = new RegExp(`<${tagName}\\b[\\s\\S]*?>`, "gu");

  for (const match of fileContent.matchAll(tagPattern)) {
    const tagMarkup = match[0];
    if (isAriaHiddenElement(tagMarkup)) {
      continue;
    }
    if (tagName === "input" && isHiddenInput(tagMarkup)) {
      continue;
    }
    if (hasAccessibleNameAttribute(tagMarkup)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, match.index ?? 0),
      tagName,
      message: "Form controls must include aria-label or aria-labelledby.",
    });
  }

  return violations;
};

const collectDialogViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];

  for (const match of fileContent.matchAll(dialogTagPattern)) {
    const tagMarkup = match[0];
    if (!hasAccessibleNameAttribute(tagMarkup)) {
      violations.push({
        filePath,
        line: getLineFromOffset(fileContent, match.index ?? 0),
        tagName: "dialog",
        message: "Dialogs must include aria-label or aria-labelledby.",
      });
    }
    if (!dialogModalPattern.test(tagMarkup)) {
      violations.push({
        filePath,
        line: getLineFromOffset(fileContent, match.index ?? 0),
        tagName: "dialog",
        message: 'Dialogs must include aria-modal="true".',
      });
    }
  }

  return violations;
};

const collectInteractiveRoleViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];

  for (const match of fileContent.matchAll(interactiveRolePattern)) {
    const tagMarkup = match[0];
    if (isAriaHiddenElement(tagMarkup)) {
      continue;
    }

    const tagName = extractTagName(tagMarkup);
    const roleMatch = roleAttributePattern.exec(tagMarkup);
    const roleName = roleMatch?.[1] ?? "";
    if (roleName === "button" && isDrawerToggleLabel(tagMarkup)) {
      continue;
    }
    if (isAllowedInteractiveRoleTag(tagName, roleName)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, match.index ?? 0),
      tagName,
      message: `Use native buttons or links instead of ${roleName} on generic containers.`,
    });
  }

  return violations;
};

const isLandmarkTag = (tagName: string): boolean =>
  landmarkTagNames.includes(tagName as (typeof landmarkTagNames)[number]);

const collectFocusableViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];

  for (const match of fileContent.matchAll(tabbablePattern)) {
    const tagMarkup = match[0];
    if (isAriaHiddenElement(tagMarkup)) {
      continue;
    }
    if (menuRolePattern.test(tagMarkup)) {
      continue;
    }

    const tagName = extractTagName(tagMarkup);
    if (tagName === "label" && isDrawerToggleLabel(tagMarkup)) {
      continue;
    }
    if (isNativeFocusableTag(tagName)) {
      continue;
    }
    if (isLandmarkTag(tagName) && programmaticFocusOnlyPattern.test(tagMarkup)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, match.index ?? 0),
      tagName,
      message: "Focusable non-native containers must be replaced with native controls.",
    });
  }

  return violations;
};

const collectMenuTriggerViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];

  for (const match of fileContent.matchAll(menuTriggerPattern)) {
    const tagMarkup = match[0];
    if (ariaControlsPattern.test(tagMarkup)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, match.index ?? 0),
      tagName: extractTagName(tagMarkup),
      message: "Menu triggers must connect to their menu with aria-controls.",
    });
  }

  return violations;
};

const collectDisclosureMenuViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];

  for (const match of fileContent.matchAll(detailsBlockPattern)) {
    const detailsMarkup = match[0];
    if (!(menuRolePattern.test(detailsMarkup) || menuItemRolePattern.test(detailsMarkup))) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, match.index ?? 0),
      tagName: "details",
      message:
        "Dropdowns built with details/summary must use disclosure semantics instead of ARIA menu roles.",
    });
  }

  return violations;
};

const collectLabelControlViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];

  for (const match of fileContent.matchAll(labelControlPattern)) {
    const tagMarkup = match[0];
    if (!buttonLikeLabelPattern.test(tagMarkup)) {
      continue;
    }
    if (isDrawerToggleLabel(tagMarkup)) {
      continue;
    }
    if (isDaisyThemeSwapLabel(tagMarkup)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, match.index ?? 0),
      tagName: "label",
      message: "Button-like drawer controls must use native buttons instead of labels.",
    });
  }

  return violations;
};

const collectTabButtonViolations = (
  filePath: string,
  fileContent: string,
  tabListMatch: RegExpMatchArray,
): Violation[] => {
  const violations: Violation[] = [];
  const tabListMarkup = tabListMatch[0];
  const tabListOffset = tabListMatch.index ?? 0;

  if (!tabButtonPattern.test(tabListMarkup)) {
    return violations;
  }

  for (const tabMatch of tabListMarkup.matchAll(tabButtonPattern)) {
    const tabMarkup = tabMatch[0];
    const line = getLineFromOffset(fileContent, tabListOffset + (tabMatch.index ?? 0));
    if (!ariaControlsPattern.test(tabMarkup)) {
      violations.push({
        filePath,
        line,
        tagName: "button",
        message: "Tabs must include aria-controls that point to a tabpanel.",
      });
    }

    if (!tabindexAttributePattern.test(tabMarkup)) {
      violations.push({
        filePath,
        line,
        tagName: "button",
        message: "Tabs must manage roving tabindex for keyboard navigation.",
      });
    }
  }

  return violations;
};

const collectTabPanelViolations = (
  filePath: string,
  fileContent: string,
  tabPanelTags: readonly RegExpMatchArray[],
): Violation[] => {
  const violations: Violation[] = [];

  for (const tabPanelMatch of tabPanelTags) {
    const tabPanelMarkup = tabPanelMatch[0];
    const line = getLineFromOffset(fileContent, tabPanelMatch.index ?? 0);
    if (!boundIdAttributePattern.test(tabPanelMarkup)) {
      violations.push({
        filePath,
        line,
        tagName: "div",
        message: "Tabpanels must expose an id referenced by their controlling tab.",
      });
    }

    if (!boundAriaLabelledByPattern.test(tabPanelMarkup)) {
      violations.push({
        filePath,
        line,
        tagName: "div",
        message: "Tabpanels must expose aria-labelledby that points back to the active tab.",
      });
    }

    if (conditionalTabPanelPattern.test(tabPanelMarkup)) {
      violations.push({
        filePath,
        line,
        tagName: "div",
        message: "Tabpanels must remain mounted and toggle visibility without v-if/v-else-if.",
      });
    }
  }

  return violations;
};

const collectTabContractViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];
  const tabLists = [...fileContent.matchAll(tabListBlockPattern)];
  if (tabLists.length === 0) {
    return violations;
  }

  for (const tabListMatch of tabLists) {
    violations.push(...collectTabButtonViolations(filePath, fileContent, tabListMatch));
  }

  const tabPanelTags = [...fileContent.matchAll(tabPanelTagPattern)];
  if (tabPanelTags.length === 0) {
    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, tabLists[0]?.index ?? 0),
      tagName: "div",
      message: "Tablists must render matching tabpanel regions.",
    });
    return violations;
  }

  violations.push(...collectTabPanelViolations(filePath, fileContent, tabPanelTags));
  return violations;
};

const collectMenuKeyboardViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];
  if (!(menuRolePattern.test(fileContent) || menuItemRolePattern.test(fileContent))) {
    return violations;
  }

  if (arrowMenuKeyPattern.test(fileContent)) {
    return violations;
  }

  violations.push({
    filePath,
    line: 1,
    tagName: "menu",
    message: "ARIA menus must implement ArrowUp and ArrowDown keyboard navigation.",
  });

  return violations;
};

const collectPaginationViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];

  for (const match of fileContent.matchAll(pageButtonPattern)) {
    const buttonMarkup = match[0];
    if (ariaCurrentPattern.test(buttonMarkup)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, match.index ?? 0),
      tagName: "button",
      message: 'Current-page pagination buttons must expose aria-current="page".',
    });
  }

  return violations;
};

const collectIconOnlyControlViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];

  for (const match of fileContent.matchAll(iconOnlyControlPattern)) {
    const [fullMatch, rawTagName, content] = match;
    if (!fullMatch) {
      continue;
    }

    if (hasAccessibleNameAttribute(fullMatch) || isAriaHiddenElement(fullMatch)) {
      continue;
    }

    const visibleText = stripMarkupToText(content ?? "");
    if (visibleText.length > 0) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, match.index ?? 0),
      tagName: rawTagName.toLowerCase(),
      message: "Icon-only controls must include aria-label or aria-labelledby.",
    });
  }

  return violations;
};

export const collectAriaLabelViolationsForContent = (
  filePath: string,
  fileContent: string,
): Violation[] => [
  ...formControlTagNames.flatMap((tagName) =>
    collectFormControlViolations(filePath, fileContent, tagName),
  ),
  ...collectDialogViolations(filePath, fileContent),
  ...collectInteractiveRoleViolations(filePath, fileContent),
  ...collectFocusableViolations(filePath, fileContent),
  ...collectMenuTriggerViolations(filePath, fileContent),
  ...collectMenuKeyboardViolations(filePath, fileContent),
  ...collectDisclosureMenuViolations(filePath, fileContent),
  ...collectLabelControlViolations(filePath, fileContent),
  ...collectTabContractViolations(filePath, fileContent),
  ...collectPaginationViolations(filePath, fileContent),
  ...collectIconOnlyControlViolations(filePath, fileContent),
];

const collectFileViolations = async (filePath: string): Promise<Violation[]> =>
  collectAriaLabelViolationsForContent(filePath, await Bun.file(filePath).text());

const collectViolations = async (): Promise<Violation[]> => {
  const files = await collectVueFiles();
  const perFileViolations = await Promise.all(
    files.map((filePath) => collectFileViolations(filePath)),
  );
  return perFileViolations.flat();
};

const main = async (): Promise<void> => {
  const violations = await collectViolations();

  if (violations.length === 0) {
    await writeOutput(
      "ARIA validation passed for dialogs, tab contracts, pagination semantics, disclosure widgets, and native interactive controls.",
    );
    return;
  }

  await writeError(
    "ARIA validation failed. Replace faux controls, label icon-only controls, and wire dialog/menu semantics correctly:",
  );
  const lines = violations.map(
    (violation) =>
      `- ${violation.filePath}:${violation.line} <${violation.tagName}> ${violation.message}`,
  );
  if (lines.length > 0) {
    await writeError(lines.join("\n"));
  }

  process.exit(1);
};

if (import.meta.main) {
  await main();
}

import { describe, expect, test } from "bun:test";
import { collectUiCanonicalPrimitiveViolationsForContent } from "./validate-ui-canonical-primitives";

const PAGE_PATH = "packages/client/pages/example.vue";
const COMPONENT_PATH = "packages/client/components/example/ExampleWidget.vue";

describe("collectUiCanonicalPrimitiveViolationsForContent: flags inline card card-border card-glass literals without SURFACE_GLASS_CARD_CLASS import", () => {
  test("flags inline card card-border card-glass literals without SURFACE_GLASS_CARD_CLASS import", () => {
    const violations = collectUiCanonicalPrimitiveViolationsForContent(
      COMPONENT_PATH,
      [
        "<template>",
        '<div class="card card-border card-glass glass-interactive h-full"></div>',
        "</template>",
      ].join("\n"),
    );
    expect(violations.some((v) => v.message.includes("SURFACE_GLASS_CARD_CLASS"))).toBe(true);
  });
});

describe("collectUiCanonicalPrimitiveViolationsForContent: passes when file references SURFACE_GLASS_CARD_CLASS", () => {
  test("passes when file references SURFACE_GLASS_CARD_CLASS", () => {
    const violations = collectUiCanonicalPrimitiveViolationsForContent(
      COMPONENT_PATH,
      [
        '<script setup lang="ts">',
        'import { SURFACE_GLASS_CARD_CLASS } from "~/constants/layout";',
        "</script>",
        "<template>",
        "<div :class=\"[SURFACE_GLASS_CARD_CLASS, 'h-full']\"></div>",
        "</template>",
      ].join("\n"),
    );
    expect(violations.some((v) => v.message.includes("SURFACE_GLASS_CARD_CLASS"))).toBe(false);
  });
});

describe("collectUiCanonicalPrimitiveViolationsForContent: flags inline loading-spinner literals without LoadingSpinner primitive", () => {
  test("flags inline loading-spinner literals without LoadingSpinner primitive", () => {
    const violations = collectUiCanonicalPrimitiveViolationsForContent(
      COMPONENT_PATH,
      '<template><span class="loading loading-spinner loading-xs"></span></template>',
    );
    expect(violations.some((v) => v.message.includes("LoadingSpinner"))).toBe(true);
  });
});

describe("collectUiCanonicalPrimitiveViolationsForContent: passes when LoadingSpinner primitive is imported", () => {
  test("passes when LoadingSpinner primitive is imported", () => {
    const violations = collectUiCanonicalPrimitiveViolationsForContent(
      COMPONENT_PATH,
      [
        '<script setup lang="ts">',
        'import LoadingSpinner from "~/components/ui/LoadingSpinner.vue";',
        "</script>",
        "<template>",
        '<span class="loading loading-spinner loading-xs"></span>',
        "</template>",
      ].join("\n"),
    );
    expect(violations.some((v) => v.message.includes("LoadingSpinner"))).toBe(false);
  });
});

describe("collectUiCanonicalPrimitiveViolationsForContent: flags raw HTML table without daisyUI table primitive", () => {
  test("flags raw HTML table without daisyUI table primitive", () => {
    const violations = collectUiCanonicalPrimitiveViolationsForContent(
      COMPONENT_PATH,
      "<template><table><thead><tr><th>X</th></tr></thead></table></template>",
    );
    expect(violations.some((v) => v.message.includes("daisyUI table"))).toBe(true);
  });
});

describe("collectUiCanonicalPrimitiveViolationsForContent: flags raw progress element without daisyUI progress primitive", () => {
  test("flags raw progress element without daisyUI progress primitive", () => {
    const violations = collectUiCanonicalPrimitiveViolationsForContent(
      COMPONENT_PATH,
      '<template><progress value="40" max="100"></progress></template>',
    );
    expect(violations.some((v) => v.message.includes("daisyUI progress"))).toBe(true);
  });
});

describe("collectUiCanonicalPrimitiveViolationsForContent: softening regression: flags card-glass even with extra classes around it", () => {
  test("softening regression: flags card-glass even with extra classes around it", () => {
    const violations = collectUiCanonicalPrimitiveViolationsForContent(
      COMPONENT_PATH,
      '<template><div class="relative card card-border card-glass glass-interactive h-full overflow-hidden"></div></template>',
    );
    expect(violations.length).toBeGreaterThan(0);
  });
});

describe("collectUiCanonicalPrimitiveViolationsForContent: softening regression: page with isEmpty but no EmptyState primitive fails", () => {
  test("softening regression: page with isEmpty but no EmptyState primitive fails", () => {
    const violations = collectUiCanonicalPrimitiveViolationsForContent(
      PAGE_PATH,
      [
        '<script setup lang="ts">',
        'const isEmpty = true; const uiState = "empty";',
        "</script>",
        "<template>",
        "<LoadingSkeleton v-if=\"uiState === 'loading'\" />",
        "</template>",
      ].join("\n"),
    );
    expect(violations.some((v) => v.message.includes("EmptyState"))).toBe(true);
  });
});

import { isControlPrimitiveOwner } from "./ui-control-primitive-owners";
import { isUiSsotAuthority } from "./ui-ssot-authority";
import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue"]);

const isSsotPrimitive = (filePath: string): boolean =>
  isUiSsotAuthority(filePath) || isControlPrimitiveOwner(filePath);

const CARD_GLASS_LITERAL_PATTERN =
  /card\s+card-border\s+card-glass(?:\s+glass-(?:interactive|strong|modal))?/gu;
const SURFACE_GLASS_CONSTANT_REFERENCE_PATTERN =
  /SURFACE_GLASS_CARD_(?:STRONG_)?(?:MODAL_)?CLASS\b/u;
const LOADING_SPINNER_LITERAL_PATTERN = /loading\s+loading-spinner\b/gu;
const LOADING_SPINNER_PRIMITIVE_REFERENCE = /LoadingSpinner\b/u;

const TABLE_LITERAL_PATTERN = /<table\b[^>]*>/gu;
const TABLE_WITHOUT_BASE_CLASS_PATTERN = /<table\b[^>]*class\s*=\s*["'][^"']*\btable\b[^"']*["']/u;
const PROGRESS_LITERAL_PATTERN = /<progress\b[^>]*>/gu;
const PROGRESS_WITHOUT_BASE_CLASS_PATTERN =
  /<progress\b[^>]*class\s*=\s*["'][^"']*\bprogress\b[^"']*["']/u;
const RADIAL_PROGRESS_LITERAL_PATTERN =
  /<[^>]*class\s*=\s*["'][^"']*\bradial-progress\b[^"']*["'][^>]*>/gu;

const EMPTY_STATE_REFERENCE_PATTERN = /<EmptyState\b/u;
const LOADING_SKELETON_REFERENCE_PATTERN = /<LoadingSkeleton\b/u;
const BOOTSTRAP_ERROR_ALERT_REFERENCE_PATTERN = /<BootstrapErrorAlert\b/u;

// Hoisted: UI state contract detection — used inside collectStatePrimitiveGapViolations.
const UI_STATE_NAME_PATTERN = /\buiState\b/u;
const LOADING_SKELETON_TAG_PATTERN = /<LoadingSkeleton\b/u;
const BOOTSTRAP_ERROR_ALERT_TAG_PATTERN = /<BootstrapErrorAlert\b/u;
// Hoisted: literal emptiness / loading / error signals in pages.
const IS_EMPTY_LITERAL_PATTERN = /\bisEmpty\b/u;
const LOADING_LITERAL_PATTERN = /['"]loading['"]/u;
const ERROR_LITERAL_PATTERN = /['"]error['"]/u;
// Hoisted: ARIA progressbar role detection on radial-progress tags.
const PROGRESSBAR_ROLE_PATTERN = /\brole\s*=\s*["']progressbar["']/u;

const collectCardGlassLiteralViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  const violations: ValidationViolation[] = [];
  CARD_GLASS_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(CARD_GLASS_LITERAL_PATTERN)) {
    if (SURFACE_GLASS_CONSTANT_REFERENCE_PATTERN.test(content)) continue;
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Inline card-glass literal "${match[0]}" bypasses SURFACE_GLASS_CARD_CLASS. Import SURFACE_GLASS_CARD_CLASS (or _STRONG_ / _MODAL_) from ~/constants/layout and bind via :class.`,
    });
  }
  return violations;
};

const collectLoadingSpinnerLiteralViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  const violations: ValidationViolation[] = [];
  LOADING_SPINNER_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(LOADING_SPINNER_LITERAL_PATTERN)) {
    if (LOADING_SPINNER_PRIMITIVE_REFERENCE.test(content)) continue;
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Inline spinner "${match[0]}" bypasses the canonical loading primitive. Use LoadingSkeleton (variant="lines") or extract a LoadingSpinner.vue primitive and consume it.`,
    });
  }
  return violations;
};

const collectTablePrimitiveViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  const violations: ValidationViolation[] = [];
  TABLE_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(TABLE_LITERAL_PATTERN)) {
    if (!TABLE_WITHOUT_BASE_CLASS_PATTERN.test(match[0])) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `Raw HTML <table> must opt into the daisyUI table primitive (class="table").`,
      });
    }
  }
  PROGRESS_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(PROGRESS_LITERAL_PATTERN)) {
    if (!PROGRESS_WITHOUT_BASE_CLASS_PATTERN.test(match[0])) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `Raw <progress> must opt into the daisyUI progress primitive (class="progress").`,
      });
    }
  }
  RADIAL_PROGRESS_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(RADIAL_PROGRESS_LITERAL_PATTERN)) {
    if (!PROGRESSBAR_ROLE_PATTERN.test(match[0])) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `daisyUI radial-progress requires role="progressbar".`,
      });
    }
  }
  return violations;
};

const collectStatePrimitiveGapViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  if (!filePath.startsWith("packages/client/pages/")) return [];
  const hasUiStateContract =
    UI_STATE_NAME_PATTERN.test(content) ||
    LOADING_SKELETON_TAG_PATTERN.test(content) ||
    BOOTSTRAP_ERROR_ALERT_TAG_PATTERN.test(content);
  if (!hasUiStateContract) return [];
  const violations: ValidationViolation[] = [];
  if (!EMPTY_STATE_REFERENCE_PATTERN.test(content) && IS_EMPTY_LITERAL_PATTERN.test(content)) {
    violations.push({
      filePath,
      line: 1,
      message: `Page models emptiness (isEmpty) but does not consume the EmptyState primitive. Pages must not hand-roll empty states.`,
    });
  }
  if (!LOADING_SKELETON_REFERENCE_PATTERN.test(content) && LOADING_LITERAL_PATTERN.test(content)) {
    violations.push({
      filePath,
      line: 1,
      message: `Page models a loading state but does not consume the LoadingSkeleton primitive. Pages must not hand-roll loading states.`,
    });
  }
  if (
    !BOOTSTRAP_ERROR_ALERT_REFERENCE_PATTERN.test(content) &&
    ERROR_LITERAL_PATTERN.test(content)
  ) {
    violations.push({
      filePath,
      line: 1,
      message: `Page models an error state but does not consume the BootstrapErrorAlert primitive. Pages must not hand-roll error states.`,
    });
  }
  return violations;
};

export const collectUiCanonicalPrimitiveViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => [
  ...collectCardGlassLiteralViolations(filePath, content),
  ...collectLoadingSpinnerLiteralViolations(filePath, content),
  ...collectTablePrimitiveViolations(filePath, content),
  ...collectStatePrimitiveGapViolations(filePath, content),
];

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions: sourceExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectUiCanonicalPrimitiveViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "UI canonical primitive validation failed:",
    await collectViolations(),
    "UI canonical primitive validation passed.",
  );
}

