import {
  collectProjectFileEntries,
  getLineFromOffset,
  getTemplateOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const NUM_120 = 120;
const NUM_200 = 200;
const NUM_30 = 30;

/**
 * UI density gate (design.md §8.2, §11 — "What would Apple do?").
 *
 * Catches:
 *   1. Cramped rows: too many flex children at `gap-1` / `gap-2` without
 *      a `flex-wrap` or `overflow-hidden` / `min-w-0` guard.
 *   2. Oversized text labels where an icon would suffice (label length > 24
 *      chars on a small button alongside an icon).
 *   3. Stacked sections with redundant headers when a single icon row would
 *      communicate the same information more fluidly.
 *   4. Long-form marketing fluff in enterprise density contexts (paragraphs
 *      > 280 chars in a stat card / table header / control surface).
 *
 * This is a heuristic gate; it surfaces candidates for review rather than
 * hard bans, but violations still fail the gate so they are adjudicated.
 */

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue"]);

const SSOT_ALLOWLIST_PATHS = new Set<string>([
  "packages/client/components/ui/LoadingSkeleton.vue",
  "packages/client/components/ui/EmptyState.vue",
  "packages/client/components/ui/PageScaffold.vue",
  "packages/client/components/ui/SectionGrid.vue",
  "packages/client/components/ui/PageHeroHeader.vue",
  "packages/client/components/ui/PageHeaderBlock.vue",
  "packages/client/components/ui/BootstrapErrorAlert.vue",
]);

const isSsotPrimitive = (filePath: string): boolean => SSOT_ALLOWLIST_PATHS.has(filePath);

// Cramped row: gap-1 or gap-2 with multiple flex children and no wrap guard.
const crampedRowPattern =
  /\bclass\s*=\s*["'][^"']*\b(?:flex|inline-flex)\b[^"']*\bgap-1\b[^"']*["']/gu;
// Button tag pair — we extract both tag and inner content separately so we
// can detect icon + long-text combos where `[^<]{24,}` would fail because
// the icon SVG sits between the opening tag and the text node.
const buttonTagPattern = /<button\b[^>]*>([\s\S]*?)<\/button>/gu;
// Long paragraph in a card/control surface.
const longParagraphInControlPattern =
  /\bclass\s*=\s*["'][^"']*\b(?:card-body|btn|stat|badge|chip|tooltip)[^"']*["'][^>]*>[^<]{280,}/gu;

// Hoisted: flex-wrap guard detection inside cramped row class strings.
const FLEX_WRAP_PATTERN = /\bflex-wrap\b/u;
// Hoisted: overflow-hidden / overflow-x-clip guard detection inside cramped row class strings.
const OVERFLOW_GUARD_PATTERN = /\boverflow-(?:hidden|x-clip)\b/u;
// Hoisted: min-w-0 guard detection inside cramped row class strings.
const MIN_W_ZERO_PATTERN = /\bmin-w-0\b/u;
// Hoisted: nav/menu/list context detection inside cramped row class strings.
const NAV_CONTEXT_CLASS_PATTERN =
  /\b(?:menu|navbar|tabs|breadcrumb|breadcrumbs|nav|sidebar|listbox|tablist)\b/u;
// Hoisted: drawer-aware pattern (ml-auto/is-drawer-*) for cramped row allowance.
const DRAWER_AWARE_CLASS_PATTERN =
  /\b(?:is-drawer-(?:open|close)|ms-auto|me-auto|ml-auto|mr-auto)\b/u;
// Hoisted: surrounding-template nav/menu container detection for cramped row allowance.
const NAV_CONTAINER_LOOKBACK_PATTERN =
  /<(?:nav|ul|ol|aside|menu|tablist)\b[^>]*>(?:[\s\S]{0,400}?)<(?:div|span)\b[^>]*\b(?:flex|inline-flex)\b[^']*\bgap-1\b/iu;
// Hoisted: SVG/Icon tag presence inside a button's inner content.
const ICON_TAG_PATTERN = /<(?:svg|Icon|icon)\b/iu;
// Hoisted: strip nested HTML tags from button inner content for visible-text length.
const NESTED_TAG_STRIP_PATTERN = /<[^>]+>/gu;
// Hoisted: strip i18n binding expressions from button inner content for visible-text length.
const I18N_BINDING_STRIP_PATTERN = /\{\{[^}]*\}\}/gu;

const extractTemplateBlocks = (content: string): string => {
  const templateStart = content.indexOf("<template>");
  if (templateStart < 0) return "";
  const templateEnd = content.lastIndexOf("</template>");
  if (templateEnd <= templateStart) return content.slice(templateStart);
  return content.slice(templateStart, templateEnd + "</template>".length);
};

const collectCrampedRowViolations = (
  filePath: string,
  content: string,
  template: string,
  templateOffset: number,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  crampedRowPattern.lastIndex = 0;
  for (const match of template.matchAll(crampedRowPattern)) {
    const classValue = match[0] ?? "";
    const lineText =
      template.slice(Math.max(0, (match.index ?? 0) - NUM_120), (match.index ?? 0) + NUM_200) ?? "";
    const hasWrap = FLEX_WRAP_PATTERN.test(classValue);
    const hasOverflowGuard = OVERFLOW_GUARD_PATTERN.test(classValue);
    const hasMinW0 = MIN_W_ZERO_PATTERN.test(classValue);
    const isNavContext =
      NAV_CONTEXT_CLASS_PATTERN.test(classValue) || NAV_CONTAINER_LOOKBACK_PATTERN.test(lineText);
    const isDrawerAware = DRAWER_AWARE_CLASS_PATTERN.test(classValue);
    if (!hasWrap && !hasOverflowGuard && !hasMinW0 && !isNavContext && !isDrawerAware) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, (match.index ?? 0) + Math.max(0, templateOffset)),
        message: `Cramped row (flex + gap-1) without flex-wrap / overflow-hidden / min-w-0 guard. Items will overshoot on narrow viewports. Consider icon-only controls or hover-reveal.`,
      });
    }
  }
  return violations;
};

const collectVerboseIconButtonViolations = (
  filePath: string,
  content: string,
  template: string,
  templateOffset: number,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  buttonTagPattern.lastIndex = 0;
  for (const match of template.matchAll(buttonTagPattern)) {
    const inner = match[1] ?? "";
    const hasIcon = ICON_TAG_PATTERN.test(inner);
    const visibleText = inner
      .replace(NESTED_TAG_STRIP_PATTERN, "")
      .replace(I18N_BINDING_STRIP_PATTERN, "")
      .trim();
    if (hasIcon && visibleText.length > 24) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, (match.index ?? 0) + Math.max(0, templateOffset)),
        message: `Button with icon + verbose label ("${visibleText.slice(0, NUM_30)}…", ${visibleText.length} chars). Icon already communicates the action; shorten the label or use aria-label + icon-only on tight surfaces.`,
      });
    }
  }
  return violations;
};

const collectLongCopyInControlViolations = (
  filePath: string,
  content: string,
  template: string,
  templateOffset: number,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  longParagraphInControlPattern.lastIndex = 0;
  for (const match of template.matchAll(longParagraphInControlPattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, (match.index ?? 0) + Math.max(0, templateOffset)),
      message: `Long-form copy (${(match[0] ?? "").length} chars) inside a control surface. Enterprise density requires scannable labels; move prose to a help docs page or a collapsible disclosure.`,
    });
  }
  return violations;
};

const collectDensityViolations = (filePath: string, content: string): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  const template = extractTemplateBlocks(content);
  if (template.length === 0) return [];
  const templateOffset = getTemplateOffset(content);
  return [
    ...collectCrampedRowViolations(filePath, content, template, templateOffset),
    ...collectVerboseIconButtonViolations(filePath, content, template, templateOffset),
    ...collectLongCopyInControlViolations(filePath, content, template, templateOffset),
  ];
};

export const collectDensityViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => collectDensityViolations(filePath, content);

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions: sourceExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectDensityViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "UI density validation failed:",
    await collectViolations(),
    "UI density validation passed.",
  );
}

import { describe, expect, test } from "bun:test";
import { collectGlassMaterialViolationsForContent } from "./validate-ui-glass-materials";

const CONSUMER_PATH = "packages/client/components/dashboard/ExampleWidget.vue";

describe("collectGlassMaterialViolationsForContent", () => {
  test("flags card with shadow but no glass class", () => {
    const violations = collectGlassMaterialViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="card card-border shadow-lg"></div></template>',
    );
    expect(violations.some((v) => v.message.includes("glass material class"))).toBe(true);
  });

  test("flags bespoke panel surface (bg-base + shadow + border)", () => {
    const violations = collectGlassMaterialViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="bg-base-100 shadow-lg border-base-300 p-4"></div></template>',
    );
    expect(violations.some((v) => v.message.includes("Bespoke panel surface"))).toBe(true);
  });

  test("flags interactive card without glass-interactive mixin", () => {
    const violations = collectGlassMaterialViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="card card-glass" @click="onClick">x</div></template>',
    );
    expect(violations.some((v) => v.message.includes("glass-interactive"))).toBe(true);
  });

  test("allows card with card-glass + glass-interactive on @click", () => {
    const violations = collectGlassMaterialViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="card card-glass glass-interactive" @click="onClick">x</div></template>',
    );
    expect(violations).toHaveLength(0);
  });

  test("allows card-glass-strong without interactive mixin (non-interactive)", () => {
    const violations = collectGlassMaterialViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="card card-glass-strong">static</div></template>',
    );
    expect(violations).toHaveLength(0);
  });

  test("flags raw glass-subtle class literal in consumers", () => {
    const violations = collectGlassMaterialViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="rounded-box glass-subtle p-4">x</div></template>',
    );
    expect(violations.some((v) => v.message.includes("SURFACE_GLASS_SUBTLE_CLASS"))).toBe(true);
  });
});

import { isControlPrimitiveOwner } from "./ui-control-primitive-owners";
import { isUiSsotAuthority } from "./ui-ssot-authority";
import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

/**
 * Glass material system enforcement (design.md §3, §5).
 *
 * The layout/CSS SSOT defines canonical glass surfaces in main.css:
 *   .glass / .card.card-glass       — standard material
 *   .glass-subtle                   — subtle (sidebar, navbar)
 *   .glass-strong / .card.card-glass-strong — elevated (popovers)
 *   .glass-modal / .card.card-glass-modal   — transient layers
 *   .glass-clear                     — decorative media controls
 *   .glass-solid                     — opaque fallback
 *   .glass-interactive               — interactive state mixin
 *   .glass-selected / .glass-disabled / .glass-error — state mixins
 *
 * This gate catches surfaces that look like elevated panels (card-like
 * containers with shadows + borders) but bypass the glass system by
 * composing raw `bg-base-*` + `shadow-*` + `border-*` utilities.
 *
 * It also enforces that `.card.card-glass` literals reference the SSOT
 * constants (SURFACE_GLASS_CARD_CLASS etc.) when used in pages/composites,
 * and that interactive cards use the `glass-interactive` mixin.
 *
 * Zero consumer exemptions — authority + ui/icon primitive owners only.
 */

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue"]);

const isSsotSourceFile = (filePath: string): boolean =>
  isUiSsotAuthority(filePath) || isControlPrimitiveOwner(filePath);

// A surface that uses card + shadow + bg-base-* but no glass class is bespoke.
const cardSurfaceWithoutGlassPattern =
  /\bclass\s*=\s*["'][^"']*\bcard\b[^"']*(?:shadow-(?:sm|md|lg|xl|2xl))[^"']*(?:(?!glass).)*["']/gu;

// Dynamic :class binding variant of the above.
const cardSurfaceWithoutGlassDynamicPattern =
  /:class\s*=\s*["'][^"']*\bcard\b[^"']*(?:shadow-(?:sm|md|lg|xl|2xl))[^"']*(?:(?!glass).)*["']/gu;

// A surface that composes bg-base-100 + shadow-* + border but isn't a card.
// This is the bespoke-panel smell: three surface utilities that the glass
// system already covers via .glass / .glass-subtle / .glass-strong.
const bespokePanelSurfacePattern =
  /\bclass\s*=\s*["'][^"']*\bbg-base-\d+[^"']*\bshadow-(?:sm|md|lg|xl|2xl)\b[^"']*\bborder-(?:base-\d+|1|2)\b[^"']*["']/gu;

// Dynamic :class binding variant of the above.
const bespokePanelSurfaceDynamicPattern =
  /:class\s*=\s*["'][^"']*\bbg-base-\d+[^"']*\bshadow-(?:sm|md|lg|xl|2xl)\b[^"']*\bborder-(?:base-\d+|1|2)\b[^"']*["']/gu;

// Interactive card (has @click or role="button" or btn) without glass-interactive.
const interactiveCardWithoutMixinPattern =
  /<(?:div|button|article|li)[^>]*\bclass\s*=\s*["'][^"']*\bcard\b[^"']*(?:glass|card-glass)[^"']*["'][^>]*(?:@click|role\s*=\s*["']button["'])[^>]*>/gu;

// Hoisted: glass token presence on a matched tag (word-boundary check covers
// glass / glass-... compound class names).
const GLASS_TOKEN_TAIL_PATTERN = /glass(?:\s|$|-)/u;
// Hoisted: glass-interactive mixin presence on a matched tag.
const GLASS_INTERACTIVE_MIXIN_PATTERN = /\bglass-interactive\b/u;

const extractTemplateBlocks = (content: string): string => {
  const templateStart = content.indexOf("<template>");
  if (templateStart < 0) return "";
  const templateEnd = content.lastIndexOf("</template>");
  if (templateEnd <= templateStart) return content.slice(templateStart);
  return content.slice(templateStart, templateEnd + "</template>".length);
};

const collectPatternViolations = (
  filePath: string,
  fullContent: string,
  haystack: string,
  haystackOffset: number,
  pattern: RegExp,
  skipPattern: RegExp | null,
  message: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  pattern.lastIndex = 0;
  for (const match of haystack.matchAll(pattern)) {
    if (skipPattern?.test(match[0] ?? "")) continue;
    violations.push({
      filePath,
      line: getLineFromOffset(fullContent, haystackOffset + (match.index ?? 0)),
      message,
    });
  }
  return violations;
};

export const collectGlassMaterialViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isSsotSourceFile(filePath)) return [];
  const template = extractTemplateBlocks(content);
  if (template.length === 0) return [];
  const templateOffset = Math.max(0, content.indexOf(template));

  const cardMsg =
    "Card surface with shadow but no glass material class. Add card-glass (or card-glass-strong/modal) or consume SURFACE_GLASS_CARD_CLASS from constants/layout.ts.";
  const panelMsg =
    "Bespoke panel surface (bg-base-* + shadow-* + border-*) bypasses the glass material system. Use glass / glass-subtle / glass-strong or a SURFACE_GLASS_*_CLASS constant.";

  const cardHits = collectPatternViolations(
    filePath,
    content,
    template,
    templateOffset,
    cardSurfaceWithoutGlassPattern,
    GLASS_TOKEN_TAIL_PATTERN,
    cardMsg,
  );
  const cardDynamicHits = collectPatternViolations(
    filePath,
    content,
    template,
    templateOffset,
    cardSurfaceWithoutGlassDynamicPattern,
    GLASS_TOKEN_TAIL_PATTERN,
    `Dynamic :class binding: ${cardMsg}`,
  );
  const panelHits = collectPatternViolations(
    filePath,
    content,
    template,
    templateOffset,
    bespokePanelSurfacePattern,
    GLASS_TOKEN_TAIL_PATTERN,
    panelMsg,
  );
  return [
    ...cardHits,
    ...cardDynamicHits,
    ...panelHits,
    ...collectPanelDynamicAndInteractiveHits(filePath, content, template, templateOffset, panelMsg),
  ];
};

const collectPanelDynamicAndInteractiveHits = (
  filePath: string,
  content: string,
  template: string,
  templateOffset: number,
  panelMsg: string,
): ValidationViolation[] => [
  ...collectPatternViolations(
    filePath,
    content,
    template,
    templateOffset,
    bespokePanelSurfaceDynamicPattern,
    GLASS_TOKEN_TAIL_PATTERN,
    `Dynamic :class binding: ${panelMsg}`,
  ),
  ...collectPatternViolations(
    filePath,
    content,
    template,
    templateOffset,
    interactiveCardWithoutMixinPattern,
    GLASS_INTERACTIVE_MIXIN_PATTERN,
    'Interactive card (has @click or role="button") missing glass-interactive mixin. Add glass-interactive or SURFACE_GLASS_CARD_CLASS (which includes it).',
  ),
  ...collectPatternViolations(
    filePath,
    content,
    content,
    0,
    /\bglass-subtle\b/gu,
    null,
    "Raw glass-subtle class literal bypasses SURFACE_GLASS_SUBTLE_CLASS. Import SURFACE_GLASS_SUBTLE_CLASS from ~/constants/layout and bind via :class.",
  ),
];

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions: sourceExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectGlassMaterialViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "UI glass material validation failed:",
    await collectViolations(),
    "UI glass material validation passed.",
  );
}

import enUS from "../packages/client/locales/en-US";
import { writeError, writeOutput } from "./utils/cli-output";
import { getLineFromOffset, shouldIgnorePath } from "./utils/validation-helpers";

type Violation = {
  filePath: string;
  line: number;
  message: string;
};

type TemplateBlock = {
  content: string;
  offset: number;
};

type TemplateTag = {
  markup: string;
  offset: number;
};

type TemplateTextSegment = {
  text: string;
  offset: number;
};

type LocalePathFrame = {
  pathValue: string;
  node: unknown;
};

type TemplateTextScanState = {
  inTag: boolean;
  inInterpolation: boolean;
  quote: "'" | '"' | null;
  textStart: number;
  index: number;
};

type TemplateCharacterWindow = {
  char: string;
  nextChar: string;
};

const projectRoot = process.cwd();
const sourceRoots = ["packages/client", "packages/shared/src"] as const;
const sourceExtensions = new Set([".vue", ".ts", ".tsx", ".js", ".mjs", ".cjs"]);

const translationCallPattern = /(?:\b\$?t)\(\s*(['"`])([^'"`]+)\1/gu;
const staticAttributePattern =
  /(?<![:\w-])(aria-label|aria-description|aria-placeholder|placeholder|title|alt|data-tip)\s*=\s*("([^"]*)"|'([^']*)')/gu;
const boundAttributeLiteralPattern =
  /(?:\s|<)(?::|v-bind:)(aria-label|aria-description|aria-placeholder|placeholder|title|alt|data-tip)\s*=\s*("([^"]*)"|'([^']*)')/gu;
const templateInterpolationPattern = /\{\{[\s\S]*?\}\}/gu;
const whitespacePattern = /\s+/gu;
const localeKeyFormatPattern = /^[a-zA-Z0-9_.-]+$/u;
const punctuationOnlyPattern = /^[\d\s+./,:;!?()[\]{}<>=_%|*&'"`~-]+$/u;
const humanTextPattern = /\p{L}/u;
const templateOpenToken = "{{";
const templateCloseToken = "}}";
const tagOpenToken = "<";
const tagCloseToken = ">";
const closingTagPrefix = "</";
const declarationTagPrefix = "<!";

const hasSourceExtension = (pathValue: string): boolean => {
  for (const extension of sourceExtensions) {
    if (pathValue.endsWith(extension)) {
      return true;
    }
  }
  return false;
};

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const createChildPath = (pathValue: string, child: string | number): string =>
  pathValue.length > 0 ? `${pathValue}.${child}` : `${child}`;

const collectChildLocaleFrames = (frame: LocalePathFrame, stack: LocalePathFrame[]): void => {
  if (Array.isArray(frame.node)) {
    for (let index = frame.node.length - 1; index >= 0; index -= 1) {
      stack.push({
        pathValue: createChildPath(frame.pathValue, index),
        node: frame.node[index],
      });
    }
    return;
  }

  if (!isRecord(frame.node)) {
    return;
  }

  const entries = Object.entries(frame.node);
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    const [key, childNode] = entries[index];
    stack.push({
      pathValue: createChildPath(frame.pathValue, key),
      node: childNode,
    });
  }
};

const collectLocalePaths = (value: unknown): Set<string> => {
  const keys = new Set<string>();
  const stack: LocalePathFrame[] = [{ pathValue: "", node: value }];

  while (stack.length > 0) {
    const frame = stack.pop();
    if (!frame) {
      continue;
    }

    if (frame.pathValue.length > 0) {
      keys.add(frame.pathValue);
    }

    if (typeof frame.node !== "string") {
      collectChildLocaleFrames(frame, stack);
    }
  }
  return keys;
};

const scanSourceRoot = async (sourceRoot: (typeof sourceRoots)[number]): Promise<string[]> => {
  const glob = new Bun.Glob(`${sourceRoot}/**/*`);
  const relativeFilePaths = await Array.fromAsync(glob.scan({ cwd: projectRoot, onlyFiles: true }));

  return relativeFilePaths.flatMap((relativeFilePath) => {
    const normalizedPath = relativeFilePath.replace(/\\/gu, "/");
    if (shouldIgnorePath(normalizedPath) || !hasSourceExtension(normalizedPath)) {
      return [];
    }
    return [normalizedPath];
  });
};

const collectSourceFiles = async (): Promise<string[]> => {
  const perRootFiles = await Promise.all(
    sourceRoots.map((sourceRoot) => scanSourceRoot(sourceRoot)),
  );
  return perRootFiles.flat();
};

const localizedDomainOutputPatterns: Array<{ pattern: RegExp; label: string }> = [
  { pattern: /\{\{\s*job\.experienceLevel\s*\}\}/gu, label: "job.experienceLevel" },
  { pattern: /\{\{\s*job\.studioType\s*\}\}/gu, label: "job.studioType" },
  { pattern: /\{\{\s*job\.platforms?\s*\}\}/gu, label: "job.platforms" },
  { pattern: /\{\{\s*job\.gameGenres?\s*\}\}/gu, label: "job.gameGenres" },
  { pattern: /\{\{\s*studio\.type\s*\}\}/gu, label: "studio.type" },
  { pattern: /\{\{\s*studio\.size\s*\}\}/gu, label: "studio.size" },
  { pattern: /<option\b[^>]*>\s*\{\{\s*type\s*\}\}\s*<\/option>/gu, label: "studio type option" },
  { pattern: /<option\b[^>]*>\s*\{\{\s*size\s*\}\}\s*<\/option>/gu, label: "studio size option" },
];

const collectLocalizedDomainOutputViolations = (
  filePath: string,
  fileContent: string,
): Violation[] => {
  const violations: Violation[] = [];

  for (const { pattern, label } of localizedDomainOutputPatterns) {
    for (const match of fileContent.matchAll(pattern)) {
      violations.push({
        filePath,
        line: getLineFromOffset(fileContent, match.index ?? 0),
        message: `${label} must be localized with a shared label resolver instead of raw output.`,
      });
    }
  }

  return violations;
};

const extractTemplateBlocks = (fileContent: string): TemplateBlock[] => {
  const blocks: TemplateBlock[] = [];
  const openTagPattern = /<template\b[^>]*>/giu;
  let openMatch = openTagPattern.exec(fileContent);

  while (openMatch) {
    const openTag = openMatch[0];
    const startOffset = (openMatch.index ?? 0) + openTag.length;
    const closeOffset = fileContent.indexOf("</template>", startOffset);
    if (closeOffset === -1) {
      break;
    }
    blocks.push({
      content: fileContent.slice(startOffset, closeOffset),
      offset: startOffset,
    });
    openTagPattern.lastIndex = closeOffset + "</template>".length;
    openMatch = openTagPattern.exec(fileContent);
  }

  return blocks;
};

const isQuoteCharacter = (char: string): char is "'" | '"' => char === "'" || char === '"';

const isTemplateTagCandidate = (markup: string): boolean =>
  !(markup.startsWith(closingTagPrefix) || markup.startsWith(declarationTagPrefix));

const findTagCloseOffset = (templateContent: string, openOffset: number): number => {
  const contentLength = templateContent.length;
  let cursor = openOffset + 1;
  let quote: "'" | '"' | null = null;

  while (cursor < contentLength) {
    const char = templateContent[cursor];
    if (quote) {
      if (char === quote) {
        quote = null;
      }
      cursor += 1;
      continue;
    }

    if (isQuoteCharacter(char)) {
      quote = char;
      cursor += 1;
      continue;
    }

    if (char === tagCloseToken) {
      return cursor;
    }

    cursor += 1;
  }

  return -1;
};

const collectTemplateTags = (templateContent: string): TemplateTag[] => {
  const tags: TemplateTag[] = [];
  const contentLength = templateContent.length;
  let index = 0;

  while (index < contentLength) {
    const openOffset = templateContent.indexOf(tagOpenToken, index);
    if (openOffset === -1) {
      break;
    }

    const closeOffset = findTagCloseOffset(templateContent, openOffset);
    if (closeOffset === -1) {
      break;
    }

    const markup = templateContent.slice(openOffset, closeOffset + 1);
    if (isTemplateTagCandidate(markup)) {
      tags.push({
        markup,
        offset: openOffset,
      });
    }

    index = closeOffset + 1;
  }

  return tags;
};

const appendTextSegment = (
  segments: TemplateTextSegment[],
  templateContent: string,
  textStart: number,
  textEnd: number,
): void => {
  if (textEnd <= textStart) {
    return;
  }

  segments.push({
    text: templateContent.slice(textStart, textEnd),
    offset: textStart,
  });
};

const isTokenPair = (char: string, nextChar: string, token: string): boolean =>
  char === token[0] && nextChar === token[1];

const advanceTagState = (state: TemplateTextScanState, char: string): void => {
  if (state.quote) {
    if (char === state.quote) {
      state.quote = null;
    }
    return;
  }

  if (isQuoteCharacter(char)) {
    state.quote = char;
    return;
  }

  if (char === tagCloseToken) {
    state.inTag = false;
    state.textStart = state.index + 1;
  }
};

const advanceTextState = (
  state: TemplateTextScanState,
  segments: TemplateTextSegment[],
  templateContent: string,
  charWindow: TemplateCharacterWindow,
): number => {
  const { char, nextChar } = charWindow;
  if (state.inInterpolation) {
    if (isTokenPair(char, nextChar, templateCloseToken)) {
      state.inInterpolation = false;
      return 2;
    }
    return 1;
  }

  if (isTokenPair(char, nextChar, templateOpenToken)) {
    state.inInterpolation = true;
    return 2;
  }

  if (char === tagOpenToken) {
    appendTextSegment(segments, templateContent, state.textStart, state.index);
    state.inTag = true;
  }

  return 1;
};

const collectTemplateTextSegments = (templateContent: string): TemplateTextSegment[] => {
  const segments: TemplateTextSegment[] = [];
  const state: TemplateTextScanState = {
    inTag: false,
    inInterpolation: false,
    quote: null,
    textStart: 0,
    index: 0,
  };

  while (state.index < templateContent.length) {
    const char = templateContent[state.index];
    const nextChar =
      state.index + 1 < templateContent.length ? templateContent[state.index + 1] : "";

    if (state.inTag) {
      advanceTagState(state, char);
      state.index += 1;
      continue;
    }

    const offsetDelta = advanceTextState(state, segments, templateContent, { char, nextChar });
    state.index += offsetDelta;
  }

  if (!state.inTag) {
    appendTextSegment(segments, templateContent, state.textStart, templateContent.length);
  }

  return segments;
};

const hasHumanText = (value: string): boolean => humanTextPattern.test(value);

const normalizeTemplateText = (value: string): string =>
  value.replace(templateInterpolationPattern, " ").replace(whitespacePattern, " ").trim();

const isIgnoredTemplateText = (value: string): boolean => {
  if (value.length === 0) {
    return true;
  }
  if (punctuationOnlyPattern.test(value)) {
    return true;
  }
  if (value === "&nbsp;") {
    return true;
  }
  return false;
};

const collectMissingTranslationKeyViolations = (
  filePath: string,
  fileContent: string,
  localeKeys: Set<string>,
): Violation[] => {
  const violations: Violation[] = [];

  for (const match of fileContent.matchAll(translationCallPattern)) {
    const key = match[2]?.trim() ?? "";
    if (!localeKeyFormatPattern.test(key)) {
      continue;
    }
    if (localeKeys.has(key)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, match.index ?? 0),
      message: `Missing translation key in en-US locale: "${key}"`,
    });
  }

  return violations;
};

const isQuotedLiteralExpression = (expression: string): boolean => {
  const opensWithSingleQuote = expression.startsWith("'");
  const closesWithSingleQuote = expression.endsWith("'");
  const opensWithDoubleQuote = expression.startsWith('"');
  const closesWithDoubleQuote = expression.endsWith('"');
  const opensWithBacktick = expression.startsWith("`");
  const closesWithBacktick = expression.endsWith("`");

  return (
    (opensWithSingleQuote && closesWithSingleQuote) ||
    (opensWithDoubleQuote && closesWithDoubleQuote) ||
    (opensWithBacktick && closesWithBacktick && !expression.includes("${"))
  );
};

const collectStaticAttributeViolations = (
  filePath: string,
  fileContent: string,
  block: TemplateBlock,
  tag: TemplateTag,
): Violation[] => {
  const violations: Violation[] = [];
  for (const match of tag.markup.matchAll(staticAttributePattern)) {
    const attributeName = match[1] ?? "";
    const value = (match[3] ?? match[4] ?? "").trim();
    if (value.length === 0 || !hasHumanText(value)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, block.offset + tag.offset + (match.index ?? 0)),
      message: `Static template attribute "${attributeName}" contains user-visible text. Use i18n binding (for example :${attributeName}="t('...')").`,
    });
  }
  return violations;
};

const collectBoundLiteralAttributeViolations = (
  filePath: string,
  fileContent: string,
  block: TemplateBlock,
  tag: TemplateTag,
): Violation[] => {
  const violations: Violation[] = [];
  for (const match of tag.markup.matchAll(boundAttributeLiteralPattern)) {
    const attributeName = match[1] ?? "";
    const expression = (match[3] ?? match[4] ?? "").trim();
    if (expression.length < 2 || !isQuotedLiteralExpression(expression)) {
      continue;
    }

    const literalValue = expression.slice(1, -1).trim();
    if (literalValue.length === 0 || !hasHumanText(literalValue)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, block.offset + tag.offset + (match.index ?? 0)),
      message:
        `Bound template attribute "${attributeName}" uses a literal string expression. ` +
        `Use i18n binding (for example :${attributeName}="t('...')").`,
    });
  }
  return violations;
};

const collectAttributeViolations = (
  filePath: string,
  fileContent: string,
  block: TemplateBlock,
  tag: TemplateTag,
): Violation[] => [
  ...collectStaticAttributeViolations(filePath, fileContent, block, tag),
  ...collectBoundLiteralAttributeViolations(filePath, fileContent, block, tag),
];

const collectTextViolations = (
  filePath: string,
  fileContent: string,
  block: TemplateBlock,
): Violation[] => {
  const violations: Violation[] = [];
  for (const segment of collectTemplateTextSegments(block.content)) {
    const normalizedText = normalizeTemplateText(segment.text);
    if (isIgnoredTemplateText(normalizedText) || !hasHumanText(normalizedText)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, block.offset + segment.offset),
      message: `Static template text "${normalizedText}" detected. Use translation keys with t('...') for user-visible copy.`,
    });
  }
  return violations;
};

const collectStaticTemplateViolations = (filePath: string, fileContent: string): Violation[] =>
  extractTemplateBlocks(fileContent).flatMap((block) => {
    const attributeViolations = collectTemplateTags(block.content).flatMap((tag) =>
      collectAttributeViolations(filePath, fileContent, block, tag),
    );
    const textViolations = collectTextViolations(filePath, fileContent, block);
    return [...attributeViolations, ...textViolations];
  });

const collectViolations = async (): Promise<Violation[]> => {
  const localeKeys = collectLocalePaths(enUS);
  const files = await collectSourceFiles();
  const violationGroups = await Promise.all(
    files.map(async (filePath) => {
      const fileContent = await Bun.file(filePath).text();
      const fileViolations = collectMissingTranslationKeyViolations(
        filePath,
        fileContent,
        localeKeys,
      );
      if (filePath.endsWith(".vue")) {
        fileViolations.push(...collectStaticTemplateViolations(filePath, fileContent));
        fileViolations.push(...collectLocalizedDomainOutputViolations(filePath, fileContent));
      }
      return fileViolations;
    }),
  );

  return violationGroups.flat();
};

const main = async (): Promise<void> => {
  const violations = await collectViolations();

  if (violations.length === 0) {
    await writeOutput(
      "UI i18n validation passed: no missing translation keys or static UI text/attributes detected.",
    );
    return;
  }

  await writeError(
    "UI i18n validation failed. Replace static user-visible copy with i18n keys and ensure all keys exist in en-US locale:",
  );
  const lines = violations.map(
    (violation) => `- ${violation.filePath}:${violation.line} ${violation.message}`,
  );
  if (lines.length > 0) {
    await writeError(lines.join("\n"));
  }
  process.exit(1);
};

await main();

