<template>
  <ResponsiveDataSurface>
    <template #cards><div>card</div></template>
    <template #table>
      <table class="table table-zebra"><tbody><tr><td>x</td></tr></tbody></table>
    </template>
  </ResponsiveDataSurface>
</template>`,
    );
    expect(violations).toHaveLength(0);
  });
});

import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const NUM_3 = 3;

/**
 * Data surface primitives gate (design.md §5, §11).
 *
 * Paginated / list / table surfaces must consume canonical primitives:
 *   - Pagination: <AppPagination> from components/ui/AppPagination.vue
 *     (never hand-rolled `<button>` page arrays)
 *   - Tables: must use the daisyUI table primitive (class="table") and
 *     be wrapped in an overflow-x-auto container for mobile
 *   - Empty states in data surfaces: must consume <EmptyState> primitive
 *
 * This catches the bespoke-pagination / raw-table smell that the existing
 * `validate-ui-canonical-primitives.ts` partially covers but misses:
 *   - hand-rolled `v-for` pagination buttons
 *   - tables without horizontal scroll containers
 *   - list/grid surfaces that model emptiness without EmptyState
 */

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue"]);

const SSOT_ALLOWLIST_PATHS = new Set<string>([
  "packages/client/components/ui/AppPagination.vue",
  "packages/client/components/ui/EmptyState.vue",
  "packages/client/components/ui/LoadingSkeleton.vue",
  "packages/client/components/ui/PageScaffold.vue",
  "packages/client/components/ui/SectionGrid.vue",
  "packages/client/components/ui/WorkPipeline.vue",
  "packages/client/components/ui/StatsRow.vue",
  "packages/client/components/ui/ResponsiveDataSurface.vue",
]);

const isSsotPrimitive = (filePath: string): boolean => SSOT_ALLOWLIST_PATHS.has(filePath);

// Hand-rolled pagination: a v-for that emits page numbers.
const handRolledPaginationPattern =
  /v-for\s*=\s*["'](?:page|pageNumber|pageNum|item|n)\s+in\s+(?:pageRange|pages|totalPages|pageNumbers|numberRange)\b/gu;
// Raw <button> with page-like aria-label or text.
const pageButtonPattern =
  /<button[^>]*\b(?:aria-label|title)\s*=\s*["'][^"']*(?:page|previous|next)[^"']*["']/gu;
// <table> without a class="table" (already in canonical-primitives, but also
// enforce overflow-x-auto scroll container presence).
const rawTablePattern = /<table\b[^>]*>/gu;
// A table element with class="table" but no ancestor overflow-x-auto scroll container.
const tableWithoutOverflowScrollPattern =
  /<table\b[^>]*class\s*=\s*["'][^"']*\btable\b[^"']*["'][^>]*>/u;

// Hoisted: AppPagination primitive reference detection.
const APP_PAGINATION_TAG_PATTERN = /<AppPagination\b/u;
// Hoisted: daisyUI table class detection inside a raw <table> tag.
const TABLE_BASE_CLASS_PATTERN = /\bclass\s*=\s*["'][^"']*\btable\b[^"']*["']/u;
// Hoisted: overflow-x-auto / overflow-x-scroll containment detection.
const OVERFLOW_X_SCROLL_PATTERN = /\boverflow-x-(?:auto|scroll)\b/u;
// Wide zebra tables (not table-sm) must ship a mobile card surface — not scroll-trap @320.
const WIDE_ZEBRA_TABLE_PATTERN =
  /<table\b[^>]*class\s*=\s*["'][^"']*\btable-zebra\b[^"']*["'][^>]*>/u;
const TABLE_SM_IN_TAG_PATTERN = /\btable-sm\b/u;
const RESPONSIVE_DATA_SURFACE_PATTERN = /<ResponsiveDataSurface\b/u;
const DUAL_SURFACE_TOKEN_PATTERN =
  /VISIBILITY_SHOW_BELOW_LG_CLASS[\s\S]*VISIBILITY_HIDE_BELOW_LG_CLASS|VISIBILITY_HIDE_BELOW_LG_CLASS[\s\S]*VISIBILITY_SHOW_BELOW_LG_CLASS/u;
const LEGACY_MD_DUAL_SURFACE_PATTERN =
  /\b(?:hidden\s+md:block|md:block\b[\s\S]*\bmd:hidden|md:hidden\b[\s\S]*\b(?:hidden\s+)?md:block)/u;

const extractTemplateBlocks = (content: string): string => {
  const templateStart = content.indexOf("<template>");
  if (templateStart < 0) return "";
  const templateEnd = content.lastIndexOf("</template>");
  if (templateEnd <= templateStart) return content.slice(templateStart);
  return content.slice(templateStart, templateEnd + "</template>".length);
};

const collectPaginationViolations = (filePath: string, content: string): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  const template = extractTemplateBlocks(content);
  if (template.length === 0) return [];
  const violations: ValidationViolation[] = [];

  const usesAppPagination = APP_PAGINATION_TAG_PATTERN.test(template);

  handRolledPaginationPattern.lastIndex = 0;
  for (const match of template.matchAll(handRolledPaginationPattern)) {
    if (usesAppPagination) continue;
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Hand-rolled pagination ("${match[0]}") bypasses the AppPagination primitive. Import AppPagination from ~/components/ui/AppPagination.vue and consume it.`,
    });
  }

  pageButtonPattern.lastIndex = 0;
  for (const match of template.matchAll(pageButtonPattern)) {
    if (usesAppPagination) continue;
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Hand-rolled page/prev/next button bypasses AppPagination. Consume the canonical pagination primitive.`,
    });
  }

  return violations;
};

const hasTableDualSurface = (content: string, template: string): boolean =>
  RESPONSIVE_DATA_SURFACE_PATTERN.test(content) ||
  DUAL_SURFACE_TOKEN_PATTERN.test(content) ||
  LEGACY_MD_DUAL_SURFACE_PATTERN.test(template);

const collectRawTableClassViolations = (
  filePath: string,
  content: string,
  template: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  rawTablePattern.lastIndex = 0;
  for (const match of template.matchAll(rawTablePattern)) {
    if (TABLE_BASE_CLASS_PATTERN.test(match[0])) continue;
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Raw <table> without class="table". Opt into the daisyUI table primitive.`,
    });
  }
  return violations;
};

const collectTableOverflowViolations = (
  filePath: string,
  content: string,
  template: string,
): ValidationViolation[] => {
  if (!tableWithoutOverflowScrollPattern.test(template)) return [];
  if (OVERFLOW_X_SCROLL_PATTERN.test(template) || RESPONSIVE_DATA_SURFACE_PATTERN.test(template)) {
    return [];
  }
  return [
    {
      filePath,
      line: getLineFromOffset(content, template.indexOf("<table") ?? 0),
      message: `<table class="table"> without an overflow-x-auto scroll container ancestor. Tables overflow on mobile without horizontal scroll containment.`,
    },
  ];
};

const collectWideZebraViolations = (
  filePath: string,
  content: string,
  template: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  WIDE_ZEBRA_TABLE_PATTERN.lastIndex = 0;
  for (const match of template.matchAll(new RegExp(WIDE_ZEBRA_TABLE_PATTERN.source, "gu"))) {
    const tableTag = match[0] ?? "";
    if (TABLE_SM_IN_TAG_PATTERN.test(tableTag)) continue;
    if (hasTableDualSurface(content, template)) continue;
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Wide table-zebra without mobile card dual-surface. Wrap with <ResponsiveDataSurface> (cards + table slots) or VISIBILITY_SHOW_BELOW_LG_CLASS / VISIBILITY_HIDE_BELOW_LG_CLASS so @320 is not a horizontal UUID scroll trap.`,
    });
  }
  return violations;
};

const collectMultiColumnTableViolations = (
  filePath: string,
  content: string,
  template: string,
): ValidationViolation[] => {
  const thCount = (template.match(/<th\b/gu) ?? []).length;
  if (thCount < NUM_3) return [];
  if (!tableWithoutOverflowScrollPattern.test(template)) return [];
  if (RESPONSIVE_DATA_SURFACE_PATTERN.test(content) || DUAL_SURFACE_TOKEN_PATTERN.test(content)) {
    return [];
  }
  return [
    {
      filePath,
      line: getLineFromOffset(content, template.indexOf("<table") ?? 0),
      message: `Multi-column table (${thCount} <th>) uses overflow-only escape. Wrap with <ResponsiveDataSurface> so mobile gets a card stack, not a horizontal scroll trap.`,
    },
  ];
};

const collectTableViolations = (filePath: string, content: string): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  const template = extractTemplateBlocks(content);
  if (template.length === 0) return [];
  return [
    ...collectRawTableClassViolations(filePath, content, template),
    ...collectTableOverflowViolations(filePath, content, template),
    ...collectWideZebraViolations(filePath, content, template),
    ...collectMultiColumnTableViolations(filePath, content, template),
  ];
};

export const collectPaginationTableViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => [
  ...collectPaginationViolations(filePath, content),
  ...collectTableViolations(filePath, content),
];

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions: sourceExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectPaginationTableViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "UI pagination/table validation failed:",
    await collectViolations(),
    "UI pagination/table validation passed.",
  );
}

import { describe, expect, test } from "bun:test";
import { collectResponsiveOverflowViolationsForContent } from "./validate-ui-responsive-overflow";

const CONSUMER_PATH = "packages/client/components/dashboard/ExampleWidget.vue";
const SSOT_LAYOUT_PATH = "packages/client/constants/layout.ts";

describe("collectResponsiveOverflowViolationsForContent", () => {
  test("flags fixed width w-64 without min-w-0 or max-w guard", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="flex w-64"></div></template>',
    );
    expect(violations.some((v) => v.message.includes("w-64"))).toBe(true);
  });

  test("allows w-64 with min-w-0 guard", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="flex w-64 min-w-0"></div></template>',
    );
    expect(violations).toHaveLength(0);
  });

  test("allows w-full", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="w-full"></div></template>',
    );
    expect(violations).toHaveLength(0);
  });

  test("flags fixed height h-64 on content block", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="h-64"></div></template>',
    );
    expect(violations.some((v) => v.message.includes("h-64"))).toBe(true);
  });

  test("flags grid-cols-4 without responsive guard", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="grid grid-cols-4"></div></template>',
    );
    expect(violations.some((v) => v.message.includes("grid-cols-4"))).toBe(true);
  });

  test("allows grid-cols-1 sm:grid-cols-4", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="grid grid-cols-1 sm:grid-cols-4"></div></template>',
    );
    expect(violations).toHaveLength(0);
  });

  test("allows SSOT layout constants to define fixed widths", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      SSOT_LAYOUT_PATH,
      'export const X = "lg:w-64 shrink-0";',
    );
    expect(violations).toHaveLength(0);
  });
});

import { isControlPrimitiveOwner } from "./ui-control-primitive-owners";
import { isUiSsotAuthority } from "./ui-ssot-authority";
import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const NUM_4 = 4;
const NUM_52 = 52;

/**
 * Responsive overflow + fluidity gate (design.md §11, §8).
 *
 * Components must not run off-screen or overshoot boundaries. This gate
 * catches the most common overflow risks:
 *   1. Fixed width utilities (`w-64`, `w-96`) without a `min-w-0` or
 *      `max-w-*` guard inside a flex/grid parent that needs to shrink.
 *   2. `overflow-x-auto` / `overflow-scroll` without an explicit
 *      `min-w-0` child — the canonical Bao pattern for truncation.
 *   3. Fixed height utilities on content blocks (`h-64`, `h-96`) that
 *      clip content on short viewports; prefer `min-h-*`.
 *   4. Grids with a fixed column count that don't collapse (`grid-cols-4`
 *      without responsive `sm:`/`md:` guards is a mobile-cramp risk).
 *
 * Allowed SSOT forms: constants/layout.ts, constants/ui-layout.ts, main.css.
 */

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue", ".ts", ".css"]);

const isSsotSourceFile = (filePath: string): boolean =>
  isUiSsotAuthority(filePath) || isControlPrimitiveOwner(filePath);

// Fixed width like w-64, w-96, w-[320px] (but not w-full, w-auto, w-fit, w-screen).
// Use a negative lookbehind for `-` so we don't match `min-w-64` / `max-w-64`.
const fixedWidthPattern = /(?<![-\w])w-(?:\d{2,4}|\[[^\]]+\])(?!\s*\/)/gu;
// Fixed height like h-64, h-96 (but not h-full, h-auto, h-fit, h-screen).
// Use a negative lookbehind for `-` so we don't match `min-h-64` / `max-h-64`.
const fixedHeightPattern = /(?<![-\w])h-(?:\d{2,4}|\[[^\]]+\])(?!\s*\/)/gu;
// Grid with fixed columns and no responsive guard on the same class string.
const fixedGridColsPattern = /\bgrid-cols-(?:[2-9]|1\d)(?![\d-])/gu;

// Threshold below which w-/h- literals are icon/avatar primitives, not overflow risks.
const SMALL_SIZE_THRESHOLD = 17; // w-16 / h-16 and below are primitives.

// Hoisted: class-attribute extraction (captures the inner class string in group 1).
const CLASS_ATTR_PATTERN = /\bclass\s*=\s*["']([^"']+)["']/gu;
// Hoisted: digit extraction from a w-/h- literal like `w-64` or `w-[320px]`.
const DIGITS_ONLY_PATTERN = /\D/gu;
// Hoisted: min-w-0 OR max-w-* guard detection.
const WIDTH_GUARD_PATTERN = /\bmin-w-0\b|\bmax-w-/u;
// Hoisted: max-w-* (any width cap) detection — used as a separate isFluidCap signal.
const MAX_W_CAP_PATTERN = /\bmax-w-/u;
// Hoisted: vertical overflow guard detection (hidden / y-auto / y-scroll / auto).
const VERTICAL_OVERFLOW_GUARD_PATTERN = /\boverflow-(?:hidden|y-auto|y-scroll|auto)\b/u;
// Hoisted: skeleton-row class detection.
const SKELETON_CLASS_PATTERN = /\bskeleton\b/u;
// Hoisted: arbitrary w-N class detection (sibling w- matching aspect-ratio primitives).
const W_ARBITRARY_PATTERN = /\bw-\d+\b/u;
// Hoisted: responsive sm:/md:/lg:/xl: grid-cols- guard detection.
const RESPONSIVE_GRID_COLS_PATTERN = /\b(?:sm|md|lg|xl):grid-cols-/u;

const extractTemplateBlocks = (content: string): string => {
  const templateStart = content.indexOf("<template>");
  if (templateStart < 0) return "";
  const templateEnd = content.lastIndexOf("</template>");
  if (templateEnd <= templateStart) return content.slice(templateStart);
  return content.slice(templateStart, templateEnd + "</template>".length);
};

const collectFixedWidthHits = (
  filePath: string,
  classValue: string,
  baseLine: number,
): ValidationViolation[] => {
  fixedWidthPattern.lastIndex = 0;
  const fixedWidthMatch = classValue.match(fixedWidthPattern);
  if (!fixedWidthMatch) return [];
  const widthValue = Number.parseInt(fixedWidthMatch[0].replace(DIGITS_ONLY_PATTERN, ""), 10);
  const isSmallPrimitive = Number.isFinite(widthValue) && widthValue <= NUM_52;
  const hasGuard = WIDTH_GUARD_PATTERN.test(classValue);
  const isFluidCap = MAX_W_CAP_PATTERN.test(classValue);
  if (isSmallPrimitive || hasGuard || isFluidCap) return [];
  return [
    {
      filePath,
      line: baseLine,
      message: `Fixed width "${fixedWidthMatch[0]}" risks horizontal overflow without min-w-0 or max-w-* guard. Use the SSOT SHELL_MAIN_INNER_CLASS / PAGE_HERO_ASIDE_CLASS pattern or wrap in min-w-0.`,
    },
  ];
};

const collectFixedHeightHits = (
  filePath: string,
  classValue: string,
  baseLine: number,
): ValidationViolation[] => {
  fixedHeightPattern.lastIndex = 0;
  const fixedHeightMatch = classValue.match(fixedHeightPattern);
  if (!fixedHeightMatch) return [];
  const heightValue = Number.parseInt(fixedHeightMatch[0].replace(DIGITS_ONLY_PATTERN, ""), 10);
  const isSmallPrimitive = Number.isFinite(heightValue) && heightValue <= SMALL_SIZE_THRESHOLD;
  const hasOverflowGuard = VERTICAL_OVERFLOW_GUARD_PATTERN.test(classValue);
  const isSkeletonRow = SKELETON_CLASS_PATTERN.test(classValue);
  const isSquarePrimitive =
    heightValue <= SMALL_SIZE_THRESHOLD + NUM_4 && W_ARBITRARY_PATTERN.test(classValue);
  if (isSmallPrimitive || hasOverflowGuard || isSkeletonRow || isSquarePrimitive) return [];
  return [
    {
      filePath,
      line: baseLine,
      message: `Fixed height "${fixedHeightMatch[0]}" clips content on short viewports. Prefer min-h-* or add overflow-y-auto/overflow-hidden for bounded scroll, or use the glass-card container query for adaptive density.`,
    },
  ];
};

const collectFixedGridHits = (
  filePath: string,
  classValue: string,
  baseLine: number,
): ValidationViolation[] => {
  fixedGridColsPattern.lastIndex = 0;
  const fixedGridMatch = classValue.match(fixedGridColsPattern);
  if (!fixedGridMatch || RESPONSIVE_GRID_COLS_PATTERN.test(classValue)) return [];
  return [
    {
      filePath,
      line: baseLine,
      message: `Fixed grid columns "${fixedGridMatch[0]}" without responsive sm:/md: guard cramps mobile. Use grid-cols-1 sm:grid-cols-2 md:grid-cols-N or the SectionGrid primitive.`,
    },
  ];
};

const collectOverflowViolations = (filePath: string, content: string): ValidationViolation[] => {
  if (isSsotSourceFile(filePath)) return [];
  const template = extractTemplateBlocks(content);
  if (template.length === 0) return [];
  const violations: ValidationViolation[] = [];

  CLASS_ATTR_PATTERN.lastIndex = 0;
  for (const classMatch of template.matchAll(CLASS_ATTR_PATTERN)) {
    const classValue = classMatch[1] ?? "";
    const baseLine = getLineFromOffset(content, classMatch.index ?? 0);
    violations.push(
      ...collectFixedWidthHits(filePath, classValue, baseLine),
      ...collectFixedHeightHits(filePath, classValue, baseLine),
      ...collectFixedGridHits(filePath, classValue, baseLine),
    );
  }

  return violations;
};

export const collectResponsiveOverflowViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => collectOverflowViolations(filePath, content);

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions: sourceExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectResponsiveOverflowViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "UI responsive overflow validation failed:",
    await collectViolations(),
    "UI responsive overflow validation passed.",
  );
}

import { writeError, writeOutput } from "./utils/cli-output";
import { getLineFromOffset, shouldIgnorePath } from "./utils/validation-helpers";

const NUM_120 = 120;
const NUM_160 = 160;

type Violation = {
  filePath: string;
  line: number;
  message: string;
};

const projectRoot = process.cwd();
const vueScanRoots = [
  "packages/client/pages",
  "packages/client/components",
  "packages/client/layouts",
] as const;
const bootstrapScanRoots = ["packages/client/composables"] as const;
const vueFileLimit = 310;
const styleBlockPattern = /<style\b/gu;
const lineBreakPattern = /\r?\n/u;
const settingsPanelPathPattern =
  /^packages\/client\/components\/settings\/Settings[A-Za-z0-9]+Panel\.vue$/u;
const settingsPanelHeaderUsagePattern = /<SettingsPanelHeader\b/u;
const brittleSettingsHeaderPattern =
  /\bclass\s*=\s*["']flex items-center justify-between gap-3["']/gu;
const settingsBootstrapFilePattern =
  /^packages\/client\/composables\/(?:.*bootstrap.*|settings-page\/runtime\.ts)$/u;
const settingsFetchCallPattern = /\b(?:[A-Za-z0-9_$]+\.)?fetchSettings\(\)/gu;
const settingsFetchGuardPatterns = [
  /if\s*\(\s*!\s*[A-Za-z0-9_$.]+\.value\s*\)/u,
  /[A-Za-z0-9_$.]+\.value\s*\?\s*Promise\.resolve\(\)\s*:\s*(?:[A-Za-z0-9_$]+\.)?fetchSettings\(\)/u,
] as const;

const collectFiles = async (roots: readonly string[], pattern: string): Promise<string[]> => {
  const fileGroups = await Promise.all(
    roots.map(async (root) => {
      const glob = new Bun.Glob(`${root}/**/${pattern}`);
      return Array.fromAsync(glob.scan({ cwd: projectRoot, onlyFiles: true }));
    }),
  );

  return fileGroups
    .flat()
    .map((filePath) => filePath.replace(/\\/gu, "/"))
    .filter((filePath) => !shouldIgnorePath(filePath));
};

const createViolation = (filePath: string, line: number, message: string): Violation => ({
  filePath,
  line,
  message,
});

const collectStyleBlockViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];
  styleBlockPattern.lastIndex = 0;
  for (const match of fileContent.matchAll(styleBlockPattern)) {
    violations.push(
      createViolation(
        filePath,
        getLineFromOffset(fileContent, match.index ?? 0),
        "Vue SFC <style> blocks are forbidden. Use shared daisyUI/Tailwind tokens or centralized CSS.",
      ),
    );
  }
  return violations;
};

const collectVueLineCountViolations = (filePath: string, fileContent: string): Violation[] => {
  const lineCount = fileContent.split(lineBreakPattern).length;
  if (lineCount <= vueFileLimit) {
    return [];
  }

  return [
    createViolation(
      filePath,
      1,
      `Vue UI file exceeds ${vueFileLimit} lines. Break the monolith into focused components/composables.`,
    ),
  ];
};

const collectSettingsPanelViolations = (filePath: string, fileContent: string): Violation[] => {
  if (!settingsPanelPathPattern.test(filePath)) {
    return [];
  }

  const violations: Violation[] = [];
  if (!settingsPanelHeaderUsagePattern.test(fileContent)) {
    violations.push(
      createViolation(
        filePath,
        1,
        "Settings panels must use the shared `SettingsPanelHeader` component so title, subtitle, and trailing status content stay DRY and responsive.",
      ),
    );
  }

  brittleSettingsHeaderPattern.lastIndex = 0;
  for (const match of fileContent.matchAll(brittleSettingsHeaderPattern)) {
    violations.push(
      createViolation(
        filePath,
        getLineFromOffset(fileContent, match.index ?? 0),
        "Bespoke `flex items-center justify-between gap-3` settings headers are forbidden. Use `SettingsPanelHeader` for wrapped copy and trailing badges.",
      ),
    );
  }

  return violations;
};

const hasSettingsFetchGuard = (fileContent: string, matchIndex: number): boolean => {
  const contextWindow = fileContent.slice(
    Math.max(0, matchIndex - NUM_160),
    Math.min(fileContent.length, matchIndex + NUM_120),
  );
  return settingsFetchGuardPatterns.some((pattern) => pattern.test(contextWindow));
};

const collectSettingsBootstrapViolations = (filePath: string, fileContent: string): Violation[] => {
  if (!settingsBootstrapFilePattern.test(filePath)) {
    return [];
  }

  const violations: Violation[] = [];
  settingsFetchCallPattern.lastIndex = 0;
  for (const match of fileContent.matchAll(settingsFetchCallPattern)) {
    const matchIndex = match.index ?? 0;
    if (hasSettingsFetchGuard(fileContent, matchIndex)) {
      continue;
    }

    violations.push(
      createViolation(
        filePath,
        getLineFromOffset(fileContent, matchIndex),
        "App settings bootstrap must stay single-source. Guard page/composable `fetchSettings()` calls behind a missing-state check instead of refetching during every bootstrap.",
      ),
    );
  }

  return violations;
};

const collectVueFileViolations = (filePath: string, fileContent: string): Violation[] => {
  if (!filePath.endsWith(".vue")) {
    return [];
  }

  return [
    ...collectStyleBlockViolations(filePath, fileContent),
    ...collectVueLineCountViolations(filePath, fileContent),
    ...collectSettingsPanelViolations(filePath, fileContent),
  ];
};

export const collectUiSingleSourceViolationsForContent = (
  filePath: string,
  fileContent: string,
): Violation[] => [
  ...collectVueFileViolations(filePath, fileContent),
  ...collectSettingsBootstrapViolations(filePath, fileContent),
];

const collectViolations = async (): Promise<Violation[]> => {
  const [vueFiles, bootstrapFiles] = await Promise.all([
    collectFiles(vueScanRoots, "*.vue"),
    collectFiles(bootstrapScanRoots, "*.ts"),
  ]);
  const files = [...vueFiles, ...bootstrapFiles];
  const violationGroups = await Promise.all(
    files.map(async (filePath) =>
      collectUiSingleSourceViolationsForContent(filePath, await Bun.file(filePath).text()),
    ),
  );

  return violationGroups.flat();
};

const main = async (): Promise<void> => {
  const violations = await collectViolations();
  if (violations.length === 0) {
    await writeOutput("UI single-source-of-truth validation passed.");
    return;
  }

  await writeError(
    "UI single-source-of-truth validation failed. Break monoliths and move custom styles into shared tokens:",
  );
  const lines = violations.map(
    (violation) => `- ${violation.filePath}:${violation.line} ${violation.message}`,
  );
  if (lines.length > 0) {
    await writeError(lines.join("\n"));
  }

  process.exit(1);
};

if (import.meta.main) {
  await main();
}

