  condition: () => Promise<boolean>,
  timeoutMessage: string,
  deadline: number = Date.now() + READY_TIMEOUT_MS,
): Promise<void> => {
  if (await condition()) {
    return;
  }

  if (Date.now() >= deadline) {
    throw new Error(timeoutMessage);
  }

  await Bun.sleep(POLL_INTERVAL_MS);
  await waitForCondition(condition, timeoutMessage, deadline);
};

const waitForService = async (url: string): Promise<void> => {
  await waitForCondition(() => isServiceReady(url), `Timed out waiting for ${url}`);
};

const requestJson = async <T>(
  path: string,
  init: RequestInit = {},
): Promise<{ status: number; body: T }> => {
  const response = await fetch(`${VERIFY_API_BASE}${path}`, {
    ...init,
    headers: {
      ...(init.body ? { "content-type": "application/json" } : {}),
      ...(init.headers ?? {}),
    },
    signal:
      init.signal ??
      AbortSignal.timeout(init.body ? RUN_COMPLETION_TIMEOUT_MS : POLL_INTERVAL_MS * NUM_8),
  });
  const rawBody = await response.text();
  if (rawBody.trim().length === 0) {
    throw new Error(`Expected JSON response body for ${path}, received an empty payload.`);
  }

  return {
    status: response.status,
    body: JSON.parse(rawBody) as T,
  };
};

const normalizePathname = (pathname: string): string =>
  pathname.replace(LEADING_PATHNAME_SLASH_PATTERN, "").replace(TRAILING_PATHNAME_SLASH_PATTERN, "");

const fileExists = async (filePath: string): Promise<boolean> =>
  stat(filePath).then(
    () => true,
    () => false,
  );

const findFirstMissingPath = async (candidatePaths: readonly string[]): Promise<string | null> => {
  const existenceChecks = await Promise.all(
    candidatePaths.map((candidatePath) => fileExists(candidatePath)),
  );
  const missingIndex = existenceChecks.findIndex((exists) => !exists);
  return missingIndex === -1 ? null : (candidatePaths[missingIndex] ?? null);
};

const hasAutomationCapabilities = (
  payload: unknown,
): payload is {
  capabilities: unknown[];
} =>
  isRecord(payload) &&
  "capabilities" in payload &&
  Array.isArray(payload.capabilities) &&
  payload.capabilities.length > 0;

const hasRunEnvelope = (payload: unknown): payload is RpaRunExecutionEnvelope =>
  isRecord(payload) && typeof payload.id === "string" && typeof payload.status === "string";

const hasAutomationVerifyContext = (payload: unknown): payload is AutomationVerifyContext =>
  isRecord(payload) && typeof payload.resumeId === "string" && payload.resumeId.trim().length > 0;

const createVerificationRuntimePaths = async (): Promise<VerificationRuntimePaths> => {
  const root = await mkdtemp(join(tmpdir(), "bao-desktop-verify-runtime-"));
  return {
    root,
    dbPath: join(root, "bao-desktop-verify.db"),
  };
};

const configureVerificationSettings = async (): Promise<void> => {
  const response = await requestJson<Record<string, unknown>>(API_ENDPOINTS.settings, {
    method: "PUT",
    body: JSON.stringify({
      automationSettings: {
        enableSmartSelectors: false,
      },
    }),
  });

  if (response.status !== HTTP_STATUS_OK) {
    throw new Error(`Failed to configure verification settings (status ${response.status})`);
  }
};

const readAutomationVerifyContext = async (): Promise<AutomationVerifyContext> => {
  const response = await requestJson<unknown>(API_ENDPOINTS.automationVerifyContext);
  if (response.status !== HTTP_STATUS_OK || !hasAutomationVerifyContext(response.body)) {
    throw new Error(`Failed to read automation verification context (status ${response.status})`);
  }

  return {
    resumeId: response.body.resumeId.trim(),
  };
};

const readAutomationRun = async (runId: string): Promise<RpaRunExecutionEnvelope> => {
  const response = await requestJson<RpaRunExecutionEnvelope>(buildAutomationRunEndpoint(runId));
  if (response.status !== HTTP_STATUS_OK || !hasRunEnvelope(response.body)) {
    throw new Error(`Failed to read automation run ${runId}`);
  }

  return response.body;
};

const waitForAutomationRunCompletion = async (
  runId: string,
  deadline: number = Date.now() + RUN_COMPLETION_TIMEOUT_MS,
): Promise<RpaRunExecutionEnvelope> => {
  let finalRun: RpaRunExecutionEnvelope | null = null;
  await waitForCondition(
    async () => {
      const run = await readAutomationRun(runId);
      finalRun = run;
      return run.status === "success" || run.status === "error";
    },
    `Timed out waiting for automation run ${runId} to complete`,
    deadline,
  );

  if (!finalRun) {
    throw new Error(`Automation run ${runId} did not return a terminal state.`);
  }

  return finalRun;
};

const subscribeToAutomationRun = async (
  runId: string,
): Promise<{
  events: RpaRunEvent[];
  close(): void;
  waitForTerminalEvent(): Promise<RpaRunEvent>;
}> => {
  const socket = new WebSocket(`${VERIFY_WS_BASE}${WS_ENDPOINTS.automation}`);
  const events: RpaRunEvent[] = [];
  let terminalEvent: RpaRunEvent | null = null;

  await new Promise<void>((resolve, reject) => {
    const timeout = setTimeout(
      () => reject(new Error("Timed out opening automation verification websocket")),
      WEBSOCKET_OPEN_TIMEOUT_MS,
    );
    socket.onopen = () => {
      clearTimeout(timeout);
      socket.send(JSON.stringify({ type: "subscribe", runId }));
      resolve();
    };
    socket.onerror = () => {
      clearTimeout(timeout);
      reject(new Error("Automation verification websocket failed to open"));
    };
  });

  socket.onmessage = (event) => {
    const payload: unknown = JSON.parse(
      typeof event.data === "string" ? event.data : `${event.data}`,
    );
    const parsedEvent = rpaRunEventSchema.safeParse(payload);
    if (!parsedEvent.success || parsedEvent.data.runId !== runId) {
      return;
    }

    const runEvent = parsedEvent.data;
    events.push(runEvent);
    if (
      runEvent.eventType === "progress" &&
      (runEvent.status === "success" || runEvent.status === "error")
    ) {
      terminalEvent = runEvent;
    }
    if (runEvent.eventType === "result" || runEvent.eventType === "error") {
      terminalEvent = runEvent;
    }
  };

  return {
    events,
    close(): void {
      socket.close();
    },
    async waitForTerminalEvent(): Promise<RpaRunEvent> {
      await waitForCondition(
        () => Promise.resolve(terminalEvent !== null),
        `Timed out waiting for websocket completion for run ${runId}`,
        Date.now() + RUN_COMPLETION_TIMEOUT_MS,
      );
      if (!terminalEvent) {
        throw new Error(`Automation websocket for run ${runId} did not yield a terminal event.`);
      }
      return terminalEvent;
    },
  };
};

const isTerminalAutomationEvent = (event: RpaRunEvent): boolean =>
  event.eventType === "result" ||
  event.eventType === "error" ||
  (event.eventType === "progress" && (event.status === "success" || event.status === "error"));

const assertAutomationEventSequence = (runId: string, events: readonly RpaRunEvent[]): void => {
  if (events.length === 0) {
    throw new Error(`Automation run ${runId} did not emit websocket events.`);
  }

  for (let index = 1; index < events.length; index += 1) {
    const currentEvent = events[index];
    const previousEvent = events[index - 1];
    if (!(currentEvent && previousEvent)) {
      throw new Error(`Automation run ${runId} emitted an invalid websocket sequence.`);
    }
    if (currentEvent.sequence < previousEvent.sequence) {
      throw new Error(`Automation run ${runId} emitted out-of-order websocket events.`);
    }
  }
};

const assertSuccessfulRun = (runId: string, run: RpaRunExecutionEnvelope): void => {
  if (run.status !== "success") {
    throw new Error(
      `Automation run ${runId} completed with ${run.status}: ${JSON.stringify({
        error: run.error,
        output: run.output,
      })}`,
    );
  }

  if (!(run.output && isRecord(run.output) && run.output.success === true)) {
    throw new Error(`Automation run ${runId} did not persist a successful output envelope.`);
  }
};

const assertObservedTerminalEvent = (
  runId: string,
  terminalEvent: RpaRunEvent,
  events: readonly RpaRunEvent[],
): void => {
  if (!isTerminalAutomationEvent(terminalEvent)) {
    throw new Error(`Automation run ${runId} did not emit a terminal websocket event.`);
  }

  const hasRunningProgress = events.some(
    (event) => event.eventType === "progress" && event.status === "running",
  );
  if (!hasRunningProgress) {
    throw new Error(`Automation run ${runId} did not emit running progress over websocket.`);
  }
};

const createJobApplyRun = async (params: {
  jobUrl: string;
  resumeId: string;
  runAt?: string;
}): Promise<RpaRunExecutionEnvelope> => {
  const endpoint = params.runAt
    ? API_ENDPOINTS.automationJobApplySchedule
    : API_ENDPOINTS.automationJobApply;
  const response = await requestJson<RpaRunExecutionEnvelope>(endpoint, {
    method: "POST",
    body: JSON.stringify({
      jobUrl: params.jobUrl,
      resumeId: params.resumeId,
      ...(params.runAt ? { runAt: params.runAt } : {}),
    }),
  });
  if (response.status !== HTTP_STATUS_OK || !hasRunEnvelope(response.body)) {
    throw new Error(`Failed to create job-apply run via ${endpoint}.`);
  }

  return response.body;
};

const assertScraperRuntimeContract = async (manifest: DesktopRuntimeManifest): Promise<void> => {
  const scraperRuntimeRoot = join(RUNTIME_ROOT, manifest.scraperDir);
  const stagedContractPaths = SCRAPER_RUNTIME_STAGE_SOURCE_PATHS.map((relativePath) =>
    join(scraperRuntimeRoot, relativePath),
  );
  const missingContractPath = await findFirstMissingPath(stagedContractPaths);
  if (missingContractPath) {
    throw new Error(`Packaged scraper runtime is missing ${missingContractPath}`);
  }

  const runtimeDependencyRoots = await collectRuntimeDependencySourceRoots(
    join(REPO_ROOT, "packages", "scraper"),
  );
  const stagedDependencyManifestPaths = Array.from(runtimeDependencyRoots.keys(), (packageName) =>
    join(scraperRuntimeRoot, "node_modules", packageName, "package.json"),
  );
  const missingDependencyManifestPath = await findFirstMissingPath(stagedDependencyManifestPaths);
  if (missingDependencyManifestPath) {
    throw new Error(
      `Packaged scraper runtime is missing dependency manifest ${missingDependencyManifestPath}`,
    );
  }
};

const assertManifestContract = async (
  manifest: DesktopRuntimeManifest,
  tauriTarget: string | null,
): Promise<void> => {
  const expectedManifest = resolveExpectedRuntimeManifest(tauriTarget);
  const manifestMismatches = getDesktopRuntimeManifestMismatches(manifest, expectedManifest);
  if (manifestMismatches.length > 0) {
    throw new Error(`Desktop runtime manifest drift detected: ${manifestMismatches.join("; ")}`);
  }

  const runtimeDependencyRoots = await collectRuntimeDependencySourceRoots(
    join(REPO_ROOT, "packages", "scraper"),
  );
  const requiredRuntimePaths = listDesktopRuntimeContractPaths(
    manifest,
    Array.from(runtimeDependencyRoots.keys()),
  ).map((relativePath) => join(RUNTIME_ROOT, relativePath));
  const missingRuntimePath = await findFirstMissingPath(requiredRuntimePaths);
  if (missingRuntimePath) {
    throw new Error(`Packaged desktop runtime contract is missing ${missingRuntimePath}`);
  }
};

const isTextFile = (filePath: string): boolean => {
  const extension = extname(filePath).toLowerCase();
  return extension.length === 0 || TEXT_FILE_EXTENSIONS.has(extension);
};

const visitTextFiles = async (
  path: string,
  visitor: (filePath: string) => Promise<void>,
): Promise<void> => {
  const currentStat = await stat(path);
  if (currentStat.isDirectory()) {
    const entries = await readdir(path, { withFileTypes: true });
    await Promise.all(entries.map((entry) => visitTextFiles(join(path, entry.name), visitor)));
    return;
  }

  if (isTextFile(path)) {
    await visitor(path);
  }
};

const findFirstMarkerMatch = async (
  path: string,
  markers: readonly string[],
): Promise<string | null> => {
  const currentStat = await stat(path);
  if (currentStat.isDirectory()) {
    const entries = await readdir(path, { withFileTypes: true });
    const matches = await Promise.all(
      entries.map((entry) => findFirstMarkerMatch(join(path, entry.name), markers)),
    );
    return matches.find((match): match is string => typeof match === "string") ?? null;
  }

  if (!isTextFile(path)) {
    return null;
  }

  const fileText = await readFile(path, "utf8");
  return markers.some((marker) => fileText.includes(marker)) ? path : null;
};

const findLeakedBuildEndpoint = (directoryPath: string): Promise<string | null> =>
  findFirstMarkerMatch(directoryPath, [...BUILD_API_LEAK_MARKERS, ...BUILD_WS_LEAK_MARKERS]);

const rewriteTextTree = async (
  directoryPath: string,
  replacements: readonly [string, string][],
): Promise<void> => {
  await visitTextFiles(directoryPath, async (filePath) => {
    const sourceText = await readFile(filePath, "utf8");
    let nextText = sourceText;
    for (const [fromValue, toValue] of replacements) {
      nextText = nextText.replaceAll(fromValue, toValue);
    }

    if (nextText !== sourceText) {
      await writeFile(filePath, nextText, "utf8");
    }
  });
};

const createVerificationFrontendRoot = async (): Promise<string> => {
  const verificationRoot = await mkdtemp(join(tmpdir(), "bao-desktop-verify-frontend-"));
  await cp(CLIENT_PUBLIC_ROOT, verificationRoot, { recursive: true, force: true });
  await rewriteTextTree(verificationRoot, [
    [DESKTOP_RUNTIME_API_BASE, VERIFY_API_BASE],
    [DESKTOP_RUNTIME_WS_BASE, VERIFY_WS_BASE],
    [DESKTOP_RUNTIME_API_BASE.replaceAll("/", "\\/"), VERIFY_API_BASE.replaceAll("/", "\\/")],
    [DESKTOP_RUNTIME_WS_BASE.replaceAll("/", "\\/"), VERIFY_WS_BASE.replaceAll("/", "\\/")],
  ]);
  return verificationRoot;
};

const resolveStaticAssetPath = async (frontendRoot: string, pathname: string): Promise<string> => {
  const normalizedPath = normalizePathname(decodeURIComponent(pathname));
  const candidateRelativePaths =
    normalizedPath.length === 0
      ? ["index.html"]
      : [normalizedPath, join(normalizedPath, "index.html")];

  const candidateMatches = await Promise.all(
    candidateRelativePaths.map(async (relativePath) => {
      const absolutePath = resolve(frontendRoot, relativePath);
      if (!absolutePath.startsWith(frontendRoot)) {
        return null;
      }

      return (await fileExists(absolutePath)) ? absolutePath : null;
    }),
  );
  const existingCandidate = candidateMatches.find(
    (match): match is string => typeof match === "string",
  );
  if (existingCandidate) {
    return existingCandidate;
  }

  const notFoundPath = join(frontendRoot, "404.html");
  if (await fileExists(notFoundPath)) {
    return notFoundPath;
  }

  return join(frontendRoot, "index.html");
};

const startStaticFrontendServer = (frontendRoot: string): StaticServerHandle => {
  const server = Bun.serve({
    hostname: DESKTOP_RUNTIME_HOST,
    port: DESKTOP_RUNTIME_VERIFY_FRONTEND_PORT,
    fetch: async (request) => {
      const requestUrl = new URL(request.url);
      const filePath = await resolveStaticAssetPath(frontendRoot, requestUrl.pathname);
      return new Response(Bun.file(filePath));
    },
  });

  return {
    async stop(closeActiveConnections = false): Promise<void> {
      await server.stop(closeActiveConnections);
    },
  };
};

const verifyCorsContract = async (
  apiBase: string,
  manifest: DesktopRuntimeManifest,
  origin: string,
): Promise<void> => {
  const response = await fetch(`${apiBase}${API_ENDPOINTS.health}`, {
    headers: {
      origin,
    },
    signal: AbortSignal.timeout(POLL_INTERVAL_MS * NUM_4),
  });

  const allowedOrigin = response.headers.get("access-control-allow-origin");
  if (allowedOrigin !== origin) {
    throw new Error(
      `Expected desktop server CORS origin ${origin}, received ${allowedOrigin ?? "<missing>"}`,
    );
  }

  if (origin !== VERIFY_FRONTEND_ORIGIN && !manifest.corsOrigins.includes(origin)) {
    throw new Error(`Desktop runtime manifest is missing expected origin ${origin}.`);
  }
};

/**
 * Chromium args that improve headless launch reliability on Windows CI (GitHub Actions).
 *
 * Critically, `--remote-debugging-port=0` forces TCP-based debugging instead of
 * Playwright's default `--remote-debugging-pipe`. The named-pipe protocol is
 * incompatible with Bun's child process handling on Windows, causing a 120s
 * timeout even though the browser PID starts successfully.
 */
const WINDOWS_CI_CHROMIUM_ARGS: string[] = [
  "--remote-debugging-port=0",
  "--disable-gpu",
  "--disable-software-rasterizer",
  "--disable-dev-shm-usage",
  "--no-sandbox",
  "--disable-setuid-sandbox",
  "--disable-background-networking",
  "--disable-default-apps",
  "--disable-sync",
  "--disable-translate",
  "--metrics-recording-only",
  "--mute-audio",
  "--no-first-run",
];

/** Whether to use the pre-installed Microsoft Edge instead of bundled Chromium. */
const USE_WINDOWS_EDGE_CHANNEL = process.platform === "win32";

const buildLaunchOptions = (executablePath: string | null): PlaywrightLaunchOptions => {
  const launchOptions: PlaywrightLaunchOptions = {
    headless: true,
    timeout: DESKTOP_RUNTIME_VERIFY_BROWSER_LAUNCH_TIMEOUT_MS,
  };
  if (USE_WINDOWS_EDGE_CHANNEL) {
    launchOptions.channel = "msedge";
    launchOptions.args = WINDOWS_CI_CHROMIUM_ARGS;
    launchOptions.ignoreDefaultArgs = ["--remote-debugging-pipe"];
  } else if (executablePath) {
    launchOptions.executablePath = executablePath;
  }
  return launchOptions;
};

const BROWSER_LAUNCH_MAX_ATTEMPTS = process.platform === "win32" ? NUM_3 : 1;
const BROWSER_LAUNCH_RETRY_DELAY_MS = 3_000;

const attemptBrowserLaunch = async (
  chromium: PlaywrightChromium,
  executablePath: string | null,
  attempt: number,
): Promise<BrowserInstance> => {
  const result = await captureResult(() => chromium.launch(buildLaunchOptions(executablePath)));
  if (result.ok) {
    return result.value;
  }
  if (attempt >= BROWSER_LAUNCH_MAX_ATTEMPTS) {
    throw result.error;
  }
  await writeOutput(
    `desktop-runtime: browser launch attempt ${attempt}/${BROWSER_LAUNCH_MAX_ATTEMPTS} failed, retrying in ${BROWSER_LAUNCH_RETRY_DELAY_MS}ms...`,
  );
  await new Promise((resolve) => setTimeout(resolve, BROWSER_LAUNCH_RETRY_DELAY_MS));
  return attemptBrowserLaunch(chromium, executablePath, attempt + 1);
};

const launchVerificationBrowser = async (playwrightModule: {
  chromium: PlaywrightChromium;
}): Promise<BrowserInstance> => {
  if (USE_WINDOWS_EDGE_CHANNEL) {
    await writeOutput(
      "desktop-runtime: launching verification browser via pre-installed Microsoft Edge (msedge channel)",
    );
    return attemptBrowserLaunch(playwrightModule.chromium, null, 1);
  }

  const browserExecutablePath = playwrightModule.chromium.executablePath().trim();
  if (browserExecutablePath.length === 0) {
    throw new Error("Playwright did not provide a bundled Chromium executable path.");
  }

  const executableStatResult = await captureResult(() => stat(browserExecutablePath));
  if (!executableStatResult.ok) {
    throw new Error(
      `Playwright bundled Chromium executable is missing at ${browserExecutablePath}. Run bun run automation:browsers:install before verifying the packaged desktop runtime.`,
      { cause: executableStatResult.error },
    );
  }
  if (!executableStatResult.value.isFile()) {
    throw new Error(
      `Playwright bundled Chromium executable path is not a file: ${browserExecutablePath}`,
    );
  }

  await writeOutput(
    `desktop-runtime: launching verification browser from ${browserExecutablePath}`,
  );

  return attemptBrowserLaunch(playwrightModule.chromium, browserExecutablePath, 1);
};

/**
 * Verifies frontend and API health using native `fetch` + `WebSocket` instead
 * of Playwright browser automation. Used on Windows where Bun's subprocess
 * management is incompatible with Playwright's debugging protocol (both pipe
 * and TCP-based connections time out despite the browser process starting).
 */
const runNativeBrowserChecks = async (
  apiBase: string,
  wsBase: string,
  frontendUrl: string,
): Promise<BrowserCheckResult> => {
  await writeOutput("desktop-runtime: running native HTTP/WS browser checks (Playwright skipped)");

  const htmlResponse = await fetch(frontendUrl);
  if (!htmlResponse.ok) {
    throw new Error(
      `Frontend HTML fetch failed: ${htmlResponse.status} ${htmlResponse.statusText}`,
    );
  }
  const html = await htmlResponse.text();
  const titleMatch = HTML_TITLE_PATTERN.exec(html);
  const pageTitle = titleMatch?.[1]?.trim() ?? "untitled";

  const healthResponse = await fetch(`${apiBase}${API_ENDPOINTS.health}`);
  if (!healthResponse.ok) {
    throw new Error(
      `Health endpoint failed: ${healthResponse.status} ${healthResponse.statusText}`,
    );
  }
  const healthPayload: unknown = await healthResponse.json();
  const healthStatus = resolveHealthStatus(healthPayload);

  const websocketUrl = `${wsBase}${WS_ENDPOINTS.automation}`;
  const websocketOpened = await new Promise<boolean>((resolve) => {
    const timeout = setTimeout(() => resolve(false), NUM_5000);
    const socket = new WebSocket(websocketUrl);
    socket.addEventListener("open", () => {
      clearTimeout(timeout);
      socket.close();
      resolve(true);
    });
    socket.addEventListener("error", () => {
      clearTimeout(timeout);
      resolve(false);
    });
  });

  return { pageTitle, healthStatus, websocketOpened };
};

const readPlaywrightHealthStatus = async (
  page: BrowserPage,
  apiBase: string,
): Promise<BrowserCheckResult["healthStatus"]> =>
  page.evaluate(
    async ({ healthEndpoint, runtimeApiBase }) => {
      const response = await fetch(`${runtimeApiBase}${healthEndpoint}`);
      const payload: unknown = await response.json();
      if (
        typeof payload === "object" &&
        payload !== null &&
        "status" in payload &&
        typeof payload.status === "string"
      ) {
        return payload.status;
      }

      return "unknown";
    },
    {
      healthEndpoint: API_ENDPOINTS.health,
      runtimeApiBase: apiBase,
    },
  );

const readPlaywrightWebsocketStatus = async (
  page: BrowserPage,
  wsBase: string,
): Promise<BrowserCheckResult["websocketOpened"]> =>
  page.evaluate(
    async ({ automationWebsocketEndpoint, runtimeWsBase }) => {
      const targetUrl = `${runtimeWsBase}${automationWebsocketEndpoint}`;
      return new Promise<boolean>((resolve) => {
        const timeout = window.setTimeout(() => resolve(false), NUM_5000);
        const socket = new WebSocket(targetUrl);

        socket.onopen = () => {
          clearTimeout(timeout);
          socket.close();
          resolve(true);
        };
        socket.onerror = () => {
          clearTimeout(timeout);
          resolve(false);
        };
      });
    },
    {
      automationWebsocketEndpoint: WS_ENDPOINTS.automation,
      runtimeWsBase: wsBase,
    },
  );

const runPlaywrightBrowserChecks = async (
  browser: BrowserInstance,
  apiBase: string,
  wsBase: string,
): Promise<BrowserCheckResult> =>
  withCleanup(
    async () => {
      const page = await browser.newPage();
      return withCleanup(
        async () => {
          await page.goto(VERIFY_FRONTEND_URL, { waitUntil: "domcontentloaded" });
          await page.waitForLoadState("load");

          const pageTitle = await page.title();
          const healthStatus = await readPlaywrightHealthStatus(page, apiBase);
          const websocketOpened = await readPlaywrightWebsocketStatus(page, wsBase);

          return {
            pageTitle,
            healthStatus,
            websocketOpened,
          };
        },
        () => page.close(),
      );
    },
    () => browser.close(),
  );

const runBrowserChecks = async (apiBase: string, wsBase: string): Promise<BrowserCheckResult> => {
  if (USE_WINDOWS_EDGE_CHANNEL) {
    return runNativeBrowserChecks(apiBase, wsBase, VERIFY_FRONTEND_URL);
  }

  const playwrightChromium = await loadPlaywrightChromium();
  const browser = await launchVerificationBrowser({ chromium: playwrightChromium });
  return runPlaywrightBrowserChecks(browser, apiBase, wsBase);
};

const assertAutomationEndpoints = async (apiBase: string): Promise<void> => {
  const capabilitiesResponse = await fetch(`${apiBase}/automation/capabilities`);
  if (!capabilitiesResponse.ok) {
    throw new Error(
      `Automation capabilities endpoint failed: ${capabilitiesResponse.status} ${capabilitiesResponse.statusText}`,
    );
  }
  const capabilitiesPayload: unknown = await capabilitiesResponse.json();
  if (!hasAutomationCapabilities(capabilitiesPayload)) {
    throw new Error("Automation capabilities payload missing required entries.");
  }

  const runsResponse = await fetch(`${apiBase}/automation/runs?limit=1`);
  if (!runsResponse.ok) {
    throw new Error(`Automation runs endpoint failed: ${runsResponse.status}`);
  }
};

const verifyAutomationRun = async (
  runId: string,
  subscription: Awaited<ReturnType<typeof subscribeToAutomationRun>>,
): Promise<void> => {
  await withCleanup(
    async () => {
      const terminalEvent = await subscription.waitForTerminalEvent();
      const completedRun = await waitForAutomationRunCompletion(runId);
      assertAutomationEventSequence(runId, subscription.events);
      assertObservedTerminalEvent(runId, terminalEvent, subscription.events);
      assertSuccessfulRun(runId, completedRun);
    },
    () => {
      subscription.close();
    },
  );
};

const verifyCompletedAutomationRun = async (runId: string): Promise<void> => {
  const completedRun = await waitForAutomationRunCompletion(runId);
  assertSuccessfulRun(runId, completedRun);
};

const verifyManualJobApplyRun = async (resumeId: string, fixtureBaseUrl: string): Promise<void> => {
  const run = await createJobApplyRun({
    jobUrl: fixtureBaseUrl,
    resumeId,
  });
  await verifyCompletedAutomationRun(run.id);
};

const verifyScheduledJobApplyRun = async (
  resumeId: string,
  fixtureBaseUrl: string,
): Promise<void> => {
  const runAt = new Date(Date.now() + SCHEDULE_RUN_LEAD_TIME_MS).toISOString();
  const run = await createJobApplyRun({
    jobUrl: fixtureBaseUrl,
    resumeId,
    runAt,
  });
  const subscription = await subscribeToAutomationRun(run.id);
  await verifyAutomationRun(run.id, subscription);
};

const verifyScheduledRunRecovery = async (
  resumeId: string,
  fixtureBaseUrl: string,
  restartServer: () => Promise<void>,
): Promise<void> => {
  const runAt = new Date(Date.now() + SCHEDULE_RECOVERY_LEAD_TIME_MS).toISOString();
  const run = await createJobApplyRun({
    jobUrl: fixtureBaseUrl,
    resumeId,
    runAt,
  });

  await Bun.sleep(AUTOMATION_RESTART_SETTLE_MS);
  await restartServer();

  const subscription = await subscribeToAutomationRun(run.id);
  await verifyAutomationRun(run.id, subscription);
};

const startPackagedServer = async (
  manifest: DesktopRuntimeManifest,
  runtimePaths: VerificationRuntimePaths,
): Promise<ReturnType<typeof Bun.spawn>> => {
  const serverExecutablePath = join(RUNTIME_ROOT, manifest.serverExecutable);
  const scriptRunnerPath = join(RUNTIME_ROOT, manifest.scriptRunnerExecutable);
  const scriptRunnerEntrypointPath = manifest.scriptRunnerEntrypoint
    ? join(RUNTIME_ROOT, manifest.scriptRunnerEntrypoint)
    : null;
  const scraperDirPath = join(RUNTIME_ROOT, manifest.scraperDir);

  if (!(await fileExists(scriptRunnerPath))) {
    throw new Error(`Packaged desktop script runner is missing ${scriptRunnerPath}`);
  }
  if (scriptRunnerEntrypointPath && !(await fileExists(scriptRunnerEntrypointPath))) {
    throw new Error(
      `Packaged desktop script runner entrypoint is missing ${scriptRunnerEntrypointPath}`,
    );
  }

  const overrideCorsOrigins = Array.from(
    new Set([...manifest.corsOrigins, VERIFY_FRONTEND_ORIGIN]),
  ).join(",");

  const proc = Bun.spawn([serverExecutablePath], {
    cwd: RUNTIME_ROOT,
    env: {
      ...process.env,
      BAO_ALLOW_AUTOMATION_PRIVATE_HOSTS: "true",
      BAO_DISABLE_AUTH: "true",
      BAO_ENABLE_AUTOMATION_VERIFY: "true",
      BAO_SCRAPER_DIR: scraperDirPath,
      BAO_SCRIPT_RUNNER_PATH: scriptRunnerPath,
      BAO_SCRIPT_RUNNER_ENTRYPOINT_PATH: scriptRunnerEntrypointPath ?? undefined,
      CORS_ORIGINS: overrideCorsOrigins,
      DB_PATH: runtimePaths.dbPath,
      HOST: manifest.serverHost,
      NODE_ENV: "production",
      PORT: `${DESKTOP_RUNTIME_VERIFY_SERVER_PORT}`,
    },
    stdin: "ignore",
    stdout: "inherit",
    stderr: "inherit",
  });

  await waitForService(`${VERIFY_API_BASE}${API_ENDPOINTS.health}`);
  return proc;
};

const stopProcess = async (proc: ReturnType<typeof Bun.spawn>): Promise<void> => {
  proc.kill();
  const [result] = await Promise.allSettled([proc.exited]);
  if (result.status === "rejected") {
    throw new Error("Failed waiting for the desktop runtime server to exit cleanly.", {
      cause: result.reason,
    });
  }
};

const assertGeneratedFrontendIsReady = async (manifest: DesktopRuntimeManifest): Promise<void> => {
  await ensureStaticFrontendEntrypoint(CLIENT_PUBLIC_ROOT);

  const leakedBuildFile = await findLeakedBuildEndpoint(CLIENT_PUBLIC_ROOT);
  if (leakedBuildFile) {
    throw new Error(`Temporary build endpoint leaked into generated frontend: ${leakedBuildFile}`);
  }

  if (!manifest.corsOrigins.includes(DESKTOP_RUNTIME_CORS_ORIGINS[0])) {
    throw new Error("Desktop runtime manifest is missing the primary packaged CORS origin.");
  }

  await assertScraperRuntimeContract(manifest);
};

const prepareVerificationFrontendRoot = async (
  manifest: DesktopRuntimeManifest,
): Promise<string> => {
  await assertGeneratedFrontendIsReady(manifest);
  const verificationFrontendRoot = await createVerificationFrontendRoot();
  const leakedProductionRuntimeFile = await findFirstMarkerMatch(verificationFrontendRoot, [
    DESKTOP_RUNTIME_API_BASE,
    DESKTOP_RUNTIME_WS_BASE,
    DESKTOP_RUNTIME_API_BASE.replaceAll("/", "\\/"),
    DESKTOP_RUNTIME_WS_BASE.replaceAll("/", "\\/"),
  ]);
  if (leakedProductionRuntimeFile) {
    throw new Error(
      `Verification frontend still references the packaged runtime default endpoints: ${leakedProductionRuntimeFile}`,
    );
  }

  return verificationFrontendRoot;
};

const assertBrowserChecksPassed = (browserResult: BrowserCheckResult): void => {
  if (browserResult.pageTitle.trim().length === 0) {
    throw new Error("Generated desktop frontend did not expose a document title.");
  }
  if (browserResult.healthStatus !== "healthy" && browserResult.healthStatus !== "degraded") {
    throw new Error(
      `Unexpected desktop API health status from browser: ${browserResult.healthStatus}`,
    );
  }
  if (!browserResult.websocketOpened) {
    throw new Error("Desktop automation WebSocket did not open from the generated frontend.");
  }
};

const runPackagedRuntimeChecks = async (
  manifest: DesktopRuntimeManifest,
  verificationFrontendRoot: string,
  fixtureBaseUrl: string,
  restartServer: () => Promise<void>,
): Promise<void> => {
  const staticServer = startStaticFrontendServer(verificationFrontendRoot);
  await withCleanup(
    async () => {
      await verifyCorsContract(VERIFY_API_BASE, manifest, DESKTOP_RUNTIME_CORS_ORIGINS[0]);
      await verifyCorsContract(VERIFY_API_BASE, manifest, VERIFY_FRONTEND_ORIGIN);
      await assertAutomationEndpoints(`${VERIFY_API_BASE}${API_ENDPOINT_PREFIX}`);
      const browserResult = await runBrowserChecks(VERIFY_API_BASE, VERIFY_WS_BASE);
      assertBrowserChecksPassed(browserResult);
      await configureVerificationSettings();
      await writeOutput(
        "desktop-runtime: configured deterministic automation verification settings",
      );

      const { resumeId } = await readAutomationVerifyContext();
      await writeOutput("desktop-runtime: verifying packaged manual automation run");
      await verifyManualJobApplyRun(resumeId, fixtureBaseUrl);

      await writeOutput("desktop-runtime: verifying scheduled automation run and websocket events");
      await verifyScheduledJobApplyRun(resumeId, fixtureBaseUrl);

      await writeOutput("desktop-runtime: verifying scheduled automation recovery across restart");
      await verifyScheduledRunRecovery(resumeId, fixtureBaseUrl, restartServer);

      await writeOutput(
        `desktop-runtime: verified frontend "${browserResult.pageTitle}" against ${VERIFY_API_BASE}`,
      );
      await writeOutput("desktop-runtime: verification passed");
    },
    () => staticServer.stop(true),
  );
};

const verifyPackagedRuntime = async (
  manifest: DesktopRuntimeManifest,
  verificationFrontendRoot: string,
): Promise<void> => {
  const runtimePaths = await createVerificationRuntimePaths();
  let serverProcess: ReturnType<typeof Bun.spawn> | null = null;
  const fixture = startJobApplyFixtureServer();

  const startServer = async (): Promise<void> => {
    serverProcess = await startPackagedServer(manifest, runtimePaths);
  };

  const restartServer = async (): Promise<void> => {
    if (serverProcess) {
      await stopProcess(serverProcess);
      serverProcess = null;
    }
    await startServer();
  };

  await withCleanup(
    async () => {
      await writeOutput("desktop-runtime: launching packaged server executable");
      await startServer();
      await runPackagedRuntimeChecks(
        manifest,
        verificationFrontendRoot,
        fixture.baseUrl,
        restartServer,
      );
    },
    async () => {
      await fixture.stop();
      if (serverProcess) {
        await stopProcess(serverProcess);
      }
      await rm(runtimePaths.root, { recursive: true, force: true });
      await rm(verificationFrontendRoot, { recursive: true, force: true });
    },
  );
};

const main = async (): Promise<void> => {
  const tauriTarget = parseTargetArg(process.argv.slice(2));
  await writeOutput("desktop-runtime: preparing runtime before verification");
  await runCommand(
    [
      process.execPath,
      "scripts/prepare-desktop-runtime.ts",
      ...(tauriTarget ? ["--target", tauriTarget] : []),
    ],
    REPO_ROOT,
  );

  const manifest = await readManifest();
  await assertManifestContract(manifest, tauriTarget);
  const verificationFrontendRoot = await prepareVerificationFrontendRoot(manifest);
  await verifyPackagedRuntime(manifest, verificationFrontendRoot);
};

await main().then(undefined, async (error: unknown) => {
  const message = toErrorMessage(error, "Unexpected error.");
  await writeError(`desktop-runtime: verification failed: ${message}`);
  process.exit(1);
});

import { readdir } from "node:fs/promises";
import { join } from "node:path";
import { APP_BRAND } from "../packages/shared/src/constants/branding";
import { DEFAULT_I18N_LOCALE_COOKIE_KEY } from "../packages/shared/src/constants/client-config";
import { APP_ROUTES } from "../packages/shared/src/constants/routes";
import {
  DEFAULT_VERIFY_HOST,
  DEFAULT_VERIFY_PORT,
  PREVIEW_LOG_LIMIT,
  PREVIEW_POLL_INTERVAL_MS,
  PREVIEW_READY_TIMEOUT_MS,
  PREVIEW_SEPARATOR_LENGTH,
} from "../packages/shared/src/constants/scripts";
import { APP_LANGUAGE_CODES } from "../packages/shared/src/constants/settings";
import { writeError, writeOutput } from "./utils/cli-output";

const NUM_26 = 26;
const NUM_5 = 5;

type RouteVerificationResult = {
  locale: string;
  route: string;
  status: number;
  heading: string;
  title: string;
};

type RouteVerificationFailure = {
  locale: string;
  route: string;
  status: number;
  reason: string;
};

type PreviewProcess = ReturnType<typeof Bun.spawn>;

const VERIFY_HOST = process.env.VERIFY_HOST || DEFAULT_VERIFY_HOST;
const VERIFY_PORT = process.env.VERIFY_PORT || DEFAULT_VERIFY_PORT;
const DEFAULT_VERIFY_BASE_URL = `http://${VERIFY_HOST}:${VERIFY_PORT}`;
const EXTERNAL_VERIFY_BASE_URL = process.env.VERIFY_BASE_URL?.replace(/\/$/u, "") ?? null;
const VERIFY_BASE_URL = EXTERNAL_VERIFY_BASE_URL ?? DEFAULT_VERIFY_BASE_URL;
const CLIENT_PACKAGE_ROOT = join(process.cwd(), "packages", "client");
const CLIENT_OUTPUT_ROOT = join(CLIENT_PACKAGE_ROOT, ".output");
const CLIENT_BUILD_OUTPUT_PATH = join(CLIENT_PACKAGE_ROOT, ".output", "server", "index.mjs");
const CLIENT_BUILD_CHUNKS_PATH = join(CLIENT_PACKAGE_ROOT, ".output", "server", "chunks");
const htmlHeadingPattern = /<h1\b[^>]*>([\s\S]*?)<\/h1>/iu;
const htmlTitlePattern = /<title\b[^>]*>([\s\S]*?)<\/title>/iu;
const htmlMainPattern = /<main\b[^>]*>/iu;
const htmlTagPattern = /<[^>]+>/gu;
const whitespacePattern = /\s+/gu;
const lineSeparator = "-".repeat(PREVIEW_SEPARATOR_LENGTH);
const expectedBrandToken = APP_BRAND.name.toLowerCase();
const routePaths = Array.from(new Set(Object.values(APP_ROUTES)));

const normalizeText = (value: string): string =>
  value.replace(htmlTagPattern, " ").replace(whitespacePattern, " ").trim();

const createRouteFailure = (
  locale: string,
  route: string,
  status: number,
  reason: string,
): RouteVerificationFailure => ({
  locale,
  route,
  status,
  reason,
});

const pushBoundedLine = (target: string[], value: string): void => {
  const normalized = value.trim();
  if (normalized.length === 0) {
    return;
  }

  target.push(normalized);
  if (target.length > PREVIEW_LOG_LIMIT) {
    target.shift();
  }
};

const readPreviewLogs = async (
  stream: number | ReadableStream<Uint8Array> | undefined,
  target: string[],
): Promise<void> => {
  if (!(stream instanceof ReadableStream)) {
    return;
  }

  const reader = stream.getReader();
  const decoder = new TextDecoder();
  let pending = "";

  const consumeResult = async (): Promise<void> => {
    const readResult = await reader.read();
    if (readResult.done) {
      const trailing = `${pending}${decoder.decode()}`.trim();
      if (trailing.length > 0) {
        pushBoundedLine(target, trailing);
      }
      return;
    }

    if (readResult.value.length > 0) {
      const chunk = `${pending}${decoder.decode(readResult.value, { stream: true })}`;
      const lines = chunk.split(/\r?\n/gu);
      pending = lines.pop() ?? "";
      for (const line of lines) {
        pushBoundedLine(target, line);
      }
    }

    return consumeResult();
  };

  await consumeResult();
};

const pathExists = async (absolutePath: string): Promise<boolean> =>
  readdir(absolutePath).then(
    () => true,
    () => false,
  );

const runCommand = async (command: readonly string[], outputMessage: string): Promise<boolean> => {
  await writeOutput(outputMessage);
  const processHandle = Bun.spawn(command, {
    cwd: process.cwd(),
    stdout: "inherit",
    stderr: "inherit",
  });
  const exitCode = await processHandle.exited;
  return exitCode === 0;
};

const ensureClientBuildExists = async (): Promise<boolean> => {
  const removeOutputSuccess = await runCommand(
    ["rm", "-rf", CLIENT_OUTPUT_ROOT],
    "Resetting client production output before verify:pages.",
  );
  if (!removeOutputSuccess) {
    return false;
  }

  const buildSuccess = await runCommand(
    [process.execPath, "run", "--cwd", "packages/client", "build"],
    "Running `bun run --cwd packages/client build` for verify:pages.",
  );
  if (!buildSuccess) {
    return false;
  }

  const buildFile = Bun.file(CLIENT_BUILD_OUTPUT_PATH);
  const [buildFileExists, chunksPathExists] = await Promise.all([
    buildFile.exists(),
    pathExists(CLIENT_BUILD_CHUNKS_PATH),
  ]);
  return buildFileExists && chunksPathExists;
};

const spawnPreviewProcess = (): PreviewProcess =>
  Bun.spawn(["bun", ".output/server/index.mjs"], {
    cwd: CLIENT_PACKAGE_ROOT,
    stdout: "pipe",
    stderr: "pipe",
    env: {
      ...process.env,
      PORT: DEFAULT_VERIFY_PORT,
      HOST: DEFAULT_VERIFY_HOST,
    },
  });

const pollPreviewReady = async (baseUrl: string, deadline: number): Promise<boolean> => {
  if (Date.now() >= deadline) {
    return false;
  }

  const fetchResult = await Promise.allSettled([
    fetch(baseUrl, { signal: AbortSignal.timeout(PREVIEW_POLL_INTERVAL_MS) }),
  ]);
  const response = fetchResult[0];
  if (response.status === "fulfilled" && response.value.ok) {
    return true;
  }

  await Bun.sleep(PREVIEW_POLL_INTERVAL_MS);
  return pollPreviewReady(baseUrl, deadline);
};

const waitForPreviewReady = async (baseUrl: string): Promise<boolean> => {
  const deadline = Date.now() + PREVIEW_READY_TIMEOUT_MS;
  return pollPreviewReady(baseUrl, deadline);
};

const verifyHtmlContent = (
  locale: string,
  route: string,
  status: number,
  html: string,
): RouteVerificationResult | RouteVerificationFailure => {
  if (route === "/" && !html.toLowerCase().includes(expectedBrandToken)) {
    return createRouteFailure(
      locale,
      route,
      status,
      `Root route did not include expected brand token "${APP_BRAND.name}".`,
    );
  }

  const headingMatch = html.match(htmlHeadingPattern);
  const heading = normalizeText(headingMatch?.[1] ?? "");
  if (heading.length === 0) {
    return createRouteFailure(
      locale,
      route,
      status,
      "No non-empty <h1> heading found in SSR HTML.",
    );
  }

  const titleMatch = html.match(htmlTitlePattern);
  const title = normalizeText(titleMatch?.[1] ?? "");
  if (title.length === 0) {
    return createRouteFailure(locale, route, status, "No non-empty <title> found in SSR HTML.");
  }

  if (!htmlMainPattern.test(html)) {
    return createRouteFailure(locale, route, status, "No <main> landmark found in SSR HTML.");
  }

  return {
    locale,
    route,
    status,
    heading,
    title,
  };
};

const verifyRoute = async (
  locale: string,
  route: string,
): Promise<RouteVerificationResult | RouteVerificationFailure> => {
  const response = await fetch(`${VERIFY_BASE_URL}${route}`, {
    headers: {
      "accept-language": locale,
      cookie: `${DEFAULT_I18N_LOCALE_COOKIE_KEY}=${locale}`,
    },
  });

  if (!response.ok) {
    return createRouteFailure(
      locale,
      route,
      response.status,
      `Expected 2xx status but received ${response.status}.`,
    );
  }

  const html = await response.text();
  return verifyHtmlContent(locale, route, response.status, html);
};

const verifyRoutes = async (): Promise<{
  successes: RouteVerificationResult[];
  failures: RouteVerificationFailure[];
}> => {
  const tasks = APP_LANGUAGE_CODES.flatMap((locale) =>
    routePaths.map((route) => verifyRoute(locale, route)),
  );
  const results = await Promise.all(tasks);
  const successes: RouteVerificationResult[] = [];
  const failures: RouteVerificationFailure[] = [];

  for (const result of results) {
    if ("reason" in result) {
      failures.push(result);
    } else {
      successes.push(result);
    }
  }

  return {
    successes,
    failures,
  };
};

const writeRouteSummary = async (
  successes: RouteVerificationResult[],
  failures: RouteVerificationFailure[],
): Promise<void> => {
  await writeOutput(`Route/content verification against ${VERIFY_BASE_URL}`);
  await writeOutput(lineSeparator);

  const successLines = successes.map(
    (success) =>
      `[ok] ${success.locale.padEnd(NUM_5)} ${success.status} ${success.route.padEnd(NUM_26)} ${success.heading} | ${success.title}`,
  );
  if (successLines.length > 0) {
    await writeOutput(successLines.join("\n"));
  }

  if (failures.length === 0) {
    await writeOutput(lineSeparator);
    await writeOutput(
      `Verified ${successes.length} localized route renders with non-empty page title, heading, and main landmark.`,
    );
    return;
  }

  await writeError(lineSeparator);
  await writeError("Route/content verification failures:");
  await writeError(
    failures
      .map(
        (failure) =>
          `[fail] ${failure.locale.padEnd(NUM_5)} ${failure.status} ${failure.route.padEnd(NUM_26)} ${failure.reason}`,
      )
      .join("\n"),
  );
  process.exit(1);
};

const runWithManagedPreview = async (): Promise<void> => {
  const buildReady = await ensureClientBuildExists();
  if (!buildReady) {
    await writeError("Unable to build the client preview required for verify:pages.");
    process.exit(1);
  }

  const previewProcess = spawnPreviewProcess();
  const stdoutLines: string[] = [];
  const stderrLines: string[] = [];
  const stdoutTask = readPreviewLogs(previewProcess.stdout, stdoutLines);
  const stderrTask = readPreviewLogs(previewProcess.stderr, stderrLines);

  const ready = await waitForPreviewReady(VERIFY_BASE_URL);
  if (!ready) {
    previewProcess.kill();
    await Promise.all([stdoutTask, stderrTask]);
    await writeError("Nuxt preview did not become ready before timeout.");
    const combinedLogs = [...stdoutLines, ...stderrLines];
    if (combinedLogs.length > 0) {
      await writeError(combinedLogs.join("\n"));
    }
    process.exit(1);
  }

  const { successes, failures } = await verifyRoutes();
  previewProcess.kill();
  await Promise.all([stdoutTask, stderrTask]);
  await writeRouteSummary(successes, failures);
};

const main = async (): Promise<void> => {
  if (EXTERNAL_VERIFY_BASE_URL) {
    const { successes, failures } = await verifyRoutes();
    await writeRouteSummary(successes, failures);
    return;
  }

  await runWithManagedPreview();
};

await main();

import { readdir } from "node:fs/promises";
import { join, relative, resolve } from "node:path";
import { writeError, writeOutput } from "./utils/cli-output";

const REPO_ROOT = resolve(import.meta.dir, "..");
const CLIENT_OUTPUT_SERVER = join(REPO_ROOT, "packages", "client", ".output", "server");
const CLIENT_OUTPUT_PUBLIC = join(REPO_ROOT, "packages", "client", ".output", "public");

const pathExists = async (absolutePath: string): Promise<boolean> =>
  readdir(absolutePath).then(
    () => true,
    () => false,
  );

const collectMapFilesRecursive = async (
  directoryPath: string,
  accumulator: string[],
): Promise<void> => {
  const entries = await readdir(directoryPath, { withFileTypes: true });
  await Promise.all(
    entries.map(async (entry) => {
      const entryPath = join(directoryPath, entry.name);
      if (entry.isDirectory()) {
        await collectMapFilesRecursive(entryPath, accumulator);
        return;
      }
      if (entry.isFile() && entry.name.endsWith(".map")) {
        accumulator.push(entryPath);
      }
    }),
  );
};

const verifyNoSourceMapsUnder = async (
  rootLabel: string,
  absoluteRoot: string,
): Promise<readonly string[]> => {
  if (!(await pathExists(absoluteRoot))) {
    await writeOutput(`verify:production-client skip ${rootLabel} (directory missing)`);
    return [] as const;
  }

  const mapPaths: string[] = [];
  await collectMapFilesRecursive(absoluteRoot, mapPaths);
  return mapPaths.map((mapPath) => relative(REPO_ROOT, mapPath));
};

const main = async (): Promise<void> => {
  const [serverMaps, publicMaps] = await Promise.all([
    verifyNoSourceMapsUnder("ssr-output", CLIENT_OUTPUT_SERVER),
    verifyNoSourceMapsUnder("static-public", CLIENT_OUTPUT_PUBLIC),
  ]);
  const unexpectedMaps = [...serverMaps, ...publicMaps].sort((left, right) =>
    left.localeCompare(right),
  );

  if (unexpectedMaps.length > 0) {
    await writeError(
      `verify:production-client failed: unexpected source map files under .output:\n${unexpectedMaps.join("\n")}`,
    );
    process.exit(1);
  }

  await writeOutput(
    "verify:production-client passed (no .map under packages/client/.output/server|public).",
  );
};

await main().then(undefined, async (error: unknown) => {
  await writeError(error instanceof Error ? error.message : String(error));
  process.exit(1);
});
